# llama-server may serve HTTP 200 on CPU when a GPU backend fails to init; classify the log.
# Priority: offload counts, then GPU model buffer lines, then device table (disconfirm only).
_GPU_OFFLOAD_MARKERS = (
    "CUDA",
    "ROCm",
    "ROCM",
    "HIP",
    "Metal",
    "Vulkan",
    "OpenCL",
    "SYCL",
    "MUSA",
    "CANN",
)
_OFFLOADED_LAYERS_RE = re.compile(
    r"offloaded\s+(\d+)\s*/\s*(\d+)\s+layers?\s+to\s+gpu", re.IGNORECASE
)
# llama.cpp #23021 moved libllama INFO (offload counts, device table, buffer sizes) to trace (4).
_LLAMA_TRACE_VERBOSITY = 4
_TRACE_VERBOSITY_HELP_RE = re.compile(r"\b4:\s*trace\b", re.IGNORECASE)
_LOG_VERBOSITY_FLAGS = frozenset(
    {"-lv", "--verbosity", "--log-verbosity", "-v", "--verbose", "--log-verbose", "--log-disable"}
)
# Past this, the active llama-server log keeps only warnings and errors.
_LLAMA_LOG_FULL_BYTES = 64 * 1024 * 1024
# llama.cpp's prefix (stamp optional, colours allowed); a mid-line "x W " is record text.
_ANSI = r"(?:\x1b\[[0-9;]*m)*"
_LOG_LEVEL_TOKEN_RE = re.compile(rf"^{_ANSI}(?:\d+\.\d+\.\d+\.\d+{_ANSI} )?{_ANSI}([A-Z]) ")
# The startup head is never trimmed: its load lines are read for the server's whole life.
_STDOUT_TRIM_AT = 20000
_STDOUT_TAIL_KEEP = 5000
_STDOUT_HEAD_MAX = 5000
# Bind addresses whose listener accepts the health probe's 127.0.0.1 connection.
_LOOPBACK_REACHABLE_BIND_IPS = frozenset(
    {"127.0.0.1", "0.0.0.0", "::", "::ffff:127.0.0.1", "::ffff:0.0.0.0"}
)


def _socket_owner_is_always_named() -> bool:
    """Windows' connection tables carry every socket's owning pid, so an unnamed one there is a
    psutil quirk rather than another user's listener (#15022)."""
    return sys.platform == "win32"


# Left in startup output when the ownership gate refuses, so it is not reported as a bad GGUF.
_PORT_OWNER_REFUSED_MARKER = "llama-server port ownership check refused the listener"


def _llama_line_is_warning_or_error(line: str, line_lower: str) -> bool:
    level = _LOG_LEVEL_TOKEN_RE.match(line)
    if level is not None:
        return level.group(1) in "WE"
    return "error" in line_lower or "fail" in line_lower or "warn" in line_lower


def _trace_verbosity_args(caps: dict, extra_args: Optional[Iterable[str]], environ) -> list[str]:
    """``--verbosity 4`` when the build hides load lines at its default and the user chose none."""
    if not caps.get("supports_trace_verbosity"):
        return []
    if _extra_args_set_any_flag(extra_args, _LOG_VERBOSITY_FLAGS):
        return []
    if "LLAMA_ARG_LOG_VERBOSITY" in environ:
        return []
    return ["--verbosity", str(_LLAMA_TRACE_VERBOSITY)]


_GPU_MODEL_BUFFER_RE = re.compile(
    r"\b(?:CUDA|ROCm|ROCM|HIP|SYCL)(\d+)\s+model buffer size\s*=\s*"
    r"([0-9]+(?:\.[0-9]+)?)\s+MiB\b",
    re.IGNORECASE,
)
_DEVICE_ROW_RE = re.compile(
    # MTL: ggml-metal names its devices MTL0, MTL1 (GGML_METAL_NAME), never "Metal".
    r"-\s*(CUDA|ROCm|ROCM|HIP|Metal|MTL|Vulkan|SYCL|OpenCL|MUSA|CANN|CPU)\w*\s*:",
    re.IGNORECASE,
)
_GPU_DEVICE_PREFIXES = (
    "cuda",
    "rocm",
    "hip",
    "metal",
    "mtl",
    "vulkan",
    "sycl",
    "opencl",
    "musa",
    "cann",
)


# Any backend's "model buffer size" line (CUDA0, CPU_Mapped, RPC0[host:port], ...).
_MODEL_BUFFER_RE = re.compile(
    r"\b([A-Za-z][^\s=]*)\s+model buffer size\s*=\s*([0-9]+(?:\.[0-9]+)?)\s+MiB\b"
)
# --fit's verdict per device, e.g. "- CUDA0 (NVIDIA GeForce RTX 3090): 31 layers ( 8 overflowing), 22815 MiB used".
# An overflowing layer keeps its MoE experts (or part of a layer) out of that device's memory.
_FIT_DEVICE_RE = re.compile(
    r"common_params_fit_impl:\s+-\s+(?P<device>[A-Za-z]+\d+)\s+\(.*?\):\s+(?P<layers>\d+)\s+layers?"
    r"\s*(?:\(\s*(?P<overflow>\d+)\s+overflowing\s*\))?\s*,\s*\d+\s+MiB used"
)
# The MoE-only fill: printed for a model with experts, whose GPU layers then hold only their dense weights.
_FIT_DENSE_ONLY_MARK = "filling dense-only layers back-to-front"
# From here the per-device lines carry an explicit "(N overflowing)" count.
_FIT_FULL_LAYERS_MARK = "converting dense-only layers to full layers"
# One extra partial layer squeezed onto device i; on any device but the last it overflows to the NEXT GPU, not RAM.
_FIT_EXTRA_LAYER_RE = re.compile(
    r"set ngl_per_device\[(?P<index>\d+)\]\.\(n_layer, n_part, overflow_type\)=\(\d+, \d+, (?:UP|GATE|ATTN)\)"
)
# --moe-cache-mib auto: every routed expert stays in host RAM and a cache of the busiest ones goes on the GPU. --fit
# returns before any per-device line on this path.
_FIT_MOE_CACHE_RE = re.compile(
    r"moe cache auto: all routed experts in host RAM, cache (?P<mib>\d+) MiB"
)


def _host_buffer(name: str) -> bool:
    """CPU* buffers, AMX and a GPU backend's pinned host buffer (CUDA_Host) live in system memory."""
    upper = name.upper()
    return "CPU" in upper or upper.endswith("_HOST") or upper == "AMX"


def parse_weight_placement(
    lines: "list[str]", model_bytes: Optional[int] = None
) -> "Optional[dict]":
    """Where llama.cpp put the main model's weights, from its startup log.

    ``gpu_mib`` / ``host_mib`` sum the main model's buffer block, the first allocated one (dry runs log 0.00 MiB).
    "offloaded 31/31" hides an expert spill, so ``overflow_layers`` comes from --fit's final per-device
    lines; the last device's count includes the output layer, which spills nothing (a 3090 gemma-4-26B
    load printing "8 overflowing" holds exactly seven layers' worth in CUDA_Host). None without --fit.
    A ``*_Mapped`` buffer logs its mmap span, first to last host tensor, which covers GPU tensors in
    between when experts spill; ``model_bytes`` (the main GGUF set) caps host at the file minus the GPU side."""
    blocks: list[list] = []
    current: Optional[list] = None
    # A build without GPU offload logs no "offloaded N/M layers" line, only the buffers: each run of them is a block.
    unmarked = False
    moe = False
    full_phase = False
    # device -> (layers, overflow or None for a dense-only line), in the order of the final verdict
    verdict: dict[str, tuple[int, Optional[int]]] = {}
    dense_only_order: list[str] = []
    extra_layer_on: set[int] = set()
    expert_cache_mib: Optional[float] = None
    for line in lines:
        if _FIT_DENSE_ONLY_MARK in line:
            moe = True
            continue
        if _FIT_FULL_LAYERS_MARK in line:
            full_phase = True
            verdict = {}
            continue
        cache = _FIT_MOE_CACHE_RE.search(line)
        if cache is not None:
            expert_cache_mib = float(cache.group("mib"))
            continue
        extra = _FIT_EXTRA_LAYER_RE.search(line)
        if extra is not None and full_phase:
            extra_layer_on.add(int(extra.group("index")))
            continue
        fit = _FIT_DEVICE_RE.search(line)
        if fit is not None:
            device = fit.group("device")
            overflow = fit.group("overflow")
            verdict[device] = (
                int(fit.group("layers")),
                int(overflow) if overflow is not None else None,
            )
            if not full_phase and device not in dense_only_order:
                dense_only_order.append(device)
            continue
        counts = _OFFLOADED_LAYERS_RE.search(line)
        if counts is not None:
            current, unmarked = [int(counts.group(2)), 0.0, 0.0, False], False
            blocks.append(current)
            continue
        buffer = _MODEL_BUFFER_RE.search(line)
        if buffer is None:
            if unmarked:
                current, unmarked = None, False
            continue
        if current is None:
            current, unmarked = [0, 0.0, 0.0, False], True
            blocks.append(current)
        mib = float(buffer.group(2))
        if _host_buffer(buffer.group(1)):
            current[2] += mib
            current[3] = current[3] or (mib > 0 and buffer.group(1).upper().endswith("_MAPPED"))
        else:
            current[1] += mib
    # A no-alloc dry run logs the same block with every buffer at 0.00 MiB.
    loaded = [block for block in blocks if block[1] + block[2] > 0]
    if not loaded:
        return None
    # llama-server loads the main model before any drafter, which can have MORE layers (Gemma 4 E2B: 35 vs 26B A4B: 30).
    main = loaded[0]
    host_mib = main[2]
    if main[3] and main[1] > 0 and model_bytes:
        host_mib = min(host_mib, max(0.0, model_bytes / (1024 * 1024) - main[1]))

    overflow: Optional[int] = None
    if verdict:
        devices = list(verdict)
        overflow = 0
        for index, device in enumerate(devices):
            layers, counted = verdict[device]
            if counted is None:
                # Dense-only fill (filled back to front, so the first device it printed is the last one). A dense
                # model's layers are full. The last device keeps one layer full and its output slot spills nothing.
                if not moe:
                    continue
                last = bool(dense_only_order) and device == dense_only_order[0]
                counted = max(0, layers - 2) if last else layers
            elif index < len(devices) - 1:
                if index in extra_layer_on and counted > 0:
                    counted -= 1
            elif counted > 0:
                counted -= 1
            overflow += counted
    return {
        "gpu_mib": round(main[1], 1),
        "host_mib": round(host_mib, 1),
        "overflow_layers": overflow,
        "all_experts_in_ram": expert_cache_mib is not None,
        "expert_cache_mib": expert_cache_mib,
    }


def _extra_weight_file_bytes(argv, env: Optional[Mapping[str, str]] = None) -> int:
    """GGUF sets of the projector, local drafter and adapters a llama-server launch loads. arg.cpp reads
    the ``LLAMA_ARG_*`` env first and lets argv override it, so ``env`` is the one the child got."""
    tokens = [str(token) for token in argv] if isinstance(argv, (list, tuple)) else []
    env_map = env or {}
    projector: Optional[str] = None
    for index, token in enumerate(tokens):
        if _flag_name(token) not in ("--mmproj", "-mm"):
            continue
        _, eq, value = token.partition("=")
        if eq:
            projector = value
        elif index + 1 < len(tokens):
            projector = tokens[index + 1]
    if projector is None:
        projector = (env_map.get("LLAMA_ARG_MMPROJ") or "").strip() or None
    drafter, remote = _extra_args_mtp_draft_source(tokens, env_map)
    paths = [path for path in (projector, None if remote else drafter) if path]
    paths += _sidecar_adapter_paths(tokens)
    return sum(_gguf_set_bytes(Path(path)) for path in dict.fromkeys(paths))


def parse_gpu_offload_counts(lines: "list[str]") -> "Optional[tuple[int, int]]":
    """``(offloaded, total)`` for the largest-M line, or None; ties keep the first
    line since llama.cpp logs the main model before its drafter."""
    max_total = -1
    offloaded_at_max = 0
    for line in lines:
        match = _OFFLOADED_LAYERS_RE.search(line)
        if not match:
            continue
        offloaded, total = int(match.group(1)), int(match.group(2))
        if total > max_total:
            max_total, offloaded_at_max = total, offloaded
    if max_total <= 0:
        return None
    return offloaded_at_max, max_total


def llama_saw_gpu_device(lines: "list[str]") -> Optional[bool]:
    """Whether llama.cpp's device table (rows after the header) lists a GPU, or None
    with no table. All-CPU means the GPU backend failed to load."""
    after_header = False
    saw_device_row = False
    saw_gpu_device = False
    for line in lines:
        if "device_info:" in line:
            after_header = True
            continue
        if not after_header:
            continue
        match = _DEVICE_ROW_RE.search(line)
        if not match:
            continue
        saw_device_row = True
        if match.group(1).lower().startswith(_GPU_DEVICE_PREFIXES):
            saw_gpu_device = True
    if not saw_device_row:
        return None
    return saw_gpu_device


def classify_gpu_offload_lines(lines: "list[str]") -> Optional[bool]:
    """True if the model landed on a GPU, False if it stayed on CPU despite GPU
    intent, None when the log has no usable signal."""
    # Decide on the largest-M offload line: a drafter on GPU must not mask a CPU main model.
    max_total = -1
    offloaded_at_max = 0
    for line in lines:
        match = _OFFLOADED_LAYERS_RE.search(line)
        if not match:
            continue
        offloaded, total = int(match.group(1)), int(match.group(2))
        if total > max_total or (total == max_total and offloaded > offloaded_at_max):
            max_total, offloaded_at_max = total, offloaded
    if max_total >= 0:
        return offloaded_at_max > 0

    # _Host buffers are CPU-pinned; buffer lines are authoritative over the device table.
    saw_model_buffer = False
    for line in lines:
        if "model buffer size" not in line:
            continue
        saw_model_buffer = True
        if "_Host" not in line and any(m in line for m in _GPU_OFFLOAD_MARKERS):
            return True
    if saw_model_buffer:
        return False

    # device_info lists available devices, not where the model loaded: disconfirm only.
    if llama_saw_gpu_device(lines) is False:
        return False
    return None


def _wsl_system_rocm_lib_dirs() -> "list[str]":
    """Bundled HIP segfaults on WSL /dev/dxg, so system ROCm libs load first. Mirrors install_llama_prebuilt; no-op off a ROCDXG WSL host."""
    try:
        if not os.path.exists("/dev/dxg"):
            return []
        with open("/proc/version", encoding = "utf-8", errors = "replace") as fh:
            if "microsoft" not in fh.read().lower():
                return []
    except (OSError, UnicodeDecodeError):
        return []
    out: "list[str]" = []
    for d in ("/opt/rocm/lib", "/opt/rocm/lib64"):
        if os.path.exists(os.path.join(d, "librocdxg.so")) or os.path.exists(
            os.path.join(d, "librocdxg.so.1")
        ):
            out.append(d)
    return out


def _bundled_hip_present(binary_dir: str) -> bool:
    """True when a prebuilt bundle ships its own HIP backend library."""
    if not binary_dir:
        return False
    try:
        # Glob libggml-hip.so* to match versioned suffixes, the same way the installer's health check does.
        return any(Path(str(binary_dir)).glob("libggml-hip.so*"))
    except OSError:
        return False


def _native_linux_system_rocm_lib_dirs(binary_dir: str = "") -> "list[str]":
    """Prepend whole system ROCm dir: bundled HIP can crash in hsa_init and mixing risks missing symbols. UNSLOTH_LLAMA_NO_SYSTEM_ROCM=1 skips it."""
    if os.environ.get("UNSLOTH_LLAMA_NO_SYSTEM_ROCM") == "1":
        return []
    if sys.platform != "linux" or os.path.exists("/dev/dxg"):
        return []
    if not os.path.exists("/dev/kfd"):
        return []
    if not _bundled_hip_present(binary_dir):
        return []
    # Env ROCm roots first so a stale /opt/rocm does not shadow them.
    candidates = []
    for var in ("HIP_PATH", "HIP_PATH_57", "ROCM_PATH"):
        val = os.environ.get(var)
        if val:
            candidates.append(val)
    candidates.append("/opt/rocm")
    out: "list[str]" = []
    seen: "set[str]" = set()
    for base in candidates:
        for lib_sub in ("lib", "lib64"):
            d = os.path.join(base, lib_sub)
            if d in seen:
                continue
            seen.add(d)
            if os.path.exists(os.path.join(d, "libhsa-runtime64.so")) or os.path.exists(
                os.path.join(d, "libhsa-runtime64.so.1")
            ):
                out.append(d)
                # ROCm keeps LLVM under root/lib/llvm even on lib64 hosts, so probe lib too, ahead of the bundle, else libamd_comgr binds the bundle libLLVM.
                for _sub in (lib_sub, "lib"):
                    llvm_lib = os.path.join(base, _sub, "llvm", "lib")
                    if llvm_lib not in seen and os.path.isdir(llvm_lib):
                        seen.add(llvm_lib)
                        out.append(llvm_lib)
    return out


# Artifact = content no plan has, else a plan with code gets wiped. Numbered lists excluded: they cost errors both ways. Keep runs bounded against backtracking.
_CLOSED_CODE_FENCE = re.compile(
    r"(?<!`)(?P<bf>`{3,})(?!`)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=bf)`*[ \t]*(?:\r?\n|\Z)"
    r"|(?<!~)(?P<tf>~{3,})(?!~)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=tf)~*[ \t]*(?:\r?\n|\Z)",
    re.IGNORECASE,
)
_CLOSED_MARKUP_ARTIFACT = re.compile(
    r"(?:<!doctype\b[\s\S]{0,200}?)?<html\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</html\s*>"
    r"|<svg\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</svg\s*>",
    re.IGNORECASE,
)
_HAS_ANSWER_ARTIFACT = re.compile(
    # Tilde fences too, since models emit tildes when the body holds backticks. CommonMark: 3+ to open, as many to close, on a cleanly ended line.
    r"(?<!`)(?P<bf>`{3,})(?!`)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=bf)`*[ \t]*(?:\r?\n|\Z)"
    r"|(?<!~)(?P<tf>~{3,})(?!~)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=tf)~*[ \t]*(?:\r?\n|\Z)"
    r"|(?:<!doctype\b[\s\S]{0,200}?)?<html\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</html\s*>"
    r"|<svg\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</svg\s*>",
    re.IGNORECASE,
)

_FENCE_RUN_RE = re.compile(r"(?<!`)(?P<backticks>`{3,})(?!`)|(?<!~)(?P<tildes>~{3,})(?!~)")
# One list marker may precede the quote: "- > ```py" is a quote in a list item.
_BLOCKQUOTE_PREFIX = re.compile(r"^[ \t]*(?:[-*+]|\d{1,9}[.)])?[ \t]*(?:>[ \t]?)+")
# Language token that makes an inline run an opener; never ends in a dot so "here." is prose.
_FENCE_INFO_STRING_RE = re.compile(r"[A-Za-z][\w+#-]*(?:\.[\w+#-]+)*")
# A fence on a list-marker line is block level, so the prose rules below do not apply.
_LIST_MARKER_ONLY = re.compile(r"^[ \t]*(?:[-*+]|\d{1,9}[.)])[ \t]+$")
_ONE_QUOTE_MARKER = re.compile(r"[ \t]*>[ \t]?")


def _has_unclosed_code_fence(text: str) -> bool:
    """Column-0 fences always count; inline ones only if they cannot read as prose, since models open fences mid-line. Quote pairing is done here, not in the regex."""
    active_char: Optional[str] = None
    active_len = 0
    active_quote = 0
    active_base = 0
    closed_any = False
    for raw_line in text.splitlines():
        # A quote marker four columns in is indented code, not a container. List markers stay alone: deeper, they may continue a list not visible in one line.
        lead = raw_line[: len(raw_line) - len(raw_line.lstrip(" \t"))]
        quote = _BLOCKQUOTE_PREFIX.match(raw_line)
        indented_quote = quote is not None and len(lead.expandtabs(4)) > 3
        if indented_quote:
            quote = None
        quote_depth = quote.group(0).count(">") if quote else 0
        line = raw_line[quote.end() :] if quote else raw_line
        runs = list(_FENCE_RUN_RE.finditer(line))
        for index, m in enumerate(runs):
            fence = m.group("backticks") or m.group("tildes")
            trailing = line[m.end() :].strip()
            ch = fence[0]
            prefix = line[: m.start()]
            indent = len(prefix.expandtabs(4))
            blank_prefix = not prefix.strip()
            if active_char is not None:
                # A closer is alone on its line, within 3 columns of the container.
                if (
                    blank_prefix
                    and active_base <= indent <= active_base + 3
                    and ch == active_char
                    and len(fence) >= active_len
                    and quote_depth == active_quote
                    and not trailing
                ):
                    active_char, active_len, active_quote, active_base = None, 0, 0, 0
                    closed_any = True
                continue
            # A later backtick run closes an inline span at any column; other delimiters are info-string text, even tildes inside a tilde info string.
            if ch == "`" and any(
                (later.group("backticks") or later.group("tildes"))[0] == ch
                for later in runs[index + 1 :]
            ):
                continue
            if blank_prefix:
                # A fence's baseline is 0 (its own indent); past three columns it is indented code and opens nothing.
                if indent <= 3:
                    active_char, active_len = ch, len(fence)
                    active_quote, active_base = quote_depth, 0
                continue
            # Models open mid-prose fences: a bare info string marks one, and only before any close. A column-0 fence is a real block and is unaffected.
            in_list = _LIST_MARKER_ONLY.match(prefix) is not None
            if not in_list:
                if indented_quote:
                    continue
                if trailing and not _FENCE_INFO_STRING_RE.fullmatch(trailing):
                    continue
                if closed_any:
                    continue
            active_char, active_len, active_quote = ch, len(fence), quote_depth
            # A list marker is the container, so its width is the baseline; mid-sentence the baseline is 0.
            active_base = indent if in_list else 0
    return active_char is not None


def _has_unclosed_markup_block(text: str) -> bool:
    """Counted rather than matched, so a closed block followed by an open one still counts as unclosed."""
    opens_html = len(re.findall(r"<html\b", text, re.IGNORECASE))
    closes_html = len(re.findall(r"</html\s*>", text, re.IGNORECASE))
    if opens_html > closes_html:
        return True
    opens_svg = len(re.findall(r"<svg\b", text, re.IGNORECASE))
    closes_svg = len(re.findall(r"</svg\s*>", text, re.IGNORECASE))
    return opens_svg > closes_svg


# "First, I'll create an <html></html> skeleton" is a plan, not a page.
_EMPTY_MARKUP_SKELETON = re.compile(
    r"<(html|svg)\b[^>]*>\s*</\1\s*>",
    re.IGNORECASE,
)
_DOCTYPE_PREFIX = re.compile(
    r"^<!doctype\b[\s\S]{0,200}?>",
    re.IGNORECASE,
)


def _is_empty_markup_skeleton(matched: str) -> bool:
    """True if ``matched`` is an empty <html></html> / <svg></svg>, doctype
    prefix and surrounding whitespace allowed."""
    candidate = _DOCTYPE_PREFIX.sub("", matched.strip(), count = 1).strip()
    return _EMPTY_MARKUP_SKELETON.fullmatch(candidate) is not None


def _is_blank_fence(matched: str, depth: int = 0) -> bool:
    """Only whitespace between the delimiter lines counts as blank, so a lone space is not an answer."""
    if matched[:1] not in ("`", "~"):
        return False
    lines = matched.splitlines()
    # Depth is the quote depth of the opener, read from the match start line. A deeper last line is a nested delimiter in the body, so it is content, not blank.
    closing = _BLOCKQUOTE_PREFIX.match(lines[-1]) if lines else None
    if (closing.group(0).count(">") if closing else 0) != depth:
        return False
    for line in lines[1:-1]:
        for _ in range(depth):
            marker = _ONE_QUOTE_MARKER.match(line)
            if marker is None:
                break
            line = line[marker.end() :]
        if line.strip():
            return False
    return True


def _first_real_artifact(text: str):
    """First _HAS_ANSWER_ARTIFACT match with something in it.

    Every match is inspected, so a skeleton followed by a real page counts."""
    for m in _HAS_ANSWER_ARTIFACT.finditer(text):
        if _is_empty_markup_skeleton(m.group(0)):
            continue
        # The container the fence sits in is whatever quotes the line it opens on.
        line_start = text.rfind("\n", 0, m.start()) + 1
        quote = _BLOCKQUOTE_PREFIX.match(text[line_start : m.start()])
        depth = quote.group(0).count(">") if quote else 0
        if _is_blank_fence(m.group(0), depth):
            continue
        return m
    return None


def _strip_markup_outside_fences(text: str) -> str:
    """Blocks that begin inside a code fence are kept, so an example's <html> cannot pair with prose."""
    fences = [m.span() for m in _CLOSED_CODE_FENCE.finditer(text)]

    def _keep_examples(m):
        # Either endpoint inside a fence makes the match that example's content.
        return m.group(0) if any(s <= m.start() < e or s < m.end() <= e for s, e in fences) else ""

    return _CLOSED_MARKUP_ARTIFACT.sub(_keep_examples, text)


# A reasoning opener ends at a tag boundary: "<think-card>" is an element of the
# answer, not a thought.
_THINK_OPEN_RE = re.compile(r"<think[\s>]")
_THINKING_OPEN_RE = re.compile(r"<thinking[\s>]")
_BRACKET_THINK_OPEN_RE = re.compile(r"\[THINK\]")


def _artifact_spans(text: str) -> "list[tuple[int, int]]":
    """Spans of the complete fences and complete markup in ``text``."""
    return [m.span() for m in _CLOSED_CODE_FENCE.finditer(text)] + [
        m.span() for m in _CLOSED_MARKUP_ARTIFACT.finditer(text)
    ]


def _find_outside_artifacts(
    text: str,
    needle: str,
    spans = None,
) -> int:
    """Ignores needle matches inside complete code fences or markup, since an example is not reasoning."""
    at = text.find(needle)
    if at < 0:
        return -1
    if spans is None:
        spans = _artifact_spans(text)
    while at >= 0:
        if not any(start <= at < end for start, end in spans):
            return at
        at = text.find(needle, at + 1)
    return -1


def _text_outside_think(text: str) -> str:
    """Drops only a leading reasoning block; a later think tag is quoted, not reasoning. A prefilled template may send only the closer."""
    stripped = text.lstrip()
    pairs = (
        (_THINKING_OPEN_RE, "<thinking", "</thinking>"),
        (_THINK_OPEN_RE, "<think", "</think>"),
        (_BRACKET_THINK_OPEN_RE, "[THINK]", "[/THINK]"),
    )
    # Settle the leading opener first: its block may name another marker.
    for lead, _opener, closer in pairs:
        if lead.match(stripped):
            # First closer, plainly: guessing which quoted closer is an example let spans swallow the real boundary. Matches _split_think_segments in routes/inference.py.
            close = text.find(closer)
            # With no closer, a thought cut off by the window runs to the end, and none of it was shown.
            return text[close + len(closer) :] if close >= 0 else ""
    # No leading opener: a bare closer comes from a template that prefilled the opener.
    spans = None
    for lead, _opener, closer in pairs:
        if closer in text and spans is None:
            spans = _artifact_spans(text)
        close = _find_outside_artifacts(text, closer, spans)
        # Boundary-aware so <think-card> in the trace is not an opener, which leaves the prefill unstripped.
        if close >= 0 and not lead.search(text[:close]):
            return text[close + len(closer) :]
    return text


def _has_answer_artifact(text: str) -> bool:
    """A closed fence or complete page counts; unfinished fences and empty skeletons do not."""
    # Strip closed artifacts first: tags or backticks inside finished code are content.
    if _has_unclosed_code_fence(_strip_markup_outside_fences(text)):
        return False
    # Nested pages are deliberately not inspected; that needs an HTML parser.
    return _first_real_artifact(text) is not None


# High floor for reasoning-heavy GGUFs and clients that omit max_tokens.
_DEFAULT_MAX_TOKENS_FLOOR = 32768
_DEFAULT_FIRST_TOKEN_TIMEOUT_S = 1200.0  # 20 min


def _conversation_recall_reserve(thread_id: Optional[str]) -> int:
    """Room to hold back during a fit for the turns recalled straight after it."""
    if not thread_id:
        return 0
    try:
        from core.rag import config as rag_config
        from core.rag import conversation_archive

        # Temporary chats are never archived, so do not reserve room for recall.
        if not conversation_archive.can_archive(thread_id):
            return 0
        # sqlite-vec may exist while the embedder fails; reserving then only loses history.
        if conversation_archive.degraded():
            return 0
        return max(0, int(rag_config.CONVERSATION_RECALL_RESERVE_TOKENS))
    except Exception:
        return 0


def _keeps_compaction_boundary(thread_id: Optional[str]) -> bool:
    """Only a persisting thread can restore a boundary: it rides on saved assistant metadata."""
    if not thread_id:
        return False
    try:
        from storage import studio_db
        return bool(studio_db.chat_thread_has_messages(str(thread_id)))
    except Exception:
        return False


def _archive_branch_transcript(
    branch_messages: Optional[list[dict]], roles: Optional[tuple[str, ...]] = None
) -> Optional[list[str]]:
    """The active branch, one normalised string per message, or None if there is nothing."""
    if not branch_messages:
        return None
    try:
        from core.rag import conversation_archive
        return conversation_archive.branch_message_texts(branch_messages, roles)
    except Exception:
        return None


def _branch_boundary(conversation: list[dict], branch: Optional[list[dict]]) -> int:
    """Count every evicted message by identity, not dropped_messages (tool refits inflate it); stopping at the first survivor un-compacts the epoch."""
    messages = list(branch or ())
    cutoff = max(
        (index for index, message in enumerate(messages) if message.get("role") == "user"),
        default = max(0, len(messages) - 1),
    )
    messages = messages[:cutoff]
    live = {id(message) for message in conversation}
    count = 0
    for message in messages:
        if message.get("role") in ("system", "developer"):
            continue
        if id(message) not in live:
            count += 1
    return count


def _records_boundary(truncation: dict) -> bool:
    """Not the fits flag: a rescued fit still evicts, and skipping the save compacts silently. Saving is not replaying: sticky logic declines fits-false records."""
    return bool(truncation.get("fits")) or bool(truncation.get("dropped_messages"))


def _effective_headroom_ratio(compaction_headroom_ratio: Optional[float] = None) -> float:
    """The extra-trim share this request's rolling fit actually used."""
    ratio = clamp_compaction_headroom_ratio(compaction_headroom_ratio)
    return _COMPACTION_HEADROOM_RATIO if ratio is None else ratio


def _boundary_metadata(
    fitted: list[dict],
    before: Optional[list[dict]],
    compaction_headroom_ratio: Optional[float] = None,
) -> dict:
    """Saved with the depth: a replayed depth is wrong if the headroom setting has since moved."""
    return {
        "boundary_messages": _branch_boundary(fitted, before),
        "boundary_anchor": _branch_boundary_anchor(fitted, before),
        "boundary_headroom_ratio": _effective_headroom_ratio(compaction_headroom_ratio),
    }


def _branch_non_system(branch: Optional[list[dict]]) -> list[dict]:
    """The branch as ``_branch_boundary`` counts it: system and developer turns removed."""
    return [
        message for message in (branch or ()) if message.get("role") not in ("system", "developer")
    ]


def _branch_boundary_anchor(conversation: list[dict], branch: Optional[list[dict]]) -> str:
    """Text, not id or index, taken after the last eviction (first survivor may be a pin). Only moves the boundary shallower; a stale anchor never evicts live turns."""
    messages = _branch_non_system(branch)
    live = {id(message) for message in conversation}
    last_dropped = max(
        (index for index, message in enumerate(messages) if id(message) not in live),
        default = -1,
    )
    for message in messages[last_dropped + 1 :]:
        if id(message) in live:
            return _anchor_text(message)
    return ""


# Bounded so a long tool argument cannot bloat per-turn UI metadata; the name and args head suffice.
_ANCHOR_ARGS_CHARS = 200
# Anchor rides in every event and persisted turn, so keep only a head; sharing a head costs an extra compaction, never a live turn.
_ANCHOR_TEXT_CHARS = 200


def _anchor_text(message: dict) -> str:
    """Tool-call messages have empty content, so fall back to tool_calls; otherwise the rebase silently fails and evicts a live message per deleted one."""
    text = _archive_message_text(message.get("content"))
    if text:
        return text[:_ANCHOR_TEXT_CHARS]
    parts = []
    for call in message.get("tool_calls") or ():
        function = (call or {}).get("function") or {}
        name = str(function.get("name") or "tool")
        arguments = str(function.get("arguments") or "").strip()[:_ANCHOR_ARGS_CHARS]
        parts.append(f"{name}: {arguments}" if arguments else name)
    return "\n".join(parts)[:_ANCHOR_TEXT_CHARS]


def _archive_message_text(content) -> str:
    """One stored message flattened the way the branch check flattens it, or ""."""
    try:
        from core.rag import conversation_archive
        return conversation_archive.message_text(content)
    except Exception:
        return ""


def _archive_content_on_branch(content, transcript: Optional[list[str]]) -> bool:
    if transcript is None:
        return True
    try:
        from core.rag import conversation_archive
        return conversation_archive.content_on_branch(content, transcript)
    except Exception:
        return True


def _row_replayed(message: dict) -> bool:
    """Status is not the test: a stopped reply with text, or reasoning alone, is kept."""
    if message.get("role") != "assistant":
        return True
    content = message.get("content")
    if isinstance(content, str):
        return bool(content.strip())
    reasoning = False
    for part in content or ():
        if not isinstance(part, dict):
            continue
        if part.get("type") == "text" and str(part.get("text") or "").strip():
            return True
        if part.get("type") in ("image", "image-url", "file"):
            return True
        reasoning = reasoning or part.get("type") == "reasoning"
    if reasoning and not _row_ended_early(message):
        return True
    return bool(message.get("attachments"))


def _row_ended_early(message: dict) -> bool:
    """`assistantTurnEndedEarly`: the persisted marker, since status is session state."""
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    return bool(metadata.get("incomplete") or custom.get("incomplete"))


def _archive_branch_chain(
    messages: list[dict], branch_messages: Optional[list[dict]]
) -> Optional[list[dict]]:
    """The stored parent chain selected by this wire branch, when ancestry can prove one."""
    if not branch_messages:
        return None
    try:
        from core.rag import conversation_archive

        def _chain(probe):
            return conversation_archive._active_chain(
                messages,
                probe,
                fallback = False,
                require_unique = True,
            )

        chain = _chain(branch_messages)
        if not chain:
            return None
        # The unstored newest turn only matches on a SIBLING, so settled turns pick the branch.
        settled = list(branch_messages)
        while settled and settled[-1].get("role") == "user":
            settled.pop()
        if settled:
            proof = _chain(settled)
            if not proof:
                return None
            tip = proof[-1].get("id")
            if not any(row.get("id") == tip for row in chain):
                return None

            # Rows past the tip match only the text of unstored turns, keyed by role; matching the whole request let an abandoned row in on repeated text.
            def _keys(rows):
                return [
                    (wire.get("role"), _archive_message_text(wire.get("content")))
                    for wire in conversation_archive._as_wire(list(rows))
                ]

            carried = set(_keys(branch_messages[len(settled) :]))
            past_tip = False
            for row in chain:
                if past_tip:
                    checked = False
                    for key in _keys([row]):
                        if not key[1]:
                            continue
                        if key not in carried:
                            return None
                        checked = True
                    # Only a reply the client drops whole may ride unchecked; refuse re-sent ones.
                    if not checked and _row_replayed(row):
                        return None
                past_tip = past_tip or row.get("id") == tip
        return chain
    except Exception:
        return None


def _archive_as_wire(messages: Optional[list[dict]]) -> list[dict]:
    """Not sanitised: the boundary anchor is written from the raw request, so lookups must match it."""
    try:
        from core.rag import conversation_archive
        return conversation_archive._as_wire(list(messages or ()), sanitise_assistant = False)
    except Exception:
        return list(messages or ())


class _CompactionBranchState(NamedTuple):
    message: dict
    truncation: Optional[dict]
    recorded: int


def _reply_text(content) -> str:
    """A stored reply's visible text, which a Max Tokens continuation re-sends verbatim."""
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    return "".join(
        str(part.get("text") or "")
        for part in content
        if isinstance(part, dict) and part.get("type") == "text"
    )


def _row_truncation(message: dict) -> Optional[dict]:
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    truncation = metadata.get("contextTruncation") or custom.get("contextTruncation")
    return truncation if isinstance(truncation, dict) else None


# The auto-continue limit is 3 rounds; a manual Continue chain longer than this keeps its refusal.
_RESUME_HOPS = 8
_RESUME_SIBLINGS = 16


def _max_tokens_cut(message: dict) -> bool:
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    incomplete = metadata.get("incomplete") or custom.get("incomplete")
    reason = incomplete.get("reason") if isinstance(incomplete, dict) else incomplete
    return reason == "length"


def _row_key(row: dict):
    return row.get("id") or id(row)


def _resumable_cuts(stored: list[dict]) -> dict:
    """Max Tokens cuts per parent: ([positions], [rows]) in creation order."""
    cuts: dict = {}
    for position, row in enumerate(stored):
        if row.get("role") == "assistant" and _max_tokens_cut(row):
            at, rows = cuts.setdefault(row.get("parentId", row.get("parent_id")), ([], []))
            at.append(position)
            rows.append(row)
    return cuts


def _resumed_reply(message: dict, cuts: dict, positions: dict) -> dict:
    """The reply an unfitted Max Tokens continuation resumed: its refusal records no epoch,
    but the epoch in force is still the resumed reply's."""
    for _ in range(_RESUME_HOPS):
        truncation = _row_truncation(message)
        if (
            truncation is None
            or truncation.get("fits")
            or truncation.get("latest_turn_role") != "assistant"
        ):
            return message
        position = positions.get(_row_key(message))
        if position is None:
            return message
        text = _reply_text(message.get("content"))
        at, rows = cuts.get(message.get("parentId", message.get("parent_id")), ((), ()))
        end = bisect.bisect_left(at, position)
        earlier = rows[max(0, end - _RESUME_SIBLINGS) : end]
        # Newest earlier cut wins; equal text counts, since a refusal adds nothing.
        source = next(
            (
                row
                for row in reversed(earlier)
                if (resumed := _reply_text(row.get("content")).rstrip())
                and text.startswith(resumed)
            ),
            None,
        )
        if source is None:
            return message
        message = source
    return message


def _compaction_branch_states(
    stored: list[dict], branch_messages: Optional[list[dict]] = None
) -> list[_CompactionBranchState]:
    """Several rows only for textually identical Retry siblings; consumers take the conservative one."""
    # Assistant rows only: an abandoned "Done" rides in on a live "not done yet".
    branch = _archive_branch_transcript(branch_messages, ("assistant",))
    if branch_messages and not branch:
        return []

    chain = _archive_branch_chain(stored, branch_messages)
    candidates = [
        message
        for message in reversed(chain if chain is not None else stored)
        if message.get("role") == "assistant"
        and (chain is not None or _archive_content_on_branch(message.get("content"), branch))
    ]
    if not candidates:
        return []

    # Exact first: the branch check is a substring test, so "Done" matches "Not done yet".
    if chain is None:
        live = set(branch or ())
        exact = [
            message
            for message in candidates
            if _archive_message_text(message.get("content")) in live
        ]
        if exact:
            candidates = exact

    # A COMPLETED row with no truncation ends the epoch; only active/aborted are placeholders.
    cuts = _resumable_cuts(stored)
    positions = {_row_key(row): position for position, row in enumerate(stored)}
    states = []
    for message in candidates:
        metadata = _resumed_reply(message, cuts, positions).get("metadata")
        metadata = metadata if isinstance(metadata, dict) else {}
        custom = metadata.get("custom")
        custom = custom if isinstance(custom, dict) else {}
        truncation = metadata.get("contextTruncation") or custom.get("contextTruncation")

        recorded = None
        if isinstance(truncation, dict):
            raw_recorded = truncation.get("boundary_messages")
            if raw_recorded is None:
                raw_recorded = truncation.get("dropped_messages")
            if raw_recorded is not None:
                try:
                    recorded = max(0, int(raw_recorded or 0))
                except (TypeError, ValueError):
                    pass
        if recorded is None and chain is not None:
            # Skipping defers to the previous epoch, so it needs a proved branch; on the text path the rows are twins. A research row reports its run, not whether this fit.
            research_row = (
                (metadata.get("serverManaged") or custom.get("serverManaged"))
                and (metadata.get("researchRunId") or custom.get("researchRunId"))
                and (metadata.get("researchStatus") or custom.get("researchStatus"))
            )
            if research_row:
                continue
            status = metadata.get("generationStatus") or custom.get("generationStatus")
            incomplete = metadata.get("incomplete") or custom.get("incomplete")
            reason = incomplete.get("reason") if isinstance(incomplete, dict) else incomplete
            active = status in {"queued", "running", "cancelling"}
            aborted = status in {"cancelled", "failed"} or reason in {"cancelled", "interrupted"}
            if active or (status != "completed" and aborted):
                continue
        if recorded is None:
            states.append(_CompactionBranchState(message, None, 0))
            continue
        states.append(_CompactionBranchState(message, truncation, recorded))

    if not states:
        return []
    if chain is not None:
        # Parent ancestry orders repeated text on one linear history unambiguously.
        return states[:1]
    newest = _archive_message_text(states[0].message.get("content"))
    return [
        state for state in states if _archive_message_text(state.message.get("content")) == newest
    ]


def _sticky_compaction_state(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> tuple[int, bool]:
    """`_sticky_compaction_details` without the manual flag."""
    return _sticky_compaction_details(
        thread_id,
        branch_messages,
        context_policy = context_policy,
        can_reset = can_reset,
        compaction_headroom_ratio = compaction_headroom_ratio,
    )[:2]


def _sticky_compaction_details(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> tuple[int, bool, bool]:
    """How many leading messages this thread last compacted away, who compacted them, and
    whether the user asked for it (/compact), which replays even while the prompt fits.

    The provenance decides which fitter may consume the count. A rolling boundary handed
    to `fit_checkpoint_context` reads as an epoch already in force, so the fit returns
    `checkpoint_started` false and `_archive_and_recall` skips the recall the rolling
    fallback would have run. Mixed provenance across surviving rows counts as rolling:
    `min(boundaries)` below may pick either row, so the safe reading is the one that still
    recalls.

    The fit is otherwise stateless: the client re-sends the whole transcript each request,
    so "keep the newest N tokens" slides forward every turn, which tells the user nothing
    useful and throws away llama-server's prefix cache each time the head moves. Reading
    the boundary back makes compaction an occasional event.

    Read from the thread's newest assistant turn, which already persists this number for
    the UI, so nothing new is stored and it survives a restart. Never raises: no history,
    a non-persisting API client, or a storage error all mean "no boundary".
    """
    if not thread_id:
        return 0, False, False
    requested_ratio = _effective_headroom_ratio(compaction_headroom_ratio)
    try:
        from storage import studio_db

        stored = list(studio_db.list_chat_messages(thread_id) or [])
        states = _compaction_branch_states(stored, branch_messages)
        if not states:
            return 0, False, False

        boundaries = []
        origins = []
        manual = []
        branch_wire = _archive_as_wire(branch_messages)
        for state in states:
            truncation = state.truncation
            recorded = state.recorded
            if truncation is None:
                return 0, False, False
            # Only a SUCCEEDED fit describes a boundary, but an explicit failure still rules.
            if not truncation.get("fits"):
                return 0, False, False
            # A provider-generated summary boundary is display metadata, not a local-fit epoch. On a provider/model
            # switch the opaque summary is deliberately withheld, so replaying its boundary here would discard the
            # original turns without retaining their summary.
            if truncation.get("summarized") is True:
                return 0, False, False
            # A boundary is valid only under the fit that will consume it, and the two
            # directions fail differently.
            #
            # A checkpoint boundary is the depth of a RESET, affordable only because the
            # block is rebuilt on every replay. Under rolling nothing rebuilds it, so the
            # depth replays with nothing handed back (18 evicted where rolling picks 6).
            # Refused HERE, not at the fit: `boundary_messages` is re-recorded every turn,
            # so a rolling turn that inherited 18 would persist it with no `checkpoint` key
            # and make the reset-sized window permanent.
            #
            # The other way, a rolling boundary reaching `fit_checkpoint_context` reads as
            # an epoch already in force, so the reset returns `checkpoint_started` false
            # and the automatic recall never runs. That only happens where the request may
            # actually reset; `_can_reset_epoch` false means the fit stays rolling whatever
            # the process policy says, and there the rolling boundary is the right one to
            # replay. Rejecting it there instead let the boundary slide every turn for any
            # model whose template cannot render tools.
            recorded_checkpoint = bool(truncation.get("checkpoint"))
            effective_checkpoint = _request_uses_checkpoint(context_policy)
            if recorded_checkpoint and not effective_checkpoint:
                return 0, False, False
            if not recorded_checkpoint and effective_checkpoint and can_reset:
                return 0, False, False
            # Changing the extra trim has to change something. Phase one of
            # `fit_rolling_context` re-applies this count before anything else and stops
            # once the result fits, so a boundary cut under a DIFFERENT ratio never reaches
            # the phase that reads the new one, in either direction: measured on a
            # 121-message transcript at context_length 1600, a stored boundary of 86 gave
            # `dropped 86` whether the request asked for 0.05 or 0.25. Refusing it makes
            # the fit recompute, which is the only place the new ratio is read. Absent on
            # rows saved before the ratio was recorded, which keep replaying as they did.
            if not recorded_checkpoint:
                recorded_ratio = truncation.get("boundary_headroom_ratio")
                try:
                    if (
                        recorded_ratio is not None
                        and abs(float(recorded_ratio) - requested_ratio) > 1e-9
                    ):
                        return 0, False, False
                except (TypeError, ValueError):
                    return 0, False, False
            # A count is only valid against the transcript it was counted on. Deleting an
            # already-evicted turn shortens the front, and replaying the count then evicts
            # that many LIVE messages instead. Re-derive it from the anchor's position on
            # this request's own branch. Only ever downward: an anchor that has moved back
            # (a repeated text, an edited turn) must not deepen the cut.
            anchor = truncation.get("boundary_anchor")
            if isinstance(anchor, str) and anchor:
                for index, branch_message in enumerate(_branch_non_system(branch_wire)):
                    if _anchor_text(branch_message) == anchor[:_ANCHOR_TEXT_CHARS]:
                        recorded = min(recorded, index)
                        break
            boundaries.append(recorded)
            origins.append(recorded_checkpoint)
            manual.append(recorded_checkpoint and truncation.get("manual") is True)
        if not boundaries:
            return 0, False, False
        return min(boundaries), all(origins), all(manual)
    except Exception:
        return 0, False, False


def _sticky_compaction_manual(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> bool:
    """Whether the epoch `_sticky_compaction_state` replays was started by /compact."""
    return _sticky_compaction_details(
        thread_id,
        branch_messages,
        context_policy = context_policy,
        can_reset = can_reset,
        compaction_headroom_ratio = compaction_headroom_ratio,
    )[2]


def _sticky_compaction_boundary(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> int:
    """`_sticky_compaction_state` without the provenance, for callers that only fit."""
    return _sticky_compaction_state(
        thread_id,
        branch_messages,
        context_policy = context_policy,
        can_reset = can_reset,
        compaction_headroom_ratio = compaction_headroom_ratio,
    )[0]


def _prefix_user_text(message: dict, prefix: str) -> dict:
    """Copy of ``message`` with ``prefix`` in front of its text. Never mutates."""
    content = message.get("content")
    if isinstance(content, str) or content is None:
        return {**message, "content": prefix + (content or "")}
    if isinstance(content, list):
        parts = list(content)
        for index, part in enumerate(parts):
            if isinstance(part, dict) and part.get("type") in ("text", "input_text"):
                parts[index] = {**part, "text": prefix + str(part.get("text") or "")}
                return {**message, "content": parts}
        return {**message, "content": [{"type": "text", "text": prefix}] + parts}
    return message


# A readable local name for the shared `context_window` policy, not a second implementation.
_retrieval_budget = retrieval_budget


def _recall_top_k(budget_tokens: int) -> int:
    """Sizes the recall from the room actually left, not the reserve, which a fit may not reach."""
    try:
        from core.rag import config as rag_config
        chunk = max(1, int(rag_config.CHUNK_TOKENS))
        cap = max(0, int(rag_config.CONVERSATION_ARCHIVE_TOP_K))
    except Exception:
        return 0
    fits = int(budget_tokens) // chunk
    if fits <= 0 and int(budget_tokens) > 0:
        # CHUNK_TOKENS is a ceiling; the exact recount below decides.
        fits = 1
    return max(0, min(cap, fits))


def _archive_and_recall(
    conversation: list[dict],
    before: list[dict],
    *,
    thread_id: Optional[str],
    style: str,
    recall_done: bool,
    force_recall: bool = True,
    recall_budget_tokens: int = 0,
    count_tokens: Optional[Callable[[list[dict]], int]] = None,
    branch_messages: Optional[list[dict]] = None,
    cancel_check: Optional[Callable[[], bool]] = None,
    background: bool = False,
) -> dict:
    """Never raises: any failure falls back to the plain fitted messages. Recall runs at most once per request or refits stack recall blocks."""
    result = {
        "conversation": conversation,
        "events": [],
        "counts": {},
        "recalled": False,
        "anchored": [],
    }
    if not thread_id:
        return result
    try:
        from core.inference.tools import build_conversation_recall
        from core.rag import conversation_archive

        if not conversation_archive.enabled():
            return result

        gone = evicted_messages(before, conversation)
        if background:
            # llama.cpp only: its streams gate the idle-gap worker (`inference_running`).
            conversation_archive.note_branch(thread_id, before, cancel_check)
        # `conversation` is the fitted prompt, so it says which repeats of a turn the model
        # can still read. Without it a twice-said turn is archived twice and spends two
        # recall slots on text already in the prompt.
        archived = (
            conversation_archive.archive_turns(
                thread_id,
                gone,
                live = conversation,
                branch = branch_messages or conversation,
                cancel_check = cancel_check,
            )
            if gone
            else 0
        )
        counts = {"archived_messages": archived}

        if recall_done or (cancel_check is not None and cancel_check()):
            result["counts"] = counts
            return result
        if not force_recall:
            # Checkpoint mode past the first turn: archiving still runs (the epoch stops being searchable otherwise); auto lookup only on the reset turn.
            result["counts"] = counts
            return result

        top_k = _recall_top_k(recall_budget_tokens)
        if top_k <= 0:
            # No room, but archiving still runs so turns stay searchable and the next fit can recall them.
            result["counts"] = counts
            return result

        # Exact recount decides; on overflow halve the turn count (4 -> 2 -> 1) instead of giving up.
        attempts = []
        attempt_k = top_k
        while True:
            attempts.append(attempt_k)
            if attempt_k <= 1:
                break
            attempt_k = max(1, attempt_k // 2)

        for index, k in enumerate(attempts):
            recall = build_conversation_recall(
                conversation,
                thread_id,
                style = style,
                top_k = k,
                branch_messages = branch_messages,
            )
            if not recall:
                result["counts"] = counts
                return result

            candidate = _inject_recall(conversation, recall, style)
            if candidate is None:
                result["counts"] = counts
                return result

            grew = None
            if count_tokens is not None and recall_budget_tokens > 0:
                try:
                    grew = count_tokens(candidate["conversation"]) - count_tokens(conversation)
                except Exception:
                    grew = None
            if grew is not None and grew > recall_budget_tokens:
                logger.info(
                    "conversation_recall.over_budget grew=%s budget=%s top_k=%s",
                    grew,
                    recall_budget_tokens,
                    k,
                )
                if index + 1 < len(attempts):
                    continue
                logger.info(
                    "conversation_recall.dropped_over_budget budget=%s", recall_budget_tokens
                )
                result["counts"] = counts
                return result

            result["conversation"] = candidate["conversation"]
            result["events"] = candidate["events"]
            result["anchored"] = candidate["anchored"]
            break

        counts["recalled_chunks"] = int(recall.get("sources") or 0)
        result["counts"] = counts
        result["recalled"] = True
    except Exception as exc:
        logger.warning("Could not archive or recall compacted turns: %s", exc)
    return result


def _inject_recall(conversation: list[dict], recall: dict, style: str) -> Optional[dict]:
    """Only the injected messages are anchored; anything else would pin a real turn the fit may evict."""
    if style == "inline":
        prefix = recall.get("prefix") or ""
        updated = list(conversation)
        for index in range(len(updated) - 1, -1, -1):
            if updated[index].get("role") == "user":
                updated[index] = _prefix_user_text(updated[index], prefix)
                break
        else:
            return None
        return {"conversation": updated, "events": [], "anchored": [updated[index]]}
    added = list(recall["messages"])
    return {
        "conversation": list(conversation) + added,
        "events": list(recall["events"]),
        "anchored": added,
    }


# Transport errors can beat the child to reapable; a request cannot wait the 5s MTP reload spends.
_RESPAWN_REAP_GRACE_S = 1.0


def _finalize_reasoning_only_cumulative(
    cumulative: str,
    reasoning_text: str,
    finish_reason: Optional[str],
    promote_reasoning_only: bool,
    resumed_reasoning: str = "",
) -> str:
    """Snapshot must stay append-only or suffix consumers drop the fallback. Promote only on clean stop, never on length; include resumed_reasoning."""
    visible_fallback = (
        resumed_reasoning + reasoning_text
        if promote_reasoning_only and finish_reason != "length"
        else ""
    )
    return cumulative + "</think>" + visible_fallback


def _ends_inside_quote(text: str) -> bool:
    """Heuristic: text ends on a quote opener left unmatched on its line, or a lone quote."""
    stripped = (text or "").rstrip()
    if not stripped or stripped[-1] not in "`\"'":
        return False
    if len(stripped) > 1 and not (stripped[-2].isspace() or stripped[-2] in "*_([{"):
        return False
    last = stripped[-1]
    line = stripped.rsplit("\n", 1)[-1]
    # An apostrophe between letters (Qwen2's, don't) is not a quote mark.
    marks = sum(
        1
        for i, ch in enumerate(line)
        if ch == last
        and not (
            ch == "'" and 0 < i < len(line) - 1 and line[i - 1].isalnum() and line[i + 1].isalnum()
        )
    )
    return marks % 2 == 1


def _quote_cut_event(
    reasoning_text: str,
    answer_text: str,
    finish_reason: Optional[str],
    promote_reasoning_only: bool,
) -> Optional[dict]:
    """Flag a mid-quote `stop` in the shown answer; off for Anthropic, which cannot relay it."""
    if not promote_reasoning_only or finish_reason != "stop":
        return None
    shown = answer_text if answer_text.strip() else reasoning_text
    return {"type": "quote_cut"} if _ends_inside_quote(shown) else None


# Only large streamed tool args get an early provisional card; render_html is exempt.
_PROVISIONAL_ARGS_MIN_CHARS = 256
_DEFAULT_STREAM_STALL_TIMEOUT_S = 120.0  # 2 min
# Textual-fallback tool calls are not grammar-bounded, so cap them per turn.
_MAX_TOOL_CALLS_PER_TURN = 8
# The first retry already runs with thinking off; more attempts rarely help.
_MAX_LENGTH_CONTINUATIONS = 2
_CONTINUE_AFTER_LENGTH_STATUS = "Continuing after a long thought..."
_CONTINUE_TRUNCATED_ANSWER_STATUS = "Continuing the answer..."
# Below this a tool result carries only the cut notice; the floor catches a collapse to zero.
_MIN_USEFUL_RESULT_TOKENS = 64
# llama.cpp's default per-image embedding cap plus mtmd's delimiters, when the admission figure is out of reach.
_FALLBACK_IMAGE_TOKENS = 4096 + 128


def _mcp_image_tokens(backend) -> int:
    """Per-image KV allowance for the loaded projector, the one admission charges."""
    try:
        from routes.inference import _openai_llama_admission_image_tokens  # noqa: PLC0415
        return int(_openai_llama_admission_image_tokens(backend))
    except Exception:  # noqa: BLE001 -- sizing must never break a tool call
        return _FALLBACK_IMAGE_TOKENS


# mtmd's delimiters around an image's embeddings, as admission allows for them.
_IMAGE_WRAPPER_TOKENS = 128
# Qwen-VL merges a 2x2 patch square per embedding: 14 px patches on Qwen2/2.5-VL, 16 on Qwen3-VL.
_MERGED_PATCH_PX = {"qwen2vl_merger": 28, "qwen2.5vl_merger": 28, "qwen3vl_merger": 32}
# Fixed per image: Gemma 3 pools 896 px to 16 x 16 (258 measured on Gemma 3 4B, ceiling 4224).
_FIXED_IMAGE_TOKENS = {"gemma3": 256}


def _image_token_price(backend, part: dict) -> int:
    """One image's prompt cost for the fit and tool-result sizing (#14968): the admission ceiling,
    unless a known projector gives a closer upper bound (the ceiling evicts history that fits)."""
    ceiling = _mcp_image_tokens(backend)
    if ceiling <= 0:
        return 0
    projector = str(getattr(backend, "_mmproj_projector_type", None) or "").strip().lower()
    fixed = _FIXED_IMAGE_TOKENS.get(projector)
    if fixed:
        return min(ceiling, fixed + _IMAGE_WRAPPER_TOKENS)
    merged = _MERGED_PATCH_PX.get(projector)
    dims = image_dimensions(part) if merged else None
    if dims is None:
        return ceiling
    width, height = dims
    # Ceil, not round: mtmd may round either side up, and this must stay an upper bound.
    tokens = math.ceil(width / merged) * math.ceil(height / merged)
    extra_args = getattr(backend, "_extra_args", None)
    try:
        cap = extra_args_image_max_tokens(extra_args) or 0
        # mtmd resizes against --image-min-tokens on its own rounded grid, which this does not model.
        if extra_args_image_min_tokens(extra_args):
            return ceiling
    except Exception:  # noqa: BLE001 -- pricing must never break a count
        cap = 0
    cap = cap or ceiling - _IMAGE_WRAPPER_TOKENS
    return min(ceiling, min(tokens, cap) + _IMAGE_WRAPPER_TOKENS)


# How many times one tool may return a byte-identical result before the model is told the
# call is not going to change. Follows OpenClaw's tool-loop detection, which keys on the
# RESULT rather than the arguments and never intervenes while results are still changing:
# the arguments varied on every one of the 18 calls observed here, so an argument-keyed
# guard would have watched the whole thing happen.
_MAX_IDENTICAL_TOOL_RESULTS = 3

# Unset (no kwargs passed) differs from None, a real value meaning send no chat_template_kwargs.
_UNSET = object()


# A result with this tail is the window's answer, not the tool's.
_WINDOW_NOTICE_MARKER = "chars for the model;"
# Zero-budget results use _zero_room_stub, which lacks the marker above; missing it lets a model re-read slices forever, so catch it too.
_ZERO_ROOM_MARKER = "no context room left"


def _is_window_notice(result: str) -> bool:
    return _WINDOW_NOTICE_MARKER in result or _ZERO_ROOM_MARKER in result


def _note_before_envelopes(result: str, tool_name: str, add_note) -> str:
    """Text after the __MCP_IMAGES__ array breaks its parse and ships the base64 as text (#11358)."""
    if not isinstance(result, str):
        return add_note(result)
    from core.inference.tools import _split_frontend_suffix

    body, suffix = _split_frontend_suffix(result, tool_name)
    return add_note(body) + suffix


# How far back the classifier looks for llama.cpp's argument-parsing error. It
# prints one and exits, so it is always at the end; generous enough to survive a
# usage hint printed after it, small enough that a 10 MB unterminated line (which
# _drain_stdout keeps whole) stays cheap to scan.
_FAILURE_SCAN_TAIL_CHARS = 64 * 1024
# Caps the child output quoted in errors: enough for a real flag or reason, not megabytes of noise.
_FAILURE_QUOTE_CHARS = 200
# Sentence-anchored: mid-sentence the same words are prose naming a tool and suppressing them loses answers. Keep invoke and query out of the verb list.
_FORCED_PLAN_INTENT = re.compile(
    r"(?:^|[.!?]\s+)\s*"
    r"(?:i\s+(?:(?:need|have|ought)\s+to|should|must)|need\s+to|going\s+to|must|should)"
    r"\s+(?:\w+\s+){0,2}?(?:call|use|run|search|fetch|render)\b",
    re.I | re.M,
)
# Negated forms announce a missing answer, so they are excluded.
_FINAL_ANSWER_SIGNAL = re.compile(
    r"\b(?:final\s+answer|answer\s*:|here\s+is|here's|in\s+summary|result\s*:"
    r"|(?:the\s+)?answer\s+is(?!\s+(?:not|unavailable|unknown|unclear|missing)\b))\b",
    re.I,
)
# A plan that pivots to an answer must survive; the pivot needs its own text. When in doubt keep output: a leaked plan is cosmetic, a dropped answer is not.
_ANSWER_PIVOT = re.compile(
    r"\b(?:but|however|although|though|that\s+said|in\s+the\s+meantime|meanwhile)\b"
    r"[\W_]*(?:\w+[\W_]+){1,}\w",
    re.I,
)


def _gguf_active_tool_names(active_tools: list[dict]) -> list[str]:
    names = [
        (tool.get("function") or {}).get("name")
        for tool in (active_tools or [])
        if isinstance(tool, dict) and isinstance(tool.get("function"), dict)
    ]
    return [name for name in names if name]


# Lookbehind excludes the Mistral [CALL_ID]...[ARGS] shape.
_GGUF_REHEARSAL_ARGS_RE = re.compile(r"(?<!\[CALL_ID\])\b([\w-]+)\[ARGS\]")


def _gguf_rehearsal_signal_pos(text: str, active_tools: list[dict]) -> int:
    """Index of the first ``NAME[ARGS]`` whose NAME is markerless-promotable, else -1. An
    inactive-name ``foo[ARGS]`` in prose is not a call, nor is a bare execution-class
    ``terminal[ARGS]``; mirrors the safetensors ``_earliest_tool_signal`` gating."""
    active = set(_gguf_active_tool_names(active_tools))
    if not active:
        return -1
    for m in _GGUF_REHEARSAL_ARGS_RE.finditer(text):
        if _markerless_promotable(m.group(1), active):
            return m.start()
    return -1


def _gguf_has_genuine_tool_signal(text: str, signals, active_tools: list[dict]) -> bool:
    """Unambiguous markers count on a plain substring hit; an [ARGS] hit is genuine only with an active tool name before it, so inactive-name prose is not parsed."""
    for sig in signals:
        if sig == "[ARGS]":
            if _gguf_rehearsal_signal_pos(text, active_tools) >= 0:
                return True
            continue
        if sig in text:
            return True
    # The parser promotes bare Gemma anywhere, so a mid-prose one is a boundary too.
    return promotable_gemma_call_pos(text, lambda: set(_gguf_active_tool_names(active_tools))) >= 0


_TEXT_TOOL_NAME_RE = re.compile(r'"name"\s*:\s*"([\w.\-]+)"')
_TEXT_TOOL_GEMMA_RE = re.compile(r"\s*call:([\w.\-]+)")
_TEXT_TOOL_REHEARSAL_RE = re.compile(r"\s*([\w.\-]+)\s*\[ARGS\]")


def _sniff_text_tool_name(text: str, enabled_names: set) -> str:
    """Only enabled names are returned, so prose cannot open a tool card; the final parse still decides."""
    # A blocked leading call will not run, so skip every markerless format before naming.
    text = text[blocked_markerless_prefix_end(text, 0, enabled_names) :]
    m = _TEXT_TOOL_NAME_RE.search(text[:4096])
    if m and m.group(1) in enabled_names:
        return m.group(1)
    m = _TEXT_TOOL_GEMMA_RE.match(text[:256])
    if m and _markerless_promotable(m.group(1), enabled_names):
        return m.group(1)
    m = _TEXT_TOOL_REHEARSAL_RE.match(text[:256])
    if m and _markerless_promotable(m.group(1), enabled_names):
        return m.group(1)
    return ""


def _is_rehearsal_prefix(stripped: str, active_tools: list[dict]) -> bool:
    """Execution-class names stream rather than being held; otherwise it mirrors the safetensors loop."""
    if not stripped or any(ch.isspace() for ch in stripped):
        return False
    for name in _gguf_active_tool_names(active_tools):
        # Use the shared gate, which also refuses mcp__* names.
        if not _markerless_promotable(name, None):
            continue
        if stripped == name or f"{name}[ARGS]".startswith(stripped):
            return True
    return False


def _held_rehearsal_tail_len(text: str, active_tools: list[dict]) -> int:
    """Holds a trailing bare tool name back while its [ARGS] may still arrive, including a bare-Gemma call:NAME{ prefix that the signal scan misses until its brace."""
    # A tail longer than every NAME[ARGS] cannot be a prefix, so the scan stops there (CJK has no spaces).
    limit = max(
        (len(name) for name in _gguf_active_tool_names(active_tools) if isinstance(name, str)),
        default = 0,
    ) + len("[ARGS]")
    i = len(text)
    stop = max(0, i - limit - 1)
    while i > stop and not text[i - 1].isspace():
        i -= 1
    tail = text[i:]
    held = (
        len(tail) if tail and len(tail) <= limit and _is_rehearsal_prefix(tail, active_tools) else 0
    )
    return max(
        held, held_bare_gemma_tail_len(text, lambda: set(_gguf_active_tool_names(active_tools)))
    )


def _should_suppress_forced_no_tool_output(text: str, previous: str = "") -> bool:
    """Suppresses only a repeat of the stall text that triggered the nudge, never a final answer."""
    stripped = text.strip()
    if not stripped or len(stripped) >= _REPROMPT_MAX_CHARS:
        return False
    if _FINAL_ANSWER_SIGNAL.search(stripped):
        return False
    plan = _FORCED_PLAN_INTENT.search(stripped)
    if plan is not None:
        # Only the plan itself is safe to drop; anything the turn pivots to after it is the answer.
        return _ANSWER_PIVOT.search(stripped[plan.end() :]) is None
    if not _is_short_intent_without_action(stripped):
        return False
    # INTENT_SIGNAL also fires on answer lead-ins; a stall only if the retry adds nothing.
    return not previous or _is_reprompt_restatement(stripped, previous)


# ── Pre-compiled patterns for GGUF shard detection ───────────
_SHARD_FULL_RE = re.compile(r"^(.*)-(\d{5})-of-(\d{5})\.gguf$", re.IGNORECASE)
_SHARD_RE = re.compile(r"^(.*)-\d{5}-of-\d{5}\.gguf$", re.IGNORECASE)


def _gguf_set_bytes(path: Path) -> int:
    """Size of a GGUF plus, when it is a split one, its sibling shards: llama-server opens the whole set."""
    total = 0
    try:
        if path.is_file():
            total += path.stat().st_size
        m = _SHARD_FULL_RE.match(path.name)
        if m is None or not path.parent.is_dir():
            return total
        # llama.cpp names a shard "<prefix>-<i>-of-<count>.gguf" from the first one's, so both must match: a
        # drafter split as "<main prefix>-MTP-..." or a stale set with another count is not this set.
        prefix, count = m.group(1).lower(), int(m.group(3))
        for sibling in path.parent.iterdir():
            if sibling.name == path.name:
                continue
            sibling_match = _SHARD_FULL_RE.match(sibling.name)
            if (
                sibling_match is None
                or sibling_match.group(1).lower() != prefix
                or int(sibling_match.group(3)) != count
                or not 1 <= int(sibling_match.group(2)) <= count
            ):
                continue
            try:
                if sibling.is_file():
                    total += sibling.stat().st_size
            except OSError:
                pass
    except OSError:
        pass
    return total


# ── Sliding-window-pattern resolver ───────────────────────────
# Period N: layer i is SWA iff (i+1) % N != 0. Absent: phi3 (no key/val length), qwen2 (converter strips the window), mistral v0.1/v0.2 (all-SWA is no period).
_BOOTSTRAP_SWA_DEFAULTS: dict[str, int] = {
    "gemma2": 2,  # Gemma2Config.sliding_window_pattern
    "gemma3": 6,  # Gemma3TextConfig.sliding_window_pattern
    "gemma3n": 5,  # text_config.layer_types: SWA*4 + FULL
    "gpt_oss": 2,  # text_config.layer_types: alternating
    "cohere2": 4,  # Cohere2Config.sliding_window_pattern
}

# Values are int period or list[bool] mask; __missed_repos__ lists casefolded repos with no SWA field. JSON on disk, lazy-loaded.
_SWA_CACHE: Optional[dict] = None
_SWA_CACHE_LOCK = threading.Lock()


def _hf_endpoint_host() -> str:
    """Host of the configured hub endpoint (HF_ENDPOINT aware)."""
    from utils.utils import hf_endpoint_host
    return hf_endpoint_host()


def _probe_dns_dead(host: Optional[str] = None, timeout: float = 2.0) -> bool:
    """Quick DNS check on a daemon thread, so concurrent sockets aren't
    affected by socket.setdefaulttimeout. Defaults to the configured endpoint's host."""
    from utils.utils import dns_host_dead, hf_endpoint_host
    return dns_host_dead(host or hf_endpoint_host(), timeout)


def _hf_env_offline() -> bool:
    """Accepts any truthy HF_HUB_OFFLINE (1, true, yes, on) to match _env_offline, not only 1."""
    try:
        from utils.models.model_config import _env_offline
        return _env_offline()
    except Exception:
        return os.environ.get("HF_HUB_OFFLINE", "").strip().lower() in {"1", "true", "yes", "on"}


def _hf_unreachable() -> bool:
    """DNS alone misses captive portals and WAN outages; the DNS shortcut is skipped when a proxy is set."""
    try:
        from utils.utils import hf_dns_dead, hf_reachability_memo, hf_unreachable
    except Exception:
        return False
    # Reuse a fresh verdict (a slow resolver costs a timeout per guard). Peek only, never record: recording a dead lookup would make recovery sticky for the TTL.
    memo = hf_reachability_memo()
    if memo is not None:
        return memo
    if hf_dns_dead():
        return True
    return hf_unreachable()


# Separates "nothing remembered" from a remembered verdict of None (not a media GGUF).
_MISS = object()


# GGUF unsigned value-type id -> byte width (uint8, uint16, uint32, uint64).
_GGUF_UINT_WIDTHS = {0: 1, 2: 2, 4: 4, 10: 8}
_GGUF_MARKUP_FIRST_BYTES = frozenset(b"<[")


@contextlib.contextmanager
def _hf_offline_if_unreachable():
    """Refcounted so one guard exit cannot re-enable the Hub mid-request. Forces offline only when unreachable; no-op if the user set the env var."""
    try:
        from utils.utils import force_hf_offline, force_hf_offline_state, hf_env_offline
    except Exception:
        yield False
        return

    ours, hf_hub_env_present = force_hf_offline_state()
    # Membership keeps HF_HUB_OFFLINE=0 as a stay-online override. Read it under the refcount so a concurrent guard cannot look user-owned.
    if hf_hub_env_present and not ours:
        yield False
        return
    # The hub ignores TRANSFORMERS_OFFLINE, so honour it here without probing.
    if not ours and hf_env_offline():
        with force_hf_offline():
            yield True
        return
    # Already forced by an in-flight guard: reuse that verdict and hold a reference.
    if not ours and not _hf_unreachable():
        yield False
        return

    if not ours:
        logger.warning("Hugging Face endpoint unreachable; using local HF cache for this load.")
    with force_hf_offline():
        yield True


def _hf_offline_if_unreachable_for(model_name):
    """Guard, but only for remote repo ids: a local path is served from disk and never
    reaches the hub, so probing would add seconds per request and prevent no retry."""
    try:
        from utils.paths import is_local_path
        if isinstance(model_name, str) and is_local_path(model_name):
            return contextlib.nullcontext()
    except Exception:
        pass
    return _hf_offline_if_unreachable()


try:
    _SLOT_SAVE_MAX_BYTES = int(os.environ.get("UNSLOTH_SLOT_SAVE_MAX_BYTES") or (10 << 30))
except ValueError:
    _SLOT_SAVE_MAX_BYTES = 10 << 30

# The idle loop holds the lifecycle gate across a slot save, so bound it.
# Override with UNSLOTH_SLOT_SAVE_TIMEOUT (seconds).
try:
    _SLOT_SAVE_HTTP_TIMEOUT = float(os.environ.get("UNSLOTH_SLOT_SAVE_TIMEOUT") or 30.0)
except ValueError:
    _SLOT_SAVE_HTTP_TIMEOUT = 30.0
if _SLOT_SAVE_HTTP_TIMEOUT <= 0:
    _SLOT_SAVE_HTTP_TIMEOUT = 30.0


def _swa_cache_path() -> Path:
    home = os.environ.get("UNSLOTH_STUDIO_HOME") or os.environ.get("STUDIO_HOME")
    base = Path(home) if home else Path.home() / ".unsloth" / "studio"
    return base / "swa_cache.json"


def _load_swa_cache() -> dict:
    global _SWA_CACHE
    with _SWA_CACHE_LOCK:
        if _SWA_CACHE is not None:
            return _SWA_CACHE
        try:
            with open(_swa_cache_path(), encoding = "utf-8-sig") as f:
                _SWA_CACHE = json.load(f)
                if not isinstance(_SWA_CACHE, dict):
                    _SWA_CACHE = {}
        except (FileNotFoundError, json.JSONDecodeError, OSError, UnicodeDecodeError):
            _SWA_CACHE = {}
        return _SWA_CACHE


def _save_swa_cache(cache: dict) -> None:
    try:
        path = _swa_cache_path()
        path.parent.mkdir(parents = True, exist_ok = True)
        tmp = path.with_suffix(".json.tmp")
        with open(tmp, "w", encoding = "utf-8") as f:
            json.dump(cache, f, indent = 2, sort_keys = True)
        tmp.replace(path)
    except (OSError, UnicodeDecodeError):
        pass


def _period_from_layer_types(layer_types: list) -> Optional[int]:
    """Smallest period N where `(i+1) % N != 0` matches the SWA mask, else None."""
    if not layer_types:
        return None
    is_swa = ["full" not in str(t).lower() for t in layer_types]
    n = len(is_swa)
    for N in range(1, n + 1):
        if all(((i + 1) % N != 0) == is_swa[i] for i in range(n)):
            return N
    return None


def _swa_entry_from_layer_types(lt) -> Optional[object]:
    """Period int, or per-layer bool mask, from a transformers ``layer_types`` list."""
    if isinstance(lt, list) and lt:
        return _period_from_layer_types(lt) or ["full" not in str(t).lower() for t in lt]
    return None


_SWA_CONFIRMED_MISS = False
_SWA_MISSED_REPOS_KEY = "__missed_repos__"


def _swa_missed_repos(cache: dict) -> set:
    missed = cache.get(_SWA_MISSED_REPOS_KEY)
    if not isinstance(missed, list):
        return set()
    return {item.casefold() for item in missed if isinstance(item, str)}


def _remember_swa_repo_miss(cache: dict, repo_id: str) -> None:
    folded = repo_id.casefold()
    with _SWA_CACHE_LOCK:
        missed = _swa_missed_repos(cache)
        if folded in missed:
            return
        missed.add(folded)
        cache[_SWA_MISSED_REPOS_KEY] = sorted(missed)
    _save_swa_cache(cache)


def _fetch_swa_entry_from_hf(repo_id: str) -> Optional[object]:
    try:
        from huggingface_hub import hf_hub_download, try_to_load_from_cache
        from utils.hf_cache_settings import active_hf_hub_cache
        from utils.hf_probe import hf_file_definitely_absent

        cached = try_to_load_from_cache(repo_id, "config.json", cache_dir = active_hf_hub_cache())
        if isinstance(cached, str):
            with open(cached, encoding = "utf-8-sig") as f:
                cfg = json.load(f)
        else:
            # Only a confirmed 404 is a miss; timeouts, 429 and gated stay None so a later load retries.
            if hf_file_definitely_absent(repo_id, "config.json"):
                return _SWA_CONFIRMED_MISS
            # Throwaway cache: a config-only repo in the user's cache lists as a phantom model (#10047).
            with tempfile.TemporaryDirectory(
                prefix = "unsloth-swa-", ignore_cleanup_errors = True
            ) as tmp:
                cfg_path = call_hub_with_anonymous_retry(
                    hf_hub_download,
                    None,
                    repo_id,
                    "config.json",
                    repo_type = "model",
                    cache_dir = tmp,
                )
                with open(cfg_path, encoding = "utf-8-sig") as f:
                    cfg = json.load(f)
    except Exception:
        return None

    src = cfg.get("text_config") if isinstance(cfg.get("text_config"), dict) else cfg
    period = src.get("sliding_window_pattern")
    if isinstance(period, int) and period > 0:
        return period
    entry = _swa_entry_from_layer_types(src.get("layer_types"))
    return entry if entry is not None else _SWA_CONFIRMED_MISS


def _arch_aliases(arch: str) -> tuple:
    # GGUF emits `falcon-h1`; HF model_type is `falcon_h1`. Normalise both ways.
    seen = []
    for a in (arch, arch.replace("-", "_"), arch.replace("_", "-")):
        if a and a not in seen:
            seen.append(a)
    return tuple(seen)


def _swa_entry_from_config_obj(cfg) -> Optional[object]:
    src = getattr(cfg, "text_config", None) or cfg
    period = getattr(src, "sliding_window_pattern", None)
    if isinstance(period, int) and period > 0:
        return period
    return _swa_entry_from_layer_types(getattr(src, "layer_types", None))


_SWA_PATTERN_SOURCE_RE = re.compile(r"sliding_window_pattern\s*(?::\s*[\w\[\], ]*)?\s*=\s*(\d+)")


def _resolve_swa_entry_from_transformers(arch: str) -> Optional[object]:
    """Default-instantiate the matching Config; on failure, regex-parse its
    source for `sliding_window_pattern = N`."""
    try:
        from transformers.models.auto.configuration_auto import (
            CONFIG_MAPPING,
            CONFIG_MAPPING_NAMES,
        )
    except Exception:
        return None

    cfg_class = None
    for alias in _arch_aliases(arch):
        if alias in CONFIG_MAPPING_NAMES:
            try:
                cfg_class = CONFIG_MAPPING[alias]
                break
            except Exception:
                cfg_class = None
    if cfg_class is None:
        return None

    try:
        if (entry := _swa_entry_from_config_obj(cfg_class())) is not None:
            return entry
    except Exception:
        pass

    import inspect

    candidates = [cfg_class]
    text_cfg_class = getattr(cfg_class, "sub_configs", {}).get("text_config")
    if text_cfg_class is not None:
        candidates.append(text_cfg_class)
    for cls in candidates:
        try:
            src = inspect.getsource(cls)
        except (OSError, TypeError):
            continue
        if m := _SWA_PATTERN_SOURCE_RE.search(src):
            period = int(m.group(1))
            if period > 0:
                return period
    return None


def _resolve_swa_pattern(
    arch: Optional[str],
    n_layers: Optional[int],
    source_repo_candidates: tuple = (),
    *,
    allow_network: Optional[bool] = None,
) -> Optional[list]:
    if not arch or not n_layers:
        return None
    if allow_network is None:
        allow_network = os.environ.get("UNSLOTH_STUDIO_OFFLINE", "0") not in (
            "1",
            "true",
            "True",
            "yes",
        )

    cache = _load_swa_cache()

    def _entry_to_mask(entry):
        if isinstance(entry, int) and entry > 0:
            return [(i + 1) % entry != 0 for i in range(n_layers)]
        if isinstance(entry, list) and entry:
            return [bool(entry[i % len(entry)]) for i in range(n_layers)]
        return None

    def _persist(entry):
        with _SWA_CACHE_LOCK:
            cache[arch] = entry
        _save_swa_cache(cache)

    if (entry := cache.get(arch)) is not None:
        if (mask := _entry_to_mask(entry)) is not None:
            return mask

    if (entry := _BOOTSTRAP_SWA_DEFAULTS.get(arch)) is not None:
        return _entry_to_mask(entry)

    entry = _resolve_swa_entry_from_transformers(arch)
    if entry is not None:
        _persist(entry)
        return _entry_to_mask(entry)

    # Tier 3: live HF fetch. Misses are keyed per repo, not arch: a new GGUF may name a new source.
    if allow_network:
        seen = set()
        missed = _swa_missed_repos(cache)
        for repo_id in source_repo_candidates:
            if not repo_id:
                continue
            folded = repo_id.casefold()
            if folded in seen or folded in missed:
                continue
            seen.add(folded)
            entry = _fetch_swa_entry_from_hf(repo_id)
            if entry is _SWA_CONFIRMED_MISS:
                _remember_swa_repo_miss(cache, folded)
                continue
            if entry is not None:
                _persist(entry)
                return _entry_to_mask(entry)

    return None


def _hf_repo_from_url(url: Optional[str]) -> Optional[str]:
    """Strips a huggingface.co or mirrored HF_ENDPOINT URL to owner/name; huggingface.co still accepted."""
    if not url:
        return None
    from utils.hf_endpoint import get_hf_endpoint

    marker = "huggingface.co/"
    if marker not in url:
        mirror = get_hf_endpoint().split("://", 1)[-1].rstrip("/") + "/"
        if mirror in url:
            marker = mirror
        else:
            return None
    tail = url.split(marker, 1)[1].rstrip("/")
    parts = tail.split("/")
    if len(parts) < 2:
        return None
    return f"{parts[0]}/{parts[1]}"


# Lazy import to avoid pulling transformers in at module level.
def _extract_model_size_b(model_id: str):
    from utils.models import extract_model_size_b
    return extract_model_size_b(model_id)


# Ordered weakest -> strongest. Must stay in sync with REASONING_EFFORT_SCALE in
# studio/frontend/src/features/chat/provider-capabilities.ts.
_REASONING_EFFORT_SCALE = ("none", "minimal", "low", "medium", "high", "xhigh", "max")

# Matches Qwen3.8 but not future names such as Qwen3.80.
_QWEN38_MODEL_RE = re.compile(r"(?:^|[^a-z0-9])qwen3\.8(?:$|[-_/\\])", re.IGNORECASE)


def _extract_reasoning_effort_levels(chat_template: str) -> list:
    """Reports only the levels the template quotes, in canonical order, not the whole scale."""
    return [
        level
        for level in _REASONING_EFFORT_SCALE
        if f"'{level}'" in chat_template or f'"{level}"' in chat_template
    ]


# Log each substitution once per (levels, requested) pair.
_REASONING_EFFORT_CLAMPS_LOGGED: set = set()


def _clamp_reasoning_effort_to_levels(effort: Optional[str], levels) -> Optional[str]:
    """Mirrors the UI clamp in provider-capabilities.ts: prefer the nearest lower level, then the weakest; an unavailable xhigh becomes max when offered."""
    if effort not in _REASONING_EFFORT_SCALE or not levels:
        return None
    if effort == "xhigh" and "xhigh" not in levels and "max" in levels:
        effort = "max"
    if effort in levels:
        return effort
    offered = [level for level in _REASONING_EFFORT_SCALE if level in levels and level != "none"]
    if not offered:
        return None
    rank = _REASONING_EFFORT_SCALE.index(effort)
    below = [level for level in offered if _REASONING_EFFORT_SCALE.index(level) < rank]
    return below[-1] if below else offered[0]


# Keyed on identity, not name, so a rebuilt GGUF at the same path is logged again.
_GGUF_METADATA_LOGGED: "dict[tuple, bool]" = {}
_GGUF_METADATA_LOGGED_MAX = 32
_GGUF_METADATA_LOGGED_LOCK = threading.Lock()


def _note_gguf_metadata_read(gguf_path: str) -> bool:
    """True on the first read of this file or when its stat fails; False on repeat reads."""
    try:
        st = os.stat(gguf_path)
        key = (os.path.abspath(gguf_path), st.st_size, st.st_mtime_ns)
    except Exception:
        return True
    with _GGUF_METADATA_LOGGED_LOCK:
        if key in _GGUF_METADATA_LOGGED:
            return False
        _GGUF_METADATA_LOGGED[key] = True
        while len(_GGUF_METADATA_LOGGED) > _GGUF_METADATA_LOGGED_MAX:
            # Insertion-ordered, so this drops the oldest.
            del _GGUF_METADATA_LOGGED[next(iter(_GGUF_METADATA_LOGGED))]
        return True


def detect_reasoning_flags(
    chat_template: Optional[str],
    model_identifier: Optional[str] = None,
    *,
    log_source: Optional[str] = None,
    log_level: str = "info",
) -> dict:
    """Shared by the llama-server and safetensors paths so both agree on the flags the frontend sees."""
    flags = {
        "supports_reasoning": False,
        "reasoning_style": "enable_thinking",
        "reasoning_always_on": False,
        "reasoning_effort_levels": [],
        "supports_preserve_thinking": False,
        "preserve_thinking_default": False,
        "supports_tools": False,
    }
    if not chat_template:
        return flags
    tpl = chat_template
    prefix = f"{log_source}: " if log_source else ""
    # The GGUF sniffer re-derives these per request, so it logs at debug after the first read of a file.
    _log = logger.debug if log_level == "debug" else logger.info

    # 'none' is this style's disable sentinel; left in, a clamp would silently disable thinking.
    effort_levels = (
        [lv for lv in _extract_reasoning_effort_levels(tpl) if lv != "none"]
        if ("reasoning_effort" in tpl and "enable_thinking" in tpl)
        else []
    )
    if effort_levels:
        # DeepSeek-V4 takes high but its template only branches on max, so add it; match whole repo-name segments so deepseek-v40 does not false-match.
        from core.inference.model_ids import hf_cache_repo_id

        # A snapshot path's last component is the revision, so read it as its repo id first.
        repo_name = hf_cache_repo_id(model_identifier) or model_identifier or ""
        segments = re.split(r"[-_.]", repo_name.lower().split("/")[-1])
        is_dsv4 = "deepseek4" in segments or any(
            a == "deepseek" and b == "v4" for a, b in zip(segments, segments[1:])
        )
        if is_dsv4 and "high" not in effort_levels:
            effort_levels = sorted(set(effort_levels) | {"high"}, key = _REASONING_EFFORT_SCALE.index)
        # GLM-5.2 style: enable_thinking gate plus a discrete reasoning_effort level set.
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "enable_thinking_effort"
        flags["reasoning_effort_levels"] = effort_levels
        _log(
            f"{prefix}model supports reasoning "
            f"(enable_thinking + reasoning_effort: {effort_levels})"
        )
    elif "enable_thinking" in tpl:
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "enable_thinking"
        _log(f"{prefix}model supports reasoning (enable_thinking)")
    elif "reasoning_effort" in tpl:
        # gpt-oss / Harmony use reasoning_effort levels; trust the scan only if it has 'low' and 'high'.
        flags["supports_reasoning"] = True
        flags["reasoning_style"] = "reasoning_effort"
        scanned = _extract_reasoning_effort_levels(tpl)
        if "low" in scanned and "high" in scanned:
            flags["reasoning_effort_levels"] = scanned
        _log(
            f"{prefix}model supports reasoning "
            f"(reasoning_effort: {flags['reasoning_effort_levels'] or 'default levels'})"
        )
    elif "thinking" in tpl:
        # DeepSeek uses 'thinking', not 'enable_thinking'
        normalized_id = (model_identifier or "").lower()
        if "deepseek" in normalized_id:
            flags["supports_reasoning"] = True
            _log(f"{prefix}model supports reasoning (DeepSeek thinking)")

    # Hardcoded <think> or reasoning_content means thinking is always on.
    if not flags["supports_reasoning"]:
        if ("<think>" in tpl and "</think>" in tpl) or "reasoning_content" in tpl:
            flags["supports_reasoning"] = True
            flags["reasoning_always_on"] = True
            _log(f"{prefix}model always reasons (<think> tags in template)")

    # preserve_thinking is an independent kwarg on some Qwen templates that keeps prior <think> blocks.
    if "preserve_thinking" in tpl:
        flags["supports_preserve_thinking"] = True
        # Qwen3.8 deliberately defaults preserve_thinking on; keep it family-scoped.
        flags["preserve_thinking_default"] = bool(_QWEN38_MODEL_RE.search(model_identifier or ""))
        _log(f"{prefix}model supports preserve_thinking")

    from core.inference.template_capabilities import template_supports_tools

    if isinstance(tpl, str) and template_supports_tools(tpl):
        flags["supports_tools"] = True
        _log(f"{prefix}model supports tool calling")

    return flags


# Gemma 4 ships MTP as a separate drafter; Gemma 3n ships none.
_GEMMA_MTP_FAMILY_RE = re.compile(r"gemma[-_]?4[-_]", re.IGNORECASE)


def _is_gemma_mtp_family(name: Optional[str]) -> bool:
    """Match Gemma 4 by name."""
    return bool(name) and bool(_GEMMA_MTP_FAMILY_RE.search(name))


def _is_gemma_mtp_name(model_identifier: Optional[str], gguf_path: Optional[str] = None) -> bool:
    """Match Gemma 4 by id or GGUF filename."""
    return _is_gemma_mtp_family(model_identifier) or _is_gemma_mtp_family(
        Path(gguf_path).name if gguf_path else None
    )


def _is_mtp_model_name(model_identifier: Optional[str], gguf_path: Optional[str] = None) -> bool:
    """Name-based MTP detector. Fallback for the metadata signal."""
    for cand in (model_identifier, Path(gguf_path).name if gguf_path else None):
        if cand and "-mtp" in cand.lower():
            return True
        # Gemma 4 too: a failed drafter download surfaces a fallback reason instead of a silent default.
        if cand and _is_gemma_mtp_family(cand):
            return True
    return False


_DRAFTER_KINDS = _gguf_names.DRAFTER_KINDS
_DRAFTER_DIR_KINDS = _gguf_names.DRAFTER_DIR_KINDS

# Human label per resolved spec mode, for launch logging and the UI notice.
_DRAFTER_DISPLAY_LABELS = {"dspark": "DSpark", "dflash": "DFlash", "eagle3": "EAGLE-3"}


def _drafter_path_kind(path: str) -> Optional[str]:
    return _gguf_names.drafter_path_kind(path)


_IMATRIX_TOKEN_RE = _gguf_names.IMATRIX_TOKEN_RE


def _is_companion_gguf_path(path: str) -> bool:
    """Exclude companions from main-model selection; use _is_mtp_only_drafter_path for launch."""
    p = path.lower()
    if not p.endswith(".gguf"):
        return False
    if "mmproj" in p:
        return True
    if _gguf_names.is_imatrix_filename(p):
        return True
    return _gguf_names.is_mtp_drafter_path(path)


def _is_mtp_only_drafter_path(path: str) -> bool:
    """MTP only, not the other companion GGUFs. Each drafter kind needs its own
    ``--spec-type``, so discovery narrows to one kind rather than reusing the
    broad companion predicate, which exists to EXCLUDE companions from menus."""
    return _drafter_path_kind(path) == "mtp"


def _is_dspark_drafter_path(path: str) -> bool:
    """Broader than detect_dspark_file (no name check): only for repo listings and snapshots, since a local folder may hold anything."""
    return _drafter_path_kind(path) == "dspark"


def _is_dflash_drafter_path(path: str) -> bool:
    """Prefix only, since dflash is also a family name; a dflash/ folder does not mark a sidecar. Only a root-level dflash- prefixed GGUF names one."""
    return _drafter_path_kind(path) == "dflash"


def _is_root_dflash_drafter_path(path: str) -> bool:
    """Prefix AND repo root: a nested dflash- weight would otherwise download before rejection."""
    normalized = path.replace("\\", "/")
    return "/" not in normalized and _is_dflash_drafter_path(normalized)


_BIG_ENDIAN_GGUF_FILENAME_RE = re.compile(r"(^|[-_])be(?:[._-]|$)", re.IGNORECASE)
_GGUF_KNOWN_QUANT_RE = _gguf_names.GGUF_QUANT_RE
_DSPARK_BEFORE_QUANT_RE = _gguf_names.DSPARK_BEFORE_QUANT_RE


def _is_big_endian_gguf_path(path: str, variant_key: str = "") -> bool:
    normalized = path.replace("\\", "/")
    name = normalized.rsplit("/", 1)[-1]
    stem = name.rsplit(".", 1)[0].lower()
    variant_key = variant_key.strip().lower()
    variant_index = stem.find(variant_key) if variant_key else -1
    parent = normalized.rsplit("/", 1)[0].lower() if "/" in normalized else ""
    variant_in_parent_only = (
        bool(parent)
        and variant_index < 0
        and (
            (variant_key and variant_key in parent)
            or (not variant_key and _GGUF_KNOWN_QUANT_RE.search(parent) is not None)
        )
    )
    for match in _BIG_ENDIAN_GGUF_FILENAME_RE.finditer(stem):
        if variant_index >= 0 and variant_index < match.start():
            return True
        tail = stem[match.end() :].lstrip("._-")
        if not tail or _GGUF_KNOWN_QUANT_RE.search(tail) is None:
            return not variant_in_parent_only
    return False


def _gguf_snapshot_files(snapshot: Path) -> list[str]:
    return [
        p.relative_to(snapshot).as_posix()
        for p in snapshot.rglob("*")
        if p.is_file() and p.name.lower().endswith(".gguf") and not is_appledouble_metadata(p)
    ]


def _cached_hf_snapshot_file(
    repo_id: str,
    filename: str,
    *,
    expected_size: Optional[int] = None,
    cache_dir: Optional[str] = None,
) -> Optional[str]:
    """Return a cached snapshot file even when HF's current-ref probe misses it."""
    if not filename:
        return None
    parts = [part for part in filename.replace("\\", "/").split("/") if part]
    if not parts or any(part in (".", "..") for part in parts):
        return None
    try:
        if cache_dir is None:
            from utils.models.model_config import _iter_hf_cache_snapshots
            snapshots = _iter_hf_cache_snapshots(repo_id)
        else:
            from hub.utils.hf_cache_state import iter_active_repo_cache_dirs
            snapshots = (
                snapshot
                for repo_dir in iter_active_repo_cache_dirs(
                    "model",
                    repo_id,
                    root = Path(cache_dir),
                )
                for snapshot in (repo_dir / "snapshots").glob("*")
                if snapshot.is_dir()
            )
        for snap in snapshots:
            candidate = snap.joinpath(*parts)
            if not candidate.is_file():
                continue
            if expected_size:
                try:
                    if candidate.stat().st_size < expected_size:
                        continue
                except OSError:
                    continue
            return str(candidate)
    except Exception as e:
        logger.debug("Snapshot cache lookup failed for %s/%s: %s", repo_id, filename, e)
    return None


def _snapshot_has_all_shards(
    main_path: str, main_filename: str, shards: Iterable[str], expected_sizes: dict[str, int]
) -> bool:
    """llama.cpp finds split shards beside the main file, so the whole set must share a snapshot."""
    root = Path(main_path)
    for _ in [part for part in main_filename.replace("\\", "/").split("/") if part]:
        root = root.parent
    for shard in shards:
        parts = [part for part in shard.replace("\\", "/").split("/") if part]
        if not parts or any(part in (".", "..") for part in parts):
            return False
        sibling = root.joinpath(*parts)
        try:
            if not sibling.is_file():
                return False
            expected = expected_sizes.get(shard)
            if expected and sibling.stat().st_size < expected:
                return False
        except OSError:
            return False
    return True


def _resolve_repo_id_casing(hf_repo: str) -> str:
    """Maps a case-variant id to the cached casing so main and companion GGUFs share one cache entry; returns hf_repo unchanged on failure."""
    try:
        from utils.paths import resolve_cached_repo_id_case
        return resolve_cached_repo_id_case(hf_repo)
    except Exception:
        return hf_repo


def _cached_gguf_snapshots(repo_id: str):
    """Retain the existing active-cache lookup; add remembered chat copies once."""
    from utils.models.model_config import _iter_hf_cache_snapshots
    from hub.utils.gguf_sources import gguf_cache_snapshots

    seen = set()
    for snapshots in (_iter_hf_cache_snapshots(repo_id), gguf_cache_snapshots(repo_id)):
        for snapshot in snapshots:
            key = str(snapshot.resolve())
            if key not in seen:
                seen.add(key)
                yield snapshot


def _cached_colocated_split_main(
    repo_id: str, main_filename: str, shards: Iterable[str], expected_sizes: dict[str, int]
) -> Optional[str]:
    """Prefers a snapshot with the full split set; a newer partial main would force a refetch."""
    main_parts = [part for part in main_filename.replace("\\", "/").split("/") if part]
    if not main_parts or any(part in (".", "..") for part in main_parts):
        return None
    try:
        for snap in _cached_gguf_snapshots(repo_id):
            main_path = snap.joinpath(*main_parts)
            if not main_path.is_file():
                continue
            expected_main = expected_sizes.get(main_filename)
            try:
                if expected_main and main_path.stat().st_size < expected_main:
                    continue
            except OSError:
                continue
            if _snapshot_has_all_shards(str(main_path), main_filename, shards, expected_sizes):
                return str(main_path)
    except Exception as e:
        logger.debug("Co-located split snapshot lookup failed for %s: %s", repo_id, e)
    return None


def _cached_variant_resolution(repo_id: str, hf_variant: str) -> tuple[Optional[str], list[str]]:
    """Find a cached main GGUF and its shards for a variant."""
    candidate = next(_cached_variant_candidates(repo_id, hf_variant), None)
    if candidate is None:
        return None, []
    _, main, shards, _ = candidate
    return main, shards


def _cached_variant_candidates(
    repo_id: str,
    hf_variant: str,
    *,
    require_mmproj: bool = False,
    strict: bool = False,
) -> Generator[tuple[str, str, list[str], Path], None, None]:
    """Incomplete or cancelled copies come last, and strict drops them so only a Hub-free copy qualifies."""
    try:
        from hub.utils.gguf_sources import (
            cached_gguf_manifest_complete,
            cached_gguf_source_partial,
        )

        pending_downloads = []
        for snap in _cached_gguf_snapshots(repo_id):
            cached_files = _gguf_snapshot_files(snap)
            matches = _gguf_files_for_variant(cached_files, hf_variant)
            if not matches:
                continue
            main = matches[0]
            shards = _gguf_extra_shards(matches, main)
            split = _SHARD_FULL_RE.match(main)
            if split:
                numbers = {
                    int(match.group(2))
                    for path in [main, *shards]
                    if (match := _SHARD_FULL_RE.match(path))
                }
                if numbers != set(range(1, int(split.group(3)) + 1)):
                    continue
            main_path = snap.joinpath(*main.replace("\\", "/").split("/"))
            if not main_path.is_file() or not _snapshot_has_all_shards(
                str(main_path), main, shards, {}
            ):
                continue
            if require_mmproj and not _pick_mmproj(cached_files):
                continue
            candidate = (str(main_path), main, shards, snap)
            if not cached_gguf_manifest_complete(
                repo_id, hf_variant, snap
            ) or cached_gguf_source_partial(repo_id, hf_variant, snap):
                pending_downloads.append(candidate)
                continue
            yield candidate
        # Keep existing reuse semantics when no completed duplicate is available.
        if not strict:
            yield from pending_downloads
    except Exception as e:
        logger.debug(f"Cache lookup for variant failed: {e}")


def _cached_variant_sizes(
    repo_id: str, hf_variant: str, main_path: str
) -> Optional[tuple[tuple[str, int], ...]]:
    """Sorted (filename, size) pairs of the complete cached copy at main_path, or None; compared later to catch truncated or dropped shards offline."""
    target = os.path.abspath(main_path)
    for cached_main, main, shards, snap in _cached_variant_candidates(repo_id, hf_variant):
        if os.path.abspath(cached_main) != target:
            continue
        try:
            return tuple(
                sorted(
                    (name, os.path.getsize(snap.joinpath(*name.replace("\\", "/").split("/"))))
                    for name in (main, *shards)
                )
            )
        except OSError:
            return None
    return None


def _cached_candidate_matches_revision_size(
    repo_id: str, candidate: tuple[str, str, list[str], Path], hf_token: Optional[str]
) -> bool:
    """Compares sizes with the Hub revision when reachable, so a manually truncated cache is not reused."""
    main_path, main, shards, snap = candidate
    paths = [main, *shards]
    try:
        from huggingface_hub import get_paths_info
        infos = list(
            call_hub_with_anonymous_retry(
                get_paths_info,
                hf_token,
                repo_id,
                paths,
                revision = snap.name,
            )
        )
    except Exception as e:
        logger.debug(
            "Could not size-check cached GGUF %s at revision %s: %s",
            repo_id,
            snap.name,
            e,
        )
        return True

    if not infos:
        # The Hub answers an unknown revision with an empty result, not an error; treat it like unreachable metadata.
        return True
    expected_sizes = {info.path: info.size for info in infos if info.size is not None}
    if any(path not in expected_sizes for path in paths):
        return False
    try:
        if os.path.getsize(main_path) < expected_sizes[main]:
            return False
    except OSError:
        return False
    return _snapshot_has_all_shards(main_path, main, shards, expected_sizes)


def _cached_complete_candidate(
    repo_id: str, gguf_filename: Optional[str], shards: list[str]
) -> Optional[tuple[str, str, list[str], Path]]:
    """Return one complete exact-filename cache candidate with snapshot context."""
    if not gguf_filename:
        return None
    if shards:
        main_path = _cached_colocated_split_main(repo_id, gguf_filename, shards, {})
    else:
        m = _SHARD_FULL_RE.match(gguf_filename)
        if m and int(m.group(3)) > 1:
            return None
        main_path = _cached_hf_snapshot_file(repo_id, gguf_filename)
    if main_path is None:
        return None
    snap = _snapshot_dir_of(main_path)
    if snap is None:
        return None
    return main_path, gguf_filename, shards, snap


def cached_gguf_for_load(
    hf_repo: str,
    hf_variant: Optional[str],
    *,
    require_mmproj: bool = False,
    verify_sizes: bool = False,
    hf_token: Optional[str] = None,
    strict: bool = False,
) -> Optional[str]:
    """Return a cached GGUF that can be loaded without downloading (``strict``: and whose
    recorded download is complete, see _cached_variant_candidates)."""
    if not hf_variant:
        return None
    hf_repo = _resolve_repo_id_casing(hf_repo)
    for candidate in _cached_variant_candidates(
        hf_repo,
        hf_variant,
        require_mmproj = require_mmproj,
        strict = strict,
    ):
        if verify_sizes and not _cached_candidate_matches_revision_size(
            hf_repo, candidate, hf_token
        ):
            continue
        return candidate[0]
    return None


def _snapshot_dir_of(path: str) -> Optional[Path]:
    """Return the HF cache snapshot containing path, if any."""
    try:
        p = Path(os.path.abspath(path))
    except OSError:
        return None
    for ancestor in p.parents:
        if ancestor.parent.name == "snapshots":
            return ancestor
    return None


def _hub_cache_dir_for_snapshot_path(path: Optional[str]) -> Optional[str]:
    """Return the HF Hub cache root that owns a snapshot-contained path."""
    if not path:
        return None
    snapshot = _snapshot_dir_of(path)
    if snapshot is None or snapshot.parent.name != "snapshots":
        return None
    return str(snapshot.parent.parent.parent)


def _companion_snapshot_sibling(
    near_path: str, pick: Callable[[list[str]], Optional[str]]
) -> Optional[str]:
    """Find a companion in the same snapshot as near_path."""
    snap = _snapshot_dir_of(near_path)
    if snap is None:
        return None
    try:
        sibling = pick(_gguf_snapshot_files(snap))
    except Exception:
        return None
    if not sibling:
        return None
    candidate = snap / sibling
    if not candidate.is_file():
        return None
    # Split companion is usable only as a whole set: llama-server resolves siblings from its directory, so shard 1 alone is not a reuse.
    from utils.models.model_config import _drafter_split_is_complete

    return str(candidate) if _drafter_split_is_complete(candidate) else None


def _pick_dspark(candidates: list[str]) -> Optional[str]:
    """The DSpark drafter a listing offers, or None. Module level for the same reason
    ``_pick_mmproj`` is: both are handed a live repo listing as well as a snapshot."""
    from hub.utils.gguf import drop_shadowed_appledouble_names
    from utils.models.model_config import dspark_preference_key

    # Every GGUF under dspark/ qualifies, so a sidecar ranks equal to its sibling and sorts first.
    files = sorted(
        (
            name
            for name in drop_shadowed_appledouble_names(list(candidates))
            if _is_dspark_drafter_path(name)
        ),
        key = dspark_preference_key,
    )
    return files[0] if files else None


_MTP_SHARD_SUFFIX_RE = re.compile(r"-[0-9]{5}-of-[0-9]{5}$")


def _is_published_mtp_drafter_name(path: str) -> bool:
    """Basename only, since any MTP/ file is too broad to launch. Names mtp-<model> or <model>-MTP, with any shard suffix stripped first."""
    lower = Path(path).name.lower()
    if not lower.endswith(".gguf"):
        return False
    stem = _MTP_SHARD_SUFFIX_RE.sub("", Path(lower).stem)
    return lower.startswith("mtp-") or stem.endswith("-mtp")


def _mtp_head_borrows(path: str) -> bool:
    """Is this the published ``-shared-`` form, which loads only under its target?"""
    return "-shared-" in Path(path).name.lower()


def _pick_mtp(candidates: list[str], *, allow_nested: bool = True) -> Optional[str]:
    """The MTP drafter a listing offers, or None; module level so /kv-cache-estimate prices the drafter the launch opens. allow_nested=False: root only."""
    from hub.utils.gguf import drop_shadowed_appledouble_names
    from utils.models.drafters import split_listing_is_complete
    from utils.models.drafters.preference import mtp_preference_key

    names = drop_shadowed_appledouble_names(list(candidates))

    def _launchable(name: str) -> bool:
        # Half a split set is unusable, so settle completeness before ranking, or an incomplete head shadows a complete lower-ranked one.
        return split_listing_is_complete(names, name)

    # Root first, so a root mirror (Gemma 4) beats a subdir copy; the mtp- prefix already excludes AppleDouble ._mtp shadows, so no filter is needed.
    mtp_files = sorted(
        f
        for f in names
        if f.lower().endswith(".gguf")
        and "/" not in f
        and Path(f).name.lower().startswith("mtp-")
        and _launchable(f)
    )
    if mtp_files:
        return mtp_files[0]

    # Fall back to MTP/, where Qwen3.8-Flash-Next publishes heads (matches the offline cache).
    if not allow_nested:
        return None
    nested = sorted(
        (
            name
            for name in names
            if "/" in name and _is_published_mtp_drafter_name(name) and _launchable(name)
        ),
        key = mtp_preference_key,
    )
    return nested[0] if nested else None


def _pick_mtp_root_only(candidates: list[str]) -> Optional[str]:
    """Root mirror only: a passed sidecar displaces the embedded head, so a nested copy buys nothing."""
    return _pick_mtp(candidates, allow_nested = False)


def _mtp_drafter_loads_standalone(path: str) -> bool:
    """A --model-draft file must have the embeddings it needs to load; the rule lives in gguf_metadata so the memory estimate shares its cache."""
    from utils.models.gguf_metadata import mtp_drafter_loads_standalone
    return mtp_drafter_loads_standalone(path)


def _pick_mmproj(
    candidates: list[str],
    *,
    order: Optional[tuple] = None,
    weight: Optional[str] = None,
) -> Optional[str]:
    from hub.utils.gguf import drop_shadowed_appledouble_names

    # "._mmproj-F16.gguf" satisfies the F16 preference and sorts ahead of the real adapter.
    candidates = drop_shadowed_appledouble_names(list(candidates))
    mmproj_files = sorted(
        f for f in candidates if f.lower().endswith(".gguf") and "mmproj" in Path(f).name.lower()
    )
    if not mmproj_files:
        return None
    if order:
        from utils.models.model_config import mmproj_order_rank, mmproj_weight_match

        # Pair with the weight first, so a repo of several checkpoints never hands over another one's projector.
        return max(
            mmproj_files,
            key = lambda f: (mmproj_weight_match(weight, f), mmproj_order_rank(f, order)),
        )
    return next((f for f in mmproj_files if f.lower().endswith("-f16.gguf")), mmproj_files[0])


def _mmproj_picker(
    model: Optional[str], weight_path: Optional[str] = None
) -> Callable[[list[str]], Optional[str]]:
    from utils.models.model_config import mmproj_order

    order = mmproj_order(model, weight_path)
    if not order:
        return _pick_mmproj
    weight = Path(weight_path).name if weight_path else None
    return functools.partial(_pick_mmproj, order = order, weight = weight)


def _hub_download_in_flight(hf_repo: str) -> bool:
    try:
        from hub.utils.download_registry import get_models_registry
        return bool(get_models_registry().active_job_refs(hf_repo))
    except Exception:
        return False


def _hub_download_blocks_gguf_load(
    hf_repo: str,
    hf_variant: Optional[str],
    *,
    require_mmproj: bool = False,
    hf_token: Optional[str] = None,
) -> bool:
    """A same-variant Hub job always blocks (it can reclaim the snapshot this load reuses); other jobs block only with no complete cached copy."""
    try:
        from hub.utils.download_registry import get_models_registry

        registry = get_models_registry()
        if not registry.active_job_refs(hf_repo):
            return False
        if registry.has_active_variant(hf_repo, hf_variant):
            return True
    except Exception:
        return False
    return (
        cached_gguf_for_load(
            hf_repo,
            hf_variant,
            require_mmproj = require_mmproj,
            verify_sizes = True,
            hf_token = hf_token,
        )
        is None
    )


# Active GGUF loads by normalized repo ID.
_LOADS_IN_FLIGHT: dict[str, int] = {}
_LOADS_IN_FLIGHT_LOCK = threading.Lock()


@contextlib.contextmanager
def gguf_load_in_flight(hf_repo: Optional[str]):
    """Track an HF GGUF load until the context exits."""
    key = (hf_repo or "").strip().lower()
    if not key:
        yield
        return
    with _LOADS_IN_FLIGHT_LOCK:
        _LOADS_IN_FLIGHT[key] = _LOADS_IN_FLIGHT.get(key, 0) + 1
    try:
        yield
    finally:
        with _LOADS_IN_FLIGHT_LOCK:
            remaining = _LOADS_IN_FLIGHT.get(key, 1) - 1
            if remaining <= 0:
                _LOADS_IN_FLIGHT.pop(key, None)
            else:
                _LOADS_IN_FLIGHT[key] = remaining


# Chat loads in flight, repo-agnostic (local paths and safetensors included). The repo-keyed counter above answers the download manager; this one answers the GPU arbiter, which must know before llama-server spawns.
_CHAT_LOADS_IN_FLIGHT = 0


@contextlib.contextmanager
def chat_load_in_flight():
    """Track a chat load from before its download until the load call returns."""
    global _CHAT_LOADS_IN_FLIGHT
    with _LOADS_IN_FLIGHT_LOCK:
        _CHAT_LOADS_IN_FLIGHT += 1
    try:
        yield
    finally:
        with _LOADS_IN_FLIGHT_LOCK:
            _CHAT_LOADS_IN_FLIGHT = max(0, _CHAT_LOADS_IN_FLIGHT - 1)


def chat_load_active() -> bool:
    """Whether any chat load is in flight, spawned or not; is_active misses loads still downloading."""
    with _LOADS_IN_FLIGHT_LOCK:
        return _CHAT_LOADS_IN_FLIGHT > 0


def zero_vram_chat_load(
    gpu_memory_mode: str,
    gpu_layers: int,
    extra_args: Optional[list] = None,
    needs_mmproj: bool = False,
    speculative_type: Optional[str] = None,
) -> bool:
    """Mirrors the launch GPU mask so a CPU-only load does not evict an image or video pipeline; mmproj and drafter intent are passed in."""
    if gpu_memory_mode != "manual" or gpu_layers != 0:
        return False
    # Every spec mode but off may launch a GPU drafter: canonicalize first, and an absent mode is auto, not off, or the arbiter is skipped.
    # -- reading the FINISHED argv, drafter included -- kept the GPUs visible: no
    spec_mode = _canonicalize_spec_mode(speculative_type) or "auto"
    if needs_mmproj or spec_mode != "off":
        return False
    if LlamaCppBackend._is_vulkan_backend():
        return False
    return not LlamaCppBackend._zero_offload_keeps_gpu_visible(
        [str(arg) for arg in (extra_args or [])], os.environ
    )


def hf_gguf_load_in_flight(hf_repo: str) -> bool:
    """Return whether a GGUF load is active for hf_repo."""
    key = (hf_repo or "").strip().lower()
    if not key:
        return False
    with _LOADS_IN_FLIGHT_LOCK:
        return _LOADS_IN_FLIGHT.get(key, 0) > 0


def _with_gguf_load_marker(load: Callable):
    """Keep an HF repo marked for the full synchronous load call."""

    @functools.wraps(load)
    def wrapped(
        self,
        intent: GgufLoadIntent,
        load_cancel_event: Optional[threading.Event] = None,
    ):
        hf_repo = intent.hf_repo
        # Must not leak: polling outside a load needs LIVE VRAM, never this snapshot.
        with _load_probe_memo_scope(), gguf_load_in_flight(hf_repo):
            if hf_repo and _hub_download_blocks_gguf_load(
                hf_repo,
                intent.hf_variant,
                # Must mirror the download gate below exactly, or a vision-off load races a download job.
                require_mmproj = bool(
                    intent.is_vision and not extra_args_disable_mmproj(intent.extra_args)
                ),
                hf_token = intent.hf_token,
            ):
                raise RuntimeError(
                    f"'{hf_repo}' is currently being downloaded by the download manager"
                )
            return load(self, intent, load_cancel_event = load_cancel_event)

    return wrapped


def _drafter_set_bytes(sizes: Mapping[str, int], name: str) -> int:
    """Total listed bytes of ``name``'s whole shard set (its own size when single)."""
    return (sizes.get(name, 0) or 0) + sum(
        sizes.get(shard, 0) or 0 for shard in _gguf_extra_shards(sizes, name)
    )


def _gguf_extra_shards(files: Iterable[str], first_shard: str) -> list[str]:
    m = _SHARD_FULL_RE.match(first_shard)
    if not m:
        return []
    prefix = m.group(1)
    total = m.group(3)
    sibling_pat = re.compile(
        r"^" + re.escape(prefix) + r"-\d{5}-of-" + re.escape(total) + r"\.gguf$",
        re.IGNORECASE,
    )
    return sorted(f for f in files if f != first_shard and sibling_pat.match(f))


def _quant_label_for_endian(path: str) -> Optional[str]:
    """With no label the caller keeps its previous argument, so the endian test is never dropped."""
    try:
        from hub.utils.gguf import extract_quant_token
        return extract_quant_token(path)
    except Exception:  # noqa: BLE001 -- an unreadable label must not sink the resolution
        return None


def _gguf_files_for_variant(files: Iterable[str], variant: str) -> list[str]:
    """Exact quant-label matches win over substrings, so stories260K does not match stories260K-be.gguf."""
    from hub.utils.gguf import drop_shadowed_appledouble_names

    variant_key = variant.strip().lower()
    # A repo listing has no bytes to read; a local one arrives already filtered on its headers.
    main_files = [
        f
        for f in drop_shadowed_appledouble_names(list(files))
        if f.lower().endswith(".gguf")
        and not _is_companion_gguf_path(f)
        # Pass the file's own quant label: a path-qualified key misreads -be.gguf as big-endian.
        and not _is_big_endian_gguf_path(f, _quant_label_for_endian(f) or variant_key)
    ]
    if not variant_key:
        return sorted(main_files)

    try:
        from utils.models.model_config import _extract_quant_label, _gguf_variant_key
    except Exception:
        _extract_quant_label = None
        _gguf_variant_key = None

    if _gguf_variant_key is not None:
        try:
            # Variant's own files first: mixing checkpoints makes llama-server read the wrong shards.
            owned = sorted(f for f in main_files if _gguf_variant_key(f).lower() == variant_key)
            if owned:
                return owned
        except Exception as e:
            logger.warning("Failed to derive GGUF variant keys: %s", e)

    if _extract_quant_label is not None:
        try:
            exact = sorted(f for f in main_files if _extract_quant_label(f).lower() == variant_key)
            if exact:
                return exact
        except Exception as e:
            logger.warning("Failed to extract GGUF quant labels: %s", e)

    boundary = re.compile(r"(?<![a-zA-Z0-9])" + re.escape(variant_key) + r"(?![a-zA-Z0-9])")
    return sorted(f for f in main_files if boundary.search(f.lower()))


def _resolve_variant_gguf_files(
    hf_repo: str,
    hf_variant: Optional[str],
    hf_token: Optional[str] = None,
) -> tuple[Optional[str], list[str]]:
    """Module level so the header probe and the download resolve the same file; two copies would drift."""
    gguf_filename: Optional[str] = None
    gguf_extra_shards: list[str] = []
    if not hf_variant:
        return None, []
    try:
        from huggingface_hub import list_repo_files

        files = call_hub_with_anonymous_retry(list_repo_files, hf_token, hf_repo)
        gguf_files = _gguf_files_for_variant(files, hf_variant)
        if gguf_files:
            gguf_filename = gguf_files[0]
            gguf_extra_shards = _gguf_extra_shards(gguf_files, gguf_filename)
    except Exception as e:
        logger.warning(f"Could not list repo files: {e}")

    # Fall back to the local cache when the repo listing is unavailable.
    if not gguf_filename:
        cached_name, cached_shards = _cached_variant_resolution(hf_repo, hf_variant)
        if cached_name:
            gguf_filename = cached_name
            gguf_extra_shards = cached_shards
            logger.info(
                "Resolved variant %s -> %s from local HF cache",
                hf_variant,
                gguf_filename,
            )

    if not gguf_filename:
        repo_name = hf_repo.split("/")[-1].replace("-GGUF", "")
        gguf_filename = f"{repo_name}-{hf_variant}.gguf"
    return gguf_filename, gguf_extra_shards


# Below this, draft-mtp regresses vs spec-off; auto mode drops MTP under it.
_MTP_MIN_SIZE_B = 3.0

# Cap GPU occupancy at 97%; the 3% covers fragmentation, per-device CUDA context and MoE routing, not the modelled compute buffer.
_CTX_FIT_VRAM_FRACTION = 0.97

# Apple unified memory is shared with the OS, so tighter than VRAM; matches the 0.85 in mlx_inference.py but is not kept in sync.
_APPLE_UNIFIED_MEMORY_FRACTION = 0.85

# The 5% of wired headroom held back absorbs error in the footprint estimate.
_APPLE_WIRED_CEILING_FRACTION = 0.95

# 8192 floor (llama.cpp 4096 is too short for chat); a result at the search floor is that floor, not a measurement; Metal re-prices from _FIT_FLOOR_MIN_CTX.
_FIT_MIN_CTX = 8192
_FIT_FLOOR_MIN_CTX = 256

# llama.cpp's own --fit floor; without the fitter running, hand over this, not 8192.
_LLAMA_FIT_MIN_CTX = 4096

# _plan_tensor_parallel's no-KV fallback. A GUESS: may shrink Auto, never a request (#9653).
_TP_UNMEASURED_CTX = 4096

# Auto offload context when no GPU subset holds the model; prefers a chat-useful size, kept separate from _FIT_MIN_CTX (search and Apple floor).
_AUTO_OFFLOAD_CTX = 8192

# Must stay >= fit search floor or the Auto re-check flips --fit off (test pins it). amd-smi vs HIP VRAM totals differing over 10% are different scopes.
_AMD_SMI_TOTAL_TOLERANCE = 0.10

# Flat MTP reserve, used only when GGUF dims are too sparse for _estimate_mtp_overhead_bytes; applied to both the fit budget and the pin.
_MTP_VRAM_RESERVE_FRAC = 0.05


# Left on every card even at 100%, matching the --fit-target margin llama.cpp
# keeps for its own fitter.
_VRAM_FLOOR_RESERVE_MIB = 512.0

# llama-server's own --fit-target default ("target margin per device for --fit,
# ... default: 1024"): what the fallback fitter leaves when we pass nothing.
_LLAMA_FIT_TARGET_DEFAULT_MIB = 1024.0

# Windows + NVIDIA since driver 536.40: WDDM spills VRAM overflow to host RAM instead of failing, so the reserve matches llama.cpp fit margin.
_WINDOWS_SYSMEM_FALLBACK_RESERVE_MIB = _LLAMA_FIT_TARGET_DEFAULT_MIB
_WINDOWS_SYSMEM_FALLBACK_MAX_FRACTION = 0.125


def _vram_reserve_floor_mib(total_mib: float, *, sysmem_fallback: bool = False) -> float:
    """Floor 512 MiB, capped at the default reserve to keep the budget monotonic; sysmem_fallback raises it and deliberately overrides a 100% budget."""
    floor = min(_VRAM_FLOOR_RESERVE_MIB, (1.0 - _CTX_FIT_VRAM_FRACTION) * total_mib)
    if not sysmem_fallback:
        return floor
    return max(
        floor,
        min(
            _WINDOWS_SYSMEM_FALLBACK_RESERVE_MIB,
            _WINDOWS_SYSMEM_FALLBACK_MAX_FRACTION * total_mib,
        ),
    )


def _vram_usable_mib(
    free_mib: float,
    total_mib: float,
    frac: float,
    *,
    pooled: bool = False,
    sysmem_fallback: bool = False,
) -> float:
    """Pooled budgets already paid every card reserve, so do not charge it again; a probe with no total still keeps a margin."""
    if total_mib and total_mib > 0:
        reserve = max(
            (1.0 - frac) * total_mib,
            _vram_reserve_floor_mib(total_mib, sysmem_fallback = sysmem_fallback),
        )
        return free_mib - reserve
    if pooled:
        return free_mib * frac
    return min(
        free_mib * frac,
        free_mib - _vram_reserve_floor_mib(free_mib, sysmem_fallback = sysmem_fallback),
    )


def _model_memory_settings_or_none() -> Optional[tuple[bool, bool]]:
    try:
        from utils.model_memory_settings import get_model_memory_settings
        return get_model_memory_settings()
    except Exception:
        return None


def _active_vram_fraction() -> float:
    """User VRAM budget, or _CTX_FIT_VRAM_FRACTION if unset; settings clamp it so no NaN or past 1.0. Read per call, so no restart is needed."""
    try:
        from utils.vram_budget_settings import get_vram_budget_fraction
        return get_vram_budget_fraction()
    except Exception:
        # Settings are a convenience; a load must never fail because of them.
        return _CTX_FIT_VRAM_FRACTION


def _kv_bytes_per_elem(cache_type: Optional[str]) -> float:
    """Bytes per KV-cache element for a llama.cpp cache type (f16 default)."""
    return {
        "f32": 4.0,
        "f16": 2.0,
        "bf16": 2.0,
        "q8_0": 34 / 32,
        "q5_1": 0.75,
        "q5_0": 0.6875,
        "q4_1": 0.625,
        "q4_0": 0.5625,
        "iq4_nl": 0.5625,
    }.get((cache_type or "f16").strip().lower(), 2.0)


# Not a CUDA/HIP FlashAttention KV type (ggml_cuda_fattn_kv_type_supported), so attention runs
# on the CPU. q4_1 / q5_0 / q5_1 did too until ggml-org/llama.cpp#28079 added an f16 fallback.
# Mapped to a same-size type that has the kernel, so the KV budget is unchanged (#10336).
_GPU_UNACCELERATED_CACHE_TYPES = {"iq4_nl": "q4_0"}


def _kv_cache_gpu_fallback_warning(
    cache_type_kv: Optional[str],
    gpu_memory_mode: str,
    gpu_layers: int,
    installed_backends: Callable[[], frozenset[str]],
) -> Optional[str]:
    """Warning for a KV cache type that runs attention on the CPU of a CUDA/HIP launch."""
    if cache_type_kv not in _GPU_UNACCELERATED_CACHE_TYPES:
        return None
    if gpu_memory_mode == "manual" and gpu_layers == 0:
        return None
    if not {"cuda", "hip"} & installed_backends():
        return None
    return (
        f"KV cache type {cache_type_kv} has no CUDA/HIP flash-attention kernel, so attention "
        "would fall back to CPU, causing high CPU load and slow generation. Using "
        f"{_GPU_UNACCELERATED_CACHE_TYPES[cache_type_kv]} instead, the same size on the GPU."
    )


# Upper bound on any current tokenizer vocab (output rows) when a truncated header drops the token array; above the 256k of Llama 4 and Gemma 3.
_ASSUMED_MAX_VOCAB = 262144
# Ceiling on float32 activations per micro-batch token for an unreadable header: 4 * n_ff at n_ff = 65536, above the Llama 3.1 405B figure of 53056.
_ASSUMED_MAX_ACTIVATION_WIDTH = 262144


def _pad_kv_cells(cells: int) -> int:
    return ((cells + 255) // 256) * 256


def _kv_cache_cell_layout(n_ctx: int, n_parallel: int, kv_unified: bool) -> tuple[int, int, int]:
    """Return llama.cpp's slot count, stream count, and cells per stream."""
    slots = max(1, n_parallel)
    padded_ctx = _pad_kv_cells(n_ctx)
    streams = 1 if kv_unified else slots
    if padded_ctx <= 0:
        return slots, streams, 0
    cells_per_stream = padded_ctx if kv_unified else _pad_kv_cells(padded_ctx // slots)
    return slots, streams, cells_per_stream


def _env_main_cache_type_for_budget(env: Optional[Mapping[str, str]] = None) -> Optional[str]:
    """Heavier of LLAMA_ARG_CACHE_TYPE_K/_V when not f16, budgeted because the child gets it unbudgeted (f32 under-reserves, quantized skips scratch)."""
    e = os.environ if env is None else env
    # An unset axis is llama.cpp f16 and joins the max; dropping it lets a lone q4_0 V price K as q4 while the child runs f16, under-reserving.
    axis_types = [
        (e.get(var) or "").strip().lower() or "f16"
        for var in ("LLAMA_ARG_CACHE_TYPE_K", "LLAMA_ARG_CACHE_TYPE_V")
    ]
    if all(t == "f16" for t in axis_types):
        return None
    heaviest = max(axis_types, key = _kv_bytes_per_elem)
    if _kv_bytes_per_elem(heaviest) == _kv_bytes_per_elem("f16"):
        return None
    return heaviest


def _extra_args_main_cache_type_for_budget(extra_args: Optional[Iterable[str]]) -> Optional[str]:
    """Budget by the heavier axis: resolve_cache_type_kv keeps the last-wins type and under-reserves."""
    k, v = parse_cache_override_per_axis(extra_args)
    candidates = [c for c in (k, v) if c]
    if not candidates:
        return None
    return max(candidates, key = _kv_bytes_per_elem)


def _effective_main_cache_types(
    args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> tuple[str, str]:
    """Effective main K/V cache types after environment and CLI precedence."""
    source_env = os.environ if env is None else env
    env_k = (source_env.get("LLAMA_ARG_CACHE_TYPE_K") or "f16").strip().lower()
    env_v = (source_env.get("LLAMA_ARG_CACHE_TYPE_V") or "f16").strip().lower()
    arg_k, arg_v = parse_cache_override_per_axis(args)
    return (
        (arg_k or env_k).strip().lower(),
        (arg_v or env_v).strip().lower(),
    )


def _planned_main_cache_types(
    cache_type_kv: Optional[str],
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
) -> tuple[str, str]:
    """Main K/V types the loader's managed flags and user extras will produce."""
    args = list(extra_args or ())
    emitted_type = _extra_args_main_cache_type_for_budget(args) or cache_type_kv
    if emitted_type:
        args = [
            "--cache-type-k",
            emitted_type,
            "--cache-type-v",
            emitted_type,
            *args,
        ]
    return _effective_main_cache_types(args, env)


# What kv_cache_type_from_str accepts; module scope so the budget can check it early.
_VALID_CACHE_TYPES = frozenset(
    {"f16", "bf16", "q8_0", "q4_0", "q4_1", "q5_0", "q5_1", "iq4_nl", "f32"}
)


def _planned_scratch_cache_type(
    cache_type_kv: Optional[str],
    extra_args: Optional[Iterable[str]] = None,
    env: Optional[Mapping[str, str]] = None,
) -> str:
    """Scratch is charged only under f16, so take the LIGHTER axis: the heavier one hides a quantized K behind f16 and silently drops the scratch."""
    return min(_planned_main_cache_types(cache_type_kv, extra_args, env), key = _kv_bytes_per_elem)


def _auto_mode_drops_mtp(
    req_mode: Optional[str],
    size_b: Optional[float],
    *,
    has_separate_drafter: bool = False,
) -> bool:
    """Embedded MTP regresses below _MTP_MIN_SIZE_B, so Auto drops it; a separate drafter is kept."""
    if has_separate_drafter:
        return False
    return req_mode == "auto" and size_b is not None and size_b < _MTP_MIN_SIZE_B


# glm5next (upstream glm5-next): MTP covers only the NextN block, so Auto keeps MTP and the fit reserves no copy; old builds retry without speculation.
_MLA_MTP_FAST_ARCHS = frozenset({"glm5next", "glm5-next"})
# Smallest context Auto shrinks to so a fast MLA head still launches.
_FAST_MTP_MIN_CTX = 65536
# Max share of the target-only Auto context a drafter may take at one slot.
_MTP_SLOT_CTX_TRIM = 0.10


def _arch_has_fast_mla_mtp(architecture: Optional[str]) -> bool:
    """Whether this MLA architecture's embedded MTP head is worth promoting in Auto."""
    return bool(architecture) and str(architecture).strip().lower() in _MLA_MTP_FAST_ARCHS


def _arch_mtp_skips_target_kv_copy(architecture: Optional[str]) -> bool:
    """Whether this MLA architecture's MTP context skips the duplicated target KV."""
    return _arch_has_fast_mla_mtp(architecture)


def _mla_mtp_auto_enabled() -> bool:
    """Off by default: MLA MTP runs ~2x slower than no speculation (duplicated KV, indexer recomputed); UNSLOTH_MLA_MTP_ENABLED=1 enables; forced modes ignore it."""
    return os.environ.get("UNSLOTH_MLA_MTP_ENABLED", "0").strip().lower() in (
        "1",
        "true",
        "yes",
        "on",
    )


def _extra_args_set_spec_type(extra_args: Optional[Iterable[str]]) -> bool:
    """User passed --spec-type / --spec-default? llama-server takes one
    --spec-type (comma-separated to chain), so suppress auto-emit."""
    return _extra_args_set_any_flag(extra_args, {"--spec-type", "--spec-default"})


# Shared with llama_server_args so detection and stripping cannot drift.
_GPU_OFFLOAD_OVERRIDE_FLAGS = _LAYER_OFFLOAD_FLAGS
# Extras keeping weights on CPU regardless of -ngl; -ncmoe 0 places nothing, so it is parsed.
_CPU_MOE_COUNT_FLAGS = frozenset({"-ncmoe", "--n-cpu-moe"})
# Dense twin of -ncmoe: a positive -ncffn moves the first N layers' FFN to CPU.
_CPU_FFN_COUNT_FLAGS = frozenset({"-ncffn", "--n-cpu-ffn"})
# User controls over llama.cpp's own fitter. Studio emits neither on Metal, so a launch carrying
# one is placed by a fitter the Metal memory probe did not run.
_FIT_CTX_FLAGS = frozenset({"-fitc", "--fit-ctx"})
_FIT_CONTROL_FLAGS = frozenset({"-fitt", "--fit-target"}) | _FIT_CTX_FLAGS
_FIT_CONTROL_ENV_VARS = ("LLAMA_ARG_FIT_TARGET", "LLAMA_ARG_FIT_CTX")
_CPU_PLACEMENT_PRESENCE_FLAGS = (_MOE_OFFLOAD_FLAGS - _CPU_MOE_COUNT_FLAGS) | frozenset(
    {"-ot", "--override-tensor"}
)
_CPU_PLACEMENT_FLAGS = _MOE_OFFLOAD_FLAGS | frozenset({"-ot", "--override-tensor"})
# Pass-through that re-places what a fit priced: the fitter, split, remote (RPC) devices,
# draft tensors moved onto a card of their own, or an unpriced vocoder GGUF.
_VRAM_FIT_VOIDING_FLAGS = (
    frozenset(
        {
            "-fit",
            "--fit",
            "--rpc",
            "-otd",
            "--override-tensor-draft",
            "--spec-draft-override-tensor",
            "-mv",
            "--model-vocoder",
        }
    )
    | _FIT_CONTROL_FLAGS
    | _TENSOR_SPLIT_FLAGS
    | _SPLIT_MODE_FLAGS
)
_VRAM_FIT_VOIDING_ENV_VARS = (
    "LLAMA_ARG_FIT",
    "LLAMA_ARG_RPC",
    *_FIT_CONTROL_ENV_VARS,
    "LLAMA_ARG_TENSOR_SPLIT",
    "LLAMA_ARG_SPLIT_MODE",
)
_THREAD_OVERRIDE_FLAGS = frozenset({"-t", "--threads"})
_GENERATION_CPU_AFFINITY_FLAGS = frozenset({"-C", "--cpu-mask", "-Cr", "--cpu-range"})
_TENSOR_SPLIT_FLAGS = frozenset({"--tensor-split", "-ts"})


def _linux_math_core_count(
    cpu_root: Path = Path("/sys/devices/system/cpu"),
    logical_cpus: Optional[int] = None,
    vendor_id: Optional[str] = None,
    event_source_root: Path = Path("/sys/bus/event_source/devices"),
    pinnable_cpus: Optional[set[int]] = None,
    probe_affinity: Optional[bool] = None,
) -> Optional[int]:
    """Physical cores as llama.cpp counts them: SMT siblings dropped; hybrid Intel keeps only P-cores; AMD capacity classes keep every physical core."""
    if logical_cpus is not None and logical_cpus < 1:
        return None

    def cpu_list(path: Path) -> Optional[set[int]]:
        try:
            raw = path.read_text(encoding = "utf-8").strip()
            if not raw:
                return set()
            result: set[int] = set()
            for part in raw.split(","):
                bounds = [int(value) for value in part.split("-")]
                if len(bounds) == 1 and bounds[0] >= 0:
                    result.add(bounds[0])
                elif len(bounds) == 2 and 0 <= bounds[0] <= bounds[1]:
                    result.update(range(bounds[0], bounds[1] + 1))
                else:
                    return None
            return result
        except (OSError, ValueError):
            return None

    if vendor_id is None:
        try:
            vendor_match = re.search(
                r"^vendor_id\s*:\s*(\S+)",
                Path("/proc/cpuinfo").read_text(encoding = "utf-8"),
                flags = re.MULTILINE,
            )
            vendor_id = vendor_match.group(1) if vendor_match else ""
        except OSError:
            vendor_id = ""
    siblings: list[str] = []
    capacities: list[Optional[int]] = []
    cpu = 0
    while logical_cpus is None or cpu < logical_cpus:
        cpu_path = cpu_root / f"cpu{cpu}"
        try:
            sibling_set = (
                (cpu_path / "topology" / "thread_siblings").read_text(encoding = "utf-8").strip()
            )
        except OSError:
            break
        if not sibling_set:
            break
        siblings.append(sibling_set)
        try:
            capacities.append(int((cpu_path / "cpu_capacity").read_text(encoding = "utf-8").strip()))
        except (OSError, ValueError):
            capacities.append(None)
        cpu += 1
    if not siblings:
        return None
    online_cpus = cpu_list(cpu_root / "online")
    active_siblings = {
        sibling_set
        for cpu, sibling_set in enumerate(siblings)
        if not online_cpus or cpu in online_cpus
    }
    if not active_siblings:
        return None
    physical_count = len(active_siblings)
    if vendor_id == "GenuineIntel":
        native_count = len(online_cpus) if online_cpus else len(siblings)

        def hybrid_math_count(performance_cpus: set[int]) -> int:
            should_probe = pinnable_cpus is None and (
                cpu_root == Path("/sys/devices/system/cpu")
                if probe_affinity is None
                else probe_affinity
            )

            def count(pin_cpus: bool) -> int:
                result = 0
                cpu = 0
                while cpu < native_count:
                    if online_cpus and cpu not in online_cpus:
                        return physical_count
                    if pinnable_cpus is not None and cpu not in pinnable_cpus:
                        return physical_count
                    if pin_cpus:
                        try:
                            os.sched_setaffinity(0, {cpu})
                        except OSError:
                            return physical_count
                    if cpu not in performance_cpus:
                        cpu += 1
                        continue
                    result += 1
                    cpu += 2
                return result or physical_count

            if not should_probe:
                return count(False)
            if not hasattr(os, "sched_getaffinity") or not hasattr(os, "sched_setaffinity"):
                return physical_count

            answer = [physical_count]

            def probe() -> None:
                try:
                    saved_affinity = os.sched_getaffinity(0)
                except OSError:
                    return
                try:
                    answer[0] = count(True)
                finally:
                    try:
                        os.sched_setaffinity(0, saved_affinity)
                    except OSError:
                        pass

            worker = threading.Thread(target = probe)
            try:
                worker.start()
                worker.join()
            except RuntimeError:
                return physical_count
            return answer[0]

        core_mask = cpu_list(event_source_root / "cpu_core" / "cpus")
        atom_path = event_source_root / "cpu_atom"
        lowpower_path = event_source_root / "cpu_lowpower"
        hybrid_pmu = atom_path.exists() or lowpower_path.exists()
        if core_mask:
            return hybrid_math_count(core_mask)
        if hybrid_pmu:
            atom_mask = cpu_list(atom_path / "cpus") or cpu_list(lowpower_path / "cpus")
            if core_mask == set() and atom_mask:
                return physical_count
            return 1
        active_capacities = [
            capacity
            for cpu, capacity in enumerate(capacities)
            if not online_cpus or cpu in online_cpus
        ]
        if (
            all(capacity is not None for capacity in active_capacities)
            and len(set(active_capacities)) > 1
        ):
            fastest = max(capacity for capacity in active_capacities if capacity is not None)
            return hybrid_math_count(
                {
                    cpu
                    for cpu, capacity in enumerate(capacities)
                    if (not online_cpus or cpu in online_cpus) and capacity == fastest
                }
            )
    return physical_count


def _spilled_decode_threads(
    n_threads: Optional[int] = None, extra_args: Optional[Iterable[str]] = None
) -> Optional[int]:
    """Physical cores as llama.cpp counts them, not os.cpu_count; inherited LLAMA_ARG_THREADS is ignored; explicit affinity or SMT oversubscription returns None."""
    requested: Optional[int] = None
    if n_threads is not None and n_threads > 0:
        requested = int(n_threads)
    args = [str(arg) for arg in extra_args] if extra_args else []
    if any(arg.partition("=")[0] in _GENERATION_CPU_AFFINITY_FLAGS for arg in args):
        return None
    for i, arg in enumerate(args):
        name, _, inline = arg.partition("=")
        if name not in _THREAD_OVERRIDE_FLAGS:
            continue
        value = inline if inline else (args[i + 1] if i + 1 < len(args) else "")
        try:
            requested = int(value.strip())
        except (TypeError, ValueError):
            continue
    physical: Optional[int] = None
    logical: Optional[int] = None
    affinity_count: Optional[int] = None
    if sys.platform.startswith("linux"):
        if hasattr(os, "sched_getaffinity"):
            try:
                affinity_count = len(os.sched_getaffinity(0))
            except OSError:
                pass
        if os.uname().machine.lower() in ("x86_64", "amd64"):
            physical = _linux_math_core_count()
    try:
        import psutil

        answer = psutil.cpu_count(logical = True)
        if answer and answer > 0:
            logical = int(answer)
        if physical is None:
            answer = psutil.cpu_count(logical = False)
            if answer and answer > 0:
                physical = int(answer)
    except Exception:
        pass
    if logical is None:
        logical = os.cpu_count()
    if affinity_count is not None and logical is not None and affinity_count < logical:
        return None
    if physical is None:
        physical = logical if logical and logical <= 4 else (logical // 2 if logical else 4)
    if requested is None:
        return physical
    actual = requested if requested > 0 else (logical or os.cpu_count() or physical)
    if actual > physical:
        return None
    return max(1, actual)


def _strip_flag_pairs(args: Iterable[str], flags: frozenset[str]) -> list[str]:
    """Drop each ``flag value`` pair naming one of ``flags``."""
    out: list[str] = []
    skip = False
    for arg in args:
        if skip:
            skip = False
            continue
        if str(arg) in flags:
            skip = True
            continue
        out.append(str(arg))
    return out


# common_params defaults in the bundled llama.cpp runtime.
_DEFAULT_LLAMA_N_BATCH = 2048
_DEFAULT_LLAMA_N_UBATCH = 512
# Non-causal image decoding needs one image chunk per micro-batch; limits from clip.cpp.
_MMPROJ_NON_CAUSAL_IMAGE_TOKENS = {
    "gemma4v": 1120,
    "gemma4uv": 1120,
    "gemma3": 256,
    "deepseek4v": 384,
}
# A projector whose family we cannot read gets headroom instead of a ceiling.
_MMPROJ_UNKNOWN_UBATCH = 2048
_GEMMA4V_CAUSAL_TEXT_N_EMBD = frozenset({1536, 2560})  # E2B and E4B
_LLAMA_ARG_TRUE_VALUES = frozenset({"on", "enabled", "true", "1"})
_LLAMA_ARG_FALSE_VALUES = frozenset({"off", "disabled", "false", "0"})
_LLAMA_ARG_AUTO_VALUES = frozenset({"auto", "-1"})
_LLAMA_ARG_TRUE_OR_AUTO_VALUES = _LLAMA_ARG_TRUE_VALUES | _LLAMA_ARG_AUTO_VALUES
_LLAMA_ARG_TRUE_FALSE_AUTO_VALUES = _LLAMA_ARG_TRUE_OR_AUTO_VALUES | _LLAMA_ARG_FALSE_VALUES


def _extra_args_set_any_flag(extra_args: Optional[Iterable[str]], flags: Collection[str]) -> bool:
    if not extra_args:
        return False
    for raw in extra_args:
        flag = _flag_name(str(raw))
        if flag in flags:
            return True
    return False


def _explicit_device_ordinals_needed(extra_args: Optional[Iterable[str]]) -> Optional[int]:
    """Leading child ordinals the user's device flags name (highest ordinal + 1, tensor-split
    length), 0 when no flag names one; None when a value cannot be read or the pick is CPU only.
    argv wins over LLAMA_ARG_*."""
    try:
        device = _last_flag_value(extra_args, frozenset({"--device", "-dev"}))
        main_gpu = _last_flag_value(extra_args, frozenset({"--main-gpu", "-mg"}))
        split = _last_flag_value(extra_args, _TENSOR_SPLIT_FLAGS)
    except ValueError:
        return None
    device = device or str(os.environ.get("LLAMA_ARG_DEVICE", "")).strip() or None
    main_gpu = main_gpu or str(os.environ.get("LLAMA_ARG_MAIN_GPU", "")).strip() or None
    split = split or str(os.environ.get("LLAMA_ARG_TENSOR_SPLIT", "")).strip() or None
    need = 0
    for token in (device or "").split(","):
        token = token.strip()
        if not token:
            continue
        # CPU only ("none", like "cpu"): the child uses no GPU, so no GPU subset may be priced lighter.
        if token.lower() == "none":
            return None
        match = re.fullmatch(r"[A-Za-z]+(\d+)", token)
        if match is None:
            return None
        need = max(need, int(match.group(1)) + 1)
    if main_gpu is not None:
        try:
            need = max(need, int(main_gpu) + 1)
        except ValueError:
            return None
    if split is not None:
        need = max(need, len([part for part in re.split(r"[,/]", split) if part.strip()]))
    return need


def _diffusion_manual_ngl(gpu_memory_mode: str, gpu_layers: int) -> Optional[int]:
    """The --ngl the diffusion runner launches with, set only by an explicit manual count, else None; shared with dedup guards so an inert pref cannot loop."""
    return int(gpu_layers) if (gpu_memory_mode == "manual" and int(gpu_layers) >= 0) else None


def _scale_diffusion_required_gb(required_gb: float, ngl: int, n_layers: Optional[int]) -> float:
    """Only ngl resident layers compete for VRAM, so sizing the whole file 409s a split that fits; an unknown layer count keeps the full estimate."""
    if not n_layers or n_layers <= 0 or ngl >= n_layers:
        return required_gb
    return required_gb * (ngl / n_layers)


# The runner's own CUDA context, which the free reading taken before spawn cannot see.
_DIFFUSION_RUNNER_OVERHEAD_MIB = 512.0
# Context the fitted split leaves room for when the runner auto-sizes (maxtok 0).
_DIFFUSION_FIT_CTX = 4096


def _diffusion_auto_ngl(
    file_bytes: int,
    n_layers: Optional[int],
    n_head: Optional[int],
    maxtok: int,
    free_mib: float,
    total_mib: float,
    *,
    sysmem_fallback: bool = False,
) -> Optional[int]:
    """GPU layers for an Auto-mode diffusion load, or None to keep every layer on the GPU.

    Only a GGUF that cannot fit moves: all layers die in cudaMalloc, or on Windows spill into
    shared system memory until RAM and the page file run out (#6456). The split leaves room
    for the compute buffer (measured 1.75x the [n_head, N, N] fp32 scores) and the 8% of VRAM
    the runner's context probe keeps free (diffusion-gemma-visual-server.cpp)."""
    if not file_bytes or not n_layers or n_layers <= 0 or (free_mib <= 0 and total_mib <= 0):
        return None
    usable = _vram_usable_mib(
        free_mib, total_mib, _active_vram_fraction(), sysmem_fallback = sysmem_fallback
    )
    usable -= _DIFFUSION_RUNNER_OVERHEAD_MIB
    file_mib = file_bytes / (1024 * 1024)
    if file_mib <= usable:
        return None
    # Mirrors unsloth_zoo's _canvas_maxtok: larger requests are sent as 0 (auto-size).
    n_ctx = maxtok if 0 < maxtok <= 8192 else _DIFFUSION_FIT_CTX
    scores_mib = max(1, n_head or 1) * n_ctx * n_ctx * 4 / (1024 * 1024)
    ctx_reserve = 1.75 * scores_mib + 0.08 * (total_mib if total_mib > 0 else free_mib)
    # The whole file over the block count also charges token_embd, which stays on the CPU.
    per_layer_mib = file_mib / n_layers
    return max(0, min(n_layers - 1, int((usable - ctx_reserve) // per_layer_mib)))


def _source_declares_option(source: str, option: str) -> bool:
    """Parsed with ast, not grepped (substring hits comments, misses quoted flags); falls back to a substring scan when the file will not parse."""
    try:
        tree = ast.parse(source)
    except (SyntaxError, ValueError):
        return option in source
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if not (isinstance(func, ast.Attribute) and func.attr == "add_argument"):
            continue
        for arg in node.args:
            if isinstance(arg, ast.Constant) and arg.value == option:
                return True
    return False


def _shim_supports_ngl(shim_cmd: List[str]) -> bool:
    """Reads the source, not a spawned probe; an unsloth_zoo lacking --ngl makes argparse exit."""
    # Key on the command shape, not the suffix, and probe that exact override file.
    if len(shim_cmd) >= 2 and "-m" not in shim_cmd:
        candidates = [Path(shim_cmd[-1])]
    else:
        candidates = []
        try:
            import importlib.util
            spec = importlib.util.find_spec("unsloth_zoo")
            if spec is not None and spec.submodule_search_locations:
                pkg_dir = Path(list(spec.submodule_search_locations)[0])
                candidates.append(pkg_dir / "diffusion_studio" / "shim.py")
        except Exception:
            return False
    for path in candidates:
        try:
            source = path.read_text(encoding = "utf-8", errors = "ignore")
        except OSError:
            continue
        if _source_declares_option(source, "--ngl"):
            return True
    return False


def _visual_server_splits_gpus(visual_bin: Optional[str]) -> bool:
    """Whether the diffusion visual server survives a model split over several GPUs.

    Builds before the fix abort on the first request once split: with the prompt-KV store
    off (it is single-device) every [prompt|canvas] row asked for logits past the server's
    canvas-sized output cap. Fixed builds answer ``--capabilities`` with ``multi_gpu_split``;
    read that literal from the binary rather than spawning it, since an old build takes
    10-30 s to fail on the unknown argument.
    """
    if not visual_bin:
        return False
    try:
        st = os.stat(visual_bin)
    except OSError:
        return False
    return _binary_has_marker(visual_bin, st.st_mtime_ns, st.st_size, b"multi_gpu_split")


@functools.lru_cache(maxsize = 16)
def _binary_has_marker(path: str, _mtime_ns: int, _size: int, marker: bytes) -> bool:
    try:
        with open(path, "rb") as f:
            return marker in f.read()
    except OSError:
        return False


# No --help flag or build number announces it: read the trace string the new fit path compiles in.
_FIT_MEASURES_BORROWED_DRAFT_MARKER = (
    b"measuring the extra model next to an allocation-free target context"
)
_LLAMA_COMMON_LIB_NAMES = (
    "libllama-common.so.0",
    "libllama-common.so",
    "libllama-common.0.dylib",
    "libllama-common.dylib",
    "llama-common.dll",
)
# The server links libllama-server-impl, which links libllama-common.
_LLAMA_SERVER_IMPL_LIB_NAMES = (
    "libllama-server-impl.so",
    "libllama-server-impl.dylib",
    "llama-server-impl.dll",
)


# (path, mtime_ns, size) -> embedded library names; the server binary is ~100 MB.
_LINKED_LIB_NAMES_CACHE: dict = {}


def _linked_llama_libs(binary: Path, lib_dir: Path) -> list:
    """The server-impl / common libraries ``binary`` links by name (DT_NEEDED, LC_LOAD_DYLIB, PE
    imports), not stray siblings."""
    try:
        st = binary.stat()
        key = (str(binary), st.st_mtime_ns, st.st_size)
    except OSError:
        return []
    embedded = _LINKED_LIB_NAMES_CACHE.get(key)
    if embedded is None:
        try:
            data = binary.read_bytes()
        except OSError:
            return []
        embedded = tuple(
            tuple(n for n in names if n.encode() in data)
            for names in (_LLAMA_SERVER_IMPL_LIB_NAMES, _LLAMA_COMMON_LIB_NAMES)
        )
        _LINKED_LIB_NAMES_CACHE[key] = embedded
    linked = []
    for names in embedded:
        hit = next((n for n in names if (lib_dir / n).exists()), None)
        if hit is not None:
            linked.append(lib_dir / hit)
    return linked


_CUDA_LIKE_DEVICE_RE = re.compile(r"(?i)(cuda|rocm|hip)\d+$")


def _spawn_draft_on_target(
    run_cmd: List[str],
    spawn_devices: Optional[str],
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Whether the spawned argv's CUDA / ROCm draft pin names the target's device."""
    pin = _extra_args_draft_device_pin(run_cmd)
    if pin is not None:
        distinct = {d.strip() for d in pin.split(",") if d.strip()}
        pin = distinct.pop() if len(distinct) == 1 else pin
    if pin is None or not _CUDA_LIKE_DEVICE_RE.match(pin.strip()):
        return True
    if spawn_devices:
        named = [d.strip().lower() for d in spawn_devices.split(",") if d.strip()]
        if _split_mode_confines_to_one_device(run_cmd, env):
            # Only devices[main_gpu] is kept (main_gpu 0 by default).
            main = LlamaCppBackend._effective_main_gpu(run_cmd, env)
            main = 0 if main is None else main
            return 0 <= main < len(named) and pin.strip().lower() == named[main]
        return set(named) == {d.strip().lower() for d in pin.split(",") if d.strip()}
    return int(re.sub(r"\D", "", pin)) == (LlamaCppBackend._effective_main_gpu(run_cmd, env) or 0)


def _sidecar_borrows_output(path: Optional[str]) -> bool:
    """Whether the draft's logits use the target's output head (src/models/dflash.cpp); unknown
    counts as borrowed."""
    if not path:
        return True
    try:
        from utils.models.gguf_metadata import _gguf_shard_has_named_tensor
        from utils.models.model_config import colocated_split_shards

        shards, complete = colocated_split_shards(Path(path))
        return not (
            complete
            and any(
                _gguf_shard_has_named_tensor(str(shard), "output.weight") is True
                for shard in shards
            )
        )
    except Exception:
        return True


def _sidecar_borrows_target_tensors(path: Optional[str]) -> bool:
    """Whether the draft borrows token_embd or output, which the fitter cannot measure
    (src/llama-context.cpp)."""
    if not path:
        return True
    try:
        from utils.models.gguf_metadata import _gguf_shard_has_named_tensor
        from utils.models.model_config import colocated_split_shards

        shards, complete = colocated_split_shards(Path(path))
        if not complete or not shards:
            return True
        return any(
            not any(_gguf_shard_has_named_tensor(str(shard), name) is True for shard in shards)
            for name in ("token_embd.weight", "output.weight")
        )
    except Exception:
        return True


def _draft_pin_device_index(
    pin: Optional[str], spawn_devices: Optional[str], device_count: int
) -> Optional[int]:
    """The child device index a one-card draft pin names, or None."""
    names = {d.strip().lower() for d in (pin or "").split(",") if d.strip()}
    if len(names) != 1:
        return None
    (name,) = names
    if spawn_devices:
        listed = [d.strip().lower() for d in spawn_devices.split(",") if d.strip()]
        if name not in listed or len(set(listed)) != len(listed):
            return None
        return listed.index(name)
    if not _CUDA_LIKE_DEVICE_RE.match(name):
        return None
    k = int(re.sub(r"\D", "", name))
    return k if 0 <= k < device_count else None


def _distinct_device_count(devices) -> int:
    """Distinct names in a ``--device`` list: a repeated card is one memory pool."""
    return len({d.strip().lower() for d in str(devices).split(",") if d.strip()})


def _fit_measures_borrowed_drafts(bin_path: Optional[str]) -> bool:
    """Whether ``bin_path``'s fitter sizes a borrowed-tensor draft itself; fails closed."""
    if not bin_path:
        return False
    candidates = [Path(bin_path)]
    try:
        # A wrapper script execs the real server.
        server = Path(_resolve_llama_binary(bin_path))
        candidates.append(server)
        lib_dir = _llama_lib_dir(bin_path)
        for lib in _linked_llama_libs(server, lib_dir):
            candidates.append(lib)
            candidates.extend(l for l in _linked_llama_libs(lib, lib_dir) if l not in candidates)
    except Exception:  # noqa: BLE001 -- an unreadable lib dir is "not known"
        pass
    seen: set = set()
    for candidate in candidates:
        try:
            candidate = candidate.resolve()
            if candidate in seen or not candidate.is_file():
                continue
            seen.add(candidate)
            st = candidate.stat()
        except OSError:
            continue
        if _binary_has_marker(
            str(candidate), st.st_mtime_ns, st.st_size, _FIT_MEASURES_BORROWED_DRAFT_MARKER
        ):
            return True
    return False


def _swa_full_from_args_or_env(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """Whether llama.cpp receives the enable-only full-size SWA option."""
    if _extra_args_set_any_flag(extra_args, {"--swa-full"}):
        return True
    value = (os.environ if env is None else env).get("LLAMA_ARG_SWA_FULL")
    return value in _LLAMA_ARG_TRUE_VALUES


def _reasoning_from_env(env: Mapping[str, str]) -> Optional[bool]:
    value = env.get("LLAMA_ARG_REASONING")
    if value in _LLAMA_ARG_TRUE_VALUES:
        return True
    if value in _LLAMA_ARG_FALSE_VALUES:
        return False
    return None


def _reasoning_preserve_from_args_or_env(
    extra_args: Optional[Iterable[str]], env: Mapping[str, str]
) -> Optional[bool]:
    """The user's --[no-]reasoning-preserve choice, else None: last flag wins, as in
    llama.cpp's parser, and the extras beat the inherited LLAMA_ARG_REASONING_PRESERVE."""
    choice: Optional[bool] = None
    for raw in extra_args or ():
        flag = _flag_name(str(raw))
        if flag == "--reasoning-preserve":
            choice = True
        elif flag == "--no-reasoning-preserve":
            choice = False
    if choice is not None:
        return choice
    value = env.get("LLAMA_ARG_REASONING_PRESERVE")
    if value in _LLAMA_ARG_TRUE_VALUES:
        return True
    if value in _LLAMA_ARG_FALSE_VALUES:
        return False
    return None


def _template_preserves_thinking_by_default(template: str, context: Mapping) -> bool:
    """Whether ``template`` replays an earlier turn's reasoning with preserve_thinking
    omitted (Qwen3.8's own does, ``|default(false)`` does not); False if unrenderable."""
    from jinja2.sandbox import ImmutableSandboxedEnvironment

    def _raise(message):
        raise ValueError(message)

    marker = "unsloth-preserve-thinking-probe"
    messages = [
        {"role": "user", "content": "q1"},
        {"role": "assistant", "content": "a1", "reasoning_content": marker},
        {"role": "user", "content": "q2"},
    ]
    try:
        jinja = ImmutableSandboxedEnvironment(
            trim_blocks = True,
            lstrip_blocks = True,
            extensions = ["jinja2.ext.loopcontrols", "jinja2.ext.do"],
        )
        jinja.globals.update(raise_exception = _raise, strftime_now = lambda fmt: time.strftime(fmt))
        rendered = jinja.from_string(template).render(
            **{**context, "messages": messages, "add_generation_prompt": True}
        )
    except Exception:
        return False
    return marker in rendered


def _reasoning_effort_from_env(env: Mapping[str, str]) -> Optional[str]:
    value = env.get("LLAMA_ARG_REASONING_EFFORT")
    return None if value == "default" else value


def _env_asks_for_the_native_context(env: Optional[Mapping[str, str]] = None) -> bool:
    """LLAMA_ARG_CTX_SIZE=0 pins the native context, as -c 0 does; llama.cpp rejects unparseable ones."""
    value = (os.environ if env is None else env).get("LLAMA_ARG_CTX_SIZE")
    try:
        return int(str(value).strip()) == 0
    except (AttributeError, TypeError, ValueError):
        return False


def _env_ctx_checkpoints_override(env: Optional[Mapping[str, str]] = None) -> Optional[int]:
    """Env count is explicit: an emitted --ctx-checkpoints would overrule it, so the auto cap yields."""
    value = (os.environ if env is None else env).get("LLAMA_ARG_CTX_CHECKPOINTS")
    try:
        count = int(str(value).strip())
    except (AttributeError, TypeError, ValueError):
        return None
    return count if count >= 0 else None


def _kv_offload_from_args(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> bool:
    """LLAMA_ARG_NO_KV_OFFLOAD counts by presence, even when empty, and forces KV offload off; a CLI -kvo beats a false LLAMA_ARG_KV_OFFLOAD."""
    source_env = os.environ if env is None else env
    enabled = True
    if source_env.get("LLAMA_ARG_NO_KV_OFFLOAD") is not None:
        enabled = False
    else:
        value = source_env.get("LLAMA_ARG_KV_OFFLOAD")
        if value in _LLAMA_ARG_FALSE_VALUES:
            enabled = False
        elif value in _LLAMA_ARG_TRUE_VALUES:
            enabled = True
    for raw in extra_args or ():
        flag = _flag_name(str(raw))
        if flag in {"-kvo", "--kv-offload"}:
            enabled = True
        elif flag in {"-nkvo", "--no-kv-offload"}:
            enabled = False
    return enabled


def _is_positive_int(value: Optional[str]) -> bool:
    """Whether ``value`` parses as an int > 0 (llama.cpp's std::stoi)."""
    try:
        return int(str(value).strip()) > 0
    except (TypeError, ValueError):
        return False


def _args_place_tensors_on_cpu(extra_args: Optional[Iterable[str]] = None) -> bool:
    """True when extras keep weights on CPU whatever the layer count says; a CPU-MoE or CPU-FFN count counts only when positive (-ncmoe 0 places nothing)."""
    values = [str(raw) for raw in extra_args or ()]
    for i, raw in enumerate(values):
        flag = _flag_name(raw)
        # Any -ot counts, even if it matches nothing: non-empty is enough, and the pattern is not guessed at.
        if flag in _CPU_PLACEMENT_PRESENCE_FLAGS:
            return True
        if flag in _CPU_MOE_COUNT_FLAGS | _CPU_FFN_COUNT_FLAGS:
            _, eq, inline = raw.partition("=")
            if _is_positive_int(inline if eq else (values[i + 1] if i + 1 < len(values) else "")):
                return True
    return False


def _env_places_tensors_on_cpu(env: Optional[Mapping[str, str]] = None) -> bool:
    """True when inherited env keeps weights on CPU whatever argv says; it survives argv stripping, and the host-residency gate must not miss it."""
    source_env = os.environ if env is None else env
    return bool(
        source_env.get("LLAMA_ARG_OVERRIDE_TENSOR")
        or source_env.get("LLAMA_ARG_CPU_MOE") in _LLAMA_ARG_TRUE_VALUES
        or _is_positive_int(source_env.get("LLAMA_ARG_N_CPU_MOE"))
        or _is_positive_int(source_env.get("LLAMA_ARG_N_CPU_FFN"))
    )


def _env_fixes_gpu_layers(env: Optional[Mapping[str, str]] = None) -> bool:
    """Any inherited count but auto/-1 overrides the fit; empty counts as unset (stoi would throw)."""
    raw = (os.environ if env is None else env).get("LLAMA_ARG_N_GPU_LAYERS")
    value = str(raw or "").strip().lower()
    return bool(value) and value not in _LLAMA_ARG_AUTO_VALUES


def _pipeline_parallel_disabled_by_args(
    extra_args: Optional[Iterable[str]],
    env: Optional[Mapping[str, str]] = None,
    n_layers: Optional[int] = None,
) -> bool:
    """Pipelining needs -sm layer, KV offload on, no tensor overrides (-ot, -cmoe, -ncmoe, not -otd); ambiguous input stays pipelined, as under-reserving OOMs."""
    source_env = os.environ if env is None else env
    if _env_places_tensors_on_cpu(source_env):
        return True
    if not _kv_offload_from_args(extra_args, env = env):
        return True
    # -sm tensor reaches here only after a downgrade strips it, so only none/row disable it.
    split_mode = parse_split_mode_override(extra_args)
    if split_mode is not None and split_mode.strip().lower() not in {"layer", "tensor"}:
        return True
    # Pipelining needs n_gpu_layers > n_layer_all (block_count, not the MTP-less hparams n_layer); a user -ngl that cannot exceed it turns it off.
    if n_layers:
        try:
            gpu_layers = parse_gpu_layers_override(extra_args)
        except ValueError:
            gpu_layers = None  # malformed: unknown, so keep the step
        if gpu_layers is not None and 0 <= gpu_layers <= n_layers:
            return True
    # Same predicate as the Model Memory host-residency gate; -ncmoe 0 pushes no override, so pipelining stays on.
    return _args_place_tensors_on_cpu(extra_args)


def _kv_unified_from_args(
    extra_args: Optional[Iterable[str]],
    default: bool = False,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Resolve llama.cpp's environment and last-wins unified KV flags."""
    enabled = False
    value = (os.environ if env is None else env).get("LLAMA_ARG_KV_UNIFIED")
    if value in _LLAMA_ARG_TRUE_VALUES:
        enabled = True
    elif value in _LLAMA_ARG_FALSE_VALUES:
        enabled = False
    if default:
        # Unsloth's managed --kv-unified is appended after environment parsing and before user extras.
        enabled = True
    for raw in extra_args or ():
        flag = _flag_name(str(raw))
        if flag in {"-kvu", "--kv-unified"}:
            enabled = True
        elif flag in {"-no-kvu", "--no-kv-unified"}:
            enabled = False
    return enabled


# llama.cpp forces flash attention off for Grok (KQ logit softcap).
_FLASH_ATTN_INCOMPATIBLE_ARCHITECTURES = frozenset({"grok"})


def _architecture_forces_flash_attn_off(architecture: Optional[str]) -> bool:
    """Whether llama.cpp will disable flash attention for this architecture on its own."""
    return str(architecture or "").strip().lower() in _FLASH_ATTN_INCOMPATIBLE_ARCHITECTURES


def _planned_flash_attn_state(
    extra_args: Optional[Iterable[str]] = None,
    *,
    planned_cache_types: Optional[tuple[str, str]] = None,
    supports_flash_attn: bool = True,
    tensor_parallel: bool = False,
    architecture: Optional[str] = None,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """One answer for the estimate and for the argv: the estimator floors V at f16 and pads
    it model-wide when flash attention is off, so resolving the two separately prices a
    different load, not a conservative one (#9697, #10489)."""
    if not supports_flash_attn:
        return False
    if _architecture_forces_flash_attn_off(architecture):
        # Ahead of every rule below, as llama.cpp puts it ahead of both its own upgrades.
        return False
    v_type = (planned_cache_types[1] if planned_cache_types else "f16") or "f16"
    quantized_v = str(v_type).strip().lower() not in {"f16", "bf16", "f32"}
    if quantized_v:
        # Not a choice: llama.cpp turns it on itself rather than refusing the load.
        return True
    # Prepended: load_model appends a managed --flash-attn on that only user extras beat.
    effective_args = ["--flash-attn", "on", *(str(arg) for arg in extra_args or ())]
    if _asked_for_auto_flash_attn(effective_args, env = env):
        if _effective_tensor_parallel(extra_args, tensor_parallel, env):
            # Not undecided: llama.cpp upgrades AUTO to ENABLED under SPLIT_MODE_TENSOR.
            return True
        # ``auto`` is decided at load time and can come back no; size for the costlier answer.
        return False
    return _flash_attn_enabled_from_args(effective_args, default = True, env = env)


def _user_fit_disabled(
    extra_args: Optional[Iterable[str]] = None, *, env: Optional[Mapping[str, str]] = None
) -> bool:
    """Whether the USER has turned llama.cpp's fitter off, last-wins: Unsloth's own token
    comes first and a retry rewrites it, so only a user's later value survives a re-place."""
    values = [str(arg) for arg in extra_args] if extra_args else []
    asked: Optional[str] = None
    inherited = (os.environ if env is None else env).get("LLAMA_ARG_FIT")
    if inherited is not None and str(inherited).strip():
        asked = str(inherited).strip()
    for i, raw in enumerate(values):
        if _flag_name(raw) not in {"-fit", "--fit"}:
            continue
        _, eq, inline = raw.partition("=")
        value = inline if eq else "on"
        if not eq and i + 1 < len(values):
            value = values[i + 1]
        asked = value
    return str(asked).strip().lower() in {"off", "0", "false", "no", "disabled"}


def _placement_is_fitter_proof(
    extra_args: Optional[Iterable[str]] = None,
    *,
    gpu_layers: Optional[int] = None,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Whether a layer count llama.cpp's fitter refuses to move owns this placement:
    ``common_params_fit_impl`` throws "n_gpu_layers already set by user" (common/fit.cpp:377)
    for any value but -1, so re-enabling the fitter for a respawn buys nothing."""
    if gpu_layers is not None and gpu_layers >= 0:
        return True
    values = [str(arg) for arg in extra_args] if extra_args else []
    for i, raw in enumerate(values):
        if _flag_name(raw) not in _GPU_LAYER_FLAGS:
            continue
        _, eq, inline = raw.partition("=")
        value = inline if eq else ""
        if not eq and i + 1 < len(values):
            value = values[i + 1]
        value = value.strip().lower()
        if value and value not in _LLAMA_ARG_AUTO_VALUES:
            return True
    return bool(_env_fixes_gpu_layers(env))


def _reserved_flash_attn_state(
    planned: bool,
    extra_args: Optional[Iterable[str]] = None,
    *,
    tensor_parallel: bool = False,
    gpu_layers: Optional[int] = None,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """A flash-attn respawn pads V model-wide and may not be re-placed, so keep the planned state; tensor mode has no respawn, so skip this."""
    if not planned:
        return planned
    if _effective_tensor_parallel(extra_args, tensor_parallel, env):
        return planned
    if _user_fit_disabled(extra_args, env = env):
        return False
    if _placement_is_fitter_proof(extra_args, gpu_layers = gpu_layers, env = env):
        return False
    return planned


def _asked_for_auto_flash_attn(
    extra_args: Optional[Iterable[str]] = None, *, env: Optional[Mapping[str, str]] = None
) -> bool:
    """``_flash_attn_enabled_from_args`` folds auto into True because it answers what the
    argv will SAY; sizing needs to know nobody has decided yet."""
    asked: Optional[str] = None
    value = (os.environ if env is None else env).get("LLAMA_ARG_FLASH_ATTN")
    if value in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES:
        asked = value
    values = [str(arg) for arg in extra_args] if extra_args else []
    for i, raw in enumerate(values):
        if _flag_name(raw) not in {"-fa", "--flash-attn"}:
            continue
        _, eq, inline = raw.partition("=")
        value = inline if eq else "on"
        if not eq and i + 1 < len(values) and values[i + 1] in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES:
            value = values[i + 1]
        asked = value
    return asked in _LLAMA_ARG_AUTO_VALUES


def _flash_attn_enabled_from_args(
    args: Optional[Iterable[str]],
    default: bool = True,
    env: Optional[Mapping[str, str]] = None,
) -> bool:
    """Resolve llama.cpp's environment and last-wins flash-attention settings."""
    enabled = default
    # llama.cpp applies the env before argv, so the CLI still wins.
    value = (os.environ if env is None else env).get("LLAMA_ARG_FLASH_ATTN")
    if value in _LLAMA_ARG_FALSE_VALUES:
        enabled = False
    elif value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
        enabled = True
    values = [str(arg) for arg in args] if args else []
    for i, raw in enumerate(values):
        if _flag_name(raw) not in {"-fa", "--flash-attn"}:
            continue
        _, eq, inline = raw.partition("=")
        value = inline if eq else "on"
        if not eq and i + 1 < len(values) and values[i + 1] in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES:
            value = values[i + 1]
        if value in _LLAMA_ARG_FALSE_VALUES:
            enabled = False
        elif value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
            enabled = True
    return enabled


def _effective_spec_type(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Optional[str]:
    """Display label only: llama.cpp accumulates spec types, so ask _extra_args_requests_mtp for MTP."""
    args = [str(a) for a in extra_args] if extra_args else []
    cli_present = False
    cli_value: Optional[str] = None
    for i, raw in enumerate(args):
        flag = _flag_name(raw)
        _, eq, inline = raw.partition("=")
        if flag == "--spec-default":
            cli_present = True
            cli_value = "default"
            continue
        if flag != "--spec-type":
            continue
        cli_present = True
        cli_value = inline if eq else (args[i + 1] if i + 1 < len(args) else "")
    if cli_present:
        return cli_value
    return (os.environ if env is None else env).get("LLAMA_ARG_SPEC_TYPE")


def _child_spec_env(
    extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]] = None
) -> Mapping[str, str]:
    """Spec env the child sees: empty unless extras name --spec-type (launch scrubs LLAMA_ARG_SPEC_*); predict from this, not os.environ."""
    if not _extra_args_set_spec_type(extra_args):
        return {}
    return os.environ if env is None else env


# Spec types giving the target context recurrent-state rollback snapshots; both MTP spellings are listed since builds advertise either name.
_TARGET_ROLLBACK_SPEC_TYPES = frozenset(
    {"mtp", "draft-mtp", "draft-eagle3", "draft-dflash", "draft-dspark"}
)


