    def diffusion_requested_ngl(self) -> Optional[int]:
        """The ask, not what runs, so repeats still dedupe; differs from gpu_layers only if the shim
        refused."""
        return getattr(self, "_diffusion_requested_ngl", None)

    @property
    def n_cpu_moe(self) -> int:
        """MoE expert layers manual mode kept on CPU (--n-cpu-moe); 0 = none."""
        return self._n_cpu_moe

    @property
    def tensor_split(self) -> Optional[List[float]]:
        """Manual returns the requested ratio; auto returns the normalized ratio actually emitted,
        or None."""
        if self._tensor_split is not None:
            return self._tensor_split
        if self._auto_tensor_split_emitted is not None:
            return list(self._auto_tensor_split_emitted)
        return None

    @property
    def gpu_ids(self) -> Optional[List[int]]:
        """User-picked physical GPU indices, or None for automatic selection."""
        return self._gpu_ids

    @property
    def requested_gpu_ids(self) -> Optional[List[int]]:
        """RAW requested GPU pin (before the fit narrowed it), or None for auto.
        gpu_ids echoes the EFFECTIVE pin for /status."""
        return self._requested_gpu_ids

    def matches_gpu_ids(self, gpu_ids: Optional[List[int]]) -> bool:
        """Whether a requested pin is already satisfied by the active runner.

        A regular GGUF load may narrow the requested placement pool to the
        smallest fitting subset. Accept both the original request and the
        effective status-echoed subset so either can round-trip without a
        needless reload. Diffusion records the lowest device of a pick that fits it,
        else the whole pick it split over, so either form matches.
        """
        if self._is_diffusion:
            full = sorted(int(x) for x in gpu_ids) if gpu_ids else None
            # Raw pick accepted too: a forced-CPU runner records no effective pin, so
            # without it re-sending the same selection would reload every time.
            held = ((self._gpu_ids or None), (self._requested_gpu_ids or None))
            return (full[:1] if full else None) in held or full in held

        requested = [int(x) for x in gpu_ids] if gpu_ids else None
        raw = self._requested_gpu_ids or None
        effective = self._gpu_ids or None
        return requested == raw or requested == effective

    def _adopt_widened_pin(self, pin_ids: List[int]) -> None:
        """Adopt the companion-widened pin as effective; else /status and dedupe keep the pre-widen pin and a reload drops the companion card; forced CPU stays None."""
        if self._gpu_ids is not None:
            self._gpu_ids = [int(i) for i in pin_ids]

    def _record_matching_gpu_request(self, gpu_ids: Optional[List[int]]) -> None:
        """Recorded even on a match so a reload does not restore GPUs the user just removed."""
        if self._is_diffusion:
            full = sorted(int(x) for x in gpu_ids) if gpu_ids else None
            # Keep the whole pick when the fit moved off its lowest GPU (a split, or one
            # higher card), or a later pick of that lowest GPU would match and not reload.
            moved = bool(self._gpu_ids) and bool(full) and self._gpu_ids != full[:1]
            self._requested_gpu_ids = full if moved else (full[:1] if full else None)
        else:
            self._requested_gpu_ids = [int(x) for x in gpu_ids] if gpu_ids else None
        if self._last_load_intent is not None:
            self._last_load_intent = replace(
                self._last_load_intent,
                gpu_ids = tuple(self._requested_gpu_ids) if self._requested_gpu_ids else None,
            )

    @property
    def last_load_intent(self) -> Optional[GgufLoadIntent]:
        return self._last_load_intent

    def _runtime_matches_intent(
        self, intent: GgufLoadIntent, effective_extra_args: Optional[list[str]]
    ) -> bool:
        """Whether active runtime settings satisfy one resolved caller intent."""

        if intent.force_reload:
            return False
        if self._requested_n_ctx != int(intent.n_ctx):
            return False
        if not self._is_diffusion and self._requested_n_parallel != max(1, int(intent.n_parallel)):
            return False
        # The same count chosen rather than defaulted is one Auto may not cut.
        if (
            not self._is_diffusion
            and self._slots_cut_for_drafter
            and not intent.n_parallel_from_default
        ):
            return False
        if not self._is_diffusion and (
            self._requested_n_batch != intent.n_batch or self._requested_n_ubatch != intent.n_ubatch
        ):
            return False
        # Requested against requested; a blank value is the llama.cpp default.
        if not self._is_diffusion and (
            _normalized_load_mode(self._requested_load_mode)
            != _normalized_load_mode(intent.load_mode)
            or self._requested_spec_draft_cache_type != intent.spec_draft_cache_type
            or self._requested_ctx_checkpoints != intent.ctx_checkpoints
            or self._requested_cache_ram != intent.cache_ram
        ):
            return False

        # Vision toggles change which files the child opens, so a server launched the other way cannot match; not on diffusion, which records False.
        if not self._is_diffusion and bool(self._disable_vision) != bool(intent.disable_vision):
            return False

        extra_args = list(effective_extra_args) if effective_extra_args is not None else None
        # Compare requests: an inherited LLAMA_ARG_THINK_BUDGET* would never converge.
        if not self._is_diffusion and (
            self._requested_reasoning_budget
            != resolve_reasoning_budget(extra_args, intent.reasoning_budget)
            or self._requested_reasoning_budget_message
            != resolve_reasoning_budget_message(extra_args, intent.reasoning_budget_message)
        ):
            return False
        # Omitted extras inherit the LAUNCHED list; judge on the flag, not value equality, since a deliberate stripped list must not read as inheriting.
        _invoked_extras = self.requested_extra_args if intent.extra_args_inherited else extra_args
        # Requested against requested per axis; the scalar _cache_type_kv misses extras/env.
        if self._requested_cache_types != _planned_main_cache_types(
            intent.cache_type_kv, _invoked_extras
        ):
            return False
        # Virtualised Metal never launches a tensor split, so judge the normalized request, else an extras -sm tensor the pin leaves in place would never match.
        if _metal_device_is_paravirtual():
            if self._tensor_parallel:
                return False
        elif not _tensor_parallel_matches_loaded(
            extra_args, intent.tensor_parallel, self._tensor_parallel
        ):
            # Only a RECORDED drop excuses a live layer server against a tensor request.
            if not (self._arch_gate_dropped_tensor_parallel and not self._tensor_parallel):
                return False
        if (
            self._layer_preserves_tensor_intent
            and not _effective_tensor_parallel(extra_args, intent.tensor_parallel)
            and not intent.preserve_multi_gpu_on_layer
        ):
            return False

        if self._is_diffusion:
            requested_ngl = _diffusion_manual_ngl(intent.gpu_memory_mode, intent.gpu_layers)
            if requested_ngl != self.diffusion_requested_ngl:
                return False
            # An older shim's dropped split matches until it gains --ngl; then the same request applies it.
            if (
                requested_ngl is not None
                and self._gpu_layers != requested_ngl
                and self.diffusion_split_supported()
            ):
                return False
        else:
            if self._swa_full != _swa_full_from_args_or_env(extra_args):
                return False
            if self._gpu_memory_mode != intent.gpu_memory_mode:
                return False
            if intent.gpu_memory_mode == "manual" and (
                self._gpu_layers != intent.gpu_layers
                or (
                    intent.gpu_layers >= 0
                    and (
                        self._n_cpu_moe != intent.n_cpu_moe
                        or (
                            (tuple(self._tensor_split) if self._tensor_split else None)
                            != (intent.tensor_split or None)
                            # A recorded drop (never None == None) means this request, so only other ratios reload.
                            and not (
                                self._arch_gate_dropped_tensor_split is not None
                                and self._arch_gate_dropped_tensor_split
                                == (intent.tensor_split or None)
                            )
                        )
                    )
                )
            ):
                return False
            # Auto mode can carry a user ratio the planner does not describe, so reuse needs an identical ratio.
            if (
                intent.gpu_memory_mode != "manual"
                and self._tensor_parallel
                and self._auto_tensor_split != self._auto_split_fingerprint(intent.tensor_split)
            ):
                return False

        if not self.matches_gpu_ids(list(intent.gpu_ids) if intent.gpu_ids else None):
            return False

        spec_owned_by_extra_args = _extra_args_set_spec_type(extra_args)
        speculative_type = (
            None
            if spec_owned_by_extra_args
            else _canonicalize_spec_mode(intent.speculative_type) or "auto"
        )
        backend_spec = self._requested_spec_mode
        if spec_owned_by_extra_args:
            if backend_spec is not None:
                return False
        elif speculative_type != (backend_spec or "auto"):
            return False
        # Retry only when the repo publishes a drafter, else it relaunches forever.
        if (
            intent.gguf_path is None
            and self._spec_fallback_reason == "drafter_not_found"
            # The fetch did find it and the load dropped it; refetching finds it again.
            and self._mtp_draft_suppressed_path is None
            and speculative_type in ("auto", "mtp", "mtp+ngram", "dspark", "dflash")
            and not (self._spec_drafter_kind == "dspark" and self._dspark_sidecar_absent)
            # DFlash uses _dflash_retry_needed; this arm would relaunch forever on permanent errors.
            and self._spec_drafter_kind != "dflash"
            and not spec_owned_by_extra_args
        ):
            return False
        # Stand-down asks the user to update llama.cpp; the identical request must reload once repaired.
        if (
            speculative_type in ("auto", "mtp", "mtp+ngram", "dspark", "dflash", "ngram")
            and self.spec_binary_fallback_can_retry()
        ):
            return False
        # Under Auto a failed fetch records no fallback reason, so the branch above cannot see it.
        if self._dflash_retry_needed and speculative_type in ("auto", "dflash"):
            return False
        # Reload once after a degraded probe starts answering, else Apply dedupes forever.
        if (
            self._capability_probe_inconclusive
            and not self._is_diffusion
            and not self.probe_server_capabilities().get("mtp_probe_inconclusive")
        ):
            return False

        compared_draft_n_max = self._spec_draft_n_max
        if self._spec_fallback_reason == "runtime_error" and self._last_load_intent is not None:
            # MTP-free recovery keeps the user's prior value in intent; only a changed value should retry MTP.
            compared_draft_n_max = self._last_load_intent.spec_draft_n_max
        draft_depth_matters = (
            self._speculative_type in ("draft-mtp", "draft-dspark", "draft-dflash")
            # Auto's Hybrid Mamba partial-offload stand-down engaged nothing, so the
            # types above cannot see it. The depth priced the rollback copies that
            # made the placement partial, so a change can re-enable MTP.
            or self._spec_fallback_reason in ("runtime_error", "mtp_partial_offload")
        )
        if draft_depth_matters:
            requested_draft_n_max = intent.spec_draft_n_max
            if (requested_draft_n_max is None) != (compared_draft_n_max is None):
                return False
            if requested_draft_n_max is not None and requested_draft_n_max != compared_draft_n_max:
                return False
        if (self._chat_template_override or None) != (intent.chat_template_override or None):
            return False

        if tuple(_invoked_extras or ()) != tuple(self.requested_extra_args or ()):
            return False
        if (intent.gguf_path is not None or intent.compare_mtp_draft) and speculative_type in (
            "auto",
            "mtp",
            "mtp+ngram",
            "dspark",
            "dflash",
        ):
            try:
                # Auto dspark or dflash counts as such; key off _spec_drafter_kind (survives fallback), not _speculative_type, or every Apply reloads a healthy server.
                _compare_dspark = speculative_type == "dspark" or (
                    speculative_type == "auto"
                    and (
                        self._speculative_type == "draft-dspark"
                        or self._spec_drafter_kind == "dspark"
                    )
                )
                _compare_dflash = speculative_type == "dflash" or (
                    speculative_type == "auto"
                    and (
                        self._speculative_type == "draft-dflash"
                        or self._spec_drafter_kind == "dflash"
                    )
                )
                if _compare_dspark:
                    intent_draft = intent.dspark_draft_path
                elif _compare_dflash:
                    intent_draft = intent.dflash_draft_path
                else:
                    intent_draft = intent.mtp_draft_path
                requested_draft = Path(intent_draft).resolve() if intent_draft else None
                # A drafter dropped on purpose counts as launched, else this reloads forever.
                _loaded = self._mtp_draft_path or self._mtp_draft_suppressed_path
                loaded_draft = Path(_loaded).resolve() if _loaded else None
            except OSError:
                return False
            if requested_draft != loaded_draft:
                return False
            # Only the unloadable drop is re-asked, since a paravirtual drop repeats for the same bytes; cache on (path, mtime, size) so only repaired files reparse.
            if (
                self._mtp_draft_suppressed_reason == "unloadable"
                and self._mtp_draft_suppressed_path
                and _mtp_drafter_loads_standalone(self._mtp_draft_suppressed_path)
            ):
                return False
        return True

    @property
    def n_layers(self) -> Optional[int]:
        """Model layer count (GGUF block_count), or None if unknown."""
        return self._n_layers

    @property
    def n_moe_layers(self) -> int:
        """Excludes leading dense layers, since --n-cpu-moe counts from layer 0 and those carry no
        experts."""
        if not self._n_experts or not self._n_layers:
            return 0
        return max(0, self._n_layers - (self._leading_dense_block_count or 0))

    _EMBEDDING_POOLING_TYPES = frozenset({1, 2, 3})  # llama_pooling_type MEAN, CLS, LAST

    @property
    def is_embedding_gguf(self) -> bool:
        """Only MEAN, CLS, LAST pool to one vector; NONE and RANK do not. Without pooling_type, fall back to arch and name hints so --embedding still launches."""
        pooling = getattr(self, "_pooling_type", None)
        if pooling is not None:
            return pooling in self._EMBEDDING_POOLING_TYPES
        path = getattr(self, "_gguf_path", None)
        if not path:
            return False
        from utils.models.gguf_metadata import is_gguf_embedding_model

        return is_gguf_embedding_model(
            path,
            model_identifier = self._model_identifier,
            architecture = self._architecture,
        )

    @staticmethod
    def _resolve_cpu_moe_flag(
        n_cpu_moe: int, n_moe_layers: int, leading_dense: int
    ) -> Optional[int]:
        """Offset past leading dense layers (--n-cpu-moe counts from layer 0); None when nothing to
        offload."""
        if n_cpu_moe <= 0 or n_moe_layers <= 0:
            return None
        return leading_dense + min(n_cpu_moe, n_moe_layers)

    @staticmethod
    def _sanitize_tensor_split(tensor_split: Optional[List[float]]) -> List[float]:
        """Negative and non-finite shares become 0, since inf would pass a > 0 gate; unreadable input returns [] and the call site drops the split."""
        try:
            return [
                x if math.isfinite(x) and x > 0.0 else 0.0 for x in (float(v) for v in tensor_split)
            ]
        except (TypeError, ValueError, OverflowError):
            return []

    @staticmethod
    def _format_tensor_split(values: List[float]) -> str:
        """Fixed-point, not %g (which prints 1000000,1 as 1e+06,1 in a pasted bug-report argv); a ratio that rounds to 0,0 is rescaled by its largest weight."""

        def _render(items):
            return [f"{x:.6f}".rstrip("0").rstrip(".") or "0" for x in items]

        rendered = _render(values)
        if values and all(part == "0" for part in rendered):
            peak = max(values)
            if peak > 0:
                rendered = _render(v / peak for v in values)
        return ",".join(rendered)

    @staticmethod
    def _discrete_first_split(
        gpu_indices: List[int],
        usable_mib: dict[int, float],
        shared_gpu_ids: Iterable[int],
        layer_mib: List[float],
        per_device_mib: float = 0.0,
        main_reserve_mib: float = 0.0,
        pipeline_mib: float = 0.0,
    ) -> Optional[List[float]]:
        """Layer-count ``--tensor-split`` shares over ``gpu_indices``: discrete cards first,
        iGPUs (whose "free" is the host pool) take the overflow. llama.cpp cuts contiguous runs
        by COUNT (get_layer_buft_list). None unless the pin mixes both kinds and every run fits."""
        shared = set(shared_gpu_ids)
        discrete = [i for i in gpu_indices if i not in shared]
        igpus = [i for i in gpu_indices if i in shared]
        n = len(layer_mib)
        if not discrete or not igpus or n == 0:
            return None
        room = {
            i: usable_mib.get(i, 0.0)
            - per_device_mib
            - (main_reserve_mib if k == 0 else pipeline_mib)
            for k, i in enumerate(gpu_indices)
        }
        prefix = [0.0]
        for mib in layer_mib:
            prefix.append(prefix[-1] + mib)

        def most_layers(cap: float) -> int:
            k = 0
            while k < n and max(prefix[j + k + 1] - prefix[j] for j in range(n - k)) <= cap:
                k += 1
            return k

        counts: dict[int, float] = {}
        left = n
        for i in sorted(discrete, key = lambda d: room[d], reverse = True):
            counts[i] = min(most_layers(room[i]), left)
            left -= counts[i]
        if left == n:
            return None
        igpu_room = {i: max(0.0, room[i]) for i in igpus}
        igpu_total = sum(igpu_room.values())
        exact = {
            i: (left * igpu_room[i] / igpu_total if igpu_total > 0 else left / len(igpus))
            for i in igpus
        }
        for i in igpus:
            counts[i] = int(exact[i])
        for i in sorted(igpus, key = lambda d: exact[d] - counts[d], reverse = True)[
            : left - sum(counts[i] for i in igpus)
        ]:
            counts[i] += 1
        # The runs llama.cpp will really cut, in device order: each must fit its room.
        start = 0
        for i in gpu_indices:
            end = start + int(counts[i])
            if prefix[end] - prefix[start] > max(0.0, room[i]):
                return None
            start = end
        shares = [float(counts[i]) for i in gpu_indices]
        # Boundaries half a layer early: float rounding in upper_bound cannot add a layer.
        first = next(k for k, v in enumerate(shares) if v > 0)
        if first != len(shares) - 1:
            shares[first] -= 0.5
            shares[-1] += 0.5
        return shares

    def _mixed_pin_split(
        self,
        gpu_indices: List[int],
        spill_inputs: Optional[dict],
        shared_gpu_ids: Iterable[int],
        extra_args: Optional[Iterable[str]],
        env: Mapping[str, str],
        *,
        layer_min_gpus: int,
        tensor_parallel: bool,
        pin_owns_devices: bool = False,
    ) -> Optional[List[float]]:
        """The discrete-first split for a full-offload mixed Vulkan pin, or None to
        leave llama.cpp's own split (the pre-existing behaviour) wherever its inputs
        cannot be priced or someone else owns the placement."""
        if (
            not shared_gpu_ids
            or spill_inputs is None
            or tensor_parallel
            # A downgraded tensor request keeps every device in use.
            or layer_min_gpus > 1
            # A GPU-resident separate drafter spreads over every device.
            or spill_inputs["separate_draft_on_gpu"]
            or spill_inputs.get("env_mmproj_unsized")
            # A host-resident cache or projector draws on the pool the iGPU reports.
            or spill_inputs.get("host_mmproj_bytes")
            or not _kv_offload_from_args(extra_args, env)
            or _extra_args_have_tensor_split(extra_args, env)
            # argv only: a non-layer inherited LLAMA_ARG_SPLIT_MODE is popped before launch.
            or _extra_args_split_mode(extra_args, {}) not in (None, "layer")
            # Extras follow the generated --fit off; the fitter rejects a multi-device split.
            or any(
                str(a) in ("-fit", "--fit") or str(a).startswith(("-fit=", "--fit="))
                for a in (extra_args or ())
            )
            # RPC devices go ahead of the local ones, so the shares would land on them.
            or (_extra_args_device(extra_args, {"--rpc"}) or "").strip()
            or str(env.get("LLAMA_ARG_RPC", "")).strip()
            # Tensor overrides move bytes after the split is priced.
            or _args_place_tensors_on_cpu(extra_args)
            or _env_places_tensors_on_cpu(env)
            # A projector pinned to another device is charged to device 0 below.
            or (_extra_args_device(extra_args, {"--mmproj-device", "-mmdev"}) or "").strip()
            or str(env.get("MTMD_BACKEND_DEVICE", "")).strip()
            # A surviving device list owns the share order; a gpu_ids pin strips it.
            or (
                not pin_owns_devices
                and (
                    _extra_args_main_device(extra_args) is not None
                    or str(env.get("LLAMA_ARG_DEVICE", "")).strip()
                )
            )
        ):
            return None
        # Adapters may target only some layers, which a total cannot place.
        if _sidecar_adapter_paths(extra_args):
            return None
        # A larger pass-through --parallel (last-wins) grows the cache priced here.
        _np_override = _extra_args_n_parallel(extra_args, env)
        if _np_override is not None and _np_override > int(spill_inputs.get("n_parallel") or 1):
            return None
        layout = self._tensor_spill_layout(spill_inputs.get("model_path"))
        if layout is None or not layout.complete or not layout.blocks:
            return None
        n_blocks = len(layout.blocks)
        kv_total = int(spill_inputs["kv_cache_bytes"] or 0)
        kv_weights = list(spill_inputs.get("kv_layer_weights") or ())
        if len(kv_weights) != n_blocks or sum(kv_weights) <= 0:
            # MLA, hybrid recurrent and an unpriced sliding window are uneven (_kv_layer_weights).
            if kv_total and (
                self._kv_lora_rank is not None
                or self._ssm_inner_size is not None
                or self._sliding_window_pattern
                or self._effective_sliding_window()
            ):
                return None
            kv_weights = [1] * n_blocks
        kv_scale = kv_total / sum(kv_weights)
        layer_bytes = [
            blk.spillable_bytes + blk.resident_bytes + w * kv_scale
            for blk, w in zip(layout.blocks, kv_weights)
        ]
        # Trailing nextn rows count in llama.cpp's n_layer_all + 1; resident only with a draft.
        n_mtp = int(self._nextn_predict_layers or 0) if layout.has_excluded_blocks else 0
        if layout.has_excluded_blocks and n_mtp <= 0:
            return None
        mtp_row = (
            layout.excluded_block_bytes / n_mtp
            if n_mtp and spill_inputs.get("mtp_will_engage")
            else 0.0
        ) + max(kv_weights) * kv_scale  # archs walking n_layer_all cache these rows too
        layer_bytes.extend([mtp_row] * n_mtp)
        # The output layer rides the last row (the last device's run).
        layer_bytes.append(layout.lm_head_bytes + layout.other_resident_bytes)
        reserve = (
            spill_inputs["compute_buffer_flat"]
            + spill_inputs["extra_gpu_bytes"]
            + int(spill_inputs.get("env_mmproj_bytes") or 0)
        )
        # As _planned_tensor_spill; a hybrid run may hold one attention layer over its share.
        per_device = spill_inputs["ctx_compute_per_device"] + spill_inputs["soft_overhead"]
        if 0 < layout.n_attention_layers < n_blocks and len(kv_weights) == n_blocks:
            per_device += kv_total / layout.n_attention_layers
        mib = 1024 * 1024
        return self._discrete_first_split(
            list(gpu_indices),
            spill_inputs["gpu_usable_mib"],
            shared_gpu_ids,
            [x / mib for x in layer_bytes],
            per_device / mib,
            reserve / mib,
            self._PIPELINE_PER_DEVICE_OVERHEAD_MIB,
        )

    @staticmethod
    def _auto_split_fingerprint(tensor_split: Optional[List[float]]) -> Optional[tuple[float, ...]]:
        """Requested vs requested, normalized; auto emits MiB budgets, not the caller ratio, or every repeat reloads the model; an empty ratio is None."""
        if not tensor_split:
            return None
        values = LlamaCppBackend._sanitize_tensor_split(tensor_split)
        total = sum(values)
        if not values or total <= 0:
            return None
        return tuple(round(v / total, 6) for v in values)

    @property
    def layer_preserves_tensor_intent(self) -> bool:
        """True when a downgraded tensor request kept this layer load multi-GPU."""
        return self._layer_preserves_tensor_intent

    @property
    def speculative_type(self) -> Optional[str]:
        return self._speculative_type

    @property
    def spec_drafter_kind(self) -> Optional[str]:
        """Resolved drafter kind (mtp, dspark, dflash), even when Auto chose it; unlike requested_spec_mode (stays auto) or speculative_type (default after fallback)."""
        return self._spec_drafter_kind

    @property
    def requested_spec_mode(self) -> Optional[str]:
        """Canonical UI-facing mode the user requested (see field doc)."""
        return self._requested_spec_mode

    @property
    def spec_draft_n_max(self) -> Optional[int]:
        """User --spec-draft-n-max override active on the load, or None when
        the platform default (6 GPU / 3 CPU) is in effect."""
        return self._spec_draft_n_max

    # ── Binary discovery ──────────────────────────────────────────

    @staticmethod
    def _resolved_studio_root_and_is_legacy() -> "tuple[Optional[Path], bool]":
        """On failure the root counts as legacy, and resolved_root is None, so read it only when not
        legacy."""
        try:
            from utils.paths.storage_roots import (  # noqa: WPS433
                studio_root as _sr,
                unsloth_home as _uh,
            )

            # llama.cpp sits beside studio/ under the master root that run.py and main.py export; not legacy.
            master = _uh()
            if master is not None:
                return master, False
            resolved = _sr()
            legacy_studio = Path.home() / ".unsloth" / "studio"
            try:
                is_legacy = resolved.resolve() == legacy_studio.resolve()
            except (OSError, ValueError):
                is_legacy = resolved == legacy_studio
            return (None if is_legacy else resolved), is_legacy
        except (ImportError, OSError, ValueError):
            return None, True

    @staticmethod
    def _find_llama_server_binary(*, include_denied: bool = False) -> Optional[str]:
        """Env LLAMA_SERVER_PATH, UNSLOTH_LLAMA_CPP_PATH, Unsloth folder setting, ~/.unsloth/llama.cpp, legacy ./llama.cpp, PATH, then legacy ./bin."""
        binary_name = "llama-server.exe" if sys.platform == "win32" else "llama-server"

        def _file_status(p: Path) -> str:
            # is_file() raises PermissionError when locked (Windows AV/ACL); never treat as missing.
            for _ in range(5):
                try:
                    if not p.is_file():
                        return "absent"
                    if sys.platform != "win32" and not os.access(p, os.X_OK):
                        return "non_executable"
                    return "file"
                except PermissionError:
                    time.sleep(0.2)
                except OSError:
                    return "absent"
            return "denied"

        def _is_file(p: Path) -> bool:
            return _file_status(p) == "file"

        def _layout_candidates(d: Path) -> list:
            # Settings validation and discovery share one layout contract, so any folder the UI accepts launches.
            from utils.llama_cpp_path_settings import llama_server_candidates
            return list(llama_server_candidates(d))

        def _unavailable(p: object) -> None:
            # Report an access-denied pinned binary instead of silently downgrading.
            logger.warning(
                f"llama-server at {p} is not executable or is access-denied "
                "(permissions, antivirus, or an in-flight install); not falling "
                "back to another binary, retry once it is available"
            )
            return None

        def _scan_pinned(paths: list):
            # First executable wins; access-denied stops, non-executable keeps looking; include_denied returns the unavailable path (diffusion only needs its dir).
            non_executable = None
            from utils.llama_cpp_path_settings import prefer_gpu_capable

            statuses = {p: _file_status(p) for p in paths}
            first = next((p for p in paths if statuses[p] == "file"), None)
            # A CPU-only first hit yields to a GPU-capable sibling, unless a denied one precedes it.
            if first is not None and not any(
                statuses[p] == "denied" for p in paths[: paths.index(first)]
            ):
                paths = prefer_gpu_capable(paths, lambda p: statuses[p] == "file")
            for p in paths:
                st = statuses[p]
                if st == "file":
                    return str(p), None
                if st == "denied":
                    return (str(p), None) if include_denied else (None, p)
                if st == "non_executable" and non_executable is None:
                    # A source checkout may leave a stale root entrypoint beside a valid CMake build; keep looking in this pinned layout, never fall through to another runtime.
                    non_executable = p
            if non_executable is not None:
                # A missing execute bit needs repair, not retry, so it must not pass preflight.
                return (None, None) if include_denied else (None, non_executable)
            return None, None

        # 1. Env var: direct path to binary
        env_path = os.environ.get("LLAMA_SERVER_PATH")
        if env_path:
            hit, locked = _scan_pinned([Path(env_path)])
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 1b. UNSLOTH_LLAMA_CPP_PATH: custom llama.cpp install dir
        custom_llama_cpp = os.environ.get("UNSLOTH_LLAMA_CPP_PATH")
        managed_path_marker = os.environ.get("UNSLOTH_STUDIO_MANAGED_LLAMA_CPP_PATH") == "1"
        if custom_llama_cpp and not managed_path_marker:
            # Expand ~ like every other reader; not Path.expanduser, which raises on unknown users.
            hit, locked = _scan_pinned(_layout_candidates(_expanded_user_path(custom_llama_cpp)))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 2. Unsloth setting: a deliberate pin, so never silently fall through to the bundle.
        try:
            from utils.llama_cpp_path_settings import get_stored_custom_llama_cpp_path
            studio_custom_llama_cpp = get_stored_custom_llama_cpp_path()
        except Exception:
            studio_custom_llama_cpp = None
        if studio_custom_llama_cpp is not None:
            hit, locked = _scan_pinned(_layout_candidates(studio_custom_llama_cpp))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit
            logger.warning(
                "The custom llama.cpp folder selected in Unsloth no longer contains "
                "%s; not falling back to another runtime",
                binary_name,
            )
            return None

        # 3-5. Env mode uses $STUDIO_HOME/llama.cpp; default or HOME-redirect uses ~/.unsloth/llama.cpp, the sibling of studio.
        legacy_llama = Path.home() / ".unsloth" / "llama.cpp"
        _resolved_sr, _is_legacy = LlamaCppBackend._resolved_studio_root_and_is_legacy()
        if _is_legacy:
            search_roots = [legacy_llama]
        else:
            # Must match _kill_orphaned_servers (excludes legacy root in custom mode), so we never spawn a server we then refuse to clean up.
            search_roots = [_resolved_sr / "llama.cpp"]
        for unsloth_home in search_roots:
            hit, locked = _scan_pinned(_layout_candidates(unsloth_home))
            if locked is not None:
                return _unavailable(locked)
            if hit:
                return hit

        # 5-6. Legacy in-tree build; a fallback, so a denied candidate just continues.
        project_root = Path(__file__).resolve().parents[4]
        from utils.llama_cpp_path_settings import prefer_gpu_capable

        for p in prefer_gpu_capable(_layout_candidates(project_root / "llama.cpp"), _is_file):
            if _is_file(p):
                return str(p)

        # 7. System PATH
        system_path = shutil.which("llama-server")
        if system_path:
            return system_path

        # 8. Legacy: extracted to bin/
        bin_path = project_root / "bin" / binary_name
        if _is_file(bin_path):
            return str(bin_path)

        return None

    # ── llama-server capability probe ─────────────────────────────
    # b10259..b10268 advertise draft-dspark but abort on load; match the base build number, gate only managed prebuilts (source builds carry no marker).
    _BROKEN_DSPARK_BUILDS = range(10259, 10269)

    @classmethod
    def _dspark_release_is_broken(cls, release_tag: Optional[str]) -> bool:
        match = re.match(r"b(\d+)", str(release_tag or ""))
        return bool(match) and int(match.group(1)) in cls._BROKEN_DSPARK_BUILDS

    # Keyed on (mtime_ns, size): updates replace the binary in place within the same second.
    _CAPABILITY_PROBE_RETRY_SECONDS = 30.0
    _CAPABILITY_PROBE_RETRY_MAX_SECONDS = 600.0
    _capability_cache: dict[tuple[str, int, int], dict[str, object]] = {}
    # (bin_path, mtime_ns, size) -> build number from `llama-server --version`, or None.
    _build_number_cache: dict[tuple[str, int, int], Optional[int]] = {}
    _capability_retry_after: dict[tuple[str, int, int], float] = {}
    _capability_retry_backoff: dict[tuple[str, int, int], float] = {}
    _capability_cache_lock = threading.Lock()

    # Older builds take a bare boolean -fa and exit on a following "on".
    _FLASH_ATTN_ENUM_RE = re.compile(
        r"(?im)^[^\n]*--flash-attn[^\n]*\bon\b[ \t]*\|[ \t]*\boff\b[^\n]*$"
    )

    @classmethod
    def _flash_attn_takes_value(cls, help_text: str) -> bool:
        """Fails open: a help text without --flash-attn keeps the value form, which the pinned
        prebuilt uses."""
        if not help_text or "--flash-attn" not in help_text:
            return True
        return bool(cls._FLASH_ATTN_ENUM_RE.search(help_text))

    # llama.cpp#23861 capped reserved output rows; older builds reserve one per ubatch token.
    _OUTPUT_ROWS_CAPPED_BUILD = 9460

    @classmethod
    def probe_build_number(cls, binary: Optional[str] = None) -> Optional[int]:
        """None for a missing binary, a failed probe, or build 1, which is a source build without tags."""
        bin_path = cls._exec_path_for_launch(binary or cls._find_llama_server_binary())
        if not bin_path or not Path(bin_path).is_file():
            return None
        try:
            binary_stat = Path(bin_path).stat()
            cache_key = (bin_path, binary_stat.st_mtime_ns, binary_stat.st_size)
        except OSError:
            cache_key = (bin_path, 0, 0)
        with cls._capability_cache_lock:
            if cache_key in cls._build_number_cache:
                return cls._build_number_cache[cache_key]
        build: Optional[int] = None
        try:
            env = cls._llama_server_env_for_binary(bin_path)
            if sys.platform == "darwin":
                env["GGML_METAL_DEVICES"] = "0"  # see probe_server_capabilities
            result = subprocess.run(
                [bin_path, "--version"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                check = False,
                env = env,
                **_windows_hidden_subprocess_kwargs(),
            )
            output = (result.stdout or "") + "\n" + (result.stderr or "")
            match = re.search(r"version:[^\r\n]*\bbuild\s+(\d+)\b", output) or re.search(
                r"version:\s*(\d+)\b(?!\.)", output
            )
            if match and int(match.group(1)) > 1:
                build = int(match.group(1))
        except Exception as exc:
            logger.debug("llama-server --version probe failed: %s", exc)
        with cls._capability_cache_lock:
            cls._build_number_cache[cache_key] = build
        return build

    @classmethod
    def reserves_micro_batch_outputs(cls, binary: Optional[str] = None) -> bool:
        """Builds before b9460, and the b9415 macOS fallback, reserve rows; unknown builds count as
        current."""
        try:
            build = cls.probe_build_number(binary)
        except Exception:
            return False
        return build is not None and build < cls._OUTPUT_ROWS_CAPPED_BUILD

    # ggml-org/llama.cpp#23089 added continuation inside an unfinished reasoning block.
    _THOUGHT_CONTINUATION_BUILD = 9200

    @classmethod
    def resumes_thoughts(cls, binary: Optional[str] = None) -> bool:
        """Whether this llama-server continues a trailing turn that holds only reasoning.

        Unknown builds are treated as current, matching Studio's prebuilts."""
        try:
            build = cls.probe_build_number(binary)
        except Exception:
            return True
        return build is None or build >= cls._THOUGHT_CONTINUATION_BUILD

    _ADVERTISED_DEFAULT_RE = re.compile(r"\(default:\s*(-?\d+)")

    @classmethod
    def _advertised_int_default(cls, help_block: Optional[str]) -> Optional[int]:
        """None means the build did not say; help wraps across columns, so the caller passes the
        joined text."""
        if not help_block:
            return None
        match = cls._ADVERTISED_DEFAULT_RE.search(help_block)
        return int(match.group(1)) if match else None

    @classmethod
    def probe_server_capabilities(cls, binary: Optional[str] = None) -> dict[str, object]:
        """Parse llama-server --help for flags; ngram_mod_flavor needs descriptions (legacy names are removal stubs); use the real exec path (SIP strips DYLD)."""
        bin_path = cls._exec_path_for_launch(binary or cls._find_llama_server_binary())
        if not bin_path or not Path(bin_path).is_file():
            return {
                "found": False,
                "mtp_token": None,
                "supports_mtp": False,
                "supports_dspark": False,
                "supports_dflash": False,
                "supports_eagle3": False,
                "mtp_probe_inconclusive": True,
                "ngram_mod_flavor": None,
                "supports_ngram_mod": False,
                "spec_draft_n_max_flag": None,
                "spec_draft_n_max_default": None,
                "supports_kv_unified": False,
                # Fail OPEN: these are emitted on every launch; only a positive absence drops one.
                "supports_no_context_shift": True,
                "supports_jinja": True,
                "supports_api_key_file": True,
                "supports_flash_attn": True,
                "flash_attn_takes_value": True,
                "supports_fit_ctx": False,
                "supports_fit_target": False,
                "fit_measures_borrowed_drafts": False,
                "supports_cache_ram": False,
                "supports_ctx_checkpoints": False,
                "ctx_checkpoints_flag": None,
                "ctx_checkpoints_default": None,
                "supports_no_cache_prompt": False,
                "supports_metrics": False,
                "supports_slot_save": False,
                "supports_reasoning_budget": False,
                "supports_reasoning_budget_message": False,
                "reasoning_budget_probe_inconclusive": True,
                # Fails CLOSED, unlike --jinja: a build without --reasoning exits on it.
                "supports_reasoning_flag": False,
                "supports_no_mmproj_offload": False,
                "supports_trace_verbosity": False,
                "supports_video_fps": False,
                "supports_video_timestamp_interval": False,
                "supports_load_mode": False,
                "supports_moe_cache": False,
                "supports_moe_cache_auto": False,
                "supports_lazy_mode": False,
                "lazy_mode_flag": None,
                "spec_draft_ngl_flag": None,
                "spec_draft_cache_k_flag": None,
                "spec_draft_cache_v_flag": None,
                "flags": {},
                "help_probe_ok": False,
            }
        try:
            binary_stat = Path(bin_path).stat()
            mtime_ns = binary_stat.st_mtime_ns
            size = binary_stat.st_size
        except OSError:
            mtime_ns = 0
            size = 0
        cache_key = (bin_path, mtime_ns, size)
        hit = None
        with cls._capability_cache_lock:
            cached = cls._capability_cache.get(cache_key)
            if cached is not None:
                retry_after = cls._capability_retry_after.get(cache_key)
                if not cached.get("mtp_probe_inconclusive") or (
                    retry_after is not None and time.monotonic() < retry_after
                ):
                    hit = cached
                else:
                    cls._capability_cache.pop(cache_key, None)
                    cls._capability_retry_after.pop(cache_key, None)
        if hit is not None:
            # A copy: the cached dict is shared across threads.
            if hit.get("supports_fit_target"):
                hit = {
                    **hit,
                    "fit_measures_borrowed_drafts": _fit_measures_borrowed_drafts(bin_path),
                }
            return hit

        mtp_token: Optional[str] = None
        supports_dspark = False
        supports_dflash = False
        supports_eagle3 = False
        ngram_mod_flavor: Optional[str] = None
        spec_draft_n_max_flag: Optional[str] = None
        spec_draft_n_max_default: Optional[int] = None
        supports_kv_unified = False
        supports_trace_verbosity = False
        # See the fallback dict: these fail open.
        supports_no_context_shift = True
        supports_jinja = True
        supports_api_key_file = True
        supports_flash_attn = True
        flash_attn_takes_value = True
        supports_fit_ctx = False
        supports_fit_target = False
        supports_cache_ram = False
        supports_ctx_checkpoints = False
        ctx_checkpoints_flag = None
        ctx_checkpoints_default = None
        supports_no_cache_prompt = False
        supports_metrics = False
        supports_slot_save = False
        supports_reasoning_budget = False
        supports_reasoning_budget_message = False
        supports_reasoning_flag = False
        supports_no_mmproj_offload = False
        supports_video_fps = False
        supports_video_timestamp_interval = False
        supports_load_mode = False
        supports_moe_cache = False
        supports_moe_cache_auto = False
        supports_lazy_mode = False
        lazy_mode_flag = None
        spec_draft_ngl_flag = None
        spec_draft_cache_k_flag = None
        spec_draft_cache_v_flag = None
        saw_spec_type = False
        probe_ok = False
        help_text = ""
        # Pre-initialised: a failed probe must fall back to nothing known, not raise.
        blocks: dict[str, str] = {}
        # Out here: a timed-out probe skips the loop but the catalogue is still built.
        takes_value: dict[str, bool] = {}

        def _is_real(flag: str) -> bool:
            """True if the flag exists AND is not a removal stub."""
            desc = blocks.get(flag)
            if desc is None:
                return False
            return "argument has been removed" not in desc

        try:
            probe_env = cls._llama_server_env_for_binary(bin_path)
            # Describe the binary, not the user's LLAMA_ARG_* defaults.
            for name in tuple(probe_env):
                if name.startswith("LLAMA_ARG_"):
                    probe_env.pop(name, None)
            if sys.platform == "darwin":
                # --help would otherwise init Metal and compile shaders, exceeding the timeout.
                probe_env["GGML_METAL_DEVICES"] = "0"
            code_integrity_blocked: Optional[str] = None
            result = subprocess.run(
                [bin_path, "--help"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                check = False,
                env = probe_env,
                # Else the probe flashes a console window on every status poll.
                **_windows_hidden_subprocess_kwargs(),
            )
            probe_ok = result.returncode == 0
            help_text = (result.stdout or "") + "\n" + (result.stderr or "")
            if not probe_ok:
                # The loader kills the process: NTSTATUS arrives as the return code or in output.
                code_integrity_blocked = code_integrity_block_reason(
                    result.returncode
                ) or code_integrity_block_reason(help_text)
                if code_integrity_blocked is not None:
                    logger.warning(
                        "llama-server is blocked by Windows code integrity policy: "
                        f"{code_integrity_blocked}. Binary: {bin_path}"
                    )
            # One block per flag, so a removed-argument description stays with its flag.
            current_flags: list[str] = []
            current_desc: list[str] = []
            # Flag -> whether its declaration shows a value placeholder.
            current_takes_value = False
            for line in help_text.splitlines():
                stripped = line.strip()
                if stripped.startswith("-") and not line.startswith(" "):
                    # New flag line; flush previous.
                    if current_flags:
                        desc = " ".join(current_desc)
                        for f in current_flags:
                            blocks[f] = desc
                            takes_value[f] = current_takes_value
                    current_flags = []
                    current_desc = [stripped]
                    # A placeholder follows its flag by a single space; the description sits 2+ spaces away.
                    current_takes_value = False
                    _previous_end = None
                    for _match in re.finditer(r"\S+", stripped):
                        _token = _match.group()
                        _flag_shaped = _token.startswith("-") and re.match(
                            r"-{1,2}[A-Za-z][A-Za-z0-9_-]*,?$", _token
                        )
                        if _flag_shaped:
                            _previous_end = _match.end()
                            continue
                        # The first non-alias token: a value placeholder when one space away, otherwise the description.
                        current_takes_value = (
                            _previous_end is not None and _match.start() - _previous_end == 1
                        )
                        break
                    # Declaration prefix only, so flag references in descriptions are ignored.
                    for tok in re.split(r"[,\s]+", stripped):
                        if tok.startswith("--") and re.match(r"--[A-Za-z][A-Za-z0-9_-]*$", tok):
                            current_flags.append(tok)
                        elif tok.startswith("-") and re.match(r"-[A-Za-z][A-Za-z0-9_-]*$", tok):
                            # Short aliases kept: the editor validates typed flags like -t against them.
                            current_flags.append(tok)
                        elif tok.startswith("-") and len(tok) > 1:
                            # A value placeholder like -1; keep scanning aliases.
                            continue
                        else:
                            # First non-flag token marks end of decl.
                            break
                else:
                    current_desc.append(stripped)
            if current_flags:
                desc = " ".join(current_desc)
                for f in current_flags:
                    blocks[f] = desc
                    takes_value[f] = current_takes_value

            # Read the full --spec-type block, since some builds put the enum on the next line; prefer draft-mtp over mtp.
            spec_help = blocks.get("--spec-type") or ""
            if not spec_help:
                # Fallback: join --spec-type lines, avoiding incidental "mtp" in --help.
                spec_help = "\n".join(
                    line for line in help_text.splitlines() if "--spec-type" in line
                )
            mtp_token = cls._mtp_token_from_spec_help(spec_help)
            supports_dspark = bool(
                re.search(
                    r"(?<![a-z0-9_-])draft-dspark(?![a-z0-9_-])",
                    spec_help.lower(),
                )
            )
            supports_eagle3 = bool(
                re.search(r"(?<![a-z0-9_-])draft-eagle3(?![a-z0-9_-])", spec_help.lower())
            )
            # Same word-boundary match as DSpark: draft-dflash only exists on
            # builds that carry the arch, and emitting a --spec-type the binary
            # does not know aborts the launch instead of falling back.
            supports_dflash = bool(
                re.search(
                    r"(?<![a-z0-9_-])draft-dflash(?![a-z0-9_-])",
                    spec_help.lower(),
                )
            )
            # Only a resolved --spec-type block confirms missing MTP; otherwise fail open.
            saw_spec_type = bool(spec_help.strip()) and "--spec-type" in spec_help

            # Post-rename builds keep legacy args as stubs; pre-rename ones only have legacy.
            new_ngram_real = (
                _is_real("--spec-ngram-mod-n-match")
                and _is_real("--spec-ngram-mod-n-min")
                and _is_real("--spec-ngram-mod-n-max")
            )
            legacy_ngram_real = (
                _is_real("--spec-ngram-size-n")
                and _is_real("--draft-max")
                and _is_real("--draft-min")
            )
            if new_ngram_real:
                ngram_mod_flavor = "new"
            elif legacy_ngram_real:
                ngram_mod_flavor = "legacy"

            # n_max flag: prefer post-rename, fall back to legacy.
            if _is_real("--spec-draft-n-max"):
                spec_draft_n_max_flag = "--spec-draft-n-max"
            elif _is_real("--draft-max"):
                spec_draft_n_max_flag = "--draft-max"
            # The build's own default depth, needed when extras own --spec-type: the child runs on it and the Hybrid Mamba rollback reserve scales by it.
            if spec_draft_n_max_flag:
                _n_max_default = re.search(
                    r"default:\s*(\d+)", blocks.get(spec_draft_n_max_flag) or ""
                )
                if _n_max_default:
                    spec_draft_n_max_default = int(_n_max_default.group(1))

            supports_kv_unified = _is_real("--kv-unified")
            # Fails closed: an older build's level 4 may be per-token debug on the decode path.
            supports_trace_verbosity = bool(
                probe_ok
                and _is_real("--verbosity")
                and _TRACE_VERBOSITY_HELP_RE.search(blocks.get("--verbosity") or "")
            )
            # Empty or failed --help must never read as absent for a flag we always send.
            if probe_ok and blocks:
                supports_no_context_shift = _is_real("--no-context-shift")
                supports_jinja = _is_real("--jinja")
                supports_api_key_file = _is_real("--api-key-file")
                # Two answers, not one: whether the flag exists, and whether its
                # declaration takes a value. A build predating flash attention
                # has neither, and emitting the flag there is an immediate exit.
                supports_flash_attn = _is_real("--flash-attn")
                flash_attn_takes_value = cls._flash_attn_takes_value(help_text)
            supports_fit_ctx = _is_real("--fit-ctx")
            supports_fit_target = _is_real("--fit-target")
            supports_cache_ram = _is_real("--cache-ram")
            # --swa-checkpoints is the older alias; probing only the modern name drops the Checkpoints control on old builds, so record which name this build has.
            for _alias in ("--ctx-checkpoints", "--swa-checkpoints"):
                if _is_real(_alias):
                    ctx_checkpoints_flag = _alias
                    break
            supports_ctx_checkpoints = ctx_checkpoints_flag is not None
            # The default was 3 on older builds, so a hardcoded 32 would raise their count.
            if ctx_checkpoints_flag:
                ctx_checkpoints_default = cls._advertised_int_default(
                    blocks.get(ctx_checkpoints_flag)
                )
            supports_no_cache_prompt = _is_real("--no-cache-prompt")
            supports_metrics = _is_real("--metrics")
            supports_slot_save = _is_real("--slot-save-path")
            supports_reasoning_budget = _is_real("--reasoning-budget")
            supports_reasoning_budget_message = _is_real("--reasoning-budget-message")
            # Catalogue, not help text: --reasoning-format / -budget / -preserve contain it.
            supports_reasoning_flag = _is_real("--reasoning")
            supports_no_mmproj_offload = _is_real("--no-mmproj-offload")
            supports_video_fps = _is_real("--video-fps")
            supports_video_timestamp_interval = _is_real("--video-timestamp-interval")
            # --load-mode supersedes --mlock / --no-mmap, which are deprecated.
            # Pre-initialised above: a failed probe must fall back, not raise.
            supports_load_mode = _is_real("--load-mode")
            # "auto" is a fork addition; upstream builds exit on it, so fail closed.
            supports_moe_cache = bool(probe_ok and _is_real("--moe-cache-mib"))
            supports_moe_cache_auto = bool(
                supports_moe_cache
                and re.search(
                    r"(?<![a-z0-9_-])auto(?![a-z0-9_-])",
                    (blocks.get("--moe-cache-mib") or "").lower(),
                )
            )
            if probe_ok:
                lazy_mode_flag = next(
                    (f for f in ("--lazy-mode", "--tensor-read-lazy") if _is_real(f)), None
                )
            supports_lazy_mode = lazy_mode_flag is not None
            # Record WHICH alias this build has: --spec-draft-ngl only landed in
            # b8955, and a build exposing only --gpu-layers-draft would refuse to
            # start on the newer name. Long forms only, since the block parser above
            # skips short aliases, so "-ngld" could never have matched.
            for _alias in ("--spec-draft-ngl", "--gpu-layers-draft", "--n-gpu-layers-draft"):
                if _is_real(_alias):
                    spec_draft_ngl_flag = _alias
                    break
            # Draft cache K and V are probed separately, since builds may carry only one flag
            # spelling.
            for _alias in ("--spec-draft-type-k", "--cache-type-k-draft"):
                if _is_real(_alias):
                    spec_draft_cache_k_flag = _alias
                    break
            for _alias in ("--spec-draft-type-v", "--cache-type-v-draft"):
                if _is_real(_alias):
                    spec_draft_cache_v_flag = _alias
                    break
        except (OSError, subprocess.SubprocessError) as exc:
            blocked = code_integrity_block_reason(exc)
            code_integrity_blocked = blocked
            if blocked is not None:
                # Warning, not debug: the only other symptom is a silent probe.
                logger.warning(
                    f"llama-server is blocked by Windows code integrity policy: {blocked}. "
                    f"Binary: {bin_path}"
                )
            else:
                logger.debug(f"llama-server --help probe failed: {exc}")
            saw_spec_type = False
            probe_ok = False
            help_text = ""

        help_nonempty = bool(help_text.strip())
        # Confirmed only by a successful --help with an MTP --spec-type block.
        if saw_spec_type and probe_ok:
            supports_mtp = mtp_token is not None
            mtp_probe_inconclusive = False
        elif help_nonempty and probe_ok:
            supports_mtp = False
            mtp_probe_inconclusive = False
        else:
            supports_mtp = False
            mtp_probe_inconclusive = True

        if supports_dspark:
            try:
                from utils.llama_cpp_freshness import read_install_marker

                marker = read_install_marker(bin_path) or {}
                release_tag = marker.get("release_tag") or marker.get("tag")
                if cls._dspark_release_is_broken(release_tag):
                    supports_dspark = False
                    logger.info(
                        "Disabling DSpark for known-broken llama.cpp prebuilt %s",
                        release_tag,
                    )
            except Exception as exc:
                logger.debug("Could not inspect llama.cpp prebuilt identity: %s", exc)

        info = {
            "found": True,
            "mtp_token": mtp_token,
            "supports_mtp": supports_mtp,
            "supports_dspark": bool(supports_dspark and saw_spec_type and probe_ok),
            "supports_dflash": bool(supports_dflash and saw_spec_type and probe_ok),
            "supports_eagle3": bool(supports_eagle3 and saw_spec_type and probe_ok),
            "mtp_probe_inconclusive": mtp_probe_inconclusive,
            "ngram_mod_flavor": ngram_mod_flavor,
            "supports_ngram_mod": ngram_mod_flavor is not None,
            "spec_draft_n_max_flag": spec_draft_n_max_flag,
            "spec_draft_n_max_default": spec_draft_n_max_default,
            "supports_kv_unified": supports_kv_unified,
            "supports_no_context_shift": supports_no_context_shift,
            "supports_jinja": supports_jinja,
            "supports_api_key_file": supports_api_key_file,
            "supports_flash_attn": supports_flash_attn,
            "flash_attn_takes_value": flash_attn_takes_value,
            "supports_fit_ctx": supports_fit_ctx,
            "supports_fit_target": supports_fit_target,
            "fit_measures_borrowed_drafts": supports_fit_target
            and _fit_measures_borrowed_drafts(bin_path),
            "supports_cache_ram": supports_cache_ram,
            "supports_ctx_checkpoints": supports_ctx_checkpoints,
            "ctx_checkpoints_flag": ctx_checkpoints_flag,
            "ctx_checkpoints_default": ctx_checkpoints_default,
            "supports_no_cache_prompt": supports_no_cache_prompt,
            "supports_metrics": supports_metrics,
            "supports_slot_save": supports_slot_save,
            "supports_reasoning_budget": supports_reasoning_budget,
            "supports_reasoning_budget_message": supports_reasoning_budget_message,
            "reasoning_budget_probe_inconclusive": not (probe_ok and help_nonempty),
            "supports_reasoning_flag": supports_reasoning_flag,
            "supports_no_mmproj_offload": supports_no_mmproj_offload,
            "supports_trace_verbosity": supports_trace_verbosity,
            "supports_video_fps": supports_video_fps,
            "supports_video_timestamp_interval": supports_video_timestamp_interval,
            "supports_load_mode": supports_load_mode,
            "supports_moe_cache": supports_moe_cache,
            "supports_moe_cache_auto": supports_moe_cache_auto,
            "supports_lazy_mode": supports_lazy_mode,
            "lazy_mode_flag": lazy_mode_flag,
            "spec_draft_ngl_flag": spec_draft_ngl_flag,
            "spec_draft_cache_k_flag": spec_draft_cache_k_flag,
            "spec_draft_cache_v_flag": spec_draft_cache_v_flag,
            # Validate pass-through args against this build; removal stubs are excluded, since a stub reads as supported and the editor stays quiet on refused flags.
            "flags": {flag: desc for flag, desc in blocks.items() if _is_real(flag)},
            # Switch flags take no value, so the editor can reject '--verbose foo' that llama-server refuses.
            "switch_flags": sorted(
                flag for flag, takes in takes_value.items() if not takes and _is_real(flag)
            ),
            # A nonzero exit can leave a partial catalogue.
            "help_probe_ok": bool(probe_ok),
        }
        with cls._capability_cache_lock:
            published = cls._capability_cache.get(cache_key)
            if published is not None and (
                not published.get("mtp_probe_inconclusive") or mtp_probe_inconclusive
            ):
                # Callers may finish out of order; never replace a conclusive result with a weaker one.
                return published
            cls._capability_cache[cache_key] = info
            if mtp_probe_inconclusive:
                # Do not pin transient failures forever or repeat timeouts; double only confirmed blocks, else busy machines get stuck on stale caps.
                if code_integrity_blocked is not None:
                    delay = cls._capability_retry_backoff.get(
                        cache_key, cls._CAPABILITY_PROBE_RETRY_SECONDS
                    )
                    cls._capability_retry_backoff[cache_key] = min(
                        delay * 2.0, cls._CAPABILITY_PROBE_RETRY_MAX_SECONDS
                    )
                else:
                    delay = cls._CAPABILITY_PROBE_RETRY_SECONDS
                    cls._capability_retry_backoff.pop(cache_key, None)
                cls._capability_retry_after[cache_key] = time.monotonic() + delay
            else:
                cls._capability_retry_after.pop(cache_key, None)
                cls._capability_retry_backoff.pop(cache_key, None)
            return info

    @classmethod
    def validate_reasoning_budget_capabilities(
        cls,
        binary: Optional[str],
        *,
        extra_args: Optional[Iterable[str]],
        reasoning_budget: int,
        reasoning_budget_message: str,
    ) -> dict[str, object]:
        """Reject configured reasoning flags before a live swap; explicit config only, since LLAMA_ARG_THINK_BUDGET* is machine-wide and no Studio control clears it."""
        effective_budget = resolve_reasoning_budget(extra_args, reasoning_budget)
        effective_message = resolve_reasoning_budget_message(extra_args, reasoning_budget_message)
        needs_budget, needs_message = cls.reasoning_budget_settings_requested(
            extra_args = extra_args,
            reasoning_budget = effective_budget,
            reasoning_budget_message = effective_message,
        )
        if not needs_budget and not needs_message:
            return cls.probe_server_capabilities(binary) if binary else {}
        if not binary:
            raise ValueError(
                "Reasoning budget settings require a llama-server runtime. "
                "Install or update llama.cpp, then try again."
            )

        caps = cls.probe_server_capabilities(binary)
        missing = []
        if needs_budget and not caps.get("supports_reasoning_budget"):
            missing.append("--reasoning-budget")
        if needs_message and not caps.get("supports_reasoning_budget_message"):
            missing.append("--reasoning-budget-message")
        if missing:
            verdict = (
                "could not verify support for"
                if caps.get("reasoning_budget_probe_inconclusive")
                else "does not support"
            )
            raise ValueError(
                f"llama-server at {binary} {verdict} {', '.join(missing)}. "
                "Update llama.cpp or clear the Reasoning Budget settings."
            )
        if needs_budget and effective_budget > 0:
            value_key = f"supports_reasoning_budget_value:{effective_budget}"
            if value_key not in caps:
                probe_binary = cls._exec_path_for_launch(binary)
                probe_env = cls._llama_server_env_for_binary(probe_binary)
                # llama-server parses LLAMA_ARG_* before argv, so clear stale inherited values.
                for name in tuple(probe_env):
                    if name.startswith("LLAMA_ARG_"):
                        probe_env.pop(name, None)
                if sys.platform == "darwin":
                    probe_env["GGML_METAL_DEVICES"] = "0"
                try:
                    result = subprocess.run(
                        [probe_binary, "--reasoning-budget", str(effective_budget), "--help"],
                        capture_output = True,
                        text = True,
                        encoding = "utf-8",
                        errors = "replace",
                        timeout = 10,
                        check = False,
                        env = probe_env,
                    )
                    caps[value_key] = result.returncode == 0
                except (OSError, subprocess.SubprocessError):
                    caps[value_key] = False
            if not caps[value_key]:
                raise ValueError(
                    f"llama-server at {binary} does not accept positive reasoning budgets. "
                    "Update llama.cpp, use 0 or -1, or clear the Reasoning Budget setting."
                )
        return caps

    @staticmethod
    def reasoning_budget_settings_requested(
        *, extra_args: Optional[Iterable[str]], reasoning_budget: int, reasoning_budget_message: str
    ) -> tuple[bool, bool]:
        budget_override = parse_reasoning_budget_override(extra_args)
        message_override = parse_reasoning_budget_message_override(extra_args)
        return (
            reasoning_budget != -1 or budget_override is not None,
            bool(reasoning_budget_message) or message_override is not None,
        )

    @staticmethod
    def _mtp_token_from_spec_help(spec_help: str) -> Optional[str]:
        """Prefers draft-mtp over the later bare mtp rename; None when neither is a --spec-type enum
        value."""
        text = spec_help or ""
        if "draft-mtp" in text:
            return "draft-mtp"
        # Bare `mtp` enum token (`|mtp|`, `,mtp,`, ...), not a substring.
        if re.search(r"(?<![A-Za-z0-9_-])mtp(?![A-Za-z0-9_-])", text):
            return "mtp"
        return None

    # ── GPU allocation ────────────────────────────────────────────

    @staticmethod
    def _get_gguf_size_bytes(model_path: str) -> int:
        """Total GGUF size in bytes, including split shards."""
        main = Path(model_path)
        total = main.stat().st_size

        # Check for split shards (e.g. model-00001-of-00003.gguf)
        m = _SHARD_FULL_RE.match(main.name)
        if m:
            prefix, _, num_total = m.group(1), m.group(2), m.group(3)
            sibling_pat = re.compile(
                r"^" + re.escape(prefix) + r"-\d{5}-of-" + re.escape(num_total) + r"\.gguf$",
                re.IGNORECASE,
            )
            for sibling in main.parent.iterdir():
                if sibling != main and sibling_pat.match(sibling.name):
                    total += sibling.stat().st_size

        return total

    @staticmethod
    def _gguf_scan_tensor_bytes(
        path: str, also: Optional[Callable[[str], bool]] = None
    ) -> "tuple[Optional[str], dict[str, int], int]":
        """(architecture, lazy-read candidate bytes by name, routed expert bytes) from one
        GGUF header. Streamed: ``GGUFReader`` materialises the vocabulary under the load
        lock. A quant type gguf predates is sized from the next tensor's offset. Names
        ``also`` accepts are kept by name too, routed experts included."""
        from gguf.constants import GGML_QUANT_SIZES
        from core.inference.offload_layout import _BLOCK_RE, _MOE_EXPERT_RE

        wanted = {name.encode() for names in _LAZY_READ_TENSORS.values() for name in names}
        architecture: Optional[str] = None
        alignment = 32  # GGUF's default when general.alignment is absent
        named: dict[str, int] = {}
        experts = 0
        offsets: list[int] = []
        unsized: list[tuple[str, int]] = []
        with open(path, "rb") as f:
            if struct.unpack("<I", f.read(4))[0] != 0x46554747:  # b"GGUF"
                return None, {}, 0
            # Version 1 used 32-bit counts and lengths, which this layout misreads.
            if struct.unpack("<I", f.read(4))[0] < 2:
                return None, {}, 0
            n_tensors, n_kv = struct.unpack("<QQ", f.read(16))
            for _ in range(n_kv):
                key = f.read(struct.unpack("<Q", f.read(8))[0])
                value_type = struct.unpack("<I", f.read(4))[0]
                if key == b"general.architecture" and value_type == 8:
                    raw = f.read(struct.unpack("<Q", f.read(8))[0])
                    architecture = raw.decode("utf-8", "replace")
                    continue
                if key == b"general.alignment" and value_type == 4:
                    alignment = max(1, struct.unpack("<I", f.read(4))[0])
                    continue
                LlamaCppBackend._gguf_skip_value(f, value_type)
            for _ in range(n_tensors):
                raw_name = f.read(struct.unpack("<Q", f.read(8))[0])
                n_dims = struct.unpack("<I", f.read(4))[0]
                dims = struct.unpack(f"<{n_dims}Q", f.read(8 * n_dims))
                ggml_type = struct.unpack("<I", f.read(4))[0]
                offset = struct.unpack("<Q", f.read(8))[0]
                offsets.append(offset)
                name = raw_name.decode("utf-8", "replace")
                block_match = _BLOCK_RE.match(name)
                is_expert = bool(block_match and _MOE_EXPERT_RE.match(block_match.group(2)))
                kept = also is not None and also(name)
                if not is_expert and raw_name not in wanted and not kept:
                    continue
                block = GGML_QUANT_SIZES.get(ggml_type)
                if block is None:
                    unsized.append((name, offset))
                    continue
                size = math.prod(dims) // block[0] * block[1]
                if is_expert:
                    experts += size
                if not is_expert or kept:
                    named[name] = size
            if unsized:
                data_start = -(-f.tell() // alignment) * alignment
                data_end = max(0, os.path.getsize(path) - data_start)
                ordered = sorted(offsets)
                for name, offset in unsized:
                    later = ordered[bisect.bisect_right(ordered, offset) :]
                    size = max(0, (later[0] if later else data_end) - offset)
                    block_match = _BLOCK_RE.match(name)
                    is_expert = bool(block_match and _MOE_EXPERT_RE.match(block_match.group(2)))
                    if is_expert:
                        experts += size
                    if not is_expert or (also is not None and also(name)):
                        named[name] = size
        return architecture, named, experts

    def _gguf_tensor_scan(
        self, model_path: Optional[str]
    ) -> "Optional[tuple[Optional[str], dict[str, int], int]]":
        """``_gguf_scan_tensor_bytes`` over every shard, cached per file identity; None
        when a shard is missing or unreadable."""
        from core.inference.offload_layout import split_shard_paths

        if not model_path:
            return None
        paths = split_shard_paths(model_path) or [model_path]
        try:
            key = tuple((p, st.st_size, st.st_mtime_ns) for p in paths for st in (os.stat(p),))
        except OSError:
            return None
        cached = getattr(self, "_gguf_tensor_scan_cache", None)
        if cached is not None and cached[0] == key:
            return cached[1]
        try:
            architecture: Optional[str] = None
            named: dict[str, int] = {}
            experts = 0
            for p in paths:
                arch, part, part_experts = self._gguf_scan_tensor_bytes(
                    p, also = _is_host_input_or_head_tensor
                )
                # Shard 1 carries the metadata.
                architecture = architecture or arch
                for name, size in part.items():
                    named[name] = named.get(name, 0) + size
                experts += part_experts
            result = (architecture, named, experts)
        except Exception as e:  # unreadable or truncated: discount nothing
            logger.debug("GGUF tensor scan failed for %s (%s)", model_path, e)
            result = None
        self._gguf_tensor_scan_cache = (key, result)
        return result

    def _unloaded_nextn_bytes(self, model_path: Optional[str]) -> int:
        """Bytes of the embedded NextN/MTP blocks llama.cpp leaves unloaded without
        ``--spec-type draft-mtp`` (nextn_flags marks them TENSOR_SKIP unless load_mtp).
        Only for architectures measured to skip them; 0 when unknown or unreadable."""
        from core.inference.offload_layout import _BLOCK_RE, split_shard_paths

        nextn = int(getattr(self, "_nextn_predict_layers", None) or 0)
        n_blocks = int(getattr(self, "_n_layers", None) or 0)
        if (
            not model_path
            or nextn <= 0
            or n_blocks <= nextn
            or getattr(self, "_architecture", None) not in _NEXTN_SKIPPED_WITHOUT_MTP_ARCHS
        ):
            return 0
        first = n_blocks - nextn

        def in_head(name: str) -> bool:
            match = _BLOCK_RE.match(name)
            return bool(match) and int(match.group(1)) >= first

        try:
            return sum(
                size
                for p in (split_shard_paths(model_path) or [model_path])
                for name, size in self._gguf_scan_tensor_bytes(p, also = in_head)[1].items()
                if in_head(name)
            )
        except Exception as e:  # missing shard or truncated header: discount nothing
            logger.debug("NextN block scan failed for %s (%s)", model_path, e)
            return 0

    def _lazy_read_host_bytes(
        self,
        model_path: Optional[str],
        *,
        caps: Optional[Mapping[str, object]],
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        auto_resolves_off: bool = False,
    ) -> int:
        """Bytes llama.cpp leaves mmap'd from disk under every load mode (``_LAZY_READ_TENSORS``);
        zero without lazy-read support, under ``off``, or on an unreadable header.
        ``auto_resolves_off``: llama.cpp turns ``auto`` into ``off`` for these devices."""
        if not model_path or not (caps or {}).get("supports_lazy_mode"):
            return 0
        mode = _effective_lazy_mode(
            extra_args, env, flag = str((caps or {}).get("lazy_mode_flag") or "--lazy-mode")
        )
        if mode == "off" or (mode == "auto" and auto_resolves_off):
            return 0
        scan = self._gguf_tensor_scan(model_path)
        if scan is None:
            return 0
        architecture, named, _experts = scan
        return _lazy_read_bytes(architecture, named, mode)

    def _lazy_auto_resolves_off(
        self,
        *,
        gpu_indices: Optional[Iterable[int]],
        detected_gpus: Optional[Iterable[tuple]],
        shared_gpu_ids: Optional[Iterable[int]],
        is_vulkan_backend: bool,
        probe_integrated_cuda: bool = True,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        device_list: Optional[bool] = None,
        tensor_parallel: Optional[bool] = None,
        integrated_gpu_ids: Optional[Iterable[int]] = None,
        child_gpu_order: Optional[Sequence[int]] = None,
    ) -> bool:
        """Whether llama.cpp resolves ``--lazy-mode auto`` to ``off`` for this child.

        ``child_gpu_order``: the ids the child's visibility mask will hold, in order
        (``_planned_child_gpu_order``), for a preview whose ``env`` does not carry that
        mask yet; a compact ``CUDA<k>`` / ``ROCm<k>`` names entry k of it."""
        tensor = (
            _effective_tensor_parallel(extra_args, False, env)
            if tensor_parallel is None
            else bool(tensor_parallel)
        )
        selected = None
        override = self._effective_device_ids(extra_args, env)
        one_device = not tensor and _split_mode_confines_to_one_device(extra_args, env)
        if one_device:
            main = self._effective_main_gpu(extra_args, env)
            main = 0 if main is None else main
            if main < 0:
                return False
        if override is not None and one_device:
            override = [d for d in override if d.lower() not in _CPU_DEVICE_VALUES]
            override = override[main : main + 1]
        if override is not None:
            # An RPC device reports mmap support (ggml-rpc.cpp device_get_props), so it never turns
            # auto off.
            gpu_names = [
                d
                for d in override
                if d.lower() not in _CPU_DEVICE_VALUES and not d.strip().lower().startswith("rpc")
            ]
            ordinals = [self._device_ordinal(d) for d in gpu_names]
            if all(o is not None for o in ordinals):
                if child_gpu_order is not None and not is_vulkan_backend:
                    _order = [int(i) for i in child_gpu_order]
                    selected = [_order[o] for o in ordinals if 0 <= o < len(_order)] or _order
                else:
                    selected = list(self._physical_ordinals(ordinals, env, is_vulkan_backend) or ())
        elif tensor or (device_list if device_list is not None else is_vulkan_backend):
            try:
                selected = list(gpu_indices or ()) or None
            except TypeError:
                selected = None
            if selected is None and tensor:
                selected = [row[0] for row in (detected_gpus or ())] or None
        if selected is not None:
            if selected and override is None and one_device:
                main = self._effective_main_gpu(extra_args, env)
                main = 0 if main is None else main
                selected = selected[main : main + 1] if main >= 0 else []
            selected = set(selected)
            if not selected:
                return False
        if selected:
            if is_vulkan_backend:
                return bool(selected & (set(shared_gpu_ids or ()) | set(integrated_gpu_ids or ())))
            try:
                if selected & LlamaCppBackend._rocm_unified_memory_gpu_ids():
                    return True
            except Exception:
                pass
            if not probe_integrated_cuda and not self._integrated_cuda_probe_is_free():
                return False
            try:
                return bool(selected & LlamaCppBackend._integrated_cuda_gpu_ids())
            except Exception:
                return False
        rows = [(row[0], row[1]) for row in (detected_gpus or ())]
        if self._offload_target_shares_system_memory(
            is_vulkan_backend = is_vulkan_backend,
            shared_gpu_ids = shared_gpu_ids,
            detected_gpus = rows,
            gpu_indices = gpu_indices,
        ):
            return True
        if is_vulkan_backend:
            return False
        if not probe_integrated_cuda and not self._integrated_cuda_probe_is_free():
            return False
        return self._integrated_cuda_selection_is_all_shared(
            list(gpu_indices) if gpu_indices else None
        )

    def _child_runs_on_cpu(
        self,
        binary: Optional[str],
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]],
        *,
        cpu_forced: bool = False,
        tensor_parallel: Optional[bool] = None,
    ) -> bool:
        """Whether the child gets no model device (CPU build, CPU --device or forced CPU launch)."""
        if (
            cpu_forced
            or self._binary_ships_no_gpu_backend(binary, env)
            or _device_selection_is_cpu(extra_args, env)
        ):
            return True
        tensor = (
            _effective_tensor_parallel(extra_args, False, env)
            if tensor_parallel is None
            else bool(tensor_parallel)
        )
        # Split mode none with a negative main GPU clears the model's devices (src/llama.cpp).
        if not tensor and _split_mode_confines_to_one_device(extra_args, env):
            main = self._effective_main_gpu(extra_args, env)
            return main is not None and main < 0
        return False

    @staticmethod
    def _metal_placement_unset(
        extra_args: Optional[Iterable[str]], env: Optional[Mapping[str, str]], *, layers_fixed: bool
    ) -> bool:
        """Whether nothing but Studio places this Metal launch, so a measured discount may pin full
        offload."""
        source_env = os.environ if env is None else env
        return not (
            layers_fixed
            or _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
            or _env_fixes_gpu_layers(source_env)
            or _device_selection_is_cpu(extra_args, source_env)
            or _args_place_tensors_on_cpu(extra_args)
            or _env_places_tensors_on_cpu(source_env)
            or _extra_args_set_any_flag(extra_args, _FIT_CONTROL_FLAGS)
            or any(source_env.get(name) for name in _FIT_CONTROL_ENV_VARS)
            or fit_is_enabled_in(extra_args)
            # A pass-through adapter sits on the base tensor's buffer (llama-adapter.cpp:335) and
            # nothing here charges it: keep the discount unspent.
            or _sidecar_adapter_paths(extra_args)
        )

    @staticmethod
    def _host_forced_table_archs(binary: Optional[str] = None) -> frozenset[str]:
        """Archs whose table the build keeps on the host whatever -ot says; none if unreadable."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return frozenset()
        try:
            resolved = _resolve_llama_binary(binary)
            libs = sorted(
                p
                for p in resolved.parent.iterdir()
                if _LLAMA_SHARED_LIB_RE.match(p.name) and p.is_file()
            )
            key = tuple(
                (str(p), st.st_size, st.st_mtime_ns)
                for p in (libs or [resolved])
                for st in (p.stat(),)
            )
        except OSError:
            return frozenset()
        return _host_forced_in_files(key)

    def lookup_tables_stream_by_default(
        self,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        *,
        gpu_ids: Optional[Iterable[int]] = None,
        tensor_parallel: Optional[bool] = None,
    ) -> bool:
        """Whether a launch on this host leaves lazily read lookup tables on disk."""
        _env = dict(os.environ if env is None else env)
        try:
            binary = self._find_llama_server_binary()
            caps = self.probe_server_capabilities(binary)
            if not caps.get("supports_lazy_mode"):
                return False
            mode = _effective_lazy_mode(
                extra_args, _env, flag = str(caps.get("lazy_mode_flag") or "--lazy-mode")
            )
            if mode != "auto":
                return mode == "on"
            tensor = (
                _effective_tensor_parallel(extra_args, False, _env)
                if tensor_parallel is None
                else bool(tensor_parallel)
            )
            self._reconcile_split_mode_env(_env, tensor_parallel = tensor)
            cpu_child = self._child_runs_on_cpu(binary, extra_args, _env, tensor_parallel = tensor)
            vulkan = not cpu_child and self._is_vulkan_backend(binary)
            rows = []
            if not cpu_child:
                with _without_torch_gpu_probe():
                    rows = list(self._get_gpu_memory(binary, for_llama_server = True) or ())
                # An empty Vulkan inventory is a failed probe: it may be an iGPU, where auto is off.
                if not rows and (vulkan or _gpu_device_node_present()):
                    return False
            shared = {idx for idx, _free, total in rows if total <= 0} if vulkan else set()
            picked = [int(i) for i in gpu_ids] if gpu_ids else None
            return not self._lazy_auto_resolves_off(
                gpu_indices = picked,
                detected_gpus = [(idx, free) for idx, free, _total in rows],
                shared_gpu_ids = shared,
                is_vulkan_backend = vulkan,
                probe_integrated_cuda = False,
                extra_args = extra_args,
                env = _env,
                device_list = None if picked else False,
                tensor_parallel = tensor_parallel,
                integrated_gpu_ids = shared,
            )
        except Exception:
            return False

    def _managed_lazy_mode_flags(
        self,
        model_path: Optional[str],
        *,
        caps: Optional[Mapping[str, object]],
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        auto_resolves_off: bool = False,
        resident_fits: Callable[[int], Optional[bool]],
        binary: Optional[str] = None,
    ) -> list[str]:
        """``[<lazy flag>, "off"]`` to keep a lazily read lookup table resident, else ``[]``."""
        caps = caps or {}
        if not model_path or not caps.get("supports_lazy_mode"):
            return []
        flag = str(caps.get("lazy_mode_flag") or "--lazy-mode")
        source_env = os.environ if env is None else env
        flags, env_name = _LAZY_MODE_SPELLINGS.get(flag, (frozenset({flag}), ""))
        if (env_name and str(source_env.get(env_name) or "").strip()) or _extra_args_set_any_flag(
            extra_args, flags
        ):
            return []
        if auto_resolves_off:
            return []
        table = self._lazy_read_host_bytes(
            model_path, caps = caps, extra_args = extra_args, env = source_env
        )
        if table <= 0:
            return []
        scan = self._gguf_tensor_scan(model_path)
        if scan is None or (
            scan[0] not in self._host_forced_table_archs(binary)
            and any(
                _override_places_tensor_on_device(name, extra_args, source_env)
                for name in scan[1]
                if _is_per_layer_embedding(name)
            )
        ):
            return []
        try:
            fits = resident_fits(table)
        except Exception as e:  # noqa: BLE001 -- unpriced: keep llama.cpp's default
            logger.debug("Lookup tables: resident fit unpriced (%s)", e)
            fits = None
        key = (model_path, table, bool(fits))
        if getattr(self, "_lazy_mode_decision_logged", None) != key:
            self._lazy_mode_decision_logged = key
            if fits:
                logger.info(
                    "Lookup tables: keeping the %.1f GB lookup table in RAM (%s off); "
                    "free RAM covers it beside the weights and the KV cache.",
                    table / (1024**3),
                    flag,
                )
            else:
                logger.info(
                    "Lookup tables: streaming the %.1f GB lookup table from disk "
                    "(llama.cpp's lazy read); RAM cannot hold it beside the weights and "
                    "the KV cache. Prefill and decode can be slower and vary.",
                    table / (1024**3),
                )
        return [flag, "off"] if fits else []

    def _apple_lookup_table_discount(
        self,
        probe_discount: int,
        model_path: Optional[str],
        *,
        caps: Optional[Mapping[str, object]],
        extra_args: Optional[Iterable[str]],
        model_size_fit: int,
        need_at_ctx: Optional[int],
        budget_mib: int,
        cache_ram: Optional[int],
        env: Optional[Mapping[str, str]] = None,
        binary: Optional[str] = None,
        cpu_forced: bool = False,
    ) -> int:
        """The Metal embedding discount with the lazily read lookup table settled."""
        source_env = os.environ if env is None else env
        self._apple_lazy_flags = []
        table = self._lazy_read_host_bytes(
            model_path, caps = caps, extra_args = extra_args, env = source_env
        )
        if table <= 0:
            auto_table = self._lazy_read_host_bytes(model_path, caps = caps, extra_args = (), env = {})
            if (
                auto_table > 0
                and _effective_lazy_mode(
                    extra_args,
                    source_env,
                    flag = str((caps or {}).get("lazy_mode_flag") or "--lazy-mode"),
                )
                == "off"
            ):
                return max(0, int(probe_discount) - auto_table)
            return probe_discount
        if _sidecar_adapter_paths(extra_args):
            return probe_discount
        scan = self._gguf_tensor_scan(model_path)
        streamed = (
            _lazy_read_names(
                scan[0],
                scan[1],
                _effective_lazy_mode(
                    extra_args,
                    source_env,
                    flag = str((caps or {}).get("lazy_mode_flag") or "--lazy-mode"),
                ),
            )
            if scan is not None
            else frozenset()
        )
        if (
            scan is not None
            and scan[0] not in self._host_forced_table_archs(binary)
            and any(
                _override_places_tensor_on_device(name, extra_args, source_env)
                for name in scan[1]
                if _is_per_layer_embedding(name) and name not in streamed
            )
        ):
            return probe_discount

        def _resident_fits(table_bytes: int) -> Optional[bool]:
            if self._child_runs_on_cpu(binary, extra_args, source_env, cpu_forced = cpu_forced):
                return None
            if any(
                str(source_env.get(name) or "").strip()
                for name in ("LLAMA_ARG_MMPROJ", "LLAMA_ARG_MMPROJ_URL")
            ):
                return None
            avail = self._available_system_memory_mib()
            prompt = _prompt_cache_host_bytes(
                cache_ram,
                extra_args,
                source_env,
                supports_cache_ram = bool((caps or {}).get("supports_cache_ram")),
            )
            if (
                avail is None
                or prompt is None
                or need_at_ctx is None
                or budget_mib <= 0
                or not self._can_estimate_kv()
            ):
                return None
            need = (
                int(model_size_fit)
                + int(need_at_ctx)
                + int(prompt)
                + int(table_bytes * _LAZY_RESIDENT_MARGIN_FRAC)
            )
            ceiling_mib = min(int(budget_mib), int(avail) - _HOST_RAM_HEADROOM_MIB)
            return need <= max(0, ceiling_mib) * 1024 * 1024

        self._apple_lazy_flags = self._managed_lazy_mode_flags(
            model_path,
            caps = caps,
            extra_args = extra_args,
            env = source_env,
            resident_fits = _resident_fits,
            binary = binary,
        )
        if self._apple_lazy_flags:
            return max(0, int(probe_discount) - table)
        if table > probe_discount:
            logger.info(
                "Metal fit: %.2f GB of lookup tables are read lazily from disk, outside "
                "the Metal working set; not charged to unified memory.",
                table / (1024**3),
            )
        return max(int(probe_discount), table)

    @staticmethod
    def _installed_ggml_backends(binary: Optional[str] = None) -> frozenset[str]:
        """Backend libraries shipped beside llama-server."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return frozenset()
        try:
            files = tuple(path.name for path in _llama_lib_dir(binary).iterdir() if path.is_file())
        except OSError:
            return frozenset()
        backends = set()
        for backend in ("base", "cpu", "cuda", "hip", "vulkan"):
            stem = f"ggml-{backend}.dll" if sys.platform == "win32" else f"libggml-{backend}.so"
            if any(name == stem or name.startswith(stem + ".") for name in files):
                backends.add(backend)
        return frozenset(backends)

    def _record_memory_state(
        self,
        argv,
        env = None,
    ) -> None:
        """Record the ``(mlock, reserves_ram)`` a launch really runs with, and
        whether it streams, from ONE parse. A dozen paths record a state; a
        second parse at each of them would drift from this one."""
        mlock, reserves_ram, direct_io = resolve_effective_load_state(argv, env)
        self._memory_state = (mlock, reserves_ram)
        self._memory_direct_io = direct_io

    def _drop_managed_dio(
        self,
        argv,
        reason: str,
        clear_record: bool = True,
    ):
        """Strip Unsloth's own DirectIO pair unless full offload is confirmed (DirectIO reads CPU layers into buffers); never the user's --load-mode."""
        if not self._memory_dio_flags:
            self._memory_dio_applicable = False
            return argv
        # Strip only while this argv holds more pairs than the user wrote.
        if _count_subsequence(list(argv), self._memory_dio_flags) <= _count_subsequence(
            list(getattr(self, "_memory_dio_user_tokens", []) or []), self._memory_dio_flags
        ):
            if clear_record:
                self._memory_dio_flags = []
            self._memory_dio_applicable = False
            return argv
        stripped = _without_subsequence(argv, self._memory_dio_flags)
        if clear_record:
            self._memory_dio_flags = []
        self._memory_dio_applicable = False
        # A child equal to an unmanaged one must not be torn down when toggles go off.
        self._memory_policy_active = self._memory_policy_extras_touched
        logger.info("Model Memory: dropping the managed --load-mode dio; %s", reason)
        return stripped

    @staticmethod
    def _vulkan_offload_is_discrete(binary: Optional[str], gpu_indices = None) -> bool:
        """An unanswered probe declines, since an iGPU's VRAM is system RAM and DirectIO would be wrong."""
        try:
            rows = LlamaCppBackend._run_vulkan_probe(binary)
        except Exception:
            return False
        if not rows:
            return False
        wanted = set(gpu_indices) if gpu_indices else None
        selected = [r for r in rows if wanted is None or r["index"] in wanted]
        if not selected:
            return False
        # EVERY ordinal, not merely some: a partial intersection confirmed an unclassified one.
        if wanted is not None and wanted - {r["index"] for r in selected}:
            return False
        # The probe reports all-False when the type query fails, so require type_known.
        if not all(r.get("type_known") for r in selected):
            return False
        return not any(r["is_igpu"] for r in selected)

    @classmethod
    def _gpu_offload_confirmed(
        cls,
        binary: Optional[str],
        env: Optional[Mapping[str, str]],
        gpu_indices,
        host_resident: bool,
        dio_possible: bool,
        extra_args = None,
    ) -> bool:
        """Whether weights sit on a discrete GPU; unanswered decline (DirectIO over host RAM is worse than nothing); gate on dio_possible, never the toggle."""
        if not dio_possible or host_resident:
            return False
        devices = cls._enumerated_gpu_devices(binary, env)
        # A pass-through --device is appended last and decides placement; values are ggml ids.
        override = cls._effective_device_ids(extra_args, env)
        if override is not None:
            if any(d.lower() in _CPU_DEVICE_VALUES for d in override):
                return False
            listed = {d.lower() for d in (devices or [])}
            if not override or not {d.lower() for d in override} <= listed:
                return False
            gpu_indices = [
                cls._device_ordinal(d) for d in override if cls._device_ordinal(d) is not None
            ]
            devices = [d for d in (devices or []) if d.lower() in {o.lower() for o in override}]
        if not cls._offload_devices_are_live(devices, gpu_indices):
            return False
        # Check EVERY selected device; the first kind's verdict alone would pass a mixed set with an iGPU.
        selected = cls._selected_devices(devices, gpu_indices)
        backends = {cls._device_backend(d) for d in selected}
        if backends - {"vulkan"} - _SELF_EVIDENTLY_DISCRETE - _NEEDS_ROCM_CLASSIFICATION:
            return False
        # An AMD id only counts once something has actually looked at the device.
        if (backends & _NEEDS_ROCM_CLASSIFICATION) and not cls._rocm_classification_answered():
            return False
        if "vulkan" in backends:
            # Only the VULKAN ordinals: a CUDA target's 0 otherwise satisfies Vulkan row 0.
            vulkan_ordinals = [
                cls._device_ordinal(d) for d in selected if cls._device_backend(d) == "vulkan"
            ]
            if any(o is None for o in vulkan_ordinals):
                return False
            return cls._vulkan_offload_is_discrete(binary, vulkan_ordinals)
        return True

    @staticmethod
    def _device_ordinal(device: str) -> Optional[int]:
        """The trailing ordinal of a ggml device id, or None."""
        match = re.search(r"(\d+)$", device)
        return int(match.group(1)) if match else None

    @staticmethod
    def _compact_ordinals(
        gpu_indices,
        env: Optional[Mapping[str, str]],
        is_vulkan = False,
    ):
        """A mask reindexes survivors from 0, so a physical id's position in the mask is its compact
        ordinal."""
        if not gpu_indices or not env or is_vulkan:
            return gpu_indices
        # GGML_VK_VISIBLE_DEVICES omitted: ggml already compacts Vulkan ordinals.
        for name in ("HIP_VISIBLE_DEVICES", "ROCR_VISIBLE_DEVICES", "CUDA_VISIBLE_DEVICES"):
            raw = env.get(name)
            if not raw or not str(raw).strip():
                continue
            try:
                order = [int(part.strip()) for part in str(raw).split(",") if part.strip()]
            except ValueError:
                return gpu_indices
            if not order:
                return gpu_indices
            try:
                mapped = [order.index(int(i)) for i in gpu_indices if int(i) in order]
            except (TypeError, ValueError):
                return gpu_indices
            return mapped or gpu_indices
        return gpu_indices

    @staticmethod
    def _physical_ordinals(
        compact,
        env: Optional[Mapping[str, str]],
        is_vulkan = False,
    ):
        """--device takes compact ids but _amd_apu_wants_unified_memory needs physical ones, so map back."""
        if not compact or not env or is_vulkan:
            return compact
        for name in ("HIP_VISIBLE_DEVICES", "ROCR_VISIBLE_DEVICES", "CUDA_VISIBLE_DEVICES"):
            raw = env.get(name)
            if not raw or not str(raw).strip():
                continue
            try:
                order = [int(part.strip()) for part in str(raw).split(",") if part.strip()]
            except ValueError:
                return compact
            if not order:
                return compact
            try:
                mapped = [order[int(i)] for i in compact if 0 <= int(i) < len(order)]
            except (TypeError, ValueError):
                return compact
            return mapped or compact
        return compact

    @classmethod
    def _effective_main_gpu(cls, extra_args, env) -> Optional[int]:
        """--main-gpu may name a device outside the plan, so it replaces the selection, not narrowing it."""
        if not _split_mode_confines_to_one_device(extra_args, env):
            return None
        value = _extra_args_device(extra_args, {"--main-gpu", "-mg"})
        if value is None and env:
            value = env.get("LLAMA_ARG_MAIN_GPU")
        if value is None:
            return None
        try:
            return int(str(value).strip())
        except (TypeError, ValueError):
            return None

    @classmethod
    def _effective_gpu_selection(
        cls,
        binary,
        env,
        gpu_indices,
        extra_args,
        dio_possible = True,
        is_vulkan = False,
    ):
        """Returns (physical, compact), resolved once for all consumers so verdict and confirmation match; the APU check needs physical ids, --list-devices compact."""
        if not dio_possible:
            return gpu_indices, gpu_indices
        override = cls._effective_device_ids(extra_args, env)
        if override and not any(d.lower() in _CPU_DEVICE_VALUES for d in override):
            listed = {d.lower() for d in (cls._enumerated_gpu_devices(binary, env) or [])}
            if {d.lower() for d in override} <= listed:
                # `--device` names compact ids, so physical is the derived form.
                ordinals = [cls._device_ordinal(d) for d in override]
                compact = [o for o in ordinals if o is not None]
                if not compact:
                    return gpu_indices, cls._compact_ordinals(gpu_indices, env, is_vulkan)
                return cls._physical_ordinals(compact, env, is_vulkan), compact
            return gpu_indices, cls._compact_ordinals(gpu_indices, env, is_vulkan)
        # Otherwise PHYSICAL, and `--main-gpu` under `-sm none` replaces the selection.
        main_gpu = cls._effective_main_gpu(extra_args, env)
        if main_gpu is not None:
            # `--main-gpu` indexes the FILTERED list, so it too arrives compact.
            return cls._physical_ordinals([main_gpu], env, is_vulkan), [main_gpu]
        return gpu_indices, cls._compact_ordinals(gpu_indices, env, is_vulkan)

    @classmethod
    def _effective_device_ids(cls, extra_args, env) -> Optional[list[str]]:
        """Last argv value wins, then LLAMA_ARG_DEVICE, as llama.cpp does; values are ggml ids."""
        value = _extra_args_main_device(extra_args)
        if value is None and env:
            value = env.get("LLAMA_ARG_DEVICE")
        if value is None:
            return None
        return [d.strip() for d in str(value).split(",") if d.strip()]

    @staticmethod
    def _selected_devices(devices: Optional[list[str]], gpu_indices) -> list[str]:
        """The enumerated GPU devices this launch will use. ggml ids are
        ``<Backend><ordinal>``; the CPU device is not a placement target, and with no
        pin every GPU device is in play."""
        if not devices:
            return []
        gpu = [d for d in devices if not d.upper().startswith("CPU")]
        if not gpu_indices:
            return gpu
        wanted = {int(i) for i in gpu_indices}
        picked = []
        for device in gpu:
            match = re.search(r"(\d+)$", device)
            if match and int(match.group(1)) in wanted:
                picked.append(device)
        return picked

    @classmethod
    def _offload_devices_are_live(cls, devices: Optional[list[str]], gpu_indices) -> bool:
        """Ordinal coverage, not device count: a multi-backend build can list one ordinal twice."""
        selected = cls._selected_devices(devices, gpu_indices)
        if not selected:
            return False
        if not gpu_indices:
            return True
        covered = {cls._device_ordinal(d) for d in selected}
        return {int(i) for i in gpu_indices} <= covered

    @staticmethod
    def _device_backend(device: str) -> str:
        """The ggml backend behind a device id, lowercased. What `_is_vulkan_backend`
        and the plugin-root scan approximated from filenames: the build reports what it
        actually loaded, so an external ``GGML_BACKEND_PATH`` plugin names itself too."""
        return re.sub(r"\d+$", "", device).strip().lower()

    @classmethod
    def _devices_are_vulkan(cls, devices: Optional[list[str]], gpu_indices) -> bool:
        """Whether any device in play is a Vulkan one, read off the build's own ids."""
        return any(
            cls._device_backend(d) == "vulkan" for d in cls._selected_devices(devices, gpu_indices)
        )

    @classmethod
    def _enumerated_gpu_devices(
        cls,
        binary: Optional[str] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[list[str]]:
        """None means an old build, timeout or crash; [] is a real answer of no devices, and both
        decline."""
        binary = binary or cls._find_llama_server_binary()
        if not binary:
            return None
        key = (binary, cls._device_visibility_key(env))
        memo = _load_probe_memo_get("devices", key)
        if memo is not None:
            return None if memo is _MISSING else memo
        devices = cls._run_list_devices(binary, env)
        _load_probe_memo_put("devices", key, _MISSING if devices is None else devices)
        return devices

    @staticmethod
    def _device_visibility_key(env: Optional[Mapping[str, str]]):
        """What this environment lets the child see, as a memo key. A rung that masks
        an adapter has a different answer coming, and without this a narrowing onto a
        usable discrete GPU kept the original set's failure."""
        source = os.environ if env is None else env
        return tuple((name, source.get(name)) for name in _DEVICE_VISIBILITY_ENV)

    @staticmethod
    def _run_list_devices(
        binary: str, env: Optional[Mapping[str, str]] = None
    ) -> Optional[list[str]]:
        """``--list-devices`` once, parsed. The flag prints and exits, so this leaves no
        server behind; it is on the argv denylist for that reason, which does not apply
        to Unsloth calling it deliberately."""
        try:
            probe_env = LlamaCppBackend._llama_server_env_for_binary(binary)
        except Exception:
            probe_env = child_env_without_native_path_secret()
        # Probe must see the child env: replay only the caller's removals, not its whole mapping, since on Windows the venv CUDA runtime is added to PATH.
        if env is not None:
            # BOTH directions: removals alone dropped a narrowing rung's new mask.
            for name in _DEVICE_VISIBILITY_ENV:
                if name in env:
                    probe_env[name] = env[name]
                else:
                    probe_env.pop(name, None)
            for name in list(probe_env):
                if name not in env and name in os.environ:
                    probe_env.pop(name, None)
        try:
            result = subprocess.run(
                [binary, "--list-devices"],
                capture_output = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 30,
                env = utf8_child_env(probe_env),
                **_windows_hidden_subprocess_kwargs(),
            )
        except Exception as e:
            logger.debug(f"llama-server --list-devices failed: {e}")
            return None
        if result.returncode != 0:
            logger.debug(f"llama-server --list-devices exited {result.returncode}")
            return None
        return _parse_listed_devices(result.stdout)

    @staticmethod
    def _is_vulkan_backend(binary: Optional[str] = None) -> bool:
        """Vulkan build is identified by its ggml lib; a CUDA or HIP lib beside it defers to that
        backend."""
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        return "vulkan" in backends and not backends.intersection({"cuda", "hip"})

    _SYSMEM_FALLBACK_RISK: dict[Optional[str], bool] = {}

    @staticmethod
    def _sysmem_fallback_risk(binary: Optional[str] = None) -> bool:
        """True when over-budget allocations spill to host RAM; Windows CUDA only, no probe (integrated CUDA is Linux-only; a probe would pin a CUDA context)."""
        if sys.platform != "win32":
            return False
        if binary is None:
            try:
                binary = LlamaCppBackend._find_llama_server_binary()
            except Exception:  # noqa: BLE001 - classify with whatever the lib lookup resolves
                binary = None
        # Keyed by resolved path and build revision: runtimes switch, updates swap in place.
        key = LlamaCppBackend._binary_revision(binary) or binary
        cached = LlamaCppBackend._SYSMEM_FALLBACK_RISK.get(key)
        if cached is not None:
            return cached
        try:
            backends = LlamaCppBackend._installed_ggml_backends(binary)
        except Exception as e:  # noqa: BLE001 - an unreadable lib dir is not a load failure
            logger.debug("sysmem-fallback classification failed, keeping the base budget: %s", e)
            return False  # not cached: a transient read error must not pin False forever
        if not backends:
            return False  # an unreadable dir scans empty; same rule, not cached
        risk = "cuda" in backends
        LlamaCppBackend._SYSMEM_FALLBACK_RISK[key] = risk
        return risk

    @staticmethod
    def _active_gpu_visibility_mask() -> Optional[str]:
        """The raw visibility mask in force (HIP, then ROCR, then CUDA on ROCm; CUDA
        otherwise), or None when unset. Split out so a caller can tell "no mask" from
        "a mask I cannot map to physical ids"."""
        try:
            import torch

            # Same ROCm detection as _emit_child_gpu_visibility: if they differ an inherited ROCR mask reads as none and the child re-exposes hidden GPUs.
            is_rocm = LlamaCppBackend._torch_is_rocm(torch)
        except Exception:
            is_rocm = False
        if is_rocm:
            hip_v = os.environ.get("HIP_VISIBLE_DEVICES")
            # ROCR_VISIBLE_DEVICES is Linux-only: on Windows a stray ROCR var masks nothing and must not be read as the ordinal to physical mapping.
            rocr_v = None if sys.platform == "win32" else os.environ.get("ROCR_VISIBLE_DEVICES")
            cvd = (
                hip_v
                if hip_v is not None
                else rocr_v
                if rocr_v is not None
                else os.environ.get("CUDA_VISIBLE_DEVICES")
            )
        else:
            cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
        return cvd

    @staticmethod
    def _resolve_visible_physical_ids() -> Optional[list[int]]:
        """Physical GPU ids behind the active visibility mask (HIP/ROCR/CUDA on
        ROCm, CUDA otherwise). None when unset, [] for an empty mask. Shared by the
        APU / datacenter / free-memory probes so they agree on the mapping."""
        cvd = LlamaCppBackend._active_gpu_visibility_mask()
        if cvd is None:
            return None
        try:
            return [int(x.strip()) for x in cvd.split(",") if x.strip()]
        except ValueError:
            pass
        # A resolvable CUDA UUID mask, else the GPU auto-pick escapes the mask onto hidden cards (#8873).
        try:
            from utils.hardware.hardware import _get_parent_visible_gpu_spec
            spec = _get_parent_visible_gpu_spec()
        except Exception:
            return None
        if spec.get("index_kind") == "cuda_device":
            # R570+ MIG ids are CUDA devices; the MIG paths pin through the snapshot.
            return None
        return spec["numeric_ids"] if spec.get("raw") == cvd.strip() else None

    @staticmethod
    def _visibility_mask_is_unmappable() -> bool:
        """True if a mask is set but unresolvable (UUID or MIG): pinning callers fail open, since numbers would expose hidden cards. False if unset or empty."""
        return (
            LlamaCppBackend._active_gpu_visibility_mask() is not None
            and LlamaCppBackend._resolve_visible_physical_ids() is None
        )

    @staticmethod
    def _emit_child_gpu_visibility(
        env: dict,
        pinned: str,
        *,
        prefer_rocr: bool = False,
    ) -> None:
        """Default masks HIP, clearing inherited ROCR (they stack); prefer_rocr masks ROCR to avoid HSA segfaults; CPU -1 keeps masks so none re-expose hidden GPUs."""
        env["CUDA_VISIBLE_DEVICES"] = pinned
        if pinned == "-1":
            # An inherited LLAMA_ARG_DEVICE or LLAMA_ARG_MAIN_GPU naming a device that no longer enumerates makes llama.cpp exit rather than use CPU.
            LlamaCppBackend._clear_device_placement_env(env)
        try:
            import torch as _torch

            # AMD SDK wheels may leave torch.version.hip unset; also check 'rocm' in __version__.
            if (
                getattr(_torch.version, "hip", None) is not None
                or "rocm" in getattr(_torch, "__version__", "").lower()
            ):
                if prefer_rocr and pinned != "-1" and sys.platform != "win32":
                    env["ROCR_VISIBLE_DEVICES"] = pinned
                    env.pop("HIP_VISIBLE_DEVICES", None)
                    # ROCR re-indexes from 0 and HIP reads CUDA_VISIBLE_DEVICES here, so pass post-ROCR ordinals 0..N-1, not physical ids: else HIP sees 0 devices.
                    env["CUDA_VISIBLE_DEVICES"] = ",".join(
                        str(i) for i in range(len(pinned.split(",")))
                    )
                else:
                    env["HIP_VISIBLE_DEVICES"] = pinned
                    if pinned != "-1":
                        env.pop("ROCR_VISIBLE_DEVICES", None)
        except Exception as e:
            logger.debug("Failed to set ROCm visibility env vars for child: %s", e)

    @staticmethod
    def _unmasked_child_gpu_physical_ids() -> Optional[tuple[int, ...]]:
        from utils.hardware import get_parent_visible_gpu_ids

        parent_gpu_ids = get_parent_visible_gpu_ids()
        if len(parent_gpu_ids) == 1:
            return (int(parent_gpu_ids[0]),)
        return None

    @staticmethod
    def _inherited_child_gpu_order(pinned_ids: Iterable[int]) -> Optional[list[int]]:
        """Ids in parent mask order, or None if already that order or the mask is partial; numeric masks set device order, so re-emitting verbatim undoes it."""
        inherited = LlamaCppBackend._resolve_visible_physical_ids()
        if not inherited:
            # A uuid mask the ordinal resolvers leave open (FASTEST_FIRST) still orders
            # the cards the memory probe matched by uuid.
            inherited = LlamaCppBackend._smi_uuid_mask_order()
        if not inherited:
            return None
        wanted = [int(i) for i in pinned_ids]
        ordered = [i for i in inherited if i in set(wanted)]
        if sorted(ordered) != sorted(wanted) or ordered == wanted:
            return None
        return ordered

    @staticmethod
    def _picker_ordered_gpu_indices(gpu_ids, gpu_indices, tp_tensor_split):
        """``(gpu_indices, tp_tensor_split)`` in the picker's order; a reorder the shares cannot
        follow is vetoed."""
        if not gpu_ids:
            return gpu_indices, tp_tensor_split
        picked = [int(i) for i in gpu_ids]
        if gpu_indices is None:
            return picked, tp_tensor_split
        before = [int(i) for i in gpu_indices]
        kept = set(before)
        reordered = [i for i in picked if i in kept] + [i for i in before if i not in set(picked)]
        if tp_tensor_split and len(tp_tensor_split) == len(before):
            share_by_id = dict(zip(before, tp_tensor_split))
            if all(i in share_by_id for i in reordered):
                return reordered, [share_by_id[i] for i in reordered]
        elif not tp_tensor_split:
            return reordered, tp_tensor_split
        return gpu_indices, tp_tensor_split

    def _planned_child_gpu_order(
        self,
        *,
        gpu_ids,
        gpu_indices,
        tp_tensor_split,
        extra_args,
        env,
        is_vulkan_backend: bool,
        cpu_forced: bool = False,
    ) -> "tuple[Optional[list[int]], Optional[list[int]]]":
        """``(device order, visibility mask order)`` the spawn will give the child; mask None when
        inherited."""
        order, split = self._picker_ordered_gpu_indices(gpu_ids, gpu_indices, tp_tensor_split)
        if order is None or is_vulkan_backend or cpu_forced:
            return (None if order is None else [int(i) for i in order]), None
        order = [int(i) for i in order]
        mask = list(order)
        if not gpu_ids:
            inherited = self._inherited_child_gpu_order(mask)
            if (
                inherited is not None
                and not _extra_args_have_tensor_split(extra_args, env)
                and (not split or len(split) == len(mask))
            ):
                mask = inherited
        try:
            if LlamaCppBackend._pinned_child_visibility(mask) is None:
                return order, None
        except Exception:
            return order, None
        return order, mask

    @staticmethod
    def _repoint_emitted_tensor_split(
        cmd: list, old_order: list[int], new_order: list[int]
    ) -> bool:
        """Moves --tensor-split shares onto reordered devices, since shares are positional: else the roomier card gets the smaller share. False vetoes the reorder."""
        try:
            at = len(cmd) - 1 - cmd[::-1].index("--tensor-split")
        except ValueError:
            return True  # no shares emitted, nothing positional to carry
        if at + 1 >= len(cmd):
            return False
        shares = cmd[at + 1].split(",")
        if len(shares) != len(old_order):
            return False
        by_id = dict(zip(old_order, shares))
        cmd[at + 1] = ",".join(by_id[i] for i in new_order)
        return True

    @staticmethod
    def _pin_visible_gpu_order_for_split(env: dict) -> Optional[tuple[int, ...]]:
        """Pin the child's GPU enumeration to the picker's order for a manual
        ``--tensor-split`` across the whole visible set. CUDA's default
        FASTEST_FIRST enumeration applies the shares to the wrong cards on
        heterogeneous hosts (#5025), and CUDA_DEVICE_ORDER only fixes the
        numbering base: an inherited numeric visibility mask ALSO defines
        enumeration order, so a reordered parent mask (CUDA_VISIBLE_DEVICES=3,1)
        would still hand the shares to the wrong cards. The UI built the split
        positionally over get_backend_visible_gpu_info's device list (ascending
        physical via nvidia-smi, inherited mask order on the torch fallback), so
        re-emit the same set in that report order -- not an assumed ascending
        sort. The visible set itself never changes. No mask, an empty mask, or a
        UUID/MIG mask (which resolves to None) is left alone -- the multi-GPU
        controls are hidden for the latter."""
        mig_rows = LlamaCppBackend._mig_snapshot_rows()
        if mig_rows is not None:
            # R570+ MIG: pin UUIDs; numeric ids would resolve against the whole host.
            from utils.hardware import mig

            # Snapshot order = picker order; never sort (a numeric mask 2,0 is not ascending).
            order = [int(r["index"]) for r in mig_rows]
            if not order:
                return None
            env["CUDA_VISIBLE_DEVICES"] = mig.visibility_for(mig_rows, order)
            return tuple(order)
        env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
        inherited = LlamaCppBackend._resolve_visible_physical_ids()
        if not inherited:
            return None
        order = None
        try:
            from utils.hardware import get_backend_visible_gpu_info
            info = get_backend_visible_gpu_info()
            if info.get("available") and info.get("index_kind") == "physical":
                reported = [d["index"] for d in info.get("devices", [])]
                if sorted(reported) == sorted(inherited):
                    order = reported
        except Exception as e:
            logger.debug("Could not read reported GPU order for split pin: %s", e)
        if order is None:
            order = sorted(inherited)
        # Re-emit via ROCR when the parent masked there, else HSA sees hidden GPUs and may segfault.
        prefer_rocr = (
            sys.platform != "win32"
            and env.get("HIP_VISIBLE_DEVICES") is None
            and env.get("ROCR_VISIBLE_DEVICES") is not None
        )
        LlamaCppBackend._emit_child_gpu_visibility(
            env, ",".join(str(i) for i in order), prefer_rocr = prefer_rocr
        )
        return tuple(int(i) for i in order)

    @staticmethod
    def _vulkan_probe_answered(binary: Optional[str]) -> bool:
        """Whether the Vulkan probe returned any rows; the iGPU check maps no answer to not integrated."""
        try:
            return bool(LlamaCppBackend._run_vulkan_probe(binary))
        except Exception:
            return False

    @staticmethod
    def _vulkan_targets_are_igpus(binary: Optional[str], gpu_indices = None) -> bool:
        """True if any Vulkan device is an iGPU, whose VRAM is shared host RAM and worth page-locking."""
        try:
            rows = LlamaCppBackend._run_vulkan_probe(binary)
        except Exception:
            return False
        if not rows:
            return False
        wanted = set(gpu_indices) if gpu_indices else None
        selected = [r for r in rows if wanted is None or r["index"] in wanted]
        return any(r["is_igpu"] for r in selected)

    def _weights_in_host_memory(
        self,
        *,
        fully_gpu_offloaded: bool,
        gpu_memory_mode: Optional[str],
        gpu_layers: Optional[int],
        extra_args: Optional[Iterable[str]],
        gpu_indices = None,
        is_vulkan_backend: bool = False,
        binary: Optional[str] = None,
        env: Optional[Mapping[str, str]] = None,
        probe_vulkan: bool = True,
        fit_active: bool = False,
    ) -> bool:
        """Errs towards True: it only gates skipping page-lock, so an unknown placement must keep mlock."""
        from utils.hardware import is_apple_silicon

        # CPU placement in extras or inherited env keeps weights in RAM whatever the layer count: check on the auto path too, never short-circuit past it.
        if _args_place_tensors_on_cpu(extra_args):
            return True
        if _env_places_tensors_on_cpu(env):
            return True
        # A --device naming no GPU beats any layer count: nowhere to offload, so the model stays in host RAM.
        if _device_selection_is_cpu(extra_args, env):
            return True
        # User extras are appended last (last-wins), so -ngl or an enabled fit voids the prediction.
        if _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS) or fit_is_enabled_in(extra_args):
            fully_gpu_offloaded = False
        all_on_gpu = fully_gpu_offloaded or self._offloads_every_layer(
            gpu_memory_mode = gpu_memory_mode,
            gpu_layers = gpu_layers,
            extra_args = extra_args,
            fit_active = fit_active,
        )
        if not all_on_gpu:
            return True
        # Unified memory: the VRAM is host RAM, so weights stay pageable however fully they are offloaded.
        if is_apple_silicon():
            return True
        if is_vulkan_backend:
            # gpu_indices are Vulkan ordinals here; the ROCm helper would misread them.
            return not probe_vulkan or self._vulkan_targets_are_igpus(binary, gpu_indices)
        return self._amd_apu_wants_unified_memory(gpu_indices)

    def _offloads_every_layer(
        self,
        *,
        gpu_memory_mode: Optional[str],
        gpu_layers: Optional[int],
        extra_args: Optional[Iterable[str]],
        fit_active: bool = False,
    ) -> bool:
        """Full offload via a route fully_gpu_offloaded misses (manual max or user -ngl); unknowns (unreadable blocks, CPU experts, tensor overrides) answer False."""
        n_layers = self.n_layers
        if not n_layers:
            return False
        if self._n_cpu_moe:
            return False
        # Parsed predicate, not presence: --n-cpu-moe 0 places nothing.
        if _args_place_tensors_on_cpu(extra_args):
            return False
        requested: Optional[int] = None
        if gpu_memory_mode == "manual" and gpu_layers is not None and gpu_layers >= 0:
            # Manual owns offload and strips -ngl from extras, so the field rules; picker max is n_layers + 1.
            requested = gpu_layers
        else:
            try:
                requested = parse_gpu_layers_override(extra_args)
            except ValueError:
                return False
        if requested is None:
            return False
        # -1 is llama.cpp's default, so an active fitter may lower it; a concrete count stands.
        if requested == -1:
            return not fit_active
        return requested > n_layers

    def _partially_offloads_layers(
        self,
        args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        fit_implies_partial: bool = True,
    ) -> bool:
        """A concrete layer count owns placement; 0 is CPU-only, not partial, and keeps CPU MTP; --fit on implies partial only in Auto, never Manual."""
        n_layers = self.n_layers
        if not n_layers:
            return False
        try:
            requested = parse_gpu_layers_override(args)
        except ValueError:
            return False
        source_env = os.environ if env is None else env
        if _device_selection_is_cpu(args, source_env):
            return False
        if requested is None:
            raw = source_env.get("LLAMA_ARG_N_GPU_LAYERS")
            if raw is not None and raw.strip():
                try:
                    requested = int(raw)
                except ValueError:
                    requested = None
        if requested == 0:
            return False
        if requested is not None and requested > 0:
            # llama.cpp needs a count above block_count to include the output layer (_offloads_every_layer).
            return requested <= n_layers
        return fit_implies_partial and fit_is_effectively_on(args, source_env)

    @staticmethod
    def _torch_is_rocm(torch) -> bool:
        """Whether this torch is a ROCm build. AMD SDK wheels leave
        ``version.hip`` unset and only encode "rocm" in ``__version__``."""
        return (
            getattr(torch.version, "hip", None) is not None
            or "rocm" in getattr(torch, "__version__", "").lower()
        )

    @staticmethod
    def _host_torch_is_rocm() -> bool:
        """Whether torch here is a ROCm build, without the caller importing torch.
        False when torch is missing or unreadable. Cheap guard so a CUDA or
        CPU-only host does not pay for ROCm-only work (#7624)."""
        try:
            import torch
            return LlamaCppBackend._torch_is_rocm(torch)
        except Exception:
            return False

    @staticmethod
    def _rocm_classification_answered() -> bool:
        """Kept apart: a page-lock skip may treat no APU and could-not-tell alike; a loader choice
        may not."""
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return False
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return False
            from core.training.worker import _rocm_classify_unified_memory

            count = torch.cuda.device_count()
            if count <= 0:
                return False
            # Classify every visible device, not just the selected ones: mapping ggml ordinals onto torch ones is not owned here; unreadable ones read discrete.
            for ordinal in range(count):
                _rocm_classify_unified_memory(torch.cuda.get_device_properties(ordinal))
            return True
        except Exception:
            return False

    @staticmethod
    def _rocm_unified_memory_gpu_ids() -> set[int]:
        """PHYSICAL ids of visible ROCm APUs, classified by the training worker so both paths agree."""
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return set()
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return set()
            from core.training.worker import _rocm_classify_unified_memory

            # Map ordinal to physical id via the ROCm mask (HIP, then ROCR, then CUDA), as _get_gpu_memory does.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            unified: set[int] = set()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    _arch, is_unified = _rocm_classify_unified_memory(
                        torch.cuda.get_device_properties(ordinal)
                    )
                except Exception:
                    continue
                if not is_unified:
                    continue
                unified.add(
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
            return unified
        except Exception:
            return set()

    @staticmethod
    def _rocm_selected_pool_mib(gpu_indices = None) -> Optional[int]:
        """Combined carve-out MiB of selected APUs, or None if any device is not one (ggml's is global)."""
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return None
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return None
            from core.training.worker import _rocm_classify_unified_memory

            wanted = None if gpu_indices is None else set(gpu_indices)
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            total_mib = 0
            seen: set[int] = set()
            for ordinal in range(torch.cuda.device_count()):
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                if wanted is not None and pid not in wanted:
                    continue
                try:
                    props = torch.cuda.get_device_properties(ordinal)
                    _arch, is_unified = _rocm_classify_unified_memory(props)
                except Exception:
                    return None
                if not is_unified:
                    return None
                total = int(getattr(props, "total_memory", 0) or 0)
                if total <= 0:
                    return None
                total_mib += total // (1024 * 1024)
                seen.add(pid)
            if not seen or (wanted is not None and seen != wanted):
                return None
            return total_mib
        except Exception:
            return None

    @staticmethod
    def _unified_memory_would_help(gpu_indices = None, need_bytes = None) -> bool:
        """Only if host RAM is the larger pool vs the carve-out total and weights overflow the carve-out, since managed pages fault in k_set_rows on gfx1151."""
        try:
            pool_mib = LlamaCppBackend._rocm_selected_pool_mib(gpu_indices)
            if not pool_mib:
                return False
            host_mib = LlamaCppBackend._available_system_memory_mib()
            if not host_mib:
                return False
            if int(host_mib) <= int(pool_mib):
                return False
            if need_bytes is None:
                return False
            return int(need_bytes) > int(pool_mib) * 1024 * 1024
        except Exception:
            return False

    @staticmethod
    def _rocm_arch_by_physical_id() -> dict[int, str]:
        """Lowercased base gfx arch per PHYSICAL id, honoring the ROCm mask; alternate SDK attr spellings are needed or the gate silently fails open."""
        arch_by_id: dict[int, str] = {}
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return arch_by_id
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return arch_by_id
            from core.training.worker import _rocm_classify_unified_memory

            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    _arch, _is_unified = _rocm_classify_unified_memory(
                        torch.cuda.get_device_properties(ordinal)
                    )
                except Exception:
                    continue
                _base = (_arch or "").split(":")[0].strip().lower()
                if not _base:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                arch_by_id[pid] = _base
        except Exception:
            return arch_by_id
        return arch_by_id

    @staticmethod
    def _offload_target_shares_system_memory(
        *, is_vulkan_backend: bool, shared_gpu_ids, detected_gpus, gpu_indices
    ) -> bool:
        """True only when every device shares host RAM as VRAM; mixed, unreadable or unpinned is False. Keep Vulkan ordinals and physical ids in separate sets."""
        devices = (
            list(gpu_indices) if gpu_indices else [idx for idx, _free in (detected_gpus or ())]
        )
        if not devices:
            return False
        if is_vulkan_backend:
            shared = set(shared_gpu_ids or ())
            return bool(shared) and all(idx in shared for idx in devices)
        # ROCm only: a CUDA get_device_properties() leaks a ~700 MiB primary context.
        try:
            unified = LlamaCppBackend._rocm_unified_memory_gpu_ids()
        except Exception:
            return False
        return bool(unified) and all(idx in unified for idx in devices)

    @staticmethod
    def _amd_apu_wants_unified_memory(gpu_indices = None) -> bool:
        """True only for AMD APUs, since GGML_CUDA_ENABLE_UNIFIED_MEMORY hurts discrete GPUs."""
        try:
            unified = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            if gpu_indices is None:
                return bool(unified)
            return any(_i in unified for _i in gpu_indices)
        except Exception:
            return False

    # PHYSICAL integrated ids, keyed per visibility mask; integratedness cannot change under a fixed mask.
    _INTEGRATED_CUDA_IDS: dict[tuple, set[int]] = {}

    @staticmethod
    def _integrated_cuda_mask_key() -> tuple:
        return tuple(
            os.environ.get(name)
            for name in ("CUDA_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES", "ROCR_VISIBLE_DEVICES")
        )

    @staticmethod
    def _integrated_cuda_probe_is_free() -> bool:
        """True if the integrated-CUDA answer is cached for this mask; the preflight never probes, since the budget is already taken and both arms fill the cache."""
        return LlamaCppBackend._integrated_cuda_mask_key() in LlamaCppBackend._INTEGRATED_CUDA_IDS

    @staticmethod
    def _integrated_cuda_gpu_ids() -> set[int]:
        """PHYSICAL ids of visible integrated CUDA GPUs; ROCm is left to _rocm_unified_memory_gpu_ids."""
        cached = LlamaCppBackend._INTEGRATED_CUDA_IDS.get(
            LlamaCppBackend._integrated_cuda_mask_key()
        )
        if cached is not None:
            # Settled: a second pass over the devices could learn nothing.
            return set(cached)
        try:
            import torch

            if LlamaCppBackend._torch_is_rocm(torch):
                return set()
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return set()
            # Same ordinal-to-physical map as the ROCm twin, so masked CUDA_VISIBLE_DEVICES=2 hosts stay correct.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            integrated: set[int] = set()
            # An incomplete pass is returned but not cached, so a failed query is retried.
            complete = True
            for ordinal in range(torch.cuda.device_count()):
                try:
                    props = torch.cuda.get_device_properties(ordinal)
                except Exception:
                    complete = False
                    continue
                # Both attribute spellings: torch renamed `integrated`.
                if not (
                    getattr(props, "is_integrated", False) or getattr(props, "integrated", False)
                ):
                    continue
                integrated.add(
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
            # Cached for the preflight only if the pass reached every device; a torch that raised says nothing.
            if complete:
                LlamaCppBackend._INTEGRATED_CUDA_IDS[
                    LlamaCppBackend._integrated_cuda_mask_key()
                ] = integrated
            return integrated
        except Exception:
            return set()

    # {physical id: pool total MiB} per visibility mask, filled beside _INTEGRATED_CUDA_IDS.
    _INTEGRATED_CUDA_POOL_MIB: dict[tuple, dict[int, int]] = {}

    @staticmethod
    def _integrated_cuda_pool_total_mib() -> dict[int, int]:
        """Pool MiB per integrated CUDA device, from props.total_memory: what it can actually allocate."""
        key = LlamaCppBackend._integrated_cuda_mask_key()
        cached = LlamaCppBackend._INTEGRATED_CUDA_POOL_MIB.get(key)
        if cached is not None:
            return dict(cached)
        integrated = LlamaCppBackend._integrated_cuda_gpu_ids()
        if not integrated:
            return {}
        try:
            import torch

            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            totals: dict[int, int] = {}
            complete = True
            for ordinal in range(torch.cuda.device_count()):
                idx = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                if idx not in integrated:
                    continue
                try:
                    props = torch.cuda.get_device_properties(ordinal)
                    totals[idx] = int(props.total_memory) // (1024 * 1024)
                except Exception:
                    complete = False
            if complete:
                LlamaCppBackend._INTEGRATED_CUDA_POOL_MIB[key] = totals
            return totals
        except Exception:
            return {}

    @staticmethod
    def _widen_integrated_cuda_rows(gpus: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
        """Only widens: a total is replaced by a larger pool, and free is floored at the CLI reading."""
        try:
            integrated = LlamaCppBackend._integrated_cuda_gpu_ids()
            if not integrated or not gpus:
                return gpus
            # nvidia-smi and CUDA order differ unless CUDA_DEVICE_ORDER=PCI_BUS_ID and the mask maps.
            order = (os.environ.get("CUDA_DEVICE_ORDER") or "").strip().upper()
            raw_mask = os.environ.get("CUDA_VISIBLE_DEVICES")
            mask_unset = raw_mask is None or not raw_mask.strip()
            mappable = mask_unset or LlamaCppBackend._resolve_visible_physical_ids() is not None
            # No single-row exemption; main.py sets PCI_BUS_ID, so Spark/Jetson/N1X qualify.
            if not (mappable and order == "PCI_BUS_ID"):
                logger.debug(
                    "Not widening integrated CUDA rows: CUDA_DEVICE_ORDER is %r and "
                    "the mask %s, so a CUDA id cannot be joined to an nvidia-smi index "
                    "here.",
                    order or "unset (FASTEST_FIRST)",
                    "resolves to no physical ids" if not mappable else "is mappable",
                )
                return gpus
            totals = LlamaCppBackend._integrated_cuda_pool_total_mib()
            avail = LlamaCppBackend._available_system_memory_mib()
            cgroup_mib = LlamaCppBackend._cgroup_available_memory_mib()
            # Integrated devices share one pool, so divide by their count.
            shared_count = max(1, sum(1 for idx, _f, _t in gpus if idx in integrated))
            out: list[tuple[int, int, int]] = []
            for idx, free_mib, total_mib in gpus:
                if idx not in integrated:
                    out.append((idx, free_mib, total_mib))
                    continue
                cli_total_mib = total_mib
                pool_mib = totals.get(idx) or 0
                if pool_mib > total_mib:
                    total_mib = pool_mib
                raw_mib = free_mib
                # MemAvailable: both free readings undercount here. A zero total never caps.
                if avail is not None and total_mib > 0:
                    raw_mib = min(total_mib, max(raw_mib, avail))
                cgroup_bound = False
                if cgroup_mib is not None and cgroup_mib <= raw_mib:
                    # Charged to the cgroup, so the free reading is the real ceiling.
                    raw_mib = cgroup_mib
                    cgroup_bound = True
                if shared_count > 1:
                    raw_mib //= shared_count
                    total_mib //= shared_count
                capped = _apply_igpu_host_reserve_mib(raw_mib, True)
                # Floor at the driver's free reading, except under a cgroup (charged to memory.max).
                if not cgroup_bound:
                    capped = max(capped, free_mib // shared_count)
                # Log only on change: _get_gpu_memory is uncached and polled every 0.25 s.
                if capped != free_mib or total_mib != cli_total_mib:
                    logger.info(
                        f"CUDA device {idx} is a unified-memory SoC sharing system RAM; "
                        f"sizing it against the shared pool "
                        f"({free_mib}->{capped}MiB free, "
                        f"{pool_mib or total_mib}MiB pool)"
                    )
                out.append((idx, capped, 0 if cgroup_bound else total_mib))
            return sorted(out, key = lambda g: g[0])
        except Exception as e:
            logger.debug(f"integrated CUDA pool sizing failed: {e}")
            return gpus

    @staticmethod
    def _integrated_cuda_unified_memory(gpu_indices = None) -> bool:
        """True if any credited CUDA device is an integrated SoC, since its pool would be double counted."""
        try:
            integrated = LlamaCppBackend._integrated_cuda_gpu_ids()
            if gpu_indices is None:
                return bool(integrated)
            return any(_i in integrated for _i in gpu_indices)
        except Exception:
            return False

    @staticmethod
    def _integrated_cuda_selection_is_all_shared(gpu_indices = None) -> bool:
        """True only if EVERY credited CUDA device is integrated; any discrete card voids it, else an otherwise fitting load is called oversized."""
        try:
            integrated = LlamaCppBackend._integrated_cuda_gpu_ids()
            if not integrated:
                return False
            if gpu_indices is not None:
                return bool(gpu_indices) and all(_i in integrated for _i in gpu_indices)
            # Nothing pinned, so the credited set is every visible device.
            visible = LlamaCppBackend._resolve_visible_physical_ids()
            if visible is None:
                import torch
                visible = list(range(torch.cuda.device_count()))
            return bool(visible) and all(_i in integrated for _i in visible)
        except Exception:
            return False

    # "Off" spellings ggml itself ignores (it tests presence); we honour them.
    _UNIFIED_MEMORY_OFF = frozenset({"", "0", "false", "no", "off"})

    @staticmethod
    def _unified_memory_opted_out(env = None) -> bool:
        """True if GGML_CUDA_ENABLE_UNIFIED_MEMORY must be unset (ggml tests presence, so =0 is no opt-out); UNSLOTH_DISABLE_UNIFIED_MEMORY=1 also unsets it."""
        try:
            source = os.environ if env is None else env
            if str(source.get("UNSLOTH_DISABLE_UNIFIED_MEMORY", "")).strip() == "1":
                return True
            value = source.get("GGML_CUDA_ENABLE_UNIFIED_MEMORY")
            if value is None:
                return False
            return str(value).strip().lower() in LlamaCppBackend._UNIFIED_MEMORY_OFF
        except Exception:
            return False

    @staticmethod
    def _unified_memory_opted_in(env = None) -> bool:
        """True when UNSLOTH_ENABLE_UNIFIED_MEMORY=1 asks for managed allocation even
        though the weights fit. Exact "1"; the opt-out wins over it."""
        try:
            source = os.environ if env is None else env
            return str(source.get("UNSLOTH_ENABLE_UNIFIED_MEMORY", "")).strip() == "1"
        except Exception:
            return False

    @staticmethod
    def _unified_memory_for_launch(
        gpu_indices,
        need_bytes,
        *,
        opted_in = False,
    ) -> bool:
        """The launch-time decision behind GGML_CUDA_ENABLE_UNIFIED_MEMORY. It is
        process-wide and hurts discrete cards, so a mixed selection is always False."""
        if opted_in and LlamaCppBackend._rocm_selected_pool_mib(gpu_indices) is not None:
            return True
        return LlamaCppBackend._unified_memory_would_help(gpu_indices, need_bytes = need_bytes)

    # Whole-word so "a100" does not match "RTX A1000".
    _DATACENTER_GPU_RE = re.compile(
        r"\b(?:a100|a30|h100|h200|h800|gh200|b200|b100|b300|gb200|gb300|"
        r"l40s?|l4|rtx pro 6000|rtx 6000 ada)\b"
    )

    # NVLink-capable subset; PCIe peer copies may be silently dropped by an IOMMU.
    # Necessary, not sufficient: _p2p_veto_reason also needs a positive NV# link.
    _NVLINK_FABRIC_GPU_RE = re.compile(
        r"\b(?:a100|a30|h100|h200|h800|gh200|b200|b100|b300|gb200|gb300)\b"
    )

    @staticmethod
    def _all_selected_gpus_match(pattern, gpu_indices = None) -> bool:
        """True iff every selected NVIDIA GPU name matches pattern (mixed, consumer, ROCm or CPU is False); maps physical ids to mask-relative ordinals for lookup."""
        try:
            import torch

            if getattr(torch.version, "hip", None) is not None:
                return False  # ROCm reuses torch.cuda.*; not a CUDA part
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return False
            count = torch.cuda.device_count()

            # Mirror _get_gpu_free_memory; unset or unparsable CUDA_VISIBLE_DEVICES keeps physical id == ordinal.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()

            names_by_id: dict[int, str] = {}
            for ordinal in range(count):
                try:
                    name = (torch.cuda.get_device_properties(ordinal).name or "").lower()
                except Exception:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                names_by_id[pid] = name

            indices = list(gpu_indices) if gpu_indices else list(names_by_id)
            saw = False
            for _i in indices:
                name = names_by_id.get(_i)
                if name is None:
                    continue  # not visible -> skip (fail conservative)
                saw = True
                if not pattern.search(name):
                    return False
            return saw
        except Exception:
            return False

    @staticmethod
    def _is_datacenter_gpu(gpu_indices = None) -> bool:
        """True iff every selected GPU qualifies for the FP32-accum tuning. Mask
        handling: _all_selected_gpus_match. Peer-copy safety: _p2p_veto_reason."""
        return LlamaCppBackend._all_selected_gpus_match(
            LlamaCppBackend._DATACENTER_GPU_RE, gpu_indices
        )

    # NV# is a bonded NVLink set; SYS/NODE/PHB/PXB/PIX cross PCIe. Header is ANSI-underlined.
    _TOPO_GPU_LABEL_RE = re.compile(r"^GPU(\d+)$")
    _TOPO_NVLINK_RE = re.compile(r"^NV\d+$")
    _ANSI_ESCAPE_RE = re.compile(r"\x1b\[[0-9;]*[A-Za-z]")

    # None = not probed; else a 1-tuple whose value may be None (unavailable).
    _NVLINK_TOPO_CACHE = None
    # Bumped on refresh so a slow prime cannot publish over a newer invalidation.
    _NVLINK_TOPO_GENERATION = 0
    _NVLINK_TOPO_LOCK = threading.Lock()

    # Its own vocabulary: a fabricated NV18 could be misread as a link count.
    _NVML_NVLINK_LABEL = "NVLINK"
    _NVML_NO_NVLINK_LABEL = "NO-NVLINK"

    # nvml.h. Only scalars and opaque handles cross, so no struct layout to get wrong.
    _NVML_SUCCESS = 0
    _NVML_P2P_CAPS_INDEX_NVLINK = 2
    _NVML_P2P_STATUS_OK = 0
    # 1..5 are the documented denials; UNKNOWN (6) and anything past the enum are not.
    _NVML_P2P_STATUS_DEFINITE_NEGATIVES = frozenset({1, 2, 3, 4, 5})
    _NVML_FEATURE_ENABLED = 1
    # Link enumeration stops at the first error; this only bounds a runaway loop.
    _NVML_MAX_LINKS = 64

    @classmethod
    def _matrix_is_nvml(cls, matrix: dict) -> bool:
        """Whether this matrix came from NVML, i.e. whether nvidia-smi is known to
        have answered."""
        return any(
            v in (cls._NVML_NVLINK_LABEL, cls._NVML_NO_NVLINK_LABEL) for v in matrix.values()
        )

    @classmethod
    def _label_is_nvlink(cls, label: str) -> bool:
        """The one place that decides whether a label means NVLink, so the
        selected-pair check and the whole-box check cannot drift apart."""
        return bool(cls._TOPO_NVLINK_RE.match(label)) or label == cls._NVML_NVLINK_LABEL

    @staticmethod
    def _nvml_library():
        """The driver's own NVML, via ctypes: present exactly when nvidia-smi is, and
        no Python dependency (nvidia-ml-py is NOT installed in a Studio env). None
        when it cannot be loaded."""
        if os.name == "nt":
            # nvml.dll can sit in NVSMI\ rather than a DLL search path, as nvidia-smi.exe
            # does (see _nvidia_smi_executable in utils/hardware/nvidia.py).
            names = ["nvml.dll"]
            for root in (os.environ.get("ProgramFiles"), os.environ.get("ProgramW6432")):
                if root:
                    names.append(os.path.join(root, "NVIDIA Corporation", "NVSMI", "nvml.dll"))
            windir = os.environ.get("SystemRoot")
            if windir:
                names.append(os.path.join(windir, "System32", "nvml.dll"))
        else:
            names = ["libnvidia-ml.so.1", "libnvidia-ml.so"]
        for name in names:
            try:
                return ctypes.CDLL(name)
            except OSError:
                continue
        return None

    # ctypes has no subprocess timeout and a wedged driver blocks nvmlInit_v2 forever.
    _NVML_PROBE_TIMEOUT_SECONDS = 10

    @classmethod
    def _probe_nvml_nvlink_topology(cls) -> Optional[dict]:
        """_probe_nvml_nvlink_topology_inner under a wall-clock bound. A stalled NVML
        call cannot be cancelled, so the thread is abandoned as a daemon and the caller
        falls through to the shell-out, which has a timeout of its own."""
        box = {}

        def _run():
            box["matrix"] = cls._probe_nvml_nvlink_topology_inner()

        worker = threading.Thread(target = _run, daemon = True, name = "nvml-nvlink-probe")
        worker.start()
        worker.join(cls._NVML_PROBE_TIMEOUT_SECONDS)
        if worker.is_alive():
            logger.debug(
                f"NVML NVLink probe still running after "
                f"{cls._NVML_PROBE_TIMEOUT_SECONDS}s; abandoning it"
            )
            return None
        return box.get("matrix")

    @classmethod
    def _probe_nvml_nvlink_topology_inner(cls) -> Optional[dict]:
        """NVML per-pair evidence: an NVSwitch link proves only attachment, so every GPU linked is not every pair reachable; None when inconclusive, then shell out."""
        lib = cls._nvml_library()
        if lib is None:
            return None
        initialised = False
        try:
            try:
                get_status = lib.nvmlDeviceGetP2PStatus
                get_count = lib.nvmlDeviceGetCount_v2
                get_handle = lib.nvmlDeviceGetHandleByIndex_v2
                get_link_state = lib.nvmlDeviceGetNvLinkState
                nvml_init = lib.nvmlInit_v2
            except AttributeError as e:
                # An older driver missing these still has the working shell-out.
                logger.debug(f"NVML lacks a required symbol: {e}")
                return None
            for fn in (get_status, get_count, get_handle, get_link_state, nvml_init):
                fn.restype = ctypes.c_int
            if nvml_init() != cls._NVML_SUCCESS:
                return None
            initialised = True

            count = ctypes.c_uint()
            if get_count(ctypes.byref(count)) != cls._NVML_SUCCESS:
                return None
            if count.value < 2:
                return None  # peer copies need two devices; nothing to say

            handles = []
            for i in range(count.value):
                handle = ctypes.c_void_p()
                if get_handle(ctypes.c_uint(i), ctypes.byref(handle)) != cls._NVML_SUCCESS:
                    return None  # partial inventory: never approve the rest
                handles.append(handle)

            # Per-device active links, used only to contradict a positive.
            active_links = []
            for handle in handles:
                seen = 0
                for link in range(cls._NVML_MAX_LINKS):
                    state = ctypes.c_uint()
                    rc = get_link_state(handle, ctypes.c_uint(link), ctypes.byref(state))
                    if rc != cls._NVML_SUCCESS:
                        break  # past this device's last link, or unsupported
                    if state.value == cls._NVML_FEATURE_ENABLED:
                        seen += 1
                active_links.append(seen)

            matrix: dict = {}
            for a in range(count.value):
                for b in range(count.value):
                    if a == b:
                        continue
                    status = ctypes.c_uint()
                    rc = get_status(
                        handles[a],
                        handles[b],
                        ctypes.c_uint(cls._NVML_P2P_CAPS_INDEX_NVLINK),
                        ctypes.byref(status),
                    )
                    if rc != cls._NVML_SUCCESS:
                        return None  # unknown for one pair is unknown for all
                    linked = status.value == cls._NVML_P2P_STATUS_OK
                    if not linked and status.value not in cls._NVML_P2P_STATUS_DEFINITE_NEGATIVES:
                        # NO-NVLINK would read as conclusive and rob `topo -m` of the say.
                        logger.debug(
                            f"NVML P2P status {status.value} for GPU {a}<->{b} is not a "
                            "definite answer; treating the topology as unreadable"
                        )
                        return None
                    # An OK on a PCIe-only box becomes unknown, not a false positive.
                    if linked and not (active_links[a] and active_links[b]):
                        logger.debug(
                            f"NVML says GPU {a}<->{b} is NVLink but they report "
                            f"{active_links[a]}/{active_links[b]} active links; "
                            "treating the topology as unreadable"
                        )
                        return None
                    matrix[(a, b)] = cls._NVML_NVLINK_LABEL if linked else cls._NVML_NO_NVLINK_LABEL

            # By key, not count: right-sized with wrong keys passes a length check.
            expected = {(a, b) for a in range(count.value) for b in range(count.value) if a != b}
            if set(matrix) != expected:
                return None
            return matrix
        except Exception as e:
            logger.debug(f"NVML NVLink probe failed: {e}")
            return None
        finally:
            if initialised:
                try:
                    lib.nvmlShutdown()
                except Exception:
                    pass

    @staticmethod
    def _probe_nvlink_topology() -> Optional[dict]:
        """Keyed by nvidia-smi PCI index, not CUDA ordinal; only GPU<n> rows and columns are read; None when the topology cannot be established."""
        try:
            from utils.hardware import gpu_query

            result = gpu_query.run_nvidia_smi(
                ["nvidia-smi", "topo", "-m"],
                cache = False,
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = child_env_without_native_path_secret(),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode != 0:
                return None
            columns: list[int] = []
            matrix: dict = {}
            for raw in result.stdout.splitlines():
                line = LlamaCppBackend._ANSI_ESCAPE_RE.sub("", raw)
                if line.strip().lower().startswith("legend"):
                    break
                tokens = line.split()
                if not tokens:
                    continue
                if not columns:
                    # Header: the leading run of GPU<n> labels names the columns.
                    for token in tokens:
                        m = LlamaCppBackend._TOPO_GPU_LABEL_RE.match(token)
                        if m is None:
                            break
                        columns.append(int(m.group(1)))
                    # Data rows lead with GPU<n> too, so one column is more likely
                    # a missing header than a real table: keep looking.
                    if len(columns) < 2:
                        columns = []
                    continue
                row = LlamaCppBackend._TOPO_GPU_LABEL_RE.match(tokens[0])
                if row is None:
                    continue  # NIC row, or the blank line before the legend
                source = int(row.group(1))
                labels = tokens[1 : 1 + len(columns)]
                if len(labels) != len(columns):
                    return None  # truncated row: refuse to guess
                for col, label in zip(columns, labels):
                    if col != source:
                        matrix[(source, col)] = label.upper()
            # Require every directed pair: truncated rows can look uniformly NVLinked.
            expected = {(a, b) for a in columns for b in columns if a != b}
            if set(matrix) != expected:
                logger.debug(
                    f"nvidia-smi topo -m: {len(matrix)} pairs for {len(columns)} "
                    f"GPUs, expected {len(expected)}; treating as unreadable"
                )
                return None
            return matrix or None
        except Exception as e:
            logger.debug(f"nvidia-smi topo probe failed: {e}")
            return None

    @classmethod
    def _probe_interconnect_matrix(cls) -> Optional[dict]:
        """NVML first, nvidia-smi topo -m only as fallback; UNSLOTH_P2P_TOPO_CROSSCHECK=1 runs both."""
        matrix = cls._probe_nvml_nvlink_topology()
        if matrix is not None and os.environ.get("UNSLOTH_P2P_TOPO_CROSSCHECK") == "1":
            topo = cls._probe_nvlink_topology()
            if topo is not None:
                nvml_yes = {k for k, v in matrix.items() if cls._label_is_nvlink(v)}
                topo_yes = {k for k, v in topo.items() if cls._label_is_nvlink(v)}
                if nvml_yes != topo_yes:
                    logger.warning(
                        "P2P topology cross-check disagreement: NVML-only pairs "
                        f"{sorted(nvml_yes - topo_yes)}, topo-only pairs "
                        f"{sorted(topo_yes - nvml_yes)}. Using topo -m. Please "
                        "report this with `nvidia-smi topo -m` output (#10613)."
                    )
                    return topo
        if matrix is not None:
            return matrix
        return cls._probe_nvlink_topology()

    @classmethod
    def prime_nvlink_topology(cls) -> None:
        """NVML only: a background prime must not spawn nvidia-smi (it can run its full timeout) and publishes only a success, never a miss."""
        if cls._NVLINK_TOPO_CACHE is not None:
            return
        if os.environ.get("UNSLOTH_P2P_TOPO_CROSSCHECK") == "1":
            # Do not publish here: only the load path runs the cross-check, and warm always primes first.
            return
        matrix = cls._probe_nvml_nvlink_topology()
        if matrix is None:
            return
        with cls._NVLINK_TOPO_LOCK:
            if cls._NVLINK_TOPO_CACHE is None:
                cls._NVLINK_TOPO_CACHE = (matrix,)

    @classmethod
    def _nvlink_topology(
        cls,
        refresh = False,
        cache_failure = True,
    ) -> Optional[dict]:
        """Probe runs unlocked; the generation check stops a slow result overwriting a newer
        invalidation."""
        if not refresh and cls._NVLINK_TOPO_CACHE is not None:
            return cls._NVLINK_TOPO_CACHE[0]
        with cls._NVLINK_TOPO_LOCK:
            generation = cls._NVLINK_TOPO_GENERATION
            if refresh:
                cls._NVLINK_TOPO_GENERATION += 1
                generation = cls._NVLINK_TOPO_GENERATION
            elif cls._NVLINK_TOPO_CACHE is not None:
                return cls._NVLINK_TOPO_CACHE[0]
        probed = cls._probe_interconnect_matrix()
        with cls._NVLINK_TOPO_LOCK:
            if generation == cls._NVLINK_TOPO_GENERATION:
                if probed is None and not cache_failure:
                    # A miss probed mid driver init would keep P2P off for the process.
                    return None
                existing = cls._NVLINK_TOPO_CACHE
                if probed is None and existing is not None and existing[0] is not None:
                    # Without this a racing transient failure would erase a concurrent pass's good matrix.
                    return existing[0]
                cls._NVLINK_TOPO_CACHE = (probed,)
                return probed
            # A refresh started mid-pass owns the answer; discard this one as stale.
            cached = cls._NVLINK_TOPO_CACHE
        return probed if cached is None else cached[0]

    @staticmethod
    def _running_virtualized() -> bool:
        """True under a hypervisor, where the IOMMU veto does not apply; False when unknown, keeping it."""
        try:
            with open("/proc/cpuinfo", "r", encoding = "utf-8", errors = "replace") as f:
                for line in f:
                    if line.startswith("flags") and ":" in line:
                        return "hypervisor" in line.split(":", 1)[1].split()
        except Exception:
            pass
        return False

    # One directory per IOMMU group, each with a `type`. Overridable for tests.
    _IOMMU_GROUPS_ROOT = "/sys/kernel/iommu_groups"

    # True if _get_gpu_memory ids are nvidia-smi PCI indices, False if torch ordinals; None until
    # probed. They coincide only under PCI_BUS_ID.
    _GPU_IDS_ARE_PCI_INDICES = None
    # index -> inherited uuid, when CUDA_VISIBLE_DEVICES named the NVML rows by uuid.
    _NVML_ROWS: list = []  # the last NVML inventory; _child_visibility_for reads it
    _SMI_UUID_ROWS: list = []  # (index, uuid) from the last nvidia-smi memory probe
    # MIG cards that same probe saw (None = discovery unknown), so pinning uses its snapshot.
    _SMI_MIG_INDICES: Optional[frozenset] = None

    # Boot-time property: cached for the default root only; an explicit root (tests) re-reads.
    _IOMMU_CACHE = None

    @classmethod
    def _iommu_is_translating_cached(cls) -> Optional[bool]:
        if cls._IOMMU_CACHE is None:
            try:
                cls._IOMMU_CACHE = (cls._iommu_is_translating(),)
            except Exception as e:
                logger.debug(f"IOMMU probe failed: {e}")
                cls._IOMMU_CACHE = (None,)
        return cls._IOMMU_CACHE[0]

    @staticmethod
    def _iommu_is_translating(root = None) -> Optional[bool]:
        """True if any IOMMU group translates DMA (bare-metal P2P then drops writes silently); None when groups exist but none is readable."""
        root = root or LlamaCppBackend._IOMMU_GROUPS_ROOT
        try:
            groups = os.listdir(root)
        except Exception:
            # Absent = nothing translates; present but unreadable = unknown.
            return None if os.path.isdir(root) else False
        if not groups:
            return False  # IOMMU compiled in but off
        kinds = []
        for group in groups:
            try:
                with open(
                    os.path.join(root, group, "type"),
                    "r",
                    encoding = "utf-8",
                    errors = "replace",
                ) as f:
                    kinds.append(f.read().strip().upper())
            except OSError:
                continue  # pre-5.x kernels have no `type`; other groups may
        if not kinds:
            return None
        return any(not kind.startswith("IDENTITY") for kind in kinds)

    @staticmethod
    def _mig_snapshot_rows():
        """R570+ MIG rows _get_gpu_memory sized under this mask and order, else None (index = CUDA id)."""
        snapshot = getattr(LlamaCppBackend, "_MIG_DEVICE_SNAPSHOT", None)
        if snapshot is not None and snapshot[:2] == (
            os.environ.get("CUDA_VISIBLE_DEVICES"),
            os.environ.get("CUDA_DEVICE_ORDER"),
        ):
            return snapshot[2]
        return None

    @classmethod
    def _p2p_veto_reason(
        cls,
        gpu_indices = None,
        launch_order_pinned = False,
        ids_are_pci_indices = None,
    ) -> Optional[str]:
        """Fail-closed wrapper around _p2p_veto_reason_inner: anything unexpected
        reads as "do not set P2P", since losing the tuning beats an exception
        escaping into load_model and failing the load."""
        try:
            return cls._p2p_veto_reason_inner(gpu_indices, launch_order_pinned, ids_are_pci_indices)
        except Exception as e:
            logger.debug(f"peer-fabric check failed: {e}")
            return f"the peer-fabric check could not complete ({type(e).__name__})"

    @classmethod
    def _p2p_veto_reason_inner(
        cls,
        gpu_indices = None,
        launch_order_pinned = False,
        ids_are_pci_indices = None,
    ) -> Optional[str]:
        """Reason GGML_CUDA_P2P must stay off, or None once every pair has a confirmed NV# link. Fails closed; device names and driver peer checks are not proof."""
        if os.environ.get("UNSLOTH_DISABLE_DC_P2P") == "1":
            return "disabled by UNSLOTH_DISABLE_DC_P2P=1"
        if os.environ.get("UNSLOTH_FORCE_DC_P2P") == "1":
            return None
        mig_rows = cls._mig_snapshot_rows()
        if mig_rows is not None:
            # MIG instances have no NVLink matrix row; whole cards keep it via physical_index.
            by_id = {int(r["index"]): r for r in mig_rows}
            selected = (
                sorted(by_id) if gpu_indices is None else sorted(set(int(i) for i in gpu_indices))
            )
            if any(i not in by_id or by_id[i].get("mig") for i in selected):
                return "MIG device UUIDs cannot be verified by the physical-card NVLink matrix"
            gpu_indices = [int(by_id[i]["physical_index"]) for i in selected]
            ids_are_pci_indices = True

        def _pcie(reason: str) -> str:
            """Appended to every PCIe peer veto; on bare-metal Linux a translating IOMMU makes
            copies unsupported."""
            if cls._iommu_is_translating_cached() and not cls._running_virtualized():
                reason += (
                    "; bare-metal Linux with a translating IOMMU, where CUDA "
                    "does not support PCIe peer copies at all"
                )
            return reason

        if not cls._all_selected_gpus_match(cls._NVLINK_FABRIC_GPU_RE, gpu_indices):
            return _pcie("no NVLink-capable part in the selection, so peer copies would cross PCIe")

        matrix = cls._nvlink_topology()
        if not matrix:
            return "neither NVML nor nvidia-smi topo -m gave a usable interconnect matrix"

        gpu_ids = sorted({i for pair in matrix for i in pair})

        # gpu_indices are already nvidia-smi indices (same enumeration as topo -m). Remapping them as
        # CUDA ordinals could make a PCIe pair look NVLinked under FASTEST_FIRST.
        if gpu_indices is not None:
            # Without a PCI_BUS_ID pin the child may resolve these ids to other cards, so refuse,
            # unless the whole box is uniformly NVLinked and the mapping cannot matter.
            uniformly_nvlinked = all(cls._label_is_nvlink(v) for v in matrix.values())
            if not (
                launch_order_pinned
                or os.environ.get("CUDA_DEVICE_ORDER") == "PCI_BUS_ID"
                or uniformly_nvlinked
            ):
                return _pcie(
                    "the child's device order is not pinned to PCI_BUS_ID and the "
                    "box is not uniformly NVLinked, so the verified GPUs may not be "
                    "the ones it runs on; set CUDA_DEVICE_ORDER=PCI_BUS_ID to "
                    "enable P2P here"
                )
            # topo -m proves nvidia-smi enumerated the selection; torch ordinals misread it under FASTEST_FIRST.
            pci_ids = (
                cls._GPU_IDS_ARE_PCI_INDICES is True
                if ids_are_pci_indices is None
                else ids_are_pci_indices
            )
            # As above: every mapping agrees on a uniform box, and stray ids still veto.
            if cls._matrix_is_nvml(matrix) and not pci_ids and not uniformly_nvlinked:
                return _pcie(
                    "the GPU selection came from torch rather than nvidia-smi, so "
                    "its ids are CUDA ordinals and cannot be matched against the "
                    "NVML interconnect matrix"
                )
            selected = sorted(set(gpu_indices))
        else:
            # No explicit selection: filter the matrix to the visible mask, but only when the mask maps to
            # PCI indices (numeric entries are CUDA ordinals); otherwise check the whole box.
            visible = cls._resolve_visible_physical_ids()
            mappable = os.environ.get("CUDA_DEVICE_ORDER") == "PCI_BUS_ID"
            selected = (
                [i for i in gpu_ids if i in set(visible)]
                if visible is not None and mappable
                else list(gpu_ids)
            )

        if len(selected) < 2:
            return "fewer than two GPUs resolved in the interconnect matrix"

        for a in selected:
            for b in selected:
                if a == b:
                    continue
                label = matrix.get((a, b))
                if label is None:
                    return f"GPU {a} and GPU {b} are absent from the interconnect matrix"
                if not cls._label_is_nvlink(label):
                    return _pcie(f"GPU {a} to GPU {b} is {label}, not NVLink")
        return None

    @staticmethod
    def _effective_gpu_count(gpu_indices = None) -> int:
        """GPUs llama-server will use: len(selection), else the visible CUDA
        device count (None = every visible GPU). 0 on error so multi-GPU tuning
        stays off when the count is unknown."""
        if gpu_indices is not None:
            return len(gpu_indices)
        try:
            import torch
            if hasattr(torch, "cuda") and torch.cuda.is_available():
                return torch.cuda.device_count()
        except Exception:
            return 0
        return 0

    # ggml tests GGML_CUDA_P2P for presence, not value, so these would ENABLE it; only absence is off.
    _FALSY_ENV_VALUES = frozenset({"", "0", "false", "off", "no"})

    # Property of the host, not the model, so warn once rather than per launch.
    _warned_no_nvlink = False

    # The loaded template refuses an empty render. Reset on every load.
    _empty_chat_render_refused = False

    @staticmethod
    def _sanitize_p2p_env(env: dict) -> Optional[str]:
        """Drops an inherited GGML_CUDA_P2P (ggml tests presence, not value); call on every launch path, since consumer GPUs never reach the DC gate."""
        value = env.get("GGML_CUDA_P2P")
        if value is None:
            return None
        if (
            str(value).strip().lower() in LlamaCppBackend._FALSY_ENV_VALUES
            or os.environ.get("UNSLOTH_DISABLE_DC_P2P") == "1"
        ):
            del env["GGML_CUDA_P2P"]
            logger.info(
                "Dropped inherited GGML_CUDA_P2P=%r from the llama-server "
                "environment: llama.cpp tests this variable for presence, not "
                "value, so passing it through would have ENABLED peer copies "
                "(#10613)",
                value,
            )
            return value
        return None

    @staticmethod
    def _p2p_user_opted_out() -> bool:
        """Whether the USER asked for peer copies off. Read from os.environ, not a
        child env _sanitize_p2p_env may already have cleaned, so the intent survives
        the variable and the default cannot put it back."""
        return (
            os.environ.get("UNSLOTH_DISABLE_DC_P2P") == "1"
            or str(os.environ.get("GGML_CUDA_P2P", "1")).strip().lower()
            in LlamaCppBackend._FALSY_ENV_VALUES
        )

    @staticmethod
    def _apply_datacenter_env(
        env: dict,
        gpu_indices = None,
        p2p_opted_out = False,
        launch_order_pinned = False,
        ids_are_pci_indices = None,
    ) -> bool:
        """Injects DC tuning via setdefault (user wins); GGML_CUDA_P2P only on a confirmed NVLink fabric; falsy values removed; UNSLOTH_DISABLE_DC_TUNING=1 opts out."""
        if LlamaCppBackend._sanitize_p2p_env(env) is not None:
            p2p_opted_out = True
        if os.environ.get("UNSLOTH_DISABLE_DC_TUNING") == "1":
            return False
        if not LlamaCppBackend._is_datacenter_gpu(gpu_indices):
            return False

        def _apply(name: str, value: str) -> str:
            supplied = name in env
            env.setdefault(name, value)
            return f"{name}={env[name]}" + (" (user)" if supplied else "")

        applied = [_apply("GGML_CUDA_FORCE_CUBLAS_COMPUTE_32F", "1")]
        if LlamaCppBackend._effective_gpu_count(gpu_indices) > 1:
            # Moves no data between GPUs, so it is not gated on the fabric.
            applied.append(_apply("CUDA_SCALE_LAUNCH_QUEUES", "4x"))
            # User asked for off: skip the probe (up to 10s).
            veto = (
                "GGML_CUDA_P2P was turned off in the environment"
                if p2p_opted_out
                else LlamaCppBackend._p2p_veto_reason(
                    gpu_indices, launch_order_pinned, ids_are_pci_indices
                )
            )
            if veto is None:
                applied.append(_apply("GGML_CUDA_P2P", "1"))
            elif "GGML_CUDA_P2P" in env:
                # A truthy user-supplied GGML_CUDA_P2P stands, but it steers straight into the known P2P failure.
                logger.warning(
                    "GGML_CUDA_P2P is set in the environment (%s), so peer copies stay "
                    "ON despite: %s. Unset it entirely -- not =0, which reads as ON "
                    "upstream -- if model output is garbled (#10613).",
                    env["GGML_CUDA_P2P"],
                    veto,
                )
            elif p2p_opted_out or os.environ.get("UNSLOTH_DISABLE_DC_P2P") == "1":
                # Asked for off: the fabric was never inspected, so do not warn about it.
                logger.info("GGML_CUDA_P2P left unset: %s", veto)
            elif not LlamaCppBackend._warned_no_nvlink:
                LlamaCppBackend._warned_no_nvlink = True
                logger.warning(
                    "Multi-GPU data-center box without a confirmed NVLink fabric: %s. "
                    "Leaving GGML_CUDA_P2P unset. A PCIe peer copy can be discarded "
                    "silently while CUDA still reports success, which surfaces as "
                    "garbled output rather than an error (#10613). Verify with "
                    "scripts/p2p_integrity_probe.py; if it passes, set "
                    "UNSLOTH_FORCE_DC_P2P=1 to opt back in.",
                    veto,
                )
        logger.info(
            "Data-center GPU detected: applied DC llama.cpp env tuning (%s)",
            ", ".join(applied),
        )
        return True

    @staticmethod
    def _visible_devices_mask(env_name: str) -> Optional[set[int]]:
        """Empty mask hides every device, unlike an unset variable (None); blank entries are dropped."""
        raw = os.environ.get(env_name)
        if raw is None:
            return None
        try:
            return set(int(x.strip()) for x in raw.split(",") if x.strip())
        except ValueError:
            if (
                env_name != "CUDA_VISIBLE_DEVICES"
                or os.environ.get("CUDA_DEVICE_ORDER") != "PCI_BUS_ID"
            ):
                return None
        from utils.hardware import nvidia

        ids = nvidia.resolve_uuid_mask(raw.strip())
        return set(ids) if ids is not None else None

    @staticmethod
    def _vulkan_pin_args(gpu_indices: Optional[Iterable[int]]) -> list[str]:
        """Pin with --device Vulkan<i>; GGML_VK_VISIBLE_DEVICES uses raw indices, not the compact
        ordinals."""
        if not gpu_indices:
            return []
        return ["--device", ",".join(f"Vulkan{i}" for i in gpu_indices)]

    @staticmethod
    def _backend_lacks_gpu_lib(binary: Optional[str] = None) -> bool:
        """Unknown and static layouts return False, so custom GPU builds are never rejected as CPU-only."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return False
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        return bool(backends.intersection({"cpu", "base"})) and not backends.intersection(
            {"cuda", "hip", "vulkan"}
        )

    def is_vulkan_build(self) -> bool:
        """Whether the resolved llama-server uses Vulkan ordinals."""
        try:
            return self._is_vulkan_backend(self._find_llama_server_binary())
        except Exception:
            return False

    def _gpu_ids_own_placement(self, gpu_ids) -> bool:
        """True when a gpu_ids pick overrules a user --device or --main-gpu; one predicate for all sites so the launch argv and loaded check cannot drift."""
        return gpu_ids is not None

    @staticmethod
    def _strip_device_extra_args(extra_args):
        """Drop device and main-GPU flags so gpu_ids remains authoritative."""
        return strip_shadowing_flags(
            extra_args,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = False,
            strip_device = True,
        )

    # Concrete gfx arch with trailing hex letter (gfx90a); generic or family labels are rejected on purpose, and the gate fails open on them.
    _CONCRETE_GFX_ARCH = re.compile(r"^gfx[0-9][0-9a-f]{2,4}$")

    @staticmethod
    def _installed_llama_gfx_archs(binary: Optional[str] = None) -> Optional[frozenset]:
        """Concrete gfx archs the installed ROCm prebuilt covers (mapped_targets in UNSLOTH_PREBUILT_INFO.json); None when unknown, so callers keep every device."""
        try:
            from utils.llama_cpp_freshness import read_install_marker

            marker = read_install_marker(binary or LlamaCppBackend._find_llama_server_binary())
            if not marker:
                return None
            targets = marker.get("mapped_targets")
            if not isinstance(targets, list):
                return None
            archs = frozenset(
                str(t).split(":")[0].strip().lower() for t in targets if str(t).strip()
            )
            if not archs:
                return None
            # Exact-set match only works if every token is concrete; one unknown token would drop every GPU,
            # so an unrecognised list fails open as a whole.
            unknown = sorted(a for a in archs if not LlamaCppBackend._CONCRETE_GFX_ARCH.match(a))
            if unknown:
                logger.warning(
                    f"install marker mapped_targets has non-concrete arch tokens "
                    f"{unknown}; skipping the GPU arch gate"
                )
                return None
            return archs
        except Exception as e:
            logger.debug(f"install marker arch read failed: {e}")
            return None

    @staticmethod
    def _installed_llama_cuda_sms(binary: Optional[str] = None) -> Optional[frozenset]:
        """SM targets the installed CUDA prebuilt was built for (``supported_sms``
        in UNSLOTH_PREBUILT_INFO.json). None when unknown (no marker, older
        install, non-CUDA bundle), so callers fail open. Never raises."""
        try:
            from utils.llama_cpp_freshness import read_install_marker

            marker = read_install_marker(binary or LlamaCppBackend._find_llama_server_binary())
            if not marker:
                return None
            sms = marker.get("supported_sms")
            if not isinstance(sms, list) or not sms:
                return None
            if not all(str(s).strip().isdigit() for s in sms):
                return None
            return frozenset(int(s) for s in sms)
        except Exception as e:
            logger.debug(f"install marker supported_sms read failed: {e}")
            return None

    @staticmethod
    def _cuda_compute_caps() -> dict:
        """Physical id -> SM (90 for sm_90) via nvidia-smi, honoring
        CUDA_VISIBLE_DEVICES; {} when unknown. Never raises."""
        mig_rows = LlamaCppBackend._mig_snapshot_rows()
        if mig_rows is not None:
            caps = {}
            for row in mig_rows:
                try:
                    major, minor = row.get("compute_cap", "").split(".")
                    caps[int(row["index"])] = int(major) * 10 + int(minor)
                except (TypeError, ValueError):
                    pass
            return caps
        try:
            from utils.hardware import gpu_query

            result = gpu_query.run_nvidia_smi(
                ["nvidia-smi", "--query-gpu=index,compute_cap", "--format=csv,noheader"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = child_env_without_native_path_secret(),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode != 0:
                return {}
            allowed = LlamaCppBackend._visible_devices_mask("CUDA_VISIBLE_DEVICES")
            if allowed is not None and os.environ.get("CUDA_DEVICE_ORDER") != "PCI_BUS_ID":
                # Numeric mask entries are CUDA ordinals, not PCI indices; without a shared order, fail open.
                return {}
            caps = {}
            for line in result.stdout.strip().splitlines():
                parts = [p.strip() for p in line.split(",")]
                if len(parts) < 2:
                    continue
                try:
                    idx = int(parts[0])
                    major, minor = parts[1].split(".")
                    sm = int(major) * 10 + int(minor)
                except ValueError:
                    continue
                if allowed is not None and idx not in allowed:
                    continue
                caps[idx] = sm
            return caps
        except Exception as e:
            logger.debug(f"compute_cap probe failed: {e}")
            return {}

    @classmethod
    def _cuda_sm_gate_error(
        cls,
        binary: Optional[str] = None,
        gpu_indices: Optional[Iterable[int]] = None,
    ) -> Optional[str]:
        """Error message when every visible GPU is OLDER than the oldest arch the
        installed CUDA bundle was built for, or None to proceed. Fails open on
        unknown coverage or caps.

        ``gpu_indices`` (physical ids the child is pinned to) tightens "every
        visible" to "any pinned": the child places work on each pinned card, so one
        too-old card aborts the load even beside a supported one.

        Only the too-old direction is broken. The bundles compile plain arch
        numbers, so each fatbin carries PTX beside its cubins, and the driver JITs
        that PTX forward onto a newer card; ggml_cuda_highest_compiled_arch picks
        the highest compiled arch <= the device and only aborts ("not compiled with
        any CUDA arch <= N") when the device is below every one of them. So an
        exact-SM test would refuse working installs: the legacy PTX-only bundle
        (sm_50-61) drives an sm_86/sm_89 host at full speed. Missing native cubins
        cost a one-time JIT, not a launch. The installer's exact-membership check
        is a different question -- which bundle is BEST to install -- not whether
        the installed one can run."""
        # Resolved once so the marker read and the remedy name the same binary.
        binary = binary or cls._find_llama_server_binary()
        supported = cls._installed_llama_cuda_sms(binary)
        if supported is None:
            return None
        caps = cls._cuda_compute_caps()
        oldest = min(supported)
        if gpu_indices is not None:
            pinned = {int(i) for i in gpu_indices}
            caps = {idx: sm for idx, sm in caps.items() if idx in pinned and sm < oldest}
        elif any(sm >= oldest for sm in caps.values()):
            return None
        if not caps:
            return None
        present = ", ".join(f"GPU {idx} is sm_{sm}" for idx, sm in sorted(caps.items()))
        # The updater cannot replace a pinned LLAMA_SERVER_PATH or a PATH llama-server, so remedy follows provenance.
        return (
            f"The installed llama.cpp build only has GPU code for sm_{oldest} and "
            f"newer, but {present} -- it was likely installed on a machine with a "
            f"newer GPU, so {cls._runtime_remedy(binary)}."
        )

    @classmethod
    def _cuda_sm_gate_keep(
        cls, binary: Optional[str], gpus: list[tuple[int, int, int]]
    ) -> list[tuple[int, int, int]]:
        """``gpus`` minus the CUDA cards older than the installed bundle's oldest
        arch, so auto placement cannot pin one beside a supported card (RTX 4090 +
        GTX 1060 under an sm_75+ build). Unchanged on unknown coverage or caps, and
        when no card survives: the gate then refuses with its own message."""
        supported = cls._installed_llama_cuda_sms(binary)
        if supported is None or not gpus:
            return gpus
        caps = cls._cuda_compute_caps()
        oldest = min(supported)
        kept = [g for g in gpus if caps.get(g[0], oldest) >= oldest]
        if not kept or len(kept) == len(gpus):
            return gpus
        for idx, _free, _total in gpus:
            if caps.get(idx, oldest) < oldest:
                logger.warning(
                    f"Skipping GPU {idx} (sm_{caps[idx]}): installed llama.cpp "
                    f"build only has GPU code for sm_{oldest} and newer"
                )
        return kept

    @classmethod
    def _arch_gate_survivors(cls, binary: Optional[str] = None) -> list[int]:
        """Physical ids the arch gate keeps, for pinning: an uncovered arch crashes HSA enumeration."""
        try:
            # Coverage first: the cached marker read avoids importing torch (~1.3s) on non-ROCm bundles.
            if cls._installed_llama_gfx_archs(binary) is None:
                return []  # unknown coverage: fail open, same as the probe
            if not cls._host_torch_is_rocm():
                return []
            if cls._visibility_mask_is_unmappable():
                # A UUID/MIG mask leaves ordinals unmapped; pinning could re-expose the dropped card. Fail open.
                logger.info(
                    "Not pinning the arch gate's survivors: the inherited GPU "
                    "visibility mask is not index based, so they cannot be named "
                    "to the child."
                )
                return []
            gated = [
                idx for idx, _free, _total in cls._get_gpu_memory(binary, for_llama_server = True)
            ]
            everything = [idx for idx, _free, _total in cls._get_gpu_memory(binary)]
            return gated if gated and len(gated) < len(everything) else []
        except Exception as e:
            logger.debug(f"arch gate survivor probe failed: {e}")
            return []

    @staticmethod
    def _get_gpu_free_memory(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int]]:
        """Free memory per GPU as ``(gpu_index, free_mib)`` sorted by index; empty
        if no supported GPU is reachable. Thin wrapper over ``_get_gpu_memory``,
        which also documents ``for_llama_server`` (forwarded verbatim)."""
        return [
            (idx, free)
            for idx, free, _total in LlamaCppBackend._get_gpu_memory(
                binary, for_llama_server = for_llama_server
            )
        ]

    @staticmethod
    def _metal_zero_ctx_floor(
        effective_ctx: int,
        auto_fit: bool,
        caller_owns_budget: bool,
        native_ctx: Optional[int],
        max_available_ctx: Optional[int] = None,
        *,
        fitter_runs: bool = True,
    ) -> int:
        """Floors a zero Metal context (-c 0 pins native length, disables --fit): _FIT_MIN_CTX if fitter runs, else _LLAMA_FIT_MIN_CTX; auto_fit and caller-owned exempt."""
        if effective_ctx > 0 or (auto_fit and fitter_runs) or caller_owns_budget:
            return 0
        if not LlamaCppBackend._apple_metal_memory_budget_bytes():
            return 0
        floor = _FIT_MIN_CTX if fitter_runs else _LLAMA_FIT_MIN_CTX
        # Never above the ceiling the cap computed; floating back up would re-create the over-commit.
        return min(floor, native_ctx or floor, max_available_ctx or floor)

    @staticmethod
    def _metal_drops_zero_ctx_override(
        ctx_override: Optional[int], caller_owns_budget: bool
    ) -> bool:
        """Drops a pass-through -c 0, since llama.cpp is last-wins and would re-pin the native length."""
        if ctx_override != 0 or caller_owns_budget:
            return False
        return bool(LlamaCppBackend._apple_metal_memory_budget_bytes())

    @staticmethod
    def _apple_metal_memory_budget_bytes() -> int:
        """Unified-memory budget for GGUF context fitting on Apple Silicon.

        No GPU is enumerated on Metal, so the context would default to native and
        over-commit unified memory ("Compute error." at decode, #5118/#6529). Use a
        fraction of the Metal working set, else total RAM; 0 off Apple Silicon or
        when unresolvable, so callers skip the cap.

        Both of those inputs describe the MACHINE, not the moment. MLX's
        max_recommended_working_set_size is a static device property, and
        virtual_memory().total obviously is, so on a 16 GB Mac the budget came
        out around 9 GB whether the machine was idle or already holding several
        gigabytes. Unsloth's own idle footprint alone is over a gigabyte once the
        warm thread has imported torch and, on Apple Silicon, MLX. The fit then
        sized a context against headroom that was not there, and llama-server
        died in KV or compute allocation.

        So take whichever is smaller: the device ceiling, or what is actually
        available right now. The ceiling still applies on a machine with plenty
        free, which is the case the working-set number was chosen for.

        _APPLE_UNIFIED_MEMORY_FRACTION then earns a second job it did not have
        over a static ceiling: available is a snapshot, and llama-server spends
        seconds loading weights, so another app can take memory inside that
        window. Budgeting all of it would re-create the failure this avoids.
        """
        from utils.hardware import is_apple_silicon

        if not is_apple_silicon():
            return 0
        from utils.hardware.hardware import _metal_recommended_working_set_bytes

        rec_bytes = _metal_recommended_working_set_bytes()
        vm = None
        try:
            import psutil
            vm = psutil.virtual_memory()
        except Exception:
            vm = None
        if rec_bytes <= 0:
            if vm is None:
                return 0
            try:
                rec_bytes = int(vm.total)
            except Exception:
                return 0
        # psutil available, not free: macOS free omits the reclaimable inactive queue. Only lowers the budget.
        try:
            available = int(getattr(vm, "available", 0) or 0) if vm is not None else 0
        except Exception:
            available = 0
        if available > 0:
            rec_bytes = min(rec_bytes, available)
        return int(rec_bytes * _APPLE_UNIFIED_MEMORY_FRACTION)

    def _metal_measured_model_mib(
        self, binary: Optional[str], model_path: Optional[str]
    ) -> Optional[tuple[int, int, int]]:
        """Measures full-offload model buffers with the sibling llama-fit-params; None if that probe
        fails, with the reason in ``_metal_probe_failure``."""
        self._metal_probe_failure = None
        if not binary or not model_path:
            self._metal_probe_failure = "no binary or model path"
            return None
        try:
            probe = _llama_lib_dir(binary) / "llama-fit-params"
        except OSError:
            self._metal_probe_failure = "llama-fit-params not found"
            return None
        try:
            probe_stat = probe.stat()
        except OSError:
            self._metal_probe_failure = f"llama-fit-params not found at {probe}"
            return None
        try:
            model_stat = os.stat(model_path)
        except OSError:
            self._metal_probe_failure = "model file unreadable"
            return None
        if os.name != "nt" and not os.access(probe, os.X_OK):
            self._metal_probe_failure = f"llama-fit-params at {probe} is not executable"
            return None
        key = (
            str(probe),
            probe_stat.st_size,
            probe_stat.st_mtime_ns,
            probe_stat.st_mode,
            model_path,
            model_stat.st_size,
            model_stat.st_mtime_ns,
        )
        cached = getattr(self, "_metal_model_mib_cache", None)
        if cached is not None and cached[0] == key:
            self._metal_probe_failure = cached[2]
            return cached[1]
        transient = getattr(_LOAD_PROBE_STATE, "metal_transient", None)
        if transient is not None and key in transient:
            self._metal_probe_failure = transient[key]
            return None
        measured: Optional[tuple[int, int, int]] = None
        failure: Optional[str] = None
        cacheable = True
        try:
            env = self._llama_server_env_for_binary(str(binary))
            for name in tuple(env):
                if name.startswith("LLAMA_ARG_"):
                    env.pop(name, None)
            result = subprocess.run(
                [str(probe), "-m", model_path, "-ngl", "999", "-c", "512", "-lv", "4"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                # A cold Metal shader compile lands here instead of at the launch.
                timeout = _METAL_FIT_PROBE_TIMEOUT_S,
                check = False,
                env = env,
                **_windows_hidden_subprocess_kwargs(),
            )
            output = (result.stdout or "") + "\n" + (result.stderr or "")
            if result.returncode != 0:
                failure = f"llama-fit-params exited with code {result.returncode}"
                cacheable = False
            else:
                measured = _parse_metal_memory_breakdown(output)
                if measured is None:
                    failure = "llama-fit-params printed no Metal memory breakdown"
            if failure:
                tail = " | ".join(
                    line.strip() for line in output.strip().splitlines()[-3:] if line.strip()
                )
                if tail:
                    failure = f"{failure}: {tail[-300:]}"
        except subprocess.TimeoutExpired:
            failure = f"llama-fit-params timed out after {_METAL_FIT_PROBE_TIMEOUT_S} s"
            cacheable = False
        except Exception as e:
            failure = f"llama-fit-params could not run: {e}"
            cacheable = False
        if failure:
            logger.debug(f"llama-fit-params memory probe failed: {failure}")
        self._metal_probe_failure = failure
        if cacheable:
            self._metal_model_mib_cache = (key, measured, failure)
        elif transient is not None:
            transient[key] = failure
        return measured

    def _metal_demand_paged_embedding_bytes(
        self,
        model_path: Optional[str],
        extra_args: Optional[Iterable[str]],
        *,
        binary: Optional[str],
        requested_load_mode: Optional[str],
        supports_load_mode: bool,
        settings: tuple[bool, bool],
        layers_fixed: bool,
        mtp_may_engage: bool,
        env: Optional[Mapping[str, str]] = None,
    ) -> int:
        """Embedding bytes proven absent from the Metal working set; fails closed, CPU weights stay
        charged."""
        source_env = os.environ if env is None else env
        if not self._metal_placement_unset(extra_args, source_env, layers_fixed = layers_fixed):
            return 0
        env_view = dict(source_env)
        scrub_memory_env(env_view, settings)
        managed, extras = apply_model_memory_policy(
            extra_args,
            supports_load_mode = supports_load_mode,
            weights_in_host_memory = True,
            gpu_offload_confirmed = False,
            env = env_view,
            settings = settings,
        )
        selected, extras = apply_load_mode_policy(
            extras,
            supports_load_mode = supports_load_mode,
            weights_in_host_memory = True,
            requested_load_mode = requested_load_mode,
            settings = settings,
        )
        mlock, reserves_ram, direct_io = resolve_effective_load_state(
            [*managed, *selected, *extras], env_view
        )
        if mlock or reserves_ram or direct_io:
            return 0
        layout = self._tensor_spill_layout(model_path, all_shards = True)
        if layout is None or not layout.complete:
            return 0
        embeddings = int(layout.token_embd_bytes) + int(layout.per_layer_embd_bytes)
        if embeddings <= 0 or (mtp_may_engage and layout.has_excluded_blocks):
            return 0
        measured = self._metal_measured_model_mib(binary, model_path)
        if measured is None:
            _info_once_per_load(
                "Metal fit: could not measure how llama.cpp maps this model (%s), so its "
                "%.2f GB of input embeddings stay charged.",
                getattr(self, "_metal_probe_failure", None) or "llama-fit-params unavailable",
                embeddings / (1024**3),
            )
            return 0
        metal_mib, host_mib, rows = measured
        mib = 1024 * 1024
        charged = (metal_mib + rows) * mib + max(0, host_mib * mib - embeddings)
        # TENSOR_SKIP blocks never reach a buffer: their bytes are in the file but not in the probe.
        mapped = int(layout.tensor_bytes) - int(layout.excluded_block_bytes)
        unmapped = min(embeddings, max(0, mapped - charged))
        if not unmapped:
            _info_once_per_load(
                "Metal fit: llama.cpp maps this model's %.2f GB of input embeddings into Metal, "
                "so they stay charged. A llama.cpp update may remove that.",
                embeddings / (1024**3),
            )
        return unmapped

    @staticmethod
    def _apple_metal_wired_ceiling_bytes() -> int:
        """Wired GPU memory a Metal load may still take, system-wide; 0 if unknown or used up."""
        return _apple_wired_headroom_bytes() or 0

    @staticmethod
    def _apple_metal_wired_headroom_bytes() -> Optional[int]:
        """The same headroom, but None when unknown, so 0 means used up."""
        return _apple_wired_headroom_bytes()

    @staticmethod
    def _metal_fit_target_floor_mib() -> float:
        """Smallest ``--fit-target`` that keeps llama.cpp's Metal fit inside the wired headroom.

        ggml-metal reports free as recommendedMaxWorkingSetSize minus this process's own
        allocations (ggml-metal-device.m, ggml_metal_device_get_memory), blind to the GPU
        memory WindowServer and other apps already hold, so --fit packs to within 1 GiB of
        the static ceiling and over-commits the wired limit (#9279). 0 when either side is
        unreadable, which leaves llama.cpp's own margin.
        """
        headroom = LlamaCppBackend._apple_metal_wired_ceiling_bytes()
        if headroom <= 0:
            return 0.0
        from utils.hardware.hardware import _metal_recommended_working_set_bytes

        seen = _metal_recommended_working_set_bytes()
        if seen <= 0:
            return 0.0
        return max(0.0, (seen - headroom) / (1024 * 1024))

    @staticmethod
    def _rocm_arch_gate_keep(
        binary: Optional[str], torch_mod, for_llama_server: bool
    ) -> Callable[[int], bool]:
        """Predicate over PHYSICAL ids: keeps a device unless ROCm with a gfx arch the installed prebuilt lacks; shared by amd-smi and torch paths."""
        if not for_llama_server or not LlamaCppBackend._torch_is_rocm(torch_mod):
            return lambda _idx: True
        supported_archs = LlamaCppBackend._installed_llama_gfx_archs(binary)
        if supported_archs is None:
            return lambda _idx: True
        arch_by_id = LlamaCppBackend._rocm_arch_by_physical_id()

        def _keep(idx: int) -> bool:
            _base = arch_by_id.get(idx, "")
            if _base and _base not in supported_archs:
                logger.warning(
                    f"Skipping GPU {idx} ({_base}): installed llama.cpp "
                    f"prebuilt only covers {sorted(supported_archs)}"
                )
                return False
            return True

        return _keep

    @staticmethod
    def _rocm_hip_is_reachable() -> bool:
        """Whether HIP can open a device; amd-smi may list cards HIP cannot open, e.g. without /dev/kfd."""
        try:
            import torch
            return bool(hasattr(torch, "cuda") and torch.cuda.is_available())
        except Exception:
            return False

    @staticmethod
    def _rocm_hip_device_count() -> int:
        """HIP's device count, the inventory the child sees; amd-smi reads the whole host instead."""
        try:
            import torch
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return 0
            return int(torch.cuda.device_count())
        except Exception:
            return 0

    @staticmethod
    def _gpu_device_ordinal_active() -> bool:
        """Whether GPU_DEVICE_ORDINAL filters devices; treated as a mask, as AMD and clr disagree on HIP."""
        return bool(os.environ.get("GPU_DEVICE_ORDINAL", "").strip())

    @staticmethod
    def _rocm_visibility_masks_are_stacked() -> bool:
        """True when ROCR and HIP masks both filter, so HIP ordinals are not physical; callers mapping onto amd-smi ids must decline. Empty ROCR still counts as set."""
        if sys.platform == "win32":
            return False
        if os.environ.get("ROCR_VISIBLE_DEVICES") is None:
            return False
        return (
            os.environ.get("HIP_VISIBLE_DEVICES") is not None
            or os.environ.get("CUDA_VISIBLE_DEVICES") is not None
        )

    @staticmethod
    def _rocm_total_memory_mib_by_physical_id() -> dict[int, int]:
        """Total MiB per PHYSICAL id via get_device_properties, which creates no HIP context."""
        totals: dict[int, int] = {}
        try:
            import torch

            if not LlamaCppBackend._torch_is_rocm(torch):
                return totals
            if not (hasattr(torch, "cuda") and torch.cuda.is_available()):
                return totals
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            for ordinal in range(torch.cuda.device_count()):
                try:
                    total_bytes = int(
                        getattr(torch.cuda.get_device_properties(ordinal), "total_memory", 0) or 0
                    )
                except Exception:
                    continue
                if total_bytes <= 0:
                    continue
                pid = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                totals[pid] = total_bytes // (1024 * 1024)
        except Exception:
            return totals
        return totals

    @staticmethod
    def _amd_smi_hip_id_map(
        enumerated: list[int], mask: Optional[list[int]]
    ) -> Optional[dict[int, int]]:
        """Maps amd-smi ids to HIP ids; None when unprovable, as an untranslated id pins the wrong card."""
        if len(enumerated) == 1 and mask in (None, [0]):
            # One card: HIP can only see it as id 0.
            return {enumerated[0]: 0}
        from utils.hardware.amd import get_hip_id_by_gpu_index

        mapping = get_hip_id_by_gpu_index()
        if mapping is None or not all(_g in mapping for _g in enumerated):
            logger.debug(
                "amd-smi VRAM probe deferring to torch: no amd-smi to HIP id mapping "
                "for this host (amd-smi list -e needs ROCm 6.4.0+)"
            )
            return None
        return mapping

    @staticmethod
    def _get_gpu_memory_amd_smi(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int, int]]:
        """ROCm VRAM via amd-smi per HIP id to avoid HIP context leaks; [] when partial, off ROCm, on unified APUs, or filtered"""
        try:
            import torch
            if not LlamaCppBackend._torch_is_rocm(torch):
                return []
        except Exception:
            return []
        if not LlamaCppBackend._rocm_hip_is_reachable():
            # HIP cannot open the hardware amd-smi lists; let torch answer.
            logger.debug(
                "amd-smi VRAM probe deferring to torch: this ROCm torch cannot open "
                "a device, so amd-smi's inventory is not usable by llama-server"
            )
            return []
        try:
            from utils.hardware.amd import get_gpu_vram_report

            if LlamaCppBackend._visibility_mask_is_unmappable():
                # A UUID mask cannot be applied here and amd-smi ignores masks; let torch answer.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: the GPU visibility mask "
                    "is not index based, so amd-smi's device list cannot be filtered"
                )
                return []
            if LlamaCppBackend._gpu_device_ordinal_active():
                # _resolve_visible_physical_ids does not read this variable, so amd-smi cannot be filtered.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: GPU_DEVICE_ORDINAL is "
                    "set, so amd-smi's device list cannot be filtered"
                )
                return []
            if LlamaCppBackend._rocm_visibility_masks_are_stacked():
                # A ROCr mask under a HIP mask re-indexes it, so the resolved ids would not be physical ids.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: ROCR_VISIBLE_DEVICES is "
                    "stacked under a HIP-layer mask, so the visible ids are positions "
                    "in the ROCr-filtered set rather than physical devices"
                )
                return []
            mask = LlamaCppBackend._resolve_visible_physical_ids()
            if mask is not None and not mask:
                return []  # every device hidden
            vram, enumerated = get_gpu_vram_report()
            if not enumerated:
                return []
            # amd-smi ids are not HIP ids; translate before comparing with the mask or passing them to the child.
            hip_by_gpu = LlamaCppBackend._amd_smi_hip_id_map(enumerated, mask)
            if hip_by_gpu is None:
                return []
            vram = {hip_by_gpu[_g]: _v for _g, _v in vram.items()}
            # amd-smi lists all cards regardless of mask; drop those this process cannot see; no mask keeps all.
            visible = set(mask) if mask is not None else set(hip_by_gpu.values())
            if not visible.issubset(vram):
                # A device that is visible and unmeasured: all or nothing.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: no usable VRAM reading "
                    f"for visible GPU(s) {sorted(visible - set(vram))}"
                )
                return []
            hip_count = LlamaCppBackend._rocm_hip_device_count()
            if len(visible) != hip_count:
                # The amd-smi inventory must equal HIP's (device-cgroup containers filter outside env vars),
                # otherwise the numbers are not comparable.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: amd-smi reports "
                    f"{len(visible)} visible GPU(s) and HIP opens {hip_count}"
                )
                return []
            hip_totals = LlamaCppBackend._rocm_total_memory_mib_by_physical_id()
            disagreeing = sorted(
                _idx
                for _idx in visible
                if _idx in hip_totals
                and abs(vram[_idx][1] - hip_totals[_idx])
                > _AMD_SMI_TOTAL_TOLERANCE * hip_totals[_idx]
            )
            if disagreeing:
                # amd-smi and HIP may measure different memory scopes (APU carve-out vs GTT); defer on mismatch; undescribed devices fail open.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: amd-smi and HIP report "
                    f"different total memory for GPU(s) {disagreeing}"
                )
                return []
            unified_ids = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            if unified_ids:
                # On a unified-memory APU amd-smi reports only the BIOS carve-out; defer the whole host to torch
                # so both branches of _get_gpu_memory agree.
                logger.debug(
                    "amd-smi VRAM probe deferring to torch: unified-memory APU(s) "
                    f"{sorted(unified_ids)} report only their dedicated VRAM slice"
                )
                return []
            arch_keeps = LlamaCppBackend._rocm_arch_gate_keep(binary, torch, for_llama_server)
            gpus: list[tuple[int, int, int]] = []
            for idx in sorted(visible):
                if not arch_keeps(idx):
                    continue
                free_mib, total_mib = vram[idx]
                gpus.append((idx, free_mib, total_mib))
            return gpus
        except Exception as e:
            logger.debug(f"amd-smi GPU probe failed: {e}")
            return []

    @staticmethod
    def _explain_empty_gpu_probe(binary: Optional[str] = None) -> str:
        """Says why _get_gpu_memory came back empty; never raises, never returns an empty string; no mem_get_info."""
        try:
            binary = binary or LlamaCppBackend._find_llama_server_binary()
            if _metal_capable_host():
                # Same check as the load site: an Intel Mac wants its real reason.
                return "this probe reads CUDA and HIP only; Apple Silicon offloads through Metal"
            # Checked first: an unopenable render node leaves HIP and Vulkan empty; Vulkan asks only the render node; unreadable installs stay eligible.
            _is_vulkan = LlamaCppBackend._is_vulkan_backend(binary)
            _backends = LlamaCppBackend._installed_ggml_backends(binary)
            _amd_capable = not LlamaCppBackend._backend_lacks_gpu_lib(binary) and (
                _is_vulkan or "hip" in _backends or not _backends
            )

            # KFD ordinal space the device lists index; None if unreadable, which leaves selectors alone.
            try:
                from utils.hardware.amd import amd_kfd_gpu_node_count
                _amd_gpu_count = amd_kfd_gpu_node_count()
            except Exception:  # noqa: BLE001
                _amd_gpu_count = None

            def _post_rocr_device_count() -> "int | None":
                # ROCr filters the physical list first and renumbers, so HIP ordinals are judged against
                # the post-ROCr count. None when survivors cannot be counted.
                if not _rocr_filters:
                    return _amd_gpu_count
                _raw = (os.environ.get("ROCR_VISIBLE_DEVICES") or "").strip()
                if not _raw or not _amd_gpu_count:
                    return None
                # Mirrors ROCr RvdFilter (amd_filter_device.h): out-of-range, repeated or illegal tokens end
                # the list, so every ending is a known prefix; only a UUID is unknowable.
                _survivors = 0
                _selected: "set[int]" = set()
                for _entry in _raw.split(","):
                    _entry = _entry.strip()
                    if not _entry.isdigit():
                        # Only the GPU-XX UUID form is unknowable; other non-indices are Illegal to ROCr.
                        return None if _entry.lower().startswith("gpu-") else _survivors
                    _idx = int(_entry)
                    if _idx >= _amd_gpu_count or _idx in _selected:
                        return _survivors
                    _selected.add(_idx)
                    _survivors += 1
                return _survivors

            def _hides_every_device(
                value: str,
                count: "int | None" = None,
                *,
                strict: bool = False,
            ) -> bool:
                # CUDA/HIP stop at the first entry naming no device; an empty or negative first
                # entry exposes nothing.
                first = value.split(",")[0].strip()
                if first == "" or first.startswith("-"):
                    return True
                # clr rejects a token unless atoi round-trips it, so 'garbage', '0x1', '00' terminate like -1.
                if strict and not first.lower().startswith("gpu-"):
                    try:
                        _index = int(first)
                    except ValueError:
                        return True
                    if str(_index) != first:
                        return True
                # An out-of-range ordinal also ends the list; only judged against a count actually read.
                _bound = _amd_gpu_count if count is None else count
                if not _bound or not first.isdigit():
                    return False
                return int(first) >= _bound

            def _cannot_be_resolved(value: str) -> bool:
                # UUID tokens cannot be resolved here, so they are unresolved rather than blockers.
                first = value.split(",")[0].strip()
                return first.lower().startswith("gpu-")

            def _vk_selects_no_device(value: str) -> bool:
                # ggml stops at the first token with no integer prefix; a sign counts as a prefix.
                _first = value.replace(",", " ").split()
                if not _first:
                    return True
                _token = _first[0]
                _digits = _token[1:] if _token[:1] in ("+", "-") else _token
                return not _digits[:1].isdigit()

            def _vk_ordinal_always_throws(value: str) -> bool:
                # A negative ordinal throws once ggml reaches it (size_t wraps -1 to 2**64-1); earlier tokens must still extract; -0 is 0.
                for _token in value.replace(",", " ").split():
                    _signed = _token[:1] in ("+", "-")
                    _digits = _token[1:] if _signed else _token
                    if not _digits[:1].isdigit():
                        return False  # extraction stops here, so nothing after it is read
                    if _token[:1] == "-" and _digits.lstrip("0"):
                        return True
                return False

            def _is_an_illegal_rocr_selector(value: str) -> bool:
                # An Illegal first ROCr token leaves zero survivors; no group membership fixes it.
                first = value.split(",")[0].strip()
                return (
                    bool(first)
                    and not first.startswith("-")
                    and not first.isdigit()
                    and not first.lower().startswith("gpu-")
                )

            # Per-variable precedence as HIP reads it: clr prefers a non-empty HIP mask over CUDA, ROCr
            # composes below it (an empty ROCr mask blinds the runtime), Windows has no ROCr layer.
            _hip_layer_var = (
                "HIP_VISIBLE_DEVICES"
                if os.environ.get("HIP_VISIBLE_DEVICES", "")
                else "CUDA_VISIBLE_DEVICES"
            )
            _rocr_filters = (
                sys.platform != "win32" and os.environ.get("ROCR_VISIBLE_DEVICES") is not None
            )
            _ordinal_filters = LlamaCppBackend._gpu_device_ordinal_active()

            _post_rocr_count = _post_rocr_device_count()

            masks = []
            blocking = []
            unresolved = []
            for var in (
                "CUDA_VISIBLE_DEVICES",
                "HIP_VISIBLE_DEVICES",
                "ROCR_VISIBLE_DEVICES",
                "GPU_DEVICE_ORDINAL",
            ):
                raw = os.environ.get(var)
                if raw is None:
                    continue
                phrase = f"{var}={raw!r}" if raw.strip() else f"{var} is empty"
                masks.append(phrase)
                if var == "GPU_DEVICE_ORDINAL":
                    _consulted = _ordinal_filters
                elif var == "ROCR_VISIBLE_DEVICES":
                    _consulted = _rocr_filters
                else:
                    _consulted = var == _hip_layer_var
                # A Vulkan build reads none of the four, so none of them blocks it.
                if _is_vulkan or not _consulted:
                    continue
                # ROCr indexes the physical list, the HIP layer indexes ROCr's survivors.
                _rocr = var == "ROCR_VISIBLE_DEVICES"
                _bound = _amd_gpu_count if _rocr else _post_rocr_count
                if _hides_every_device(raw, _bound, strict = not _rocr) or (
                    _rocr and _is_an_illegal_rocr_selector(raw)
                ):
                    blocking.append(phrase)
                elif _cannot_be_resolved(raw):
                    unresolved.append(phrase)
            # A Vulkan build reads only GGML_VK_VISIBLE_DEVICES; without the raw device count only a
            # no-integer first token or a negative ordinal is decidable.
            if _is_vulkan:
                _vk_raw = os.environ.get("GGML_VK_VISIBLE_DEVICES")
                if _vk_raw is not None:
                    _vk_phrase = (
                        f"GGML_VK_VISIBLE_DEVICES={_vk_raw!r}"
                        if _vk_raw.strip()
                        else "GGML_VK_VISIBLE_DEVICES is empty"
                    )
                    masks.append(_vk_phrase)
                    if _vk_selects_no_device(_vk_raw) or _vk_ordinal_always_throws(_vk_raw):
                        blocking.append(_vk_phrase)
                    else:
                        unresolved.append(_vk_phrase)

            mask_note = f" ({', '.join(masks)})" if masks else ""

            node_hint = None
            if _amd_capable:
                try:
                    from utils.hardware.amd import amd_node_permission_hint
                    node_hint = amd_node_permission_hint(needs_kfd = not _is_vulkan)
                except Exception:  # noqa: BLE001
                    node_hint = None

            def _closed_nodes_block_the_runtime() -> bool:
                # An unreadable host answers True, keeping the closed node as the reason, as before the sibling check.
                try:
                    from utils.hardware.amd import amd_closed_nodes_block_the_runtime
                    return amd_closed_nodes_block_the_runtime(needs_kfd = not _is_vulkan)
                except Exception:  # noqa: BLE001
                    return True

            def _another_vendor_has_an_open_node() -> bool:
                # Vulkan enumerates any vendor, so an open non-AMD render node is a complete path; False on a host this cannot read.
                if not _is_vulkan:
                    return False
                # Decided by which drivers the loader can load: an AMD-only loader ignores other vendor open nodes; one that loads them must NOT suppress.
                try:
                    from utils.hardware.amd import (
                        a_non_amd_render_node_is_open,
                        the_vulkan_loader_can_only_load_amd,
                    )
                    if the_vulkan_loader_can_only_load_amd():
                        return False
                    return a_non_amd_render_node_is_open()
                except Exception:  # noqa: BLE001
                    return False

            # Closed node, if it does not explain the empty probe, is appended to the reason, not in place of it.
            _second_finding = ""
            # Sufficient alone, so it rides on the PRIMARY reason, not on whatever gets demoted.
            _loader_finding = ""

            def _the_vulkan_loader_has_no_driver() -> bool:
                try:
                    from utils.hardware.amd import the_vulkan_loader_has_no_usable_driver
                    return the_vulkan_loader_has_no_usable_driver()
                except Exception:  # noqa: BLE001
                    return False

            def _the_loader_override_to_blame() -> "str | None":
                # Which of the three causes it is, since only two are repaired by
                # installing anything.
                try:
                    from utils.hardware.amd import the_vulkan_loader_override_to_blame
                    return the_vulkan_loader_override_to_blame()
                except Exception:  # noqa: BLE001
                    return None

            def _reason(text: str) -> str:
                return f"{text}{_loader_finding}{_second_finding}"

            if node_hint:
                # Only a mask that can hide every device counts as a second blocker beside a closed node.
                if blocking:
                    node_hint = (
                        f"{node_hint} A device visibility mask is also in force "
                        f"({', '.join(blocking)}), which the groups do not clear."
                    )
                elif unresolved:
                    node_hint = (
                        f"{node_hint} {', '.join(unresolved)} names a device this cannot "
                        f"resolve, so whether it also hides the card is unknown; check it "
                        f"if the groups do not help."
                    )
                # A closed node explains the empty probe only if the runtime would have used it (no
                # open sibling).
                _node_is_why = (
                    _closed_nodes_block_the_runtime() and not _another_vendor_has_an_open_node()
                )
                # No loadable manifest is a blocker the node repair cannot clear; keep it out of node_hint.
                _also = "also " if _node_is_why else ""
                if _is_vulkan and _the_vulkan_loader_has_no_driver():
                    # Name the loader override env var so the user knows what to unset.
                    _override = _the_loader_override_to_blame()
                    if _override:
                        _loader_finding = (
                            f" The Vulkan loader {_also}has no driver it can load "
                            f"here, and what leaves it with none is {_override}: clear or "
                            f"correct that, since reinstalling the driver does not change "
                            f"an environment override."
                        )
                    else:
                        _loader_finding = (
                            f" The Vulkan loader {_also}has no driver it can load "
                            f"here: every ICD manifest it would read is missing its library "
                            f"or is 32-bit, so reinstall the Vulkan driver as well."
                        )
                if _node_is_why:
                    return f"{node_hint}{_loader_finding}"
                _second_finding = f" Separately, and not why the probe is empty: {node_hint}"
            if _is_vulkan:
                return _reason("the Vulkan probe reported no device")

            try:
                import torch
            except Exception:  # noqa: BLE001
                return _reason(f"torch is not importable, so no GPU could be enumerated{mask_note}")
            if not hasattr(torch, "cuda") or not torch.cuda.is_available():
                return _reason(f"torch reports no usable CUDA or HIP device{mask_note}")
            # Counting devices does not create a context; reading their memory would.
            count = torch.cuda.device_count()
            if not count:
                return _reason(f"torch enumerated 0 devices{mask_note}")

            if LlamaCppBackend._torch_is_rocm(torch):
                coverage = LlamaCppBackend._installed_llama_gfx_archs(binary)
                if coverage:
                    present = sorted(set(LlamaCppBackend._rocm_arch_by_physical_id().values()))
                    if present and not (set(present) & set(coverage)):
                        return _reason(
                            f"the installed llama.cpp build covers {sorted(coverage)} but this "
                            f"host has {present}, so the arch gate dropped every device"
                        )
                return _reason(
                    f"torch sees {count} ROCm device(s) but the probe returned none, so "
                    f"amd-smi and the torch fallback both declined{mask_note}"
                )
            return _reason(f"torch sees {count} device(s) but the probe returned none{mask_note}")
        except Exception as e:  # noqa: BLE001 -- diagnostics must not break a load
            return f"the reason could not be determined ({type(e).__name__})"

    @staticmethod
    def _nvidia_probe_script() -> Optional[Path]:
        """studio/nvidia_probe.py, the installers' NVML / CUDA driver reader (UNSLOTH_NVIDIA_PROBE wins)."""
        from utils.prebuilt.update_flow import find_installer_script
        return find_installer_script(env_var = "UNSLOTH_NVIDIA_PROBE", script_name = "nvidia_probe.py")

    @staticmethod
    def _nvml_rows_visible(rows: list[dict]) -> list[dict]:
        """The NVML rows CUDA_VISIBLE_DEVICES permits, in mask order: an index or a GPU-/MIG-
        uuid prefix per entry, as the CUDA runtime reads it. An entry naming no single device
        ends the mask there: "0,2,-1,1" exposes 0 and 2, "-1" alone hides every GPU, and a
        repeated index empties it, as CUDA does. A GPU in MIG mode is one row backed by one
        slice, which the child is pinned to: the first slice the mask names, else the one with
        the least free memory, so the budget never exceeds the device the child gets (R570+
        enumerates every slice, but one per card is sized and pinned)."""
        raw = os.environ.get("CUDA_VISIBLE_DEVICES")
        parents = [r for r in rows if not r.get("mig")]

        def free_mib(r: dict) -> int:
            try:
                return int(r.get("memory_free_mib") or 0)
            except (TypeError, ValueError):
                return 0

        def as_cuda_sees(r: dict) -> dict:
            if r.get("mig"):
                return r  # a slice the mask named stays that slice
            slices = [
                s for s in rows if s.get("mig") and str(s.get("index")) == str(r.get("index"))
            ]
            return min(slices, key = free_mib) if slices else r

        tokens = [t.strip() for t in (raw or "").split(",")] if raw else []
        picked: list[dict] = []
        if raw is None:
            picked = [as_cuda_sees(r) for r in parents]
        seen: set[int] = set()
        for token in tokens:
            if not token:
                break  # an empty entry ends the mask, as CUDA reads it
            prefix = re.match(r"\+?\d+", token)
            # Case-insensitive, as the nvidia-smi uuid matcher reads the same mask.
            low = token.lower()
            if low.startswith("gpu-"):
                hits = [r for r in parents if str(r.get("uuid", "")).lower().startswith(low)]
            elif low.startswith("mig-"):
                # A MIG- entry names a slice row the probe lists under its parent.
                hits = [
                    r
                    for r in rows
                    if r.get("mig") and str(r.get("uuid", "")).lower().startswith(low)
                ]
            elif prefix:
                # CUDA reads an index strtoul-style: "1gpu2" is GPU 1.
                index = int(prefix.group())
                if index in seen:
                    return []
                seen.add(index)
                hits = [r for r in parents if str(r.get("index")) == str(index)]
            else:
                hits = []
            if len(hits) != 1:
                break
            if str(hits[0].get("index")) not in {str(p.get("index")) for p in picked}:
                picked.append(as_cuda_sees(hits[0]))
        return picked

    @staticmethod
    def _uuid_by_index(rows: list[dict]) -> dict[int, str]:
        """The uuid each visible index stands for: every row when the mask named rows by
        uuid, else only a slice standing in for its MIG parent (a slice has no index of its
        own). Derived from the rows and the mask on each call, so it belongs to no probe."""
        tokens = [t.strip() for t in (os.environ.get("CUDA_VISIBLE_DEVICES") or "").split(",")]
        by_uuid = any(t and not t.isdigit() for t in tokens)
        return {
            int(r["index"]): str(r["uuid"])
            for r in LlamaCppBackend._nvml_rows_visible(rows)
            if str(r.get("index", "")).isdigit() and (by_uuid or r.get("mig"))
        }

    @staticmethod
    def _child_visibility_for(gpu_indices) -> str:
        """The mask for these indices: the inherited uuids when the mask named the rows by
        uuid (a MIG slice must stay a MIG- entry), else the indices themselves."""
        ids = [int(i) for i in gpu_indices]
        by_index = LlamaCppBackend._uuid_by_index(LlamaCppBackend._NVML_ROWS)
        if by_index and all(i in by_index for i in ids):
            return ",".join(by_index[i] for i in ids)
        return ",".join(str(i) for i in ids)

    @staticmethod
    def _pinned_child_visibility(gpu_indices) -> Optional[str]:
        """``_child_visibility_for``, or None when the inherited CUDA mask must stand: a MIG
        or unresolvable UUID mask the ids cannot be mapped back to, where a numeric pin would
        be re-read against the whole host (a card the parent hid, or the whole MIG card)."""
        cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
        mig_rows = LlamaCppBackend._mig_snapshot_rows()
        if mig_rows is not None:
            from utils.hardware import mig
            return mig.visibility_for(mig_rows, gpu_indices)
        if (
            LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is False
            and cvd is not None
            and cvd.strip()
            and LlamaCppBackend._visibility_mask_is_unmappable()
        ):
            # Torch ordinals: map through the mask itself, never through NVML rows cached by
            # an earlier probe (their indices are physical, so ordinal 0 could name another slice).
            return LlamaCppBackend._mig_tokens_for_ordinals(cvd, gpu_indices)
        mask = LlamaCppBackend._child_visibility_for(gpu_indices)
        if (
            cvd is not None
            and cvd.strip()
            and mask == ",".join(str(int(i)) for i in gpu_indices)
            and LlamaCppBackend._visible_devices_mask("CUDA_VISIBLE_DEVICES") is None
            and LlamaCppBackend._visibility_mask_is_unmappable()
        ):
            # Physical rows the memory probe matched by uuid: hand the child those uuids.
            uuids = LlamaCppBackend._smi_uuids_for(cvd, gpu_indices)
            if uuids is not None:
                return uuids
            return LlamaCppBackend._mig_tokens_for_ordinals(cvd, gpu_indices)
        return mask

    @staticmethod
    def _smi_uuid_mask_order() -> Optional[list[int]]:
        """Physical ids of a whole-GPU uuid mask in mask order, from the last nvidia-smi
        rows; None unless the probe's ids are physical and every token matched a row."""
        cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
        if LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is not True or not (cvd or "").strip():
            return None
        from utils.hardware import nvidia

        visible = nvidia._uuid_visible_ordinal_map(cvd, LlamaCppBackend._SMI_UUID_ROWS)
        return sorted(visible, key = visible.__getitem__) if visible else None

    @staticmethod
    def _smi_uuids_for(cvd: str, gpu_indices) -> Optional[str]:
        """The uuids of these physical ids when the current whole-GPU uuid mask names each
        of them in the last nvidia-smi rows, else None. Never for a MIG card: CUDA hands a
        GPU- entry on one a slice, which only the NVML rows name."""
        if LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is not True:
            return None
        from utils.hardware import nvidia

        rows = LlamaCppBackend._SMI_UUID_ROWS
        visible = nvidia._uuid_visible_ordinal_map(cvd, rows)
        try:
            ids = [int(i) for i in gpu_indices]
        except (TypeError, ValueError):
            return None
        if not visible or not ids or len(set(ids)) != len(ids):
            return None
        if any(i not in visible for i in ids):
            return None
        # The probe that chose these rows classified them; a later recheck failing must
        # not widen the child to the whole inherited mask.
        mig = LlamaCppBackend._SMI_MIG_INDICES
        if mig is None:
            # Unknown then too: NVML rows from that probe still name MIG cards.
            mig = {
                int(r["index"])
                for r in LlamaCppBackend._NVML_ROWS
                if r.get("mig") and str(r.get("index", "")).isdigit()
            }
        if set(ids) & mig:
            return None
        by_index = dict(rows)
        return ",".join(by_index[i] for i in ids)

    @staticmethod
    def _mig_tokens_for_ordinals(cvd: str, gpu_indices) -> Optional[str]:
        """The inherited MIG- entries behind torch ordinals, or None (keep the whole mask). Only
        when torch enumerated every entry, so ordinal i is entry i in mask order."""
        tokens = [t.strip() for t in cvd.split(",") if t.strip()]
        if LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is not False or not all(
            t.startswith("MIG-") for t in tokens
        ):
            return None
        try:
            import torch
            if torch.cuda.device_count() != len(tokens):
                return None
            ids = [int(i) for i in gpu_indices]
        except Exception:
            return None
        if not ids or len(set(ids)) != len(ids) or not all(0 <= i < len(tokens) for i in ids):
            return None
        return ",".join(tokens[i] for i in ids)

    @staticmethod
    def _get_gpu_memory_nvml() -> list[tuple[int, int, int]]:
        """Free/total per NVIDIA GPU via NVML in a child for hosts whose nvidia-smi is absent or hung; a row without memory voids the answer."""
        if sys.platform == "darwin" or os.environ.get("UNSLOTH_NVIDIA_LIBRARY_PROBE", "1") == "0":
            return []
        script = LlamaCppBackend._nvidia_probe_script()
        if script is None:
            return []
        try:
            result = subprocess.run(
                [sys.executable, "-I", str(script), "--json"],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = utf8_child_env(child_env_without_native_path_secret()),
                **_windows_hidden_subprocess_kwargs(),
            )
            payload = json.loads(result.stdout or "null")
        except Exception as e:
            logger.debug(f"NVML probe failed: {e}")
            return []
        if not isinstance(payload, dict) or payload.get("source") != "nvml":
            return []
        LlamaCppBackend._NVML_ROWS = list(payload.get("devices") or [])
        gpus: list[tuple[int, int, int]] = []
        for row in LlamaCppBackend._nvml_rows_visible(LlamaCppBackend._NVML_ROWS):
            try:
                idx = int(row["index"])
                free_mib = int(row.get("memory_free_mib") or 0)
                total_mib = int(row.get("memory_total_mib") or 0)
            except (KeyError, TypeError, ValueError):
                return []
            if total_mib <= 0:
                # One visible GPU without a reading voids the answer; a full card (free 0) is still a reading.
                return []
            gpus.append((idx, free_mib, total_mib))
        gpus.sort(key = lambda g: g[0])
        return gpus

    @staticmethod
    def _whole_gpu_mask_rows(
        cvd: str, uuid_rows: list[tuple[int, str]], physical_ids: set[int]
    ) -> Optional[set[int]]:
        """Physical rows behind a whole-GPU uuid mask the ordinal resolvers left open.
        A uuid names its card whatever CUDA_DEVICE_ORDER says, so only membership is
        needed. None for a MIG mask or a token no row verifies, so the caller keeps
        its conservative path."""
        from utils.hardware import nvidia

        tokens = [t.strip().lower() for t in cvd.split(",") if t.strip()]
        if not tokens or any(not t.startswith("gpu-") for t in tokens):
            return None
        if uuid_rows:
            visible = nvidia._uuid_visible_ordinal_map(cvd, uuid_rows)
            return set(visible) if visible is not None else None
        # No uuid column: verify with the separate uuid query, never assume. Only a
        # one-card mask: these rows carry no uuids to order or pin a multi-card subset,
        # while the inherited mask already pins a single card.
        ids = nvidia.resolve_uuid_mask(cvd)
        return set(ids) if ids and len(ids) == 1 and set(ids) <= physical_ids else None

    @staticmethod
    def _get_gpu_memory(
        binary: Optional[str] = None, *, for_llama_server: bool = False
    ) -> list[tuple[int, int, int]]:
        """Order nvidia-smi, amd-smi, then torch last (permanent CUDA/HIP context); Vulkan probe on Vulkan builds; for_llama_server adds ROCm arch gate."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if LlamaCppBackend._is_vulkan_backend(binary):
            return LlamaCppBackend._get_gpu_free_memory_vulkan(binary)
        from utils.hardware import mig

        mig_rows = mig.visible_devices(fresh = True, listing = True)
        LlamaCppBackend._MIG_DEVICE_SNAPSHOT = None
        if mig_rows is not None:
            # CUDA device ids; unknown memory stays zero rather than dropping a device.
            LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = False
            LlamaCppBackend._MIG_DEVICE_SNAPSHOT = (
                os.environ.get("CUDA_VISIBLE_DEVICES"),
                os.environ.get("CUDA_DEVICE_ORDER"),
                mig_rows,
            )
            gpus = sorted(
                (
                    int(r["index"]),
                    int(r.get("memory_free_mib") or 0),
                    int(r.get("memory_total_mib") or 0),
                )
                for r in mig_rows
            )
            return LlamaCppBackend._cuda_sm_gate_keep(binary, gpus) if for_llama_server else gpus
        # ── NVIDIA via nvidia-smi ────────────────────────────────────
        unsized_ids: list[int] = []
        mig_card_rows: list[tuple[int, int, int]] = []
        try:
            from utils.hardware import gpu_query

            # Placement / fit: never a cached reading. A hung CLI raises so the MIG-aware NVML branch runs.
            result = gpu_query.run_nvidia_smi(
                [
                    "nvidia-smi",
                    # uuid in the same call: a whole-GPU uuid mask resolves without
                    # CUDA_DEVICE_ORDER or a second query.
                    "--query-gpu=index,memory.free,memory.total,uuid",
                    "--format=csv,noheader,nounits",
                ],
                capture_output = True,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 10,
                env = child_env_without_native_path_secret(),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode == 0:
                from utils.hardware import nvidia

                allowed = LlamaCppBackend._visible_devices_mask("CUDA_VISIBLE_DEVICES")
                _cvd = (os.environ.get("CUDA_VISIBLE_DEVICES") or "").strip()
                rows: list[tuple[int, int, int]] = []
                unsized_rows: list[int] = []
                uuid_rows: list[tuple[int, str]] = []
                for line in result.stdout.strip().splitlines():
                    parts = [p.strip() for p in line.split(",")]
                    if len(parts) < 2:
                        continue
                    if len(parts) >= 4 and parts[0].isdigit() and parts[3]:
                        uuid_rows.append((int(parts[0]), parts[3]))
                    # Index and free required; skip a bad line rather than abandon
                    # the probe to the torch fallback.
                    try:
                        idx = int(parts[0])
                        free_mib = int(parts[1])
                    except ValueError:
                        # Jetson answers "[N/A]": no dedicated VRAM (#4862).
                        if parts[0].isdigit():
                            unsized_rows.append(int(parts[0]))
                        continue
                    # Total parsed separately: N/A on MIG/vGPU keeps the GPU at total 0 instead of dropping it.
                    total_mib = 0
                    if len(parts) >= 3 and parts[2]:
                        try:
                            total_mib = int(parts[2])
                        except ValueError:
                            total_mib = 0
                    rows.append((idx, free_mib, total_mib))
                LlamaCppBackend._SMI_UUID_ROWS = uuid_rows
                LlamaCppBackend._SMI_MIG_INDICES = None
                if allowed is None and _cvd:
                    allowed = LlamaCppBackend._whole_gpu_mask_rows(
                        _cvd, uuid_rows, {r[0] for r in rows} | set(unsized_rows)
                    )
                if allowed is None and _cvd:
                    # CUDA's numeric-prefix reading ("1gpu2" is 1, "0,1,abc" is 0,1).
                    _ids = LlamaCppBackend._resolve_visible_physical_ids()
                    allowed = set(_ids) if _ids is not None else None
                unsized_ids = [i for i in unsized_rows if allowed is None or i in allowed]
                gpus = [r for r in rows if allowed is None or r[0] in allowed]
                # Match the docstring's sort-by-id guarantee (driver order isn't).
                gpus.sort(key = lambda g: g[0])
                if allowed is None and _cvd:
                    # A MIG / unresolvable UUID mask names devices these rows cannot be
                    # matched to: listing every card sizes against GPUs the parent hid.
                    # The NVML branch names slices and uuids.
                    gpus = []
                elif gpus:
                    mig_known = nvidia.get_mig_gpu_indices_or_none()
                    if mig_known is not None:
                        LlamaCppBackend._SMI_MIG_INDICES = frozenset(mig_known)
                    mig = (mig_known or set()) & {g[0] for g in gpus}
                    if mig_known is None:
                        # MIG discovery failed: a row may be a whole MIG card. NVML names
                        # slices and whole cards alike, so its reading wins; without one
                        # the CLI rows stand, as before MIG support (no CUDA context).
                        nvml = {g[0]: g for g in LlamaCppBackend._get_gpu_memory_nvml()}
                        if nvml:
                            gpus = [nvml.get(g[0], g) for g in gpus]
                        else:
                            # No current NVML inventory: an older one must not name devices.
                            LlamaCppBackend._NVML_ROWS = []
                    elif not mig:
                        # The CLI now answers for these cards: an earlier NVML inventory
                        # (slices since removed) must not name the child's devices.
                        LlamaCppBackend._NVML_ROWS = []
                    if mig:
                        # A MIG card's row is the whole card: swap in its NVML slice reading,
                        # keeping the whole cards. No reading at all: the later probes decide,
                        # then these rows as before.
                        slices = {g[0]: g for g in LlamaCppBackend._get_gpu_memory_nvml()}
                        mig_card_rows = gpus
                        gpus = [slices.get(g[0], g) if g[0] in mig else g for g in gpus]
                        gpus = [g for g in gpus if g[0] not in mig or g[0] in slices]
                if gpus:
                    LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = True
                    if for_llama_server:
                        gpus = LlamaCppBackend._cuda_sm_gate_keep(binary, gpus)
                    # The CLI row is the carve-out, not the pool. Discrete rows unchanged.
                    return LlamaCppBackend._widen_integrated_cuda_rows(gpus)
        except Exception as e:
            logger.debug(f"nvidia-smi probe failed: {e}")

        # ── NVIDIA via NVML, when nvidia-smi is absent, stale or hung ────
        nvml_gpus = LlamaCppBackend._get_gpu_memory_nvml()
        if nvml_gpus:
            LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = True
            if for_llama_server:
                nvml_gpus = LlamaCppBackend._cuda_sm_gate_keep(binary, nvml_gpus)
            # nvidia-smi IS NVML: same carve-out, same PCI indexing, same correction.
            return LlamaCppBackend._widen_integrated_cuda_rows(nvml_gpus)

        # ── AMD ROCm via amd-smi ─────────────────────────────────────
        rocm_gpus = LlamaCppBackend._get_gpu_memory_amd_smi(
            binary, for_llama_server = for_llama_server
        )
        if rocm_gpus:
            return rocm_gpus

        # ── Torch fallback (covers AMD ROCm and missing nvidia-smi) ──
        gpus = (
            []
            if _GPU_MEMORY_SKIP_TORCH.get()
            else LlamaCppBackend._get_gpu_memory_torch(binary, for_llama_server)
        )
        if not gpus and mig_card_rows:
            LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = True
            return LlamaCppBackend._widen_integrated_cuda_rows(mig_card_rows)
        if gpus or not (for_llama_server and unsized_ids):
            return gpus
        return LlamaCppBackend._tegra_unified_memory_rows(unsized_ids)

    @staticmethod
    def _tegra_unified_memory_rows(gpu_ids: list[int]) -> list[tuple[int, int, int]]:
        """Price a Jetson's GPU from system RAM when nvidia-smi answers ``[N/A]`` and
        torch cannot see it (a generic aarch64 wheel), so the context is still capped
        (#4862). llama-server only: it runs on JetPack's CUDA, torch-backed callers do not."""
        from utils.tegra import is_tegra

        if not is_tegra():
            return []
        avail = LlamaCppBackend._available_system_memory_mib()
        if avail is None:
            return []
        cgroup_mib = LlamaCppBackend._cgroup_available_memory_mib()
        # Same policy as the torch integrated branch: a cgroup-bound pool publishes no total.
        total = (
            0
            if cgroup_mib is not None and cgroup_mib <= avail
            else LlamaCppBackend._total_system_memory_mib() or 0
        )
        free = _apply_igpu_host_reserve_mib(avail, True)
        LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = True
        # Torch never saw these, so record them as integrated or the pool is credited twice.
        LlamaCppBackend._INTEGRATED_CUDA_IDS[LlamaCppBackend._integrated_cuda_mask_key()] = set(
            gpu_ids
        )
        return [(idx, free, total) for idx in sorted(gpu_ids)]

    @staticmethod
    def _get_gpu_memory_torch(
        binary: Optional[str], for_llama_server: bool
    ) -> list[tuple[int, int, int]]:
        """The torch arm of ``_get_gpu_memory``."""
        try:
            import torch

            if not hasattr(torch, "cuda") or not torch.cuda.is_available():
                return []
            if not hasattr(torch.cuda, "mem_get_info"):
                return []
            # CUDA ordinals from here on, not nvidia-smi PCI indices.
            LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES = False
            # torch ordinals are relative to the mask: translate to physical ids before CVD; an empty mask means no GPUs, so never use or to fall back.
            physical_ids = LlamaCppBackend._resolve_visible_physical_ids()
            # Shared-pool APU: report total 0 since that total is system RAM.
            unified_ids = LlamaCppBackend._rocm_unified_memory_gpu_ids()
            # Integrated CUDA SoCs share one pool too, and their free reading errs the opposite way to ROCm's.
            integrated_ids = LlamaCppBackend._integrated_cuda_gpu_ids()
            # Same #7624 arch gate the amd-smi branch applies, from the one helper.
            arch_keeps = LlamaCppBackend._rocm_arch_gate_keep(binary, torch, for_llama_server)
            # Read once from the set the loop tests, so count and decision agree (no division by zero).
            shared_cuda_count = sum(1 for _i in integrated_ids if arch_keeps(_i))
            gpus = []
            # Windows ROCm over-reports free on discrete cards too; cap against this process's allocator.
            from utils.hardware import trusted_mem_get_info

            for ordinal in range(torch.cuda.device_count()):
                free_bytes, total_bytes = trusted_mem_get_info(ordinal)
                idx = (
                    physical_ids[ordinal]
                    if physical_ids is not None and ordinal < len(physical_ids)
                    else ordinal
                )
                if not arch_keeps(idx):
                    continue
                shared = idx in unified_ids
                integrated = idx in integrated_ids
                cgroup_bound = False
                raw_mib = free_bytes // (1024 * 1024)
                total_mib = total_bytes // (1024 * 1024)
                if shared:
                    # ROCm free is unreliable on a shared pool (Windows free==total); cap at system RAM before taking the reserve.
                    avail = LlamaCppBackend._available_system_memory_mib()
                    if avail is not None:
                        raw_mib = min(raw_mib, avail)
                elif integrated:
                    # cudaMemGetInfo free is MemFree, which counts page cache as used; MemAvailable
                    # adds it back.
                    avail = LlamaCppBackend._available_system_memory_mib()
                    # A zero total is a probe that could not size the pool, not a pool
                    # of zero: capping against it would take the device to nothing.
                    if avail is not None and total_mib > 0:
                        raw_mib = min(total_mib, max(raw_mib, avail))
                    # cgroup available is a ceiling too, since allocations are charged to the cgroup.
                    # `<=` on purpose: equality is normal when the cgroup caps MemAvailable.
                    cgroup_mib = LlamaCppBackend._cgroup_available_memory_mib()
                    if cgroup_mib is not None and cgroup_mib <= raw_mib:
                        raw_mib = cgroup_mib
                        # The pool is the container's: publish no total so the reserve is not taken
                        # from host memory.
                        cgroup_bound = True
                    # One pool shared by all integrated devices: split it so sums do not double count.
                    if shared_cuda_count > 1:
                        raw_mib //= shared_cuda_count
                        total_mib //= shared_cuda_count
                free_mib = _apply_igpu_host_reserve_mib(raw_mib, shared or integrated)
                if free_mib < raw_mib:
                    logger.info(
                        f"{'CUDA' if integrated else 'ROCm'} device {idx} is a "
                        f"unified-memory {'SoC' if integrated else 'APU'} sharing system "
                        f"RAM; reserving {raw_mib - free_mib}MiB host headroom "
                        f"({raw_mib}->{free_mib}MiB usable)"
                    )
                # ROCm publishes 0 for a shared pool because that total is system RAM of unknown scope; zeroing it would drop to free*frac.
                gpus.append((idx, free_mib, 0 if shared or cgroup_bound else total_mib))
            # Match the nvidia-smi path's docstring guarantee of sorted-by-id.
            return sorted(gpus, key = lambda g: g[0])
        except Exception as e:
            logger.debug(f"torch GPU probe failed: {e}")
            return []

    @staticmethod
    def _vulkan_auto_gpu_memory(gpus: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
        """Prefer discrete devices for automatic Vulkan placement."""
        discrete = [gpu for gpu in gpus if gpu[2] > 0]
        return discrete or gpus

    @staticmethod
    def _run_vulkan_probe(binary: Optional[str] = None) -> list[dict]:
        """Indices are ggml's compact Vulkan ordinals, as --device Vulkan<i> selects, not raw
        enumeration."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return []
        # Memoised per load (15s subprocess); cleared by _load_probe_memo_scope.
        _memo = _load_probe_memo_get("vulkan", binary)
        if _memo is not None:
            return _memo
        binary_dir = _llama_lib_dir(binary)
        if not _lib_dir_has_ggml_backend(binary_dir, "vulkan"):
            _load_probe_memo_put("vulkan_outcome", binary, "error")
            _load_probe_memo_put("vulkan", binary, [])
            return []

        env = child_env_without_native_path_secret()
        # Let ggml apply GGML_VK_VISIBLE_DEVICES; Python sees compact ordinals.
        if sys.platform != "win32":
            # _loader_path_var keeps macOS off LD_LIBRARY_PATH, which dyld ignores.
            _loader_var = _loader_path_var()
            existing_ld = env.get(_loader_var, "")
            env[_loader_var] = (
                f"{binary_dir}{os.pathsep}{existing_ld}" if existing_ld else str(binary_dir)
            )
        probe_script = Path(__file__).with_name("_vulkan_probe.py")
        try:
            # UTF-8: device names can be non-ASCII and a cp1252 decode could throw.
            result = subprocess.run(
                [sys.executable, str(probe_script), str(binary_dir)],
                capture_output = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 15,
                env = utf8_child_env(env),
                **_windows_hidden_subprocess_kwargs(),
            )
            if result.returncode != 0:
                logger.debug(
                    f"vulkan GPU probe exited {result.returncode}: {result.stderr.strip()}"
                )
                # Suspect only, never proof: a driver can fault on exit after listing a device.
                _crashed = LlamaCppBackend._is_signal_crash(result.returncode) or (
                    sys.platform == "win32" and LlamaCppBackend._is_abort_exit(result.returncode)
                )
                _load_probe_memo_put("vulkan_outcome", binary, "crashed" if _crashed else "error")
                _load_probe_memo_put("vulkan", binary, [])
                return []
        except subprocess.TimeoutExpired as e:
            # Suspect, not absent: a healthy discrete card can take longer than this.
            logger.info(f"vulkan GPU probe timed out: {e}")
            _load_probe_memo_put("vulkan_outcome", binary, "timeout")
            _load_probe_memo_put("vulkan", binary, [])
            return []
        except Exception as e:
            logger.debug(f"vulkan GPU probe failed: {e}")
            # Memoised too: an unanswered probe comes straight back here, so an uncached
            # timeout is paid twice over and again per rung.
            _load_probe_memo_put("vulkan_outcome", binary, "error")
            _load_probe_memo_put("vulkan", binary, [])
            return []

        rows: list[dict] = []
        for line in result.stdout.strip().splitlines():
            parts = line.split("\t")
            # 4 columns from an older probe (no name); 5 with the name column, 7 with the PCI id.
            if len(parts) not in (4, 5, 6, 7):
                continue
            try:
                free_b, total_b = int(parts[1]), int(parts[3])
                # Intel's Windows driver can report budget > heap size (ggml-org/llama.cpp#29277).
                if 0 < total_b < free_b:
                    free_b = total_b
                rows.append(
                    {
                        "index": int(parts[0]),
                        "free_mib": free_b // (1024 * 1024),
                        "is_igpu": parts[2] == "1",
                        "total_mib": total_b // (1024 * 1024),
                        "name": parts[4].strip() if len(parts) >= 5 else "",
                        # Absent on an older staged probe, so it reads unknown and declines.
                        "type_known": len(parts) >= 6 and parts[5].strip() == "1",
                        "pci_id": parts[6].strip().lower() if len(parts) >= 7 else "",
                    }
                )
            except ValueError:
                continue
        rows.sort(key = lambda r: r["index"])
        if rows:
            _outcome = "devices"
        else:
            # Unparseable output is not proof of zero devices.
            _outcome = "error" if result.stdout.strip() else "none"
        _load_probe_memo_put("vulkan_outcome", binary, _outcome)
        _load_probe_memo_put("vulkan", binary, rows)
        return rows

    @staticmethod
    def _vulkan_probe_outcome(binary: Optional[str] = None) -> str:
        """``devices``, ``none`` (enumerated zero), ``timeout``, ``crashed`` or ``error``,
        from this load's probe memo. Unarmed (outside a load) only ``devices`` / ``error``.
        """
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return "error"
        if LlamaCppBackend._run_vulkan_probe(binary):
            return "devices"
        outcome = _load_probe_memo_get("vulkan_outcome", binary)
        return outcome if outcome in ("none", "timeout", "crashed") else "error"

    @staticmethod
    def vulkan_device_inventory(binary: Optional[str] = None) -> list[dict]:
        """UI-facing Vulkan device list: the devices llama-server will actually
        use, with real totals (an iGPU keeps its shared-RAM total here -- the
        caller labels it, unlike the fit which zeroes it). Same rows as
        ``_run_vulkan_probe``; names fall back to ``Vulkan<i>``.
        """
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return []
        from utils import gpu_memory_events
        from utils.hardware import gpu_query

        use_cache = gpu_query.display_cache_allowed() and not _load_probe_memo_armed()
        key = ("vulkan", binary)
        if use_cache:
            with _vulkan_inventory_lock:
                entry = _vulkan_inventory_cache.get(key)
            if (
                entry is not None
                and time.monotonic() - entry[0] < _VULKAN_INVENTORY_TTL_S
                and entry[1] == gpu_memory_events.generation()
            ):
                return [dict(row) for row in entry[2]]
        generation = gpu_memory_events.generation()
        rows = LlamaCppBackend._run_vulkan_probe(binary)
        for row in rows:
            if not row["name"]:
                row["name"] = f"Vulkan{row['index']}"
        # An empty answer may be a failed probe: never served, like gpu_query's failures.
        with _vulkan_inventory_lock:
            if rows:
                _vulkan_inventory_cache[key] = (
                    time.monotonic(),
                    generation,
                    [dict(row) for row in rows],
                )
            else:
                _vulkan_inventory_cache.pop(key, None)
        return rows

    @staticmethod
    def _get_gpu_free_memory_vulkan(binary: Optional[str] = None) -> list[tuple[int, int, int]]:
        """Fit view of Vulkan probe: (index, free, total) sorted; iGPU total 0 so fit uses free*frac; [] when no device reachable."""
        gpus: list[tuple[int, int, int]] = []
        for row in LlamaCppBackend._run_vulkan_probe(binary):
            idx, free_mib, is_igpu = row["index"], row["free_mib"], row["is_igpu"]
            # iGPU total is shared RAM: keep 0 so the fit uses free*frac.
            total_mib = 0 if is_igpu else row["total_mib"]
            capped = _apply_igpu_host_reserve_mib(free_mib, is_igpu)
            if capped < free_mib:
                logger.info(
                    f"Vulkan device VK{idx} is an integrated GPU sharing system "
                    f"RAM; reserving {free_mib - capped}MiB host headroom "
                    f"({free_mib}->{capped}MiB usable)"
                )
            gpus.append((idx, capped, total_mib))
        if gpus:
            logger.info(
                "Vulkan GPU memory detected: "
                + ", ".join(f"VK{idx}={free}MiB" for idx, free, _total in gpus)
            )
        return gpus

    @staticmethod
    def _igpu_backed_free_mib(free_mib: int, headroom_mib: int = 0) -> int:
        """Bounds a raw iGPU free reading by host RAM; not applicable on WSL, whose VM and adapter
        disagree."""
        available = LlamaCppBackend._available_system_memory_mib()
        total_ram = LlamaCppBackend._total_system_memory_mib()
        if available is None or total_ram is None:
            return free_mib
        unseen = 0 if _is_wsl() else max(0, free_mib - total_ram)
        host_backed = max(0, available - max(0, headroom_mib))
        return min(free_mib, unseen + host_backed)

    @staticmethod
    def _igpu_backed_usable_mib(usable_mib: int) -> int:
        """Admission bound for post-reserve iGPU budget; placement keeps the raw reading to avoid
        demotion."""
        if usable_mib <= 0:
            return 0
        raw_free_mib = usable_mib + _IGPU_HOST_RESERVE_MIB
        backed_mib = LlamaCppBackend._igpu_backed_free_mib(
            raw_free_mib, headroom_mib = _HOST_RAM_HEADROOM_MIB
        )
        return min(usable_mib, backed_mib)

    @staticmethod
    def _cgroup_memory_budgets() -> list[tuple[int, int]]:
        """Memory this process may still charge to an enforcing cgroup; empty when no finite limit."""
        return _host_memory.cgroup_memory_budgets(_CGROUP_ROOT, _PROC_SELF_CGROUP)

    @staticmethod
    def _cgroup_available_memory_mib() -> Optional[int]:
        """What this process can still charge, i.e. the tightest REMAINDER."""
        return _host_memory.cgroup_headroom_mib(LlamaCppBackend._cgroup_memory_budgets())

    @staticmethod
    def _cgroup_memory_limit_mib() -> Optional[int]:
        """Tightest cgroup LIMIT, i.e. capacity; never the remainder, which shrinks as the container
        fills."""
        return _host_memory.cgroup_limit_mib(LlamaCppBackend._cgroup_memory_budgets())

    @staticmethod
    def _available_system_memory_mib() -> Optional[int]:
        """Available system RAM MiB (psutil, then /proc/meminfo), None if unreadable, capped by cgroup remainder; the APU ceiling."""
        return _host_memory.usable_mib(
            _host_memory.system_available_mib(), LlamaCppBackend._cgroup_available_memory_mib()
        )

    @staticmethod
    def _total_system_memory_mib() -> Optional[int]:
        """Total system RAM MiB (psutil, then /proc/meminfo), None if unreadable; the ceiling MemAvailable can reach."""
        return _host_memory.system_total_mib()

    @staticmethod
    def _host_memory_capacity_mib() -> Optional[int]:
        """Host RAM this process may charge: MemTotal narrowed by a cgroup LIMIT, not the remainder."""
        return _host_memory.usable_mib(
            LlamaCppBackend._total_system_memory_mib(), LlamaCppBackend._cgroup_memory_limit_mib()
        )

    _ARGV_MODEL = frozenset({"-m", "--model"})
    _ARGV_RPC = frozenset({"--rpc"})

    @staticmethod
    def _binary_ships_no_gpu_backend(
        binary: Optional[str] = None, env: Optional[Mapping[str, str]] = None
    ) -> bool:
        """True when no GPU backend; SYCL, MUSA, CANN, OpenCL count as GPU; static or unreadable layouts and GGML_BACKEND_PATH answer False."""
        binary = binary or LlamaCppBackend._find_llama_server_binary()
        if not binary:
            return False
        source = os.environ if env is None else env
        if str(source.get("GGML_BACKEND_PATH", "") or "").strip():
            return False
        try:
            files = tuple(path.name for path in _llama_lib_dir(binary).iterdir() if path.is_file())
        except OSError:
            return False
        cpu_stem = "ggml-cpu" if sys.platform == "win32" else "libggml-cpu"
        base_stem = "ggml-base" if sys.platform == "win32" else "libggml-base"
        split_library = any(name.startswith((cpu_stem, base_stem)) for name in files)
        return split_library and not any(_GGML_GPU_BACKEND_RE.match(name) for name in files)

    def _argv_offloads_every_layer(
        self,
        argv: Iterable[str],
        env: Optional[Mapping[str, str]] = None,
    ) -> bool:
        """Unknown placement counts as partial offload, so unverified GPU memory is never credited."""
        args = [str(a) for a in argv or ()]
        if _device_selection_is_cpu(args, env):
            return False
        if _args_place_tensors_on_cpu(args) or _env_places_tensors_on_cpu(env):
            return False
        # The fitter owns placement unless it is explicitly disabled.
        if fit_is_effectively_on(args, env):
            return False
        try:
            requested = parse_gpu_layers_override(args)
        except ValueError:
            return False
        if requested is None:
            return False
        # -1 means every layer; otherwise the count must exceed the block count.
        n_layers = self.n_layers
        return requested == -1 or (bool(n_layers) and requested > n_layers)

    def _launch_forces_full_offload(
        self,
        argv: Iterable[str],
        env: Optional[Mapping[str, str]] = None,
    ) -> bool:
        """Whether every layer is on GPU: a user count above block count stands under --fit on; no count with fitter off (default -1) too."""
        args = [str(a) for a in argv or ()]
        if self._argv_offloads_every_layer(args, env):
            return True
        if _device_selection_is_cpu(args, env):
            return False
        if _args_place_tensors_on_cpu(args) or _env_places_tensors_on_cpu(env):
            return False
        try:
            requested = parse_gpu_layers_override(args)
        except ValueError:
            return False
        if requested is None and env and _env_fixes_gpu_layers(env):
            raw = str(env.get("LLAMA_ARG_N_GPU_LAYERS", "")).strip().lower()
            if raw == "all":
                return True
            try:
                requested = int(raw)
            except ValueError:
                return False
        if requested is None:
            return not fit_is_effectively_on(args, env)
        n_layers = self.n_layers
        if not n_layers:
            return False
        return requested > n_layers

    @staticmethod
    def _rows_the_child_can_reach(detected_gpus, pinned_ids) -> list:
        """Narrows detected GPUs to the launch pin set, not the inherited mask (already applied); None means no narrowing, not an empty pin."""
        rows = list(detected_gpus or ())
        if pinned_ids is None:
            return rows
        visible = set(pinned_ids)
        return [row for row in rows if row[0] in visible]

    def _shared_heap_budget(
        self,
        gpus: Iterable[tuple],
        shared_gpu_ids: Collection[int],
        model_bytes: int,
        argv: list[str],
        env: Optional[Mapping[str, str]] = None,
    ) -> tuple[int, int]:
        """Largest shared iGPU pool only, when a pin names it or unpinned with no discrete card; selected discrete cards reduce its bytes."""
        rows = [(row[0], max(0, row[1])) for row in gpus]
        pinned = _extra_args_main_device(argv)
        if pinned is None and env:
            pinned = env.get("LLAMA_ARG_DEVICE")
        if pinned is None:
            reachable = {idx for idx, _free in rows}
            # Unpinned, llama.cpp adds integrated GPUs only when it finds no discrete one.
            if any(idx not in shared_gpu_ids for idx in reachable):
                reachable -= set(shared_gpu_ids)
        else:
            # Match the ggml registry names emitted by _vulkan_pin_args.
            names = {device.strip().lower() for device in str(pinned).split(",")}
            reachable = {idx for idx, _free in rows if f"vulkan{idx}" in names}
        pool = 0
        if (
            shared_gpu_ids
            and self._argv_offloads_every_layer(argv, env)
            # Tensor-split positions cannot be mapped reliably to probe indices.
            and not _extra_args_set_any_flag(argv, _TENSOR_SPLIT_FLAGS)
            and not str((env or {}).get("LLAMA_ARG_TENSOR_SPLIT") or "").strip()
            # With multiple devices, split-mode none does not identify the recipient.
            and not (len(reachable) > 1 and _split_mode_confines_to_one_device(argv, env))
        ):
            budgets = []
            for idx, free in rows:
                if idx not in shared_gpu_ids or idx not in reachable:
                    continue
                backed = self._igpu_backed_usable_mib(free)
                if backed < free:
                    logger.info(
                        f"Vulkan device VK{idx} offers {free}MiB to placement; "
                        f"host admission credits {backed}MiB"
                    )
                budgets.append(backed)
            pool = max(budgets, default = 0)
        on_cards = sum(free for idx, free in rows if idx not in shared_gpu_ids and idx in reachable)
        return pool, model_bytes - on_cards * 1024 * 1024

    def _launch_host_shortfall_message(
        self,
        cmd: Iterable[str],
        detected_gpus: Iterable[tuple],
        env: Optional[Mapping[str, str]] = None,
        *,
        child_has_no_gpu: bool = False,
        avail_mib: Optional[int] = None,
        shared_gpu_ids: Iterable[int] = (),
        honor_opt_out: bool = True,
        integrated_gpu_ids: Iterable[int] = (),
    ) -> Optional[str]:
        """Advisory shortfall warning, never blocks; UNSLOTH_ALLOW_HOST_OFFLOAD=1 silences only the message, never the pageable-load override."""
        argv = [str(a) for a in cmd or ()]
        if not argv:
            return None
        model_path = _extra_args_device(argv, self._ARGV_MODEL)
        if not model_path:
            return None
        if honor_opt_out and self._host_offload_warning_opted_out():
            logger.info("UNSLOTH_ALLOW_HOST_OFFLOAD set: skipping the host-RAM preflight.")
            return None
        # rpc places layers on remote devices this cannot size, in either spelling
        _env = os.environ if env is None else env
        if (_extra_args_device(argv, self._ARGV_RPC) or "").strip() or str(
            _env.get("LLAMA_ARG_RPC", "") or ""
        ).strip():
            return None
        try:
            model_bytes = self._get_gguf_size_bytes(model_path)
        except Exception:
            return None
        gpus = [] if child_has_no_gpu else list(detected_gpus or ())
        # _get_gpu_memory returns [] on a failed probe, which looks like a GPU-less host.
        if not model_bytes or (not gpus and not child_has_no_gpu):
            return None
        shared = set(shared_gpu_ids or ())
        # Same lazy-read discount as the fit, or this rewrite undoes its pinned verdict.
        try:
            model_bytes = max(
                1,
                model_bytes
                - self._lazy_read_host_bytes(
                    model_path,
                    caps = self.probe_server_capabilities(argv[0]),
                    extra_args = argv,
                    env = _env,
                    auto_resolves_off = self._lazy_auto_resolves_off(
                        gpu_indices = [row[0] for row in gpus] if gpus else None,
                        detected_gpus = gpus,
                        shared_gpu_ids = shared,
                        is_vulkan_backend = bool(shared) or self._is_vulkan_backend(argv[0]),
                        probe_integrated_cuda = False,
                        extra_args = argv,
                        env = _env,
                        device_list = False,
                        integrated_gpu_ids = integrated_gpu_ids,
                    ),
                ),
            )
        except Exception as e:  # noqa: BLE001 -- unverified discount: price the whole file
            logger.debug("Lazy-read discount skipped in the host preflight: %s", e)
        free_vram_mib = sum(max(0, row[1]) for row in gpus if row[0] not in shared)
        heap_free_mib, heap_bytes = self._shared_heap_budget(gpus, shared, model_bytes, argv, _env)
        offload_bytes = model_bytes - free_vram_mib * 1024 * 1024
        # Skip card-resident loads so a cgroup budget never applies to a nonpositive need.
        if 0 < offload_bytes and heap_bytes <= heap_free_mib * 1024 * 1024:
            # A finite cgroup still limits host-backed GPU allocations.
            cgroup_mib = self._cgroup_available_memory_mib()
            if cgroup_mib is None:
                return None
            return self._apu_ram_shortfall_message(heap_bytes, cgroup_mib)
        return self._host_offload_shortfall_message(
            offload_bytes,
            self._available_system_memory_mib() if avail_mib is None else avail_mib,
        )

    @staticmethod
    def _apu_ram_shortfall_message(
        model_size_bytes: int,
        avail_mib: Optional[int],
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
        *,
        part: str = "APU",
    ) -> Optional[str]:
        """Weights-only RAM shortfall on unified-memory parts; KV not counted; None if avail unknown; advisory, never a refusal."""
        if avail_mib is None:
            return None
        need_mib = model_size_bytes / (1024 * 1024)
        if need_mib <= avail_mib - headroom_mib:
            return None
        free_hint = " (on WSL, raise the memory limit in .wslconfig)" if part == "APU" else ""
        return (
            f"This model needs about {need_mib / 1024:.0f} GB but only about "
            f"{avail_mib / 1024:.0f} GB of memory is available. On a unified-memory "
            f"{part} the weights load into system RAM, so the OS may stop the load. "
            "Loading anyway. If it does not complete, use a smaller or more "
            f"quantized GGUF, or free memory{free_hint}."
        )

    @staticmethod
    def _igpu_dedicated_memory_bytes(
        gpu_indices = None, *, ordinals_are_vulkan = False
    ) -> Optional[int]:
        """Dedicated iGPU bytes: Windows registry first (cheap), then the ROCm pool; None rather
        than guess."""
        # Every listed adapter counts, readable or not: the count IS the attribution test.
        answers: list[Optional[dict]] = []
        try:
            from utils.hardware.hardware import (
                _AMD_PCI_VENDOR_ID,
                _INTEL_PCI_VENDOR_ID,
                _windows_amd_adapter_records_by_luid,
            )
            for vendor_id in (_AMD_PCI_VENDOR_ID, _INTEL_PCI_VENDOR_ID):
                answers.append(
                    _windows_amd_adapter_records_by_luid(vendor_id, distinguish_failure = True)
                )
        except Exception:
            answers = []
        if any(answer is not None for answer in answers):
            # An unreadable vendor makes the inventory incomplete, so fail closed.
            if any(answer is None for answer in answers):
                return None
            adapters = sum(len(answer) for answer in answers)
            # AMD only: on Intel UMA the DirectX value is a small dedicated block, not a carve-out.
            amd_sizes = [
                int(record["dedicated_memory_bytes"])
                for record in (answers[0] or {}).values()
                if record.get("dedicated_memory_bytes")
            ]
            if adapters == 1 and len(amd_sizes) == 1 and amd_sizes[0] > 0:
                return amd_sizes[0]
            if adapters:
                # Two adapters need a LUID join to attribute; staying silent beats advising the wrong GPU.
                return None
        if ordinals_are_vulkan:
            # No Linux reading for Vulkan: gpu_indices are Vulkan ordinals, not HIP ids, and probing
            # would create a HIP context (~800 MiB) in this process.
            return None
        pool_mib = LlamaCppBackend._rocm_selected_pool_mib(gpu_indices)
        return int(pool_mib) * 1024 * 1024 if pool_mib and pool_mib > 0 else None

    @staticmethod
    def _igpu_carveout_ladder_gb(cap_gb: float) -> list[int]:
        """Ascending carve-out sizes up to cap_gb, in firmware-menu steps (powers of two and halves)."""
        # A non-finite cap would hang the loop below; reject it first.
        if not isinstance(cap_gb, (int, float)) or not math.isfinite(cap_gb):
            return []
        rungs: set[int] = set()
        # From 1 GB: an APU on its automatic setting reports a few hundred MB.
        step = 1
        while step <= cap_gb:
            rungs.add(step)
            if step * 1.5 <= cap_gb:
                rungs.add(int(step * 1.5))
            step *= 2
        return sorted(rungs)

    @staticmethod
    def _igpu_carveout_advice(
        model_size_bytes: Optional[int],
        carve_out_bytes: Optional[int],
        host_total_bytes: Optional[int],
        *,
        is_igpu: bool,
        min_host_gb: int = _CARVEOUT_ADVICE_MIN_HOST_GB,
        host_fraction: float = _CARVEOUT_ADVICE_HOST_FRACTION,
        nominal_slack_gb: float = _CARVEOUT_NOMINAL_SLACK_GB,
    ) -> Optional[dict]:
        """Advice to raise an iGPU dedicated allocation when weights exceed it; silent on discrete GPUs and when no allocation fits; only advises."""
        if not is_igpu:
            return None
        # Strictly positive, not truthy: -1 would yield confident wrong advice.
        if not all(
            isinstance(value, (int, float)) and math.isfinite(value) and value > 0
            for value in (model_size_bytes, carve_out_bytes, host_total_bytes)
        ):
            return None
        if model_size_bytes <= carve_out_bytes:
            return None  # already fits: nothing to advise

        gb = float(1024**3)
        # Windows subtracts the carve-out from reported RAM, so add it back.
        machine_gb = (host_total_bytes + carve_out_bytes) / gb
        need_gb = model_size_bytes / gb
        current_gb = carve_out_bytes / gb

        # Whatever is suggested, the rest of the system still has to run.
        reserve_gb = max(float(min_host_gb), machine_gb * host_fraction)
        cap_gb = machine_gb - reserve_gb
        if need_gb > cap_gb:
            # No allocation this machine can offer holds the weights, so any advice would be unactionable.
            return None

        suggested = next(
            (rung for rung in LlamaCppBackend._igpu_carveout_ladder_gb(cap_gb) if rung >= need_gb),
            None,
        )
        # Not `<= current_gb`: the current rung sits just above the reading. See _CARVEOUT_NOMINAL_SLACK_GB.
        if suggested is None or suggested <= current_gb + nominal_slack_gb:
            return None

        return {
            "current_gb": round(current_gb, 1),
            "needed_gb": round(need_gb, 1),
            "suggested_gb": int(suggested),
            "machine_gb": round(machine_gb, 1),
            "host_left_gb": round(machine_gb - suggested, 1),
        }

    def _record_carveout_advice(
        self,
        gpu_indices,
        need_bytes,
        *,
        is_vulkan_backend = False,
        shared_gpu_ids = None,
        detected_gpus = None,
        target_unknown = False,
        forced_cpu = False,
    ) -> None:
        """Sets _last_carveout_advice; never raises, runs the cheapest test first; declines if target unknown or load is forced to CPU."""
        self._last_carveout_advice = None
        try:
            if not need_bytes or target_unknown or forced_cpu:
                return
            # Gated here: on Vulkan gpu_indices are Vulkan ordinals, which the ROCm gate would misread
            # as HIP ids. Also cheap, so dGPU-only Vulkan launches return early.
            if is_vulkan_backend and not self._offload_target_shares_system_memory(
                is_vulkan_backend = True,
                shared_gpu_ids = shared_gpu_ids,
                detected_gpus = detected_gpus,
                gpu_indices = gpu_indices,
            ):
                return
            carve_out = self._igpu_dedicated_memory_bytes(
                gpu_indices, ordinals_are_vulkan = is_vulkan_backend
            )
            if not carve_out or need_bytes <= carve_out:
                return  # fits, or nothing to compare it against
            total_mib = self._total_system_memory_mib()
            advice = self._igpu_carveout_advice(
                need_bytes,
                carve_out,
                int(total_mib) * 1024 * 1024 if total_mib else None,
                is_igpu = True,
            )
            if advice is None:
                return
            # Probe only after a confirmed shortfall. AMD only (CUDA would create a context per device),
            # and not on Vulkan, which was classified above.
            if not is_vulkan_backend and not self._amd_apu_wants_unified_memory(gpu_indices):
                return
            # Asked last, so the common path never pays a database round trip.
            from utils.igpu_carveout_notice_settings import notice_already_dismissed

            if notice_already_dismissed(advice.get("current_gb")):
                return
            advice["message"] = self._igpu_carveout_advice_message(advice)
            self._last_carveout_advice = advice
            logger.info(
                "Integrated GPU has %.0f GB dedicated but this model needs about "
                "%.0f GB; suggesting %d GB.",
                advice["current_gb"],
                advice["needed_gb"],
                advice["suggested_gb"],
            )
        except Exception:
            logger.debug("Carve-out advice declined", exc_info = True)
            self._last_carveout_advice = None

    @property
    def last_carveout_advice(self) -> Optional[dict]:
        """Advice from the most recent load, or None. Read by the route."""
        return getattr(self, "_last_carveout_advice", None)

    @staticmethod
    def _fmt_gb(value: float) -> str:
        """Whole numbers above 10 GB, one decimal below, so small allocations do not print as 0 GB."""
        if value < 10:
            return f"{value:.1f}".rstrip("0").rstrip(".")
        return f"{value:.0f}"

    @staticmethod
    def _igpu_carveout_advice_message(advice: dict) -> str:
        """Two short sentences, since a longer toast covers the controls under it; names no vendor
        or menu."""
        fmt = LlamaCppBackend._fmt_gb
        return (
            f"Weights need about {fmt(advice['needed_gb'])} GB but only "
            f"{fmt(advice['current_gb'])} GB is allocated to the integrated GPU, so the rest "
            f"runs from slower shared memory. Raising it to {advice['suggested_gb']} GB in "
            "your firmware or GPU control panel leaves about "
            f"{fmt(advice['host_left_gb'])} GB for the system."
        )

    @staticmethod
    def _host_offload_shortfall_message(
        offload_bytes: int,
        avail_mib: Optional[int],
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
    ) -> Optional[str]:
        """Discrete-GPU spill warning vs free VRAM, no margin; None if avail unknown or nothing spills; advisory, never a refusal."""
        if offload_bytes <= 0 or avail_mib is None:
            return None
        need_mib = offload_bytes / (1024 * 1024)
        if need_mib <= avail_mib - headroom_mib:
            return None
        # need up, usable down, so the printed pair cannot round into a tie
        need_gb = math.ceil(need_mib / 1024)
        usable_gb = math.floor(max(0, avail_mib - headroom_mib) / 1024)
        return (
            f"About {need_gb} GB of this model does not fit in GPU memory and would run "
            f"from system RAM. Only about {avail_mib / 1024:.0f} GB is available and "
            f"{headroom_mib / 1024:.0f} GB of that is kept free for the rest of the "
            f"system, leaving about {usable_gb} GB usable. The weights are memory-mapped, "
            "so the machine pages them in from disk as it runs. Loading anyway: expect "
            "slow generation, and slower still on a hard disk than on an SSD. A smaller "
            "or more quantized GGUF, or more free memory, would run faster."
        )

    @staticmethod
    def _host_offload_warning_opted_out() -> bool:
        """UNSLOTH_ALLOW_HOST_OFFLOAD (deprecated) may only silence the warning, never change the child."""
        return os.environ.get("UNSLOTH_ALLOW_HOST_OFFLOAD", "").strip().lower() in (
            "1",
            "true",
            "yes",
        )

    def _page_an_oversized_unmapped_load(
        self, cmd: Iterable[str], env: Optional[dict], oversized
    ) -> tuple[list, Optional[str]]:
        """Returns (cmd, note); rewrites an oversized non-pageable load to mmap so it finishes; judges effective env state, not argv; never blocks."""
        original = cmd if isinstance(cmd, list) else list(cmd or ())
        _mlock_now, _reserves_ram_now = resolve_effective_memory_state(original, env)
        if not _reserves_ram_now:
            return original, None
        try:
            if not (oversized() if callable(oversized) else oversized):
                return original, None
        except Exception:
            # Advisory pricing: an unreadable host or GGUF leaves the launch alone.
            logger.debug("Could not price the load for a pageable override.", exc_info = True)
            return original, None
        paged, overridden = force_pageable_load(original, env)
        if not overridden:
            return original, None
        logger.warning(
            "Overriding the unmapped load mode (%s) for an oversized model: it would "
            "allocate the whole model in host RAM instead of paging it in.",
            ", ".join(overridden),
        )
        return paged, _PAGEABLE_OVERRIDE_NOTE

    @property
    def last_load_warning(self) -> Optional[str]:
        """Advisory notice from the most recent load, or None. Read by the route."""
        notices = (self._variant_fallback_warning, self._last_load_warning)
        return " ".join(notice for notice in notices if notice) or None

    def _begin_load_warnings(self) -> None:
        """Clears the old notice only once a load commits to replacing the server; a rejected try
        keeps it."""
        self._last_load_warning = None
        self.hub_access_warning = None
        # The advice describes the dying child's placement, not its replacement.
        self._last_carveout_advice = None

    def _record_load_warning(self, message: Optional[str]) -> None:
        """Logs and keeps the notice for the route; never raises, as these replace refusals; first notice wins, since it priced the whole pool."""
        if not message:
            return
        logger.warning(message)
        if self._last_load_warning is None:
            self._last_load_warning = message

    def _amend_load_warning(self, note: Optional[str]) -> None:
        """Appends the late pageable-load override to the recorded notice; a suppressed load has none to amend and keeps only the log."""
        if note and self._last_load_warning:
            self._last_load_warning += note

    def _reprice_after_dropping_pinned_projector(
        self,
        *,
        apu_msg: Optional[str],
        host_msg: Optional[str],
        model_size: Optional[int],
        pinned_bytes: int,
        avail_mib: Optional[int],
        part: str = "APU",
    ) -> None:
        """Re-prices the APU RAM notice after a retry drops the CPU-pinned projector; the override stays."""
        if not apu_msg or pinned_bytes <= 0 or model_size is None or avail_mib is None:
            return
        current = self._last_load_warning
        if not current or not current.startswith(apu_msg):
            return
        # Carry over the pageable-override note so a reprice cannot reword it.
        suffix = current[len(apu_msg) :]
        # Use the preflight avail_mib: the healthy child now holds the weights, so a fresh reading
        # would charge model_size twice.
        repriced = self._apu_ram_shortfall_message(model_size, avail_mib, part = part)
        if repriced:
            self._last_load_warning = repriced + suffix
        elif host_msg:
            # The discrete guard never charged the projector, so its verdict stands.
            self._last_load_warning = host_msg + suffix
        elif suffix.strip():
            self._last_load_warning = _PAGEABLE_OVERRIDE_TEXT_ONLY_NOTICE
        else:
            self._last_load_warning = None
        logger.info(
            "Text-only fallback dropped the CPU-pinned vision projector (%.0f MiB); "
            "re-priced the host memory advisory against the weights alone.",
            pinned_bytes / (1024 * 1024),
        )

    def _reprice_after_cpu_only_fallback(
        self,
        *,
        host_msg: Optional[str],
        cpu_cmd: Iterable[str],
        env: Optional[Mapping[str, str]],
        avail_mib: Optional[int],
        pageable_note: Optional[str] = None,
    ) -> None:
        """Reprices host RAM notice for CPU-only Vulkan replay; call only once the replay is healthy, never when chosen; clears carve-out advice."""
        self._last_carveout_advice = None
        repriced = self._launch_host_shortfall_message(
            cpu_cmd,
            (),
            env,
            child_has_no_gpu = True,
            avail_mib = avail_mib,
        )
        note = pageable_note or ""
        current = self._last_load_warning
        if current is None:
            # The model fit in VRAM, so nothing warned; on CPU it fits nowhere but disk.
            self._record_load_warning((repriced + note) if repriced else None)
            return
        if not host_msg or not current.startswith(host_msg) or not repriced:
            # Nothing to re-price, but the override still changed the child: say so.
            self._amend_load_warning(pageable_note)
            return
        self._last_load_warning = repriced + current[len(host_msg) :] + note
        logger.info(
            "Re-priced the host memory advisory for the CPU replay: it runs with no "
            "GPU, so the whole model is charged to system RAM."
        )

    def _unified_pool_gpu_ids(
        self, rows, *, gpu_indices, shared_gpu_ids, is_vulkan_backend: bool
    ) -> set:
        """Ids in ``rows`` whose free VRAM is the host RAM pool (Vulkan iGPUs, ROCm APUs, CUDA
        SoCs)."""
        rows = list(rows or ())
        shared = set(shared_gpu_ids or ())
        pinned = list(gpu_indices) if gpu_indices is not None else [row[0] for row in rows]
        if rows and not is_vulkan_backend and self._amd_apu_wants_unified_memory(pinned):
            # Per device: a discrete card beside an APU still has its own pool.
            shared |= {row[0] for row in rows if self._amd_apu_wants_unified_memory([row[0]])}
        # Integrated CUDA SoCs (Jetson, DGX Spark) too. Cache only: _get_gpu_memory filled it.
        _integrated = LlamaCppBackend._INTEGRATED_CUDA_IDS.get(
            LlamaCppBackend._integrated_cuda_mask_key(), ()
        )
        shared |= {row[0] for row in rows if row[0] in _integrated}
        return shared

    def _fits_without_paging(
        self,
        footprint_bytes: Optional[int],
        detected_gpus: Iterable[tuple],
        *,
        gpu_indices: Optional[Iterable[int]] = None,
        shared_gpu_ids: Iterable[int] = (),
        host_only_bytes: int = 0,
        vram_margin_mib: Union[float, Mapping[int, float]] = 0.0,
        avail_mib: Optional[int] = None,
        headroom_mib: int = _HOST_RAM_HEADROOM_MIB,
    ) -> Optional[bool]:
        """Whether the whole load fits in VRAM, or in VRAM plus host RAM (else False;
        None when it cannot be told). This is the ``--load-mode`` question: mmap earns
        its keep by demand-paging a footprint the machine cannot hold, so a load that
        fits never needs it.

        ``footprint_bytes`` is weights + KV + scratch, not weights alone. The refusal
        guards next door deliberately price weights only, because understating there
        can only fail to refuse a load that would have worked. Here the bias runs the
        other way: understating would claim a fit that isn't one and hand the load a
        loader that cannot page, so every term the launch knows about is charged.

        Shared iGPU memory is not added on top of host RAM (it IS host RAM), so those
        devices are dropped from the VRAM term and their weights are carried by the RAM
        term, the same split ``_launch_host_shortfall_message`` uses. ``gpu_indices``
        narrows the VRAM term to the devices this launch actually pins; unpinned cards
        hold nothing for it. Unreadable RAM answers None rather than guessing, which
        keeps the caller on llama.cpp's own default.

        ``host_only_bytes`` is the part of ``footprint_bytes`` that CANNOT be satisfied
        out of VRAM however much is free -- a drafter the launch pinned to the CPU is
        the case -- so it is subtracted from what VRAM may cover and added to the RAM
        requirement instead. Pooling it would let free VRAM pay for bytes that can only
        ever be allocated in host RAM.

        ``vram_margin_mib`` is the free VRAM llama.cpp's own fitter keeps PER DEVICE
        and will not allocate into (``--fit-target``, default 1024 MiB, "target margin
        per device for --fit"; common/arg.cpp, common/common.h). Under ``--fit on``
        the child spills weights to host RAM rather than dip into it, so those bytes
        are not credit this launch may spend. Zero on the proved path, which emits
        ``-ngl -1 --fit off`` and runs no fitter at all. A mapping gives each card the
        margin of Studio's per-device list, keyed by physical GPU id.
        """
        if not footprint_bytes or footprint_bytes <= 0:
            return None
        host_only = max(0, int(host_only_bytes or 0))
        shared = set(shared_gpu_ids or ())
        pinned = None if gpu_indices is None else {int(idx) for idx in gpu_indices}
        free_vram_mib = sum(
            max(0, row[1] - _margin_mib_for(vram_margin_mib, row[0]))
            for row in (detected_gpus or ())
            if row[0] not in shared and (pinned is None or row[0] in pinned)
        )
        free_vram_bytes = int(free_vram_mib * 1024 * 1024)
        # VRAM covers the GPU-eligible part; its spill plus the host-only bytes hit RAM.
        spill = max(0, max(0, footprint_bytes - host_only) - free_vram_bytes) + host_only
        if spill <= 0:
            return True
        avail = self._available_system_memory_mib() if avail_mib is None else avail_mib
        if avail is None:
            return None
        # Same headroom as the host-offload refusal: a full RAM is the paging case to avoid.
        return spill <= max(0, avail - headroom_mib) * 1024 * 1024

    def _fit_derived_load_mode(
        self,
        *,
        model_size: Optional[int],
        mmproj_pinned_bytes: int = 0,
        kv_cache_bytes: int = 0,
        kv_sized: bool = True,
        mtp_bytes: int = 0,
        mtp_unsized: bool = False,
        host_only_bytes: int = 0,
        compute_buffer_flat: int = 0,
        compute_buffer_ctx: int = 0,
        pipeline_overhead_bytes: int = 0,
        soft_overhead: int = 0,
        gpus: Optional[Iterable[tuple]] = None,
        gpu_indices: Optional[Iterable[int]] = None,
        shared_gpu_ids: Iterable[int] = (),
        fit_margin_mib: Union[float, Mapping[int, float]] = 0.0,
        is_vulkan_backend: bool = False,
        avail_mib: Optional[int] = None,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        lazy_read_bytes: int = 0,
        announce: bool = True,
    ) -> Optional[str]:
        """``"none"`` when the fit proves the load needs no demand paging, else None.

        mmap exists to demand-page a footprint the machine cannot hold, and llama.cpp
        builds its async pinned-buffer upload path ONLY when mmap is off
        (llama-model-loader.cpp, ``upload_backend``), so a load that fits wants
        ``none``: same residency, faster load, no model-sized mapping left behind.
        Anything that does not fit, or that cannot be priced, keeps llama.cpp's own
        ``auto``, where the mapping is what stops an over-committed load from being
        killed outright.

        The footprint is charged WHOLE, weights and KV and scratch, because
        understating it would claim a fit that is not there and hand the load a loader
        that cannot page. Every term that cannot be read abstains for the same reason:
        unreadable weights, an unsized KV (the estimator returns 0 without the dims,
        and a 0 KV term on a long-context load is exactly the missing term) and a
        drafter engaged but unsized, which the placement itself covers with a flat
        cushion rather than a number.

        ``host_only_bytes`` is the slice of that footprint no amount of free VRAM can
        hold (a drafter pinned to the CPU with ``-ngld 0``): counted in the total, but
        charged to host RAM alone, because free VRAM cannot pay for an allocation the
        child only ever makes on the host. ``kv_cache_bytes`` joins it under an
        effective ``--no-kv-offload``, which puts the WHOLE cache on the host
        whatever the layer placement says (llama-kv-cache.cpp defaults each layer's
        buffer type to the CPU one and upgrades it only inside ``if (offload)``).

        Apple Silicon abstains outright. Metal is the one backend where
        ``buffer_from_host_ptr`` IS supported, so mmap wraps the weights in a Metal
        buffer in place, zero copy and file backed; ``none`` would allocate the same
        bytes anonymously, and an evictable 30 GB mapping on a 32 GB machine is the
        difference between working and being jetsammed. The host figure is the wrong
        ceiling there anyway (see ``_apple_metal_memory_budget_bytes``), so a fit read
        off ``MemAvailable`` would not be one worth acting on.

        ``extra_args`` is the pass-through block as the child will really get it (the
        caller strips what a ``gpu_ids`` pin owns first), and it voids the VRAM term.
        Those tokens are appended AFTER this launch's own placement flags and
        llama.cpp is last-wins (common/arg.cpp assigns ``n_gpu_layers`` / ``devices``
        on every occurrence), so a hand-typed ``-ngl``, a ``--device`` naming no GPU
        or a CPU tensor override runs weights out of host RAM that the planner just
        credited to a card. The placement this priced is then not the one that
        launches, and ``none`` on a footprint host RAM cannot hold is an OOM where
        ``auto`` would have demand-paged. Dropping the VRAM credit rather than
        abstaining keeps the answer for the case that is still provable: a load host
        RAM holds WHOLE is safe wherever those flags end up putting it. The same
        predicates the Model Memory host-residency gate uses, so the two cannot drift.

        ``env`` is the environment the child will really get (``os.environ`` when the
        caller passes none). Every one of those pass-through overrides has an env twin
        llama.cpp reads BEFORE argv, so classifying on the tokens alone would miss an
        inherited ``LLAMA_ARG_DEVICE=none``, which no automatic launch clears (only an
        explicit ``gpu_ids`` pin does). A ``--device`` naming FEWER devices than this
        fit credits voids the VRAM term for the same reason a CPU-valued one does: the
        cards it leaves out hold nothing for this launch. ``LLAMA_ARG_N_GPU_LAYERS``
        is the sharpest of them: the fitting path emits no ``-ngl`` for it to lose
        to, so an inherited count is the whole layer policy (see
        ``_env_fixes_gpu_layers``).

        ``fit_margin_mib`` is what llama.cpp's fitter keeps free per device when the
        fitter really runs, i.e. VRAM this load may not spend; see
        ``_fits_without_paging``. The caller answers that from the EFFECTIVE flags
        rather than from its own plan: the extras land after this launch's ``--fit``
        and llama.cpp is last-wins, ``-ngl -1`` is llama.cpp's own default so an
        enabled fitter is free to lower it (common/fit.cpp aborts only on a count the
        user really set), and a pass-through ``--fit-target`` raises the margin above
        anything ``_ctx_integrity_flags`` emitted.

        ``lazy_read_bytes`` (``_lazy_read_host_bytes``) leaves the footprint: it stays
        mmap'd and pages through the headroom. ``announce`` False silences a what-if call.
        """
        from utils.hardware import is_apple_silicon

        if not model_size or not kv_sized or mtp_unsized or is_apple_silicon():
            return None
        # Pass-through adapters are resident weights model_size never carried; unreadable abstains.
        sidecar_bytes = _sidecar_adapter_bytes(extra_args)
        if sidecar_bytes is None:
            return None
        rows = list(gpus or ())
        source_env = os.environ if env is None else env
        _credited = len(list(gpu_indices)) if gpu_indices is not None else len(rows)
        if _pass_through_overrides_placement(
            extra_args,
            source_env,
            _credited,
            is_vulkan_backend = is_vulkan_backend,
            gpu_indices = gpu_indices,
        ):
            if announce:
                logger.info(
                    "Load mode: pass-through arguments override the placement this fit "
                    "priced; charging the whole load to host RAM."
                )
            rows, gpu_indices = [], None
        footprint = (
            model_size
            # Pass-through LoRA / control vectors, allocated alongside the base tensors.
            + max(0, sidecar_bytes)
            # A CPU-pinned projector left model_size but is still resident; this sum is a footprint, not a VRAM budget.
            + max(0, mmproj_pinned_bytes)
            + max(0, kv_cache_bytes)
            # Carries the drafter's own weights and KV.
            + max(0, mtp_bytes)
            # Resident, but only ever in host RAM; charged to the RAM term alone below.
            + max(0, host_only_bytes)
            + max(0, compute_buffer_flat)
            + max(0, compute_buffer_ctx)
            # A layer split adds fixed context and scratch on every extra device. 0 on a single GPU.
            + max(0, pipeline_overhead_bytes)
            + max(0, soft_overhead)
        )
        _lazy_discount = max(0, int(lazy_read_bytes or 0))
        if _lazy_discount:
            footprint = max(1, footprint - _lazy_discount)
        # Unified memory is ONE pool: an APU's free VRAM IS the host RAM the spill
        # comes out of, so adding both fits a model twice into memory that holds it
        # once. shared_gpu_ids already names Vulkan iGPUs; the ROCm APUs it cannot see
        # are added here. Both end up priced against host RAM alone.
        shared = self._unified_pool_gpu_ids(
            rows,
            gpu_indices = gpu_indices,
            shared_gpu_ids = shared_gpu_ids,
            is_vulkan_backend = is_vulkan_backend,
        )
        # --no-kv-offload puts the WHOLE cache in host RAM whatever the layer placement
        # says (llama-kv-cache.cpp upgrades a layer's buffer type only inside
        # `if (offload)`), so free VRAM may not pay for it. Resolved off the same
        # effective views the placement overrides above use.
        _kv_on_host = not _kv_offload_from_args(extra_args, env = source_env)
        if self._fits_without_paging(
            footprint,
            rows,
            gpu_indices = gpu_indices,
            shared_gpu_ids = shared,
            # A CPU-pinned projector is counted once in the footprint above, and charged to the RAM term so surplus VRAM cannot cover it.
            host_only_bytes = (
                max(0, host_only_bytes)
                + max(0, mmproj_pinned_bytes)
                # Same split as the pinned projector: counted once above, charged to RAM.
                + (max(0, kv_cache_bytes) if _kv_on_host else 0)
            ),
            vram_margin_mib = fit_margin_mib,
            avail_mib = avail_mib,
        ):
            if announce:
                logger.info(
                    "Load mode: the whole load (%.1f GB) fits without paging, using "
                    "--load-mode %s%s.",
                    footprint / (1024**3),
                    self._FIT_LOAD_MODE,
                    (
                        f" ({_lazy_discount / (1024**3):.1f} GB of lazily read tables stay "
                        "on disk)"
                        if _lazy_discount
                        else ""
                    ),
                )
            return self._FIT_LOAD_MODE
        return None

    # Chosen by measurement: dio was fastest cold on large models; kept at none because that was
    # requested. dio has no pre-enum spelling, so old builds would emit nothing.
    _FIT_LOAD_MODE = "none"

    METAL_CTX_OVERCOMMIT_ENV = "UNSLOTH_ALLOW_METAL_CTX_OVERCOMMIT"

    @staticmethod
    def _metal_context_overcommit_message(
        requested_ctx: int,
        max_available_ctx: int,
        cache_type_kv: Optional[str] = None,
        *,
        nothing_fits: bool = False,
        wired_limit: bool = False,
    ) -> Optional[str]:
        """Refuses, not clamps, an explicit Metal context over the iogpu wired limit, which panics the machine; UNSLOTH_ALLOW_METAL_CTX_OVERCOMMIT=1 abstains."""
        if requested_ctx <= 0:
            return None
        # nothing_fits has no positive ceiling: even the smallest context did not fit.
        if not nothing_fits:
            if max_available_ctx <= 0:
                return None
            if requested_ctx <= max_available_ctx:
                return None
        # the user's own opt-out, so read the real environment, not the curated child env
        if os.environ.get(LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV, "").strip().lower() in (
            "1",
            "true",
            "yes",
        ):
            logger.info(
                "%s set: launching at a context unified memory is not sized for.",
                LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV,
            )
            return None
        kv_hint = (
            " Setting the KV cache to q8_0 roughly halves what the context costs."
            if (cache_type_kv or "f16").strip().lower() in ("f16", "fp16", "")
            else ""
        )
        auto_advice = "" if wired_limit else "leave it on Auto, "
        if nothing_fits:
            return (
                "No context fits in this Mac's unified memory with this model. The weights "
                "fit, but they leave too little for even the smallest context, so a load at "
                f"any length would over-commit. The GPU and the rest of the system share one "
                f"pool here, so there is nothing to offload to, and the load would bring the "
                f"machine down instead of reporting an error. Use a smaller or more quantized "
                f"GGUF, or free memory."
                f"{kv_hint} Set "
                f"{LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV}=1 to load it anyway."
            )
        return (
            f"A context of {requested_ctx:,} tokens does not fit in this Mac's unified "
            f"memory with this model. The largest that fits is {max_available_ctx:,} "
            "tokens. The GPU and the rest of the system share one pool here, so there is "
            "nothing to offload to, and the load would bring the machine down instead of "
            f"reporting an error. Lower the context to {max_available_ctx:,} or less, "
            f"{auto_advice}or use a more quantized GGUF."
            f"{kv_hint} Set "
            f"{LlamaCppBackend.METAL_CTX_OVERCOMMIT_ENV}=1 to load it anyway."
        )

    @staticmethod
    def _metal_context_pressure_message(
        requested_ctx: int, need_mib: float, free_budget_mib: float
    ) -> str:
        # need up, free down, so the printed pair cannot round into a tie
        need_gb = math.ceil(need_mib / 1024)
        free_gb = math.floor(max(0.0, free_budget_mib) / 1024)
        return (
            f"A context of {requested_ctx:,} tokens needs about {need_gb} GB of unified "
            f"memory, more than the {free_gb} GB Unsloth budgets from the memory free right "
            "now. It fits under the GPU's wired memory limit, so it is loading anyway, but "
            "macOS may have to compress or swap other apps to make room and generation may "
            "slow down. Lower the context or free memory to avoid that."
        )

    @staticmethod
    def _cuda_context_overcommit_notice(
        requested_ctx: int,
        max_available_ctx: int,
        cache_type_kv: Optional[str] = None,
        *,
        quantised_ctx_fits: bool = False,
    ) -> Optional[str]:
        """Discrete GPUs only warn on an oversize hand-set context: layers offload to CPU instead."""
        if requested_ctx <= 0 or max_available_ctx <= 0:
            return None
        if requested_ctx <= max_available_ctx:
            return None
        kv_hint = ""
        if quantised_ctx_fits and (cache_type_kv or "f16").strip().lower() in (
            "f16",
            "fp16",
            "",
        ):
            kv_hint = " Setting the KV cache to q8_0 makes this context fit without shortening it."
        # Fires only after a --fit on or spill-plan hand-off: planned CPU offload on every OS.
        cause = (
            "The GPU cannot hold it, so layers will be moved to the CPU and generation "
            f"will be slower. Lower the context to {max_available_ctx:,} or less, or "
            "leave it on Auto."
        )
        return (
            f"A context of {requested_ctx:,} tokens does not fit in this GPU's memory with "
            f"this model. The largest that fits is {max_available_ctx:,} tokens. "
            f"{cause}{kv_hint}"
        )

    @staticmethod
    def _unmeasured_context_notice(
        requested_ctx: int, cache_type_kv: Optional[str] = None
    ) -> Optional[str]:
        """Advisory for a hand-set context with no KV estimate behind it: the short-context
        fallbacks used to cut a 262,144-token request to 4,096 and publish it (#9653). Not a
        refusal, which on a guess blocks live loads."""
        if requested_ctx <= 0:
            return None
        kv_hint = (
            " Setting the KV cache to q8_0 roughly halves what the context costs."
            if (cache_type_kv or "f16").strip().lower() in ("f16", "fp16", "")
            else ""
        )
        return (
            f"This model's GGUF does not carry the attention dimensions needed to size "
            f"the KV cache, so the {requested_ctx:,}-token context was launched as "
            f"requested without being checked against available memory. The reported "
            f"maximum context is that request, not a measured ceiling. If the load fails "
            f"or the machine runs short of memory, lower the context or leave it on "
            f"Auto.{kv_hint}"
        )

    # Skip the wait when the last kill is older than this; the driver has already reclaimed it.
    _VRAM_SETTLE_WINDOW_S: float = 15.0

    @staticmethod
    def _wait_for_vram_settle(
        max_wait: float = 2.0,
        interval: float = 0.25,
        tolerance_mib: int = 256,
        since_kill: float = 0.0,
    ) -> None:
        """Polls until VRAM settles after a kill; skips on cold start, stale kill, CPU-only, probe errors, GPU-set change; max_wait caps a wedged nvidia-smi."""
        now = time.monotonic()
        if since_kill <= 0.0:
            return
        if now - since_kill > LlamaCppBackend._VRAM_SETTLE_WINDOW_S:
            return
        deadline = now + max_wait

        def _probe_or_none():
            if time.monotonic() >= deadline:
                return None
            try:
                from utils.hardware import gpu_query

                # Consecutive samples are compared: a cached one would read as settled.
                with gpu_query.fresh_reads():
                    return LlamaCppBackend._get_gpu_free_memory()
            except Exception:
                return None

        prev = _probe_or_none()
        if prev is None or not prev:
            return
        while time.monotonic() < deadline:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return
            # Clip the nap so a near-zero ``max_wait`` is respected.
            time.sleep(min(interval, remaining))
            curr = _probe_or_none()
            if curr is None or not curr or len(curr) != len(prev):
                return
            prev_map = dict(prev)
            stable = True
            for idx, free in curr:
                if idx not in prev_map:
                    stable = False
                    break
                prev_free = prev_map[idx]
                # Adaptive: 2% of the larger sample dominates the 256 MiB floor.
                per_gpu_tol = max(tolerance_mib, int(max(free, prev_free) * 0.02))
                if abs(free - prev_free) >= per_gpu_tol:
                    stable = False
                    break
            if stable:
                return
            prev = curr

    # Free-VRAM fraction at which Unsloth pins the GPU instead of deferring to --fit on.
    # Guards fragmentation and per-device context; 0.90 sent 91-94% fits to CPU offload.
    _GPU_PIN_VRAM_FRACTION = 0.97

    # Fallback per-device tensor-mode compute buffer, used only when GGUF dims are unavailable.
    _TENSOR_PARALLEL_BUFFER_RESERVE_MIB = 5120

    # Fixed per-device overhead (context + scratch) on each extra GPU of a layer split, ~0.9 GB, independent of --parallel; reserved so a split cannot OOM at load.
    _PIPELINE_PER_DEVICE_OVERHEAD_MIB = 1024

    # V cache types that run without flash attention. A quantized V aborts without FA (K does not),
    # so the FA-off fallback resets only V to f16.
    _NON_QUANTIZED_KV_TYPES = frozenset({"f16", "bf16", "f32"})

    # Manual mode owns these; they must not leak from the parent env. Draft placement stays separate.
    _MANUAL_PLACEMENT_ENV_VARS = (
        "LLAMA_ARG_CPU_MOE",
        "LLAMA_ARG_N_CPU_MOE",
        "LLAMA_ARG_N_GPU_LAYERS",
        "LLAMA_ARG_TENSOR_SPLIT",
        "LLAMA_ARG_FIT",
        "LLAMA_ARG_FIT_TARGET",
        "LLAMA_ARG_FIT_CTX",
    )

    # Eligibility must reject every inherited placement value replay removes.
    _CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS = (
        *_MANUAL_PLACEMENT_ENV_VARS,
        "LLAMA_ARG_DEVICE",
        "LLAMA_ARG_MAIN_GPU",
        "LLAMA_ARG_SPLIT_MODE",
        "LLAMA_ARG_OVERRIDE_TENSOR",
    )

    # Keys (binary, mtime, model, kv types) that aborted on --split-mode tensor this process; KV type matters since iq4_nl asserts where q4_0 runs.
    _tensor_split_abort_keys: set[tuple[str, int, str, tuple[str, str]]] = set()

    # Binaries that refused quantized KV under tensor split, keyed per binary not model; consulted only when an axis is quantized, since f16 still splits.
    _tensor_quant_kv_unsupported_binaries: set[tuple[str, int]] = set()

    # Warned binary dirs: the env is rebuilt per launch and probe, so warn once per binary.
    _missing_cuda_runtime_warned: set[str] = set()

    @classmethod
    def _binary_key(cls, binary: Optional[str]) -> Optional[tuple[str, int]]:
        """(path, mtime_ns); ns mtime re-probes a same-second binary swap."""
        if not binary:
            return None
        try:
            mtime = Path(binary).stat().st_mtime_ns
        except OSError:
            mtime = 0
        return (binary, mtime)

    @classmethod
    def _record_tensor_quant_kv_unsupported(cls, binary: Optional[str]) -> None:
        """Remember a binary that cannot run a quantized KV cache in tensor mode."""
        key = cls._binary_key(binary)
        if key is not None:
            cls._tensor_quant_kv_unsupported_binaries.add(key)

    @classmethod
    def _tensor_quant_kv_unsupported_binary(
        cls,
        binary: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> bool:
        """True if this binary already refused a quantized KV cache in tensor mode
        AND this launch asks for one. A non-quantized pair is unaffected."""
        if not any(_kv_bytes_per_elem(t) < _kv_bytes_per_elem("f16") for t in cache_types):
            return False
        key = cls._binary_key(binary)
        return key is not None and key in cls._tensor_quant_kv_unsupported_binaries

    @classmethod
    def _tensor_split_cache_key(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> Optional[tuple[str, int, str, tuple[str, str]]]:
        """(path, mtime_ns, model, (type_k, type_v)) key; ns mtime re-probes a
        same-second binary swap. ``cache_types`` defaults to llama.cpp's own
        default pair, which is what a caller that sets no type gets."""
        if not binary or not model:
            return None
        try:
            mtime = Path(binary).stat().st_mtime_ns
        except OSError:
            mtime = 0
        k, v = cache_types
        return (binary, mtime, model, (k.strip().lower(), v.strip().lower()))

    @classmethod
    def _tensor_split_aborts(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> bool:
        """True if this (binary, model, KV types) aborted on --split-mode tensor
        this session. A different cache type is a different question, so it is
        tried rather than assumed broken."""
        key = cls._tensor_split_cache_key(binary, model, cache_types)
        return key is not None and key in cls._tensor_split_abort_keys

    @classmethod
    def _record_tensor_split_abort(
        cls,
        binary: Optional[str],
        model: Optional[str],
        cache_types: tuple[str, str] = ("f16", "f16"),
    ) -> None:
        """Remember a (binary, model, KV types) that aborts on --split-mode tensor."""
        key = cls._tensor_split_cache_key(binary, model, cache_types)
        if key is not None:
            cls._tensor_split_abort_keys.add(key)

    # Keyed like the tensor latch: binary mtime drops entries after an update.
    _sched_reserve_abort_keys: set[tuple] = set()

    @classmethod
    def _sched_reserve_aborts(cls, binary: Optional[str], model: Optional[str]) -> bool:
        key = cls._tensor_split_cache_key(binary, model)
        return key is not None and key in cls._sched_reserve_abort_keys

    @classmethod
    def _record_sched_reserve_abort(cls, binary: Optional[str], model: Optional[str]) -> None:
        key = cls._tensor_split_cache_key(binary, model)
        if key is not None:
            cls._sched_reserve_abort_keys.add(key)

    @classmethod
    def _forget_sched_reserve_abort(cls, binary: Optional[str], model: Optional[str]) -> None:
        key = cls._tensor_split_cache_key(binary, model)
        if key is not None:
            cls._sched_reserve_abort_keys.discard(key)

    @staticmethod
    def _windows_pip_nvidia_dll_dirs(prefix: str) -> list[str]:
        """Returns DLL dirs from pip CUDA wheels under Lib/site-packages for llama-server.exe; walks with Path.iterdir since [ ] in usernames break glob."""
        site_packages = Path(prefix) / "Lib" / "site-packages"
        out: list[str] = []
        seen: set[str] = set()

        def _add(path: Path) -> None:
            if not path.is_dir():
                return
            key = os.path.normcase(os.path.abspath(str(path)))
            if key in seen:
                return
            seen.add(key)
            out.append(str(path))

        nvidia_root = site_packages / "nvidia"
        if nvidia_root.is_dir():
            for pkg_dir in nvidia_root.iterdir():
                if not pkg_dir.is_dir():
                    continue
                # Arch-specific subdirs first so cudart64_X.dll wins over an empty sibling bin.
                for sub in (
                    pkg_dir / "bin" / "x86_64",
                    pkg_dir / "bin" / "x64",
                    pkg_dir / "bin",
                    pkg_dir / "Library" / "bin" / "x86_64",
                    pkg_dir / "Library" / "bin" / "x64",
                    pkg_dir / "Library" / "bin",
                ):
                    _add(sub)
        _add(site_packages / "torch" / "lib")
        return out

    @classmethod
    def _warn_missing_windows_cuda_runtime(cls, binary_dir: str, path_dirs: list[str]) -> None:
        """Warns when a CUDA llama-server has no cudart/cublas DLLs to load; never raises or changes
        launch."""
        try:
            if binary_dir in cls._missing_cuda_runtime_warned:
                return
            # Official prebuilts are single-backend, so the ggml CUDA lib beside llama-server IS the build.
            ggml_cuda = os.path.join(binary_dir, "ggml-cuda.dll")
            if not os.path.isfile(ggml_cuda):
                return
            for directory in path_dirs:
                try:
                    names = os.listdir(directory)
                except OSError:
                    continue
                if any(name.lower().startswith("cudart64_") for name in names):
                    return
            cls._missing_cuda_runtime_warned.add(binary_dir)
            logger.warning(
                "llama.cpp is the CUDA build (%s) but no cudart64_*.dll was found on its "
                "DLL search path. The CUDA ggml backend will not load and llama-server "
                "will report no devices. This is what a CPU-only PyTorch in the managed "
                "environment looks like; repair the installation to restore GPU support.",
                ggml_cuda,
            )
        except Exception as e:
            logger.debug(f"CUDA runtime DLL diagnostic failed: {e}")

    @staticmethod
    def _build_windows_path_dirs(binary_dir: str, prefix: str, cuda_path: str) -> list[str]:
        """Ordered PATH entries prepended so llama-server.exe resolves cudart /
        cublas DLLs: binary_dir, pip nvidia wheels, CUDA_PATH/bin, .../bin/x64.
        Extracted so test_windows_gpu_detection_mock tests the real logic. #5106."""
        path_dirs = [binary_dir]
        path_dirs.extend(LlamaCppBackend._windows_pip_nvidia_dll_dirs(prefix))
        if cuda_path:
            cuda_bin = os.path.join(cuda_path, "bin")
            if os.path.isdir(cuda_bin):
                path_dirs.append(cuda_bin)
            cuda_bin_x64 = os.path.join(cuda_path, "bin", "x64")
            if os.path.isdir(cuda_bin_x64):
                path_dirs.append(cuda_bin_x64)
        return path_dirs

    @staticmethod
    def _llama_server_env_for_binary(
        binary: str,
        *,
        use_system_rocm: bool = True,
        verify_system_rocm: bool = True,
    ) -> dict[str, str]:
        """Build a subprocess env that lets llama-server resolve native libs.

        ``use_system_rocm=False`` skips the native-Linux system ROCm prepend;
        ``verify_system_rocm=False`` keeps it without the GPU visibility probe.
        WSL's librocdxg prepend is independent and is not gated by this flag.
        """
        env = child_env_without_native_path_secret()
        # Every child inherits this env, so strip an off-meaning GGML_CUDA_P2P here (ggml reads presence).
        LlamaCppBackend._sanitize_p2p_env(env)
        # _llama_lib_dir resolves the llama-server symlink to the real build/bin.
        binary_dir = str(_llama_lib_dir(binary))

        if sys.platform == "win32":
            # Ordering: see _build_windows_path_dirs. #5106.
            path_dirs = LlamaCppBackend._build_windows_path_dirs(
                binary_dir,
                sys.prefix,
                os.environ.get("CUDA_PATH", ""),
            )
            existing_path = env.get("PATH", "")
            env["PATH"] = ";".join(path_dirs) + ";" + existing_path
            # Warn against the full search path: a hand-installed toolkit may put cudart on PATH.
            _full_search_path = path_dirs + [d for d in existing_path.split(";") if d]
            LlamaCppBackend._warn_missing_windows_cuda_runtime(binary_dir, _full_search_path)

            # The ROCm prebuilt bundles rocblas.dll but not its Tensile kernel files.
            _hip_path = os.environ.get("HIP_PATH", os.environ.get("ROCM_PATH", ""))
            if _hip_path:
                _rocblas_lib = os.path.join(_hip_path, "bin", "rocblas", "library")
                if os.path.isdir(_rocblas_lib):
                    env.setdefault("ROCBLAS_TENSILE_LIBPATH", _rocblas_lib)
        elif sys.platform == "darwin":
            # dyld ignores LD_LIBRARY_PATH. A healthy prebuilt resolves via @loader_path; one with wrong
            # install names dies in dyld without this.
            _dyld = _loader_path_var()
            env[_dyld] = _prepend_loader_dir(env.get(_dyld, ""), binary_dir)
        else:
            # Linux: LD_LIBRARY_PATH for libs next to the binary plus the CUDA runtime libs.
            import platform

            lib_dirs = []
            # WSL: system HIP before the bundle's (which segfaults on /dev/dxg).
            lib_dirs.extend(_wsl_system_rocm_lib_dirs())
            if lib_dirs:
                env.setdefault("HSA_ENABLE_DXG_DETECTION", "1")
            # Native Linux AMD: system ROCm libs before the bundle's HIP runtime,
            # which can be incompatible with the host amdkfd driver (#7233). On other
            # hosts the system copy is the mismatched one and hides the GPU (#14906).
            if use_system_rocm and not LlamaCppBackend._prefers_bundle_only_rocm(binary):
                _system_rocm = _native_linux_system_rocm_lib_dirs(binary_dir)
                if _system_rocm and not (
                    verify_system_rocm
                    and LlamaCppBackend._system_rocm_hides_gpu(binary, _system_rocm)
                ):
                    lib_dirs.extend(_system_rocm)
            lib_dirs.append(binary_dir)
            _arch = platform.machine()  # x86_64, aarch64, etc.

            # Pip-installed nvidia libs: the prebuilt links libcudart.so.13 from here, not /usr/local/cuda.
            import glob as _glob

            # glob.escape: a prefix with [brackets] is otherwise read as a pattern.
            _site = os.path.join(_glob.escape(sys.prefix), "lib", "python*", "site-packages")
            _pip_dirs = []
            for _nv_pattern in [
                os.path.join(_site, "nvidia", _sub, "lib") for _sub in ("cu*", "cudnn", "nvjitlink")
            ] + [os.path.join(_site, "torch", "lib")]:
                for _nv_dir in _glob.glob(_nv_pattern):
                    if os.path.isdir(_nv_dir):
                        _pip_dirs.append(_nv_dir)

            _system_dirs = []
            for cuda_lib in [
                "/usr/local/cuda/lib64",
                f"/usr/local/cuda/targets/{_arch}-linux/lib",
                # Fallback CUDA compat paths for a CUDA 12 build, since default /usr/local/cuda is CUDA 13+.
                "/usr/local/cuda-12/lib64",
                "/usr/local/cuda-12.8/lib64",
                f"/usr/local/cuda-12/targets/{_arch}-linux/lib",
                f"/usr/local/cuda-12.8/targets/{_arch}-linux/lib",
            ]:
                if os.path.isdir(cuda_lib):
                    _system_dirs.append(cuda_lib)
            from utils.tegra import TEGRA_LIB_DIR, is_tegra

            if is_tegra():
                # Jetson: JetPack's CUDA first; the generic pip builds load but crash on unified memory (#4862).
                _tegra = [TEGRA_LIB_DIR] if os.path.isdir(TEGRA_LIB_DIR) else []
                lib_dirs.extend(_tegra + _system_dirs + _pip_dirs)
            else:
                lib_dirs.extend(_pip_dirs + _system_dirs)

            # Vendored dirs go last: rescue only, never displace a runtime already found.
            from utils.llama_cpp_freshness import read_install_marker
            from utils.prebuilt.runtime_libs import vendored_cuda_runtime_dirs

            marker_binary = str(_resolve_llama_binary(binary))
            vendored_cuda_dirs = vendored_cuda_runtime_dirs(read_install_marker(marker_binary))
            existing_ld = env.get("LD_LIBRARY_PATH", "")
            env["LD_LIBRARY_PATH"] = ":".join(
                path for path in [*lib_dirs, existing_ld, *vendored_cuda_dirs] if path
            )

        return env

    @classmethod
    def _clear_manual_placement_env(cls, env: dict[str, str]) -> None:
        """Remove inherited main-model placement owned by Manual mode."""
        for name in cls._MANUAL_PLACEMENT_ENV_VARS:
            env.pop(name, None)

    @classmethod
    def _clear_device_placement_env(cls, env: dict[str, str]) -> None:
        """Remove inherited device placement owned by an explicit ``gpu_ids``."""
        for name in ("LLAMA_ARG_DEVICE", "LLAMA_ARG_MAIN_GPU"):
            env.pop(name, None)

    @classmethod
    def _clear_split_placement_env(cls, env: dict[str, str]) -> None:
        """Env twins of --split-mode/--tensor-split must go, or an inherited ratio lands on the
        wrong card."""
        for name in ("LLAMA_ARG_SPLIT_MODE", "LLAMA_ARG_TENSOR_SPLIT"):
            env.pop(name, None)

    @classmethod
    def _reconcile_split_mode_env(cls, env: dict[str, str], *, tensor_parallel: bool) -> None:
        """Clear inherited LLAMA_ARG_* split env that contradicts Studio's split, so previews price
        what the child runs."""
        if not tensor_parallel:
            # Layer split: clear a non-layer inherited split mode (and any paired
            # tensor-split) so the child can't override the layer plan.
            _inherited_sm = (env.get("LLAMA_ARG_SPLIT_MODE") or "").strip().lower()
            if _inherited_sm and _inherited_sm != "layer":
                env.pop("LLAMA_ARG_SPLIT_MODE", None)
                env.pop("LLAMA_ARG_TENSOR_SPLIT", None)
        else:
            # Unsloth owns the tensor split: it emits --tensor-split when it picks an
            # uneven one (CLI wins) and nothing when an even split is safe. Clear any
            # inherited LLAMA_ARG_TENSOR_SPLIT so the even case can't be overridden by a
            # stale env (the layer branch above clears it too).
            env.pop("LLAMA_ARG_TENSOR_SPLIT", None)

    @staticmethod
    def _discrete_tier(
        gpus: list,
        integrated: frozenset,
        shared: frozenset = frozenset(),
    ) -> Optional[list]:
        """The discrete-first tier (#7624): unshared discrete cards in ``gpus`` order, or
        None when ``gpus`` holds no integrated GPU (no tier; the base pick applies). Shared
        dGPUs are left to the full-pool pick, whose shared preference spans every card."""
        if not integrated or all(g[0] not in integrated for g in gpus):
            return None
        return [g for g in gpus if g[0] not in integrated and g[0] not in shared]

    @staticmethod
    def _select_gpus(
        model_size_bytes: int,
        gpus: list[tuple[int, int]],
        usable_fraction: Optional[float] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        per_device_overhead_bytes: int = 0,
        min_gpus: int = 1,
        shared: frozenset = frozenset(),
        integrated: frozenset = frozenset(),
        discrete_size_bytes: Optional[int] = None,
        prefer_discrete: bool = True,
        discount_prefixes: frozenset = frozenset(),
        shared_gpu_ids: Optional[Iterable[int]] = None,
    ) -> tuple[Optional[list[int]], bool]:
        """Pick GPU(s) for a model from estimated VRAM and free memory.

        ``shared``: GPUs another loaded model runs on. A model that fits one card alone
        takes a card outside it when one fits, so two models don't share compute.

        ``integrated``: unified-memory GPUs; discrete GPUs win when they alone hold the model.
        ``discrete_size_bytes`` prices that discrete attempt (default ``model_size_bytes``):
        bytes that live in host RAM only on unified memory are not charged to a dGPU.
        ``prefer_discrete`` False (an explicit device pick) skips the discrete tier but still
        prices a dGPU-only candidate at ``discrete_size_bytes`` when it keeps the leading
        ordinals, so a user's device ordinals still name the same cards.

        ``min_gpus`` (default 1, capped at ``len(gpus)``) keeps a downgraded
        tensor/multi-GPU request spread instead of collapsing to one card.

        ``model_size_bytes`` should include weights and estimated KV cache.
        ``usable_fraction`` (default ``_GPU_PIN_VRAM_FRACTION``) provides
        headroom for compute buffers, CUDA context, and other runtime
        overhead; callers lower it when MTP reserves VRAM for a draft model.
        ``total_by_idx`` (index -> total MiB) makes the headroom an ABSOLUTE
        ``(1 - fraction) * total`` per GPU instead of a fraction of free.
        ``per_device_overhead_bytes`` is the fixed layer-split cost per GPU beyond
        the first; a k-GPU pin must hold ``model + (k-1) * overhead`` or it can OOM
        a device after -ngl -1 (no --fit fallback). Single-GPU adds none.
        ``shared_gpu_ids`` (iGPUs whose "VRAM" is host RAM) rank after every discrete card.

        Returns (gpu_indices, use_fit):
          - ([1], False)       fits on 1 GPU at the headroom threshold
          - ([1, 2], False)    needs 2 GPUs
          - (None, True)       too large, let --fit handle it
        """
        if not gpus:
            return None, True

        min_gpus = max(1, min(min_gpus, len(gpus)))
        # Discrete first (#7624): an APU's "free" is system RAM. Falls through if it can't meet min_gpus.
        discrete = LlamaCppBackend._discrete_tier(gpus, integrated, shared)
        if prefer_discrete and discrete is not None and min_gpus <= len(discrete):
            picked, use_fit = LlamaCppBackend._select_gpus(
                model_size_bytes if discrete_size_bytes is None else discrete_size_bytes,
                discrete,
                usable_fraction = usable_fraction,
                total_by_idx = total_by_idx,
                per_device_overhead_bytes = per_device_overhead_bytes,
                min_gpus = min_gpus,
            )
            if not use_fit and picked and len(picked) >= min_gpus:
                return picked, False
        model_size_mib = model_size_bytes / (1024 * 1024)
        if usable_fraction is None:
            usable_fraction = _active_vram_fraction()
        overhead_mib = per_device_overhead_bytes / (1024 * 1024)
        # Host-only bytes (checkpoints, a CPU-pinned projector) never land on a dGPU-only subset.
        # Only on a subset the caller vetted (``discount_prefixes``): one that keeps the user's
        # device ordinals naming the same cards. Anything else pays the full price.
        _discount = (
            not prefer_discrete
            and integrated
            and discount_prefixes
            and discrete_size_bytes is not None
            and discrete_size_bytes < model_size_bytes
        )

        def _size_mib(ids: list) -> float:
            if _discount and integrated.isdisjoint(ids) and frozenset(ids) in discount_prefixes:
                return discrete_size_bytes / (1024 * 1024)
            return model_size_mib

        # Usable budget: free minus reserve when total is known, else free*frac.
        _sysmem_fallback = LlamaCppBackend._sysmem_fallback_risk()

        def _usable(idx: int, free_mib: int) -> float:
            t = total_by_idx.get(idx, 0) if total_by_idx else 0
            usable = _vram_usable_mib(
                free_mib, t, usable_fraction, sysmem_fallback = _sysmem_fallback
            )
            return max(0.0, usable) if t > 0 else usable

        # Rank by usable budget (free - reserve), not raw free: a more-used large
        # card can have less usable room than a less-used small one.
        _shared = set(shared_gpu_ids or ())
        ranked = sorted(
            gpus,
            key = lambda g: (
                g[0] not in _shared and _usable(g[0], g[1]) > overhead_mib,
                _usable(g[0], g[1]),
            ),
            reverse = True,
        )

        # Cap a downgraded multi-GPU request to the usable count so it skips near-full cards.
        usable_count = sum(1 for idx, free_mib in ranked if _usable(idx, free_mib) > overhead_mib)
        min_gpus = max(1, min(min_gpus, usable_count or 1))

        # A busy card too small alone must not pull a card that fits into a shared pin.
        if (
            min_gpus <= 1
            and ranked[0][0] in shared
            and _usable(ranked[0][0], ranked[0][1]) < model_size_mib
        ):
            for idx, free_mib in ranked:
                if idx not in shared and _usable(idx, free_mib) >= model_size_mib:
                    return [idx], False

        # Try 1 GPU at the usable-VRAM threshold (only when one device is allowed).
        if min_gpus <= 1 and _usable(ranked[0][0], ranked[0][1]) >= _size_mib([ranked[0][0]]):
            for idx, free_mib in ranked:
                if idx not in shared and _usable(idx, free_mib) >= _size_mib([idx]):
                    return [idx], False
            return [ranked[0][0]], False
        # A discounted dGPU can hold its lighter size alone even when the top-ranked APU cannot
        # hold the full one: try each card at its own price before spreading.
        if min_gpus <= 1 and _discount:
            fits = [idx for idx, free_mib in ranked if _usable(idx, free_mib) >= _size_mib([idx])]
            if fits:
                return [next((idx for idx in fits if idx not in shared), fits[0])], False

        # Try N GPUs most-free first; each past the first adds per-device overhead; a fit needs at least min_gpus devices.
        cumulative = 0.0
        selected = []
        for idx, free_mib in ranked:
            selected.append(idx)
            cumulative += _usable(idx, free_mib)
            if (
                len(selected) >= min_gpus
                and cumulative >= _size_mib(selected) + (len(selected) - 1) * overhead_mib
            ):
                return sorted(selected), False

        # Too large even for all GPUs; let --fit handle it
        logger.debug(
            "Model does not fit in available GPU memory, falling back to --fit",
            model_size_mib = round(model_size_mib, 2),
            ranked_gpus = ranked,
        )
        return None, True

    @staticmethod
    def _select_gpus_split_aware(
        model_size_bytes: int,
        gpus: list[tuple[int, int]],
        usable_fraction: Optional[float] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        per_device_overhead_bytes: int = 0,
        min_gpus: int = 1,
        split_extra_bytes: int = 0,
        shared: frozenset = frozenset(),
        integrated: frozenset = frozenset(),
        discrete_size_bytes: Optional[int] = None,
        prefer_discrete: bool = True,
        discount_prefixes: frozenset = frozenset(),
        shared_gpu_ids: Optional[Iterable[int]] = None,
    ) -> tuple[Optional[list[int]], bool]:
        """``_select_gpus``, re-checked at the multi-device context-compute rate.

        The device count comes out of the footprint, so the first pass must price the
        compute buffer at the single-device rate -- but a layer split replicates a BIGGER
        one per card (see ``_CTX_COMPUTE_SPLIT_MULT``). ``split_extra_bytes`` is that
        per-device step (0 when llama.cpp declines pipeline parallelism): charge it and
        re-select once the count is known to be > 1, exact in one retry since the step is
        count-independent. The bigger overhead can cut ``_select_gpus``'s usable-card
        count to one, and a lone card is not a split, so a retry landing below two
        devices is re-priced without the delta. Still no fit returns (None, True) ->
        --fit on, i.e. CPU offload rather than a pin that OOMs at launch.

        ``integrated``: as in ``_select_gpus``, but the discrete tier must pass the whole
        split-aware check (priced at ``discrete_size_bytes`` when given); otherwise the
        full pool is priced exactly as without it. ``prefer_discrete`` False skips the tier
        and hands the accounting to ``_select_gpus``."""
        # Only an explicit pick passes the accounting on; the tier above already ran otherwise.
        _acct = (
            {
                "integrated": integrated,
                "prefer_discrete": False,
                "discount_prefixes": discount_prefixes,
            }
            if not prefer_discrete and integrated and discrete_size_bytes is not None
            else {}
        )
        discrete = (
            LlamaCppBackend._discrete_tier(gpus, integrated, shared) if prefer_discrete else None
        )
        if discrete is not None:
            if max(1, min(min_gpus, len(gpus))) <= len(discrete):
                picked, needs_fit = LlamaCppBackend._select_gpus_split_aware(
                    model_size_bytes if discrete_size_bytes is None else discrete_size_bytes,
                    discrete,
                    usable_fraction = usable_fraction,
                    total_by_idx = total_by_idx,
                    per_device_overhead_bytes = per_device_overhead_bytes,
                    min_gpus = min_gpus,
                    split_extra_bytes = split_extra_bytes,
                )
                if not needs_fit and picked and len(picked) >= max(1, min(min_gpus, len(gpus))):
                    return picked, False
        gpu_indices, use_fit = LlamaCppBackend._select_gpus(
            model_size_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes,
            min_gpus = min_gpus,
            shared = shared,
            shared_gpu_ids = shared_gpu_ids,
            **({**_acct, "discrete_size_bytes": discrete_size_bytes} if _acct else {}),
        )
        if use_fit or split_extra_bytes <= 0 or not gpu_indices or len(gpu_indices) < 2:
            return gpu_indices, use_fit
        retry_indices, retry_fit = LlamaCppBackend._select_gpus(
            model_size_bytes + split_extra_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes + split_extra_bytes,
            min_gpus = min_gpus,
            shared_gpu_ids = shared_gpu_ids,
            **(
                {**_acct, "discrete_size_bytes": discrete_size_bytes + split_extra_bytes}
                if _acct
                else {}
            ),
        )
        if not retry_fit and retry_indices and len(retry_indices) >= 2:
            return retry_indices, retry_fit
        single, single_fit = LlamaCppBackend._select_gpus(
            model_size_bytes,
            gpus,
            usable_fraction = usable_fraction,
            total_by_idx = total_by_idx,
            per_device_overhead_bytes = per_device_overhead_bytes,
            min_gpus = 1,
            shared = shared,
            shared_gpu_ids = shared_gpu_ids,
            **({**_acct, "discrete_size_bytes": discrete_size_bytes} if _acct else {}),
        )
        if not single_fit and single is not None and len(single) == 1:
            return single, False
        return retry_indices, retry_fit

    @staticmethod
    def _every_gpu_holds_reserve(usable_mib: Iterable[float], reserve_bytes: int) -> bool:
        """Each card must hold its own reserve: a pooled sum lets a roomy card mask a small card's OOM."""
        reserve_mib = reserve_bytes / (1024 * 1024)
        values = list(usable_mib)
        return bool(values) and all(usable >= reserve_mib for usable in values)

    @staticmethod
    def _cap_ctx_to_per_device_reserve(
        ctx: int,
        usable_mib: Iterable[float],
        reserve_bytes_fn: Callable[[int], int],
        min_ctx: int = 8192,
    ) -> int:
        """Largest context in [min_ctx, ctx] whose reserve fits every selected GPU; bisects since reserves are monotone; returns 0 if min_ctx fails."""
        values = list(usable_mib)
        if not values or ctx < min_ctx:
            return 0
        smallest = min(values)
        lo, hi, best = min_ctx, ctx, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if reserve_bytes_fn(mid) / (1024 * 1024) <= smallest:
                best, lo = mid, mid + 1
            else:
                hi = mid - 1
        best = (best // 256) * 256  # same alignment _fit_context_to_vram uses
        return best if best >= min_ctx else 0

    # ── KV cache VRAM estimation ─────────────────────────────────────

    def _can_estimate_kv(self) -> bool:
        """True if we have enough GGUF metadata to estimate KV cache size."""
        if self._n_layers is None:
            return False
        # MLA: kv_lora_rank suffices (K-only cache).
        if self._kv_lora_rank is not None:
            return True
        # New-style: need explicit key AND value dimensions.
        if self._kv_key_length is not None and self._kv_value_length is not None:
            return True
        # Legacy: need embedding_length + a head count (scalar or per-layer).
        return self._embedding_length is not None and (
            self._n_kv_heads is not None
            or self._n_heads is not None
            or self._n_kv_heads_by_layer is not None
        )

    def _kv_layer_weights(
        self,
        n_ctx: int,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
        cache_type_kv: Optional[str] = None,
    ) -> "list[int]":
        """Only ratios, scaled to the byte total, so cell geometry must match it (incl --swa-full); [] off the SWA path; shared-cache layers weight 0."""
        pattern = self._sliding_window_pattern
        n_layers = self._n_layers or 0
        if not pattern or n_layers <= 0:
            return []
        # Mirror _estimate_kv_cache_bytes' branch order.
        if self._kv_lora_rank is not None:
            return []
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            return []
        swa = self._sliding_window or 0
        if swa <= 0:
            return []
        n_kv = self._n_kv_heads or self._n_heads or 1
        key_len = self._kv_key_length or 0
        val_len = self._kv_value_length or 0
        if not key_len or not val_len:
            return []
        key_len_swa = self._kv_key_length_swa or key_len
        val_len_swa = self._kv_value_length_swa or val_len
        # Same floor as _estimate_kv_cache_bytes: a bad GGUF cannot zero the vector.
        n_layers_kv = max(1, n_layers - (self._shared_kv_layers or 0))
        # Same cell layout the byte total was computed with.
        slots, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        full_cells = max(1, cells_per_stream * streams)
        if swa_full:
            swa_cells = full_cells
        else:
            ubatch = max(0, int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch))
            swa_limit = int(swa) * (slots if kv_unified else 1) + ubatch
            swa_cells = max(1, _pad_kv_cells(min(cells_per_stream, swa_limit)) * streams)
        # With FA off llama.cpp pads every layer's V to the model-wide max, as the byte total does,
        # and floors V at f16; carry both K and V so the vector matches the total.
        bpe_k = _kv_bytes_per_elem(cache_type_kv)
        bpe_v = bpe_k if flash_attn else max(bpe_k, _kv_bytes_per_elem("f16"))
        padded_v_width = None if flash_attn else self._max_kv_value_width(val_len, val_len_swa)
        weights: list[int] = []
        for layer_idx in range(n_layers):
            if layer_idx >= n_layers_kv:
                weights.append(0)
                continue
            layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
            is_swa = layer_idx < len(pattern) and bool(pattern[layer_idx])
            key_bytes = layer_n_kv * (key_len_swa if is_swa else key_len) * bpe_k
            value_bytes = (
                layer_n_kv * (val_len_swa if is_swa else val_len)
                if padded_v_width is None
                else padded_v_width
            ) * bpe_v
            width = key_bytes + value_bytes
            weights.append(int(width * (swa_cells if is_swa else full_cells)))
        return weights if any(weights) else []

    def _kv_heads_for_layer(self, layer_idx: int, fallback: int) -> int:
        if self._n_kv_heads_by_layer is not None and layer_idx < len(self._n_kv_heads_by_layer):
            return self._n_kv_heads_by_layer[layer_idx]
        return fallback

    def _recurrent_state_bytes(self, n_parallel: int = 1) -> int:
        """VRAM for linear-attention conv and recurrent state (per-layer KDA layout; Hybrid Mamba uses _mamba_recurrent_state_bytes); does not scale with context."""
        heads_by_layer = getattr(self, "_n_kv_heads_by_layer", None)
        n_layers_raw = getattr(self, "_n_layers", None)
        kda_head_dim = getattr(self, "_kda_head_dim", None)
        if not heads_by_layer or not n_layers_raw or not kda_head_dim:
            return 0
        n_recurrent = sum(1 for i in range(self._n_layers) if self._kv_heads_for_layer(i, 1) == 0)
        if n_recurrent == 0:
            return 0
        head_dim, n_head = self._kda_head_dim, self._n_heads or 1
        d_conv = self._ssm_conv_kernel or 4
        n_embd_r = 3 * max(0, d_conv - 1) * n_head * head_dim
        n_embd_s = head_dim * head_dim * n_head
        return int(n_recurrent * (n_embd_r + n_embd_s) * 4 * max(1, n_parallel))

    def _rollback_state_bytes(self, n_parallel: int = 1) -> int:
        """Size one target-context rollback snapshot for either recurrent family."""
        return self._mamba_recurrent_state_bytes(n_parallel) or self._recurrent_state_bytes(
            n_parallel
        )

    def _ctx_checkpoint_bytes(
        self,
        cache_type_kv: Optional[str] = None,
        *,
        swa_full: bool = False,
        flash_attn: bool = True,
    ) -> int:
        """Host bytes of one slot's context checkpoint: the recurrent state, else the SWA window."""
        recurrent = self._rollback_state_bytes(1)
        if recurrent > 0:
            return recurrent

        def kv(checkpoints: int) -> int:
            return self._estimate_kv_cache_bytes(
                1,
                cache_type_kv,
                swa_full = swa_full,
                ctx_checkpoints = checkpoints,
                flash_attn = flash_attn,
            )

        return max(0, kv(1) - kv(0))

    def _bounded_ctx_checkpoints(
        self,
        n_parallel: int,
        server_caps: Mapping[str, object],
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
        *,
        cache_type_kv: Optional[str] = None,
        swa_full: bool = False,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """Return an automatic context-checkpoint cap, or None to preserve the argv."""
        flag = server_caps.get("ctx_checkpoints_flag")
        if not flag:
            return None
        # Extras and LLAMA_ARG_CTX_CHECKPOINTS are the operator's; emitting overrules them.
        if parse_ctx_checkpoints_override(extra_args) is not None:
            return None
        if _env_ctx_checkpoints_override(env) is not None:
            return None
        per_checkpoint = self._ctx_checkpoint_bytes(
            cache_type_kv, swa_full = swa_full, flash_attn = flash_attn
        )
        if per_checkpoint <= 0:
            return None
        total_ram_mib = self._host_memory_capacity_mib()
        # This build's own default: capping against 32 would raise a build that keeps 3.
        upstream_default = ctx_checkpoints_default_for_caps(server_caps)
        bounded = ctx_checkpoints_within_host_budget(
            per_checkpoint,
            n_parallel,
            (total_ram_mib * 1024 * 1024) if total_ram_mib else None,
            upstream_default = upstream_default,
        )
        if bounded >= upstream_default:
            return None
        logger.info(
            "Capping llama-server context checkpoints at %d per slot (this build's default %d): "
            "each one snapshots %.1f MiB of this model's state, so the default "
            "would hold %.1f GiB of host RAM across %d slot(s).",
            bounded,
            upstream_default,
            per_checkpoint / (1024**2),
            upstream_default * per_checkpoint * max(1, n_parallel) / (1024**3),
            max(1, n_parallel),
        )
        return bounded

    def _target_kv_excludes_nextn(self) -> bool:
        """Whether target KV skips MTP blocks: hybrid recurrent yes; other archs only if listed in _TARGET_KV_EXCLUDES_NEXTN_ARCHS; unknown keeps all."""
        if not self._nextn_predict_layers:
            return False
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            return True
        arch = getattr(self, "_architecture", None)
        return bool(arch) and str(arch).strip().lower() in _TARGET_KV_EXCLUDES_NEXTN_ARCHS

    def _ssm_recurrent_layer_count(self, n_layers: int) -> int:
        """SSM layers of a header with no attention interval, by llama.cpp's is_recr rules."""
        arch = getattr(self, "_architecture", None)
        if arch in _SSM_EVERY_LAYER_ARCHS:
            return n_layers
        heads = getattr(self, "_n_kv_heads_by_layer", None)
        if not heads or getattr(self, "_kda_head_dim", None):
            return 0
        ffn = (
            getattr(self, "_feed_forward_length_by_layer", None)
            if arch in _SSM_FFN_FREE_LAYER_ARCHS
            else None
        ) or []
        return sum(
            1
            for i, n_kv in enumerate(heads[:n_layers])
            if n_kv == 0 and not (i < len(ffn) and ffn[i] > 0)
        )

    def _mamba_recurrent_state_bytes(
        self,
        n_parallel: int = 1,
        n_rs_seq: int = 0,
    ) -> int:
        """Under MTP each sequence keeps --spec-draft-n-max rollback states: 1 + n_rs_seq times the base."""
        n_layers_raw = getattr(self, "_n_layers", None)
        d_inner_raw = getattr(self, "_ssm_inner_size", None)
        d_state_raw = getattr(self, "_ssm_state_size", None)
        n_group_raw = getattr(self, "_ssm_group_count", None)
        d_conv_raw = getattr(self, "_ssm_conv_kernel", None)
        fai_raw = getattr(self, "_full_attention_interval", None)
        # Mamba1 (Jamba, Mamba) writes no group count; llama.cpp reads it as 0.
        if not all(
            value is not None
            for value in (
                n_layers_raw,
                d_inner_raw,
                d_state_raw,
                d_conv_raw,
            )
        ) or (fai_raw is not None and n_group_raw is None):
            return 0
        # Exclude embedded MTP blocks: llama.cpp keeps them out of the target's n_layer.
        n_layers = max(
            0,
            int(n_layers_raw or 0) - int(getattr(self, "_nextn_predict_layers", None) or 0),
        )
        if fai_raw is not None:
            fai = int(fai_raw or 0)
            n_attn = -(-n_layers // fai) if fai > 0 else n_layers
            n_recurrent = max(0, n_layers - n_attn)
        else:
            n_recurrent = self._ssm_recurrent_layer_count(n_layers)
        if n_recurrent == 0:
            return 0
        d_inner = int(d_inner_raw or 0)
        d_state = int(d_state_raw or 0)
        n_group = int(n_group_raw or 0)
        d_conv = int(d_conv_raw or 0)
        n_embd_r = max(0, d_conv - 1) * (d_inner + 2 * n_group * d_state)
        n_embd_s = d_state * d_inner
        return int(
            n_recurrent * (n_embd_r + n_embd_s) * 4 * max(1, n_parallel) * max(1, 1 + n_rs_seq)
        )

    def _legacy_head_dim(self) -> int:
        """Head-dim fallback for GGUFs without explicit key/value dims. Reached
        only via the legacy branch of _can_estimate_kv(), so _embedding_length
        is non-None here."""
        return self._embedding_length // self._n_heads if self._n_heads else 128  # type: ignore[operator]

    def _max_kv_value_width(
        self,
        default_len: int,
        swa_len: Optional[int] = None,
    ) -> int:
        """llama.cpp's hparams.n_embd_v_gqa_max() over every model layer."""
        n_layers = self._n_layers or 1
        n_kv = self._n_kv_heads or self._n_heads or 1
        if self._sliding_window_pattern is None:
            max_len = max(default_len, swa_len or default_len)
            return max(
                self._kv_heads_for_layer(layer_idx, n_kv) * max_len for layer_idx in range(n_layers)
            )
        return max(
            self._kv_heads_for_layer(layer_idx, n_kv)
            * (
                (swa_len or default_len)
                if (
                    layer_idx < len(self._sliding_window_pattern)
                    and self._sliding_window_pattern[layer_idx]
                )
                else default_len
            )
            for layer_idx in range(n_layers)
        )

    def _estimate_kv_cache_bytes(
        self,
        n_ctx: int,
        cache_type_kv: Optional[str] = None,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        ctx_checkpoints: int = 0,
        flash_attn: bool = True,
    ) -> int:
        """Estimate KV cache VRAM for a given context length.

        5-path architecture-aware estimation:
          1. MLA      -- compressed KV latent + RoPE, K-only (no separate V)
          2. Hybrid   -- only attention layers need KV (Mamba layers don't)
          3. SWA      -- sliding-window layers use compact or full cache cells
          4. GQA      -- standard full KV with explicit key/value dimensions
          5. Legacy   -- fallback using embed // n_heads

        Server-flag knobs (mirror llama-server's CLI):
          swa_full        -- --swa-full: SWA layers cache full n_ctx (path 3->4).
          n_parallel      -- --parallel slots: controls per-slot stream padding.
          kv_unified      -- --kv-unified: one shared stream vs one per slot.
          n_ubatch        -- --ubatch-size: SWA cache's processing headroom.
          ctx_checkpoints -- --ctx-checkpoints: N snapshots per slot. An SWA
                             model snapshots its window; a hybrid recurrent one
                             snapshots its WHOLE recurrent state (see path 2).
                             They live in host RAM, never VRAM.
          flash_attn      -- False pads variable-width V tensors to the model max.

        Returns 0 if metadata is insufficient.
        """
        if not self._can_estimate_kv() or n_ctx <= 0:
            return 0

        # block_count includes MTP blocks; only _TARGET_KV_EXCLUDES_NEXTN_ARCHS keep them out of the
        # target context (priced in _mtp_draft_kv_bytes). Elsewhere subtracting would under-reserve.
        n_layers = self._n_layers  # type: ignore[assignment]
        if self._target_kv_excludes_nextn():
            n_layers = max(1, n_layers - (self._nextn_predict_layers or 0))
        # Gemma 3n/4 reuse earlier KV in the last shared_kv_layers blocks. Floor at 1.
        shared = self._shared_kv_layers or 0
        n_layers_kv = max(1, n_layers - shared)
        n_kv = self._n_kv_heads or self._n_heads or 1  # type: ignore[assignment]

        # Bytes per element depends on KV cache quantization
        bpe_k = _kv_bytes_per_elem(cache_type_kv)
        # The FA-off retry rewrites a quantized V cache to f16; price that retry.
        bpe_v = bpe_k if flash_attn else max(bpe_k, _kv_bytes_per_elem("f16"))

        slots, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        total_cells = cells_per_stream * streams
        ubatch = max(
            0,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )

        # A hybrid snapshot is the whole recurrent state, not a context-scaled window.
        recurrent_checkpoints = slots * max(0, ctx_checkpoints) * self._rollback_state_bytes(1)

        # Path 1: MLA. One compressed latent per token/layer, no V cache. Default head_count_kv to 1,
        # not n_heads, which would overcount 128x on DeepSeek-V3.
        if self._kv_lora_rank is not None:
            n_kv_mla = self._n_kv_heads or 1
            rope_dim = self._key_length_mla or 64
            key_len = self._kv_key_length or (self._kv_lora_rank + rope_dim)
            # Hybrid MLA (Kimi-K3): linear-attention layers have head_count_kv 0 and no growing cache.
            n_mla_layers = n_layers_kv
            if self._n_kv_heads_by_layer:
                attn = sum(
                    1 for i in range(n_layers_kv) if self._kv_heads_for_layer(i, n_kv_mla) > 0
                )
                n_mla_layers = max(1, attn)
            return (
                int(n_mla_layers * total_cells * n_kv_mla * key_len * bpe_k)
                + self._recurrent_state_bytes(n_parallel)
                + recurrent_checkpoints
            )

        key_len = self._kv_key_length
        val_len = self._kv_value_length

        # Path 2: hybrid Mamba/attention; only 1 in N layers has KV.
        if self._ssm_inner_size is not None and self._full_attention_interval is not None:
            fai = self._full_attention_interval
            n_attn = -(-n_layers // fai) if fai > 0 else n_layers  # ceiling division
            recurrent = self._mamba_recurrent_state_bytes(n_parallel)
            if key_len is not None and val_len is not None:
                v_width = n_kv * val_len if flash_attn else self._max_kv_value_width(val_len)
                return (
                    int(n_attn * total_cells * (n_kv * key_len * bpe_k + v_width * bpe_v))
                    + recurrent
                    + recurrent_checkpoints
                )
            head_dim = self._legacy_head_dim()
            return (
                int(n_attn * total_cells * n_kv * 2 * head_dim * bpe_k)
                + recurrent
                + recurrent_checkpoints
            )

        # Path 3: sliding window. Compact SWA adds one micro-batch and pads to 256 cells; unified mode
        # has one stream, non-unified one per slot; --swa-full expands SWA to full context.
        if (
            self._sliding_window is not None
            and self._sliding_window > 0
            and key_len is not None
            and val_len is not None
        ):
            swa = self._sliding_window
            if swa_full:
                swa_cells_total = total_cells
            else:
                swa_limit = swa * (slots if kv_unified else 1) + ubatch
                swa_cells_per_stream = min(cells_per_stream, swa_limit)
                swa_cells_per_stream = _pad_kv_cells(swa_cells_per_stream)
                swa_cells_total = swa_cells_per_stream * streams
            key_len_swa = self._kv_key_length_swa or key_len
            val_len_swa = self._kv_value_length_swa or val_len
            padded_v_width = None if flash_attn else self._max_kv_value_width(val_len, val_len_swa)
            if self._sliding_window_pattern is not None:
                global_bytes = 0.0
                swa_bytes = 0.0
                checkpoint_extra_per_slot = 0.0
                # Only layers that allocate their own KV; trailing shared layers
                # reuse earlier caches.
                for layer_idx in range(n_layers_kv):
                    layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
                    is_swa = (
                        layer_idx < len(self._sliding_window_pattern)
                        and self._sliding_window_pattern[layer_idx]
                    )
                    layer_key_bytes = layer_n_kv * (key_len_swa if is_swa else key_len) * bpe_k
                    layer_value_bytes = (
                        layer_n_kv * (val_len_swa if is_swa else val_len)
                        if padded_v_width is None
                        else padded_v_width
                    ) * bpe_v
                    layer_kv_bytes = layer_key_bytes + layer_value_bytes
                    if is_swa:
                        swa_bytes += swa_cells_total * layer_kv_bytes
                        if ctx_checkpoints > 0 and not swa_full:
                            checkpoint_extra_per_slot += ctx_checkpoints * swa * layer_kv_bytes
                    else:
                        global_bytes += total_cells * layer_kv_bytes
                return int(global_bytes + swa_bytes + slots * checkpoint_extra_per_slot)
            n_global = max(1, n_layers_kv // 4)
            n_swa = n_layers_kv - n_global
            global_v_width = n_kv * val_len if padded_v_width is None else padded_v_width
            swa_v_width = n_kv * val_len_swa if padded_v_width is None else padded_v_width
            kv_per_token = n_kv * key_len * bpe_k + global_v_width * bpe_v
            kv_per_token_swa = n_kv * key_len_swa * bpe_k + swa_v_width * bpe_v
            global_bytes = n_global * total_cells * kv_per_token
            swa_bytes = n_swa * swa_cells_total * kv_per_token_swa
            checkpoint_extra_per_slot = (
                ctx_checkpoints * n_swa * swa * kv_per_token_swa
                if ctx_checkpoints > 0 and not swa_full
                else 0.0
            )
            return int(global_bytes + swa_bytes + slots * checkpoint_extra_per_slot)

        ssm_state = self._mamba_recurrent_state_bytes(n_parallel) + recurrent_checkpoints

        # Path 4: Standard GQA with explicit key/value dimensions
        if key_len is not None and val_len is not None:
            padded_v_width = None if flash_attn else self._max_kv_value_width(val_len)
            bytes_per_cell = 0.0
            for layer_idx in range(n_layers_kv):
                layer_n_kv = self._kv_heads_for_layer(layer_idx, n_kv)
                v_width = layer_n_kv * val_len if padded_v_width is None else padded_v_width
                bytes_per_cell += layer_n_kv * key_len * bpe_k + v_width * bpe_v
            return int(total_cells * bytes_per_cell) + ssm_state

        # Path 5: Legacy fallback (old GGUFs without explicit dimensions)
        head_dim = self._legacy_head_dim()
        # llama.cpp defaults head_count_kv to head_count, so a pure SSM (head_count 0) has no KV.
        layer_default = self._n_kv_heads if self._n_kv_heads is not None else (self._n_heads or 0)
        heads = [self._kv_heads_for_layer(i, layer_default) for i in range(n_layers_kv)]
        # Without flash attention V is padded to the widest layer, as on Path 4.
        v_heads = sum(heads) if flash_attn else len(heads) * max(heads)
        return int((sum(heads) * bpe_k + v_heads * bpe_v) * head_dim * total_cells) + ssm_state

    def _draft_backend_for(self, drafter_path: str) -> Optional["LlamaCppBackend"]:
        """Lightweight backend with a drafter GGUF's metadata, to size its own KV
        via _estimate_kv_cache_bytes. Cached per path; None if unreadable."""
        cache = getattr(self, "_draft_backend_cache", None)
        if cache is not None and cache[0] == drafter_path:
            return cache[1]
        db: Optional[LlamaCppBackend] = None
        try:
            db = LlamaCppBackend.__new__(LlamaCppBackend)
            for attr in (
                "_context_length",
                "_n_layers",
                "_n_kv_heads",
                "_n_heads",
                "_embedding_length",
                "_kv_key_length",
                "_kv_value_length",
                "_kv_lora_rank",
                "_sliding_window",
                "_sliding_window_pattern",
                "_ssm_inner_size",
                "_ssm_state_size",
                "_ssm_group_count",
                "_ssm_conv_kernel",
                "_full_attention_interval",
                "_key_length_mla",
                "_n_kv_heads_by_layer",
                "_kv_key_length_swa",
                "_kv_value_length_swa",
                "_shared_kv_layers",
                "_nextn_predict_layers",
            ):
                setattr(db, attr, None)
            db._model_identifier = "mtp-draft"
            db._read_gguf_metadata(drafter_path)
        except Exception as e:  # unreadable drafter -> caller falls back
            logger.debug(f"Could not read drafter GGUF for MTP budget: {e}")
            db = None
        self._draft_backend_cache = (drafter_path, db)
        return db

    def _mtp_draft_kv_bytes(
        self,
        n_ctx: int,
        *,
        drafter_path: Optional[str] = None,
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        n_parallel: int = 1,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """Draft KV bytes at n_ctx from GGUF dims (separate drafter at heavier type, embedded head from main dims); None when dims missing (flat fallback)."""
        if n_ctx <= 0:
            return None
        bpe_k = _kv_bytes_per_elem(draft_cache_type_k)
        bpe_v = _kv_bytes_per_elem(draft_cache_type_v)
        if drafter_path:
            db = self._draft_backend_for(drafter_path)
            if db is None or not db._can_estimate_kv():
                return None
            # Gemma 4 assistant layers share the target's KV, so only drafter weights add memory.
            if getattr(db, "_architecture", None) == "gemma4-assistant":
                return 0
            heavier = draft_cache_type_k if bpe_k >= bpe_v else draft_cache_type_v
            # The drafter follows the main model's slot and stream layout.
            kv = db._estimate_kv_cache_bytes(
                n_ctx,
                heavier,
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )
            return kv if kv > 0 else None
        nextn = self._nextn_predict_layers or 0
        n_kv = self._n_kv_heads or self._n_heads
        k_len = self._kv_key_length
        v_len = self._kv_value_length
        if not (nextn and n_kv and k_len and v_len):
            return None
        # A one-layer MTP head fits less context with a quantized KV than f16, so floor it at f16.
        f16_bpe = _kv_bytes_per_elem("f16")
        bpe_k = max(bpe_k, f16_bpe)
        bpe_v = max(bpe_v, f16_bpe)
        _, streams, cells_per_stream = _kv_cache_cell_layout(n_ctx, n_parallel, kv_unified)
        v_width = n_kv * v_len
        if not flash_attn:
            v_width = self._max_kv_value_width(
                v_len,
                self._kv_value_length_swa,
            )
        return int(nextn * (n_kv * k_len * bpe_k + v_width * bpe_v) * cells_per_stream * streams)

    def _cpu_resident_draft_bytes(
        self,
        n_ctx: int,
        *,
        drafter_path: Optional[str],
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        n_parallel: int = 1,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """A CPU-pinned drafter is charged to host RAM, since --load-mode none makes it anonymous memory; None when unpriceable so the caller abstains."""
        if not drafter_path:
            return 0
        try:
            weights = self._get_gguf_size_bytes(drafter_path)
        except Exception:
            weights = 0
        if weights <= 0:
            return None
        kv = self._mtp_draft_kv_bytes(
            n_ctx,
            drafter_path = drafter_path,
            draft_cache_type_k = draft_cache_type_k,
            draft_cache_type_v = draft_cache_type_v,
            n_parallel = n_parallel,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            flash_attn = flash_attn,
        )
        if kv is None:
            return None
        # The drafter's own context allocates its decode graph on the host here.
        return int(weights) + max(0, int(kv)) + self._MTP_DRAFT_COMPUTE_BYTES

    def _estimate_mtp_overhead_bytes(
        self,
        n_ctx: int,
        *,
        spec_draft_n_max: int = 0,
        draft_cache_type_k: Optional[str] = None,
        draft_cache_type_v: Optional[str] = None,
        drafter_path: Optional[str] = None,
        draft_weights_bytes: int = 0,
        n_parallel: int = 1,
        mtp_keeps_target_ctx: bool = True,
        target_rollback: bool = True,
        swa_full: bool = False,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        flash_attn: bool = True,
    ) -> Optional[int]:
        """MTP draft reserve: draft KV + drafter weights + verify state (MLA repeats target KV, hybrids add rollback); None if KV unsized, caller keeps flat fallback."""
        draft_kv = self._mtp_draft_kv_bytes(
            n_ctx,
            drafter_path = drafter_path,
            draft_cache_type_k = draft_cache_type_k,
            draft_cache_type_v = draft_cache_type_v,
            n_parallel = n_parallel,
            swa_full = swa_full,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            flash_attn = flash_attn,
        )
        weights = max(0, draft_weights_bytes)
        # MLA models under MTP keep a second f16 copy of the target KV (ctx_tgt=yes), about the size of
        # the main KV. Not charged for non-MLA MTP, separate drafters, or NextN-only contexts.
        target_ctx_copy = 0
        if (
            mtp_keeps_target_ctx
            and self._kv_lora_rank is not None
            and not _arch_mtp_skips_target_kv_copy(getattr(self, "_architecture", None))
        ):
            target_ctx_copy = self._estimate_kv_cache_bytes(
                n_ctx,
                "f16",
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )
        # Hybrid Mamba targets add one rollback state copy per drafted token in the target context;
        # target_rollback decides, not drafter_path.
        target_recurrent_copies = 0
        if target_rollback and spec_draft_n_max > 0:
            target_recurrent_copies = self._rollback_state_bytes(n_parallel) * spec_draft_n_max
        spec_compute = self._mtp_draft_compute_bytes(
            n_ctx,
            drafter_path = drafter_path,
            n_ubatch = n_ubatch,
            n_parallel = n_parallel,
            spec_draft_n_max = spec_draft_n_max,
        )
        if draft_kv is None:
            # KV unsized: still reserve known weights and target copies. Nothing known -> None.
            total = weights + target_ctx_copy + target_recurrent_copies
            return total + spec_compute if total > 0 else None
        return draft_kv + weights + target_ctx_copy + target_recurrent_copies + spec_compute

    def _mtp_draft_compute_bytes(
        self,
        n_ctx: int,
        *,
        drafter_path: Optional[str] = None,
        n_ubatch: Optional[int] = None,
        n_parallel: int = 1,
        spec_draft_n_max: int = 0,
    ) -> int:
        """Draft mask and activations beyond the separately charged floor, plus
        target verification rows. Use the drafter's dimensions when available,
        otherwise the target's dimensions for an embedded head."""
        verify_rows = self._spec_verify_rows_bytes(n_parallel, spec_draft_n_max)
        if n_ctx <= 0:
            return verify_rows
        ub = max(1, int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch))
        width = self._compute_activation_width()
        db = self._draft_backend_for(drafter_path) if drafter_path else None
        if db is not None:
            draft_width = getattr(db, "_compute_activation_width", lambda: 0)()
            if draft_width > 0:
                width = draft_width + 2 * (getattr(self, "_embedding_length", None) or 0)
            if getattr(db, "_architecture", None) == "dflash" and draft_width > 0:
                # The DSpark/DFlash prompt graph grows with -ub (DeepSeek-V4.1 DSpark: 725.5 MiB at
                # 512, 2900.5 MiB at 2048).
                vocab = (
                    getattr(db, "_vocab_size", None)
                    or getattr(self, "_vocab_size", None)
                    or _ASSUMED_MAX_VOCAB
                )
                heads = (getattr(db, "_n_heads", None) or 0) * (
                    getattr(db, "_kv_key_length", None) or 0
                )
                width = max(width, 2 * vocab + 2 * heads + draft_width)
        activations = int(width * ub * 4 * self._COMPUTE_BUFFER_SAFETY)
        spec = verify_rows + max(0, ub * 2 * n_ctx + activations - self._MTP_DRAFT_COMPUTE_BYTES)
        if getattr(db, "_architecture", None) == "dflash":
            spec = max(spec, self._DFLASH_DRAFT_COMPUTE_BYTES)
        return spec

    def _spec_verify_rows_bytes(self, n_parallel: int, spec_draft_n_max: int) -> int:
        """Target output rows for verified draft tokens, wherever the drafter runs."""
        return (
            max(1, n_parallel)
            * max(0, spec_draft_n_max)
            * self._SPEC_VERIFY_ROW_COPIES
            * (getattr(self, "_vocab_size", None) or _ASSUMED_MAX_VOCAB)
            * 4
        )

    def _mtp_reserve_note(
        self,
        reserve_bytes: int,
        *,
        n_ctx: int,
        n_parallel: int,
        n_ubatch: Optional[int],
        n_max: Optional[int],
        target_rollback: bool,
        flat_fallback: bool,
        reprice: Optional[Callable[[int, int], int]] = None,
    ) -> str:
        """Names only the dimensions that move the reserve, as judged by reprice; otherwise all of them."""
        ubatch = self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch

        def _moves(*candidates: tuple[int, int]) -> bool:
            if reprice is None:
                return True
            try:
                # The estimator's own value, not the total: a flat fallback reports 0.
                base = reprice(n_parallel, ubatch)
                for slots, ub in candidates:
                    if reprice(slots, ub) != base:
                        return True
            except Exception:
                # Cannot answer says nothing about the dependency: keep the name.
                return True
            return False

        # Slot counts dividing the padded total price the same; the last candidate exceeds it, so moves.
        _cells = _pad_kv_cells(max(1, n_ctx)) // 256
        slots_named = _moves(
            (n_parallel + 1, ubatch),
            (n_parallel + 2, ubatch),
            (max(n_parallel + 3, n_parallel * 2), ubatch),
            (max(n_parallel + 3, _cells + 1), ubatch),
        )
        # Same padding, via the compact-SWA window: a step of one bucket always crosses.
        ubatch_named = _moves(
            (n_parallel, ubatch * 2),
            (n_parallel, max(1, ubatch // 2)),
            (n_parallel, ubatch + 256),
        )
        scales_with_n_max = bool(
            target_rollback and n_max and self._rollback_state_bytes(n_parallel) > 0
        )
        return (
            f"MTP reserve: {reserve_bytes / (1024**3):.2f} GB "
            f"(draft KV @ {n_ctx}"
            + (f" x {n_parallel} slots" if slots_named else "")
            + (f", ubatch {ubatch}" if ubatch_named else "")
            + (f", n_max {n_max}" if scales_with_n_max else "")
            + (", flat-frac fallback" if flat_fallback else "")
            + "), "
        )

    _DEFAULT_N_UBATCH = _DEFAULT_LLAMA_N_UBATCH
    _COMPUTE_BUFFER_SAFETY = 1.10  # margin on the modelled activation width
    # Soft VRAM the modeled terms omit; charged to the fit budget on tight tiers (#6682).
    _CUDA_CONTEXT_RESERVE_BYTES = 320 * 1024 * 1024  # CUDA ctx + cuBLAS workspace (~330 MiB)
    _MMPROJ_VRAM_SAFETY = 1.4  # mmproj worst-case buffer vs file size (runtime ~1.3x)
    # Context the projector's residency is priced at: the length where fitting means no layer spills.
    _MMPROJ_FIT_FLOOR_CTX = 8192
    _MTP_DRAFT_COMPUTE_BYTES = 224 * 1024 * 1024  # MTP draft decode graph beyond its KV
    # A DFlash/DSpark draft context re-reserves a flat block graph once the drafter initialises,
    # independent of n_ctx. Measured on llama.cpp b11642, draft graph + target verify graph:
    # Nemotron 3.5 Bolt DSpark (block 8) 528.5 + 44 MiB, LiLiCorr (block 8, SWA 1024) 307 + 60 MiB.
    # The _MTP_DRAFT_COMPUTE_BYTES floor is charged beside this, so the floor is the excess over it.
    _DFLASH_DRAFT_COMPUTE_BYTES = 349 * 1024 * 1024
    # Draft depth to budget when the extras own the spec block and the probe cannot
    # read the build's own default off its --help. Shipped values are 3
    # (common_params_speculative_draft::n_max) and 16; take the deeper, since the
    # Hybrid Mamba rollback copies scale by this and under-reserving them OOMs the
    # load while over-reserving only costs context. Zero cost on any other model,
    # where the recurrent state is nil.
    _UNKNOWN_SPEC_DRAFT_N_MAX = 16
    # Vocabulary-wide float32 copies per verified draft token (logits and sampling).
    _SPEC_VERIFY_ROW_COPIES = 3
    # GGML_SCHED_MAX_COPIES input copies per device, unless pipeline parallel is disabled.
    _CTX_COMPUTE_SPLIT_MULT = 4
    # DeepSeek-V4 indexer + sparse attention reserve a ctx-scaling compute buffer the rates miss
    # (~65.5 GiB at 1M, any KV type); without it auto-fit OOMs at full context.
    _DSV4_CTX_COMPUTE_FLAT_BYTES = 2 * 1024**3  # ctx-independent indexer scratch
    _DSV4_CTX_COMPUTE_BYTES_PER_TOK = 72000  # per token at ub=512 (~72 GiB at 1M)
    # DeepSeek-V4.1 (deepseek41): its own sparse-attention graph, far smaller than DSV4's but
    # not linear in context. Measured CUDA0 compute buffer, UD-IQ1_S with experts + Engram on
    # CPU, f16 cache: ub=512 2102 / 2198 / 3094 / 11197 MiB at 16k / 64k / 256k / 1M; ub=2048
    # 9751 / 37143 MiB at 256k / 1M. Flat + linear (rate ub-scaled) is the chord to the 1M
    # point, so it stays above every measurement (convex curve; 1M is the trained maximum).
    _DSV41_CTX_COMPUTE_FLAT_BYTES = 2 * 1024**3
    _DSV41_CTX_COMPUTE_BYTES_PER_TOK = 9600  # per token at ub=512 (~11.4 GiB at 1M)

    # Inkling banded flash path, valid only with the bundled llama.cpp reserve fix: ~5.6 KiB/tok compute at ub=512; 8192 adds ~1.5x headroom.
    _INKLING_CTX_COMPUTE_BYTES_PER_TOK = 8192  # per token at ub=512
    # Dense relative-bias fallback (quantized KV disables the banded path): ~402 KiB/tok measured.
    _INKLING_CTX_COMPUTE_DENSE_BYTES_PER_TOK = 402470  # per token at ub=512

    def _compute_activation_width(self) -> int:
        """Widest dense, expert or recurrent block plus per-layer embeddings, floored at 12 * n_embd."""

        def dim(name: str) -> int:
            return getattr(self, name, None) or 0

        n_embd = dim("_embedding_length")
        if n_embd <= 0:
            return 0

        widths = [12 * n_embd]
        if dim("_feed_forward_length") > 0:
            widths.append(4 * dim("_feed_forward_length"))
        n_used = dim("_expert_used_count")
        # Granite 4.0 H writes its expert width as feed_forward_length.
        n_ff_exp = dim("_expert_feed_forward_length") or (
            dim("_feed_forward_length") if dim("_n_experts") else 0
        )
        if n_used > 0 and n_ff_exp > 0:
            shared = dim("_expert_shared_feed_forward_length") or (
                n_ff_exp * dim("_expert_shared_count")
            )
            # Nemotron 3.5 routes experts through a moe_latent_size projection.
            n_embd_exp = dim("_moe_latent_size") or n_embd
            widths.append(n_used * (2 * n_embd_exp + 3 * n_ff_exp) + 3 * shared)
        inner = dim("_ssm_inner_size")
        if inner > 0:
            conv_in = inner + 2 * (dim("_ssm_group_count") or 1) * dim("_ssm_state_size")
            widths.append(4 * conv_in)
        per_layer_input = dim("_embedding_length_per_layer_input") * dim("_n_layers")
        return max(widths) + per_layer_input

    def _estimate_compute_buffer_bytes(
        self,
        *,
        n_ubatch: Optional[int] = None,
        n_parallel: int = 1,
        per_device_tensor: bool = False,
        vocab_ceiling: Optional[int] = None,
    ) -> int:
        """Per-device compute-graph bytes not growing with context; output rows min(ubatch, slots) in newer llama.cpp, else ubatch; MTP verify rows go in MTP reserve."""
        width = self._compute_activation_width()
        n_vocab = self._vocab_size or vocab_ceiling or 0
        if width <= 0 or n_vocab <= 0:
            return 0
        ub = max(
            1,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )
        par = max(1, int(n_parallel))
        activations = width * ub * 4
        if self.is_embedding_gguf:
            outputs = (self._embedding_length or 0) * ub * 4
        elif getattr(self, "_reserves_micro_batch_outputs", False):
            # Before llama.cpp#23861: a row for every micro-batch token, once.
            outputs = n_vocab * ub * 4
        else:
            outputs = n_vocab * min(ub, par) * 4
        swa_mask = 0
        sliding_window = self._effective_sliding_window()
        if sliding_window > 0:
            swa_mask = _pad_kv_cells(sliding_window * par + ub) * ub * 2
        # A recurrent block works on every slot's state at once.
        inner = getattr(self, "_ssm_inner_size", None) or 0
        recurrent = 0
        if inner > 0:
            state = getattr(self, "_ssm_state_size", None) or 0
            conv_in = inner + 2 * (getattr(self, "_ssm_group_count", None) or 1) * state
            recurrent = par * (inner * state + 3 * conv_in) * 4
        return int((activations + outputs + recurrent) * self._COMPUTE_BUFFER_SAFETY + swa_mask)

    def _effective_sliding_window(self) -> int:
        """The sliding window when some layer really slides, else 0. Phi-4-mini
        declares a 262144 window over a 131072 context and no pattern, which bounds
        nothing."""
        window = getattr(self, "_sliding_window", None) or 0
        if window <= 0:
            return 0
        pattern = getattr(self, "_sliding_window_pattern", None)
        if pattern is not None:
            return window if any(pattern) else 0
        context = getattr(self, "_context_length", None) or 0
        return window if not context or window < context else 0

    def _attention_dequant_width(self) -> int:
        """K+V elements per cell copied to f16 from a quantized cache, from the widest global layer (SWA does not scale with context); MLA has K only."""
        n_heads = getattr(self, "_n_heads", None)
        n_kv = getattr(self, "_n_kv_heads", None) or n_heads
        kv_lora_rank = getattr(self, "_kv_lora_rank", None)
        key_len = getattr(self, "_kv_key_length", None)
        val_len = getattr(self, "_kv_value_length", None)
        if kv_lora_rank is not None:
            rope_dim = getattr(self, "_key_length_mla", None) or 64
            return (getattr(self, "_n_kv_heads", None) or 1) * (key_len or kv_lora_rank + rope_dim)
        if key_len is None or val_len is None:
            if not (n_heads and n_kv):
                return getattr(self, "_embedding_length", None) or 0
            return 2 * n_kv * self._legacy_head_dim()
        by_layer = getattr(self, "_n_kv_heads_by_layer", None)
        pattern = (
            getattr(self, "_sliding_window_pattern", None)
            if getattr(self, "_sliding_window", None)
            else None
        )
        widest = 0
        for i, heads in enumerate(by_layer or ()):
            if not (pattern is not None and i < len(pattern) and pattern[i]):
                widest = max(widest, heads)
        return (widest or n_kv or 1) * (key_len + val_len)

    def _compute_buffer_ctx_bytes(
        self,
        n_ctx: int,
        n_ubatch: Optional[int] = None,
        cache_type_kv: Optional[str] = None,
        *,
        layer_split: bool = False,
        flash_attn: bool = True,
        n_parallel: int = 1,
    ) -> int:
        """Per-device context scratch: KQ mask and dequant; without flash attention, float32 scores
        and mask."""
        n_embd = self._embedding_length or 0
        if n_embd <= 0 or n_ctx <= 0:
            return 0
        ub = max(
            1,
            int(self._DEFAULT_N_UBATCH if n_ubatch is None else n_ubatch),
        )
        # One KQ mask copy, f16 with FA, f32 without. Rates below include one; a split adds copies.
        mask_rate = ub * (2 if flash_attn else 4)
        split_extra = (self._CTX_COMPUTE_SPLIT_MULT - 1) * mask_rate if layer_split else 0
        if getattr(self, "_architecture", None) == "deepseek4":
            # DSV4: flat + linear, ub-scaled, any KV type. No split_extra: 72000 already covers the mask copies.
            ub_scale = ub / self._DEFAULT_N_UBATCH
            return int(
                self._DSV4_CTX_COMPUTE_FLAT_BYTES
                + self._DSV4_CTX_COMPUTE_BYTES_PER_TOK * n_ctx * ub_scale
            )
        if getattr(self, "_architecture", None) == "deepseek41":
            # DSV4.1 sparse-attention buffer (see constants): flat + linear, ub-scaled. Unlike
            # deepseek4 the rate has little headroom at 1M (~4%), so a layer split adds the
            # extra mask copies like every other arch.
            ub_scale = ub / self._DEFAULT_N_UBATCH
            per_tok = self._DSV41_CTX_COMPUTE_BYTES_PER_TOK * ub_scale + split_extra
            flat = self._DSV41_CTX_COMPUTE_FLAT_BYTES
            if not flash_attn:
                # Dense branch: f32 KQ scores [window + n_comp, ub, n_head]. Layer score sizes
                # differ, so the allocator fragments and keeps two copies live (one undercounts).
                n_head = getattr(self, "_n_heads", None) or max(1, n_embd // 64)
                score_rate = 2 * ub * n_head * 4
                window_cells = _pad_kv_cells(
                    self._effective_sliding_window() * max(1, int(n_parallel)) + ub
                )
                # The measured rate holds one f16 KQ mask; here it is f32.
                per_tok += score_rate + ub * 2
                flat += score_rate * window_cells
            return int(flat + per_tok * n_ctx)
        if getattr(self, "_architecture", None) == "inkling":
            ub_scale = ub / self._DEFAULT_N_UBATCH
            # A quantized KV forces the dense fallback (~402 KiB/tok); size for it so the server loads.
            if cache_type_kv and _kv_bytes_per_elem(cache_type_kv) < 2.0:
                rate = self._INKLING_CTX_COMPUTE_DENSE_BYTES_PER_TOK
            else:
                # Banded flash path (see constants): linear, ub-scaled.
                rate = self._INKLING_CTX_COMPUTE_BYTES_PER_TOK
            # Both paths allocate the mask, and 8192 has too little headroom to absorb a split.
            return int(rate * n_ctx * ub_scale + split_extra * n_ctx)
        per_tok = mask_rate
        if _kv_bytes_per_elem(cache_type_kv) < 2.0:
            # Quantized cache: the f16 K/V copy, independent of the micro-batch.
            per_tok += self._attention_dequant_width() * 2
        if not flash_attn:
            n_head = getattr(self, "_n_heads", None) or max(1, n_embd // 64)
            per_tok += ub * n_head * 4
            if getattr(self, "_kv_lora_rank", None) is not None:
                # MLA decompresses an f32 copy of the latent cache to attend over it.
                per_tok += self._attention_dequant_width() * 4
        # Scheduler copies replicate masks and hidden states, not dequant scratch.
        split_fixed = 0
        if layer_split:
            split_fixed = self._CTX_COMPUTE_SPLIT_MULT * n_embd * ub * 4
            sliding_window = self._effective_sliding_window()
            if sliding_window > 0:
                swa_cells = _pad_kv_cells(sliding_window * max(1, int(n_parallel)) + ub)
                split_fixed += (self._CTX_COMPUTE_SPLIT_MULT - 1) * swa_cells * mask_rate
        return int((per_tok + split_extra) * n_ctx + split_fixed)

    def _slots_that_fit_on_gpu(
        self,
        n_parallel: int,
        effective_ctx: int,
        gpus: list[tuple[int, int]],
        total_by_idx: Optional[dict[int, int]],
        base_footprint_bytes: int,
        cache_type_kv: Optional[str],
        pin_fraction: float,
        per_device_overhead_bytes: int,
        min_gpus: int,
        n_ubatch: Optional[int] = None,
        swa_full: bool = False,
        kv_unified: bool = True,
        flash_attn: bool = True,
        split_extra_bytes: int = 0,
        split_extra_for_slots: Optional[Callable[[int], int]] = None,
        ubatch_for_slots: Optional[Callable[[int], Optional[int]]] = None,
        mtp_bytes_for_slots: Optional[Callable[[int, Optional[int]], int]] = None,
        ctx_checkpoints: int = 0,
        include_requested: bool = False,
        exact: bool = False,
        integrated: frozenset = frozenset(),
        discrete_host_only_bytes: int = 0,
        prefer_discrete: bool = True,
        discount_prefixes: frozenset = frozenset(),
        shared_gpu_ids: Optional[Iterable[int]] = None,
    ) -> tuple[Optional[list[int]], bool, int]:
        """Largest serving-slot count that fits fully on GPU, so Unsloth keeps the model on
        GPU (-ngl -1) instead of --fit on, which offloads layers to host and collapses decode
        ~3x (oobabooga #6718). The search runs over [1, n_parallel) by default, or over
        [1, n_parallel] when ``include_requested`` is set. ``base_footprint_bytes`` is the
        slot-independent footprint (weights + soft overhead + context-linear compute,
        minus the folded compute buffer); each candidate re-adds the slot-sized compute buffer
        and KV, then re-selects GPUs like the explicit-context path -- ``split_extra_bytes``
        included, so a multi-GPU candidate is re-checked at the split rate. Returns
        (gpu_indices, use_fit=False, slots) for the largest fitting count, else (None, True,
        n_parallel). Unit-testable with synthetic VRAM maps.
        ``exact`` stops after the first candidate, for a caller that accepts only
        ``n_parallel`` itself and would re-price every lower count just to discard it.
        ``ctx_checkpoints`` mirrors --ctx-checkpoints: N host-RAM snapshots per slot,
        passed only when the GPUs share that pool (unified memory), else 0.
        ``integrated``: the discrete-tier attempt is priced without the checkpoints and
        without ``discrete_host_only_bytes`` (e.g. a CPU-pinned projector on a shared pool);
        ``gpus`` already narrowed to discrete cards of a mixed pool are priced that way outright.
        ``prefer_discrete`` False (explicit device pick) skips the tier, keeping that pricing.
        ``ubatch_for_slots`` re-derives the micro-batch per candidate: the emitted
        --batch-size is raised to max(slots, 2), and llama.cpp caps the micro-batch
        against it, so a batch below the requested slot count shrinks as the candidates
        do. Holding it at the requested count made a fitting candidate look too big and
        dropped the load to --fit offload.
        ``mtp_bytes_for_slots(slots, ubatch)`` does the same for the MTP reserve, which is
        NOT slot-independent: compact SWA scales its window allowance by the slot count
        under kv_unified and adds one micro-batch, and an MLA target with recurrent (KDA)
        layers charges per slot. It takes the candidate micro-batch as well as the slot
        count, since a reduced candidate lowers the batch floor and so the ubatch too;
        pricing the reserve at the requested pair over-charged every candidate, so one that
        fits could be rejected and the load kept --fit. ``split_extra_for_slots(slots)``
        re-prices the split step, whose sliding-window masks also scale with slots."""
        for slots in range(n_parallel if include_requested else n_parallel - 1, 0, -1):
            _ub = ubatch_for_slots(slots) if ubatch_for_slots else n_ubatch
            cb = self._estimate_compute_buffer_bytes(
                n_ubatch = _ub, n_parallel = slots, per_device_tensor = False
            )
            if cb <= 0:
                cb = self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024

            def _kv(ckpts: int) -> int:
                return self._estimate_kv_cache_bytes(
                    effective_ctx,
                    cache_type_kv,
                    n_parallel = slots,
                    swa_full = swa_full,
                    kv_unified = kv_unified,
                    n_ubatch = _ub,
                    ctx_checkpoints = ckpts,
                    flash_attn = flash_attn,
                )

            kv = _kv(ctx_checkpoints)
            total = (
                base_footprint_bytes
                + cb
                + (mtp_bytes_for_slots(slots, _ub) if mtp_bytes_for_slots else 0)
                + kv
            )
            # Checkpoints and host-only bytes sit in host RAM, which a dGPU does not draw on.
            discrete_total = None
            if integrated and (ctx_checkpoints or discrete_host_only_bytes):
                discrete_total = (
                    total - discrete_host_only_bytes - (kv - _kv(0) if ctx_checkpoints else 0)
                )
                # Devices already narrowed to dGPUs of a mixed pool (the slot re-fit).
                if all(g[0] not in integrated for g in gpus):
                    total = discrete_total
            gpu_indices, use_fit = self._select_gpus_split_aware(
                total,
                gpus,
                usable_fraction = pin_fraction,
                total_by_idx = total_by_idx,
                per_device_overhead_bytes = per_device_overhead_bytes,
                min_gpus = min_gpus,
                split_extra_bytes = (
                    split_extra_for_slots(slots) if split_extra_for_slots else split_extra_bytes
                ),
                integrated = integrated,
                discrete_size_bytes = discrete_total,
                prefer_discrete = prefer_discrete,
                discount_prefixes = discount_prefixes,
                shared_gpu_ids = shared_gpu_ids,
            )
            if not use_fit:
                return gpu_indices, False, slots
            if exact:
                break
        return None, True, n_parallel

    def _fit_context_to_vram(
        self,
        requested_ctx: int,
        available_mib: int,
        model_size_bytes: int,
        cache_type_kv: Optional[str] = None,
        min_ctx: int = 8192,
        *,
        swa_full: bool = False,
        n_parallel: int = 1,
        kv_unified: bool = True,
        n_ubatch: Optional[int] = None,
        ctx_checkpoints: int = 0,
        flash_attn: bool = True,
        kv_on_gpu: bool = True,
        mtp_engaged: bool = False,
        # True only for an absolute budget already summed across cards.
        pooled: bool = False,
        mtp_overhead_fn: Optional[Callable[[int], int]] = None,
        compute_ctx_bytes_fn: Optional[Callable[[int], int]] = None,
        budget_frac: Optional[float] = None,
        total_mib: Optional[int] = None,
    ) -> int:
        """Return the largest context length that fits in GPU VRAM.

        Budget caps occupancy at ``_CTX_FIT_VRAM_FRACTION`` of the card: an
        absolute ``free - (1 - frac) * total`` when ``total_mib`` is given, else
        ``free * frac``. Weights alone over budget returns ``requested_ctx``.

        ``kv_on_gpu`` mirrors ``--kv-offload`` (default on); when False the KV
        cache lives in CPU RAM and the requested context is honored verbatim.
        Other keyword args mirror ``_estimate_kv_cache_bytes``; pass ``ctx_checkpoints``
        only against a unified-memory budget, since the snapshots live in host RAM.

        ``mtp_engaged`` reserves extra VRAM for the MTP draft model's KV cache +
        compute buffers, else tight tiers (e.g. 32 GB) spill to a slower path.
        """
        if not self._can_estimate_kv():
            logger.debug(
                "Skipping context fit because KV cache metadata is unavailable",
                requested_ctx = requested_ctx,
                available_mib = available_mib,
            )
            return requested_ctx

        # KV lives off-GPU: no VRAM accounting needed for the cache itself.
        if not kv_on_gpu:
            return requested_ctx

        kv_kwargs = dict(
            swa_full = swa_full,
            n_parallel = n_parallel,
            kv_unified = kv_unified,
            n_ubatch = n_ubatch,
            ctx_checkpoints = ctx_checkpoints,
            flash_attn = flash_attn,
        )

        # A byte-accurate mtp_overhead_fn supersedes the flat fraction.
        if budget_frac is None:
            flat_mtp = mtp_engaged and mtp_overhead_fn is None
            budget_frac = _active_vram_fraction() - (_MTP_VRAM_RESERVE_FRAC if flat_mtp else 0.0)
        # Absolute reserve off total when known, else fraction-of-free; clamp >=0.
        budget_mib = _vram_usable_mib(
            available_mib,
            total_mib or 0,
            budget_frac,
            pooled = pooled,
            sysmem_fallback = LlamaCppBackend._sysmem_fallback_risk(),
        )
        if total_mib is not None and total_mib > 0:
            budget_mib = max(0.0, budget_mib)
        budget_bytes = budget_mib * 1024 * 1024
        model_footprint = model_size_bytes

        def _mtp_at(ctx: int) -> int:
            return mtp_overhead_fn(ctx) if mtp_overhead_fn is not None else 0

        def _cc_at(ctx: int) -> int:
            # Context-linear compute growth; model_footprint's flat term covers only ctx -> 0.
            return compute_ctx_bytes_fn(ctx) if compute_ctx_bytes_fn is not None else 0

        # Already fits?
        kv = self._estimate_kv_cache_bytes(requested_ctx, cache_type_kv, **kv_kwargs)
        if model_footprint + kv + _mtp_at(requested_ctx) + _cc_at(requested_ctx) <= budget_bytes:
            return requested_ctx

        # Weights + compute buffer alone exceed budget -- reducing ctx can't help.
        if model_footprint >= budget_bytes:
            logger.debug(
                "Model footprint exceeds GPU budget before KV cache",
                requested_ctx = requested_ctx,
                available_mib = available_mib,
                model_size_gb = round(model_footprint / (1024**3), 2),
            )
            return requested_ctx

        # Binary search for max context that fits (KV + MTP draft reserve at that ctx)
        remaining = budget_bytes - model_footprint
        effective_min = min(min_ctx, requested_ctx)
        lo, hi = effective_min, requested_ctx
        best = effective_min
        while lo <= hi:
            mid = (lo + hi) // 2
            kv = self._estimate_kv_cache_bytes(mid, cache_type_kv, **kv_kwargs)
            if kv + _mtp_at(mid) + _cc_at(mid) <= remaining:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1

        # Round down to nearest 256 for alignment, never above requested_ctx
        best = (best // 256) * 256
        best = max(effective_min, best)
        best = min(best, requested_ctx)
        return best

    # ── Variant fallback ────────────────────────────────────────────

    @staticmethod
    def _find_fitting_variant(
        hf_repo: str,
        free_bytes: int,
        requested_bytes: int,
        hf_token: Optional[str] = None,
        requested_file: Optional[str] = None,
    ) -> Optional[tuple[str, int, list[str]]]:
        """Smaller-than-requested GGUF variant incl all shards: largest leaving _DISK_RESERVE_BYTES free, else fewest new bytes; (first shard, total, extras) or None."""
        try:
            from huggingface_hub import get_paths_info, list_repo_files
            from core.inference.openai_auto_download import _DISK_RESERVE_BYTES

            files = call_hub_with_anonymous_retry(list_repo_files, hf_token, hf_repo)
            from hub.utils.gguf import drop_shadowed_appledouble_names, gguf_checkpoint_family

            gguf_files = [
                f
                for f in drop_shadowed_appledouble_names(list(files))
                if f.lower().endswith(".gguf")
                and not _is_companion_gguf_path(f)
                and not _is_big_endian_gguf_path(f)
            ]
            # A sibling checkpoint's smaller quant is different weights, not a fallback.
            if requested_file is not None:
                checkpoint = gguf_checkpoint_family(requested_file)
                gguf_files = [f for f in gguf_files if gguf_checkpoint_family(f) == checkpoint]
            if not gguf_files:
                return None

            # Sizes for all GGUF files
            path_infos = list(
                call_hub_with_anonymous_retry(get_paths_info, hf_token, hf_repo, gguf_files)
            )
            size_map = {p.path: (p.size or 0) for p in path_infos}

            # Group by variant: shards share a prefix before -NNNNN-of-NNNNN
            variants: dict[str, list[str]] = {}
            for f in gguf_files:
                m = _SHARD_RE.match(f)
                key = m.group(1) if m else f
                variants.setdefault(key, []).append(f)

            # Sum shard sizes per variant, track the first shard (for download)
            fitting: list[tuple[str, int, list[str], int]] = []
            for key, shard_files in variants.items():
                total = sum(size_map.get(f, 0) for f in shard_files)
                first = sorted(shard_files)[0]
                extra = [path for path in sorted(shard_files) if path != first]
                cached = _cached_complete_candidate(hf_repo, first, extra)
                needed = (
                    0
                    if cached and _cached_candidate_matches_revision_size(hf_repo, cached, hf_token)
                    else total
                )
                if 0 < total < requested_bytes and needed <= free_bytes:
                    fitting.append((first, total, extra, needed))
            if not fitting:
                return None

            roomy = [v for v in fitting if v[3] + _DISK_RESERVE_BYTES <= free_bytes]
            # Only cached variants can tie on new bytes, and the larger costs no more.
            first_file, total_size, extra_shards, _ = (
                max(roomy, key = lambda v: v[1])
                if roomy
                else min(fitting, key = lambda v: (v[3], -v[1]))
            )
            return first_file, total_size, extra_shards
        except Exception:
            return None

    # ── Port allocation ───────────────────────────────────────────

    @staticmethod
    def _find_free_port() -> int:
        """Find an available TCP port."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.bind(("127.0.0.1", 0))
            return s.getsockname()[1]

    @staticmethod
    def _health_listener_is_ours(
        process,
        port,
        bind_host = None,
    ) -> bool:
        """False when the port answering /health is demonstrably not held by our child's tree.

        _find_free_port releases the port before llama-server binds it, so another local user could
        answer /health and receive every prompt plus the per-launch key. Their socket shows no pid
        on Linux/macOS, so our own (readable) tree not listening counts as foreign. Unreadable
        ownership keeps today's behaviour. On Windows psutil can report our live listener as NONE
        and/or pid 0 (#15022), so only a named foreign pid refuses there."""
        pid = getattr(process, "pid", None)
        if not isinstance(pid, int) or not isinstance(port, int):
            return True
        # A child that already exited cannot be the server that answered.
        poll = getattr(process, "poll", None)
        if callable(poll) and poll() is not None:
            return False
        try:
            import psutil
            from core.inference.sd_cpp_server import _has_ancestor
        except Exception:  # noqa: BLE001 -- optional dependency
            return True
        try:
            root = psutil.Process(pid)
            tree = [root, *root.children(recursive = True)]
        except psutil.NoSuchProcess:
            return False
        except Exception:  # noqa: BLE001 -- access denied / platform quirk
            return True

        windows = _socket_owner_is_always_named()
        bind_ips = set(_LOOPBACK_REACHABLE_BIND_IPS)
        if bind_host:
            try:
                bind_ips.update(a[4][0] for a in socket.getaddrinfo(bind_host, port))
            except OSError:
                pass

        def _listens(conn) -> bool:
            laddr = getattr(conn, "laddr", None)
            if not (
                bool(laddr)
                and getattr(laddr, "port", None) == port
                and getattr(laddr, "ip", None) in bind_ips
            ):
                return False
            if conn.status == psutil.CONN_LISTEN:
                return True
            # Windows can report the live listener as NONE: a TCP socket with no peer still is one.
            return (
                windows
                and conn.status == psutil.CONN_NONE
                and not getattr(conn, "raddr", None)
                and getattr(conn, "type", socket.SOCK_STREAM) == socket.SOCK_STREAM
            )

        tree_readable = True
        for member in tree:
            try:
                read = getattr(member, "net_connections", None) or member.connections
                if any(_listens(c) for c in read(kind = "inet")):
                    return True
            except psutil.NoSuchProcess:
                continue
            except Exception:  # noqa: BLE001 -- access denied / platform quirk
                tree_readable = False
        tree_pids = {m.pid for m in tree}
        foreign = None
        try:
            # Scan every listener: a foreign one listed before ours must not refuse our start.
            for conn in psutil.net_connections(kind = "inet"):
                # pid 0 is the System Idle Process on Windows: psutil's other "unknown owner".
                if not _listens(conn) or conn.pid is None or (windows and conn.pid == 0):
                    continue
                if conn.pid in tree_pids or _has_ancestor(conn.pid, pid):
                    return True
                foreign = conn.pid
        except Exception as exc:  # noqa: BLE001 -- permissions / platform quirks
            logger.debug("llama-server port ownership check unavailable: %s", exc)
        if foreign is not None:
            logger.error(
                "llama-server port %s is held by pid %s, not our child %s; refusing to use it",
                port,
                foreign,
                pid,
            )
            return False
        if tree_readable and not windows:
            logger.error(
                "llama-server port %s answered /health but our child %s is not listening on it; "
                "refusing to use it",
                port,
                pid,
            )
            return False
        return True

    # ── Stdout drain (prevents pipe deadlock on Windows) ─────────

    def _drain_stdout(self):
        """Drains llama-server stdout in a background thread so a full ~4 KB Windows pipe cannot block it; tees each line to _llama_log_fh when set."""
        startup_len: Optional[int] = None
        log_bytes = 0
        levelled = to_info = False
        proc = self._process
        device_lost_seen = False
        metal_poison = {"draft": False}
        try:
            for line in proc.stdout:
                line = line.rstrip()
                if line:
                    lines = self._stdout_lines
                    lines.append(line)
                    if len(lines) > _STDOUT_TRIM_AT:
                        # Before readiness the whole log so far is startup: keep its head too.
                        head = _STDOUT_HEAD_MAX if startup_len is None else startup_len
                        head = min(head, _STDOUT_HEAD_MAX, len(lines))
                        del lines[head : len(lines) - _STDOUT_TAIL_KEEP]
                    # Only readiness lines wake the probe; waking per tensor-load line spins startup.
                    line_lower = line.lower()
                    ready = "server is listening" in line_lower or "model loaded" in line_lower
                    if ready:
                        if startup_len is None:
                            startup_len = len(self._stdout_lines)
                        health_probe_event = getattr(self, "_health_probe_event", None)
                        if health_probe_event is not None:
                            health_probe_event.set()
                    # Unprefixed lines continue the previous record (e.g. a request dump).
                    level = _LOG_LEVEL_TOKEN_RE.match(line)
                    if level is not None:
                        levelled = True
                        to_info = level.group(1) in "WE" or (ready and level.group(1) == "I")
                        # E lines only: unprefixed lines can be a request dump with user text.
                        if level.group(1) == "E":
                            if any(m in line for m in _DRAFT_CONTEXT_FAILURE_MARKERS):
                                metal_poison["draft"] = True
                            if not device_lost_seen and any(
                                marker in line for marker in _GPU_DEVICE_LOST_MARKERS
                            ):
                                device_lost_seen = True
                                self._retire_device_lost_server_soon(proc)
                            elif (
                                not device_lost_seen
                                and not metal_poison.get("pending")
                                and any(
                                    marker in line for marker in _METAL_BACKEND_POISONED_MARKERS
                                )
                            ):
                                # Not latched: a request can echo this text, so retirement confirms
                                # a compute failure first.
                                metal_poison["pending"] = True
                                self._retire_device_lost_server_soon(
                                    proc, metal_poison = metal_poison
                                )
                    elif not levelled:
                        to_info = ready or _llama_line_is_warning_or_error(line, line_lower)
                    try:
                        if to_info:
                            logger.info(f"[llama-server] {line}")
                        else:
                            logger.debug(f"[llama-server] {line}")
                    except Exception:
                        # A closed stdout must not stop the drain and stall the server.
                        pass
                    fh = getattr(self, "_llama_log_fh", None)
                    if fh is not None:
                        try:
                            if log_bytes >= _LLAMA_LOG_FULL_BYTES:
                                if not _llama_line_is_warning_or_error(line, line_lower):
                                    continue
                            elif log_bytes + len(line) + 1 >= _LLAMA_LOG_FULL_BYTES:
                                fh.write(
                                    "[studio] log past 64 MiB: keeping warnings and errors only\n"
                                )
                            log_bytes += len(line) + 1
                            fh.write(line + "\n")
                            fh.flush()
                        except ValueError:
                            # Closed under us by the kill path.
                            pass
                        except OSError as e:
                            if not getattr(self, "_llama_log_tee_failed", False):
                                self._llama_log_tee_failed = True
                                try:
                                    logger.warning(
                                        f"Could not write llama-server log "
                                        f"{getattr(self, '_llama_log_path', None)}: {e}"
                                    )
                                except Exception:
                                    pass
        except Exception:
            # Never let the drain die: a full stdout pipe can deadlock llama-server on Windows.
            logger.debug("llama-server stdout drain stopped", exc_info = True)
        finally:
            # EOF means the process exited; wake the health loop immediately.
            health_probe_event = getattr(self, "_health_probe_event", None)
            if health_probe_event is not None:
                health_probe_event.set()

    # GGUF KV type sizes for fast skipping
    _GGUF_TYPE_SIZE = {
        0: 1,
        1: 1,
        2: 2,
        3: 2,
        4: 4,
        5: 4,
        6: 4,
        7: 1,
        10: 8,
        11: 8,
        12: 8,
    }

    @staticmethod
    def _gguf_skip_value(f, vtype: int) -> None:
        """Skip a GGUF KV value without reading it."""
        sz = LlamaCppBackend._GGUF_TYPE_SIZE.get(vtype)
        if sz is not None:
            f.seek(sz, 1)
        elif vtype == 8:  # STRING
            slen = struct.unpack("<Q", f.read(8))[0]
            f.seek(slen, 1)
        elif vtype == 9:  # ARRAY
            atype = struct.unpack("<I", f.read(4))[0]
            alen = struct.unpack("<Q", f.read(8))[0]
            elem_sz = LlamaCppBackend._GGUF_TYPE_SIZE.get(atype)
            if elem_sz is not None:
                f.seek(elem_sz * alen, 1)
            elif atype == 8:
                from utils.models.gguf_metadata import skip_gguf_strings
                for _ in range(alen - skip_gguf_strings(f, alen)):
                    slen = struct.unpack("<Q", f.read(8))[0]
                    f.seek(slen, 1)
            else:
                for _ in range(alen):
                    LlamaCppBackend._gguf_skip_value(f, atype)
        else:
            # Its size is unknown, so every later read would be misaligned.
            raise ValueError(f"unknown GGUF value type {vtype}")

    @staticmethod
    def _gguf_read_array_value(f, atype: int, alen: int) -> Optional[list]:
        if atype == 4:  # UINT32
            return [struct.unpack("<I", f.read(4))[0] for _ in range(alen)]
        if atype == 5:  # INT32
            return [struct.unpack("<i", f.read(4))[0] for _ in range(alen)]
        if atype == 7:  # BOOL
            return [struct.unpack("<?", f.read(1))[0] for _ in range(alen)]

        if atype == 8:  # STRING: kept only for the delimiter-shaped entries (#7066).
            from core.inference.chat_template_helpers import delimiter_shaped_tokens
            from utils.models.gguf_metadata import take_gguf_strings_by_first_byte

            done, raws = take_gguf_strings_by_first_byte(f, alen, _GGUF_MARKUP_FIRST_BYTES)
            kept: list = []
            for raw in raws:
                try:
                    kept.append(raw.decode("utf-8"))
                except UnicodeDecodeError:
                    continue
            for _ in range(alen - done):
                n = struct.unpack("<Q", f.read(8))[0]
                raw = f.read(n)
                # Only <...> / [...] entries are kept, so skip decoding the rest; UTF-8 makes the first byte
                # decisive. Still read, not seeked, so short reads and non-seekable streams behave the same.
                if raw[:1] != b"<" and raw[:1] != b"[":
                    continue
                # Undecodable entries are not markers.
                try:
                    kept.append(raw.decode("utf-8"))
                except UnicodeDecodeError:
                    continue
            return delimiter_shaped_tokens(kept)

        for _ in range(alen):
            LlamaCppBackend._gguf_skip_value(f, atype)
        return None

    @classmethod
    def _gguf_path_is_diffusion(cls, gguf_path: str, model_identifier: str) -> bool:
        """Classify a downloaded GGUF without mutating the active backend."""
        probe = object.__new__(cls)
        probe._model_identifier = model_identifier
        probe._read_gguf_metadata(gguf_path)
        return probe._is_diffusion

    @classmethod
    def _gguf_path_wants_nested_mtp(cls, gguf_path: str) -> bool:
        """May this target take an MTP/ drafter? Only qwen4exp with no head of its own; arch-gated since MTP/ may cover some quants only; fails closed."""
        try:
            probe = object.__new__(cls)
            probe._model_identifier = "mtp-head-probe"
            probe._read_gguf_metadata(gguf_path)
            return probe._architecture == "qwen4exp" and not probe._nextn_predict_layers
        except Exception as e:
            logger.debug("Nested MTP eligibility probe failed for %s: %s", gguf_path, e)
            return False

    def _reject_vulkan_diffusion_gpu_ids_before_teardown(
        self, gguf_path: str, model_identifier: str
    ) -> None:
        """Reject Vulkan + gpu_ids for diffusion GGUFs before Phase 1 teardown."""
        if self._gguf_path_is_diffusion(gguf_path, model_identifier):
            raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)

    @classmethod
    def _non_chat_gguf_refusal_for_path(
        cls, gguf_path: str, model_identifier: Optional[str]
    ) -> Optional[str]:
        """Header check on a probe object, not self (which would overwrite live metadata), run before Phase 1 teardown so a refusal costs no resident model."""
        probe = object.__new__(cls)
        probe._model_identifier = model_identifier
        probe._read_gguf_metadata(gguf_path)
        return probe._non_chat_gguf_refusal(gguf_path)

    @classmethod
    def _verified_cached_gguf(cls, intent, hf_repo, hf_variant) -> Optional[str]:
        """Return a carried file only if it still matches the load and active cache."""
        verified = getattr(intent, "verified_gguf", None)
        if not verified:
            return None
        try:
            repo, variant, path, sizes = verified
        except (TypeError, ValueError):
            return None
        if (repo or "").lower() != (hf_repo or "").lower():
            return None
        if (variant or "").lower() != (hf_variant or "").lower():
            return None
        if not path:
            return None
        try:
            if not Path(path).is_file():
                return None
            from utils.hf_cache_settings import get_hf_cache_paths
            hub_cache = Path(os.path.abspath(get_hf_cache_paths().hub_cache))
        except Exception:  # noqa: BLE001 -- an unreadable cache setting is not a reusable path
            return None
        # Cache settings can change while a load is in flight.
        try:
            if not Path(os.path.abspath(path)).is_relative_to(hub_cache):
                return None
        except (OSError, ValueError):
            return None
        # Recheck every shard's recorded size against this snapshot; both local, no Hub calls.
        try:
            if _cached_variant_sizes(_resolve_repo_id_casing(repo), variant, path) != sizes:
                return None
        except OSError:
            return None
        return path

    @classmethod
    def non_chat_gguf_refusal_for_intent(cls, intent) -> Optional[str]:
        """Asks before the route evicts a resident Images/Video pipeline; fails open like the in-
        load checks."""
        try:
            gguf_path = getattr(intent, "gguf_path", None)
            hf_repo = getattr(intent, "hf_repo", None)
            identifier = getattr(intent, "model_identifier", None)
            if gguf_path and not hf_repo and Path(gguf_path).is_file():
                return cls._non_chat_gguf_refusal_for_path(gguf_path, identifier)
            if hf_repo:
                hf_variant = getattr(intent, "hf_variant", None)
                verified = cls._verified_cached_gguf(intent, hf_repo, hf_variant)
                if verified:
                    verdict = cls._non_chat_gguf_refusal_for_path(verified, identifier)
                    cls._hand_over_route_verdict(hf_repo, hf_variant, verdict)
                    return verdict
                # Same offline window as the download, so Hub calls do not wait out retry backoff.
                with _hf_offline_if_unreachable():
                    verdict = cls._remote_non_chat_gguf_verdict(
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        hf_token = getattr(intent, "hf_token", None),
                        model_identifier = identifier,
                    )
                cls._hand_over_route_verdict(hf_repo, hf_variant, verdict)
                return verdict
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Non-chat GGUF preflight failed for the route: %s", e)
        return None

    def host_offload_warning_for_intent(self, intent) -> Optional[str]:
        """Advisory only, never a refusal: prices physical RAM and VRAM totals, not free memory; local paths only, never a download."""
        try:
            gguf_path = getattr(intent, "gguf_path", None)
            if not gguf_path or getattr(intent, "hf_repo", None):
                return None
            if not Path(gguf_path).is_file():
                return None
            binary = self._find_llama_server_binary()
            if not binary:
                return None
            # extras are appended after -m at launch and llama.cpp is last-wins, so read them
            argv = [
                binary,
                "-m",
                str(gguf_path),
                *(str(arg) for arg in getattr(intent, "extra_args", None) or ()),
            ]
            total_ram_mib = self._total_system_memory_mib()
            if total_ram_mib is None:
                return None
            probed = self._get_gpu_memory(binary)
            # an igpu and a MIG/vGPU line report total 0, leaving the ceiling unknown
            if any(total <= 0 for _idx, _free, total in probed):
                return None
            return self._launch_host_shortfall_message(
                argv,
                [(idx, total) for idx, _free, total in probed],
                avail_mib = total_ram_mib,
            )
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Host-RAM preflight failed for the route: %s", e)
        return None

    # Each ask may take several 15s Hub calls, so the route hands its verdict to the load.
    # Taken once by its own load; the TTL only covers a route ask no load came for.
    _HANDOFF_TTL_S = 120.0
    _route_verdict_handoff: Optional[
        tuple[tuple[Optional[str], Optional[str]], Optional[str], float]
    ] = None

    @classmethod
    def _take_route_verdict(cls, hf_repo, hf_variant):
        """The verdict the route just took for this key, or ``_MISS``. Consumed on read."""
        handoff = cls._route_verdict_handoff
        if handoff is None:
            return _MISS
        key, verdict, at = handoff
        if key != (hf_repo, hf_variant) or (time.monotonic() - at) >= cls._HANDOFF_TTL_S:
            return _MISS
        cls._route_verdict_handoff = None
        return verdict

    @classmethod
    def _hand_over_route_verdict(cls, hf_repo, hf_variant, verdict) -> None:
        cls._route_verdict_handoff = ((hf_repo, hf_variant), verdict, time.monotonic())

    @classmethod
    def _remote_non_chat_gguf_refusal(
        cls,
        *,
        hf_repo: str,
        hf_variant: Optional[str],
        hf_token: Optional[str],
        model_identifier: Optional[str],
    ) -> Optional[str]:
        """Decides a repo load from a 256 KiB header prefix before Phase 1 teardown, without a download; fails open, never stricter than the full-file check."""
        handed_over = cls._take_route_verdict(hf_repo, hf_variant)
        if handed_over is not _MISS:
            logger.debug("Reusing the header verdict the route already took for %s", hf_repo)
            return handed_over
        return cls._remote_non_chat_gguf_verdict(
            hf_repo = hf_repo,
            hf_variant = hf_variant,
            hf_token = hf_token,
            model_identifier = model_identifier,
        )

    @classmethod
    def _remote_non_chat_gguf_verdict(
        cls,
        *,
        hf_repo: str,
        hf_variant: Optional[str],
        hf_token: Optional[str],
        model_identifier: Optional[str],
    ) -> Optional[str]:
        """The uncached probe: one listing, one cache resolution, one range read."""
        try:
            from core.inference.diffusion_compat import (
                _read_gguf_header,
                _read_local_header,
            )
        except Exception as e:  # noqa: BLE001 -- an unavailable probe is not a verdict
            logger.debug("GGUF header probe unavailable: %s", e)
            return None
        try:
            gguf_filename, shards = _resolve_variant_gguf_files(hf_repo, hf_variant, hf_token)
            if not gguf_filename:
                return None
            # Resolve with the same precedence and verification as _download_gguf so the probe judges
            # the file the load will open. verify_sizes fails open offline.
            local = cached_gguf_for_load(hf_repo, hf_variant, verify_sizes = True, hf_token = hf_token)
            if local is None and not hf_variant:
                # No variant: mirror _download_gguf's other half. Never the bare local path, which would
                # bring back a candidate the verified lookup rejected.
                candidate = _cached_complete_candidate(hf_repo, gguf_filename, list(shards))
                if candidate is not None and _cached_candidate_matches_revision_size(
                    hf_repo, candidate, hf_token
                ):
                    local = candidate[0]
            prefix = (
                _read_local_header(local)
                if local
                else _read_gguf_header(hf_repo, gguf_filename, hf_token)
            )
            # Magic, version and the two counts: anything shorter is not a GGUF at all.
            if len(prefix) < 24:
                return None
            with tempfile.TemporaryDirectory(prefix = "unsloth-gguf-probe-") as probe_dir:
                # Named after the real file: a GGUF declaring no architecture is judged by its name, and a temp name would lose the page pointer.
                probe_path = os.path.join(probe_dir, os.path.basename(gguf_filename))
                with open(probe_path, "wb") as handle:
                    handle.write(prefix)
                return cls._non_chat_gguf_refusal_for_path(probe_path, model_identifier)
        except Exception as e:  # noqa: BLE001 -- a probe that failed is not a verdict
            logger.debug("Non-chat GGUF header probe failed for %s: %s", hf_repo, e)
            return None

    def _read_gguf_metadata(self, gguf_path: str) -> None:
        """Metadata lives in shard 1 of split GGUFs; per-model flags are reset first so none carry over."""
        # Reset so stale flags do not carry over when switching models.
        self._context_length = None
        self._chat_template = None
        self._empty_chat_render_refused = False
        self._markup_tokens = []
        self._markup_profile = None
        self._supports_reasoning = False
        self._reasoning_always_on = False
        self._reasoning_style = "enable_thinking"
        self._reasoning_effort_levels = []
        self._reasoning_default = True
        self._supports_preserve_thinking = False
        self._preserve_thinking_default = False
        self._supports_tools = False
        self._n_layers = None
        self._n_experts = None
        self._leading_dense_block_count = None
        self._n_kv_heads = None
        self._n_kv_heads_by_layer = None
        self._n_heads = None
        self._embedding_length = None
        self._pooling_type = None
        self._gguf_path = gguf_path
        self._feed_forward_length = None
        self._feed_forward_length_by_layer = None
        self._expert_used_count = None
        self._expert_feed_forward_length = None
        self._expert_shared_feed_forward_length = None
        self._expert_shared_count = None
        self._moe_latent_size = None
        self._embedding_length_per_layer_input = None
        self._vocab_size = None
        self._kv_key_length = None
        self._kv_value_length = None
        self._sliding_window = None
        self._sliding_window_pattern = None
        self._full_attention_interval = None
        self._kv_lora_rank = None
        self._key_length_mla = None
        self._kv_key_length_swa = None
        self._kv_value_length_swa = None
        self._ssm_inner_size = None
        self._ssm_state_size = None
        self._ssm_group_count = None
        self._ssm_conv_kernel = None
        self._kda_head_dim = None
        self._shared_kv_layers = None
        self._nextn_predict_layers = None
        self._architecture = None
        self._gguf_type = None
        self._is_diffusion = False
        self._gguf_header_parsed = False
        self._gguf_split_index = None

        try:
            canvas_seen = False
            WANTED = {
                "general.architecture",
                "general.type",
                "tokenizer.chat_template",
                # Vocab size = tokens array length (no vocab_size key in many GGUFs).
                "tokenizer.ggml.tokens",
                # Block-diffusion marker (DiffusionGemma); routes to the diffusion runner.
                "diffusion.canvas_length",
                # Source-repo hints for the SWA resolver's HF fallback.
                "general.source.huggingface.repository",
                "general.source.url",
                "general.source.repo_url",
                "general.base_model.0.repo_url",
                "general.base_model.0.organization",
                "general.base_model.0.name",
                "general.basename",
                "general.organization",
                "general.size_label",
                "general.finetune",
            }
            # Arch-specific keys added dynamically once we know the arch.
            arch_keys: dict[str, str] = {}  # gguf_key -> attribute name
            arch = None
            pooling_by_arch: dict[str, int] = {}

            nextn_by_arch: dict[str, int] = {}
            sliding_window_pattern_period: Optional[int] = None
            general: dict[str, str] = {}

            with open(gguf_path, "rb") as f:
                magic = struct.unpack("<I", f.read(4))[0]
                if magic != 0x46554747:  # b"GGUF" as little-endian u32
                    return
                _version = struct.unpack("<I", f.read(4))[0]
                _tensor_count, kv_count = struct.unpack("<QQ", f.read(16))

                # Set by the loop's `else` below: True only if no truncation `break` fired.
                kv_complete = False
                for _ in range(kv_count):
                    # Tolerate truncated input (partial HTTP range header): stop and let the resolver fallback run on what was parsed.
                    try:
                        key_len_bytes = f.read(8)
                        if len(key_len_bytes) < 8:
                            break
                        key_len = struct.unpack("<Q", key_len_bytes)[0]
                        key_bytes = f.read(key_len)
                        if len(key_bytes) < key_len:
                            break
                        key = key_bytes.decode("utf-8")
                        vtype_bytes = f.read(4)
                        if len(vtype_bytes) < 4:
                            break
                        vtype = struct.unpack("<I", vtype_bytes)[0]
                        # gguf-split puts all metadata in shard 1; later shards carry only split.*
                        # keys. Read the index,
                        # not presence, since shard 1 has these keys too.
                        if key == "split.no":
                            width = _GGUF_UINT_WIDTHS.get(vtype)
                            if width is not None:
                                raw = f.read(width)
                                if len(raw) < width:
                                    break
                                self._gguf_split_index = int.from_bytes(raw, "little")
                                continue
                    except (struct.error, UnicodeDecodeError):
                        break

                    try:
                        if (
                            key in WANTED
                            or key in arch_keys
                            or key.endswith(".pooling_type")
                            or key.endswith(".nextn_predict_layers")
                        ):
                            if vtype == 8:  # STRING
                                slen = struct.unpack("<Q", f.read(8))[0]
                                val_s = f.read(slen).decode("utf-8")
                                if key.startswith("general.") and key != "general.architecture":
                                    general[key] = val_s
                                if key == "general.type":
                                    self._gguf_type = val_s.strip().lower()
                                if key == "general.architecture":
                                    arch = val_s
                                    self._architecture = val_s
                                    arch_keys = {
                                        f"{arch}.context_length": "context_length",
                                        f"{arch}.block_count": "n_layers",
                                        f"{arch}.expert_count": "n_experts",
                                        f"{arch}.leading_dense_block_count": "leading_dense_block_count",
                                        f"{arch}.attention.head_count_kv": "n_kv_heads",
                                        f"{arch}.attention.head_count": "n_heads",
                                        f"{arch}.embedding_length": "embedding_length",
                                        f"{arch}.pooling_type": "pooling_type",
                                        f"{arch}.feed_forward_length": "feed_forward_length",
                                        f"{arch}.expert_used_count": "expert_used_count",
                                        f"{arch}.expert_feed_forward_length": "expert_feed_forward_length",
                                        f"{arch}.expert_shared_feed_forward_length": "expert_shared_feed_forward_length",
                                        f"{arch}.expert_shared_count": "expert_shared_count",
                                        f"{arch}.moe_latent_size": "moe_latent_size",
                                        f"{arch}.embedding_length_per_layer_input": "embedding_length_per_layer_input",
                                        f"{arch}.attention.key_length": "kv_key_length",
                                        f"{arch}.attention.value_length": "kv_value_length",
                                        f"{arch}.attention.sliding_window": "sliding_window",
                                        f"{arch}.attention.sliding_window_pattern": "sliding_window_pattern",
                                        f"{arch}.full_attention_interval": "full_attention_interval",
                                        f"{arch}.attention.kv_lora_rank": "kv_lora_rank",
                                        f"{arch}.attention.key_length_mla": "key_length_mla",
                                        f"{arch}.attention.key_length_swa": "kv_key_length_swa",
                                        f"{arch}.attention.value_length_swa": "kv_value_length_swa",
                                        f"{arch}.attention.shared_kv_layers": "shared_kv_layers",
                                        f"{arch}.ssm.inner_size": "ssm_inner_size",
                                        f"{arch}.ssm.state_size": "ssm_state_size",
                                        f"{arch}.ssm.group_count": "ssm_group_count",
                                        f"{arch}.ssm.conv_kernel": "ssm_conv_kernel",
                                        f"{arch}.kda.head_dim": "kda_head_dim",
                                        f"{arch}.nextn_predict_layers": "nextn_predict_layers",
                                    }
                                elif key == "tokenizer.chat_template":
                                    self._chat_template = val_s
                            elif vtype in (4, 10):  # UINT32 or UINT64
                                val_i = (
                                    struct.unpack("<I", f.read(4))[0]
                                    if vtype == 4
                                    else struct.unpack("<Q", f.read(8))[0]
                                )
                                if key == "diffusion.canvas_length":
                                    canvas_seen = True
                                if key.endswith(".pooling_type"):
                                    pooling_by_arch[key] = val_i

                                if key.endswith(".nextn_predict_layers"):
                                    nextn_by_arch[key] = val_i
                                attr = arch_keys.get(key)
                                if attr:
                                    if attr == "sliding_window_pattern":
                                        sliding_window_pattern_period = val_i
                                    else:
                                        setattr(self, f"_{attr}", val_i)
                            elif vtype == 9:  # ARRAY
                                atype = struct.unpack("<I", f.read(4))[0]
                                alen = struct.unpack("<Q", f.read(8))[0]
                                # Vocab size = token count; keep the length, not the strings.
                                if key == "tokenizer.ggml.tokens":
                                    self._vocab_size = int(alen)
                                val_a = self._gguf_read_array_value(f, atype, alen)
                                if key == "tokenizer.ggml.tokens" and val_a is not None:
                                    # Keep only delimiter-shaped entries, a few hundred of a six-figure vocab, not the whole vocabulary, enough to separate sentinels across model families.
                                    from core.inference.chat_template_helpers import (
                                        delimiter_shaped_tokens,
                                    )
                                    self._markup_tokens = delimiter_shaped_tokens(val_a)
                                attr = arch_keys.get(key)
                                if attr == "n_kv_heads" and val_a is not None:
                                    self._n_kv_heads_by_layer = [int(x) for x in val_a]
                                    if self._n_kv_heads is None and self._n_kv_heads_by_layer:
                                        self._n_kv_heads = max(self._n_kv_heads_by_layer)
                                elif attr == "sliding_window_pattern" and val_a is not None:
                                    self._sliding_window_pattern = [bool(x) for x in val_a]
                                    sliding_window_pattern_period = None
                                elif attr == "feed_forward_length" and val_a:
                                    self._feed_forward_length_by_layer = [int(x) for x in val_a]
                                    self._feed_forward_length = max(
                                        self._feed_forward_length_by_layer
                                    )
                                elif (
                                    attr in ("expert_used_count", "expert_feed_forward_length")
                                    and val_a
                                ):
                                    # Per-layer on Nemotron 3.5 Bolt; the widest layer sizes the graph.
                                    setattr(self, f"_{attr}", max(int(x) for x in val_a))
                            else:
                                self._gguf_skip_value(f, vtype)
                        else:
                            self._gguf_skip_value(f, vtype)
                    except (struct.error, UnicodeDecodeError, ValueError):
                        # Truncated input (e.g. HTTP byte-range header
                        # fetch), or a value type with no known size; break
                        # so the resolver fallback runs on what we have.
                        break
                else:
                    kv_complete = True

            # Bind buffered metadata after discovering the architecture namespace.
            if arch is not None:
                self._pooling_type = pooling_by_arch.get(f"{arch}.pooling_type", self._pooling_type)
                self._nextn_predict_layers = nextn_by_arch.get(
                    f"{arch}.nextn_predict_layers",
                    self._nextn_predict_layers,
                )

            # Decide diffusion routing before the SWA resolver: it can raise on an unknown arch and drop DiffusionGemma to plain llama-server.
            self._is_diffusion = bool(
                (arch and arch.lower().startswith("diffusion")) or canvas_seen
            )
            if self._is_diffusion:
                logger.info(
                    f"GGUF metadata: diffusion model detected (architecture={arch}); "
                    "will serve via the diffusion runner"
                )

            # Expand a scalar period straight from the GGUF first.
            if (
                self._sliding_window_pattern is None
                and sliding_window_pattern_period
                and self._n_layers
            ):
                self._sliding_window_pattern = [
                    (i + 1) % sliding_window_pattern_period != 0 for i in range(self._n_layers)
                ]

            # Diffusion models skip the resolver: no SWA pattern, and it can raise for them.
            if (
                self._sliding_window_pattern is None
                and self._sliding_window
                and self._n_layers
                and not self._is_diffusion
            ):
                hf_repo_candidates = (
                    general.get("general.source.huggingface.repository"),
                    _hf_repo_from_url(general.get("general.source.url")),
                    _hf_repo_from_url(general.get("general.source.repo_url")),
                    _hf_repo_from_url(general.get("general.base_model.0.repo_url")),
                    (
                        f"{general['general.base_model.0.organization']}/"
                        f"{general['general.base_model.0.name']}".replace(" ", "-")
                        if general.get("general.base_model.0.organization")
                        and general.get("general.base_model.0.name")
                        else None
                    ),
                    (
                        f"{general['general.organization']}/{general['general.basename']}".replace(
                            " ", "-"
                        )
                        if general.get("general.organization") and general.get("general.basename")
                        else None
                    ),
                )
                self._sliding_window_pattern = _resolve_swa_pattern(
                    arch,
                    self._n_layers,
                    hf_repo_candidates,
                )

            # Only a complete walk means _architecture None is 'declares none', not 'read stopped early'.
            self._gguf_header_parsed = kv_complete

            # Many call sites re-read the header per request; only log the first read of a file.
            first_read = _note_gguf_metadata_read(gguf_path)
            level = "info" if first_read else "debug"
            log_at = logger.info if first_read else logger.debug
            if self._context_length:
                log_at(f"GGUF metadata: context_length={self._context_length}")
            if self._chat_template:
                log_at(f"GGUF metadata: chat_template={len(self._chat_template)} chars")
                # Detect thinking/reasoning support from chat template.
                flags = detect_reasoning_flags(
                    self._chat_template,
                    self._model_identifier,
                    log_source = "GGUF metadata",
                    log_level = level,
                )
                self._supports_reasoning = flags["supports_reasoning"]
                self._reasoning_style = flags["reasoning_style"]
                self._reasoning_effort_levels = flags.get("reasoning_effort_levels", [])
                self._reasoning_always_on = flags["reasoning_always_on"]
                self._supports_preserve_thinking = flags["supports_preserve_thinking"]
                self._preserve_thinking_default = flags["preserve_thinking_default"]
                self._supports_tools = flags["supports_tools"]
        except Exception as e:
            logger.warning(f"Failed to read GGUF metadata: {e}")

    # ── Diffusion runner (DiffusionGemma) ──

    def _find_diffusion_assets(self) -> Optional[tuple[list, str, Optional[str]]]:
        """Shim: UNSLOTH_DG_SHIM (.py) first, else the installed unsloth_zoo shim; binary: DG_VISUAL_BIN first, else beside llama-server; None if neither."""
        import importlib.util

        # Visual-server binary: env override, else beside llama-server or in build/bin.
        visual_bin = os.environ.get("DG_VISUAL_BIN")
        if not visual_bin:
            name = "llama-diffusion-gemma-visual-server" + (".exe" if os.name == "nt" else "")
            # include_denied: a transiently locked llama-server still pins the install dir.
            base = self._find_llama_server_binary(include_denied = True)
            if base:
                base_dir = Path(base).parent
                for cand in (
                    base_dir / name,
                    base_dir / "build" / "bin" / name,
                    base_dir / "build" / "bin" / "Release" / name,
                ):
                    if cand.is_file():
                        visual_bin = str(cand)
                        break
        if not (visual_bin and Path(visual_bin).is_file()):
            return None

        # Shim: a file override (its dir goes on PYTHONPATH), else the zoo package via -m.
        shim_file = os.environ.get("UNSLOTH_DG_SHIM")
        if shim_file and Path(shim_file).is_file():
            return ([sys.executable, shim_file], visual_bin, str(Path(shim_file).parent))

        # find_spec on the top-level package does not run its __init__.
        try:
            spec = importlib.util.find_spec("unsloth_zoo")
        except Exception:
            spec = None
        if spec is not None and spec.submodule_search_locations:
            pkg_dir = Path(list(spec.submodule_search_locations)[0])
            if (pkg_dir / "diffusion_studio" / "shim.py").is_file():
                return (
                    [sys.executable, "-m", "unsloth_zoo.diffusion_studio.shim"],
                    visual_bin,
                    None,
                )

        return None

    def diffusion_split_supported(self) -> bool:
        """Whether a launch honours --ngl, mirroring the launch gate: a split the launcher drops must be guarded as GPU-resident; False if no shim or probe fails."""
        try:
            assets = self._find_diffusion_assets()
        except Exception:
            return False
        if assets is None:
            return False
        shim_cmd, _visual_bin, _extra_pythonpath = assets
        return _shim_supports_ngl(shim_cmd)

    @staticmethod
    def _mig_pinned_gpu_token(gpu: str) -> str:
        """On an R570+ MIG host, numeric ``gpu`` ids become the instance UUIDs; anything else as is."""
        if gpu and all(token.strip().isdigit() for token in gpu.split(",")):
            from utils.hardware import mig
            return mig.mask_for([int(token) for token in gpu.split(",")]) or gpu
        return gpu

    @staticmethod
    def _diffusion_gpu_arg(
        gpu_ids: Optional[List[int]],
        *,
        cpu_only: bool = False,
        force_cpu: bool = False,
    ) -> str:
        """Forward the first token of the parent mask, not a new ordinal; force_cpu outranks the picker, else the child holds a GPU while _gpu_offload_active is False."""
        if force_cpu:
            return ""
        if gpu_ids:
            return str(sorted(gpu_ids)[0])
        if cpu_only:
            return ""
        if "DG_GPU" in os.environ:
            return os.environ["DG_GPU"]
        parent_mask = os.environ.get("CUDA_VISIBLE_DEVICES")
        if parent_mask:
            first = next((token.strip() for token in parent_mask.split(",") if token.strip()), "")
            if first and first != "-1":
                return first
        return "0"

    @classmethod
    def _diffusion_fit_gpus(
        cls,
        model_size_bytes: int,
        gpu_ids: Optional[List[int]],
        gpu: str,
        visual_bin: Optional[str],
    ) -> Optional[List[int]]:
        """Physical GPUs to layer-split a diffusion GGUF over, or None to keep ``gpu`` alone.

        The visual server loads with llama.cpp's default layer split over every device in
        its mask, so widening the mask is the whole change. Only a GGUF that does not fit
        ``gpu`` moves: alone it overflows the card (a hang on Windows, where it spills into
        shared memory, #6347). The pool is the explicit pick, else every visible GPU; when
        no subset holds it, None leaves the single-device GPU / CPU layer fit in charge.
        Each device is charged the runner's own context on top of its weights, the same fit
        test as _diffusion_auto_ngl, so the two never disagree on whether ``gpu`` suffices.
        Shared with the training guard, so both budget the devices the runner will use. A
        runner that cannot split keeps today's single device."""
        if not gpu.isdigit() or not model_size_bytes or not _visual_server_splits_gpus(visual_bin):
            return None
        # Unpinned: only ids the child resolves the same way under PCI order (no inherited
        # mask to reinterpret, ids from nvidia-smi / NVML), as for llama-server auto fits.
        if not gpu_ids and ("DG_GPU" in os.environ or "CUDA_VISIBLE_DEVICES" in os.environ):
            return None
        try:
            binary = cls._find_llama_server_binary()
            # Vulkan ordinals are not the CUDA ids the runner's mask takes.
            if binary and cls._is_vulkan_backend(binary):
                return None
            memory = cls._get_gpu_memory(binary)
        except Exception as e:
            logger.debug(f"DiffusionGemma GPU fit skipped: {e}")
            return None
        if not gpu_ids and cls._GPU_IDS_ARE_PCI_INDICES is not True:
            return None
        pool = set(int(i) for i in gpu_ids) if gpu_ids else None
        gpus = [(idx, free) for idx, free, _ in memory if pool is None or idx in pool]
        total_by_idx = {idx: total for idx, _, total in memory}
        first = [(idx, free) for idx, free in gpus if idx == int(gpu)]
        if len(gpus) < 2 or not first:
            return None
        overhead = int(_DIFFUSION_RUNNER_OVERHEAD_MIB * 1024 * 1024)
        need = model_size_bytes + overhead
        if cls._select_gpus(need, first, total_by_idx = total_by_idx)[0]:
            return None
        picked, _ = cls._select_gpus(
            need, gpus, total_by_idx = total_by_idx, per_device_overhead_bytes = overhead
        )
        if not picked or sorted(picked) == [int(gpu)]:
            return None
        return sorted(picked)

    def _diffusion_fit_ngl(
        self, model_path: str, gpu: str, maxtok: int, *, pinned: bool
    ) -> Optional[int]:
        """Auto-mode ``--ngl`` for the runner's device ``gpu``, or None to keep its default."""
        # An NGL in the environment is the zoo runner's own override: leave it in charge.
        if not gpu.isdigit() or "NGL" in os.environ:
            return None
        try:
            binary = self._find_llama_server_binary()
            # Vulkan ordinals are not the CUDA ids the runner's mask takes.
            if binary and self._is_vulkan_backend(binary):
                return None
            rows = self._get_gpu_memory(binary)
            file_bytes = self._get_gguf_size_bytes(model_path)
            sysmem_fallback = self._sysmem_fallback_risk(binary)
        except Exception as e:
            logger.debug(f"DiffusionGemma layer fit skipped: {e}")
            return None
        row = next((r for r in rows if r[0] == int(gpu)), None)
        # Unpinned, the child's "0" is CUDA's fastest-first device unless PCI order is set,
        # not nvidia-smi's index 0: size against the roomiest card so no load that fits
        # today is cut down.
        if not pinned and len(rows) > 1 and os.environ.get("CUDA_DEVICE_ORDER") != "PCI_BUS_ID":
            row = max(
                rows,
                key = lambda r: _vram_usable_mib(
                    r[1], r[2], _active_vram_fraction(), sysmem_fallback = sysmem_fallback
                ),
            )
        if row is None:
            return None
        return _diffusion_auto_ngl(
            file_bytes,
            self._n_layers,
            self._n_heads,
            maxtok,
            row[1],
            row[2],
            sysmem_fallback = sysmem_fallback,
        )

    def _start_diffusion_server(
        self,
        *,
        model_path: str,
        gguf_path: Optional[str],
        hf_repo: Optional[str],
        hf_variant: Optional[str],
        model_identifier: str,
        n_ctx: int,
        extra_args: Optional[List[str]],
        gpu_ids: Optional[List[int]] = None,
        gpu_memory_mode: Literal["auto", "manual"] = "auto",
        gpu_layers: int = -1,
        cancelled: Optional[Callable[[], bool]] = None,
    ) -> bool:
        """Launch the OpenAI-compat diffusion shim (which drives the on-device
        visual decoder) and wait for health. Presents the same /v1 + /health
        interface as llama-server, so the rest of Unsloth is unchanged.

        Manual mode forwards gpu_layers as --ngl so a GGUF larger than VRAM can be
        split across GPU and RAM; auto keeps every layer on the GPU unless the GGUF
        cannot fit it."""
        assets = self._find_diffusion_assets()
        if assets is None:
            raise RuntimeError(
                "DiffusionGemma runner not found. Install unsloth_zoo (which ships "
                "unsloth_zoo.diffusion_studio.shim) or set UNSLOTH_DG_SHIM to a shim "
                "file, and provide the visual-server binary via DG_VISUAL_BIN or next "
                "to llama-server in the install tree."
            )
        shim_cmd, visual_bin, extra_pythonpath = assets
        self._diffusion_visual_bin = visual_bin

        self._kill_process()
        self._port = self._find_free_port()
        # 0 = the visual server auto-sizes context to VRAM, capped at the training context; an in-range n_ctx overrides.
        maxtok = n_ctx if (n_ctx and 0 < n_ctx <= 65536) else 0
        # Honour the manual split (unpinned, every layer goes to GPU and a GGUF over VRAM dies in cudaMalloc even at 0 layers); drop --ngl for an old shim.
        manual_ngl = _diffusion_manual_ngl(gpu_memory_mode, gpu_layers)
        if manual_ngl is not None and not _shim_supports_ngl(shim_cmd):
            # cpu_only is torch.cuda only, so on a paravirtual Mac only the split keeps weights off Metal;
            # refuse rather than serve possibly corrupt output.
            if manual_ngl == 0 and _metal_device_is_paravirtual():
                raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)
            logger.warning(
                "DiffusionGemma: ignoring the %d GPU-layer split; the installed "
                "unsloth_zoo shim has no --ngl. Upgrade unsloth_zoo to set the split.",
                manual_ngl,
            )
            manual_ngl = None
        # No visible CUDA GPU: keep the child CPU-masked with an empty --gpu, else the shim defaults to GPU 0.
        cpu_only = self._effective_gpu_count() == 0
        # Not derived from cpu_only (torch.cuda only): only a zero-layer split keeps weights off every backend, else a GPU is held while _gpu_offload_active is False.
        holds_no_gpu = manual_ngl == 0
        # Honor the GPU picker first: start from the lowest selected GPU. With no pick,
        # fall back to the CPU-only mask, else DG_GPU / 0. A manual split already says
        # where the layers go; otherwise a GGUF too big for that one device is
        # layer-split over the pool (#6347).
        gpu = self._diffusion_gpu_arg(gpu_ids, cpu_only = cpu_only, force_cpu = holds_no_gpu)
        # Auto: a GGUF too large for that device is layer-split over the GPU pool when the
        # runner supports it (#6347), else gets the GPU / CPU split that fits it (#6456).
        fit_ngl = None
        fit_gpus = None
        if manual_ngl is None:
            fit_ngl = self._diffusion_fit_ngl(model_path, gpu, maxtok, pinned = bool(gpu_ids))
            try:
                fit_gpus = self._diffusion_fit_gpus(
                    self._get_gguf_size_bytes(model_path),
                    gpu_ids,
                    gpu,
                    visual_bin,
                )
            except OSError as e:
                logger.debug(f"DiffusionGemma GPU fit skipped: {e}")
            # The probe runs under the load lock and can be slow: honour a Stop that came in.
            if cancelled is not None and cancelled():
                logger.info("Load cancelled before diffusion server start")
                self._health_wait_cancelled = True
                return False
            if fit_gpus:
                fit_ngl = None
                gpu = ",".join(str(i) for i in fit_gpus)
                logger.info(
                    f"DiffusionGemma does not fit one GPU; splitting layers over GPUs {gpu}"
                )
            if fit_ngl is not None and not _shim_supports_ngl(shim_cmd):
                logger.warning(
                    "DiffusionGemma does not fit GPU %s and the installed unsloth_zoo shim "
                    "has no --ngl to split it. Run 'unsloth studio update'.",
                    gpu,
                )
                fit_ngl = None
            # Pin the context the split was sized for. Left to auto-size, the runner's second
            # probe pass sizes against host RAM, which on Windows the driver backs with
            # shared memory instead of refusing.
            if fit_ngl is not None and not 0 < maxtok <= 8192:
                maxtok = _DIFFUSION_FIT_CTX
            # Nothing fits: run on the CPU like a manual zero-layer split, not on a
            # GPU context the card may not have room for.
            if fit_ngl == 0:
                holds_no_gpu = True
                gpu = self._diffusion_gpu_arg(gpu_ids, cpu_only = cpu_only, force_cpu = True)

        gpu = self._mig_pinned_gpu_token(gpu)
        cmd = list(shim_cmd) + [
            "--gguf",
            model_path,
            "--host",
            "127.0.0.1",
            "--port",
            str(self._port),
            "--gpu",
            gpu,
            "--maxtok",
            str(maxtok),
        ]
        if manual_ngl is not None:
            cmd += ["--ngl", str(manual_ngl)]
            # Block diffusion is compute-bound, so CPU layers are far slower; make that visible.
            logger.warning(
                "DiffusionGemma: %d GPU layers requested. Layers left on CPU are much "
                "slower for block diffusion than for a regular model; prefer a smaller "
                "quant over a large CPU split if throughput matters.",
                manual_ngl,
            )
        elif fit_ngl is not None:
            cmd += ["--ngl", str(fit_ngl)]
            logger.warning(
                "DiffusionGemma does not fit GPU %s: keeping %d of %s layers on it and the "
                "rest on CPU, which is much slower for block diffusion. A smaller quant "
                "that fits the GPU is faster.",
                gpu,
                fit_ngl,
                self._n_layers,
            )

        env = child_env_without_native_path_secret()
        # The shim imports unsloth_zoo, which refuses to load without UNSLOTH_IS_PRESENT; the shim never imports unsloth, so set it here.
        env["UNSLOTH_IS_PRESENT"] = "1"
        # unsloth_zoo import aborts with no accelerator; allow CPU since the shim does no torch GPU work.
        if cpu_only:
            env.setdefault("UNSLOTH_ALLOW_CPU", "1")
        env["DG_VISUAL_BIN"] = visual_bin
        env["DG_GPU"] = gpu
        if gpu_ids or fit_gpus:
            # The visual server remasks via CUDA_VISIBLE_DEVICES=<gpu>; pin PCI
            # order (as the llama-server path does) so the picked physical id maps
            # to the GPU the picker showed, not CUDA's default fastest-first order.
            env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
        # The file-override shim imports its sibling visual_engine.
        if extra_pythonpath:
            existing = env.get("PYTHONPATH")
            env["PYTHONPATH"] = (
                (extra_pythonpath + os.pathsep + existing) if existing else extra_pythonpath
            )

        logger.info(f"Starting DiffusionGemma runner: {' '.join(cmd)}")
        self._stdout_lines = []
        self._llama_log_fh = None
        self._llama_log_path = None
        try:
            log_dir = _swa_cache_path().parent / "logs" / "diffusion-server"
            log_dir.mkdir(parents = True, exist_ok = True)
            self._llama_log_path = log_dir / f"diffusion-{int(time.time())}-port-{self._port}.log"
            self._llama_log_fh = open(self._llama_log_path, "w", encoding = "utf-8", buffering = 1)
            # After the open, so the cap counts this file and can never delete it.
            prune_log_dir(log_dir, "diffusion-*.log", protect = self._llama_log_path)
            logger.info(f"diffusion runner stdout/stderr -> {self._llama_log_path}")
        except (OSError, UnicodeDecodeError) as e:
            logger.debug(f"Could not open diffusion runner log file: {e}")

        # Shim dies with this backend so a crash never orphans a GPU process; with no parent-death backstop everywhere, a runner started after the sweep outlives it.
        with self._spawn_lock:
            if self._spawn_is_stale():
                logger.info("app is shutting down; not starting the diffusion runner")
                self._close_attempt_log()
                self._health_wait_cancelled = True
                return False
            _spawned = subprocess.Popen(
                cmd,
                stdout = subprocess.PIPE,
                stderr = subprocess.STDOUT,
                text = True,
                encoding = "utf-8",
                errors = "replace",
                env = utf8_child_env(env),
                # Not start_new_session: the desktop signals the process group, force-kills after 5 s; a separate session leaves the shim and visual server holding the GPU.
                **_windows_hidden_subprocess_kwargs(),
                **_child_popen_kwargs(),
            )
            self._process = _spawned
            _invalidate_gpu_memory("llama-server spawned")
            # macOS has no parent-death signal, so only this record reaps the runner. Under the lock so
            # adoption after the sweep cannot re-add a forgotten pid.
            try:
                from utils.process_lifetime import adopt_pid
                adopt_pid(_spawned.pid)
            except Exception as e:
                logger.debug(f"Could not track diffusion runner for lifetime sweep: {e}")
        # Post-adoption recheck as for llama-server: teardown never marks a helper-owned backend, so a late latch would leave the runner alive through the health wait.
        if self._spawn_is_stale():
            logger.info("shutdown began during the spawn; killing the new diffusion runner")
            self._kill_process()
            self._close_attempt_log()
            self._health_wait_cancelled = True
            return False
        self._stdout_thread = threading.Thread(
            target = self._drain_stdout, daemon = True, name = "diffusion-stdout"
        )
        self._stdout_thread.start()

        # Publish state before the health wait (mirrors the llama-server path).
        self._gguf_path = model_path
        self._gguf_load_identity = self._gguf_load_source_identity(model_path)
        self._hf_repo = hf_repo
        self._is_vision = False
        # A diffusion model must not report the last model's vision state.
        self._disable_vision = False
        self._vision_disabled_by_user = False
        self._is_audio = False  # clear any prior TTS/audio model's routing flag
        self._model_identifier = model_identifier
        self._cache_type_kv = None
        self._reasoning_budget = -1
        self._reasoning_budget_message = ""
        self._requested_reasoning_budget = -1
        self._requested_reasoning_budget_message = ""
        self._swa_full = False
        self._kv_cache_unified = False
        self._memory_state = None
        self._memory_direct_io = None
        self._memory_dio_applicable = False
        self._memory_dio_flags = []
        self._memory_dio_user_tokens = []
        self._memory_policy_active = False
        self._memory_policy_extras_touched = False
        self._memory_mlock_applicable = True
        self._fit_load_mode_flags = []
        self._lazy_mode_flags = []
        self._apple_lazy_flags = []
        self._mixed_split_flags = []
        self._memory_pending_launch = None
        self._n_ubatch = self._DEFAULT_N_UBATCH
        self._requested_n_batch = None
        self._requested_n_ubatch = None
        # The runner passes none of these, so a previous GGUF's values must not be reported.
        self._requested_load_mode = None
        self._requested_spec_draft_cache_type = None
        self._requested_ctx_checkpoints = None
        self._requested_cache_ram = None
        self._idle_slot_clearing_active = False
        self._flash_attn_enabled = True
        self._effective_cache_types = ("f16", "f16")
        self._requested_cache_types = ("f16", "f16")
        self._kv_cache_context_total = None
        # False means confirmed to hold no VRAM and makes the coordinator skip the unload, so claim it only for a zero-layer split.
        self._gpu_offload_active = not holds_no_gpu
        # A runner crash must neither replay the replaced chat load nor meet its Metal OOM latch.
        self._last_load_intent = None
        self._mtp_runtime_fallback_active = False
        self._metal_oom_strikes = None
        self._metal_oom_terminal_key = None
        # Record the applied split and reset the other knobs so status and reload dedup agree.
        self._gpu_memory_mode = gpu_memory_mode if manual_ngl is not None else "auto"
        self._gpu_layers = manual_ngl if manual_ngl is not None else -1
        # What was asked for, not what was applied (_gpu_layers): dedup guards must compare like with like, or the same request reloads on every /load.
        self._diffusion_requested_ngl = _diffusion_manual_ngl(gpu_memory_mode, gpu_layers)
        self._n_cpu_moe = 0
        self._tensor_split = None
        self._auto_tensor_split = None
        self._auto_tensor_split_emitted = None
        self._spill_plan_flags = []
        # Diffusion is never tensor-parallel: clear prior TP state, since phase 1 only kills the process; else /status misreports TP and re-Apply reloads.
        self._tensor_parallel = False
        # A diffusion runner holds VRAM; a leftover arch-gate flag would claim it does not, letting the arbiter run a competing workload into it.
        self._arch_gate_forced_cpu = False
        # Record the devices the runner got: the lowest selected GPU, or the split above.
        # Unused members of a pick that fits one device are dropped, or /status misreports
        # placement and the dedup reloads. Clears any explicit pin from a prior chat load.
        # A zero-layer split on virtualised Metal masks the child's devices outright, so
        # it pins nothing: record no effective pin, or /status names a device the runner
        # never used and clearing that pick reloads the same CPU runner.
        _pv_diffusion_cpu = manual_ngl == 0 and _metal_device_is_paravirtual()
        _pinned = (fit_gpus or [sorted(gpu_ids)[0]]) if gpu_ids else None
        self._gpu_ids = _pinned if not _pv_diffusion_cpu else None
        # The frontend prefers requested_gpu_ids when hydrating the picker.
        self._requested_gpu_ids = (
            sorted(int(i) for i in gpu_ids) if gpu_ids and fit_gpus else _pinned
        )
        if hf_variant:
            self._hf_variant = hf_variant
        elif gguf_path:
            try:
                from utils.models.model_config import _extract_quant_label
                self._hf_variant = _extract_quant_label(gguf_path)
            except Exception:
                self._hf_variant = None
        else:
            self._hf_variant = None
        # Provisional until the server reports the budget it resolved (auto-size picks it from VRAM).
        self._effective_context_length = maxtok or self._context_length
        self._max_context_length = self._context_length or maxtok or None
        self._vram_fit_context_length = None

        healthy = self._wait_for_health(timeout = self._HEALTH_STALL_TIMEOUT_S, cancelled = cancelled)
        if healthy:
            if not self._publish_healthy():
                # A teardown between the probe and this commit is already killing the runner; publishing would advertise a dead server.
                self._kill_process()
                return False
            self._gpu_offload_active = not holds_no_gpu
            if extra_args is not None:
                self._extra_args = list(extra_args)
                # No spec block to drop, so launched equals requested; rebind so a record from a prior GGUF load cannot outlive it.
                self._requested_extra_args = list(extra_args)
                self._extra_args_source = (model_identifier, hf_variant)
            # The visual server logs MAXTOK=<N>, the context it resolved; read it back for the UI.
            chosen = maxtok
            try:
                for _ln in reversed(self._stdout_lines):
                    _m = re.search(r"MAXTOK=(\d+)", _ln)
                    if _m:
                        chosen = int(_m.group(1))
                        break
            except Exception:
                pass
            if chosen and chosen > 0:
                self._effective_context_length = chosen
                self._max_context_length = chosen
            self._requested_n_ctx = int(n_ctx)
            if cancelled is not None and cancelled():
                logger.info("DiffusionGemma start cancelled after it became healthy")
                self._healthy = False
                self._kill_process()
                return False
        else:
            self._healthy = False
            if getattr(self, "_health_wait_cancelled", False):
                # An automatic switch cancels without unloading, so nothing else reaps the shim and visual server, which would keep loading and holding memory.
                logger.info("DiffusionGemma start cancelled; stopping the runner")
                self._kill_process()
            else:
                logger.error("DiffusionGemma runner failed to become healthy")
        return healthy

    # ── HF download (no lock held) ───────────────────────────────

    def _download_gguf(
        self,
        *,
        hf_repo: str,
        hf_variant: Optional[str] = None,
        hf_token: Optional[str] = None,
        force: bool = False,
        allow_smaller_fallback: bool = True,
        cancel_event: Optional[threading.Event] = None,
    ) -> str:
        """Runs without self._lock so unload_model can cancel between shards; force re-fetches a cached blob; allow_smaller_fallback=False raises on low disk."""
        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            raise GgufDownloadCancelled("Cancelled")
        from utils.hf_cache_settings import get_hf_cache_paths

        download_cache_dir = str(get_hf_cache_paths().hub_cache)
        try:
            import huggingface_hub  # noqa: F401 -- presence check only
        except ImportError:
            raise RuntimeError(
                "huggingface_hub is required for HF model loading. "
                "Install it with: pip install huggingface_hub"
            )

        resolved_hf_repo = _resolve_repo_id_casing(hf_repo)
        if resolved_hf_repo != hf_repo:
            logger.info(
                "Using cached repo_id casing '%s' for requested '%s'",
                resolved_hf_repo,
                hf_repo,
            )
            hf_repo = resolved_hf_repo

        # Resolve the filename from the variant (shared with the pre-teardown header probe)
        gguf_filename, gguf_extra_shards = _resolve_variant_gguf_files(
            hf_repo, hf_variant, hf_token
        )

        # Prefer the existing model. Updates use force=True to fetch a new revision.
        if not force:
            if hf_variant:
                # By variant, so a newer revision's filename does not hide a complete older copy; size-check against that older snapshot's own revision if its metadata remains.
                cached_main = cached_gguf_for_load(
                    hf_repo,
                    hf_variant,
                    verify_sizes = True,
                    hf_token = hf_token,
                )
            else:
                candidate = _cached_complete_candidate(hf_repo, gguf_filename, gguf_extra_shards)
                cached_main = (
                    candidate[0]
                    if candidate is not None
                    and _cached_candidate_matches_revision_size(hf_repo, candidate, hf_token)
                    else None
                )
            if cached_main is not None:
                logger.info(f"Reusing cached GGUF: {cached_main}")
                return cached_main

        # Check disk space; fall back to a smaller variant if needed
        all_gguf_files = [gguf_filename] + gguf_extra_shards
        try:
            from huggingface_hub import get_paths_info, try_to_load_from_cache

            path_infos = list(
                call_hub_with_anonymous_retry(get_paths_info, hf_token, hf_repo, all_gguf_files)
            )
            total_bytes = sum((p.size or 0) for p in path_infos)

            # Preflight only against bytes still to download, or cached large models fail on low disk.
            already_cached_bytes = 0
            # Count only files that can resume this download.
            offline = _hf_env_offline()
            # Offline split sets are reusable only when every shard shares a snapshot.
            split_needs_refetch = bool(offline and not force and gguf_extra_shards)
            if not force and not split_needs_refetch:
                for p in path_infos:
                    if not p.size:
                        continue
                    try:
                        cached_path = try_to_load_from_cache(
                            hf_repo,
                            p.path,
                            cache_dir = download_cache_dir,
                        )
                    except Exception:
                        cached_path = None
                    if (
                        not (isinstance(cached_path, str) and os.path.exists(cached_path))
                        and offline
                    ):
                        cached_path = _cached_hf_snapshot_file(
                            hf_repo,
                            p.path,
                            expected_size = p.size,
                            cache_dir = download_cache_dir,
                        )
                    if isinstance(cached_path, str) and os.path.exists(cached_path):
                        try:
                            on_disk = os.path.getsize(cached_path)
                        except OSError:
                            on_disk = 0
                        # Satisfied only when the full blob is present.
                        if on_disk >= p.size:
                            already_cached_bytes += p.size

            total_download_bytes = max(0, total_bytes - already_cached_bytes)

            if total_download_bytes > 0:
                Path(download_cache_dir).mkdir(parents = True, exist_ok = True)
                free_bytes = shutil.disk_usage(download_cache_dir).free

                total_gb = total_download_bytes / 1e9
                free_gb = free_bytes / 1e9
                cached_gb = already_cached_bytes / 1e9

                logger.info(
                    f"GGUF download: {total_gb:.1f} GB needed "
                    f"({cached_gb:.1f} GB already cached), "
                    f"{free_gb:.1f} GB free on disk"
                )

                if total_download_bytes > free_bytes:
                    if not allow_smaller_fallback:
                        # Update path: never silently switch to a smaller quant.
                        raise RuntimeError(
                            f"Not enough disk space to download {gguf_filename}. "
                            f"Only {free_gb:.1f} GB free in {download_cache_dir}"
                        )
                    smaller = self._find_fitting_variant(
                        hf_repo,
                        free_bytes,
                        total_bytes,
                        hf_token,
                        requested_file = gguf_filename,
                    )
                    if smaller:
                        fallback_file, fallback_size, fallback_shards = smaller
                        from utils.models.model_config import _gguf_variant_key

                        fallback_variant = _gguf_variant_key(fallback_file)
                        notice = (
                            f"Not enough disk space to download {hf_variant} "
                            f"({total_gb:.1f} GB needed, {free_gb:.1f} GB free), so "
                            f"{fallback_variant} ({fallback_size / 1e9:.1f} GB) "
                            "was loaded instead."
                        )
                        logger.warning(notice)
                        self._pending_variant_fallback = (fallback_variant, notice)
                        gguf_filename = fallback_file
                        gguf_extra_shards = fallback_shards

                        # The fallback is a new load target: apply the same any-revision cache reuse before fetching.
                        fallback_candidate = _cached_complete_candidate(
                            hf_repo, gguf_filename, gguf_extra_shards
                        )
                        if fallback_candidate is not None and (
                            _cached_candidate_matches_revision_size(
                                hf_repo, fallback_candidate, hf_token
                            )
                        ):
                            logger.info(f"Reusing cached fallback GGUF: {fallback_candidate[0]}")
                            return fallback_candidate[0]
                    else:
                        raise RuntimeError(
                            f"Not enough disk space to download any variant. "
                            f"Only {free_gb:.1f} GB free in {download_cache_dir}"
                        )
        except RuntimeError:
            raise
        except Exception as e:
            logger.warning(f"Could not check disk space: {e}")

        gguf_label = f"{hf_repo}/{gguf_filename}" + (
            f" (+{len(gguf_extra_shards)} shards)" if gguf_extra_shards else ""
        )
        logger.info(f"Resolving GGUF: {gguf_label}")
        try:
            if cancel_event.is_set():
                raise GgufDownloadCancelled("Cancelled")
            dl_start = time.monotonic()
            # Xet primary, HTTP fallback on stall; per-file so finished shards stay cached.
            local_path = hf_hub_download_with_xet_fallback(
                hf_repo,
                gguf_filename,
                hf_token,
                cancel_event = cancel_event,
                on_status = lambda m: logger.info(m),
                force_download = force,
                cache_dir = download_cache_dir,
            )
            for shard in gguf_extra_shards:
                if cancel_event.is_set():
                    raise GgufDownloadCancelled("Cancelled")
                logger.info(f"Resolving GGUF shard: {shard}")
                hf_hub_download_with_xet_fallback(
                    hf_repo,
                    shard,
                    hf_token,
                    cancel_event = cancel_event,
                    force_download = force,
                    cache_dir = download_cache_dir,
                )
        except Exception as e:
            if isinstance(e, GgufDownloadCancelled):
                raise
            if isinstance(e, RuntimeError) and "Cancelled" in str(e):
                raise GgufDownloadCancelled(str(e)) from e
            raise RuntimeError(
                f"Failed to download GGUF file '{gguf_filename}' from {hf_repo}: {e}"
                # Only when a token went out: an anonymous 401 is a private or missing repo.
                f"{hf_token_rejected_hint(e) if is_rejected_credential_error(e, hf_token) else ''}"
            )

        dl_elapsed = time.monotonic() - dl_start
        if dl_elapsed < 2.0:
            logger.info(f"GGUF resolved from cache: {local_path}")
        else:
            logger.info(f"GGUF downloaded in {dl_elapsed:.1f}s: {local_path}")
        return local_path

    def _download_companion_gguf(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str],
        pick: Callable[[list[str]], Optional[str]],
        label: str,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
        reuse_snapshot_sibling: bool = True,
        outcome: Optional[dict] = None,
        on_transient_failure: Optional[Callable[[], None]] = None,
    ) -> Optional[str]:
        """Split companion fetched whole (llama-server needs siblings); on_transient_failure only on retryable drops; reuse_snapshot_sibling=False skips snapshot reuse."""
        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            return None

        # Kept so shard siblings resolve from the same names the pick chose among.
        available: list[str] = []

        def _pick_from(names: list[str]) -> Optional[str]:
            nonlocal available
            available = list(names)
            return pick(available)

        # Keep companion files in the main GGUF's snapshot.
        if near_path and reuse_snapshot_sibling:
            cached = _companion_snapshot_sibling(near_path, pick)
            if cached:
                logger.info("Reusing cached %s: %s", label, cached)
                return cached

        from utils.hf_cache_settings import get_hf_cache_paths

        companion_cache_dir = _hub_cache_dir_for_snapshot_path(near_path) or str(
            get_hf_cache_paths().hub_cache
        )

        if _hub_download_in_flight(hf_repo):
            logger.info("Skipping %s download while a hub download is active", label)
            return None

        target: Optional[str] = None
        # A listing that never completed says nothing about the repo's contents.
        listing_answered = False
        # Retryable failure; a permanent error also leaves the listing unanswered.
        listing_failed = False
        from huggingface_hub import list_repo_files

        # Retry transient listing errors only; offline raises at once and falls through to cache.
        for attempt in range(3):
            if cancel_event.is_set():
                return None
            try:
                target = _pick_from(
                    call_hub_with_anonymous_retry(list_repo_files, hf_token, hf_repo)
                )
                listing_answered = True
                listing_failed = False
                break
            except Exception as e:
                if type(e).__name__ in _PERMANENT_HUB_ERRORS:
                    logger.debug(f"Could not list repo files for {label}: {e}")
                    break
                listing_failed = True
                logger.debug(
                    f"Could not list repo files for {label} (attempt {attempt + 1}/3): {e}"
                )
                if attempt < 2:
                    cancel_event.wait(2**attempt)

        # Captured before the cache fallback can name a file the live revision dropped.
        listed_live = (target is not None) if listing_answered else None

        if target is None:
            try:
                from utils.models.model_config import _iter_hf_cache_snapshots
                for snap in _iter_hf_cache_snapshots(hf_repo, companion_cache_dir):
                    rel_files = _gguf_snapshot_files(snap)
                    target = _pick_from(rel_files)
                    if target is not None:
                        logger.info("Resolved %s %s from local HF cache", label, target)
                        break
            except Exception as e:
                logger.debug(f"Offline cache lookup for {label} failed: {e}")

        # Record absence only when really answered, so an unreachable Hub is retried on next Apply.
        if (
            outcome is not None
            and not cancel_event.is_set()
            and (listing_answered or target is not None)
        ):
            outcome["listed"] = target is not None
        if outcome is not None and not cancel_event.is_set() and listed_live is not None:
            outcome["listed_live"] = listed_live
        if target is None or cancel_event.is_set():
            # The listing is the only step that can fail this far in.
            if target is None and listing_failed and not cancel_event.is_set():
                self._report_transient_companion_failure(on_transient_failure, label)
            return None

        # Offline: resolve_cached_repo_id_case can return a partial casing, so hf_hub_download would silently drop the companion; scan every case variant.
        if _hf_env_offline():
            cached = _cached_hf_snapshot_file(
                hf_repo,
                target,
                cache_dir = companion_cache_dir,
            )
            if cached:
                from utils.models.model_config import _drafter_split_is_complete

                # Half a split companion is no companion, and offline nothing completes it: answer None rather than a drafter llama-server cannot open.
                if _drafter_split_is_complete(Path(cached)):
                    logger.info("Resolved %s from local HF cache: %s", label, cached)
                    return cached

        # Same shard helper as the main download, so the two agree on set membership.
        extra_shards = _gguf_extra_shards(available, target)
        # The filename carries the set size, so a short listing is answerable before download.
        _shard_total = _SHARD_FULL_RE.match(target)
        if _shard_total and len(extra_shards) + 1 != int(_shard_total.group(3)):
            logger.info(
                "Skipping %s: %s lists %d of %s shards.",
                label,
                hf_repo,
                len(extra_shards) + 1,
                _shard_total.group(3),
            )
            # Settled: the listing answered, so record absence rather than reloading every Apply.
            if outcome is not None:
                outcome["listed"] = False
                outcome["listed_live"] = False
            return None
        try:
            logger.info(f"Downloading {label}: {hf_repo}/{target}")
            # Same policy; companions are best-effort (caller below swallows failures to None).
            local_path = hf_hub_download_with_xet_fallback(
                hf_repo,
                target,
                hf_token,
                cancel_event = cancel_event,
                cache_dir = companion_cache_dir,
            )
            for shard in extra_shards:
                if cancel_event.is_set():
                    return None
                logger.info(f"Downloading {label} shard: {hf_repo}/{shard}")
                hf_hub_download_with_xet_fallback(
                    hf_repo,
                    shard,
                    hf_token,
                    cancel_event = cancel_event,
                    cache_dir = companion_cache_dir,
                )
            return local_path
        except Exception as e:
            logger.warning(f"Could not download {label}: {e}")
            # Listed but the fetch dropped: retryable unless permanent or cancelled.
            if (
                not cancel_event.is_set()
                and type(e).__name__ not in _PERMANENT_HUB_ERRORS
                and getattr(e, "errno", None) not in _UNRECOVERABLE_LOCAL_ERRNOS
                and not _hf_env_offline()
            ):
                self._report_transient_companion_failure(on_transient_failure, label)
            return None

    @staticmethod
    def _report_transient_companion_failure(
        on_transient_failure: Optional[Callable[[], None]], label: str
    ) -> None:
        """Tells the caller a companion was lost to a retryable failure; best-effort, so a callback that raises must not fail the load."""
        if on_transient_failure is None:
            return
        try:
            on_transient_failure()
        except Exception as exc:
            logger.debug("Could not record the transient %s failure: %s", label, exc)

    def _download_mmproj(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
    ) -> Optional[str]:
        """Downloads the mmproj, preferring mmproj-F16.gguf; falls back to a hand-added projector beside the cached weight only if the repo publishes none; else None."""

        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            return None

        from utils.models.model_config import mmproj_f16_unsafe, mmproj_precision

        names = (hf_repo, near_path)
        pick = _mmproj_picker(hf_repo, near_path)
        f16_unsafe = any(mmproj_f16_unsafe(n) for n in names)
        if f16_unsafe and near_path:
            # Only a cached MiMo-VL F16 projector is broken; a cached BF16 / F32 one is reused as usual.
            cached = _companion_snapshot_sibling(near_path, pick)
            with contextlib.suppress(OSError):
                if cached and mmproj_precision(cached) != "f16" and Path(cached).stat().st_size > 0:
                    logger.info("Reusing cached mmproj: %s", cached)
                    return cached
        outcome: dict = {}
        resolved = self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = pick,
            label = "mmproj",
            cancel_event = cancel_event,
            near_path = near_path,
            reuse_snapshot_sibling = not f16_unsafe,
            outcome = outcome,
        )
        if resolved is not None:
            # An interrupted zero-byte copy must not shadow a working projector.
            try:
                if Path(resolved).stat().st_size > 0:
                    return resolved
            except OSError:
                return resolved
            logger.info("Ignoring an empty mmproj resolved for %s: %s", hf_repo, resolved)
        elif outcome.get("listed_live") is True:
            # The fetch dropped: retry next Apply rather than launch a hand-added file. Offline falls back.
            return None
        if not near_path or cancel_event.is_set():
            return None
        from utils.models.model_config import _hf_cached_local_mmproj

        cached = _hf_cached_local_mmproj(near_path)
        if cached is not None:
            logger.info("Reusing hand-added mmproj from the HF cache: %s", cached)
        return cached

    def _cached_repo_mtp_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
        allow_nested: bool = True,
    ) -> Optional[str]:
        """Cached drafter for offline reuse, ranked with _pick_mtp keys so offline and online pick one file; allow_nested=False drops the MTP/ half."""
        try:
            from utils.models.drafters.preference import mtp_preference_key
            from utils.models.model_config import (
                _drafter_split_is_complete,
                _iter_hf_cache_snapshots,
            )

            roots: list[Path] = []
            subdirs: list[Path] = []
            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            for snap in snapshots:  # newest first
                snap_roots: list[str] = []
                snap_subdirs: list[str] = []
                for f in _gguf_snapshot_files(snap):
                    # MTP only: a DSpark drafter needs --spec-type draft-dspark. Nested files need a drafter name, or an mmproj under MTP/ would go to --model-draft.
                    if "/" not in f:
                        if _is_mtp_only_drafter_path(f):
                            snap_roots.append(f)
                    elif _is_mtp_only_drafter_path(f) and _is_published_mtp_drafter_name(f):
                        snap_subdirs.append(f)
                # Root lexical, nested by preference: the tiers as _pick_mtp orders them.
                roots.extend(snap / f for f in sorted(snap_roots))
                subdirs.extend(snap / f for f in sorted(snap_subdirs, key = mtp_preference_key))
            # Newest snapshot first, root before MTP/, so a newer GGUF pairs with the newest drafter.
            for cand in roots + subdirs if allow_nested else roots:
                # Half a split set is not a drafter; offline there is no fetch to complete it.
                if cand.is_file() and _drafter_split_is_complete(cand):
                    return str(cand)
        except Exception as e:
            logger.debug("Cached MTP drafter lookup failed for %s: %s", hf_repo, e)
        return None

    def _download_mtp(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
        allow_nested: bool = True,
    ) -> Optional[str]:
        """Download MTP drafter: root mtp-*.gguf mirror first, MTP/ fallback only if allow_nested (qwen4exp only); None when the repo bakes the head into the main GGUF."""

        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            return None

        if near_path:
            from utils.models.gguf_metadata import read_gguf_nextn_predict_layers
            if (read_gguf_nextn_predict_layers(near_path) or 0) > 0:
                logger.info("Main GGUF contains an embedded MTP head; skipping separate drafter.")
                return None

        pick = _pick_mtp if allow_nested else _pick_mtp_root_only

        borrowed_cached: Optional[str] = None
        if near_path:
            cached = _companion_snapshot_sibling(near_path, pick)
            if cached and _mtp_head_borrows(cached) and not _hf_env_offline():
                # --fit cannot measure a borrowing head, so the MTP context would OOM; hf_hub_download reuses this file if nothing better is found.
                logger.info(
                    "Cached MTP drafter borrows the target's embeddings; checking the "
                    "repo for a self-contained head: %s",
                    cached,
                )
                borrowed_cached = cached
            elif cached:
                logger.info("Reusing cached MTP drafter: %s", cached)
                return cached

        # Offline, reuse any cached drafter. Online, the download refetches a changed file, so skip
        # the probe rather than pair new weights with a stale draft.
        if _hf_env_offline():
            cached = self._cached_repo_mtp_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
                allow_nested = allow_nested,
            )
            if cached:
                logger.info(f"Reusing cached MTP drafter (offline): {cached}")
                return cached

        fetched = self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = pick,
            label = "MTP drafter",
            cancel_event = cancel_event,
            near_path = near_path,
            reuse_snapshot_sibling = borrowed_cached is None,
        )
        if fetched is None and borrowed_cached is not None:
            # An unmeasurable drafter still drafts; no drafter at all is the bigger loss.
            logger.info("Keeping the cached borrowing MTP drafter: %s", borrowed_cached)
            return borrowed_cached
        return fetched

    def _cached_repo_dspark_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
    ) -> Optional[str]:
        """The preferred already-cached DSpark sidecar for a repo, Q8_0 first
        (dspark_preference_key), so an offline reuse picks the same file the
        online download would have fetched."""
        try:
            from utils.models.model_config import (
                _iter_hf_cache_snapshots,
                dspark_preference_key,
            )

            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            candidates: list[Path] = []
            for snap in snapshots:
                candidates.extend(
                    snap / name
                    for name in _gguf_snapshot_files(snap)
                    if _is_dspark_drafter_path(name)
                )
            for candidate in sorted(candidates, key = lambda p: dspark_preference_key(p.name)):
                if candidate.is_file():
                    return str(candidate)
        except Exception as exc:
            logger.debug("Cached DSpark drafter lookup failed for %s: %s", hf_repo, exc)
        return None

    def _download_dspark(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
        binary: Optional[str] = None,
        caps_probe: Optional[Callable[[Optional[str]], dict]] = None,
    ) -> Optional[str]:
        """Fetches the DSpark sidecar, skipped unless supports_dspark; a raised probe still fetches, caps_probe latches the guess, else a lapsed retry looks conclusive."""
        cancel_event = (
            cancel_event
            if cancel_event is not None
            else getattr(self, "_cancel_event", threading.Event())
        )
        if cancel_event.is_set():
            return None
        if caps_probe is None:
            caps_probe = self.probe_server_capabilities

        cached = _companion_snapshot_sibling(near_path, _pick_dspark) if near_path else None
        if not cached and _hf_env_offline():
            cached = self._cached_repo_dspark_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
            )
        try:
            if not caps_probe(binary).get("supports_dspark"):
                logger.warning(
                    "Skipping the DSpark sidecar download: llama-server has no usable "
                    "--spec-type draft-dspark, so this load falls back to no speculative "
                    "decoding. Run `unsloth studio update`, then reload."
                )
                # Still report a sidecar on disk, else the reuse check reloads each Apply; _build_speculative_flags re-checks support and still falls back.
                return cached
        except Exception as exc:
            logger.debug("DSpark capability probe failed before the sidecar fetch: %s", exc)

        if cached:
            logger.info("Reusing cached DSpark drafter: %s", cached)
            return cached
        outcome: dict = {}
        found = self._download_companion_gguf(
            hf_repo = hf_repo,
            hf_token = hf_token,
            pick = _pick_dspark,
            label = "DSpark drafter",
            cancel_event = cancel_event,
            near_path = near_path,
            outcome = outcome,
        )
        # Tells a repo with no sidecar apart from a fetch that may yet succeed.
        self._dspark_sidecar_absent = outcome.get("listed") is False
        return found

    def _cached_repo_dflash_drafter(
        self,
        hf_repo: str,
        *,
        cache_dir: Optional[str] = None,
        near_path: Optional[str] = None,
    ) -> Optional[str]:
        """Preferred cached DFlash sidecar, Q8_0 first, ranked against near_path's weight so a multi-family repo does not hand model B model A's sidecar."""
        try:
            from utils.models.drafters import (
                _drafter_split_is_complete,
                dflash_repo_preference_key,
                is_dflash_architecture,
            )
            from utils.models.model_config import _iter_hf_cache_snapshots

            snapshots = (
                _iter_hf_cache_snapshots(hf_repo)
                if cache_dir is None
                else _iter_hf_cache_snapshots(hf_repo, cache_dir)
            )
            weight_name = Path(near_path).name if near_path else None
            ranked: list[tuple[tuple[int, int, int, str], Path]] = []
            for snap in snapshots:
                names = _gguf_snapshot_files(snap)
                # Every non-sidecar GGUF here, nested dflash-*.gguf included, is a weight a sidecar could name.
                others = [
                    Path(name).name for name in names if not _is_root_dflash_drafter_path(name)
                ]
                ranked.extend(
                    (dflash_repo_preference_key(name, weight_name, others), snap / name)
                    for name in names
                    if _is_root_dflash_drafter_path(name)
                )
            for _, candidate in sorted(ranked, key = lambda entry: entry[0]):
                if not candidate.is_file():
                    continue
                # dflash- is only a naming convention: verify the header as the local scan does, and skip a mismatch rather than fail, or it is refused at startup.
                if not is_dflash_architecture(str(candidate)):
                    logger.info(
                        "Ignoring cached DFlash candidate %s: general.architecture is not dflash",
                        candidate,
                    )
                    continue
                # Half a split set reads as a valid header but cannot be opened, so the load quietly drops speculation; skip it, another snapshot may hold the full set.
                if not _drafter_split_is_complete(candidate):
                    logger.info(
                        "Ignoring cached DFlash candidate %s: split shard set is incomplete",
                        candidate,
                    )
                    continue
                return str(candidate)
        except Exception as exc:
            logger.debug("Cached DFlash drafter lookup failed for %s: %s", hf_repo, exc)
        return None

    def _download_dflash(
        self,
        *,
        hf_repo: str,
        hf_token: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
        near_path: Optional[str] = None,
        binary: Optional[str] = None,
    ) -> Optional[str]:
        """Auto fetches this ~1.5 GiB sidecar, gated on supports_dflash (--spec-type draft-dflash); a raised probe still fetches."""

        cancel_event = cancel_event if cancel_event is not None else self._cancel_event
        if cancel_event.is_set():
            return None
        weight_name = Path(near_path).name if near_path else None
        # Whatever a previous load concluded, this one is asking again.
        self._dflash_retry_needed = False

        def _mark_retry_needed() -> None:
            self._dflash_retry_needed = True

        # Header-rejected basenames, so the search moves past an impostor to the real sidecar.
        rejected: set[str] = set()

        def _pick_dflash(candidates: list[str]) -> Optional[str]:
            # Ranked against the weight loaded, not precision alone, so model B does not get model A's drafter; a sidecar naming no family stays eligible.
            from utils.models.drafters import (
                dflash_repo_preference_key,
                split_listing_is_complete,
            )

            # Root level only, as the local scan: a nested dflash-*.gguf is an ordinary weight, and offering it spends a whole download before the header check.
            others = [
                Path(name).name
                for name in candidates
                if name.lower().endswith(".gguf") and not _is_root_dflash_drafter_path(name)
            ]
            eligible = [
                name
                for name in candidates
                if _is_root_dflash_drafter_path(name)
                and Path(name).name not in rejected
                # Before ranking, as dflash_plan_files: the fetch refuses a half-listed set, and returning one would end the loop.
                and split_listing_is_complete(candidates, name)
            ]
            if not eligible:
                return None
            # Same size bound as dflash_plan_files: header reads only after download, a drafter is a few layers of its target, and an unlisted size keeps the candidate.
            sizes = self._remote_root_gguf_sizes(hf_repo, hf_token)
            try:
                target_bytes = (self._get_gguf_size_bytes(near_path) or 0) if near_path else 0
            except OSError:
                target_bytes = 0
            files = sorted(
                (
                    name
                    for name in eligible
                    # Whole set, not the picked shard: each half of a split weight can sit under the target while the set does not.
                    if not (
                        target_bytes and _drafter_set_bytes(sizes, Path(name).name) >= target_bytes
                    )
                ),
                key = lambda name: dflash_repo_preference_key(name, weight_name, others),
            )
            return files[0] if files else None

        def _validated(path: Optional[str]) -> Optional[str]:
            """Returns path only if header says dflash, since a filename test accepts any dflash-*.gguf; else the download spends gigabytes on a file llama-server refuses."""
            from utils.models.drafters import is_dflash_architecture

            if not path:
                return None
            if is_dflash_architecture(path):
                return path
            rejected.add(Path(path).name)
            logger.warning("Ignoring DFlash candidate %s: general.architecture is not dflash", path)
            return None

        # Each rejection shrinks the pool, and answers already seen end the loop, so a scan that ignores the pool cannot spin.
        cached: Optional[str] = None
        seen_siblings: set[str] = set()
        while near_path and not cancel_event.is_set():
            sibling = _companion_snapshot_sibling(near_path, _pick_dflash)
            if sibling is None or sibling in seen_siblings:
                break
            seen_siblings.add(sibling)
            cached = _validated(sibling)
            if cached:
                break
        # _cached_repo_dflash_drafter already header-checks its candidates.
        if not cached and _hf_env_offline():
            cached = self._cached_repo_dflash_drafter(
                hf_repo,
                cache_dir = _hub_cache_dir_for_snapshot_path(near_path),
                near_path = near_path,
            )
        try:
            if not self.probe_server_capabilities(binary).get("supports_dflash"):
                logger.warning(
                    "Skipping the DFlash sidecar download: llama-server has no usable "
                    "--spec-type draft-dflash, so this load falls back to no speculative "
                    "decoding. Run `unsloth studio update`, then reload."
                )
                # Still report a sidecar on disk, else the reuse check reloads each Apply; _build_speculative_flags re-checks support and still falls back.
                return cached
        except Exception as exc:
            logger.debug("DFlash capability probe failed before the sidecar fetch: %s", exc)

        if cached:
            logger.info("Reusing cached DFlash drafter: %s", cached)
            return cached
        outcome: dict = {}
        found: Optional[str] = None
        # The header is checkable only after fetch, so a rejection falls through to the next candidate; a fetch returning an already rejected file ends the search.
        fetched: set[str] = set()
        while True:
            candidate = self._download_companion_gguf(
                hf_repo = hf_repo,
                hf_token = hf_token,
                pick = _pick_dflash,
                label = "DFlash drafter",
                cancel_event = cancel_event,
                near_path = near_path,
                outcome = outcome,
                # Only a Hub failure, not a header rejection, leaves a real sidecar unfetched.
                on_transient_failure = _mark_retry_needed,
            )
            if candidate is None or candidate in fetched:
                break
            fetched.add(candidate)
            found = _validated(candidate)
            if found:
                break
        # Tells a repo with no usable sidecar apart from a fetch that may yet succeed; an ordinary dflash- weight counts as no usable sidecar.
        self._dflash_sidecar_absent = outcome.get("listed") is False
        return found

    @staticmethod
    def _remote_root_gguf_sizes(hf_repo: str, hf_token: Optional[str] = None) -> dict[str, int]:
        """Sizes come from model_info (list_repo_files has names only); empty means no size bound."""
        try:
            from huggingface_hub import model_info
            info = call_hub_with_anonymous_retry(model_info, hf_token, hf_repo, files_metadata = True)
            return {
                name: int(getattr(sibling, "size", 0) or 0)
                for sibling in (getattr(info, "siblings", None) or [])
                if isinstance(name := getattr(sibling, "rfilename", None), str) and "/" not in name
            }
        except Exception as exc:
            logger.debug("Could not size the DFlash candidates for %s: %s", hf_repo, exc)
            return {}

    def _dspark_wins_auto(
        self,
        *,
        binary: Optional[str],
        dspark_draft_path: Optional[str],
        spec_canon: str,
        extra_args: Optional[list[str]],
        caps: Optional[Callable[[Optional[str]], dict]] = None,
    ) -> bool:
        """A DSpark path alone is not enough: Auto picks DSpark only if the binary supports draft-dspark, else it stands down on DFlash and loads no drafter."""
        if spec_canon != "auto" or not dspark_draft_path:
            return False
        if _extra_args_set_spec_type(extra_args):
            return False
        try:
            # Through the caller's getter so an inconclusive probe still latches for this launch.
            probe = caps or self.probe_server_capabilities
            return bool(probe(binary).get("supports_dspark"))
        except Exception as exc:
            logger.debug("DSpark capability probe failed during Auto: %s", exc)
            return False

    def _resolve_launch_mmproj_path(
        self,
        *,
        model_path: str,
        mmproj_path: Optional[str],
        extra_args: Optional[Iterable[str]] = None,
    ) -> Optional[str]:
        """Resolve a projector, trusting an explicit path over filename heuristics."""
        override = _extra_args_device(extra_args, {"--mmproj", "-mm"})
        if override is not None:
            if not override or not Path(override).is_file():
                raise ValueError("The custom mmproj path must name an existing file.")
            return override
        if not mmproj_path:
            return None

        mmproj = Path(mmproj_path)
        if not mmproj.is_file():
            logger.warning(f"mmproj file not found: {mmproj_path}")
            return None

        from utils.models.model_config import mmproj_matches_model_family

        if not mmproj_matches_model_family(model_path, str(mmproj)):
            logger.warning(
                f"mmproj does not match model family: model={Path(model_path).name} "
                f"mmproj={mmproj.name}"
            )
            return None

        return str(mmproj)

    def _mmproj_vram_bytes(self, launch_mmproj_path: Optional[str]) -> int:
        """Return resolved mmproj VRAM bytes, or 0 when absent/unreadable."""
        if not launch_mmproj_path:
            return 0
        try:
            return self._get_gguf_size_bytes(launch_mmproj_path)
        except OSError as e:
            logger.debug(f"Could not size mmproj {launch_mmproj_path}: {e}")
            return 0

    def _inherited_mmproj_soft_overhead(self, mmproj_bytes: int, *, on_host: bool) -> int:
        """Projector arriving only via LLAMA_ARG_MMPROJ gets an encoder allowance, since its file size alone understates VRAM; VRAM arm only."""
        if mmproj_bytes <= 0 or on_host:
            return 0
        return int(mmproj_bytes * (self._MMPROJ_VRAM_SAFETY - 1.0))

    def _resolve_launch_mtp_path(
        self,
        *,
        mtp_draft_path: Optional[str],
        drafter_label: str = "MTP",
    ) -> Optional[str]:
        """Returns mtp_draft_path only if it exists on disk, else None; no family check, since the drafter comes only from the main GGUF's repo."""
        if not mtp_draft_path:
            return None
        if not Path(mtp_draft_path).is_file():
            logger.warning(f"{drafter_label} drafter file not found: {mtp_draft_path}")
            return None
        return str(mtp_draft_path)

    _IMAGE_ARCHES = _gguf_archs.DIFFUSION_IMAGE_GGUF_ARCHS
    _AMBIGUOUS_IMAGE_ARCHES = _gguf_archs.AMBIGUOUS_DIFFUSION_GGUF_ARCHS
    _VIDEO_ARCHES = _gguf_archs.VIDEO_GGUF_ARCHS
    _UNRUNNABLE_MEDIA_ARCHES = _gguf_archs.UNSUPPORTED_DIFFUSION_GGUF_ARCHS
    _DIFFUSION_ARCHES = (
        _IMAGE_ARCHES | _AMBIGUOUS_IMAGE_ARCHES | _VIDEO_ARCHES | _UNRUNNABLE_MEDIA_ARCHES
    )
    _SPEECH_ARCHES = _SPEECH_GGUF_ARCHS

    _PLACEHOLDER_ARCHES = _gguf_archs.PLACEHOLDER_DIFFUSION_GGUF_ARCHS

    @staticmethod
    def _video_arch_is_pickable(
        arch: Optional[str], gguf_path: Optional[str], model_identifier: Optional[str]
    ) -> bool:
        """Asks arch, repo id, then filename in _arch_to_task's order; an MoE counts only if it names one expert of a high/low noise pair, and the engine can build it."""
        try:
            from core.inference.video_families import detect_video_family

            from routes.models import _video_family_buildable

            fam = detect_video_family("", override = (arch or "").strip().lower() or None)
            if fam is None:
                for needle in (model_identifier, os.path.basename(gguf_path or "")):
                    if not needle:
                        continue
                    fam = detect_video_family(needle)
                    if fam is not None:
                        break
            if fam is None:
                return False
            from core.inference.video_moe_pair import moe_pick_pairs

            # An MoE expert is offered when its name pairs the partner the loader assembles it with.
            return moe_pick_pairs(fam, gguf_path) and _video_family_buildable(fam)
        except Exception as e:  # noqa: BLE001 -- never lose the page over a probe failure
            logger.debug("Family probe failed for video arch: %s", e)
            return True

    @staticmethod
    def _image_arch_is_pickable(
        gguf_path: Optional[str],
        model_identifier: Optional[str],
        arch: Optional[str] = None,
    ) -> bool:
        """The Images picker's fail-open buildability gate (Qwen-Image-2.1 needs diffusers 0.41)."""
        try:
            from routes.models import _diffusion_gguf_family_hints, _gguf_family_buildable
            return _gguf_family_buildable(
                _diffusion_gguf_family_hints(
                    arch, (model_identifier, os.path.basename(gguf_path or ""))
                )
            )
        except Exception as e:  # noqa: BLE001 -- never lose the page over a probe failure
            logger.debug("Family probe failed for image arch: %s", e)
            return True

    @staticmethod
    def _ambiguous_image_arch_is_pickable(
        gguf_path: Optional[str], model_identifier: Optional[str]
    ) -> bool:
        """Matches routes.models._arch_to_task so the refusal never names a missing Images row; imported lazily (routes imports this module); fails open on probe error."""
        try:
            from core.inference.diffusion_engine_router import family_buildable_here
            from core.inference.diffusion_families import (
                detect_family_for_pick,
                family_gguf_loadable,
            )

            for needle in (model_identifier, os.path.basename(gguf_path or "")):
                if not needle:
                    continue
                fam = detect_family_for_pick(needle)
                if fam is not None:
                    return family_gguf_loadable(fam) and family_buildable_here(
                        fam, model_kind = "gguf"
                    )
            return False
        except Exception as e:  # noqa: BLE001 -- never lose the page over a probe failure
            logger.debug("Family probe failed for ambiguous image arch: %s", e)
            return True

    def _non_chat_gguf_refusal(self, gguf_path: str) -> Optional[str]:
        """Header-only refusal of adapter and media GGUFs: an adapter, a media architecture, or none
        at all once the header parsed."""
        # Metadata, not filenames: an adapter may declare a chat arch; a merged LoRA is a full model.
        # Checked before the walk gate: a type that was read is definitive even from a partial prefix.
        if getattr(self, "_gguf_type", None) == "adapter":
            return (
                "This GGUF is a LoRA adapter and needs a matching base model. "
                "Select a full model GGUF for chat, or use this adapter with its base model."
            )
        arch = (self._architecture or "").strip().lower()
        # A media arch is KV 0 so a partial remote prefix can carry it; the walk still gates the no-arch fallback, since an incomplete read looks like none.
        if (
            arch not in self._DIFFUSION_ARCHES
            and not is_speech_gguf_architecture(arch)
            and not is_audio_cpp_gguf_architecture(arch)
            and not getattr(self, "_gguf_header_parsed", False)
        ):
            return None
        if arch in self._PLACEHOLDER_ARCHES:
            # A placeholder arch counts as no architecture, so the name-based branch below decides the page.
            arch = ""
        if arch:
            if is_audio_cpp_gguf_architecture(arch):
                return (
                    "This is an audio GGUF (speech, music or transcription), which cannot run as "
                    "a chat model. Open it from the Audio page instead."
                )
            if is_speech_gguf_architecture(arch):
                # Points at the Transformers build: the Audio page cannot list a speech GGUF either.
                return (
                    "This is a text-to-speech GGUF, which llama.cpp cannot load: it has no "
                    "CSM decoder. Run the model's Transformers build (for example "
                    "unsloth/csm-1b) from the Audio page instead."
                )
            if arch in self._UNRUNNABLE_MEDIA_ARCHES:
                return (
                    f"This is an image / video generation GGUF (architecture '{arch}'), "
                    "which cannot run as a chat model. Unsloth Studio cannot run this "
                    "architecture at all: neither the Images page nor the Video page "
                    "accepts it."
                )
            if arch in self._VIDEO_ARCHES:
                # wan alone is not enough: the canonical classifier resolves the family by name and rejects an MoE the GGUF loader cannot assemble.
                if self._video_arch_is_pickable(arch, gguf_path, self._model_identifier):
                    return (
                        f"This is a text-to-video GGUF (architecture '{arch}'), which "
                        "cannot run as a chat model. Open it from the Video page instead."
                    )
                return (
                    f"This is a text-to-video GGUF (architecture '{arch}'), which cannot "
                    "run as a chat model. Unsloth cannot assemble this particular model "
                    "from a GGUF, so the Video page does not list it either."
                )
            if arch in self._IMAGE_ARCHES:
                if self._image_arch_is_pickable(gguf_path, self._model_identifier, arch):
                    return (
                        f"This is an image-generation GGUF (architecture '{arch}'), which "
                        "cannot run as a chat model. Open it from the Images page instead."
                    )
                return (
                    f"This is an image-generation GGUF (architecture '{arch}'), which "
                    "cannot run as a chat model. No image engine installed here can build "
                    "this model family, so the Images page does not list it either. "
                    "Updating Unsloth may add support for it."
                )
            if arch in self._AMBIGUOUS_IMAGE_ARCHES:
                if self._ambiguous_image_arch_is_pickable(gguf_path, self._model_identifier):
                    return (
                        f"This is an image-generation GGUF (architecture '{arch}'), which "
                        "cannot run as a chat model. Open it from the Images page instead."
                    )
                return (
                    f"This is an image-generation GGUF (architecture '{arch}'), which "
                    "cannot run as a chat model. Unsloth could not tell which model family "
                    f"this file belongs to -- '{arch}' is shared by several -- so the "
                    "Images page cannot assemble it either."
                )
            return None

        # A later gguf-split shard declares no architecture; llama.cpp's own first-split error is better.
        # Requires split.no > 0 and nothing declared, since shard 1 has the split keys too.
        if self._architecture is None and (self._gguf_split_index or 0) > 0:
            return None

        # No architecture declared: not loadable by llama-server whatever it is; name a page only when the identifiers make that clear.
        needles = [n for n in (self._model_identifier, os.path.basename(gguf_path or "")) if n]
        # Name a page only if its picker would actually list the model.
        try:
            from core.inference.video_families import detect_video_family
            if any(detect_video_family(n) is not None for n in needles):
                if self._video_arch_is_pickable(None, gguf_path, self._model_identifier):
                    return (
                        "This is a text-to-video model, not a chat model: its GGUF carries "
                        "no llama.cpp model metadata, so llama-server cannot load it. Open "
                        "it from the Video page instead."
                    )
                return (
                    "This is a text-to-video model, not a chat model, and its GGUF carries "
                    "no llama.cpp model metadata. Unsloth cannot assemble this particular "
                    "model from a GGUF either, so the Video page does not list it."
                )
        except Exception as e:  # noqa: BLE001 -- naming the page is a nicety, never a gate
            logger.debug("Video family probe failed during non-chat GGUF preflight: %s", e)
        try:
            from core.inference.diffusion_families import detect_family
            if any(detect_family(n) is not None for n in needles):
                if self._ambiguous_image_arch_is_pickable(gguf_path, self._model_identifier):
                    return (
                        "This is an image-generation model, not a chat model: its GGUF "
                        "carries no llama.cpp model metadata, so llama-server cannot load "
                        "it. Open it from the Images page instead."
                    )
                return (
                    "This is an image-generation model, not a chat model, and its GGUF "
                    "carries no llama.cpp model metadata. Unsloth cannot assemble this "
                    "particular model from a GGUF either, so the Images page does not list "
                    "it."
                )
        except Exception as e:  # noqa: BLE001
            logger.debug("Image family probe failed during non-chat GGUF preflight: %s", e)
        return (
            "This GGUF carries no llama.cpp model metadata (no general.architecture), so "
            "llama-server cannot load it as a chat model. Image and video GGUFs are "
            "packaged this way -- try the Images or Video page, or pick a chat GGUF."
        )

    # Distro packages for the Linux prebuilt's shared libs, for the loader-failure hint.
    _SHARED_LIB_PACKAGES = {
        "libgomp.so.1": " (Debian/Ubuntu: libgomp1, Fedora/RHEL: libgomp)",
    }

    # Libraries Unsloth ships in build/bin; a loader failure naming one means a broken managed
    # runtime, not a missing package.
    _BUNDLED_LIB_PREFIXES = ("libllama", "libggml", "libmtmd")

    @staticmethod
    def _is_bundled_llama_library(lib: str) -> bool:
        # The loader prints a soname when absent, a full path when rejected; compare basenames.
        return os.path.basename((lib or "").strip()).startswith(
            LlamaCppBackend._BUNDLED_LIB_PREFIXES
        )

    @staticmethod
    def _is_unsloth_managed_binary(binary: Optional[str]) -> bool:
        """A pinned LLAMA_SERVER_PATH or PATH llama-server is unmanaged, so update cannot repair it; an unknown binary (none passed) keeps the managed default."""
        if not binary:
            return True
        try:
            from utils.llama_cpp_path_settings import custom_llama_cpp_path_source
            from utils.llama_cpp_update import (
                _active_install_is_local_link,
                _llama_install_root,
            )

            # A Settings-selected checkout is user-owned even if it looks like our tree.
            if custom_llama_cpp_path_source() == "studio":
                return False
            # A --with-llama-cpp-dir symlinked tree is the user's; the updater refuses to write through it.
            if _active_install_is_local_link(binary):
                return False
            return _llama_install_root(binary) is not None
        except Exception:
            return True

    @staticmethod
    def _is_llama_install_tree(binary: Optional[str]) -> bool:
        """A --with-llama-cpp-dir checkout is the active install but not updater-replaceable."""
        if not binary:
            return True
        try:
            from utils.llama_cpp_update import _llama_install_root
            return _llama_install_root(binary) is not None
        except Exception:
            return True

    @staticmethod
    def _is_library_path(lib: str) -> bool:
        # glibc treats any slash as a pathname (no search); match both separators since the text
        # comes from another host.
        lib = (lib or "").strip()
        return "/" in lib or "\\" in lib

    @staticmethod
    def _missing_library_message(lib: str, binary: Optional[str] = None) -> str:
        """The loader could not FIND ``lib`` ("cannot open shared object file")."""
        if LlamaCppBackend._is_bundled_llama_library(lib):
            if LlamaCppBackend._is_unsloth_managed_binary(binary):
                return (
                    f"llama-server could not start: {lib} is part of Unsloth's own "
                    "llama.cpp runtime and is missing from the install. Run "
                    "`unsloth studio update` to reinstall it, then load the model "
                    "again."
                )
            return (
                f"llama-server could not start: {lib} is part of the llama.cpp "
                "runtime that the llama-server binary in use was built with. That "
                "binary is a custom install Unsloth does not manage, so reinstall "
                "or rebuild that llama.cpp, then load the model again."
            )
        # A pathname was opened directly, so no package will put that exact file there.
        if LlamaCppBackend._is_library_path(lib):
            _remedy = (
                "run `unsloth studio update`"
                if LlamaCppBackend._is_unsloth_managed_binary(binary)
                else "reinstall or rebuild that custom llama.cpp"
            )
            return (
                f"llama-server could not start: {lib} is missing from that exact "
                f"location. Restore it, or {_remedy}, then load the model again."
            )
        return (
            f"llama-server could not start: the system library "
            f"{lib or 'it needs'} is missing. Install it with your package "
            f"manager{LlamaCppBackend._SHARED_LIB_PACKAGES.get(lib, '')}, "
            "then load the model again."
        )

    @staticmethod
    def _unloadable_library_message(
        lib: str,
        reason: str,
        binary: Optional[str] = None,
    ) -> str:
        """The file exists but the loader refused it, so installing a package is the wrong advice."""
        detail = f" ({reason})" if reason else ""
        if LlamaCppBackend._is_bundled_llama_library(lib):
            if LlamaCppBackend._is_unsloth_managed_binary(binary):
                return (
                    f"llama-server could not start: {lib}, part of Unsloth's own "
                    f"llama.cpp runtime, could not be loaded{detail}. The install "
                    "is incomplete or mismatched. Run `unsloth studio update` to "
                    "reinstall it, then load the model again."
                )
            return (
                f"llama-server could not start: {lib}, part of the llama.cpp "
                "runtime that the llama-server binary in use was built with, "
                f"could not be loaded{detail}. That binary is a custom install "
                "Unsloth does not manage, so reinstall or rebuild that "
                "llama.cpp, then load the model again."
            )
        return (
            f"llama-server could not start: the library {lib or 'it needs'} "
            f"could not be loaded{detail}. Reinstall or update whatever "
            "provides it, then load the model again."
        )

    @staticmethod
    def _exec_path_for_launch(binary: Optional[str]) -> Optional[str]:
        """Resolves only an installer-template macOS wrapper past /bin/sh (SIP strips DYLD_*), by shape not provenance; any other wrapper is left alone."""
        if not binary or sys.platform != "darwin":
            return binary
        if not LlamaCppBackend._is_unsloth_managed_binary(binary):
            try:
                from utils.llama_cpp_path_settings import custom_llama_cpp_path_source
                if custom_llama_cpp_path_source() != "studio":
                    return binary
            except Exception:
                return binary
        if not _is_installer_entrypoint(binary):
            return binary
        # template_only: resolve only through links that are also ours.
        return str(_resolve_llama_binary(binary, template_only = True))

    @staticmethod
    def _runtime_remedy(binary: Optional[str]) -> str:
        """Pinned or PATH llama-server binaries get a rebuild instruction, since update cannot touch
        them."""
        return (
            "run `unsloth studio update` to reinstall the llama.cpp runtime"
            if LlamaCppBackend._is_unsloth_managed_binary(binary)
            else "reinstall or rebuild that custom llama.cpp"
        )

    # A tried: list can run to kilobytes; cap like the glibc branch.
    _MACOS_REASON_CHARS = 300

    # macOS PATH_MAX is 1024; anything past double is not from the loader.
    _DYLD_LIB_NAME_MAX_CHARS = 2048

    @staticmethod
    def _plain_dyld_lib_name(lib: str) -> str:
        """Reduces dyld @rpath, @loader_path or @executable_path names to basename: they are lookup tokens, so as paths they would name a missing directory."""
        if lib.startswith(("@rpath/", "@loader_path/", "@executable_path/")):
            lib = os.path.basename(lib)
        # Quoted from untrusted output into an HTTP error, so cap it.
        if len(lib) > LlamaCppBackend._DYLD_LIB_NAME_MAX_CHARS:
            lib = lib[: LlamaCppBackend._DYLD_LIB_NAME_MAX_CHARS] + "..."
        return lib

    # Ten paths of a long length each is generous; it only cuts text no real dyld reason produces.
    _DYLD_REASON_MAX_CHARS = 4000
    # How far past Library not loaded to scan for its Reason: four times the cap, so noise before a real reason is still found whole.
    _DYLD_REASON_SCAN_CHARS = 16000
    # Candidates come from one tried: list; dyld searches a bounded set, so a longer list is not dyld's.
    _DYLD_MAX_CANDIDATES = 128

    # dyld framing must start a line; phrases like 'Referenced from:' can come from wrappers or GGUF metadata.
    _DYLD_FRAMING_RE = re.compile(
        r"(?im)^[ \t]*(?:dyld(?:\[\d+\])?:|termination reason:.*\bdyld\b)"
    )

    @staticmethod
    def _dyld_reason_after(output: str, start: int) -> str:
        """Searched only after the dyld message, in a capped window, since the match can backtrack badly."""
        # Windowed: the reason sits right under the line, and matching all output could use huge memory.
        window = output[start : start + LlamaCppBackend._DYLD_REASON_SCAN_CHARS]
        match = re.compile(
            r"reason:[ \t]*([^\r\n]*(?:\r?\n[ \t]+[^\r\n]*)*)",
            re.IGNORECASE,
        ).search(window)
        if not match:
            return ""
        return " ".join(match.group(1)[: LlamaCppBackend._DYLD_REASON_MAX_CHARS].split())

    @staticmethod
    def _dyld_tried_verdict(reason: str, binary: Optional[str]) -> str:
        """Prefers the dyld candidate in our own lib dir, else the first; the bare reason if no list."""
        lib_dir = ""
        if binary:
            try:
                lib_dir = str(_llama_lib_dir(binary))
            except (OSError, ValueError):
                lib_dir = ""
        # Use finditer with a cap, not findall: a list built before the first useful match is wasted work.
        first: Optional[str] = None
        for index, match in enumerate(re.finditer(r"'([^']+)'\s*\(([^)]*)\)", reason)):
            if index >= LlamaCppBackend._DYLD_MAX_CANDIDATES:
                break
            path, verdict = match.group(1), match.group(2)
            if first is None:
                first = verdict
            if lib_dir and os.path.dirname(path) == lib_dir:
                return verdict
        return first if first is not None else reason

    @staticmethod
    def _classify_macos_loader_failure(output: str, binary: Optional[str]) -> Optional[str]:
        """Only dyld-framed output counts: GGUF metadata can echo 'Library not loaded' text."""
        if not output:
            return None
        if not LlamaCppBackend._DYLD_FRAMING_RE.search(output):
            return None
        lowered = output.lower()

        # Same markers as install_llama_prebuilt.looks_like_macos_incompatibility.
        if ("built for macos" in lowered and "newer than running os" in lowered) or (
            "symbol not found" in lowered and "mtlresidency" in lowered
        ):
            return (
                "llama-server could not start: the installed llama.cpp runtime "
                "was built for a newer version of macOS than this Mac is "
                f"running. Update macOS, or {LlamaCppBackend._runtime_remedy(binary)} "
                "to get a build that matches this OS."
            )

        # "Library not loaded: <path>", then the "Reason:" that belongs to it.
        not_loaded = re.search(
            r"library not loaded:[ \t]*([^\r\n]+)",
            output,
            re.IGNORECASE,
        )
        if not_loaded:
            lib = LlamaCppBackend._plain_dyld_lib_name(not_loaded.group(1).strip())
            reason = LlamaCppBackend._dyld_reason_after(output, not_loaded.end())
            # dyld4 gives a per-path verdict; judge our path, not a stale copy elsewhere.
            verdict = LlamaCppBackend._dyld_tried_verdict(reason, binary)
            verdict_l = verdict.lower()
            # Code-signature refusal: a hard SIGKILL on Apple Silicon, not a GGUF or memory problem.
            if "code signature" in verdict_l or "not valid for use in process" in verdict_l:
                return (
                    f"llama-server could not start: macOS rejected the code "
                    f"signature of {lib}. The file was modified or is "
                    f"incompletely signed, so {LlamaCppBackend._runtime_remedy(binary)}."
                )
            # dyld4 reports incompatible architecture; older dyld reported wrong architecture.
            if "incompatible architecture" in verdict_l or "wrong architecture" in verdict_l:
                return (
                    f"llama-server could not start: {lib} was built for a "
                    "different CPU architecture than this Mac. Its install is "
                    f"for the wrong platform, so {LlamaCppBackend._runtime_remedy(binary)}."
                )
            # Only 'no such file' / 'image not found' mean absent; otherwise dyld found and refused it.
            if not verdict_l or "no such file" in verdict_l or "image not found" in verdict_l:
                return LlamaCppBackend._missing_library_message(lib, binary)
            return LlamaCppBackend._unloadable_library_message(
                lib, verdict[: LlamaCppBackend._MACOS_REASON_CHARS], binary
            )

        # Symbol mismatch: a system framework means the build needs a newer macOS, ours means mixed
        # builds. Only with dyld framing, since 'Symbol not found' is ordinary English.
        if "symbol not found" in lowered and any(
            marker in lowered for marker in ("dyld[", "dyld:", "referenced from:", "expected in:")
        ):
            expected = re.search(r"expected in:\s*(?:<[^>]*>\s*)?([^\r\n]+)", output, re.IGNORECASE)
            # Newer dyld quotes the path; strip quotes or the /System prefix test fails.
            expected_path = expected.group(1).strip().strip("'\"") if expected else ""
            if expected_path.startswith(("/System/", "/usr/lib/")):
                return (
                    "llama-server could not start: it needs a symbol this "
                    "version of macOS does not provide, so the installed "
                    "llama.cpp runtime was built for a newer macOS. Update "
                    f"macOS, or {LlamaCppBackend._runtime_remedy(binary)} to get "
                    "a build that matches this OS."
                )
            return (
                "llama-server could not start: its llama.cpp libraries are from "
                "a different build than the llama-server binary (a symbol it "
                "needs is missing). The install is mismatched, so "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )
        return None

    # The shell's EBADARCH message; never reaches dyld, so matched on its own.
    _BAD_CPU_TYPE_RE = re.compile(r"(?im)^.*:[ \t]*bad cpu type in executable[ \t]*$")

    @staticmethod
    def _classify_llama_start_failure(
        output: str,
        gguf_path: Optional[str],
        model_identifier: Optional[str],
        returncode: Optional[int] = None,
        binary: Optional[str] = None,
        log_path: "Optional[Path | str]" = None,
        secrets: Sequence[Optional[str]] = (),
        extra_args: Optional[Sequence[str]] = None,
    ) -> str:
        """Redacts every classified message, since each branch quotes untrusted child output."""
        return LlamaCppBackend._scrub_secret_values(
            LlamaCppBackend._classify_start_failure_text(
                output,
                gguf_path,
                model_identifier,
                returncode,
                binary,
                log_path,
                secrets,
                extra_args,
            ),
            secrets,
        )

    @staticmethod
    def _classify_start_failure_text(
        output: str,
        gguf_path: Optional[str],
        model_identifier: Optional[str],
        returncode: Optional[int] = None,
        binary: Optional[str] = None,
        log_path: "Optional[Path | str]" = None,
        secrets: Sequence[Optional[str]] = (),
        extra_args: Optional[Sequence[str]] = None,
    ) -> str:
        """Classifies the child's output, which is never trusted, even when it mimics Unsloth's own
        framing."""
        lowered = (output or "").lower()

        # A healthy server we stopped ourselves: its output holds no failure to classify.
        if _PORT_OWNER_REFUSED_MARKER.lower() in lowered:
            return (
                "llama-server started and answered on its local port, but Studio could not "
                "confirm that the listener on that port belongs to the server it launched, so it "
                "stopped the server. The model file and memory are not the problem; the backend "
                "log names the port and the process that held it."
            )

        # Then: every branch below advises reinstall, memory or administrator,
        # none of which lift a refusal to load a file that is present.
        blocked = code_integrity_block_reason(returncode) or code_integrity_block_reason(output)
        if blocked is not None:
            return code_integrity_user_message(binary or "the llama.cpp runtime", blocked)

        cuda_image_error = LlamaCppBackend._cuda_kernel_image_error(output)
        if cuda_image_error is not None:
            return LlamaCppBackend._cuda_kernel_image_message(cuda_image_error, binary, log_path)

        # Split the glibc loader message on ': ', not whitespace, since library paths may contain
        # spaces.
        missing_lib = re.search(
            r"error while loading shared libraries:[ \t]*([^\r\n]+?)"
            r"(?::[ \t]+([^\r\n]*))?[ \t]*\r?$",
            output or "",
            re.MULTILINE,
        )
        if missing_lib:
            _lib = missing_lib.group(1).strip()
            _reason = (missing_lib.group(2) or "").strip()
            # glibc omits the object name on its own allocation failures.
            if not (
                "/" in _lib or "\\" in _lib or any(_e in _lib for _e in (".so", ".dylib", ".dll"))
            ):
                return LlamaCppBackend._unloadable_library_message(
                    "", f"{_lib} {_reason}".strip(), binary
                )
            # Only ENOENT means absent; EACCES etc. mean it exists but cannot be opened, so no package fix; a truncated tail keeps the missing-library reading.
            _reason_l = _reason.lower()
            _errno_text = ""
            if "cannot open shared object file:" in _reason_l:
                _errno_text = _reason_l.split("cannot open shared object file:", 1)[1].strip()
            if not _reason_l or (
                "cannot open" in _reason_l and (not _errno_text or "no such file" in _errno_text)
            ):
                return LlamaCppBackend._missing_library_message(_lib, binary)
            return LlamaCppBackend._unloadable_library_message(_lib, _reason, binary)

        # macOS: dyld shares no wording with glibc.
        macos_detail = LlamaCppBackend._classify_macos_loader_failure(output or "", binary)
        if macos_detail:
            return macos_detail

        # Wrong-arch executable: the shell rejects it before dyld runs.
        if LlamaCppBackend._BAD_CPU_TYPE_RE.search(output or ""):
            return (
                "llama-server could not start: the executable was built for a "
                "different CPU architecture than this Mac, so "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )

        # Argument parsing runs before the model loads: an unknown flag vs a rejected value. Bounded
        # to the tail, where llama.cpp prints argument errors.
        scan_tail = (output or "")[-_FAILURE_SCAN_TAIL_CHARS:]

        def _short(value: str) -> str:
            """Bounds the child-output fragment quoted into an error, since a wrapper could print 64 KiB."""
            value = value.strip()
            return (
                value
                if len(value) <= _FAILURE_QUOTE_CHARS
                else (value[:_FAILURE_QUOTE_CHARS] + "...")
            )

        unknown_arg = re.search(r"error:\s*invalid argument:\s*(\S+)", scan_tail, re.IGNORECASE)
        if unknown_arg:
            # Name both owners: Unsloth's own conditional flags can be rejected too.
            return (
                f"llama-server does not recognise the argument "
                f"'{_short(unknown_arg.group(1))}'. Check it in this model's extra "
                f"arguments, or reinstall llama.cpp if you did not set it."
            )

        bad_arg_value = re.search(
            r'error while handling argument "([^"]+)":\s*([^\r\n]*)',
            scan_tail,
            re.IGNORECASE,
        )
        if bad_arg_value:
            _arg = _short(bad_arg_value.group(1))
            _why = _short(bad_arg_value.group(2) or "")
            # llama.cpp surfaces a failed std::stoi as just 'stoi'.
            if _why.lower() in {"stoi", "stof", "stod", "stoul", "stoll"}:
                _why = "the value is not a number"
            _tail = f": {_why}" if _why else ""
            # Blame the extra arguments only when they really carry the flag; an alias spelling gets neutral wording rather than a guess.
            _owned_by_user = False
            if extra_args:
                from core.inference.llama_server_args import _flag_name
                _failed_flag = _flag_name(_arg)
                _owned_by_user = _failed_flag is not None and any(
                    _flag_name(str(token)) == _failed_flag for token in extra_args
                )
            if _owned_by_user:
                return (
                    f"llama-server rejected the value for '{_arg}'{_tail}. Fix it in "
                    f"the extra arguments for this model."
                )
            return (
                f"llama-server rejected the value for '{_arg}'{_tail}. Check it in "
                f"this model's extra arguments, or reinstall llama.cpp if you did "
                f"not set it."
            )

        # --split-mode tensor is arch-gated in llama.cpp; point at the toggle.
        if "split_mode_tensor not implemented" in lowered:
            return (
                "Tensor parallelism is not supported for this model's "
                "architecture. Turn off Tensor Parallelism in the model "
                "settings and reload."
            )

        if LlamaCppBackend._is_sched_reserve_abort(output or ""):
            return LlamaCppBackend._sched_reserve_abort_message()

        # An older build refusing quantized KV under tensor split: the remedy is an update.
        if LlamaCppBackend._is_tensor_quant_kv_unsupported(lowered):
            return (
                "This llama.cpp build cannot use a quantized KV cache together "
                "with Tensor Parallelism (support landed in b9455). Update "
                "llama.cpp, or set the KV cache type to f16, or turn off Tensor "
                "Parallelism in the model settings."
            )

        # llama.cpp prints the bad magic with %c, so a binary header shows as garbage.
        if "invalid magic characters" in lowered:
            # Not necessarily the main model: the projector and drafter report this too.
            base = os.path.basename(gguf_path) if gguf_path else ""
            named = f", loading {base}" if base else ""
            # A ._ path proves the volume keeps xattrs in AppleDouble companions; dot_clean fixes it.
            remedy = (
                'This volume has no native extended attributes, so macOS keeps them in "._" '
                'companions: run "dot_clean -m" on the folder to remove them, or keep models '
                "on an APFS disk."
                if base.startswith("._")
                else "Re-download the model, or pick a different file."
            )
            return LlamaCppBackend._with_startup_diagnostics(
                f"llama-server opened a file that is not a GGUF{named}: it does not start with "
                "the GGUF magic. It may be that file or a companion loaded with it, such as a "
                f"vision projector or a drafter, which llama-server does not always name. {remedy}",
                output,
                log_path,
                secrets,
            )

        # Detect Ollama first so the arch branch keeps the Ollama hint.
        gguf = gguf_path or ""
        is_ollama = (
            ".studio_links" in gguf
            or os.sep + "ollama_links" + os.sep in gguf
            or os.sep + ".cache" + os.sep + "ollama" + os.sep in gguf
            or (model_identifier or "").startswith("ollama/")
        )

        # Unknown-arch: diffusion to Images page, Ollama to Ollama hint, else unsupported; exact match only.
        arch_match = re.search(r"unknown model architecture:\s*'([^']+)'", lowered)
        if arch_match:
            arch = arch_match.group(1)
            if is_audio_cpp_gguf_architecture(arch):
                return (
                    "This is an audio GGUF (speech, music or transcription), which llama-server "
                    "cannot run as a chat/completion model. Open it from Unsloth's Audio page instead."
                )
            if is_speech_gguf_architecture(arch):
                # Name the build that runs it, not a page this file will not appear on.
                return (
                    f"'{arch}' is a text-to-speech GGUF, which llama-server cannot run as a "
                    "chat/completion model. Run the model's Transformers build (for example "
                    "unsloth/csm-1b) from Unsloth's Audio page instead."
                )
            if arch in LlamaCppBackend._UNRUNNABLE_MEDIA_ARCHES:
                return (
                    f"'{arch}' is an image / video generation GGUF, which llama-server "
                    "cannot run as a chat/completion model. Unsloth Studio cannot run "
                    "this architecture at all: neither the Images page nor the Video "
                    "page accepts it."
                )
            if arch in LlamaCppBackend._VIDEO_ARCHES:
                if LlamaCppBackend._video_arch_is_pickable(arch, gguf_path, model_identifier):
                    return (
                        f"'{arch}' is a text-to-video GGUF, which llama-server "
                        "cannot run as a chat/completion model. Open it from "
                        "Unsloth's Video page instead of a chat."
                    )
                return (
                    f"'{arch}' is a text-to-video GGUF, which llama-server cannot run as "
                    "a chat/completion model. Unsloth cannot assemble this particular "
                    "model from a GGUF, so the Video page does not list it either."
                )
            if (
                arch in LlamaCppBackend._IMAGE_ARCHES
                and LlamaCppBackend._image_arch_is_pickable(gguf_path, model_identifier, arch)
            ) or (
                arch in LlamaCppBackend._AMBIGUOUS_IMAGE_ARCHES
                and LlamaCppBackend._ambiguous_image_arch_is_pickable(gguf_path, model_identifier)
            ):
                return (
                    f"'{arch}' is a diffusion (image-generation) GGUF, which "
                    "llama-server cannot run as a chat/completion model. Use "
                    "Unsloth's Images page to generate with local diffusion "
                    "GGUFs such as FLUX and Qwen-Image."
                )
            if arch in LlamaCppBackend._IMAGE_ARCHES:
                return (
                    f"'{arch}' is a diffusion (image-generation) GGUF, which "
                    "llama-server cannot run as a chat/completion model. No image engine "
                    "installed here can build this model family, so Unsloth's Images page "
                    "does not list it either. Updating Unsloth may add support for it."
                )
            if arch in LlamaCppBackend._AMBIGUOUS_IMAGE_ARCHES:
                # Unresolved shared archs are hidden from the Images picker.
                return (
                    f"'{arch}' is a diffusion (image-generation) GGUF, which "
                    "llama-server cannot run as a chat/completion model. Unsloth Studio "
                    f"could not tell which model family this file is -- '{arch}' is "
                    "shared by several -- so the Images page cannot assemble it either."
                )
            if is_ollama:
                return (
                    "Some Ollama models do not work with llama.cpp. Try a "
                    "different model, or use this model directly through "
                    "Ollama instead."
                )
            # Includes an arch the installed build predates.
            return (
                f"The installed llama.cpp does not recognise this GGUF's model "
                f"architecture ('{arch}'). The file is valid. If the model is newer "
                "than this llama.cpp build, updating llama.cpp may add support for it."
            )

        # Other Ollama compat failures, only when the output shows a GGUF compat issue.
        if is_ollama:
            gguf_compat_hints = (
                "key not found",
                "unknown model architecture",
                "failed to load model",
            )
            if any(h in lowered for h in gguf_compat_hints):
                return (
                    "Some Ollama models do not work with llama.cpp. Try a "
                    "different model, or use this model directly through "
                    "Ollama instead."
                )

        # GGUF converted for another llama.cpp format revision (#8513: pre-#24908 MiniMax-M3 lacks indexer keys).
        missing_key = re.search(r"key not found in model:\s*([\w.\-]+)", scan_tail, re.IGNORECASE)
        if missing_key:
            return LlamaCppBackend._with_startup_diagnostics(
                f"This GGUF is missing the metadata key '{_short(missing_key.group(1))}', "
                "which the installed llama.cpp requires to load it. The file was made "
                "for a different llama.cpp version of this model's format, usually an "
                "older or pre-release one; this is not a memory problem. Download an "
                "updated GGUF of this model, or update llama.cpp if the file is newer "
                "than this build.",
                output,
                log_path,
                secrets,
            )

        # A type this build lacks (prism-ml PQ2_0 / PTQ1_0 = 142 / 143) or packs differently (group-128 Q2_0, #11259).
        # A truncated download fails later instead, as "data is not within the file bounds".
        # Bundled IQ1_XS..IQ1_XXXS = 64-66, so ids 43-63 fail later as an empty block-size-0 slot (#13908).
        bad_type = re.search(
            r"tensor '([^']*)' (?:has invalid ggml type (\d+)|of type (\d+) .*?not a multiple of block size \(0\))",
            scan_tail,
        )
        bad_layout = re.search(r"tensor '[^']*' has offset \d+, expected \d+", scan_tail)
        if bad_type or bad_layout:
            detail = (
                f"tensor '{_short(bad_type.group(1))}' uses quantization type "
                f"{bad_type.group(2) or bad_type.group(3)}, which this build does not have"
                if bad_type
                else "its tensor layout does not match this build's quantization types"
            )
            return LlamaCppBackend._with_startup_diagnostics(
                "The installed llama.cpp cannot read this GGUF's weights "
                f"({detail}); this is not a memory problem. The file was likely made for "
                "a different llama.cpp build: a newer one, or a publisher's own fork. Pick "
                "another quant of this model, or use the llama.cpp build the "
                "model card names. If the model card says it runs on stock llama.cpp, "
                "the file may be damaged: download it again.",
                output,
                log_path,
                secrets,
            )

        # 127 without any loader line above is not specific to a library: it is
        # also what a shell wrapper entrypoint reports when its exec target is
        # gone (_llama_lib_dir supports those, as does a custom
        # LLAMA_SERVER_PATH), and what a "symbol lookup error" from a mismatched
        # runtime exits with. Name both causes instead of blaming a distro
        # package -- but still keep it off the GGUF and off memory.
        # A ROCm symbol lookup is also 127, but the generic text below would send
        # the user to reinstall a binary Vulkan and a shell launch both run fine.
        _rocm_miss = LlamaCppBackend._bundled_hip_symbol_miss(output or "")
        if _rocm_miss:
            _miss_obj, _miss_sym = _rocm_miss
            return (
                f"llama-server could not start: bundled {_short(os.path.basename(_miss_obj))} "
                f"looked up {_short(_miss_sym)} in a different ROCm than it was built "
                "against. That is a HIP/ROCR version mix, not a missing "
                "binary and not out of VRAM. Try the Vulkan backend, or "
                f"{LlamaCppBackend._runtime_remedy(binary)}."
            )
        if returncode == 127:
            # The updater cannot touch a pinned binary.
            _remedy = (
                "run `unsloth studio update` to reinstall the llama.cpp runtime"
                if LlamaCppBackend._is_unsloth_managed_binary(binary)
                else "reinstall or rebuild that custom llama.cpp"
            )
            return (
                "llama-server exited immediately (status 127): either the "
                "llama-server executable could not be found or run, or one of "
                f"the shared libraries it needs could not be loaded. Check the "
                f"llama-server log, and {_remedy}."
            )

        # SIGKILL with no output is usually the OOM killer.
        if returncode == -9:
            # macOS also SIGKILLs an invalid code signature before any output.
            if sys.platform == "darwin":
                # Log is often empty: name likely causes (incl. macOS SIGKILL); signal 9 may also be a supervisor.
                return LlamaCppBackend._with_startup_diagnostics(
                    "llama-server was stopped by macOS (signal 9) before it "
                    "started. This is most often out of memory, so try a "
                    "smaller or more quantized GGUF, or lower the context "
                    "length. macOS also sends signal 9 when it refuses a "
                    "binary's code signature, so if memory is not the problem, "
                    f"{LlamaCppBackend._runtime_remedy(binary)}.",
                    output,
                    log_path,
                    secrets,
                )
            return (
                "llama-server was stopped by the operating system (signal 9), "
                "most likely out of memory. Try a smaller or more quantized "
                "GGUF, lower the context length, or free memory (on WSL, raise "
                "the memory limit in .wslconfig)."
            )
        # SIGTERM is also how unload/cancel stops the server; report neutrally.
        if returncode == -15:
            return (
                "llama-server was terminated (signal 15) before it became "
                "healthy. If you cancelled or unloaded the model this is "
                "expected; otherwise check the llama-server log for the cause."
            )

        # A startup stall is not a bad GGUF; memory pressure or a proxy intercepting the loopback probe can also cause it.
        if "health check timed out" in lowered:
            return (
                "llama-server started but stopped making progress before it became "
                "healthy on its local /health endpoint. Try a smaller context length or a more "
                "quantized GGUF, and if you use a VPN or HTTP proxy make sure "
                "localhost bypasses it (NO_PROXY=127.0.0.1,localhost)."
            )

        # Fallback: carry the output tail and log path so the report is actionable.
        return LlamaCppBackend._with_startup_diagnostics(
            "llama-server failed to start. "
            "Check that the GGUF file is valid and you have enough memory.",
            output,
            log_path,
            secrets,
        )

    # Bounded so a chatty server cannot flood an API error.
    _STARTUP_TAIL_CHARS = 2000

    # Labels _with_startup_diagnostics writes, used to stay idempotent. Keep in sync with the writer.
    _DIAGNOSTICS_MARKERS = ("llama-server output:", "Full log: ")

    # Token shapes redacted on sight, whatever the variable name.
    _SECRET_VALUE_RES = (
        re.compile(r"hf_(?:oauth_[A-Za-z0-9._~+/=-]{20,}|[A-Za-z0-9]{20,})"),
        re.compile(r"github_pat_[A-Za-z0-9_]{20,}"),
        re.compile(r"gh[pousr]_[A-Za-z0-9]{20,}"),
        re.compile(r"sk-[A-Za-z0-9_\-]{20,}"),
        # HTTP credentials. Full RFC 9110 token68 class so no base64 tail survives.
        re.compile(r"(?i)(?:bearer|basic)\s+[A-Za-z0-9._~+/\-]+=*"),
        # Our own --api-key matches no shape and is in no env var.
        re.compile(r"(?<=--api-key )\S+"),
        re.compile(r"(?<=--api-key=)\S+"),
        # URL userinfo: keep the scheme, drop the credential.
        re.compile(r"(?<=://)[^/@\s]+(?=@)"),
    )

    # NAME = value in shell, JSON or bare form; the unterminated-quote arm must come after the quoted one; names may contain hyphen and dot.
    _SECRET_ASSIGNMENT_RE = re.compile(
        r"""(?P<q>["']?)(?P<name>[A-Za-z_][A-Za-z0-9_.\-]{0,63})(?P=q)
            (?P<sep>[ \t]*[=:][ \t]*)
            (?:(?P<vq>["'])(?P<qval>(?:\\.|(?!(?P=vq))[^\\])*)(?P=vq)
             |  (?P<uq>["'])(?P<uval>[^\r\n]*)
             |  (?P<val>[^\s,;]+))""",
        re.VERBOSE,
    )

    @staticmethod
    def _redact_secret_assignments(text: str) -> str:
        """Replaces whatever follows a secret-looking name, so escaping or quoting cannot hide the value."""
        try:
            from utils.prebuilt.child_env import is_secret_env_name
        except Exception:  # noqa: BLE001 - redaction must never break a load error
            return text

        def sub(m: "re.Match[str]") -> str:
            # Normalise hyphen and dot to underscore before asking the predicate: its markers are underscored, so api-key missed while api_key matched.
            name = m.group("name")
            if not is_secret_env_name(name.replace("-", "_").replace(".", "_")):
                return m.group(0)
            q, vq, uq = m.group("q"), m.group("vq"), m.group("uq")
            if vq:
                body = f"{vq}***{vq}"
            elif uq:
                # Unterminated: keep the opening delimiter, drop the rest; do not invent a closing quote.
                body = f"{uq}***"
            else:
                body = "***"
            return f"{q}{m.group('name')}{q}{m.group('sep')}{body}"

        try:
            return LlamaCppBackend._SECRET_ASSIGNMENT_RE.sub(sub, text)
        except Exception:  # noqa: BLE001
            return text

    @staticmethod
    def _scrub_secret_values(text: str, extra: Sequence[Optional[str]] = ()) -> str:
        """Redacts env values by value and by secret-looking name, since each alone misses something."""
        if not text:
            return text
        cleaned = LlamaCppBackend._redact_secret_assignments(text)
        # Minted secrets plus env values, replaced longest first since credentials can overlap.
        literals = {literal for literal in extra if literal and len(literal) >= 8}
        # Reuse the managed-server denylist by name so the two cannot drift; URL userinfo is withheld whatever its name.
        try:
            from utils.prebuilt.child_env import URL_USERINFO_RE, is_secret_env_name
            for name, value in os.environ.items():
                if not value:
                    continue
                secret_name = is_secret_env_name(name)
                if len(value) < 8:
                    # Too short to replace globally, so redact only next to its (optionally quoted) name.
                    if secret_name:
                        cleaned = re.sub(
                            rf"([\"']?{re.escape(name)}[\"']?\s*[=:]\s*)"
                            rf"([\"']?){re.escape(value)}\2",
                            r"\1\2***\2",
                            cleaned,
                        )
                    continue
                if secret_name or URL_USERINFO_RE.search(value):
                    literals.add(value)
        except Exception:  # noqa: BLE001 - redaction must never break a load error
            pass
        for literal in sorted(literals, key = len, reverse = True):
            cleaned = cleaned.replace(literal, "***")
        # By shape, for credentials not present in our environment to match on.
        for pattern in LlamaCppBackend._SECRET_VALUE_RES:
            cleaned = pattern.sub("***", cleaned)
        return cleaned

    @staticmethod
    def _has_startup_diagnostics(text: str) -> bool:
        """Matches our framing, not bare marker words, so a server echoing them still gets its tail."""
        return text.startswith(LlamaCppBackend._DIAGNOSTICS_MARKERS) or any(
            f"\n\n{marker}" in text for marker in LlamaCppBackend._DIAGNOSTICS_MARKERS
        )

    # Caps window widening so a pathological env value cannot force a full-output scan.
    _MAX_SECRET_SCAN_CHARS = 262144

    @staticmethod
    def _max_secret_len(extra: Sequence[Optional[str]] = ()) -> int:
        """Longest value _scrub_secret_values could be asked to match, capped."""
        longest = 0
        for literal in extra:
            if literal:
                longest = max(longest, len(literal))
        try:
            from utils.prebuilt.child_env import URL_USERINFO_RE, is_secret_env_name
            for name, value in os.environ.items():
                if not value or len(value) <= longest:
                    continue
                if is_secret_env_name(name) or URL_USERINFO_RE.search(value):
                    longest = len(value)
        except Exception:  # noqa: BLE001 - a narrower window still redacts most
            pass
        return min(longest, LlamaCppBackend._MAX_SECRET_SCAN_CHARS)

    @staticmethod
    def _with_startup_diagnostics(
        message: str,
        output: Optional[str],
        log_path: "Optional[Path | str]",
        extra_secrets: Sequence[Optional[str]] = (),
    ) -> str:
        """Appends the output tail and log path to message, returning it unchanged when neither exists; a message already carrying the block is returned as is."""
        if LlamaCppBackend._has_startup_diagnostics(message):
            return message
        parts = [message]
        # Slice before filtering (runaway lines), widened by the longest secret so a long
        # credential cannot straddle the cut and escape redaction.
        _window = LlamaCppBackend._STARTUP_TAIL_CHARS * 4 + LlamaCppBackend._max_secret_len(
            extra_secrets
        )
        raw = (output or "")[-_window:]
        # Strip control characters (progress bars, colour codes) from API error tails; keep newlines and tabs.
        tail = "".join(ch for ch in raw if ch in "\n\t" or ch.isprintable()).strip()
        if tail:
            tail = LlamaCppBackend._scrub_secret_values(tail, extra_secrets)
            tail = tail[-LlamaCppBackend._STARTUP_TAIL_CHARS :].lstrip()
            parts.append(f"llama-server output:\n{tail}")
        if log_path:
            parts.append(f"Full log: {log_path}")
        return "\n\n".join(parts)

    def _plan_tensor_parallel(
        self,
        gpus: list[tuple[int, int]],
        model_size: int,
        target_ctx: int,
        cache_type_kv: Optional[str] = None,
        n_parallel: int = 1,
        mtp_engaged: bool = False,
        mtp_overhead_fn: Optional[Callable[[int], int]] = None,
        mtp_flat_reserve_bytes: int = 0,
        max_target_ctx: Optional[int] = None,
        total_by_idx: Optional[dict[int, int]] = None,
        n_ubatch: Optional[int] = None,
        soft_overhead_bytes: int = 0,
        swa_full: bool = False,
        kv_unified: bool = True,
        flash_attn: bool = True,
        vram_fraction: Optional[float] = None,
        scratch_cache_type_kv: Optional[str] = None,
        explicit_ctx: bool = False,
    ) -> tuple[int, int, list[int], Optional[list[int]]]:
        """Plans a --split-mode tensor load, capping context to pooled VRAM; if KV cannot be sized it may shrink Auto but never overrule an explicit context."""
        _tp_frac = vram_fraction if vram_fraction is not None else _active_vram_fraction()

        _tp_sysmem_fallback = LlamaCppBackend._sysmem_fallback_risk()

        def _usable(idx: int, free_mib: int) -> float:
            # Clamped on both branches: this pool is summed, so a negative card must not fund another.
            t = total_by_idx.get(idx, 0) if total_by_idx else 0
            return max(
                0.0,
                _vram_usable_mib(free_mib, t, _tp_frac, sysmem_fallback = _tp_sysmem_fallback),
            )

        # Drop GPUs whose usable budget cannot hold the per-device compute buffer (OOM in TP).
        _reserve_bytes = self._estimate_compute_buffer_bytes(
            n_ubatch = n_ubatch, n_parallel = n_parallel, per_device_tensor = True
        )
        reserve_mib = (
            _reserve_bytes // (1024 * 1024)
            if _reserve_bytes > 0
            else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB
        )
        usable_gpus = [g for g in gpus if _usable(g[0], g[1]) >= reserve_mib]
        gpu_indices = sorted(idx for idx, _ in usable_gpus)
        if len(gpu_indices) < 2:
            # Tensor parallelism is meaningless below 2 GPUs; the caller drops it, so never emit a split.
            return (
                target_ctx if target_ctx > 0 else 4096,
                target_ctx if target_ctx > 0 else 4096,
                gpu_indices,
                None,
            )
        free_by_idx = {idx: free for idx, free in usable_gpus}
        usable_by_idx = {idx: _usable(idx, free_by_idx[idx]) for idx in gpu_indices}
        pool_mib = sum(usable_by_idx.values())
        # Flat MTP cushion for what the byte fn cannot size; without it the search OOMs.
        flat_mtp_bytes = max(0, mtp_flat_reserve_bytes)
        if mtp_engaged and mtp_overhead_fn is None:
            flat_mtp_bytes = max(flat_mtp_bytes, 2 * 1024**3)
        # Tensor mode has no --fit valve, so charge the soft overhead here too (pooled, once).
        kv_budget_b = (
            (pool_mib - len(gpu_indices) * reserve_mib) * 1024 * 1024
            - model_size
            - flat_mtp_bytes
            - max(0, soft_overhead_bytes)
        )

        def _mtp_at(ctx: int) -> int:
            return mtp_overhead_fn(ctx) if mtp_overhead_fn is not None else 0

        def _kv_at(ctx: int) -> int:
            return self._estimate_kv_cache_bytes(
                ctx,
                cache_type_kv,
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )

        # Tensor mode replicates the compute graph on every device, so growth is n_dev x per-device.
        # Priced from the lighter KV axis so a q4 axis keeps its dequant scratch.
        n_dev = len(gpu_indices)
        cc_cache_type = (
            scratch_cache_type_kv if scratch_cache_type_kv is not None else cache_type_kv
        )

        def _cc_ctx(ctx: int) -> int:
            # Same state _kv_at prices with: the mask is f32 whenever tensor mode does not answer True.
            return n_dev * self._compute_buffer_ctx_bytes(
                ctx, n_ubatch, cc_cache_type, flash_attn = flash_attn
            )

        def _fit_ctx(ctx: int) -> int:
            # Largest ctx whose KV, MTP reserve and compute fit the pooled budget; never above an explicit ctx.
            if self._can_estimate_kv() and ctx > 0:
                ctx_floor = min(2048, ctx)
                if kv_budget_b <= 0:
                    # If weights and buffers exceed the pool, use the floor; the load then falls back to layer split.
                    return ctx_floor

                def _consumer(c: int) -> int:
                    return _kv_at(c) + _mtp_at(c) + _cc_ctx(c)

                if _consumer(ctx) <= kv_budget_b:
                    return ctx
                lo, hi, best = ctx_floor, ctx, ctx_floor
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if _consumer(mid) <= kv_budget_b:
                        best = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1
                return best
            # KV size unknown -> can't prove a safe cap; floor.
            return min(_TP_UNMEASURED_CTX, ctx) if ctx > 0 else _TP_UNMEASURED_CTX

        # Hardware ceiling for the UI bound, independent of an explicit small -c.
        max_ctx_target = max_target_ctx if (max_target_ctx and max_target_ctx > 0) else target_ctx
        max_available_ctx = _fit_ctx(max_ctx_target)
        effective_ctx = min(_fit_ctx(target_ctx), max_available_ctx)
        if not self._can_estimate_kv() and explicit_ctx and target_ctx > 0:
            # Never apply the guessed min() to an explicitly typed context.
            effective_ctx = target_ctx
            max_available_ctx = max(max_available_ctx, effective_ctx)

        min_usable_mib = min(usable_by_idx.values())
        kv_bytes = _kv_at(effective_ctx) if (self._can_estimate_kv() and effective_ctx > 0) else 0
        # The MTP reserve must also fit the even split: per-ctx bytes plus the same flat cushion.
        mtp_bytes = (_mtp_at(effective_ctx) if effective_ctx > 0 else 0) + flat_mtp_bytes
        # Context-linear compute is replicated per device, so charge the whole split, as kv_budget_b does.
        cc_bytes = _cc_ctx(effective_ctx) if effective_ctx > 0 else 0
        even_share_mib = (
            (model_size + kv_bytes + mtp_bytes + cc_bytes) / len(gpu_indices) / (1024 * 1024)
        )
        tensor_split: Optional[list[int]] = None
        if even_share_mib > (min_usable_mib - reserve_mib):
            # Subtract the replicated compute share per device, or the smaller card is overweighted.
            cc_per_dev_mib = (cc_bytes // len(gpu_indices)) // (1024 * 1024) if cc_bytes else 0
            adj = [
                max(0, int(usable_by_idx[i] - reserve_mib - cc_per_dev_mib)) for i in gpu_indices
            ]
            if sum(adj) > 0:
                tensor_split = adj
        return effective_ctx, max_available_ctx, gpu_indices, tensor_split

    def _tensor_split_fits_budget(
        self,
        split: list[float],
        gpus: list[tuple[int, int]],
        gpu_indices: list[int],
        model_size: int,
        effective_ctx: int,
        cache_type_kv: Optional[str] = None,
        n_parallel: int = 1,
        n_ubatch: Optional[int] = None,
        kv_unified: bool = True,
        flash_attn: bool = True,
        swa_full: bool = False,
        mtp_engaged: bool = False,
        mtp_overhead_fn: Optional[Callable[[int], int]] = None,
        mtp_flat_reserve_bytes: int = 0,
        total_by_idx: Optional[dict[int, int]] = None,
        vram_fraction: Optional[float] = None,
        soft_overhead_bytes: int = 0,
        scratch_cache_type_kv: Optional[str] = None,
    ) -> bool:
        """Mirrors the planner budget, including soft_overhead and the lighter K/V type, or it is
        optimistic."""
        if not split or sum(split) <= 0 or len(split) != len(gpu_indices):
            return False

        _tp_frac = vram_fraction if vram_fraction is not None else _active_vram_fraction()
        # Must match the planner's floor, or this passes splits the planner rejected.
        _tp_sysmem_fallback = LlamaCppBackend._sysmem_fallback_risk()

        def _usable(idx: int, free_mib: int) -> float:
            t = total_by_idx.get(idx, 0) if total_by_idx else 0
            return max(
                0.0,
                _vram_usable_mib(free_mib, t, _tp_frac, sysmem_fallback = _tp_sysmem_fallback),
            )

        free_by_idx = {idx: free for idx, free in gpus}
        # Fail closed: gpus and gpu_indices can disagree; an unpriceable budget is not a pass.
        if any(idx not in free_by_idx for idx in gpu_indices):
            return False
        usable_by_idx = {idx: _usable(idx, free_by_idx[idx]) for idx in gpu_indices}

        _reserve_bytes = self._estimate_compute_buffer_bytes(
            n_ubatch = n_ubatch, n_parallel = n_parallel, per_device_tensor = True
        )
        reserve_mib = (
            _reserve_bytes // (1024 * 1024)
            if _reserve_bytes > 0
            else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB
        )

        flat_mtp = max(0, mtp_flat_reserve_bytes)
        if mtp_engaged and mtp_overhead_fn is None:
            flat_mtp = max(flat_mtp, 2 * 1024**3)

        kv_bytes = (
            self._estimate_kv_cache_bytes(
                effective_ctx,
                cache_type_kv,
                n_parallel = n_parallel,
                swa_full = swa_full,
                kv_unified = kv_unified,
                n_ubatch = n_ubatch,
                flash_attn = flash_attn,
            )
            if self._can_estimate_kv() and effective_ctx > 0
            else 0
        )
        mtp_bytes = (
            mtp_overhead_fn(effective_ctx) if mtp_overhead_fn is not None else 0
        ) + flat_mtp
        # Replicated, not split: every device allocates the whole buffer, so charge it flat per device.
        cc_per_device_bytes = self._compute_buffer_ctx_bytes(
            effective_ctx,
            n_ubatch,
            scratch_cache_type_kv or cache_type_kv,
            # Same state as the KV above.
            flash_attn = flash_attn,
        )
        total_bytes = model_size + kv_bytes + mtp_bytes + max(0, soft_overhead_bytes)

        total_weight = sum(split)
        for i, idx in enumerate(gpu_indices):
            alloc_bytes = total_bytes * split[i] / total_weight
            capacity_bytes = (usable_by_idx[idx] - reserve_mib) * 1024 * 1024 - cc_per_device_bytes
            if alloc_bytes > capacity_bytes:
                return False
        return True

    @staticmethod
    def _with_mmproj_offload_disabled(
        cmd: Sequence[str], env: Optional[Mapping[str, str]] = None
    ) -> Optional[List[str]]:
        """Returns a retry argv with the projector pinned to CPU at the end, since llama.cpp boolean flags are last-wins; None when no projector or already on CPU."""
        args = [str(arg) for arg in cmd]

        def _flag(token: str) -> str:
            return token.split("=", 1)[0].replace("_", "-").lower()

        if not any(_flag(arg) in ("--mmproj", "-mm") for arg in args):
            return None
        # Only a resolved False means on CPU; argv and env at arg.cpp precedence (LLAMA_ARG_NO_MMPROJ_OFFLOAD, disabled token); explicit --mmproj-offload is overridden.
        if _resolved_mmproj_offload(args, env or {}) is False:
            return None
        placements = [
            _flag(arg) for arg in args if _flag(arg) in ("--mmproj-offload", "--no-mmproj-offload")
        ]
        if not placements:
            # Deliberate superset of the resolution above: arg.cpp rejects 'no', so no retry helps.
            env_value = str((env or {}).get(_MMPROJ_OFFLOAD_ENV_VAR) or "").strip().lower()
            if env_value in ("0", "false", "off", "no"):
                return None
        return args + ["--no-mmproj-offload"]

    @staticmethod
    def _is_gpu_memory_start_failure(output: str) -> bool:
        """Whether startup output ties allocation pressure to a GPU backend."""
        lines = (output or "").lower().splitlines()
        allocation_markers = (
            "out of memory",
            "failed to allocate",
            "cudamalloc failed",
            "hiperroroutofmemory",
            "vk_error_out_of_device_memory",
        )
        gpu_markers = (
            "cuda",
            "hiperror",
            "hipmalloc",
            "ggml_backend_hip",
            "rocm",
            "vulkan",
            "vk_",
            "metal",
            "sycl",
            "oneapi",
            "musa",
            "gpu",
            "device memory",
        )
        return any(
            any(marker in line for marker in allocation_markers)
            and any(marker in line for marker in gpu_markers)
            for line in lines
        )

    @staticmethod
    def _is_projector_incompatibility(output: str) -> bool:
        """Matches only projector-format errors, so OOM or bad-GGUF failures keep their own handling."""
        text = (output or "").lower()
        if any(
            m in text
            for m in (
                "unknown projector type",
                "unsupported projector",
                "unsupported mmproj",
            )
        ):
            return True
        # Builds that phrase it via clip.cpp without the exact words above.
        return (
            "clip" in text
            and "projector" in text
            and ("unknown" in text or "unsupported" in text or "not supported" in text)
        )

    @staticmethod
    def _mmproj_retry_failure_message(*, projector_confirmed: bool, detail: str) -> str:
        """Only a confirmed projector mismatch keeps the historical wording; bare signal crashes do not."""
        if projector_confirmed:
            return (
                "Vision projector incompatible with this llama.cpp "
                "build, and the text-only retry also failed: " + detail
            )
        return (
            "Vision model failed to start (llama-server crashed with "
            "--mmproj), and the text-only retry also failed: " + detail
        )

    @staticmethod
    def _output_has_nonprojector_diagnostic(output: str) -> bool:
        """Output naming a real non-projector cause, like OOM, must surface instead of a text-only retry."""
        text = (output or "").lower()
        return any(
            m in text
            for m in (
                "out of memory",
                "failed to allocate",
                "unknown model architecture",
                "split_mode_tensor not implemented",
                LlamaCppBackend._TENSOR_QUANT_KV_UNSUPPORTED_MARKER,
            )
        )

    # llama.cpp before b9455 refused quantized KV under --split-mode tensor with a clean exit 1;
    # this marker avoids two doomed loads on older binaries.
    _TENSOR_QUANT_KV_UNSUPPORTED_MARKER = (
        "split_mode_tensor and kv cache quantization not implemented"
    )

    @classmethod
    def _is_tensor_quant_kv_unsupported(cls, output: str) -> bool:
        """Matches the quantized-KV tensor-mode refusal; no retry helps, only a different llama.cpp
        build."""
        return cls._TENSOR_QUANT_KV_UNSUPPORTED_MARKER in (output or "").lower()

    @staticmethod
    def _is_tensor_split_assert(output: str) -> bool:
        """True only for the #6415 split-axis warmup assert (GGML_BACKEND_SPLIT_AXIS_*),
        not any ggml assert/abort, so an unrelated invariant isn't cached. stderr is
        merged into output."""
        text = (output or "").lower()
        if "ggml_assert" not in text and "ggml_abort" not in text:
            return False
        # the split-axis enum token, unique to this assert (not the source file).
        return "split_axis" in text

    # Matched on basename so a path component cannot stand in for the object.
    _ROCM_OBJECT_HINTS = ("libamdhip", "libamd_comgr", "libhsa-runtime", "libhip", "libroc")

    # Paired with the binary revision so an old proof does not apply to a newly swapped build.
    _bundle_only_rocm_dirs: dict[str, tuple] = {}
    _bundle_only_rocm_lock = threading.Lock()

    @staticmethod
    def _remember_bundle_only_rocm(binary: str) -> None:
        resolved = _resolve_llama_binary(binary)
        revision = LlamaCppBackend._binary_stamp(resolved)
        with LlamaCppBackend._bundle_only_rocm_lock:
            LlamaCppBackend._bundle_only_rocm_dirs[str(resolved.parent)] = revision

    @staticmethod
    def _prefers_bundle_only_rocm(binary: str) -> bool:
        resolved = _resolve_llama_binary(binary)
        revision = LlamaCppBackend._binary_stamp(resolved)
        with LlamaCppBackend._bundle_only_rocm_lock:
            return LlamaCppBackend._bundle_only_rocm_dirs.get(str(resolved.parent)) == revision

    # Build dirs whose system ROCm prepend was already probed, keyed like the latch above.
    _system_rocm_probed: dict[str, tuple] = {}
    _system_rocm_probe_lock = threading.Lock()

    @staticmethod
    def _list_devices_under(binary: str, env: Mapping[str, str]) -> Optional[list[str]]:
        try:
            result = subprocess.run(
                [binary, "--list-devices"],
                capture_output = True,
                encoding = "utf-8",
                errors = "replace",
                timeout = 30,
                env = utf8_child_env(dict(env)),
                **_windows_hidden_subprocess_kwargs(),
            )
        except Exception as e:
            logger.debug(f"llama-server --list-devices failed: {e}")
            return None
        if result.returncode != 0:
            return None
        return _parse_listed_devices(result.stdout)

    @staticmethod
    def _system_rocm_hides_gpu(binary: str, system_dirs: "list[str]") -> bool:
        """True when llama-server lists no GPU with system ROCm first but does with its bundle.

        The prepend crash-proofs hosts whose bundled ROCR mismatches amdkfd (#7208), but
        where the system copy is the mismatched one HIP init fails silently and the server
        runs on CPU (#14906). No crash means the load_model retry never fires, so this asks
        the binary directly, once per build. Any other answer keeps the prepend.
        """
        resolved = _resolve_llama_binary(binary)
        key = str(resolved.parent)
        revision = LlamaCppBackend._binary_stamp(resolved)
        with LlamaCppBackend._system_rocm_probe_lock:
            # A caller that waited out the first probe re-reads its verdict from the latch.
            if LlamaCppBackend._system_rocm_probed.get(key) == revision:
                return LlamaCppBackend._prefers_bundle_only_rocm(binary)
            mixed = LlamaCppBackend._list_devices_under(
                binary,
                LlamaCppBackend._llama_server_env_for_binary(binary, verify_system_rocm = False),
            )
            bundled = None
            if mixed == []:
                bundled = LlamaCppBackend._list_devices_under(
                    binary,
                    LlamaCppBackend._llama_server_env_for_binary(binary, use_system_rocm = False),
                )
            LlamaCppBackend._system_rocm_probed[key] = revision
            if not bundled:
                return False
            logger.warning(
                "llama-server lists no GPU with the system ROCm libraries (%s) ahead of its "
                "bundled runtime, but lists %s without them; using the bundled ROCm runtime.",
                ":".join(system_dirs),
                ", ".join(bundled),
            )
            LlamaCppBackend._remember_bundle_only_rocm(binary)
            return True

    @staticmethod
    def _bundled_hip_symbol_miss(output: str) -> "Optional[tuple[str, str]]":
        """Splits glibc's symbol lookup error at ': undefined symbol:', so paths with spaces stay whole."""
        match = re.search(
            r"symbol lookup error:[ \t]*([^\r\n]{1,4096}?):"
            r"[ \t]*undefined symbol:[ \t]*([^\s,]+)",
            output or "",
        )
        if not match:
            return None
        obj = os.path.basename(match.group(1)).lower()
        if not obj.startswith(LlamaCppBackend._ROCM_OBJECT_HINTS):
            return None
        return match.group(1), match.group(2)

    @staticmethod
    def _is_bundled_hip_rocr_mismatch(output: str) -> bool:
        return LlamaCppBackend._bundled_hip_symbol_miss(output) is not None

    @staticmethod
    def _is_sched_reserve_abort(output: str) -> bool:
        """GGML_ASSERT(*cur_backend_id != -1); matches backtrace frames, which outlive the [New LWP] dump."""
        text = (output or "").lower()
        if "ggml_assert" not in text and "ggml_abort" not in text:
            return False
        # The #6415 split-axis abort shares the frame but has its own latch.
        if "split_axis" in text:
            return False
        if "cur_backend_id" in text:
            return True
        # Never sched_reserve / graph_reserve alone (reserve-time OOM passes through them).
        if "failed to initialize context" in text or "ggml_assert(" in text:
            return False
        return "ggml_backend_sched_split_graph" in text

    @staticmethod
    def _sched_reserve_abort_message() -> str:
        return (
            "llama.cpp aborted while reserving the compute graph "
            "(GGML_ASSERT(*cur_backend_id != -1)): no backend can place part of this model's "
            "graph. Either this llama.cpp build lacks an operation the model needs on this "
            "device (common for new attention types on CPU), or the model does not fit in "
            "memory. Try `unsloth studio update` for a newer llama.cpp, a smaller "
            "quantization, a lower context length, or turning off speculative decoding."
        )

    @staticmethod
    def _is_signal_crash(returncode: Optional[int]) -> bool:
        """Hard faults only: SIGKILL, SIGTERM and SIGINT are excluded since they mean OOM kill or unload."""
        if returncode is None:
            return False
        if returncode >= 0xC0000000:  # Windows access violation / illegal instruction
            return True
        return -returncode in (4, 6, 7, 8, 11)  # SIGILL SIGABRT SIGBUS SIGFPE SIGSEGV

    @staticmethod
    def _is_abort_exit(returncode: Optional[int]) -> bool:
        """Windows CRT abort() exit code (3) from GGML_ASSERT on MSVC -- not a POSIX
        signal or 0xC0000000+ NTSTATUS."""
        return returncode == 3

    @classmethod
    def _should_record_tensor_split_abort(cls, returncode: Optional[int], output: str) -> bool:
        """The #6415 split-axis abort: the marker plus a hard crash (POSIX signal or
        Windows abort exit). Marker required so a generic crash isn't cached."""
        return cls._is_tensor_split_assert(output) and (
            cls._is_signal_crash(returncode) or cls._is_abort_exit(returncode)
        )

    # ROCm arch-mismatch crash: deterministic, only a different device helps.
    # clr reports it with four different codes.
    _KERNEL_IMAGE_INVALID_MARKERS = (
        "device kernel image is invalid",  # hipErrorInvalidImage
        "no kernel image is available for execution",  # hipErrorNoBinaryForGpu
        "invalid kernel file",  # hipErrorInvalidKernelFile
        "invalid device function",  # hipErrorInvalidDeviceFunction
    )

    @classmethod
    def _kernel_image_invalid(cls, output: str) -> bool:
        # Case-folded, since hipGetErrorString is lowercase but the layers that reprint it vary in case.
        text = (output or "").lower()
        return any(marker in text for marker in cls._KERNEL_IMAGE_INVALID_MARKERS)

    # #12842. A HIP build prints "ROCm error:", so the #7624 crash never matches. Every
    # kernel fails alike, so no fit, flash-attn, slot or drafter retry can help.
    _CUDA_KERNEL_IMAGE_RE = re.compile(
        r"\bCUDA error: (device kernel image is invalid|no kernel image is available for execution)",
        re.IGNORECASE,
    )

    @classmethod
    def _cuda_kernel_image_error(cls, output: str) -> Optional[str]:
        """The CUDA kernel-image error text in ``output`` (lowercased), or None."""
        match = cls._CUDA_KERNEL_IMAGE_RE.search(output or "")
        return match.group(1).lower() if match else None

    @staticmethod
    def _cuda_install_driver_version(binary: Optional[str]) -> Optional[tuple[int, int]]:
        """The driver CUDA version the installer recorded for the managed install that
        owns ``binary`` (UNSLOTH_PREBUILT_INFO.json host_profile), or None."""
        try:
            from utils.llama_cpp_update import _llama_install_root

            root = _llama_install_root(binary) if binary else None
            if root is None:
                return None
            marker = json.loads((root / "UNSLOTH_PREBUILT_INFO.json").read_text(encoding = "utf-8"))
            driver = (marker.get("host_profile") or {}).get("driver_cuda_version")
            if isinstance(driver, list) and len(driver) == 2:
                return (int(driver[0]), int(driver[1]))
        except Exception:
            pass
        return None

    @classmethod
    def _cuda_kernel_image_message(
        cls,
        error: str,
        binary: Optional[str],
        log_path: "Optional[Path | str]" = None,
    ) -> str:
        remedy = cls._runtime_remedy(binary)
        log_hint = f" Full log: {log_path}" if log_path else ""
        if error == "no kernel image is available for execution":
            return (
                'llama-server could not load its CUDA kernels ("no kernel image is available '
                "for execution\"): this llama.cpp CUDA build has no kernels for this GPU's "
                "architecture. This is not the GGUF file and not out of memory. "
                f"{remedy[0].upper()}{remedy[1:]}, or use the CPU or Vulkan backend.{log_hint}"
            )
        driver = cls._cuda_install_driver_version(binary)
        if driver is not None and driver >= (12, 4):
            return (
                'llama-server could not load its CUDA kernels ("device kernel image is '
                f'invalid") although this NVIDIA driver supports CUDA {driver[0]}.{driver[1]}: '
                "the llama.cpp CUDA libraries look damaged or mismatched. This is not the "
                f"GGUF file and not out of memory. {remedy[0].upper()}{remedy[1:]}.{log_hint}"
            )
        driver_text = (
            f" (this NVIDIA driver supports CUDA {driver[0]}.{driver[1]})" if driver else ""
        )
        return (
            'llama-server could not load its CUDA kernels ("device kernel image is '
            'invalid"): the NVIDIA driver is most likely too old for this llama.cpp CUDA '
            f"build{driver_text}, which needs CUDA 12.4 or newer. This is not the GGUF file "
            "and not out of memory. Update the NVIDIA driver to R550 or newer (CUDA 12.4+), "
            f"or {remedy}.{log_hint}"
        )

    @classmethod
    def _arch_crash_retry_gpu_ids(cls, selected, enumerated) -> list[int]:
        """Prefers GPUs the failed launch never touched; else drops unified-memory devices, where
        this recurs."""
        _selected = set(selected or ())
        if not _selected:
            return []
        remaining = sorted(i for i in set(enumerated or ()) if i not in _selected)
        if remaining or len(_selected) < 2:
            return remaining
        try:
            discrete = sorted(_selected - cls._rocm_unified_memory_gpu_ids())
        except Exception:
            return []
        return discrete if 0 < len(discrete) < len(_selected) else []

    @staticmethod
    def _cache_tuning_target_unknown(
        extra_args: Optional[Iterable[str]], device_flags_owned: bool, env: Mapping[str, str]
    ) -> bool:
        """Fails closed: a user device pick can redirect the child, so the target device is unknown."""
        if device_flags_owned:
            return False
        return bool(
            _extra_args_set_any_flag(extra_args, _DEVICE_FLAGS)
            or str(env.get("LLAMA_ARG_DEVICE", "")).strip()
        )

    @staticmethod
    def _retry_cache_tuning_flags(
        cmd: list[str],
        *,
        cache_ram: Optional[int],
        ctx_checkpoints: Optional[int],
        server_caps: Mapping[str, Any],
    ) -> list[str]:
        """Skips any cache setting the command already states, since appended flags win the last-
        wins parse."""
        # Short spellings state the setting too; appending after one would clobber the user's value.
        stated = {_flag_name(str(token)) for token in cmd}
        flags: list[str] = []
        if (
            cache_ram is None
            and server_caps.get("supports_cache_ram")
            and not (_CACHE_RAM_FLAGS & stated)
        ):
            flags.extend(["--cache-ram", "0"])
        checkpoints_flag = server_caps.get("ctx_checkpoints_flag")
        if ctx_checkpoints is None and checkpoints_flag and not (_CTX_CHECKPOINTS_FLAGS & stated):
            flags.extend([str(checkpoints_flag), "0"])
        return flags

    @staticmethod
    def _without_flag_pairs(cmd: list[str], pairs: list[str]) -> list[str]:
        """Safe only for pairs this process emitted: a two-token step would swallow a following user
        extra."""
        out = list(cmd)
        for index in range(0, len(pairs) - 1, 2):
            flag, value = pairs[index], pairs[index + 1]
            for at in range(len(out) - 1):
                if out[at] == flag and out[at + 1] == value:
                    del out[at : at + 2]
                    break
        return out

    @staticmethod
    def _without_tensor_split(cmd: list[str]) -> Optional[list[str]]:
        """Drops the flag: split shares are positional over visible devices, and masking re-indexes them."""
        return LlamaCppBackend._without_flags(cmd, ("--tensor-split", "-ts"))

    @staticmethod
    def _without_flags(cmd: list[str], names: Collection[str]) -> Optional[list[str]]:
        """Value-taking flags only: a valueless one such as --mlock would drop the next argv entry."""
        out: list[str] = []
        found = False
        skip = False
        for tok in cmd:
            if skip:
                skip = False
                continue
            token = str(tok)
            if _flag_name(token) in names:
                found = True
                skip = "=" not in token
                continue
            out.append(token)
        return out if found else None

    @staticmethod
    def _requires_symmetric_kv(kv_lora_rank, architecture) -> bool:
        """Whether llama.cpp rejects K != V for a model with this metadata.

        Mirrors ``is_mla() || arch == LLM_ARCH_DEEPSEEK4 || arch == LLM_ARCH_DEEPSEEK41``:
        kv_lora_rank stands in for is_mla() (the MLA archs' converter writes it
        alongside the MLA head dims), and deepseek4 / deepseek41 are checked by name
        because they set neither.
        """
        if kv_lora_rank is not None:
            return True
        return (architecture or "").strip().lower() in ("deepseek4", "deepseek41")

    def _target_kv_symmetry(self) -> bool:
        """Whether the TARGET model requires K == V."""
        return self._requires_symmetric_kv(self._kv_lora_rank, getattr(self, "_architecture", None))

    def _draft_kv_symmetry(
        self,
        cmd: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[bool]:
        """Reads the drafter the command names, not the stored sidecar; an unreadable one counts as True."""
        path, is_remote = _extra_args_mtp_draft_source(list(cmd or []), env)
        if not path:
            return None
        if is_remote:  # a repo id is not a local file whose metadata can be read
            return True
        try:
            db = self._draft_backend_for(path)
        except Exception:
            db = None
        if db is None:  # named but unreadable -> conservative, not the target
            return True
        return self._requires_symmetric_kv(
            getattr(db, "_kv_lora_rank", None), getattr(db, "_architecture", None)
        )

    @staticmethod
    def _reset_quantized_v_cache(
        cmd: list[str],
        reason: str,
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> list[str]:
        """Quantized V needs flash attention, so it goes to f16; MLA and DeepSeek4 reset K to f16 as
        well."""
        out = list(cmd)
        _v_cache_flags = (
            "--cache-type-v",
            "-ctv",
            "--cache-type-v-draft",
            "--spec-draft-type-v",
            "-ctvd",
        )
        _cache_reset = False
        for i, tok in enumerate(out):
            # llama.cpp rewrites '_' to '-' in '--' flags, so match underscore aliases too.
            name = _flag_name(tok)
            if name not in _v_cache_flags:
                continue
            if "=" in tok:
                flag, _, value = tok.partition("=")
                if value.strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i] = f"{flag}=f16"
                    _cache_reset = True
            elif i + 1 < len(out):
                if out[i + 1].strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i + 1] = "f16"
                    _cache_reset = True
        # MLA rejects K != V, so K follows V; gated per model, and an unreadable drafter counts as MLA.
        _main_k_flags = ("--cache-type-k", "-ctk")
        _draft_k_flags = ("--cache-type-k-draft", "--spec-draft-type-k", "-ctkd")
        if draft_mla is None:
            draft_mla = mla
        _k_cache_flags = (_main_k_flags if mla else ()) + (_draft_k_flags if draft_mla else ())
        _k_reset = False
        for i, tok in enumerate(out):
            if _flag_name(tok) not in _k_cache_flags:
                continue
            if "=" in tok:
                flag, _, value = tok.partition("=")
                if value.strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i] = f"{flag}=f16"
                    _k_reset = True
            elif i + 1 < len(out):
                if out[i + 1].strip().lower() not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                    out[i + 1] = "f16"
                    _k_reset = True
        if _cache_reset or _k_reset:
            logger.info(
                "KV cache dtype reset to f16 because flash attention is off (%s): a "
                "quantized V cache requires flash attention in llama.cpp. %s",
                reason,
                (
                    "The K cache went down with it: this model uses MLA, which "
                    "rejects different K and V cache types."
                    if _k_reset
                    else "The K cache is left untouched."
                ),
            )
        return out

    @staticmethod
    def _with_flash_attn_off(
        cmd: list[str],
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> Optional[list[str]]:
        """Turns flash attention off; a bare --flash-attn is dropped, since older builds take no value."""
        out = list(cmd)

        def explicit(i):
            nxt = out[i + 1] if i + 1 < len(out) else None
            return nxt if nxt in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES else None

        effective = None
        for i, tok in enumerate(out):
            name = _flag_name(tok)
            if name in ("--flash-attn", "-fa") and "=" in tok:
                effective = tok.partition("=")[2]
            elif name in ("--flash-attn", "-fa"):
                effective = explicit(i) or "on"
        if effective not in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
            return None
        # A bare flag cannot take =off, so dropping the token disables FA; remove back to front.
        bare_at: list[int] = []
        for i, tok in enumerate(out):
            name = _flag_name(tok)
            if name in ("--flash-attn", "-fa") and "=" in tok:
                flag, _, value = tok.partition("=")
                if value in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
                    out[i] = f"{flag}=off"
            elif name in ("--flash-attn", "-fa"):
                if explicit(i) in _LLAMA_ARG_TRUE_OR_AUTO_VALUES:
                    out[i + 1] = "off"
                elif explicit(i) is None:  # bare flag (reads as on) -> drop it
                    bare_at.append(i)
        for i in reversed(bare_at):
            del out[i]

        # Quantized V is legal with FA on but would crash this FA-off retry.
        return LlamaCppBackend._reset_quantized_v_cache(
            out,
            "disabled by the crash-recovery fallback",
            mla = mla,
            draft_mla = draft_mla,
        )

    @staticmethod
    def _drop_env_quantized_v_cache(
        env: MutableMapping[str, str],
        *,
        mla: bool = False,
        draft_mla: Optional[bool] = None,
    ) -> bool:
        """Env-only quantized V caches would abort the FA-off retry; MLA also drops the K env vars."""
        dropped = False
        variables = ["LLAMA_ARG_CACHE_TYPE_V", "LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_V"]
        if draft_mla is None:
            draft_mla = mla
        if mla:
            variables.append("LLAMA_ARG_CACHE_TYPE_K")
        if draft_mla:
            variables.append("LLAMA_ARG_SPEC_DRAFT_CACHE_TYPE_K")
        for var in variables:
            value = (env.get(var) or "").strip().lower()
            if value and value not in LlamaCppBackend._NON_QUANTIZED_KV_TYPES:
                env.pop(var, None)
                dropped = True
        return dropped

    @staticmethod
    def _drop_env_flash_attn(env: MutableMapping[str, str]) -> bool:
        """Env is read before argv, and older builds cannot negate a bare --flash-attn; drop the env var."""
        return env.pop("LLAMA_ARG_FLASH_ATTN", None) is not None

    # Matched on wording, not architecture name.
    _KV_UNIFIED_REFUSED_MARKERS = (
        "a unified kv cache is only supported with a single sequence",
        "needs one sequence per stream",
    )

    @staticmethod
    def _is_kv_unified_refused(output: str) -> bool:
        low = (output or "").lower()
        return any(marker in low for marker in LlamaCppBackend._KV_UNIFIED_REFUSED_MARKERS)

    @staticmethod
    def _with_single_sequence(cmd: list[str]) -> Optional[list[str]]:
        """Reverses Studio's own --kv-unified choice above one slot; every parallel-flag alias is
        removed."""
        out: list[str] = []
        saw_kv_unified = False
        multi_slot = False
        skip_value = False
        for i, tok in enumerate(cmd):
            if skip_value:
                skip_value = False
                continue
            name = _flag_name(tok)
            if name in ("--kv-unified", "-kvu"):
                saw_kv_unified = True
                # The flag is bare, but an inline "=1" or a separate "1" reach us.
                if (
                    "=" not in tok
                    and cmd[i + 1 : i + 2]
                    # Case-sensitive, like llama.cpp's own bool parse.
                    and cmd[i + 1] in _LLAMA_ARG_TRUE_FALSE_AUTO_VALUES
                ):
                    skip_value = True
                continue
            if name in _PARALLEL_FLAGS:
                if "=" in tok:
                    value = tok.partition("=")[2]
                elif tok != name:
                    # The attached short, -np8, which _flag_name peels to -np.
                    value = tok[len(name) :]
                else:
                    # Valueless --parallel: eating the next token would delete a flag.
                    value = cmd[i + 1] if i + 1 < len(cmd) else ""
                    skip_value = _flag_name(value) is None
                try:
                    multi_slot = multi_slot or int(value.strip()) > 1
                except (AttributeError, TypeError, ValueError):
                    pass
                out.extend([name, "1"])
                continue
            out.append(tok)
        if not saw_kv_unified and not multi_slot:
            return None
        if not any(_flag_name(tok) in _PARALLEL_FLAGS for tok in out):
            out.extend(["--parallel", "1"])
        return out

    @staticmethod
    def _drop_env_single_sequence(env: MutableMapping[str, str]) -> bool:
        """Drops the env twins instead of negating them, since --no-kv-unified needs every build to
        know it."""
        dropped = env.pop("LLAMA_ARG_KV_UNIFIED", None) is not None
        return env.pop("LLAMA_ARG_N_PARALLEL", None) is not None or dropped

    @staticmethod
    def _strip_mmproj_args(cmd: list[str]) -> list[str]:
        """Remove explicit projector paths, including aliases, for managed emission or retry."""
        out: list[str] = []
        skip_value = False
        for tok in cmd:
            if skip_value:
                skip_value = False
                continue
            if _flag_name(tok) in {"--mmproj", "-mm"}:
                skip_value = "=" not in tok
                continue
            out.append(tok)
        return out

    @staticmethod
    def _vulkan_prebuilt_was_auto_selected(binary: Optional[str]) -> bool:
        """Only an auto-detected Vulkan bundle may fall back to CPU on a crash; a user-chosen one
        must not."""
        if not binary:
            return False
        from utils.llama_cpp_update import _llama_install_root
        from utils.prebuilt.llama_backend import (
            environment_backend_override,
            marker_backend_was_chosen,
        )

        # Same precedence the installer used; only a concrete override counts as a choice.
        override = environment_backend_override(
            os.environ.get("UNSLOTH_LLAMA_CPP_BACKEND"),
            os.environ.get("UNSLOTH_FORCE_VULKAN"),
        )
        if override is not None and override != "auto":
            return False
        try:
            install_root = _llama_install_root(binary)
            if install_root is None:
                return False
            marker = json.loads(
                (install_root / "UNSLOTH_PREBUILT_INFO.json").read_text(encoding = "utf-8")
            )
        except (OSError, ValueError, TypeError):
            return False
        # Reads new and pre-#7188 markers alike, including the force_cpu-only ones.
        return isinstance(marker, dict) and not marker_backend_was_chosen(marker)

    @staticmethod
    def _strip_cpu_fallback_main_placement(args: Iterable[str]) -> list[str]:
        """Remove every raw main-model placement choice the CPU replay replaces."""
        stripped = strip_shadowing_flags(
            args,
            strip_context = False,
            strip_cache = False,
            strip_spec = False,
            strip_template = False,
            strip_split_mode = True,
            strip_offload = True,
            strip_device = True,
        )
        return _paravirtual_strip_gpu_overrides(stripped, log_dropped = False) or []

    @classmethod
    def _cpu_fallback_request_eligible(
        cls,
        intent: GgufLoadIntent,
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        *,
        allow_manual_cpu: bool = False,
    ) -> bool:
        """Whether CPU recovery may replace the requested placement."""
        args = [str(arg) for arg in (extra_args or ())]
        companion_placement_flags = {
            *_OVERRIDE_TENSOR_FLAGS,
            "--spec-draft-device",
            "-devd",
            "--device-draft",
            "--spec-draft-ngl",
            "-ngld",
            "--gpu-layers-draft",
            "--n-gpu-layers-draft",
            "--mmproj-offload",
            "--no-mmproj-offload",
        }
        child_env = os.environ if env is None else env
        placement_eligible = intent.gpu_memory_mode == "auto" or (
            allow_manual_cpu and intent.gpu_memory_mode == "manual" and intent.gpu_layers == 0
        )
        return bool(
            placement_eligible
            and not intent.gpu_ids
            and not intent.tensor_parallel
            and not intent.tensor_split
            and intent.n_cpu_moe == 0
            and cls._strip_cpu_fallback_main_placement(args) == args
            and not _extra_args_set_any_flag(args, companion_placement_flags)
            and not any(
                str(child_env.get(name) or "").strip()
                for name in (
                    *cls._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS,
                    "LLAMA_ARG_N_GPU_LAYERS_DRAFT",
                    "LLAMA_ARG_MMPROJ_OFFLOAD",
                    "GGML_BACKEND_PATH",
                )
            )
        )

    @classmethod
    def _auto_vulkan_cpu_fallback_eligible(
        cls,
        binary: Optional[str],
        intent: GgufLoadIntent,
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
        *,
        allow_manual_cpu: bool = False,
    ) -> bool:
        """Whether a signal may replace automatic Vulkan placement with CPU."""
        return bool(
            cls._cpu_fallback_request_eligible(
                intent, extra_args, env, allow_manual_cpu = allow_manual_cpu
            )
            and cls._is_vulkan_backend(binary)
            and cls._vulkan_prebuilt_was_auto_selected(binary)
        )

    @staticmethod
    def _as_cpu_fallback_intent(intent: GgufLoadIntent) -> GgufLoadIntent:
        return replace(
            intent,
            gpu_memory_mode = "manual",
            gpu_layers = 0,
            n_cpu_moe = 0,
            tensor_parallel = False,
            tensor_split = None,
            gpu_ids = None,
            cpu_fallback = True,
        )

    def _preserve_cpu_fallback_intent(
        self,
        intent: GgufLoadIntent,
        *,
        source_matches: bool = False,
    ) -> GgufLoadIntent:
        if not self._cpu_fallback_reason:
            return intent
        if not source_matches and not self.matches_load_source(intent):
            return intent
        # Decided by this load's own probe: only a zero-device answer takes the CPU route.
        if not source_matches and self._cpu_fallback_reason in (
            "vulkan_no_device",
            "vulkan_startup_stall",
        ):
            return intent
        extras = list(intent.extra_args) if intent.extra_args is not None else None
        # Judge the env the replay runs with (_cpu_isolated_replay pops placement vars).
        replay_env = {
            name: value
            for name, value in os.environ.items()
            if name not in self._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS
            and name != "GGML_BACKEND_PATH"
        }
        if not self._cpu_fallback_request_eligible(
            intent,
            extras,
            replay_env,
            allow_manual_cpu = True,
        ):
            return intent
        return self._as_cpu_fallback_intent(intent)

    def _apply_cpu_fallback_state(
        self,
        intent: GgufLoadIntent,
        *,
        is_vision: bool,
        mmproj_has_audio: bool,
        disable_vision: bool,
        vision_disabled_by_user: bool,
        reason: str = "vulkan_startup_crash",
    ) -> GgufLoadIntent:
        intent = self._as_cpu_fallback_intent(intent)
        self._gpu_memory_mode = intent.gpu_memory_mode
        self._gpu_layers = intent.gpu_layers
        self._n_cpu_moe = intent.n_cpu_moe
        self._tensor_split = intent.tensor_split
        self._tensor_parallel = intent.tensor_parallel
        self._gpu_ids = intent.gpu_ids
        self._requested_gpu_ids = None
        self._layer_preserves_tensor_intent = False
        self._is_vision = is_vision
        self._mmproj_has_audio = mmproj_has_audio
        # Caller returns before the load assigns these; without it Vision state stays stale.
        self._disable_vision = bool(disable_vision)
        self._vision_disabled_by_user = bool(vision_disabled_by_user)
        self._cpu_fallback_reason = reason
        return intent

    @staticmethod
    def _launch_has_mmproj(cmd: Iterable[str], env: Mapping[str, str]) -> bool:
        """Whether this launch receives a projector from argv or the environment."""
        return _extra_args_set_any_flag(cmd, {"--mmproj", "-mm"}) or any(
            str(env.get(name) or "").strip()
            for name in ("LLAMA_ARG_MMPROJ", "LLAMA_ARG_MMPROJ_URL")
        )

    @classmethod
    def _cpu_isolated_replay(
        cls,
        cmd: Iterable[str],
        env: dict[str, str],
        server_caps: Mapping[str, object],
        *,
        drop_full_offload_threads: bool = False,
    ) -> Optional[list[str]]:
        """Uses --device none, not -ngl 0, and returns None when a companion mmproj cannot be pinned
        to CPU."""
        original = [str(arg) for arg in cmd]
        has_mmproj = cls._launch_has_mmproj(original, env)
        if has_mmproj and not _paravirtual_mmproj_pinnable(server_caps):
            return None
        has_draft = _extra_args_mtp_draft_path(original, env = env) is not None
        draft_ngl_flag = _paravirtual_draft_ngl_flag(server_caps) if has_draft else None
        if has_draft and draft_ngl_flag is None:
            return None

        replay = cls._strip_cpu_fallback_main_placement(original)
        if drop_full_offload_threads:
            # Windows full-offload pins 2 threads; a CPU replay would decode on 2 cores.
            replay = _strip_flag_pairs(replay, _THREAD_OVERRIDE_FLAGS)
            for name in ("OMP_NUM_THREADS", "OMP_WAIT_POLICY"):
                env.pop(name, None)
        replay.extend(["--gpu-layers", "0", "--fit", "off", "--device", "none"])
        if has_mmproj:
            replay.append("--no-mmproj-offload")
        if has_draft:
            replay.extend([str(draft_ngl_flag), "0", "--device-draft", "none"])

        for name in (*cls._CPU_FALLBACK_MAIN_PLACEMENT_ENV_VARS, "GGML_BACKEND_PATH"):
            env.pop(name, None)
        return replay

    def _undo_moe_spill_batch(self, argv: "list[str]") -> "list[str]":
        """Restores only the batch tokens Unsloth itself raised; otherwise argv comes back unchanged."""
        tokens = getattr(self, "_moe_spill_batch_tokens", None)
        if not tokens:
            return list(argv)
        raised, before = tokens
        argv = list(argv)
        for i in range(len(argv) - len(raised) + 1):
            if argv[i : i + len(raised)] == raised:
                return [*argv[:i], *before, *argv[i + len(raised) :]]
        return argv

    def _drop_moe_cache(
        self,
        argv: "list[str]",
        why: str = "",
    ) -> "list[str]":
        """``argv`` without the ``--moe-cache-mib auto`` this launch added; a user's is kept."""
        tokens = list(getattr(self, "_moe_cache_flags", None) or ())
        stripped = _without_subsequence(list(argv), tokens)
        if tokens and stripped != list(argv) and why:
            logger.info("MoE cache: dropping --moe-cache-mib auto for the %s.", why)
        return stripped

    def _moe_cache_auto_eligible(
        self,
        *,
        caps: Optional[Mapping[str, object]],
        gpu_memory_mode: str,
        use_fit: bool,
        experts_on_host: bool,
        discrete_gpu: bool,
        gpu_indices: Optional[Iterable[int]],
        detected_gpus: Optional[Iterable[tuple[int, int]]],
        is_vulkan_backend: bool,
        tensor_parallel: bool,
        extra_args: Optional[Iterable[str]],
        env: Optional[Mapping[str, str]] = None,
    ) -> bool:
        """Whether this launch may get ``--moe-cache-mib auto`` (the caller still checks RAM
        and the final load mode): a build with ``auto``, ``--fit on``, spilling experts, one
        discrete CUDA / ROCm GPU (the cache is single-device), and no user placement."""
        if not (caps or {}).get("supports_moe_cache_auto"):
            return False
        if gpu_memory_mode == "manual" or not use_fit or not experts_on_host:
            return False
        if not discrete_gpu or is_vulkan_backend or tensor_parallel or self.n_moe_layers <= 0:
            return False
        devices = (
            {int(i) for i in gpu_indices}
            if gpu_indices is not None
            else {int(idx) for idx, _free in (detected_gpus or ())}
        )
        if len(devices) != 1:
            return False
        source_env = os.environ if env is None else env
        if _extra_args_set_any_flag(extra_args, _MOE_CACHE_USER_OWNED_FLAGS):
            return False
        if any(str(source_env.get(name) or "").strip() for name in _MOE_CACHE_USER_OWNED_ENV):
            return False
        if _env_fixes_gpu_layers(source_env):
            return False
        try:
            return fit_is_effectively_on(list(extra_args or ()), source_env)
        except ValueError:  # a valueless --fit: llama-server refuses the launch anyway
            return False

    def _discrete_gpu_for_expert_spill(
        self,
        gpu_indices: Optional[Iterable[int]],
        detected_gpus: Optional[Iterable[tuple[int, int]]],
        shared_gpu_ids: Optional[Iterable[int]] = None,
    ) -> bool:
        """Unified memory has nothing to stream and a CPU launch has no GPU, so only a discrete GPU
        counts."""
        detected = list(detected_gpus or ())
        if not detected or _metal_capable_host():
            return False
        on = set(gpu_indices) if gpu_indices else {idx for idx, _free in detected}
        if on and on <= set(shared_gpu_ids or ()):
            return False
        try:
            if self._amd_apu_wants_unified_memory(
                gpu_indices
            ) or self._integrated_cuda_unified_memory(gpu_indices):
                return False
        except Exception as e:
            logger.debug(f"unified-memory probe failed ({e}); not raising the micro-batch")
            return False
        return True

    def _prepare_cpu_fallback_launch(
        self,
        binary: Optional[str],
        cmd: Iterable[str],
        env: dict[str, str],
        server_caps: Mapping[str, object],
        *,
        drop_full_offload_threads: bool = False,
        avail_mib: Optional[int] = None,
    ) -> Optional[tuple[list[str], Optional[str], Optional[str]]]:
        """Returns (argv, cwd, pageable_note) or None; avail_mib is shared so rewrite and repricing
        agree."""
        if not self._is_vulkan_backend(binary):
            return None
        replay = self._cpu_isolated_replay(
            cmd, env, server_caps, drop_full_offload_threads = drop_full_offload_threads
        )
        if replay is None:
            return None
        # Replay runs on no GPU, so give the CPU attempt llama.cpp's auto mmap back.
        if self._fit_load_mode_flags:
            replay = _without_subsequence(replay, self._fit_load_mode_flags)
            logger.info(
                "Load mode: dropping the fit's --load-mode none for the CPU "
                "fallback; it runs entirely from host RAM."
            )
        replay = self._drop_managed_lazy_mode(replay, "CPU fallback")
        # And the managed pair: this replay appends "--device none".
        replay = self._drop_managed_dio(
            replay, "the CPU fallback runs entirely from host RAM", clear_record = False
        )
        # Nothing to stream without a GPU; the expert cache needs one too.
        replay = self._undo_moe_spill_batch(replay)
        replay = self._drop_moe_cache(replay, "CPU fallback")
        # A user's own "--load-mode none" / "--no-mmap" survives that strip, by design,
        # and on this rung it is no longer the mode they were priced for: the replay
        # appends "--gpu-layers 0 --fit off --device none", so nothing credits VRAM and
        # the child holds the WHOLE model in host RAM. Unmapped that is one allocation
        # of the whole file rather than a mapping the kernel pages, i.e. an OOM kill on
        # a host that cannot hold it -- which the main launch path would have rewritten
        # before spawning. So price the replay on its OWN footprint (never the preflight
        # verdict, which credited a GPU placement this argv has just deleted) and apply
        # the same override.
        _priced_replay = replay
        replay, pageable_note = self._page_an_oversized_unmapped_load(
            replay,
            env,
            # UNSLOTH_ALLOW_HOST_OFFLOAD silences a message; it must not withdraw the rewrite.
            lambda: bool(
                self._launch_host_shortfall_message(
                    _priced_replay,
                    (),
                    env,
                    child_has_no_gpu = True,
                    avail_mib = avail_mib,
                    honor_opt_out = False,
                )
            ),
        )
        cpu_binary = self._cpu_isolated_binary(binary)
        if cpu_binary is None:
            return None
        loader_env = self._llama_server_env_for_binary(cpu_binary)
        loader_path = _loader_path_var()
        env[loader_path] = loader_env[loader_path]
        replay[0] = cpu_binary
        # Keep the working directory: relative paths in user extra args resolve against it.
        return replay, None, pageable_note

    def _cpu_isolated_binary(self, binary: Optional[str]) -> Optional[str]:
        """Backend libs load before --device none, so the CPU copy is staged without GPU backend libs."""
        if not binary or not self._is_llama_install_tree(binary):
            return None
        source_binary = _resolve_llama_binary(binary)
        source_stamp = self._binary_stamp(source_binary)
        runtime = self._cpu_fallback_runtime
        if (
            runtime is not None
            and runtime.source_binary == source_binary
            and runtime.source_stamp == source_stamp
        ):
            if runtime.staged_binary.is_file():
                return str(runtime.staged_binary)
        self._cleanup_cpu_fallback_runtime()
        staged_runtime = None
        try:
            runtime_root = _swa_cache_path().parent / "runtime"
            runtime_root.mkdir(parents = True, exist_ok = True)
            _sweep_abandoned_cpu_runtimes(runtime_root)
            staged_runtime = tempfile.TemporaryDirectory(
                prefix = "llama-cpu-",
                dir = runtime_root,
            )
            staged_dir = Path(staged_runtime.name)
            # kill -9 skips the atexit hook, so stamp the owner for later collection.
            (staged_dir / _CPU_RUNTIME_OWNER_FILE).write_text(str(os.getpid()), encoding = "utf-8")
            lib_dir = _llama_lib_dir(str(source_binary))
            gpu_backend = _GGML_GPU_BACKEND_RE
            cpu_library_present = False
            for source in lib_dir.iterdir():
                try:
                    resolved = source.resolve(strict = True)
                except OSError:
                    continue
                name = source.name
                is_shared = name.endswith((".dll", ".dylib")) or ".so" in name
                if resolved != source_binary and not is_shared:
                    continue
                if gpu_backend.match(name.lower()):
                    continue
                destination = staged_dir / name
                if destination.exists():
                    continue
                try:
                    os.link(resolved, destination)
                except OSError:
                    shutil.copy2(resolved, destination)
                if name.lower().startswith(("libggml-cpu", "ggml-cpu")):
                    cpu_library_present = True
            staged_binary = staged_dir / source_binary.name
            if not staged_binary.is_file() or not cpu_library_present:
                staged_runtime.cleanup()
                return None
        except (OSError, ValueError):
            if staged_runtime is not None:
                with contextlib.suppress(Exception):
                    staged_runtime.cleanup()
            return None
        self._cpu_fallback_runtime = _CpuFallbackRuntime(
            tempdir = staged_runtime,
            source_binary = source_binary,
            staged_binary = staged_binary,
            source_stamp = source_stamp,
        )
        return str(staged_binary)

    @staticmethod
    def _binary_stamp(path: Path) -> tuple:
        try:
            stat = path.stat()
        except OSError:
            return ()
        return (stat.st_ino, stat.st_size, stat.st_mtime_ns)

    @staticmethod
    def _binary_revision(binary: Optional[str]) -> tuple:
        """Path cannot tell the build, as updates swap the file in place; () when unreadable means
        unchanged."""
        if not binary:
            return ()
        stamp = LlamaCppBackend._binary_stamp(Path(binary))
        return (str(binary),) + stamp if stamp else ()

    def _cleanup_cpu_fallback_runtime(self) -> None:
        runtime = getattr(self, "_cpu_fallback_runtime", None)
        self._cpu_fallback_runtime = None
        # A failed cleanup() detaches its finalizer, so retry it on the next call.
        pending = getattr(self, "_pending_cpu_fallback_cleanups", [])
        if runtime is not None:
            pending.append(runtime.tempdir)
        retry = []
        for tempdir in pending:
            try:
                tempdir.cleanup()
            except Exception:
                retry.append(tempdir)
        self._pending_cpu_fallback_cleanups = retry

    def _cleanup_failed_cpu_fallback(self) -> None:
        """Remove every process and staged artifact from a terminal CPU replay."""
        self._kill_process()
        self._cpu_fallback_reason = None
        self._cleanup_cpu_fallback_runtime()

    @staticmethod
    def _gpu_init_crash_message(binary: Optional[str] = None) -> str:
        """Return backend-specific advice for a GPU initialization crash."""
        base = (
            "llama-server crashed at startup on both the vision and text-only "
            "attempts -- a GPU driver/runtime initialization crash, not a model "
            "or vision-projector problem. "
        )
        backends = LlamaCppBackend._installed_ggml_backends(binary)
        backend = next((name for name in ("cuda", "hip", "vulkan") if name in backends), None)
        if backend == "vulkan":
            return base + (
                "This build uses Vulkan, which Unsloth selects when it detects an "
                "Intel or AMD GPU. Older integrated GPUs and their drivers can fault "
                "inside Vulkan device initialization. Update your Vulkan driver (Mesa "
                "on Linux), or reinstall llama.cpp on CPU with "
                "UNSLOTH_LLAMA_CPP_BACKEND=cpu unsloth studio update."
            )
        if backend == "hip":
            return base + (
                "This often means an unsupported secondary GPU; on AMD/ROCm, hide it "
                "with ROCR_VISIBLE_DEVICES (e.g. ROCR_VISIBLE_DEVICES=0 exposes only "
                "the first GPU) before launching Unsloth Studio."
            )
        if backend == "cuda":
            return base + (
                "This often means an unsupported secondary GPU or a driver/CUDA "
                "runtime mismatch; hide the extra GPU with CUDA_VISIBLE_DEVICES (e.g. "
                "CUDA_VISIBLE_DEVICES=0 exposes only the first GPU) before launching "
                "Unsloth Studio, or update the NVIDIA driver."
            )
        return base + (
            "Check the llama-server log and your GPU driver, and make sure the "
            "installed llama.cpp build matches this machine's GPU."
        )

    @staticmethod
    def _redacted_cmd_for_log(cmd: "list[str]") -> "list[str]":
        """Copy of cmd with the value after --api-key replaced by <redacted>."""
        out = list(cmd)
        if "--api-key" in out:
            ki = out.index("--api-key") + 1
            if ki < len(out):
                out[ki] = "<redacted>"
        return out

    def _start_llama_process(
        self, cmd: list[str], env: dict, *, child_gpu_physical_ids: Optional[tuple[int, ...]]
    ) -> bool:
        """Returns False without spawning once teardown has begun, so callers stop instead of
        health-waiting."""
        # Drop an orphan Popen a concurrent load may have stored past Phase 1.
        self._kill_process()
        self._child_gpu_physical_ids = child_gpu_physical_ids

        self._stdout_lines = []
        # Tees llama-server output to a log file for post-mortems; the parent keeps only the last 50 lines.
        self._llama_log_fh = None
        try:
            log_dir = _swa_cache_path().parent / "logs" / "llama-server"
            log_dir.mkdir(parents = True, exist_ok = True)
            self._llama_log_path = log_dir / f"llama-{int(time.time())}-port-{self._port}.log"
            self._llama_log_fh = open(
                self._llama_log_path,
                "w",
                encoding = "utf-8",
                buffering = 1,
            )
            # After the open, so the cap counts this file and can never delete it.
            prune_log_dir(log_dir, "llama-*.log", protect = self._llama_log_path)
            logger.info(f"llama-server stdout/stderr -> {self._llama_log_path}")
        except (OSError, UnicodeDecodeError) as e:
            # Best-effort; never block the load on logging.
            logger.warning(f"Could not open llama-server log file: {e}")
            self._llama_log_path = None

        # Log the argv per attempt (the text-only mmproj retry re-enters here
        # with --mmproj stripped), redacting the API key.
        logger.info(f"Starting llama-server: {' '.join(self._redacted_cmd_for_log(cmd))}")

        # The mmproj text-only retry reaches a spawn without passing _spawn_and_wait.
        with self._spawn_lock:
            if self._spawn_is_stale():
                logger.info("app is shutting down; not starting llama-server")
                self._close_attempt_log()
                self._health_wait_cancelled = True
                return False
            # PDEATHSIG follows the forking thread; the MTP-crash reload's thread exits.
            _spawned = _spawn_on_lifetime_thread(
                lambda: subprocess.Popen(
                    cmd,
                    stdout = subprocess.PIPE,
                    stderr = subprocess.STDOUT,
                    text = True,
                    encoding = "utf-8",
                    errors = "replace",
                    env = env,
                    **_windows_hidden_subprocess_kwargs(),
                    **_child_popen_kwargs(),
                )
            )
            self._process = _spawned
            # The env picks companions too (LLAMA_ARG_MMPROJ, ...): load_progress sizes them from it.
            self._process_env = (_spawned, env)
            _invalidate_gpu_memory("llama-server spawned")
            # Serialise loads so two llama-servers never coexist; /unload is not blocked; lifecycle read first.
            self._note_server_pid(_spawned.pid)

        # A helper load's stale check is not atomic with the latch; recheck and reap.
        if self._spawn_is_stale():
            logger.info("shutdown began during the spawn; killing the new llama-server")
            self._kill_process()
            self._close_attempt_log()
            self._health_wait_cancelled = True
            return False

        # Start background thread to drain stdout and prevent pipe deadlock
        self._stdout_thread = threading.Thread(
            target = self._drain_stdout, daemon = True, name = "llama-stdout"
        )
        self._stdout_thread.start()
        return True

    @contextlib.contextmanager
    def _serial_load_scope(self):
        """Clears the pending fraction on leaving the lock, so a queued load's freshly armed value
        survives."""
        with self._serial_load_lock:
            try:
                yield
            finally:
                self._vram_fraction_pending = None
                self._binary_revision_pending = None
                # Cleared here, or a finished load could blank a queued load's marker.
                self._memory_pending_launch = None

    @_invalidates_gpu_memory("llama.cpp load")
    @_with_gguf_load_marker
    @holds_inference
    def load_model(
        self,
        intent: GgufLoadIntent,
        load_cancel_event: Optional[threading.Event] = None,
    ) -> bool:
        """Start llama-server from one immutable load intent."""

        def _load_cancelled() -> bool:
            return self._cancel_event.is_set() or bool(
                load_cancel_event is not None and load_cancel_event.is_set()
            )

        download_cancel_event = (
            _CombinedCancelEvent(self._cancel_event, load_cancel_event)
            if load_cancel_event is not None
            else self._cancel_event
        )

        gguf_path = intent.gguf_path
        mmproj_path = intent.mmproj_path
        mtp_draft_path = intent.mtp_draft_path
        dspark_draft_path = intent.dspark_draft_path
        dflash_draft_path = intent.dflash_draft_path
        hf_repo = intent.hf_repo
        hf_variant = intent.hf_variant
        hf_token = intent.hf_token
        model_identifier = intent.model_identifier
        is_vision = intent.is_vision
        disable_vision = intent.disable_vision
        n_ctx = intent.n_ctx
        _replayed_ctx_refit = False
        chat_template_override = intent.chat_template_override
        cache_type_kv = intent.cache_type_kv
        speculative_type = intent.speculative_type
        spec_draft_n_max = intent.spec_draft_n_max
        tensor_parallel = intent.tensor_parallel
        gpu_memory_mode = intent.gpu_memory_mode
        gpu_layers = intent.gpu_layers
        n_cpu_moe = intent.n_cpu_moe
        tensor_split = list(intent.tensor_split) if intent.tensor_split is not None else None
        gpu_ids = list(intent.gpu_ids) if intent.gpu_ids is not None else None
        gpu_ids_are_vulkan_ordinals = intent.gpu_ids_are_vulkan_ordinals
        n_threads = intent.n_threads
        n_parallel = intent.n_parallel
        n_batch = intent.n_batch
        n_ubatch = intent.n_ubatch
        load_mode = intent.load_mode
        spec_draft_cache_type = intent.spec_draft_cache_type
        ctx_checkpoints = intent.ctx_checkpoints
        cache_ram = intent.cache_ram
        extra_args = list(intent.extra_args) if intent.extra_args is not None else None
        custom_mmproj = _extra_args_device(extra_args, {"--mmproj", "-mm"})
        if custom_mmproj is not None:
            mmproj_path = self._resolve_launch_mmproj_path(
                model_path = gguf_path or "", mmproj_path = mmproj_path, extra_args = extra_args
            )
            is_vision = True
        preserve_multi_gpu_on_layer = intent.preserve_multi_gpu_on_layer
        reasoning_budget = intent.reasoning_budget
        reasoning_budget_message = intent.reasoning_budget_message
        # Refuse fast during an in-app binary swap; the flag is set under this lock so loads have drained.
        self._codec_failure.message = None
        with self._serial_load_scope():
            # Here, not at the spawn: the duplicate-adoption phase below kills whatever is loaded.
            with self._spawn_lock:
                _stale_load = self._spawn_is_stale()
            if _stale_load:
                logger.info("dropping a load left over from the previous server lifecycle")
                return False
            # In-app update swapping binaries: refuse fast (set under this lock,
            # so any in-flight load has drained) instead of using a half-swapped one.
            if getattr(self, "_llama_update_in_progress", False):
                raise RuntimeError("llama.cpp is updating; try again in a moment.")

            intent = self._preserve_cpu_fallback_intent(intent)
            tensor_parallel = intent.tensor_parallel
            gpu_memory_mode = intent.gpu_memory_mode
            gpu_layers = intent.gpu_layers
            n_cpu_moe = intent.n_cpu_moe
            tensor_split = list(intent.tensor_split) if intent.tensor_split is not None else None
            gpu_ids = list(intent.gpu_ids) if intent.gpu_ids is not None else None

            # Read before the pin below rewrites every placement to manual/0.
            _caller_owns_budget = gpu_memory_mode == "manual" and gpu_layers >= 0

            # A virtualised Apple GPU corrupts offloaded layers, so pin to CPU before the duplicate
            # check so the compared placement is the one that launches.
            _paravirtual_cpu_forced = _metal_device_is_paravirtual()
            if _paravirtual_cpu_forced:
                _pv_placement = paravirtual_normalized_request(
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    tensor_parallel = tensor_parallel,
                    tensor_split = tensor_split,
                    n_cpu_moe = n_cpu_moe,
                    extra_args = extra_args,
                )
                if (gpu_memory_mode, gpu_layers) != (
                    _pv_placement.gpu_memory_mode,
                    _pv_placement.gpu_layers,
                ):
                    logger.warning(
                        "Forcing gpu_layers=0 for %s: this Mac's Metal device is "
                        "virtualised and offloaded layers produce corrupt output.",
                        model_identifier or gguf_path,
                    )
                if extra_args and _pv_placement.extra_args != list(extra_args):
                    logger.warning(
                        "Dropping offload flags from extra args on a "
                        "virtualised Metal device: %s -> %s",
                        list(extra_args),
                        _pv_placement.extra_args,
                    )
                if tensor_parallel or tensor_split:
                    logger.info(
                        "Virtualised Metal device: dropping tensor split/parallel "
                        "flags (nothing to split on the GPU)"
                    )
                gpu_memory_mode = _pv_placement.gpu_memory_mode
                gpu_layers = _pv_placement.gpu_layers
                n_cpu_moe = _pv_placement.n_cpu_moe
                extra_args = _pv_placement.extra_args
                # Spelled out (not read off _pv_placement, which returns exactly these)
                # so tests/test_tp_vision_regression.py's TP-drop allowlist sees this site.
                tensor_parallel = False
                tensor_split = None
                # Signed shift to llama.cpp's fit margin: lowering holds more back, raising packs closer; default 0.
                intent = replace(
                    intent,
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    n_cpu_moe = n_cpu_moe,
                    extra_args = tuple(extra_args) if extra_args is not None else None,
                    tensor_parallel = False,
                    tensor_split = None,
                )

            # Resolved once under the lock so ranking, fitting and the duplicate check agree.
            _vram_frac = _active_vram_fraction()
            # How far this budget moves llama.cpp's own fitter margin, set once the
            # devices are known. Signed: lowering holds more back, raising packs
            # closer to the card. Zero at the default.
            _fit_target_delta_mib = 0.0
            # The same delta per physical GPU id, when the per-device list applies.
            _fit_target_delta_by_idx: Optional[dict[int, float]] = None
            # Studio's emitted margins per card, spelled into --fit-target at spawn.
            _fit_target_margins_by_idx: Optional[dict[int, float]] = None
            # Set only if that margin actually reached the command line, which is
            # what makes the child budget-priced in a mode the planner skipped.
            _fit_target_priced = False

            def _budget_priced_placement() -> Optional[float]:
                """Read at call time: the fraction this child was sized against; None for manual or
                CPU-fallback."""
                if intent.cpu_fallback:
                    return None
                if gpus:
                    return _vram_frac
                # Manual+Auto bypasses the planner but --fit-target still prices the child.
                return _vram_frac if _fit_target_priced else None

            # Armed before the duplicate check so a racing save sees the pending value.
            self._vram_fraction_pending = _vram_frac
            # _vram_fraction_launched is committed at the launch site, not here.
            if self.adopt_load_intent_if_matched(intent):
                logger.info(
                    f"load_model: backend already in target state for "
                    f"'{model_identifier}', skipping reload"
                )
                # Retry probe only if a prior attempt didn't finish.
                if not self._audio_probed:
                    try:
                        detected = self._detect_audio_type_strict()
                        self._audio_probed = True
                    except Exception as exc:
                        logger.debug("Fast-path audio probe failed: %s", exc)
                        detected = None
                    applied_audio = (
                        self._apply_detected_audio(detected)
                        if intent.audio_codec_path is None
                        else self._apply_detected_audio(detected, intent.audio_codec_path)
                    )
                    if not applied_audio:
                        return False
                if not self._healthy:
                    return False
                return True

            # Stays armed through the download and planning, which can take minutes.
            # Placement is undecided until the spawn site narrows it: a needless
            # reload prompt beats sizing a child against a replaced budget.
            self._cancel_event.clear()
            # Belongs to this attempt only; a guard that runs before this load's first
            # health wait would otherwise read the previous request's cancellation.
            self._health_wait_cancelled = False
            if _load_cancelled():
                logger.info("Load cancelled before GGUF resolution")
                return False

            # Defer a not-found error: diffusion GGUFs use another runner.
            # Snapshot under the settings guard so a racing save asks for a reload.
            from utils.llama_cpp_path_settings import llama_cpp_path_selection_guard

            with llama_cpp_path_selection_guard():
                binary = self._find_llama_server_binary()
                # macOS: launch the resolved server, never a shell wrapper; SIP purges DYLD_* through /bin/sh.
                binary = self._exec_path_for_launch(binary)
                self._binary_revision_pending = self._binary_revision(binary)

            # Accumulated, not sampled: a later probe success must not erase an earlier guess.
            _launch_probe_inconclusive = False
            # Set when FA ends up off without the argv saying so.
            _flash_attn_known_off = False

            def _launch_caps(bin_path):
                nonlocal _launch_probe_inconclusive
                caps = self.probe_server_capabilities(bin_path)
                if caps.get("mtp_probe_inconclusive"):
                    _launch_probe_inconclusive = True
                return caps

            _reasoning_requested = any(
                self.reasoning_budget_settings_requested(
                    extra_args = extra_args,
                    reasoning_budget = reasoning_budget,
                    reasoning_budget_message = reasoning_budget_message,
                )
            )
            if (
                _reasoning_requested
                and gguf_path
                and Path(gguf_path).is_file()
                and self._gguf_path_is_diffusion(gguf_path, model_identifier)
            ):
                raise ValueError(
                    "Reasoning Budget settings are not supported for DiffusionGemma models."
                )
            # Nothing configured means nothing to reject; _launch_caps probes the binary anyway.
            if _reasoning_requested:
                self.validate_reasoning_budget_capabilities(
                    binary,
                    extra_args = extra_args,
                    reasoning_budget = reasoning_budget,
                    reasoning_budget_message = reasoning_budget_message,
                )
            is_vulkan_backend = self._is_vulkan_backend(binary)
            # Computed once so the reload comparator matches the argv.
            _gpu_ids_own_device_flags = self._gpu_ids_own_placement(gpu_ids)
            _vulkan_ordinal_pin = (
                is_vulkan_backend and bool(gpu_ids) and gpu_ids_are_vulkan_ordinals is not False
            )
            _cpu_only_pin = (
                bool(gpu_ids) and not is_vulkan_backend and self._backend_lacks_gpu_lib(binary)
            )

            # Without --kv-unified, --parallel N splits -c into N windows; fall back to one slot.
            if n_parallel > 1 and binary and not _launch_caps(binary).get("supports_kv_unified"):
                logger.warning(
                    "llama-server at %s has no --kv-unified, so %d parallel slots would "
                    "split the context window %d ways. Using 1 slot instead; update "
                    "llama.cpp to run chats in parallel.",
                    binary,
                    n_parallel,
                    n_parallel,
                )
                n_parallel = 1  # allow-slot-clamp: the build cannot serve more

            # ── Vulkan-ordinal preflight (BEFORE the Phase 1 kill) ────────
            # Vulkan-ordinal preflight, above the kill so an invalid pin leaves the live model untouched.
            # Vulkan ordinals are not range-checked at the route, unlike CUDA ids.
            if _vulkan_ordinal_pin and binary:
                _pf_wanted = {int(x) for x in gpu_ids}
                _pf_probed = {g[0] for g in self._get_gpu_memory(binary)}
                if not _pf_wanted.issubset(_pf_probed):
                    raise ValueError(
                        f"Requested Vulkan GPU ordinal(s) {sorted(_pf_wanted)} not "
                        f"present. Available Vulkan devices: {sorted(_pf_probed)}."
                    )

            # Classify before killing the healthy server; diffusion changes placement validity.
            _pv_diffusion_unpinnable = bool(
                _paravirtual_cpu_forced and not self.diffusion_split_supported()
            )
            _preflight_model_path = None
            self._pending_variant_fallback = None
            if hf_repo and (_vulkan_ordinal_pin or _cpu_only_pin or _pv_diffusion_unpinnable):
                _resolved_repo = _resolve_repo_id_casing(hf_repo)
                if _resolved_repo != hf_repo:
                    logger.info(
                        "Using cached repo_id casing '%s' for requested '%s'",
                        _resolved_repo,
                        hf_repo,
                    )
                    hf_repo = _resolved_repo
                with _hf_offline_if_unreachable():
                    _preflight_model_path = self._download_gguf(
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        hf_token = hf_token,
                        cancel_event = download_cancel_event,
                    )
                _preflight_is_diffusion = self._gguf_path_is_diffusion(
                    _preflight_model_path, model_identifier
                )
                if _preflight_is_diffusion:
                    if _vulkan_ordinal_pin:
                        raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)
                    if _pv_diffusion_unpinnable:
                        raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)
                elif _cpu_only_pin:
                    raise ValueError(
                        f"Requested gpu_ids {list(gpu_ids)} but the llama.cpp build has "
                        "no GPU backend (CPU-only build); it would ignore the pin and run "
                        "on CPU. Omit gpu_ids to run on CPU."
                    )
            elif is_vulkan_backend and gpu_ids and gguf_path and not hf_repo:
                if not Path(gguf_path).is_file():
                    raise FileNotFoundError(f"GGUF file not found: {gguf_path}")

            # Settle an unpinnable diffusion split here before teardown; _start_diffusion_server re-checks it.
            if _vulkan_ordinal_pin and gguf_path and not hf_repo:
                self._reject_vulkan_diffusion_gpu_ids_before_teardown(
                    gguf_path,
                    model_identifier,
                )
            # Same for the unpinnable diffusion split: _start_diffusion_server enforces
            # it everywhere, but only after the teardown, so settle the local case here
            # and leave the running server alone.
            if (
                _pv_diffusion_unpinnable
                and gguf_path
                and not hf_repo
                and self._gguf_path_is_diffusion(gguf_path, model_identifier)
            ):
                raise ValueError(_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR)

            # Refuse an on-disk image/video GGUF before the teardown (header answers it).
            if gguf_path and not hf_repo and Path(gguf_path).is_file():
                _early_non_chat = self._non_chat_gguf_refusal_for_path(gguf_path, model_identifier)
                if _early_non_chat:
                    logger.error(
                        "Refusing non-chat GGUF before teardown: %s (%s)",
                        _early_non_chat,
                        gguf_path,
                    )
                    raise ValueError(_early_non_chat)

            # Same refusal for repo loads (what the Model Hub sends), via a header byte range.
            # Fails open into the post-download check.
            if hf_repo:
                # Offline guard: the probe hits the Hub twice, each with retry backoff.
                with _hf_offline_if_unreachable():
                    _early_non_chat = (
                        self._non_chat_gguf_refusal_for_path(
                            _preflight_model_path, model_identifier
                        )
                        if _preflight_model_path
                        else self._remote_non_chat_gguf_refusal(
                            hf_repo = hf_repo,
                            hf_variant = hf_variant,
                            hf_token = hf_token,
                            model_identifier = model_identifier,
                        )
                    )
                if _early_non_chat:
                    logger.error(
                        "Refusing non-chat GGUF before teardown: %s (%s)",
                        _early_non_chat,
                        hf_repo,
                    )
                    raise ValueError(_early_non_chat)

            # The probe can take a moment on a slow Hub, so re-read the cancel flag rather
            # than tearing down a healthy server for a load that was called off.
            if _load_cancelled():
                logger.info("Load cancelled before teardown")
                return False

            # Fail fast before killing the live server; an explicit reload retries.
            _abort_memo_model = repr(
                (
                    replace(intent, hf_token = None, force_reload = False, verified_gguf = None),
                    _vram_frac,
                    _model_memory_settings_or_none(),
                )
            )
            if intent.force_reload:
                LlamaCppBackend._forget_sched_reserve_abort(binary, _abort_memo_model)
            elif LlamaCppBackend._sched_reserve_aborts(binary, _abort_memo_model):
                logger.warning(
                    "Skipping reload of '%s': it already aborted in the llama.cpp graph "
                    "scheduler this session.",
                    model_identifier,
                )
                raise RuntimeError(self._sched_reserve_abort_message())

            # ── Phase 1: kill old process (under lock, fast) ──────────
            # Drop the previous advisory here, where the old child is committed to dying, so every
            # stand-down above keeps it.
            _replaying_cpu_fallback = intent.cpu_fallback
            with self._lock:
                self._begin_load_warnings()
                self._kill_process()
                if not _replaying_cpu_fallback:
                    self._cpu_fallback_reason = None
                    self._cleanup_cpu_fallback_runtime()

                self._mmproj_fallback_reason = None
                self._variant_fallback_warning = None
            # Reset at the teardown, not where the binary resolves: early bails keep the old server.
            self._launch_binary_revision = self._binary_revision(binary)
            # Cleared per load: a local-file load never reaches the DFlash fetch.
            self._dflash_retry_needed = False

            # ── Phase 2: download (NO lock held, so cancel can proceed) ──
            # Resolve the canonical MTP mode once; it decides which drafter is downloaded and launched.
            _spec_canon = _canonicalize_spec_mode(speculative_type) or "auto"
            # #11308: DFlash2 + --split-mode tensor aborts at startup (ggml-org/llama.cpp#27819) and the
            # route falls back to layer split, so Auto prefers a loadable MTP sidecar on tensor instead.
            # _estimate_gguf_required_gb mirrors this.
            _auto_tensor_split = _spec_canon == "auto" and _effective_tensor_parallel(
                extra_args, tensor_parallel
            )

            def _auto_dflash_blocked_by_tensor() -> bool:
                if (
                    _auto_tensor_split
                    and mtp_draft_path
                    and not _extra_args_mtp_draft_path(extra_args, env = _child_spec_env(extra_args))
                ):
                    try:
                        from utils.models.gguf_metadata import read_gguf_nextn_predict_layers
                        return bool(
                            _launch_caps(binary).get("mtp_token")
                            and not (read_gguf_nextn_predict_layers(model_path) or 0) > 0
                            and _mtp_drafter_loads_standalone(mtp_draft_path)
                        )
                    except Exception:
                        return False
                return False

            def _dflash_breaks_on_images() -> bool:
                if not dflash_draft_path or disable_vision or extra_args_disable_mmproj(extra_args):
                    return False
                try:
                    projector = self._resolve_launch_mmproj_path(
                        model_path = model_path, mmproj_path = mmproj_path, extra_args = extra_args
                    )
                except Exception:
                    return False
                return _dflash_drafter_breaks_on_images(model_path, dflash_draft_path, projector)

            _unloadable_mtp_draft_path: Optional[str] = None
            # Scope HF_HUB_OFFLINE to the download block only when DNS is dead.
            if hf_repo:
                # Resolve repo casing once so the GGUF and companions share one cache entry.
                _resolved_repo = _resolve_repo_id_casing(hf_repo)
                if _resolved_repo != hf_repo:
                    logger.info(
                        "Using cached repo_id casing '%s' for requested '%s'",
                        _resolved_repo,
                        hf_repo,
                    )
                    hf_repo = _resolved_repo
                with _hf_offline_if_unreachable():
                    model_path = _preflight_model_path
                    if model_path is None:
                        # Revalidate the carried file before skipping download resolution.
                        model_path = self._verified_cached_gguf(intent, hf_repo, hf_variant)
                        if model_path:
                            logger.info("Reusing verified cached GGUF: %s", model_path)
                    if model_path is None:
                        model_path = self._download_gguf(
                            hf_repo = hf_repo,
                            hf_variant = hf_variant,
                            hf_token = hf_token,
                            cancel_event = download_cancel_event,
                        )
                    if self._pending_variant_fallback:
                        hf_variant, self._variant_fallback_warning = self._pending_variant_fallback
                        # Replayed by the respawn and a variant-less Apply, which would re-download.
                        intent = replace(intent, hf_variant = hf_variant)
                    # Vision off does not skip the fetch: an mmproj may be an audio encoder instead.
                    if is_vision and not mmproj_path and not extra_args_disable_mmproj(extra_args):
                        mmproj_path = self._download_mmproj(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            cancel_event = download_cancel_event,
                            near_path = model_path,
                        )
                    # Fetch the separate MTP drafter; no size gate (helps even sub-3B).
                    # The MTP/ fallback is qwen4exp only, whose GGUFs carry no head.
                    if (
                        not mtp_draft_path
                        and _spec_canon in ("auto", "mtp", "mtp+ngram")
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        mtp_draft_path = self._download_mtp(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            cancel_event = download_cancel_event,
                            near_path = model_path,
                            allow_nested = self._gguf_path_wants_nested_mtp(model_path),
                        )
                    # "auto" is included: DSpark is the default whenever the repo
                    # ships a sidecar. Repos without one no-op, exactly like the
                    # MTP fetch above, so this costs one listing and no download.
                    if (
                        not dspark_draft_path
                        and _spec_canon in ("auto", "dspark")
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        dspark_draft_path = self._download_dspark(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            cancel_event = download_cancel_event,
                            near_path = model_path,
                            binary = binary,
                            caps_probe = _launch_caps,
                        )
                    # Auto fetch stands down once DSpark resolves (it wins the promotion), using the same
                    # capability-aware 'resolved'. An explicit 'dflash' still fetches.
                    if (
                        not dflash_draft_path
                        and _spec_canon in ("auto", "dflash")
                        and not _auto_dflash_blocked_by_tensor()
                        and not self._dspark_wins_auto(
                            binary = binary,
                            dspark_draft_path = dspark_draft_path,
                            spec_canon = _spec_canon,
                            extra_args = extra_args,
                        )
                        and not _extra_args_set_spec_type(extra_args)
                    ):
                        dflash_draft_path = self._download_dflash(
                            hf_repo = hf_repo,
                            hf_token = hf_token,
                            cancel_event = download_cancel_event,
                            near_path = model_path,
                            binary = binary,
                        )
            elif gguf_path:
                if not Path(gguf_path).is_file():
                    raise FileNotFoundError(f"GGUF file not found: {gguf_path}")
                model_path = gguf_path
            else:
                raise ValueError("Either gguf_path or hf_repo must be provided")

            # Set identifier early so _read_gguf_metadata can use it (DeepSeek).
            self._model_identifier = model_identifier

            # Capability gate shared with the DFlash fetch so fetch and promotion agree.
            if self._dspark_wins_auto(
                binary = binary,
                dspark_draft_path = dspark_draft_path,
                spec_canon = _spec_canon,
                extra_args = extra_args,
                caps = _launch_caps,
            ):
                _spec_canon = "dspark"
                logger.info("Auto: DSpark sidecar available, using draft-dspark.")

            # DSpark keeps first refusal, matching llama.cpp's own downloader.
            if (
                _spec_canon == "auto"
                and dflash_draft_path
                and not _extra_args_set_spec_type(extra_args)
            ):
                try:
                    if not _launch_caps(binary).get("supports_dflash"):
                        pass
                    elif _auto_dflash_blocked_by_tensor():
                        logger.info(
                            "Auto: DFlash sidecar available but tensor split is on; "
                            "keeping tensor split with the MTP drafter "
                            "(llama.cpp cannot run DFlash2 with --split-mode tensor yet)."
                        )
                    elif _dflash_breaks_on_images():
                        logger.info(
                            "Auto: DFlash sidecar %s has no M-RoPE sections, so llama.cpp "
                            "cannot carry it past an image on this vision model; keeping "
                            "vision and skipping DFlash. Choose DFlash in the Speculative "
                            "Decoding dropdown to force it, or turn Vision off.",
                            dflash_draft_path,
                        )
                    else:
                        _spec_canon = "dflash"
                        logger.info("Auto: DFlash sidecar available, using draft-dflash.")
                except Exception as exc:
                    logger.debug("DFlash capability probe failed during Auto: %s", exc)
            elif (
                _spec_canon == "dflash"
                and not _extra_args_set_spec_type(extra_args)
                and _dflash_breaks_on_images()
            ):
                logger.warning(
                    "DFlash forced with sidecar %s, which has no M-RoPE sections: llama.cpp "
                    "will fail the first image sent after text in a chat. Use Auto or turn "
                    "Vision off to keep images working.",
                    dflash_draft_path,
                )

            # From here mtp_draft_path is whichever drafter launches; _spec_canon says which.
            if _spec_canon == "dspark":
                mtp_draft_path = dspark_draft_path
            elif _spec_canon == "dflash":
                mtp_draft_path = dflash_draft_path

            # Read GGUF metadata (context_length, chat_template); header-only.
            self._read_gguf_metadata(model_path)

            if (
                self._nextn_predict_layers
                and mtp_draft_path
                and _spec_canon not in ("dspark", "dflash")
            ):
                # A root mtp-*.gguf may mirror the embedded head; -md would replace it.
                logger.info("Main GGUF contains an embedded MTP head; ignoring separate drafter.")
                mtp_draft_path = None

            # Drop before the fit prices it, but not when extras name their own drafter (last-wins).
            if (
                mtp_draft_path
                and _spec_canon not in ("dspark", "dflash")
                and not _extra_args_mtp_draft_path(extra_args, env = _child_spec_env(extra_args))
                and not _mtp_drafter_loads_standalone(mtp_draft_path)
            ):
                logger.warning(
                    "Dropping MTP drafter %s: it carries neither token_embd.weight nor "
                    "nextn_shared_target_tensors, so llama-server cannot load it as "
                    "--model-draft; loading without it.",
                    mtp_draft_path,
                )
                _unloadable_mtp_draft_path = mtp_draft_path
                mtp_draft_path = None

            if _load_cancelled():
                logger.info("Load cancelled after download phase")
                return False

            # Whether the user set the batch pair, read before the embedding and projector
            # raises below overwrite n_batch / n_ubatch. Gates the expert-spill raise.
            _user_named_batch = any(_named_batch_sizes(extra_args, None, n_batch, n_ubatch)[2:])

            # MEAN/CLS inputs must fit one micro-batch (LAST splits). Before the projector raise,
            # which would otherwise read as a user-set micro-batch.
            if self._pooling_type in (1, 2):
                n_batch, n_ubatch = _embedding_batch_ubatch(
                    resolve_requested_ctx(extra_args, n_ctx) or self._context_length or 0,
                    n_batch,
                    n_ubatch,
                    extra_args,
                )

            # Decide after downloading the projector and before pricing the load.
            n_batch, n_ubatch = _batch_ubatch_for_mmproj(
                _launch_required_ubatch(
                    None
                    if (disable_vision or not is_vision)
                    else self._resolve_launch_mmproj_path(
                        model_path = model_path,
                        mmproj_path = mmproj_path,
                        extra_args = extra_args,
                    ),
                    # Use the same order-independent metadata read as the estimators.
                    _read_gguf_embedding_length(model_path),
                    extra_args,
                    is_vision = is_vision,
                    vision_off = disable_vision,
                ),
                n_batch,
                n_ubatch,
                extra_args,
            )

            # Backstop for what the pre-teardown probes fail open on.
            non_chat = self._non_chat_gguf_refusal(model_path)
            if non_chat:
                logger.error("Refusing non-chat GGUF: %s (%s)", non_chat, model_path)
                raise ValueError(non_chat)

            # Block-diffusion GGUFs (DiffusionGemma) cannot run on llama-server;
            # serve them with the diffusion runner (same OpenAI-compat interface).
            if self._is_diffusion:
                # The diffusion runner cannot translate Vulkan ordinals to CUDA IDs.
                if is_vulkan_backend and gpu_ids and gpu_ids_are_vulkan_ordinals is not False:
                    raise ValueError(_VULKAN_DIFFUSION_GPU_IDS_ERROR)
                # This path skips the command builder that clears these.
                self._layer_preserves_tensor_intent = False
                # This path must reset the drafter verdict like _build_speculative_flags, or a stale one relaunches.
                self._mtp_draft_path = None
                self._mtp_draft_suppressed_path = None
                self._mtp_draft_suppressed_reason = None
                # And the verdict on why the last load had no drafter, for the same
                # reason once more: _build_speculative_flags clears it at the top of
                # every load that reaches it, and this path never does. Both retry
                # rules in the dedupe read it -- the drafter one and the binary one --
                # and a stale answer would relaunch this server on every Apply for a
                # drafter it was never going to carry.
                self._spec_fallback_reason = None
                self._spec_drafter_kind = None
                # Discovery runs before the metadata read that says diffusion, so a
                # transient sidecar failure can set this for a drafterless server.
                self._dflash_retry_needed = False
                # Same reason: this path returns before the launch block, and the
                # diffusion runner ignores the budget, so a previous llama-server's
                # fraction would relaunch a healthy diffusion server on every Apply.
                self._vram_fraction_launched = None
                # Outside the lock, as for llama-server: the Auto layer fit reads free VRAM,
                # which a just-killed runner still holds until the driver reclaims it.
                self._wait_for_vram_settle(since_kill = self._last_kill_monotonic)
                with self._lock:
                    if _load_cancelled():
                        logger.info("Load cancelled before diffusion server start")
                        return False
                    return self._start_diffusion_server(
                        model_path = model_path,
                        gguf_path = gguf_path,
                        hf_repo = hf_repo,
                        hf_variant = hf_variant,
                        model_identifier = model_identifier,
                        n_ctx = n_ctx,
                        extra_args = extra_args,
                        gpu_ids = gpu_ids,
                        gpu_memory_mode = gpu_memory_mode,
                        gpu_layers = gpu_layers,
                        cancelled = _load_cancelled,
                    )

            if not binary:
                # Locked binary (antivirus / in-flight install) means retry, not reinstall.
                locked = self._find_llama_server_binary(include_denied = True)
                if locked:
                    raise RuntimeError(
                        f"llama-server at {locked} is temporarily unavailable "
                        "(access-denied; antivirus or an in-flight install). "
                        "Retry the load once it is released."
                    )
                # Typed error so /load returns an actionable 400, not a 500.
                raise LlamaServerNotFoundError(LLAMA_SERVER_NOT_FOUND_DETAIL)

            server_caps = _launch_caps(binary)
            self._reserves_micro_batch_outputs = self.reserves_micro_batch_outputs(binary)
            self._resumes_thoughts = self.resumes_thoughts(binary)

            # Outside self._lock so /unload, /cancel, /status aren't blocked.
            self._wait_for_vram_settle(since_kill = self._last_kill_monotonic)

            # ── Phase 3: start llama-server (under lock) ──────────────
            with self._lock:
                # Re-check cancel inside lock
                if _load_cancelled():
                    logger.info("Load cancelled before server start")
                    return False

                self._port = self._find_free_port()

                # Seed safe defaults before probing so the except path has valid state.
                ctx_override = parse_ctx_override(extra_args)
                requested_ctx = resolve_requested_ctx(extra_args, n_ctx)
                swa_full = _swa_full_from_args_or_env(extra_args)

                # Size from the emitted batch (floor max(slots, 2)), not the requested one.
                def _ubatch_for_slots(slots: int) -> Optional[int]:
                    return _extra_args_n_ubatch(
                        extra_args,
                        n_ctx = (requested_ctx if requested_ctx > 0 else self._context_length),
                        n_batch = _emitted_n_batch(n_batch, slots),
                        n_ubatch = n_ubatch,
                    )

                _effective_ubatch = _ubatch_for_slots(n_parallel)

                # The budget is per slot and the fit can still cut n_parallel, so both
                # counts are taken after it settles, as _effective_ubatch is below.
                def _ctx_checkpoints_for_final_slots() -> int:
                    return effective_ctx_checkpoints_for_caps(
                        server_caps,
                        extra_args,
                        ctx_checkpoints,
                        per_checkpoint_bytes = self._ctx_checkpoint_bytes(
                            cache_type_kv, swa_full = swa_full, flash_attn = planned_flash_attn
                        ),
                        n_parallel = n_parallel,
                        total_host_bytes = ((self._host_memory_capacity_mib() or 0) * 1024 * 1024)
                        or None,
                    )

                _requested_ctx_checkpoints = (
                    resolve_ctx_checkpoints(extra_args, ctx_checkpoints)
                    if server_caps.get("ctx_checkpoints_flag")
                    else 0
                )
                # Snapshots are host RAM (copied device-to-host): only a host-RAM pool pays.
                _fit_ctx_checkpoints = (
                    0 if self._rollback_state_bytes(1) > 0 else _requested_ctx_checkpoints
                )
                # --embedding forces n_batch = n_ubatch, which aborts a load below the slots.
                if (
                    self.is_embedding_gguf
                    and _effective_ubatch is not None
                    and _effective_ubatch < n_parallel
                ):
                    # max(): '-b 0' resolves to 0, and --parallel 0 is rejected.
                    _embedding_slots = max(1, _effective_ubatch)
                    logger.warning(
                        "Reducing serving slots from %d to %d: llama-server caps the batch "
                        "at the %d-token micro-batch under --embedding and aborts when that "
                        "is below the slot count.",
                        n_parallel,
                        _embedding_slots,
                        _effective_ubatch,
                    )
                    n_parallel = _embedding_slots  # allow-slot-clamp: llama-server would abort
                    _effective_ubatch = _ubatch_for_slots(n_parallel)
                planned_kv_unified = _kv_unified_from_args(
                    extra_args,
                    default = n_parallel > 1 and server_caps.get("supports_kv_unified", False),
                )
                _pipeline_parallel_off = _pipeline_parallel_disabled_by_args(
                    extra_args, n_layers = self._n_layers
                )
                cache_override = parse_cache_override(extra_args)
                # Budget the heavier of asymmetric K/V extras; this only affects the reserve.
                _extras_cache = _extra_args_main_cache_type_for_budget(extra_args)
                cache_type_kv = _extras_cache if _extras_cache is not None else cache_type_kv
                _cache_type_from_env = False
                # An unknown type is never emitted, so treat it as unset and adopt the env type.
                if cache_type_kv is not None and (
                    cache_type_kv.strip().lower() not in _VALID_CACHE_TYPES
                ):
                    cache_type_kv = None
                if cache_type_kv is None:
                    # Adopt an inherited env type for the reserve only; not re-emitted.
                    cache_type_kv = _env_main_cache_type_for_budget()
                    _cache_type_from_env = cache_type_kv is not None
                # Dequant scratch keys off the lighter axis, not the heavier one.
                _scratch_cache_type_kv = _planned_scratch_cache_type(
                    None if _cache_type_from_env else cache_type_kv,
                    extra_args,
                )
                # The (K, V) pair this launch will run, for the tensor-abort latch:
                # since #23792 the type reaches the child, so an abort can be specific
                # to it and the latch must not generalise across types.
                _planned_cache_pair = _planned_main_cache_types(
                    None if _cache_type_from_env else cache_type_kv,
                    extra_args,
                )
                # Auto leaves this negative, which is llama.cpp's default and no override.
                _manual_gpu_layers = gpu_layers if gpu_memory_mode == "manual" else None
                # After the cache pair: a quantized V forces flash attention on.
                planned_flash_attn = _reserved_flash_attn_state(
                    _planned_flash_attn_state(
                        extra_args,
                        planned_cache_types = _planned_cache_pair,
                        supports_flash_attn = bool(server_caps.get("supports_flash_attn", True)),
                        tensor_parallel = tensor_parallel,
                        architecture = self._architecture,
                    ),
                    extra_args,
                    tensor_parallel = tensor_parallel,
                    gpu_layers = _manual_gpu_layers,
                )

                def _replan_env(_current_tp: bool) -> "Optional[Mapping[str, str]]":
                    """The environment the CHILD will see: the launch clears a non-layer
                    inherited LLAMA_ARG_SPLIT_MODE, which otherwise turns tensor mode back
                    on inside the helper."""
                    if _current_tp:
                        return None
                    inherited = (os.environ.get("LLAMA_ARG_SPLIT_MODE") or "").strip().lower()
                    if not inherited or inherited == "layer":
                        return None
                    return {
                        key: value
                        for key, value in os.environ.items()
                        if key not in ("LLAMA_ARG_SPLIT_MODE", "LLAMA_ARG_TENSOR_SPLIT")
                    }

                def _replanned_flash_attn(_current_tp: bool) -> bool:
                    """Re-resolve the planned attention after a tensor-mode downgrade: AUTO
                    plans it ON under tensor, so a stale plan budgets a V layer never gets."""
                    _env = _replan_env(_current_tp)
                    return _reserved_flash_attn_state(
                        _planned_flash_attn_state(
                            extra_args,
                            planned_cache_types = _planned_cache_pair,
                            supports_flash_attn = bool(server_caps.get("supports_flash_attn", True)),
                            tensor_parallel = _current_tp,
                            architecture = self._architecture,
                            env = _env,
                        ),
                        extra_args,
                        tensor_parallel = _current_tp,
                        gpu_layers = _manual_gpu_layers,
                        env = _env,
                    )

                # Extras --split-mode wins and inherited tensor env flips it on.
                split_mode_override = parse_split_mode_override(extra_args)
                tensor_parallel = _effective_tensor_parallel(extra_args, tensor_parallel)
                # Nothing to split; tensor mode under the CPU-only mask would abort.
                if gpu_memory_mode == "manual" and gpu_layers == 0:
                    if tensor_parallel or tensor_split:
                        logger.info(
                            "Manual gpu_layers=0: dropping tensor split/parallel "
                            "flags (nothing to split on the GPU)"
                        )
                    tensor_parallel = False
                    tensor_split = None
                    # The plan was made under tensor, the one state forcing AUTO on. Same
                    # for every later downgrade.
                    planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                # Auto ratio is set only on the auto tensor branch; reset so a manual load cannot carry it forward.
                self._gpu_memory_mode = gpu_memory_mode
                # Reset before the branch so an earlier launch's recorded drop cannot excuse this one.
                self._arch_gate_dropped_tensor_split = None
                self._arch_gate_dropped_tensor_parallel = False
                # Same reason, same place: the auto ratio is recorded only on the
                # auto tensor branch, so without this a manual load would carry a
                # previous auto load's ratio forward into the next comparison.
                self._auto_tensor_split = None
                self._auto_tensor_split_emitted = None
                if gpu_memory_mode == "manual" and gpu_layers >= 0:
                    self._gpu_layers = gpu_layers
                    self._n_cpu_moe = n_cpu_moe
                    self._tensor_split = tensor_split
                else:
                    self._gpu_layers = -1
                    self._n_cpu_moe = 0
                    self._tensor_split = None
                    self._auto_tensor_split = None
                    self._auto_tensor_split_emitted = None
                self._mixed_split_flags = []
                self._requested_gpu_ids = [int(i) for i in gpu_ids] if gpu_ids else None
                self._gpu_ids = list(self._requested_gpu_ids) if self._requested_gpu_ids else None
                # Tensor split on <2 GPUs is a no-op and aborts on some architectures.
                if (
                    tensor_parallel
                    and gpu_memory_mode == "manual"
                    and gpu_layers >= 0
                    and self._effective_gpu_count(sorted(gpu_ids) if gpu_ids else None) < 2
                ):
                    logger.info(
                        "Tensor parallelism requested in manual mode but fewer "
                        "than 2 GPUs are in use; ignoring (needs >= 2)."
                    )
                    tensor_parallel = False
                    planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                if tensor_parallel and gpu_memory_mode == "manual" and gpu_layers < 0:
                    logger.info(
                        "Manual mode with Auto layers hands memory management to "
                        "llama.cpp --fit, which is incompatible with tensor "
                        "parallelism; ignoring the tensor split."
                    )
                    tensor_parallel = False
                    planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                if ctx_override is not None and ctx_override > 0:
                    logger.info(f"User --ctx-size {ctx_override} honored; skipping auto-reduce")
                if cache_override is not None:
                    _ck, _cv = parse_cache_override_per_axis(extra_args)
                    logger.info(
                        f"User --cache-type-k/-v (k={_ck}, v={_cv}) honored; "
                        "KV estimate budgets the heavier axis"
                    )
                if split_mode_override is not None:
                    logger.info(
                        f"User --split-mode {split_mode_override} honored; "
                        "reconciled into tensor_parallel state"
                    )
                effective_ctx = requested_ctx if requested_ctx > 0 else (self._context_length or 0)
                max_available_ctx = self._context_length or effective_ctx
                gpus: list[tuple[int, int]] = []
                # Keep fit-budget and launch-flag mmproj resolution in sync.
                launch_mmproj_path = None
                # Only where the switch dropped a usable projector; None also means a missing file or family mismatch, so do not tell the user to re-enable Vision.
                _dv_dropped_image_projector = False
                if not extra_args_disable_mmproj(extra_args):
                    launch_mmproj_path = self._resolve_launch_mmproj_path(
                        model_path = model_path,
                        mmproj_path = mmproj_path,
                        extra_args = extra_args,
                    )
                    # Audio-only projector (ultravox, Voxtral, Qwen3-ASR) stays when Vision is off: suppressing it drops audio input and frees no image VRAM.
                    if disable_vision and launch_mmproj_path:
                        _dv_has_audio, _dv_accepts_image = False, True
                        try:
                            from utils.models.gguf_metadata import mmproj_capabilities
                            _dv_has_audio, _dv_accepts_image = mmproj_capabilities(
                                launch_mmproj_path
                            )
                        except Exception as e:
                            # Unknown reads image-capable upstream, so honor the switch
                            # rather than quietly keep a projector the user turned off.
                            logger.debug(f"mmproj capability read failed: {e}")
                        if _dv_accepts_image:
                            if _dv_has_audio:
                                # One projector serves both modalities (Qwen2.5-Omni) and llama.cpp cannot load half of it, so audio goes with vision.
                                logger.warning(
                                    "Vision is off for this load, so this model's audio "
                                    "input goes too: its projector serves both and "
                                    "llama.cpp cannot load one modality without the "
                                    "other. Turn Vision back on to send audio."
                                )
                            launch_mmproj_path = None
                            _dv_dropped_image_projector = True
                        else:
                            logger.info(
                                "Vision is off for this load, but this model's projector "
                                "is audio-only (no vision tower), so it stays loaded: "
                                "dropping it would remove audio input and free no image "
                                "VRAM."
                            )
                # Virtualised Metal corrupts the encoder: drop the projector unless --no-mmproj-offload exists, else images encode from garbage; only if the probe answered.
                _pv_mmproj_unpinnable = bool(
                    launch_mmproj_path
                    and _paravirtual_cpu_forced
                    and _paravirtual_probe_answered(server_caps)
                    and not server_caps.get("supports_no_mmproj_offload")
                )
                if _pv_mmproj_unpinnable:
                    logger.warning(
                        "Disabling image/audio input for this session: this Mac's "
                        "Metal device is virtualised and this llama-server build has "
                        "no --no-mmproj-offload, so the vision projector would keep "
                        "running on the device whose output is corrupt. Run 'unsloth "
                        "studio update' to install a build that supports it."
                    )
                    launch_mmproj_path = None
                # A stray mmproj must not flip a non-VLM GGUF into vision mode.
                effective_is_vision = bool(launch_mmproj_path) and bool(is_vision)
                if is_vision and not effective_is_vision and not _pv_mmproj_unpinnable:
                    logger.warning(
                        "Vision-capable GGUF loaded without a usable mmproj; "
                        "image input will be disabled for this session"
                    )
                # Seed before the try (except falls through to the launch; the probe may throw first). Capture before manual empties gpus so defaults stay GPU-aware.
                _detected_gpus: list[tuple[int, int]] = []
                _shared_gpu_ids: set[int] = set()
                _vulkan_igpu_ids: frozenset[int] = frozenset()
                _placement_ctx_checkpoints = 0
                # Set when the arch gate emptied a non-empty GPU pool, so the env
                # block below masks the child onto the CPU. Bound before the try for
                # the same reason as _detected_gpus: the except path (--fit on) falls
                # through to the launch, which reads it.
                _arch_gate_forced_cpu = False
                # Not derived from env: an inherited mask would be subtracted twice.
                _launch_pinned_ids: Optional[list] = None
                # The pageable rewrite a CPU replay applied, kept across attempts: the
                # env is shared, so only the first replay to need it produces a note.
                _replay_pageable_override: Optional[str] = None
                # Set by the restored cpu_fallback path, consumed once the launch is
                # healthy: str carries that replay's override note, True means none.
                _restored_cpu_reprice: Union[str, bool, None] = None
                # Whether the planner ran and could not fit; use_fit alone cannot tell.
                _placement_verdict_partial = False
                _ctx_capped_for_vram = False
                # Probed GPUs reporting total 0: a pool shared with host RAM (APU, iGPU, SoC).
                _shared_pool_gpus: set[int] = set()
                _metal_alongside_shortfall: Optional[tuple[int, int]] = None
                # A path that never prices the launch must not commit the previous one's plan.
                self._pending_plan_mib = {}
                # Set by the expert-spill raise after the fit.
                self._moe_spill_batch_restore: Optional[tuple[Optional[int], Optional[int]]] = None
                _moe_cache_candidate = False
                _moe_cache_ram_ok = False
                _shared_gpus = frozenset()
                _integrated_gpus = frozenset()
                # The discrete-first tier; accounting keeps _integrated_gpus.
                _tier_gpus = frozenset()
                # dGPU subsets an explicit pick may price without host-only bytes.
                _discount_prefixes = frozenset()
                # Sized inputs for the tensor-spill planner, None when the fit never
                # priced them. Bound before the try like _placement_verdict_partial:
                # the except arm restores use_fit=True without rebinding
                # kv_cache_bytes, so reading it from the spill arm would be an
                # UnboundLocalError on the path that reaches it most often.
                _spill_inputs: Optional[dict] = None
                # Read after the try: the except arm leaves the planner's locals unbound.
                _tp_planned = False
                # Held, not recorded here: _record_load_warning is first-notice-wins.
                _unmeasured_ctx_notice: Optional[str] = None
                _cuda_ctx_notice: Optional[str] = None
                _ctx_cap_fits = False
                _vram_fit_ctx: Optional[int] = None
                _flat_mtp_engages = False
                total_by_idx: dict[int, int] = {}
                _gpu_mem: list[tuple[int, int, int]] = []
                model_size = None  # set in the fit try; used by the APU RAM guard
                _mtp_will_engage = False
                _separate_draft_launches = False  # a sidecar displaces an embedded head
                # "none" once the fit proves the load needs no demand paging, else None
                # for llama.cpp's own default. Bound before the try like the verdict
                # flags above: the except path falls through to the launch, which reads it.
                _fit_load_mode: Optional[str] = None
                _managed_lazy_flags: Optional[list[str]] = None
                _host_input_embd = 0
                # Layer-fallback min GPUs; raised below on a tensor downgrade. Bound
                # before the try so the --fit-on except path still has it (no UnboundLocal).
                _layer_min_gpus = 1
                # Reject after the try; raising inside would be swallowed into the --fit-on fallback.
                _vulkan_explicit_unmatched = False
                _vulkan_requested_ids: list[int] = []
                _vulkan_available_ordinals: list[int] = []
                # Auto dropped the drafter because only the target fit. Bound before the
                # try: the launch below reads it either way.
                _spec_dropped_no_vram = False
                _mtp_slots_asked: Optional[int] = None
                _mtp_slots_target_ctx: Optional[int] = None
                # The projector runs on the CPU and so allocates no VRAM:
                # --no-mmproj-offload clears mmproj_use_gpu and clip.cpp gates its whole
                # GPU backend on that, leaving no partial offload. Only the paravirtual
                # reason is known this early; the fit below may add the automatic one.
                # Bound before the try, like _spec_dropped_no_vram.
                _mmproj_cpu_pinned = bool(
                    launch_mmproj_path
                    and _paravirtual_cpu_forced
                    and _paravirtual_mmproj_pinnable(server_caps)
                )
                # The APU RAM guard prices system RAM, where a CPU-pinned projector still lives.
                _mmproj_pinned_bytes = 0
                # Raised after this block so the except below cannot swallow it; the handler log line is kept out of this comment because a test string-searches for it.
                _metal_ctx_refusal: Optional[str] = None
                _metal_ctx_warning: Optional[str] = None
                # A discounted Metal ceiling must launch the measured full-offload placement.
                _metal_full_offload_pinned = False
                # --fit-target floor from the Metal wired headroom; 0 off Apple Silicon.
                _metal_fit_target_floor_mib = 0.0
                # --fit-target headroom for a DSpark/DFlash sidecar the child's fitter cannot size.
                _sidecar_fit_reserve_mib = 0
                _sidecar_fit_reserve_eligible_mib = 0
                _sidecar_compute_mib = 0
                _fit_device_count = 1
                _sidecar_reserve_graph_mib = [0]
                _sidecar_draft_layers: Optional[int] = None
                _sidecar_owns_output = False
                _sidecar_override_flags: List[str] = []
                _sidecar_override_pairs: List[List[str]] = []
                _sidecar_reserve_logged: list = []
                _sidecar_reserve_reprice: Optional[Callable[..., int]] = None
                _sidecar_kind_for_fit = None
                # The fit and launch must use the same Model Memory snapshot.
                from utils.model_memory_settings import capture_model_memory_settings

                _mem_settings = capture_model_memory_settings(
                    lambda pair: setattr(self, "_memory_pending_launch", pair)
                )
                try:
                    gguf_size = self._get_gguf_size_bytes(model_path)
                    # Only a GPU-loaded mmproj counts; the resolved value (env or argv) decides.
                    _user_mmproj_offload = _resolved_mmproj_offload(extra_args)
                    mmproj_size = (
                        self._mmproj_vram_bytes(launch_mmproj_path)
                        if (effective_is_vision and _user_mmproj_offload is not False)
                        else 0
                    )
                    if _user_mmproj_offload is False and launch_mmproj_path:
                        # Still in system RAM, which the APU shortfall guard prices.
                        _mmproj_pinned_bytes = self._mmproj_vram_bytes(launch_mmproj_path)
                    model_size = gguf_size + mmproj_size
                    # 2-tuple gpus for existing logic + a total map for the absolute
                    # per-GPU headroom (correct when the GPU is already partly used).
                    # Pass binary so a Vulkan build probes ggml's Vulkan ordinals.
                    # AUTOMATIC placement only. Gating an explicit pin would leave
                    # `gpus` empty, skipping the fit and layer plan and forcing
                    # `--fit on`, yet `gpu_indices` is restored from `gpu_ids` below
                    # so the pin happens anyway. A pinned uncovered GPU is the user's
                    # call and already reports "device kernel image is invalid".
                    # After the download, so the launch reuses fresh rows instead of re-probing (15 s).
                    if self._is_vulkan_backend(binary):
                        _arm_load_probe_memo()
                    _gpu_mem = self._get_gpu_memory(binary, for_llama_server = not gpu_ids)
                    _held_by_others = self._other_planned_vram_mib()
                    _shared_gpus = frozenset(_held_by_others)
                    _gpu_mem = _net_of_other_models_vram(
                        _gpu_mem, _held_by_others, self._media_unallocated_vram_mib()
                    )
                    # Every present device gated out (#7624). Left alone the launch
                    # takes the `--fit on` arm with `gpu_indices` still None, so no
                    # mask is written, the child enumerates every unsupported card and
                    # dies, and the reactive retry cannot help (its guard needs a
                    # truthy `gpu_indices`). CPU is the only placement that runs here.
                    # ROCm auto only; the guard spares CUDA and CPU-only hosts, where
                    # an empty probe just means "no GPU".
                    if (
                        not gpu_ids
                        and not _gpu_mem
                        and not is_vulkan_backend
                        and self._host_torch_is_rocm()
                    ):
                        _ungated = self._get_gpu_memory(binary)
                        # Re-derive: _get_gpu_memory turns any probe error into [], so do not infer from empty.
                        _coverage = self._installed_llama_gfx_archs(binary)
                        _arch_by_id = self._rocm_arch_by_physical_id() if _ungated else {}
                        _all_uncovered = (
                            bool(_ungated)
                            and _coverage is not None
                            and all(
                                (_arch_by_id.get(idx) or "") not in ("", *_coverage)
                                for idx, _free, _total in _ungated
                            )
                        )
                        if _all_uncovered:
                            _arch_gate_forced_cpu = True
                            _present = ", ".join(
                                f"{idx} ({_arch_by_id.get(idx) or 'unknown arch'})"
                                for idx, _free, _total in _ungated
                            )
                            logger.warning(
                                "The installed llama.cpp build has no kernels for "
                                "any GPU on this host (%s), so inference falls back "
                                "to CPU. Reinstall llama.cpp for these devices to "
                                "get GPU inference back.",
                                _present,
                            )
                    _vulkan_igpu_ids = (
                        frozenset(idx for idx, _free, total in _gpu_mem if total <= 0)
                        if is_vulkan_backend
                        else frozenset()
                    )
                    if is_vulkan_backend and not gpu_ids and gpu_memory_mode != "manual":
                        _gpu_mem = self._vulkan_auto_gpu_memory(_gpu_mem)
                    gpus = [(idx, free) for idx, free, _t in _gpu_mem]
                    # Fail-open if none match so a stale UI choice can't strand the load on CPU.
                    if gpu_ids:
                        # Restrict probed pool to selection; if none match, fall back to all GPUs rather than strand on CPU.
                        _wanted_ids = {int(x) for x in gpu_ids}
                        # Reject if ANY requested ordinal is absent, not only when none match.
                        _probed_ordinals = {g[0] for g in gpus}
                        if is_vulkan_backend and not _wanted_ids.issubset(_probed_ordinals):
                            _vulkan_explicit_unmatched = True
                            _vulkan_requested_ids = sorted(_wanted_ids)
                            _vulkan_available_ordinals = sorted(_probed_ordinals)
                        # Restrict the probed pool to the selection; fail-open (keep the
                        # full pool) if none match so a stale UI choice can't strand the
                        # load on CPU (issue #7164).
                        _sel_gpus = [g for g in gpus if g[0] in _wanted_ids]
                        gpus = _sel_gpus if _sel_gpus else gpus
                    total_by_idx = {idx: total for idx, _f, total in _gpu_mem}
                    _shared_pool_gpus = {idx for idx, total in total_by_idx.items() if total <= 0}
                    # GPU picker: restrict every mode to the chosen devices, so
                    # auto selection only considers them and manual mask to
                    # them (the env block below pins CUDA/HIP_VISIBLE_DEVICES).
                    if gpu_ids:
                        _picked = set(gpu_ids)
                        gpus = [g for g in gpus if g[0] in _picked]

                    # GPUs the model will run on -- captured before manual
                    # empty `gpus` to bypass the planner. bool() drives the
                    # GPU-aware speculative defaults; the list feeds the
                    # CPU-fallback check.
                    _detected_gpus = list(gpus)
                    # Auto placement only; Vulkan auto already dropped its iGPUs above.
                    if not gpu_ids and not is_vulkan_backend and len(gpus) > 1:
                        _unified = self._rocm_unified_memory_gpu_ids()
                        # CUDA ids are ordinals; nvidia-smi rows are PCI indices. Join only
                        # where they agree, as _widen_integrated_cuda_rows does.
                        if LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is False or (
                            (os.environ.get("CUDA_DEVICE_ORDER") or "").strip().upper()
                            == "PCI_BUS_ID"
                            and not self._visibility_mask_is_unmappable()
                        ):
                            _unified |= set(
                                LlamaCppBackend._INTEGRATED_CUDA_IDS.get(
                                    LlamaCppBackend._integrated_cuda_mask_key(), ()
                                )
                            )
                        _integrated_gpus = frozenset(idx for idx, _free in gpus if idx in _unified)
                        # A user device flag names ordinals of the base pick's mask, and an
                        # unmappable mask re-emits ordinals as physical ids: keep the base pick.
                        # Host-only bytes still never land on a discrete-only subset.
                        _tier_gpus = _integrated_gpus
                        if _integrated_gpus and (
                            _extra_args_set_any_flag(extra_args, _DEVICE_FLAGS)
                            or any(
                                str(os.environ.get(_v, "")).strip()
                                for _v in ("LLAMA_ARG_DEVICE", "LLAMA_ARG_MAIN_GPU")
                            )
                            or self._visibility_mask_is_unmappable()
                        ):
                            _tier_gpus = frozenset()
                        # Under that pick, host-only bytes may skip only a dGPU subset whose pinned
                        # mask (emitted in ascending ids) keeps every ordinal the flags name on the
                        # same card: a leading run of the inherited order, already ascending.
                        if (
                            _integrated_gpus
                            and not _tier_gpus
                            and not self._visibility_mask_is_unmappable()
                        ):
                            _need = _explicit_device_ordinals_needed(extra_args)
                            if _need is not None:
                                _ids = {idx for idx, _free in gpus}
                                _mask = self._resolve_visible_physical_ids()
                                _order = (
                                    [i for i in _mask if i in _ids]
                                    if _mask is not None
                                    else sorted(_ids)
                                )
                                _discount_prefixes = frozenset(
                                    frozenset(_order[:k])
                                    for k in range(max(1, _need), len(_order) + 1)
                                    if _order[:k] == sorted(_order[:k])
                                )
                    # Vulkan reports total 0 only for integrated GPUs. Their
                    # free "VRAM" is the same host pool the RAM guard prices.
                    _shared_gpu_ids = (
                        {idx for idx, _free in _detected_gpus if total_by_idx.get(idx, 1) <= 0}
                        if is_vulkan_backend
                        else set()
                    )
                    # Checkpoints are host RAM: a discrete card never holds them, but a
                    # unified-memory GPU's "VRAM" is that same pool, so it still pays. ANY
                    # shared candidate keeps the charge: Auto may later pick that one alone.
                    _gpu_ids_now = [idx for idx, _free in gpus]
                    _placement_ctx_checkpoints = (
                        _fit_ctx_checkpoints
                        if _fit_ctx_checkpoints
                        and _gpu_ids_now
                        and (
                            bool(_shared_gpu_ids)
                            or (
                                not is_vulkan_backend
                                and (
                                    self._amd_apu_wants_unified_memory(_gpu_ids_now)
                                    or (
                                        self._integrated_cuda_probe_is_free()
                                        and self._integrated_cuda_unified_memory(_gpu_ids_now)
                                    )
                                )
                            )
                        )
                        else 0
                    )

                    def _subset_ckpts(subset) -> int:
                        # A discrete-tier subset holds no unified-memory GPU, so no checkpoints.
                        if _integrated_gpus and _integrated_gpus.isdisjoint(i for i, _f in subset):
                            return 0
                        return _placement_ctx_checkpoints

                    def _tiered_subsets(
                        ranked: list,
                        floor: int,
                        score_of = None,
                    ) -> list:
                        # (count, prefix) in _select_gpus order: unshared discrete first.
                        tier = LlamaCppBackend._discrete_tier(ranked, _tier_gpus, _shared_gpus)
                        base = [(n, ranked[:n]) for n in range(floor, len(ranked) + 1)]
                        if tier is None or floor > len(tier):
                            return base
                        first = [(n, tier[:n]) for n in range(floor, len(tier) + 1)]
                        if score_of is None:
                            return first + base
                        # Auto: the discrete tier wins only where it gives up nothing the base walk
                        # (the pick before #14372) got. ``score_of`` is None for no fit, else a tuple
                        # (context, drafter kept, ...) the tier must match in every term.
                        base_score = next(
                            (sc for n, sub in base for sc in (score_of(n, sub),) if sc), None
                        )
                        if base_score is None:
                            return first + base
                        kept = []
                        for n, sub in first:
                            sc = score_of(n, sub)
                            if sc and all(t >= b for t, b in zip(sc, base_score)):
                                kept.append((n, sub))
                        return kept + base

                    # The --fit fallback is llama.cpp's own fitter, which knows nothing
                    # about this budget: it keeps its own margin and packs the rest on,
                    # so the slider never reached the path that runs when the fit is
                    # tightest. Hand it the difference, both directions, measured from
                    # the default so an untouched slider leaves the command alone.
                    # --fit-target takes a per-device list in llama.cpp's enumeration
                    # order. Where CUDA's PCI order makes that order provable, each card
                    # gets its own margin, spelled at spawn against the final mask. A
                    # single broadcast value would otherwise have to be sized by the
                    # largest card when lowering, which on mixed cards can exceed a
                    # smaller card's whole memory and leave it unused. Elsewhere (Vulkan,
                    # ROCm, UUID/MIG masks, --device/--rpc) the direction picks the card:
                    # lowering scales by the largest, so no device ends up under the
                    # margin it asked for, raising by the smallest, so none is taken
                    # below its own.
                    if _vram_frac != _CTX_FIT_VRAM_FRACTION and gpus:
                        # Free stands in for an unreported total (MIG/vGPU); deriving from a zero total would silently drop the budget where headroom is hardest to see.
                        _scales = [total_by_idx.get(_idx) or _free for _idx, _free in gpus]
                        _scale = (
                            max(_scales) if _vram_frac < _CTX_FIT_VRAM_FRACTION else min(_scales)
                        )
                        _fit_target_delta_mib = (_CTX_FIT_VRAM_FRACTION - _vram_frac) * _scale
                        # Where llama.cpp's device order is provable, each card gets
                        # its own margin instead (_per_device_fit_target_argv). Every
                        # probed row, not just `gpus`: an unpinned child sees them all.
                        if self._fit_target_per_device_ok(
                            is_vulkan_backend = is_vulkan_backend,
                            extra_args = extra_args,
                            env = os.environ,
                        ):
                            _fit_target_delta_by_idx = {
                                int(_idx): (_CTX_FIT_VRAM_FRACTION - _vram_frac)
                                * (_total if _total and _total > 0 else _free)
                                for _idx, _free, _total in _gpu_mem
                            }

                    _sysmem_fallback = self._sysmem_fallback_risk(binary)

                    def _gpu_usable(g, frac = _vram_frac):
                        # Callers pass the ACTIVE fraction so the ranking matches the
                        # budget the fit then tests, else mixed totals mis-order.
                        idx, free = g
                        return _vram_usable_mib(
                            free,
                            total_by_idx.get(idx, 0),
                            frac,
                            sysmem_fallback = _sysmem_fallback,
                        )

                    def _gpu_rank(
                        g,
                        frac = _vram_frac,
                        floor_mib = 0.0,
                    ):
                        # iGPUs after every discrete card that holds its split buffers (_select_gpus).
                        usable = _gpu_usable(g, frac)
                        return (g[0] not in _shared_gpu_ids and usable > floor_mib, usable)

                    def _pool_budget_mib(subset, frac):
                        # Per-GPU sum, so an unknown-total GPU cannot add free with no cushion.
                        return sum(max(0.0, _gpu_usable(g, frac)) for g in subset)

                    # Resolve effective context: 0 means let llama-server use
                    # the model's native length. Only expand to a known native
                    # length if metadata exists; else keep 0 as a sentinel.
                    if requested_ctx > 0:
                        effective_ctx = requested_ctx
                    elif self._context_length is not None:
                        effective_ctx = self._context_length
                    else:
                        effective_ctx = 0
                    original_ctx = effective_ctx
                    # Default UI ceiling to the native context length;
                    # GPU/VRAM-fit logic below may shrink it on limited HW.
                    max_available_ctx = self._context_length or effective_ctx

                    # Manual + Auto layers: hand memory to llama.cpp --fit; an explicit gpu_ids pick still pins, and a context of 0 lets --fit size it.
                    if gpu_memory_mode == "manual" and gpu_layers < 0:
                        gpus = []
                        effective_ctx = requested_ctx if requested_ctx > 0 else 0
                        original_ctx = effective_ctx
                        # --fit aborts under --split-mode tensor.
                        extra_args = strip_split_mode_only(extra_args)
                        planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                    elif gpu_memory_mode == "manual":
                        # Manual offload: the user owns masking and context; an explicit gpu_ids pick still pins below.
                        gpus = []
                        effective_ctx = (
                            requested_ctx if requested_ctx > 0 else (self._context_length or 0)
                        )
                        original_ctx = effective_ctx
                        # Single-GPU tensor aborts; non-tensor user modes are kept.
                        if tensor_parallel or split_mode_override == "tensor":
                            extra_args = strip_split_mode_only(extra_args)
                            planned_flash_attn = _replanned_flash_attn(tensor_parallel)

                    # Mirrors _build_speculative_flags; uses _spec_canon since Auto may be dspark/dflash.
                    _mtp_effective = _spec_canon
                    _mtp_size_for_fit = _extract_model_size_b(model_identifier)
                    # Draft-simple/draft-eagle3 in extras load a separate model; reserve only when extras name a drafter.
                    _mtp_sub_3b_for_fit = (
                        _mtp_size_for_fit is not None
                        and _mtp_size_for_fit < _MTP_MIN_SIZE_B
                        and not bool(mtp_draft_path)
                    )
                    # Inherited spec env reaches the child only when extras own --spec-type.
                    _spec_env: Mapping[str, str] = _child_spec_env(extra_args)
                    # Extras can run MTP even when Unsloth suppresses its own emission.
                    _user_mtp_via_extras = _extra_args_requests_mtp(extra_args, env = _spec_env)
                    # A non-MTP model-based draft mode (draft-simple/draft-eagle3) in
                    # extras also loads a separate draft model that needs reserving;
                    # engage only when extras actually name a drafter for it.
                    _user_draft_via_extras = _extra_args_requests_separate_draft(
                        extra_args, env = _spec_env
                    ) and bool(_extra_args_mtp_draft_path(extra_args))
                    # Mirrors _build_speculative_flags: reserve only for MTP the launch will emit, which needs a head or drafter and a binary that supports --spec-type mtp.
                    _mtp_model_for_fit = bool(
                        self._nextn_predict_layers
                        or _is_mtp_model_name(model_identifier, model_path)
                        or bool(mtp_draft_path)
                    ) and not (
                        # Drafterless Gemma falls back to ngram-mod; reserve no
                        # drafter VRAM for it (mirrors the launch resolver).
                        _is_gemma_mtp_name(model_identifier, model_path)
                        and not mtp_draft_path
                        and not self._nextn_predict_layers
                    )
                    _mtp_binary_ok = True
                    _mtp_probe_raised = False
                    if not _user_mtp_via_extras:
                        try:
                            _fit_caps = _launch_caps(binary) or {}
                            _sidecar_cap = {
                                "dspark": "supports_dspark",
                                "dflash": "supports_dflash",
                            }.get(_mtp_effective)
                            _mtp_binary_ok = bool(
                                _fit_caps.get(_sidecar_cap)
                                if _sidecar_cap
                                else _fit_caps.get("mtp_token")
                            )
                        except Exception:
                            _mtp_binary_ok = False
                            _mtp_probe_raised = True
                    _auto_studio_mtp = (
                        not _extra_args_set_spec_type(extra_args)
                        and _mtp_model_for_fit
                        and (
                            _mtp_effective in ("mtp", "mtp+ngram", "dspark", "dflash")
                            or (_mtp_effective == "auto" and not _mtp_sub_3b_for_fit)
                        )
                        and (
                            _mtp_binary_ok
                            # Reserve on a raised (uncached) probe too: it re-probes in
                            # _build_speculative_flags and may still engage MTP (embedded
                            # head or separate drafter -- _mtp_model_for_fit covers both).
                            or _mtp_probe_raised
                        )
                    )
                    _mtp_will_engage = bool(
                        _user_mtp_via_extras or _user_draft_via_extras or _auto_studio_mtp
                    )
                    # The duplicated target-KV copy is MTP-only; separate drafters keep no such copy.
                    _engaged_is_mtp = bool(
                        _user_mtp_via_extras
                        or (_auto_studio_mtp and _mtp_effective not in ("dspark", "dflash"))
                    )
                    # Without draft-mtp the embedded head is never loaded, so its blocks
                    # leave the weights the fit prices (about 3 GB on Nemotron 3.5 Super).
                    if not _engaged_is_mtp:
                        _nextn_unloaded = self._unloaded_nextn_bytes(model_path)
                        gguf_size -= _nextn_unloaded
                        model_size -= _nextn_unloaded
                    # The recurrent rollback copies are a WIDER set than that copy
                    # (_TARGET_ROLLBACK_SPEC_TYPES): DSpark and DFlash pay them too,
                    # and draft-simple is the one engaged draft mode that does not,
                    # which is why the pass-through arm reads the types rather than
                    # assuming every extras-owned drafter qualifies.
                    _target_rollback = bool(
                        _auto_studio_mtp
                        or _user_mtp_via_extras
                        or (
                            _user_draft_via_extras
                            and _accumulated_spec_types(extra_args, env = _spec_env)
                            & _TARGET_ROLLBACK_SPEC_TYPES
                        )
                    )

                    # Effective draft depth, by what the CHILD will run on rather than
                    # what was asked for: an extras depth wins (last-wins at launch),
                    # else the field, else the platform default (2 GPU / 3 CPU).
                    _extra_n_max = _extra_args_spec_draft_n_max(extra_args)
                    _mtp_eff_n_max = _extra_n_max
                    if _mtp_eff_n_max is None and _extra_args_set_spec_type(extra_args):
                        # Extras own the spec block, so the child drafts at the env or build default depth;
                        # pricing a request field of 2 would under-reserve a build that drafts 16.
                        try:
                            _depth_caps = _launch_caps(binary) or {}
                        except Exception:
                            _depth_caps = {}
                        # Only the env twin of the flag this build carries; both names only where the probe named no flag, since a post-rename build ignores the legacy name.
                        _depth_flag = _depth_caps.get("spec_draft_n_max_flag")
                        if _depth_flag == "--draft-max":
                            _env_names = ("LLAMA_ARG_DRAFT_MAX",)
                        elif _depth_flag:
                            _env_names = ("LLAMA_ARG_SPEC_DRAFT_N_MAX",)
                        else:
                            _env_names = ("LLAMA_ARG_SPEC_DRAFT_N_MAX", "LLAMA_ARG_DRAFT_MAX")
                        _env_n_max = next(
                            (v for v in map(_spec_env.get, _env_names) if _is_positive_int(v)),
                            None,
                        )
                        if _env_n_max is not None:
                            _mtp_eff_n_max = int(str(_env_n_max).strip())
                        else:
                            # Probe gave no default: never fall back to the platform default (the child drafts at the build depth); assume the deepest shipped llama.cpp.
                            _mtp_eff_n_max = (
                                _depth_caps.get("spec_draft_n_max_default")
                                or self._UNKNOWN_SPEC_DRAFT_N_MAX
                            )
                    elif _mtp_eff_n_max is None:
                        _mtp_eff_n_max = spec_draft_n_max
                    if _mtp_eff_n_max is None:
                        # _detected_gpus, not gpus: manual empties gpus but still uses the GPU draft depth.
                        _mtp_eff_n_max = (
                            3 if _mtp_effective == "dspark" else (2 if _detected_gpus else 3)
                        )
                    # Size the drafter the launch loads: extras --model-draft (last wins), else Unsloth mtp_draft_path, else env. A wrong one under-reserves and OOMs.
                    _cli_draft_for_budget = _extra_args_mtp_draft_path(extra_args, env = {})
                    _studio_draft_for_budget = (
                        mtp_draft_path
                        if (
                            _mtp_will_engage
                            and mtp_draft_path
                            and not _extra_args_set_spec_type(extra_args)
                        )
                        else None
                    )
                    # Same scrubbed view: reserving for an inherited drafter the child
                    # never loads shrinks the context or rejects a placement that fits.
                    _env_draft_for_budget = _extra_args_mtp_draft_path([], env = _spec_env)
                    _mtp_draft_for_budget = (
                        _cli_draft_for_budget or _studio_draft_for_budget or _env_draft_for_budget
                    )
                    # Whether a separate drafter is emitted, taken before the CPU nulling below. Not mtp_draft_path: extras owning --spec-type bypass the Unsloth sidecar.
                    _separate_draft_launches = bool(_mtp_draft_for_budget)
                    # The child honors LLAMA_ARG_N_GPU_LAYERS_DRAFT, so consult the env too.
                    _draft_on_cpu = _extra_args_draft_offloaded_to_cpu(extra_args, env = os.environ)
                    # Kept for the load-mode fit: a CPU drafter's bytes move to host RAM.
                    _cpu_draft_path = _mtp_draft_for_budget if _draft_on_cpu else None
                    if _draft_on_cpu:
                        _mtp_draft_for_budget = None

                    def _launch_split_env() -> dict:
                        e = dict(os.environ)
                        if not tensor_parallel:
                            sm = (e.get("LLAMA_ARG_SPLIT_MODE") or "").strip().lower()
                            if sm and sm != "layer":
                                e.pop("LLAMA_ARG_SPLIT_MODE", None)
                                e.pop("LLAMA_ARG_TENSOR_SPLIT", None)
                        return e

                    def _sidecar_planned_device_count() -> int:
                        count = len(gpu_indices if gpu_indices is not None else _detected_gpus)
                        if not _gpu_ids_own_device_flags:
                            named = _extra_args_main_device(extra_args) or os.environ.get(
                                "LLAMA_ARG_DEVICE"
                            )
                            if named:
                                count = _distinct_device_count(named)
                        if count > 1 and _split_mode_confines_to_one_device(
                            extra_args, _launch_split_env()
                        ):
                            return 1
                        return count

                    def _draft_on_target_device_now(apple_budget_mib: Optional[int] = None) -> bool:
                        # A draft pinned to another device allocates there (on Apple Silicon only
                        # MTL0 / Vulkan0 is the target's).
                        pin = _extra_args_draft_device_pin(extra_args)
                        if pin is None:
                            return True
                        distinct = {d.strip() for d in pin.split(",") if d.strip()}
                        pin = distinct.pop() if len(distinct) == 1 else pin
                        apple = _apple_budget_mib if apple_budget_mib is None else apple_budget_mib
                        # The picker strips competing device extras and env twins at emission, so
                        # this is the launch's placement.
                        _pl_args = (
                            self._strip_device_extra_args(extra_args)
                            if _gpu_ids_own_device_flags
                            else extra_args
                        )
                        _pl_env = _launch_split_env()
                        if gpu_memory_mode == "manual":
                            self._clear_manual_placement_env(_pl_env)
                        if _gpu_ids_own_device_flags:
                            self._clear_device_placement_env(_pl_env)
                        main = _extra_args_main_device(_pl_args)
                        if main is None and not _gpu_ids_own_device_flags:
                            main = _pl_env.get("LLAMA_ARG_DEVICE") or None
                        if main is None and is_vulkan_backend:
                            ids = (
                                gpu_indices
                                if gpu_indices is not None
                                else [g[0] for g in _detected_gpus]
                            )
                            main = ",".join(f"Vulkan{i}" for i in ids) or (
                                "Vulkan0" if apple > 0 else None
                            )
                        elif main is None and apple > 0:
                            main = "MTL0"
                        elif (main is None and pin.strip()) and all(
                            _CUDA_LIKE_DEVICE_RE.match(d.strip())
                            for d in pin.split(",")
                            if d.strip()
                        ):
                            # CUDA / ROCm pins are remapped into the child's mask: only the spawned
                            # argv can tell (_spawn_draft_on_target).
                            return True

                        if main and _split_mode_confines_to_one_device(_pl_args, _pl_env):
                            listed = [d.strip() for d in str(main).split(",") if d.strip()]
                            if len(listed) > 1:
                                at = self._effective_main_gpu(_pl_args, _pl_env)
                                at = 0 if at is None else at
                                main = listed[at] if 0 <= at < len(listed) else None

                        def _names(value: str) -> set:
                            return {d.strip().lower() for d in str(value).split(",") if d.strip()}

                        return bool(main) and bool(_names(pin)) and _names(pin) <= _names(main)

                    _draft_share_unknown = bool(
                        _mtp_draft_for_budget
                        and _draft_card_share_unknown(
                            extra_args,
                            os.environ,
                            n_draft_layers = getattr(
                                self._draft_backend_for(_mtp_draft_for_budget),
                                "_n_layers",
                                None,
                            ),
                        )
                    )
                    _mtp_draft_weights = 0
                    if _mtp_draft_for_budget:
                        try:
                            _mtp_draft_weights = self._get_gguf_size_bytes(_mtp_draft_for_budget)
                        except Exception:
                            _mtp_draft_weights = 0
                    # Draft K/V types (f16 by default; independent extras overrides).
                    _mtp_draft_ck, _mtp_draft_cv = _extra_args_draft_cache_types(extra_args)
                    # Emitted before the extras, so an extra still last-wins.
                    _budget_draft_cache = (
                        spec_draft_cache_type.strip().lower() if spec_draft_cache_type else None
                    )
                    if _budget_draft_cache in _VALID_KV_CACHE_TYPES:
                        _mtp_draft_ck = _mtp_draft_ck or _budget_draft_cache
                        _mtp_draft_cv = _mtp_draft_cv or _budget_draft_cache

                    # Byte-accurate reserve when dims allow, else None -> flat fallback.
                    mtp_overhead_fn: Optional[Callable[[int], int]] = None
                    # True when the byte reserve is weights-only; the flat cushion then covers the draft KV.
                    _mtp_kv_unsized = False
                    if _mtp_will_engage:
                        _probe_ctx = self._context_length or (
                            effective_ctx if effective_ctx > 0 else 4096
                        )
                        _draft_kv_probe = self._mtp_draft_kv_bytes(
                            _probe_ctx,
                            drafter_path = _mtp_draft_for_budget,
                            draft_cache_type_k = _mtp_draft_ck,
                            draft_cache_type_v = _mtp_draft_cv,
                            n_parallel = n_parallel,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            flash_attn = planned_flash_attn,
                        )
                        if (
                            self._estimate_mtp_overhead_bytes(
                                _probe_ctx,
                                spec_draft_n_max = _mtp_eff_n_max,
                                draft_cache_type_k = _mtp_draft_ck,
                                draft_cache_type_v = _mtp_draft_cv,
                                drafter_path = _mtp_draft_for_budget,
                                draft_weights_bytes = _mtp_draft_weights,
                                n_parallel = n_parallel,
                                mtp_keeps_target_ctx = _engaged_is_mtp,
                                target_rollback = _target_rollback,
                                swa_full = swa_full,
                                kv_unified = planned_kv_unified,
                                n_ubatch = _effective_ubatch,
                                flash_attn = planned_flash_attn,
                            )
                            is not None
                        ):
                            # Reserve is weights-only when the draft KV is unsizable.
                            _mtp_kv_unsized = _draft_kv_probe is None

                            # Closure binding this load's draft params; ctx varies.
                            def mtp_overhead_fn(
                                ctx: int,
                                _n: int = _mtp_eff_n_max,
                                _ck: Optional[str] = _mtp_draft_ck,
                                _cv: Optional[str] = _mtp_draft_cv,
                                _dp: Optional[str] = _mtp_draft_for_budget,
                                _w: int = _mtp_draft_weights,
                                _np: int = n_parallel,
                                _mtp: bool = _engaged_is_mtp,
                                _rollback: bool = _target_rollback,
                                _swa_full: bool = swa_full,
                                _kv_unified: bool = planned_kv_unified,
                                _n_ubatch: Optional[int] = _effective_ubatch,
                            ) -> int:
                                # Applied here, not in a wrapper, so every gate taking this callback
                                # prices the draft micro-batch.
                                _n_ubatch = (
                                    _capped_draft_n_ubatch(
                                        extra_args,
                                        os.environ,
                                        ctx,
                                        _emitted_n_batch(n_batch, _np),
                                        n_ubatch,
                                    )
                                    or _n_ubatch
                                )
                                v = self._estimate_mtp_overhead_bytes(
                                    ctx,
                                    spec_draft_n_max = _n,
                                    draft_cache_type_k = _ck,
                                    draft_cache_type_v = _cv,
                                    drafter_path = _dp,
                                    draft_weights_bytes = _w,
                                    n_parallel = _np,
                                    mtp_keeps_target_ctx = _mtp,
                                    target_rollback = _rollback,
                                    swa_full = _swa_full,
                                    kv_unified = _kv_unified,
                                    n_ubatch = _n_ubatch,
                                    # Read at call time: a downgrade re-plans attention, and a
                                    # default arg would go stale.
                                    flash_attn = planned_flash_attn,
                                )
                                return v if v is not None else 0

                    def _mtp_bytes(
                        ctx: int,
                        slots: Optional[int] = None,
                        ubatch: Optional[int] = None,
                    ) -> int:
                        # Reserve scales with slots/ubatch for compact SWA and MLA+recurrent.
                        if mtp_overhead_fn is None:
                            return 0
                        if slots is None:
                            if ubatch:
                                return mtp_overhead_fn(ctx, _n_ubatch = ubatch)
                            return mtp_overhead_fn(ctx)
                        return mtp_overhead_fn(
                            ctx, _np = slots, _n_ubatch = ubatch if ubatch else _effective_ubatch
                        )

                    def _kv_bytes(ctx: int, ctx_checkpoints: int = 0) -> int:
                        # Checkpoints default OFF: placement prices them itself, and only
                        # on unified memory. The load-mode host figure passes a count.
                        return self._estimate_kv_cache_bytes(
                            ctx,
                            cache_type_kv,
                            n_parallel = n_parallel,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            ctx_checkpoints = ctx_checkpoints,
                            flash_attn = planned_flash_attn,
                        )

                    def _cc_bytes(
                        ctx: int,
                        n_gpus: int = 1,
                        slots: int = 0,
                        cache_type: Optional[str] = None,
                    ) -> int:
                        # Compute growth priced from the LIGHTER KV axis (the heavier scalar hides a paired quantized one); replicated per device; read at call time.
                        return max(1, n_gpus) * self._compute_buffer_ctx_bytes(
                            ctx,
                            _ubatch_for_slots(slots) if slots else _effective_ubatch,
                            cache_type or _scratch_cache_type_kv,
                            layer_split = n_gpus > 1 and not _pipeline_parallel_off,
                            flash_attn = planned_flash_attn,
                            n_parallel = slots or n_parallel,
                        )

                    def _cc_split_extra(
                        ctx: int,
                        slots: int = 0,
                        cache_type: Optional[str] = None,
                    ) -> int:
                        # Per-device step from the single-device to split compute rate, for paths choosing GPUs before the count; 0 when llama.cpp declines pipeline parallelism.
                        return max(
                            0,
                            _cc_bytes(ctx, 2, slots, cache_type) // 2
                            - _cc_bytes(ctx, 1, slots, cache_type),
                        )

                    def _layer_compute_buffer(slots: int) -> int:
                        cb = self._estimate_compute_buffer_bytes(
                            n_ubatch = _ubatch_for_slots(slots),
                            n_parallel = slots,
                            per_device_tensor = False,
                        )
                        return (
                            cb if cb > 0 else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
                        )

                    # Layer-split compute buffer (one lump; tensor mode reserves it
                    # per device in _plan_tensor_parallel). Context-independent, so
                    # fold it into the model footprint for the branches below. Falls
                    # back to the flat reserve when dims are missing (returns 0), a
                    # safe upper bound since the tensor buffer >= the layer one.
                    _compute_buffer_pipeline = self._estimate_compute_buffer_bytes(
                        n_ubatch = _effective_ubatch,
                        n_parallel = n_parallel,
                        per_device_tensor = False,
                    )
                    if _compute_buffer_pipeline <= 0:
                        _compute_buffer_pipeline = (
                            self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
                        )

                    # Tensor mode reserves the whole buffer on every selected device.
                    _compute_buffer_tensor = self._estimate_compute_buffer_bytes(
                        n_ubatch = _effective_ubatch,
                        n_parallel = n_parallel,
                        per_device_tensor = True,
                    )
                    if _compute_buffer_tensor <= 0:
                        _compute_buffer_tensor = (
                            self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024
                        )

                    # Reserve extra devices' fixed overhead so a k-GPU split cannot OOM a device.
                    _pipeline_overhead_bytes = self._PIPELINE_PER_DEVICE_OVERHEAD_MIB * 1024 * 1024

                    # Explicit n_ctx: honor it, capping only if no GPU combination fits. Auto: prefer fewer GPUs with reduced context (multi-GPU is slower).
                    gpu_indices, use_fit = None, True
                    # Per-GPU weight proportions for tensor mode (None lets
                    # llama.cpp split by free VRAM).
                    tp_tensor_split: Optional[list[int]] = None
                    # Whether the TP branch planned this load. Not readable from tp_tensor_split (None when llama.cpp sizes it); re-set per retry so a retry starts clean.
                    _tp_planned = False
                    explicit_ctx = requested_ctx > 0
                    # No speculative GPU load when the drafter is CPU-offloaded; a sidecar wins over an embedded head (has_dft), and a head with no sidecar stays reserved.
                    _draft_cpu_no_embedded = _draft_on_cpu and (
                        _separate_draft_launches or not self._nextn_predict_layers
                    )
                    # A replay was fitted without the drafter: re-fit it like a fresh MTP load, before any explicit_ctx reader.
                    if (
                        explicit_ctx
                        and ctx_override is None
                        and intent.max_seq_length_auto_derived
                        # CPU-pinned drafters too: the target still pays rollback state for them.
                        and _mtp_will_engage
                        # Forced = anything that bypasses the Auto drop probe, advanced arguments included.
                        and (
                            (_canonicalize_spec_mode(speculative_type) or "auto") != "auto"
                            or _user_mtp_via_extras
                            or _user_draft_via_extras
                            or _extra_args_set_spec_type(extra_args)
                            or _extra_args_mtp_draft_path(extra_args, env = _spec_env)
                        )
                    ):
                        explicit_ctx = False
                        _replayed_ctx_refit = True

                    # Run before the probe, which is gated on not tensor_parallel but must answer for any load that ends layer-split, so the downgrades must come first.
                    if preserve_multi_gpu_on_layer:
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))

                    if tensor_parallel and self._tensor_quant_kv_unsupported_binary(
                        binary, _planned_cache_pair
                    ):
                        # This build refused quantized KV under tensor: go straight to layer, which keeps the quantized cache, instead of reloading just to hear it again.
                        logger.info(
                            "Tensor parallelism skipped: this llama.cpp build cannot "
                            "use a quantized KV cache with --split-mode tensor "
                            "(needs b9455+); loading with a layer split."
                        )
                        tensor_parallel = False
                        # A missing capability says nothing about capacity, so keep multi-GPU.
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        extra_args = strip_split_mode_only(extra_args)
                        planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                    if tensor_parallel and self._tensor_split_aborts(
                        binary, model_identifier, _planned_cache_pair
                    ):
                        # Aborted on tensor for this model this session; skip tensor upfront.
                        logger.info(
                            "Tensor parallelism skipped: this llama.cpp build aborted "
                            "on --split-mode tensor for this model earlier this "
                            "session; using layer split across %d GPU(s).",
                            len(gpus),
                        )
                        tensor_parallel = False
                        # The abort says nothing about capacity, so keep multi-GPU.
                        _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        # An extras --split-mode tensor would re-engage tensor mode.
                        extra_args = strip_split_mode_only(extra_args)
                        planned_flash_attn = _replanned_flash_attn(tensor_parallel)

                    # Tensor mode replicates a compute buffer on every GPU, so drop
                    # GPUs below that reserve from the set up front (gpu_indices
                    # becomes the CUDA_VISIBLE_DEVICES mask, fully excluding them).
                    tp_gpus = gpus
                    # Manual mode owns the layer count and context, so it skips
                    # the memory-based planner; its toggle still emits
                    # --split-mode tensor below (split by free VRAM, or by the
                    # Split ratio if set). auto plans here.
                    plan_tp = tensor_parallel and gpu_memory_mode != "manual"
                    if plan_tp:
                        # Downstream, incl. the drop probe, prices the projector off these two; drafter is dropped last.
                        _tp_reserve_bytes = self._estimate_compute_buffer_bytes(
                            n_ubatch = _effective_ubatch,
                            n_parallel = n_parallel,
                            per_device_tensor = True,
                        )
                        reserve_mib = (
                            _tp_reserve_bytes // (1024 * 1024)
                            if _tp_reserve_bytes > 0
                            else self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB
                        )
                        # Admit by usable budget, not raw free (a partly-used big card has no budget left).
                        tp_gpus = [g for g in gpus if _gpu_usable(g) >= reserve_mib]

                    if plan_tp and len(tp_gpus) < 2:
                        # Tensor needs >= 2 usable GPUs; otherwise drop --split-mode tensor (a single GPU is a no-op and zero GPUs must not reach llama-server) and use layer or CPU.
                        logger.info(
                            "Tensor parallelism requested but only %d of %d GPU(s) "
                            "have enough free VRAM for the compute buffer; "
                            "ignoring (needs >= 2).",
                            len(tp_gpus),
                            len(gpus),
                        )
                        tensor_parallel = False
                        # Cards below tensor's reserve can still do layer split, so keep multi-GPU.
                        if len(gpus) >= 2:
                            _layer_min_gpus = max(_layer_min_gpus, len(gpus))
                        extra_args = strip_split_mode_only(extra_args)
                        planned_flash_attn = _replanned_flash_attn(tensor_parallel)

                    # Normalize before anything prices it: _mtp_bytes reads mtp_overhead_fn at call time.
                    if _draft_cpu_no_embedded and mtp_overhead_fn is not None:
                        # Drafter on CPU: only the target's rollback snapshots and verification rows
                        # stay on GPU.
                        def _cpu_draft_target_state(
                            _ctx: int,
                            _np: int = n_parallel,
                            _n_ubatch: Optional[int] = _effective_ubatch,
                            _n: int = _mtp_eff_n_max,
                            _rollback: bool = _target_rollback,
                        ) -> int:
                            if _n <= 0:
                                return 0
                            rollback = self._rollback_state_bytes(_np) * _n if _rollback else 0
                            return rollback + self._spec_verify_rows_bytes(_np, _n)

                        mtp_overhead_fn = (
                            _cpu_draft_target_state
                            if _cpu_draft_target_state(effective_ctx) > 0
                            else None
                        )
                        _mtp_kv_unsized = False

                    # Projector goes to host RAM first when the load does not fit, but never drops vision; pin only helps where a device has its own budget (total > 0).
                    _mm_pin_deferred = False

                    def _apply_mmproj_cpu_pin(floor_ctx: int) -> None:
                        nonlocal _mmproj_cpu_pinned, _mmproj_pinned_bytes
                        nonlocal mmproj_size, model_size
                        _mmproj_cpu_pinned = True
                        _mmproj_pinned_bytes = mmproj_size
                        # No KV estimate: the fit never applies a floor, so pricing the reserve at one promises unseen room.
                        mmproj_size = 0
                        model_size = gguf_size
                        # Announce a CPU-resident projector: set after the per-load reset and before recovery paths, which override it with a more specific reason.
                        self._mmproj_fallback_reason = "cpu_offload"
                        logger.info(
                            "Auto: running the vision projector on the CPU "
                            "(--no-mmproj-offload); it does not fit in VRAM "
                            "alongside the model at %d context. Image encoding "
                            "gets slower, text generation is unaffected. Pass "
                            "--mmproj-offload in the advanced arguments to keep it "
                            "on the GPU.",
                            floor_ctx,
                        )

                    def _host_input_bytes_now(weights: int) -> int:
                        if not (
                            gpus
                            and not _integrated_gpus
                            and not _shared_gpu_ids
                            and not _shared_pool_gpus
                            and not _metal_capable_host()
                            and not self._amd_apu_wants_unified_memory([i for i, _f in gpus])
                            and not set(
                                LlamaCppBackend._INTEGRATED_CUDA_IDS.get(
                                    LlamaCppBackend._integrated_cuda_mask_key(), ()
                                )
                            ).intersection(i for i, _f in gpus)
                        ):
                            return 0
                        # A streamed table stays on the host whatever -ot says.
                        _inp_extras = (
                            self._strip_device_extra_args(extra_args)
                            if _gpu_ids_own_device_flags
                            else extra_args
                        )
                        _inp_env = dict(os.environ)
                        if gpu_memory_mode == "manual":
                            self._clear_manual_placement_env(_inp_env)
                        if _gpu_ids_own_device_flags:
                            self._clear_device_placement_env(_inp_env)
                        self._reconcile_split_mode_env(_inp_env, tensor_parallel = tensor_parallel)
                        try:
                            _inp_lazy = "off"
                            if server_caps.get("supports_lazy_mode"):
                                _inp_lazy = _effective_lazy_mode(
                                    _inp_extras,
                                    _inp_env,
                                    flag = str(server_caps.get("lazy_mode_flag") or "--lazy-mode"),
                                )
                            if _inp_lazy == "auto" and self._lazy_auto_resolves_off(
                                gpu_indices = (
                                    gpu_indices
                                    if gpu_indices is not None or not gpu_ids
                                    else [int(i) for i in gpu_ids]
                                ),
                                detected_gpus = _detected_gpus,
                                shared_gpu_ids = _shared_gpu_ids,
                                is_vulkan_backend = is_vulkan_backend,
                                extra_args = _inp_extras,
                                env = _inp_env,
                                tensor_parallel = tensor_parallel,
                                integrated_gpu_ids = _vulkan_igpu_ids,
                            ):
                                _inp_lazy = "off"
                            found = _host_pinned_input_bytes(
                                self._gguf_tensor_scan(model_path),
                                _inp_extras,
                                _inp_env,
                                lazy_mode = _inp_lazy,
                                host_forced = self._host_forced_table_archs(binary),
                            )
                        except Exception as e:  # unread header: charge the whole file
                            logger.debug("Host-pinned input embeddings unpriced: %s", e)
                            return 0
                        return min(max(0, found), max(0, int(weights) - 1))

                    _mm_budgeted_gpus = [
                        (_idx, _free) for _idx, _free in gpus if total_by_idx.get(_idx, 0) > 0
                    ]
                    _discrete_vram = bool(_mm_budgeted_gpus)
                    if (
                        effective_is_vision
                        and mmproj_size > 0
                        and _discrete_vram
                        and not _mmproj_cpu_pinned
                        and gpu_memory_mode != "manual"
                        # Not gated on tensor_parallel: the answer is never applied to a tensor load, but the tensor weight-budget check may downgrade one to layer.
                        and _paravirtual_mmproj_pinnable(server_caps)
                        # arg.cpp applies env before argv, so a user's spelling in either owns the placement.
                        and not _extra_args_set_mmproj_offload(extra_args)
                        and not _env_sets_mmproj_offload()
                    ):
                        # Is model+drafter+projector VRAM-resident? Auto asks at the floor (shrinks context first); explicit asks at its requested length, since --fit spills layers.
                        _mm_mtp_on_gpu = _mtp_will_engage and not _draft_cpu_no_embedded
                        _mm_frac = _vram_frac - (
                            _MTP_VRAM_RESERVE_FRAC
                            if (_mm_mtp_on_gpu and (mtp_overhead_fn is None or _mtp_kv_unsized))
                            else 0.0
                        )
                        _mm_floor_ctx = (
                            effective_ctx
                            if explicit_ctx
                            else min(self._MMPROJ_FIT_FLOOR_CTX, effective_ctx)
                        )
                        _mm_need = (
                            gguf_size
                            - _host_input_bytes_now(gguf_size)
                            + mmproj_size
                            + _compute_buffer_pipeline
                            + self._CUDA_CONTEXT_RESERVE_BYTES
                            + int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                            + (self._MTP_DRAFT_COMPUTE_BYTES if _mm_mtp_on_gpu else 0)
                        )
                        if _mm_floor_ctx > 0 and self._can_estimate_kv():
                            _mm_need += (
                                _kv_bytes(_mm_floor_ctx)
                                + _cc_bytes(_mm_floor_ctx)
                                + _mtp_bytes(_mm_floor_ctx)
                            )
                        else:
                            # Flat fraction is the reserve when _mtp_bytes is 0; the probe must test the budget the fit uses.
                            _mm_floor_ctx = self._context_length or effective_ctx or 4096
                            _mm_need += _mtp_bytes(_mm_floor_ctx)
                        # Use the same selector, fraction and split-aware overhead as the placement,
                        # so this probe
                        # is never more optimistic than the placement it gates.
                        _mm_split_aware = self._can_estimate_kv()

                        def _mm_probe_needs_fit(need: int, devices: list) -> bool:
                            return (
                                self._select_gpus_split_aware(
                                    need,
                                    devices,
                                    usable_fraction = _mm_frac,
                                    total_by_idx = total_by_idx,
                                    per_device_overhead_bytes = _pipeline_overhead_bytes
                                    + _cc_bytes(_mm_floor_ctx),
                                    min_gpus = _layer_min_gpus,
                                    split_extra_bytes = _cc_split_extra(_mm_floor_ctx),
                                    shared_gpu_ids = _shared_gpu_ids,
                                )
                                if _mm_split_aware
                                else self._select_gpus(
                                    need,
                                    devices,
                                    usable_fraction = _mm_frac,
                                    total_by_idx = total_by_idx,
                                    per_device_overhead_bytes = _pipeline_overhead_bytes,
                                    min_gpus = _layer_min_gpus,
                                    shared_gpu_ids = _shared_gpu_ids,
                                )
                            )[1]

                        _mm_needs_fit = _mm_probe_needs_fit(_mm_need, _mm_budgeted_gpus)
                        # An APU reporting a total is budgeted above, but its "VRAM" is host
                        # RAM, so moving the projector frees nothing there. Also pin when that
                        # alone lets the discrete cards hold the model (#7624).
                        _mm_discrete = LlamaCppBackend._discrete_tier(
                            _mm_budgeted_gpus, _tier_gpus, _shared_gpus
                        )
                        if (
                            not _mm_needs_fit
                            and _mm_discrete
                            and _layer_min_gpus <= len(_mm_discrete)
                        ):
                            _mm_needs_fit = _mm_probe_needs_fit(
                                _mm_need, _mm_discrete
                            ) and not _mm_probe_needs_fit(
                                _mm_need
                                - mmproj_size
                                - int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0)),
                                _mm_discrete,
                            )
                        if _mm_needs_fit:
                            if tensor_parallel:
                                # Held, not applied here: layer-split numbers would misprice a tensor load. The tensor downgrade below needs this verdict.
                                _mm_pin_deferred = True
                            else:
                                _apply_mmproj_cpu_pin(_mm_floor_ctx)

                    # Auto drops the drafter rather than trade context or --fit offload for it, priced over
                    # the same subsets the placement loop walks. Skipped under tensor parallelism.
                    if (
                        _mtp_will_engage
                        and (_canonicalize_spec_mode(speculative_type) or "auto") == "auto"
                        and not _user_mtp_via_extras
                        and not _user_draft_via_extras
                        and not _extra_args_set_spec_type(extra_args)
                        # llama.cpp loads a bare --model-draft anyway (has_dft()), so keep the reserve.
                        and not _extra_args_mtp_draft_path(extra_args, env = _spec_env)
                        and not _draft_cpu_no_embedded
                        and not _draft_share_unknown
                        and _draft_on_target_device_now(apple_budget_mib = 0)
                        and not tensor_parallel
                        and gpus
                        and effective_ctx > 0
                        and self._can_estimate_kv()
                    ):

                        def _probe_frac(drafter: bool) -> float:
                            # The flat fraction is the reserve whenever _mtp_bytes is 0.
                            # Same budget the fit uses, else the probe answers for a
                            # card size the fit never tests.
                            return _vram_frac - (
                                _MTP_VRAM_RESERVE_FRAC
                                if (drafter and (mtp_overhead_fn is None or _mtp_kv_unsized))
                                else 0.0
                            )

                        def _probe_base(
                            drafter: bool,
                            n: int,
                            slots: int = 0,
                        ) -> int:
                            # model_size_fit's terms, before it is built below.
                            _soft = self._CUDA_CONTEXT_RESERVE_BYTES
                            if effective_is_vision and mmproj_size > 0:
                                _soft += int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                            if drafter:
                                _soft += self._MTP_DRAFT_COMPUTE_BYTES
                            return (
                                model_size
                                - _host_input_bytes_now(model_size)
                                + (
                                    _layer_compute_buffer(slots)
                                    if slots
                                    else _compute_buffer_pipeline
                                )
                                + _soft
                                + max(0, n - 1) * _pipeline_overhead_bytes
                            )

                        # Same order and budget as the auto placement loop.
                        def _probe_rank(drafter: bool) -> list:
                            return sorted(
                                gpus,
                                key = lambda g: _gpu_rank(
                                    g,
                                    _probe_frac(drafter),
                                    _pipeline_overhead_bytes / (1024 * 1024),
                                ),
                                reverse = True,
                            )

                        _probe_overhead_mib = _pipeline_overhead_bytes / (1024 * 1024)

                        def _probe_floor(ranked: list, drafter: bool) -> int:
                            # Same floor as the placement loop _auto_min_gpus, so a one-GPU placement the loop forbids cannot be the one that saves the drafter.
                            return max(
                                1,
                                min(
                                    _layer_min_gpus,
                                    sum(
                                        1
                                        for g in ranked
                                        if _gpu_usable(g, _probe_frac(drafter))
                                        > _probe_overhead_mib
                                    )
                                    or 1,
                                ),
                            )

                        # Both rankings: the unsized-drafter fraction can reorder heterogeneous cards.
                        _probe_orders = [_probe_rank(False)]
                        _ranked_w = _probe_rank(True)
                        if [id(g) for g in _ranked_w] != [id(g) for g in _probe_orders[0]]:
                            _probe_orders.append(_ranked_w)
                        _target_fits_somewhere = False
                        _both_fit_somewhere = False
                        _probe_ctx = 0
                        _probe_need = _probe_have = 0.0
                        # (GPU count, target-only ctx, budget with drafter, checkpoints) per
                        # drafter-ranked subset; a discrete-tier subset pays no checkpoints.
                        _target_placements: list[tuple[int, int, float, int]] = []
                        _drafter_order = _probe_orders[-1]

                        def _probe_target_ctx(_n: int, _subset) -> Optional[int]:
                            # The target-only context the placement loop gives ``_subset``, or None.
                            _cc_n = lambda c, _k = _n: _cc_bytes(c, _k)
                            _base_wo = _probe_base(False, _n)
                            _budget_wo = _pool_budget_mib(_subset, _probe_frac(False))
                            # Explicit context is honored verbatim, so that is what the
                            # drafter has to fit alongside; Auto gets its own best cap.
                            _ctx_wo = (
                                effective_ctx
                                if explicit_ctx
                                else self._fit_context_to_vram(
                                    effective_ctx,
                                    _budget_wo,
                                    _base_wo,
                                    cache_type_kv,
                                    swa_full = swa_full,
                                    n_parallel = n_parallel,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = _effective_ubatch,
                                    flash_attn = planned_flash_attn,
                                    mtp_engaged = False,
                                    mtp_overhead_fn = None,
                                    compute_ctx_bytes_fn = _cc_n,
                                    budget_frac = 1.0,
                                    pooled = True,
                                    total_mib = None,
                                    ctx_checkpoints = _subset_ckpts(_subset),
                                )
                            )
                            if _ctx_wo <= 0:
                                return None
                            _shared = _kv_bytes(_ctx_wo) + _cc_n(_ctx_wo)
                            _foot_wo = (_base_wo + _shared) / (1024 * 1024)
                            if _foot_wo > _budget_wo:
                                return None
                            # The pooled figure hides the compute buffer every device
                            # replicates, so the weakest card may not hold the context
                            # the pool priced and the placement loop caps to what it
                            # does. Charging the drafter at the uncapped context
                            # condemns it at a context this load never reaches. Same
                            # reserve and cap the auto-context loop below applies, so
                            # the two cannot disagree. Auto only: an explicit context
                            # is honored verbatim and overflows to --fit.
                            _usable_wo = [_gpu_usable(g, _probe_frac(False)) for g in _subset]
                            _probe_reserve_at = lambda c, _k = _n: (
                                (_pipeline_overhead_bytes if _k > 1 else 0) + _cc_bytes(c, _k) // _k
                            )
                            if not self._every_gpu_holds_reserve(
                                _usable_wo, _probe_reserve_at(_ctx_wo)
                            ):
                                if explicit_ctx:
                                    # Nothing to cap: this subset cannot hold it, and
                                    # _select_gpus_split_aware will go to --fit too.
                                    # Calling it a fit would drop the drafter and then
                                    # report a pin that never happened.
                                    return None
                                _ctx_wo = self._cap_ctx_to_per_device_reserve(
                                    _ctx_wo, _usable_wo, _probe_reserve_at
                                )
                                if _ctx_wo <= 0:
                                    return None
                                # Every pooled term shrinks with the context, so this
                                # cannot newly fail; re-price rather than lean on it.
                                _shared = _kv_bytes(_ctx_wo) + _cc_n(_ctx_wo)
                                _foot_wo = (_base_wo + _shared) / (1024 * 1024)
                                if _foot_wo > _budget_wo:
                                    return None
                            return _ctx_wo

                        _slots_reducible = (
                            n_parallel > 1
                            and intent.n_parallel_from_default
                            and _extra_args_n_parallel(extra_args, env = {}) is None
                        )

                        def _mtp_foot_mib(n: int, ctx: int, s: int) -> float:
                            ub = _ubatch_for_slots(s)
                            return (
                                _probe_base(True, n, s)
                                + self._estimate_kv_cache_bytes(
                                    ctx,
                                    cache_type_kv,
                                    n_parallel = s,
                                    swa_full = swa_full,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = ub,
                                    flash_attn = planned_flash_attn,
                                )
                                + _cc_bytes(ctx, n, s)
                                + _mtp_bytes(ctx, s, ub)
                            ) / (1024 * 1024)

                        def _ctx_with_drafter(
                            n: int, ctx: int, budget: float, s: int, ckpts: int
                        ) -> int:
                            if explicit_ctx:
                                return ctx if _mtp_foot_mib(n, ctx, s) <= budget else 0
                            ub = _ubatch_for_slots(s)
                            fitted = self._fit_context_to_vram(
                                ctx,
                                budget,
                                _probe_base(True, n, s),
                                cache_type_kv,
                                swa_full = swa_full,
                                n_parallel = s,
                                kv_unified = planned_kv_unified,
                                n_ubatch = ub,
                                flash_attn = planned_flash_attn,
                                mtp_engaged = True,
                                mtp_overhead_fn = (
                                    functools.partial(mtp_overhead_fn, _np = s, _n_ubatch = ub)
                                    if mtp_overhead_fn is not None
                                    else None
                                ),
                                compute_ctx_bytes_fn = lambda c: _cc_bytes(c, n, s),
                                budget_frac = 1.0,
                                pooled = True,
                                total_mib = None,
                                ctx_checkpoints = ckpts,
                            )
                            return (
                                fitted
                                if fitted > 0 and _mtp_foot_mib(n, fitted, s) <= budget
                                else 0
                            )

                        def _probe_slots(_n: int, _subset, _ctx: int) -> int:
                            # Most slots the slot search below can keep the drafter at here (ctx
                            # kept, less the trim at one slot), 0 if none or slots are pinned.
                            if not _slots_reducible:
                                return 0
                            _budget = _pool_budget_mib(_subset, _probe_frac(True))
                            _ckpts = _subset_ckpts(_subset)
                            for _s in range(n_parallel - 1, 0, -1):
                                _keep = 1 - (
                                    _MTP_SLOT_CTX_TRIM if _s == 1 and not explicit_ctx else 0
                                )
                                _c = _ctx_with_drafter(_n, _ctx, _budget, _s, _ckpts)
                                if _c > 0 and _c >= _ctx * _keep:
                                    return _s
                            return 0

                        def _probe_score(_n: int, _subset):
                            # (target context, drafter fits beside it at that context, slots it
                            # keeps); explicit context is the same everywhere.
                            _ctx = _probe_target_ctx(_n, _subset)
                            if _ctx is None:
                                return None
                            _need = (
                                _probe_base(True, _n)
                                + _kv_bytes(_ctx)
                                + _cc_bytes(_ctx, _n)
                                + _mtp_bytes(_ctx)
                            ) / (1024 * 1024)
                            if _need <= _pool_budget_mib(_subset, _probe_frac(True)):
                                return (_ctx, 1, n_parallel)
                            # No drafter at the requested slots: the placement keeping more
                            # slots for it wins, so the tier cannot cost the base walk slots.
                            return (_ctx, 0, _probe_slots(_n, _subset, _ctx))

                        for _probe_ranked in _probe_orders:
                            if _both_fit_somewhere:
                                break
                            _probe_min_gpus = _probe_floor(_probe_ranked, False)
                            # The placement loop's subsets in its order: discrete first.
                            for _n, _subset in _tiered_subsets(
                                _probe_ranked,
                                _probe_min_gpus,
                                score_of = _probe_score,
                            ):
                                _ctx_wo = _probe_target_ctx(_n, _subset)
                                if _ctx_wo is None:
                                    continue
                                _cc_n = lambda c, _k = _n: _cc_bytes(c, _k)
                                _shared = _kv_bytes(_ctx_wo) + _cc_n(_ctx_wo)
                                _foot_w = (
                                    _probe_base(True, _n) + _shared + _mtp_bytes(_ctx_wo)
                                ) / (1024 * 1024)
                                _budget_w = _pool_budget_mib(_subset, _probe_frac(True))
                                if not _target_fits_somewhere:
                                    _target_fits_somewhere = True
                                    _probe_ctx, _probe_need, _probe_have = (
                                        _ctx_wo,
                                        _foot_w,
                                        _budget_w,
                                    )
                                if _probe_ranked is _drafter_order:
                                    _target_placements.append(
                                        (_n, _ctx_wo, _budget_w, _subset_ckpts(_subset))
                                    )
                                if _foot_w <= _budget_w:
                                    _both_fit_somewhere = True
                                    break
                                # The loop would re-cap context with the drafter, which is the trade
                                # being refused.
                                _ctx_w = (
                                    0
                                    if explicit_ctx
                                    else self._fit_context_to_vram(
                                        _ctx_wo,
                                        _budget_w,
                                        _probe_base(True, _n),
                                        cache_type_kv,
                                        swa_full = swa_full,
                                        n_parallel = n_parallel,
                                        kv_unified = planned_kv_unified,
                                        n_ubatch = _effective_ubatch,
                                        flash_attn = planned_flash_attn,
                                        mtp_engaged = True,
                                        mtp_overhead_fn = mtp_overhead_fn,
                                        compute_ctx_bytes_fn = _cc_n,
                                        budget_frac = 1.0,
                                        pooled = True,
                                        total_mib = None,
                                        ctx_checkpoints = _subset_ckpts(_subset),
                                    )
                                )
                                if (
                                    _ctx_w > 0
                                    and (
                                        _probe_base(True, _n)
                                        + _kv_bytes(_ctx_w)
                                        + _cc_n(_ctx_w)
                                        + _mtp_bytes(_ctx_w)
                                    )
                                    / (1024 * 1024)
                                    <= _budget_w
                                ):
                                    # A NextN-only head is the main decode speedup: pay context.
                                    if (
                                        _engaged_is_mtp
                                        and _arch_has_fast_mla_mtp(
                                            getattr(self, "_architecture", None)
                                        )
                                        and _ctx_w >= min(_ctx_wo, _FAST_MTP_MIN_CTX)
                                    ):
                                        _both_fit_somewhere = True
                                        logger.info(
                                            "Auto: keeping the embedded MTP head; context %d -> %d "
                                            "so it fits (%.1f GB budget).",
                                            _ctx_wo,
                                            _ctx_w,
                                            _budget_w / 1024,
                                        )
                                    break
                        # Fewer slots before no drafter. The walk takes the first subset holding the
                        # drafter, so it must keep its target-only ctx (less the trim at one slot).
                        # An extras --parallel wins at launch, so it is kept; the env twin is scrubbed.
                        if _target_fits_somewhere and not _both_fit_somewhere and _slots_reducible:
                            _mtp_slots = _mtp_slots_ctx = 0
                            for _s in range(n_parallel - 1, 0, -1):
                                _keep = 1 - (
                                    _MTP_SLOT_CTX_TRIM if _s == 1 and not explicit_ctx else 0
                                )
                                for _n, _ctx_c, _budget_c, _ckpts_c in _target_placements:
                                    _c = _ctx_with_drafter(_n, _ctx_c, _budget_c, _s, _ckpts_c)
                                    if _c <= 0:
                                        continue
                                    if _c >= _ctx_c * _keep:
                                        _mtp_slots, _mtp_slots_ctx = _s, _c
                                        _mtp_slots_target_ctx = _ctx_c
                                    break
                                if _mtp_slots:
                                    break
                            if _mtp_slots:
                                logger.info(
                                    "Auto: serving slots reduced %d -> %d so the drafter fits "
                                    "in VRAM at context %d (target alone: %d). Set Parallel "
                                    "Slots to keep %d without the drafter.",
                                    n_parallel,
                                    _mtp_slots,
                                    _mtp_slots_ctx,
                                    _probe_ctx,
                                    n_parallel,
                                )
                                _mtp_slots_asked = n_parallel
                                n_parallel = _mtp_slots  # allow-slot-clamp: the drafter fits in VRAM only at fewer slots
                                _effective_ubatch = _ubatch_for_slots(n_parallel)
                                _compute_buffer_pipeline = _layer_compute_buffer(n_parallel)
                                if mtp_overhead_fn is not None:
                                    # Its defaults were bound at the requested count.
                                    mtp_overhead_fn = functools.partial(
                                        mtp_overhead_fn,
                                        _np = n_parallel,
                                        _n_ubatch = _effective_ubatch,
                                    )
                                _both_fit_somewhere = True
                        if _target_fits_somewhere and not _both_fit_somewhere:
                            _spec_dropped_no_vram = True
                            _mtp_will_engage = False
                            # Clearing the flag alone leaves the reserve (the fit calls any non-None mtp_overhead_fn): clear that and _mtp_kv_unsized too, or the flat fraction returns.
                            mtp_overhead_fn = None
                            _mtp_kv_unsized = False
                            logger.warning(
                                "Speculative decoding disabled for this load: the model "
                                "fits in VRAM at context %d but its drafter does not "
                                "(needs %.1f GB of a %.1f GB budget, on any GPU subset). "
                                "Auto keeps the context rather than shrink it for a speed "
                                "option. Select the drafter in Settings to force it.",
                                _probe_ctx,
                                _probe_need / 1024,
                                _probe_have / 1024,
                            )

                    # Flat fallback only when the draft KV is unsized; an embedded head keeps its reserve.
                    _flat_mtp_engages = _mtp_will_engage and (
                        mtp_overhead_fn is None or _mtp_kv_unsized
                    )
                    # MTP reserves GPU VRAM unless its only drafter is a separate
                    # CPU-offloaded one (an embedded head stays on GPU). The tensor
                    # path reserves like the layer path; gate both on this.
                    _mtp_reserves_gpu = _mtp_will_engage and not _draft_cpu_no_embedded
                    # Whether any byte reserve survives on GPU (a CPU drafter keeps target rollback state). Kept apart from _mtp_reserves_gpu, which also charges the draft graph.
                    _mtp_gpu_bytes_remain = _mtp_reserves_gpu or mtp_overhead_fn is not None
                    _flat_mtp_reserve = (
                        _MTP_VRAM_RESERVE_FRAC
                        if (_flat_mtp_engages and not _draft_cpu_no_embedded)
                        else 0.0
                    )
                    _pin_fraction = _vram_frac - _flat_mtp_reserve

                    # CUDA/cuBLAS context is discrete-GPU only (not Metal); mmproj and MTP draft-graph buffers exist on every backend, so charge them everywhere.
                    _soft_overhead = self._CUDA_CONTEXT_RESERVE_BYTES if gpus else 0
                    if effective_is_vision and mmproj_size > 0:
                        _soft_overhead += int(mmproj_size * (self._MMPROJ_VRAM_SAFETY - 1.0))
                    if _mtp_reserves_gpu:
                        _soft_overhead += self._MTP_DRAFT_COMPUTE_BYTES
                    # On shared memory (APU/iGPU, unified, unknown total) a CPU-pinned projector still sits in
                    # the measured pool, so charge it when shared memory is present.
                    _shared_pool_mmproj = (
                        _mmproj_pinned_bytes
                        if (not gpus or len(_mm_budgeted_gpus) < len(gpus))
                        else 0
                    )
                    _host_input_embd = _host_input_bytes_now(model_size)
                    if _host_input_embd:
                        logger.info(
                            "GPU fit: %.2f GB of input embeddings and lookup tables stay "
                            "in host memory; not charged to VRAM.",
                            _host_input_embd / (1024**3),
                        )
                    model_size_fit = (
                        model_size
                        - _host_input_embd
                        + _compute_buffer_pipeline
                        + _soft_overhead
                        + _shared_pool_mmproj
                    )

                    def _subset_model_size(n_gpus: int) -> int:
                        return model_size_fit + max(0, n_gpus - 1) * _pipeline_overhead_bytes

                    def _discrete_host_only(subset = None) -> int:
                        # The shared-pool projector charge a discrete tier drops: only when
                        # every discrete total is known, and none for a subset holding an
                        # iGPU. Read by name so a later rebind of _shared_pool_mmproj carries.
                        if subset is not None and not _integrated_gpus.isdisjoint(
                            i for i, _f in subset
                        ):
                            return 0
                        if _integrated_gpus and all(
                            (total_by_idx or {}).get(i, 0) > 0
                            for i, _f in gpus
                            if i not in _integrated_gpus
                        ):
                            return _shared_pool_mmproj
                        return 0

                    # Unified-memory budget (0 off Apple Silicon) for the no-GPU Metal cap below.
                    _apple_budget_mib = self._apple_metal_memory_budget_bytes() // (1024 * 1024)
                    _metal_media_mib, _metal_media_unallocated_mib = (
                        self._metal_media_mib() if _apple_budget_mib > 0 else (0, 0)
                    )
                    if _metal_media_mib:
                        # 0 would mean "not Apple Silicon" and skip every Metal check.
                        _apple_budget_mib = max(
                            1,
                            min(
                                _apple_budget_mib,
                                _apple_budget_beside_media_mib(
                                    _metal_media_mib, _metal_media_unallocated_mib
                                ),
                            ),
                        )
                    _metal_media_wired_mib = int(
                        _metal_media_unallocated_mib * _APPLE_WIRED_CEILING_FRACTION
                    )

                    def _apple_wired_left_mib(wired_bytes: int) -> int:
                        return max(0, wired_bytes // (1024 * 1024) - _metal_media_wired_mib)

                    if tensor_parallel and tp_gpus:
                        # The planner can shrink ctx/KV, not weights or the MTP reserve.
                        _tp_weight_budget_mib = (
                            sum(_gpu_usable(g) for g in tp_gpus) - len(tp_gpus) * reserve_mib
                        )
                        _tp_flat_mtp = 2 * 1024**3  # flat reserve when dims unavailable
                        if not _mtp_gpu_bytes_remain:
                            # No MTP, or its only drafter is CPU-offloaded and the
                            # target keeps no state of its own (no GPU bytes at all).
                            _tp_mtp_floor = 0
                        elif mtp_overhead_fn is not None and not _mtp_kv_unsized:
                            _tp_mtp_floor = _mtp_bytes(
                                min(2048, effective_ctx) if effective_ctx > 0 else 2048
                            )
                        else:
                            # Tensor mode has no --fit valve: keep the flat cushion for unsized KV, never below the known byte reserve.
                            _tp_mtp_floor = max(
                                _tp_flat_mtp,
                                _mtp_bytes(min(2048, effective_ctx) if effective_ctx > 0 else 2048),
                            )
                        _tp_required_mib = (
                            model_size - _host_input_embd + _tp_mtp_floor + _soft_overhead
                        ) / (1024 * 1024)
                        if _tp_weight_budget_mib <= _tp_required_mib:
                            logger.info(
                                "Tensor parallelism requested but the pooled VRAM "
                                "budget cannot hold the weights, MTP reserve, and "
                                "per-device compute buffers; falling back to layer split."
                            )
                            tensor_parallel = False
                            # Weights needed >1 card, so keep multi-GPU across the
                            # usable tensor GPUs.
                            if len(tp_gpus) >= 2:
                                _layer_min_gpus = max(_layer_min_gpus, len(tp_gpus))
                            extra_args = strip_split_mode_only(extra_args)
                            planned_flash_attn = _replanned_flash_attn(tensor_parallel)
                            # Apply the deferred pin only without a GPU drafter: the drafter-drop
                            # probe did not run.
                            if _mm_pin_deferred and not _mtp_reserves_gpu:
                                _apply_mmproj_cpu_pin(_mm_floor_ctx)
                                _mm_pin_deferred = False
                                # _subset_model_size closes over model_size_fit by name, so
                                # rebinding carries through.
                                _soft_overhead = self._CUDA_CONTEXT_RESERVE_BYTES if gpus else 0
                                if _mtp_reserves_gpu:
                                    _soft_overhead += self._MTP_DRAFT_COMPUTE_BYTES
                                _shared_pool_mmproj = (
                                    _mmproj_pinned_bytes
                                    if (not gpus or len(_mm_budgeted_gpus) < len(gpus))
                                    else 0
                                )
                                model_size_fit = (
                                    model_size
                                    - _host_input_embd
                                    + _compute_buffer_pipeline
                                    + _soft_overhead
                                    + _shared_pool_mmproj
                                )

                    if tensor_parallel and tp_gpus:
                        # Tensor-parallel allocation; see _plan_tensor_parallel.
                        target_ctx = (
                            effective_ctx
                            if explicit_ctx
                            else (self._context_length or effective_ctx)
                        )
                        # Weights-only mtp_overhead_fn: pass the flat cushion for unsized KV, or the binary search spends that cushion on context.
                        _tp_unsized_mtp_reserve = (
                            2 * 1024**3 if (_mtp_reserves_gpu and _mtp_kv_unsized) else 0
                        )
                        (
                            effective_ctx,
                            max_available_ctx,
                            gpu_indices,
                            tp_tensor_split,
                        ) = self._plan_tensor_parallel(
                            tp_gpus,
                            max(1, model_size - _host_input_embd),
                            target_ctx,
                            cache_type_kv = cache_type_kv,
                            scratch_cache_type_kv = _scratch_cache_type_kv,
                            n_parallel = n_parallel,
                            mtp_engaged = _mtp_reserves_gpu,
                            mtp_overhead_fn = mtp_overhead_fn,
                            mtp_flat_reserve_bytes = _tp_unsized_mtp_reserve,
                            # Report the UI ceiling from native ctx, not the
                            # explicit small request.
                            max_target_ctx = self._context_length or target_ctx,
                            total_by_idx = total_by_idx,
                            n_ubatch = _effective_ubatch,
                            soft_overhead_bytes = _soft_overhead,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            flash_attn = planned_flash_attn,
                            # Already resolved: a mid-load save must not change the fraction here.
                            vram_fraction = _vram_frac,
                            explicit_ctx = explicit_ctx,
                        )
                        use_fit = False
                        _tp_planned = True
                        if explicit_ctx and not self._can_estimate_kv():
                            # Tensor mode emits --fit off, so nothing downstream catches it.
                            _unmeasured_ctx_notice = self._unmeasured_context_notice(
                                effective_ctx, cache_type_kv
                            )
                    elif gpus and self._can_estimate_kv() and effective_ctx > 0:
                        # Hardware cap for UI bounds, independent of the requested context.
                        native_ctx_for_cap = self._context_length or effective_ctx
                        if native_ctx_for_cap > 0:
                            ranked_for_cap = sorted(
                                gpus,
                                key = lambda g: _gpu_rank(
                                    g,
                                    _vram_frac - _flat_mtp_reserve,
                                    _pipeline_overhead_bytes / (1024 * 1024),
                                ),
                                reverse = True,
                            )
                            best_cap = 0
                            _cap_fraction = _vram_frac - _flat_mtp_reserve
                            # Every subset Auto may take, discrete tier included, priced as Auto prices it.
                            # With an integrated GPU, start at Auto's GPU floor: a forced split never takes
                            # a checkpoint-free dGPU-only subset, explicit device pick or not.
                            _cap_floor = 1
                            if _integrated_gpus:
                                _cap_floor = max(
                                    1,
                                    min(
                                        _layer_min_gpus,
                                        sum(
                                            1
                                            for g in ranked_for_cap
                                            if _gpu_usable(g, _cap_fraction)
                                            > _pipeline_overhead_bytes / (1024 * 1024)
                                        )
                                        or 1,
                                    ),
                                )

                            def _cap_fit(n_gpus: int, subset) -> Optional[int]:
                                # The context Auto would cap ``subset`` to for the UI ceiling, or None.
                                # Per-GPU-consistent pool budget (fixes mixed
                                # known/unknown totals); pass it as an absolute
                                # budget so the fit and the check below agree.
                                pool_budget = _pool_budget_mib(subset, _cap_fraction)
                                _ms = _subset_model_size(n_gpus) - _discrete_host_only(subset)
                                # Compute buffer is replicated per device in a layer
                                # split, so scale the context term by the subset size.
                                _cc_sub = lambda c, n = n_gpus: _cc_bytes(c, n)
                                capped = self._fit_context_to_vram(
                                    native_ctx_for_cap,
                                    pool_budget,
                                    _ms,
                                    cache_type_kv,
                                    swa_full = swa_full,
                                    n_parallel = n_parallel,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = _effective_ubatch,
                                    flash_attn = planned_flash_attn,
                                    mtp_engaged = _mtp_reserves_gpu,
                                    mtp_overhead_fn = mtp_overhead_fn,
                                    compute_ctx_bytes_fn = _cc_sub,
                                    budget_frac = 1.0,
                                    pooled = True,
                                    total_mib = None,
                                    ctx_checkpoints = _subset_ckpts(subset),
                                )
                                kv = _kv_bytes(capped)
                                footprint_mib = (
                                    _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                ) / (1024 * 1024)
                                if footprint_mib > pool_budget:
                                    return None
                                if (
                                    n_gpus > 1
                                    and _integrated_gpus
                                    and _integrated_gpus.isdisjoint(i for i, _f in subset)
                                ):
                                    # A dGPU-only tier is not a usable-descending prefix, so pooling can
                                    # hide a small card's replicated reserve: cap as Auto's walk does.
                                    _usable_mib = [_gpu_usable(g, _cap_fraction) for g in subset]
                                    _reserve_at = lambda c, n = n_gpus: (
                                        _pipeline_overhead_bytes + _cc_bytes(c, n) // n
                                    )
                                    if not self._every_gpu_holds_reserve(
                                        _usable_mib, _reserve_at(capped)
                                    ):
                                        capped = self._cap_ctx_to_per_device_reserve(
                                            capped, _usable_mib, _reserve_at
                                        )
                                return capped

                            def _cap_score(n_gpus: int, subset):
                                capped = _cap_fit(n_gpus, subset)
                                return None if capped is None else (capped,)

                            for n_gpus, subset in _tiered_subsets(
                                ranked_for_cap, _cap_floor, score_of = _cap_score
                            ):
                                capped = _cap_fit(n_gpus, subset)
                                if capped is not None:
                                    best_cap = max(best_cap, capped)
                            if best_cap > 0:
                                max_available_ctx = best_cap
                                _ctx_cap_fits = True
                                # A forced GPU floor plans subsets this sweep did not hold to it.
                                _vram_fit_ctx = best_cap if _layer_min_gpus <= 1 else None
                            else:
                                # No context fits: anchor the UI safe zone at the Auto offload fallback so Auto
                                # never exceeds its own published ceiling.
                                max_available_ctx = min(_AUTO_OFFLOAD_CTX, native_ctx_for_cap)

                        if explicit_ctx:
                            # Honor the requested context; if it does not fit, ship --fit on and let -ngl flex.
                            requested_total = (
                                model_size_fit
                                + _kv_bytes(effective_ctx)
                                + _mtp_bytes(effective_ctx)
                                + _cc_bytes(effective_ctx)
                            )
                            # Compute buffer is replicated on every device in a layer split: priced single-device, then re-checked at the split rate, falling back to --fit on.
                            gpu_indices, use_fit = self._select_gpus_split_aware(
                                requested_total,
                                gpus,
                                usable_fraction = _pin_fraction,
                                total_by_idx = total_by_idx,
                                per_device_overhead_bytes = _pipeline_overhead_bytes
                                + _cc_bytes(effective_ctx),
                                min_gpus = _layer_min_gpus,
                                split_extra_bytes = _cc_split_extra(effective_ctx),
                                shared = _shared_gpus,
                                integrated = _integrated_gpus,
                                prefer_discrete = bool(_tier_gpus),
                                discount_prefixes = _discount_prefixes,
                                discrete_size_bytes = requested_total - _discrete_host_only(),
                                shared_gpu_ids = _shared_gpu_ids,
                            )
                            # No silent shrink: effective_ctx stays requested_ctx; use_fit means --fit on will offload. -nkvo keeps the cache on the host, so overflow is not real.
                            if (
                                use_fit
                                and _ctx_cap_fits
                                and not _cuda_ctx_notice
                                and _kv_offload_from_args(extra_args)
                                and not _args_place_tensors_on_cpu(extra_args)
                                and not _env_places_tensors_on_cpu()
                                and not _device_selection_is_cpu(extra_args, os.environ)
                                and not _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
                                and not _env_fixes_gpu_layers()
                                # A trailing user --fit off disables the fitter that would offload.
                                and (
                                    fit_is_enabled_in(extra_args)
                                    or not _extra_args_set_any_flag(extra_args, {"-fit", "--fit"})
                                )
                                # At the native ceiling the true max above it was never searched.
                                and max_available_ctx < native_ctx_for_cap
                            ):
                                _q8_fits = False
                                if planned_flash_attn and (
                                    cache_type_kv or "f16"
                                ).strip().lower() in (
                                    "f16",
                                    "fp16",
                                    "",
                                ):
                                    _q8_kv = self._estimate_kv_cache_bytes(
                                        effective_ctx,
                                        "q8_0",
                                        n_parallel = n_parallel,
                                        swa_full = swa_full,
                                        kv_unified = planned_kv_unified,
                                        n_ubatch = _effective_ubatch,
                                        flash_attn = planned_flash_attn,
                                    )
                                    if _q8_kv > 0:
                                        _, _q8_use_fit = self._select_gpus_split_aware(
                                            model_size_fit
                                            + _q8_kv
                                            + _mtp_bytes(effective_ctx)
                                            + _cc_bytes(effective_ctx, cache_type = "q8_0"),
                                            gpus,
                                            usable_fraction = _pin_fraction,
                                            total_by_idx = total_by_idx,
                                            per_device_overhead_bytes = (
                                                _pipeline_overhead_bytes
                                                + _cc_bytes(effective_ctx, cache_type = "q8_0")
                                            ),
                                            min_gpus = _layer_min_gpus,
                                            split_extra_bytes = _cc_split_extra(
                                                effective_ctx, cache_type = "q8_0"
                                            ),
                                            shared = _shared_gpus,
                                            integrated = _integrated_gpus,
                                            prefer_discrete = bool(_tier_gpus),
                                            discount_prefixes = _discount_prefixes,
                                            discrete_size_bytes = model_size_fit
                                            + _q8_kv
                                            + _mtp_bytes(effective_ctx)
                                            + _cc_bytes(effective_ctx, cache_type = "q8_0")
                                            - _discrete_host_only(),
                                            shared_gpu_ids = _shared_gpu_ids,
                                        )
                                        _q8_fits = not _q8_use_fit
                                _cuda_ctx_notice = self._cuda_context_overcommit_notice(
                                    effective_ctx,
                                    max_available_ctx,
                                    cache_type_kv,
                                    quantised_ctx_fits = _q8_fits,
                                )
                        else:
                            # Rank by the active pin fraction so the order matches the fit budget.
                            pin_fraction = _pin_fraction
                            # Max _reserve_at ask: a short card must not hide an iGPU that fits.
                            _rank_floor_mib = (
                                _pipeline_overhead_bytes + _cc_bytes(effective_ctx, 2) // 2
                            ) / (1024 * 1024)
                            ranked = sorted(
                                gpus,
                                key = lambda g: _gpu_rank(g, pin_fraction, _rank_floor_mib),
                                reverse = True,
                            )
                            # Skips _select_gpus, so apply its per-device overhead cap.
                            _pipeline_overhead_mib = _pipeline_overhead_bytes / (1024 * 1024)
                            _auto_min_gpus = max(
                                1,
                                min(
                                    _layer_min_gpus,
                                    sum(
                                        1
                                        for g in ranked
                                        if _gpu_usable(g, pin_fraction) > _pipeline_overhead_mib
                                    )
                                    or 1,
                                ),
                            )
                            _ctx_before_fit = effective_ctx
                            if _shared_gpus and _auto_min_gpus == 1 and effective_ctx > 0:
                                # Sharing a card splits its compute between the models.
                                _alone_mib = (
                                    _subset_model_size(1)
                                    + _kv_bytes(effective_ctx)
                                    + _mtp_bytes(effective_ctx)
                                    + _cc_bytes(effective_ctx, 1)
                                ) / (1024 * 1024)
                                _unshared = next(
                                    (
                                        g
                                        for g in ranked
                                        if g[0] not in _shared_gpus
                                        and _gpu_usable(g, pin_fraction) >= _alone_mib
                                    ),
                                    None,
                                )
                                if _unshared is not None:
                                    ranked.remove(_unshared)
                                    ranked.insert(0, _unshared)

                            def _subset_ms(n_gpus: int, subset) -> int:
                                # A CPU-pinned projector is charged for a shared pool; a
                                # discrete-tier subset draws on none.
                                return _subset_model_size(n_gpus) - _discrete_host_only(subset)

                            def _auto_fit(n_gpus: int, subset, ctx: int) -> Optional[int]:
                                # The context ``subset`` holds when Auto caps ``ctx`` to it, or None.
                                pool_budget = _pool_budget_mib(subset, pin_fraction)
                                _ms = _subset_ms(n_gpus, subset)
                                # Compute buffer is replicated per device in a layer
                                # split, so scale the context term by the subset size.
                                _cc_sub = lambda c, n = n_gpus: _cc_bytes(c, n)
                                capped = self._fit_context_to_vram(
                                    ctx,
                                    pool_budget,
                                    _ms,
                                    cache_type_kv,
                                    swa_full = swa_full,
                                    n_parallel = n_parallel,
                                    kv_unified = planned_kv_unified,
                                    n_ubatch = _effective_ubatch,
                                    flash_attn = planned_flash_attn,
                                    mtp_engaged = _mtp_reserves_gpu,
                                    mtp_overhead_fn = mtp_overhead_fn,
                                    compute_ctx_bytes_fn = _cc_sub,
                                    budget_frac = 1.0,
                                    pooled = True,
                                    total_mib = None,
                                    ctx_checkpoints = _subset_ckpts(subset),
                                )
                                kv = _kv_bytes(capped)
                                footprint_mib = (
                                    _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                ) / (1024 * 1024)
                                if footprint_mib > pool_budget:
                                    return None
                                # Pooling admits a subset whose per-device reserve
                                # does not fit the smallest card, which then OOMs at
                                # launch; only knowable once `capped` is chosen.
                                _usable_mib = [_gpu_usable(g, pin_fraction) for g in subset]
                                _reserve_at = lambda c, n = n_gpus: (
                                    (_pipeline_overhead_bytes if n > 1 else 0)
                                    + _cc_bytes(c, n) // n
                                )
                                if not self._every_gpu_holds_reserve(
                                    _usable_mib, _reserve_at(capped)
                                ):
                                    # Keep the largest context the smallest card holds
                                    # rather than lose the subset to the 4096 drop below.
                                    # Costs no context: a longer prefix never has a larger
                                    # smallest card, and the reserve is one function for n > 1.
                                    capped = self._cap_ctx_to_per_device_reserve(
                                        capped, _usable_mib, _reserve_at
                                    )
                                    if capped <= 0:
                                        return None
                                    # Pooled terms only shrink with the context, so this
                                    # cannot newly fail; re-price rather than lean on that
                                    # across the KV and MTP branches.
                                    kv = _kv_bytes(capped)
                                    footprint_mib = (
                                        _ms + kv + _mtp_bytes(capped) + _cc_sub(capped)
                                    ) / (1024 * 1024)
                                    if footprint_mib > pool_budget:
                                        return None
                                return capped

                            def _auto_score(
                                n_gpus: int,
                                subset,
                                ctx = effective_ctx,
                            ):
                                capped = _auto_fit(n_gpus, subset, ctx)
                                return None if capped is None else (capped,)

                            _subsets = _tiered_subsets(ranked, _auto_min_gpus, score_of = _auto_score)
                            for n_gpus, subset in _subsets:
                                capped = _auto_fit(n_gpus, subset, effective_ctx)
                                if capped is None:
                                    continue
                                effective_ctx = capped
                                _ctx_capped_for_vram = 0 < capped < _ctx_before_fit
                                if (
                                    _ctx_capped_for_vram
                                    and _tier_gpus
                                    and _tier_gpus.isdisjoint(i for i, _f in subset)
                                ):
                                    # Capped only by the discrete preference: the base walk
                                    # holds the full context, so nothing evicted would help.
                                    _base_ctx = next(
                                        (
                                            c
                                            for n in range(_auto_min_gpus, len(ranked) + 1)
                                            for c in (_auto_fit(n, ranked[:n], _ctx_before_fit),)
                                            if c is not None
                                        ),
                                        None,
                                    )
                                    _ctx_capped_for_vram = not (
                                        _base_ctx is not None and _base_ctx >= _ctx_before_fit
                                    )
                                gpu_indices = sorted(idx for idx, _ in subset)
                                use_fit = False
                                break
                            else:
                                # No GPU subset (discrete or full pool) holds the model at a
                                # fitted context. Prefer a useful chat context before
                                # handing placement to --fit on and host offload.
                                effective_ctx = min(_AUTO_OFFLOAD_CTX, effective_ctx)
                                if effective_ctx > 0:
                                    for n_gpus, subset in _subsets:
                                        kv = _kv_bytes(effective_ctx)
                                        footprint_mib = (
                                            _subset_ms(n_gpus, subset)
                                            + kv
                                            + _mtp_bytes(effective_ctx)
                                            + _cc_bytes(effective_ctx, n_gpus)
                                        ) / (1024 * 1024)
                                        if footprint_mib > _pool_budget_mib(subset, pin_fraction):
                                            continue
                                        # Pooling hides the per-device reserve here too.
                                        if not self._every_gpu_holds_reserve(
                                            (_gpu_usable(g, pin_fraction) for g in subset),
                                            (_pipeline_overhead_bytes if n_gpus > 1 else 0)
                                            + _cc_bytes(effective_ctx, n_gpus) // n_gpus,
                                        ):
                                            continue
                                        gpu_indices = sorted(idx for idx, _ in subset)
                                        use_fit = False
                                        break

                    elif gpus:
                        # Without KV metadata llama.cpp owns the fit; keep the Auto default of the measured offload path.
                        logger.debug(
                            "Falling back to file-size-only GPU selection",
                            model_size_gb = round(model_size / (1024**3), 2),
                        )
                        # Byte-accurate MTP reserve and the flat fallback are mutually exclusive by design.
                        _fs_total = model_size_fit + _mtp_bytes(
                            self._context_length or effective_ctx or 4096
                        )
                        gpu_indices, use_fit = self._select_gpus(
                            _fs_total,
                            gpus,
                            usable_fraction = _pin_fraction,
                            total_by_idx = total_by_idx,
                            per_device_overhead_bytes = _pipeline_overhead_bytes,
                            min_gpus = _layer_min_gpus,
                            shared = _shared_gpus,
                            integrated = _integrated_gpus,
                            prefer_discrete = bool(_tier_gpus),
                            discount_prefixes = _discount_prefixes,
                            discrete_size_bytes = _fs_total - _discrete_host_only(),
                            shared_gpu_ids = _shared_gpu_ids,
                        )
                        if use_fit and not explicit_ctx:
                            # Without KV metadata, llama.cpp owns the fit. Keep the
                            # same useful Auto default as the measured offload path.
                            effective_ctx = (
                                min(_AUTO_OFFLOAD_CTX, effective_ctx)
                                if effective_ctx > 0
                                else _AUTO_OFFLOAD_CTX
                            )

                    elif _apple_budget_mib > 0 and effective_ctx > 0:
                        # No GPU on Metal: cap here, or the context stays native and over-commits
                        # unified memory.
                        # llama.cpp's --fit is blind to Unsloth's own footprint and the wired limit.
                        native_ctx_for_cap = self._context_length or effective_ctx
                        # With --fit off (argv or LLAMA_ARG_FIT env) nothing reduces what we emit, so hand over the floor the llama.cpp fitter itself would reduce to.
                        _metal_floor_ctx = (
                            _FIT_MIN_CTX
                            if fit_is_effectively_on(extra_args, os.environ)
                            else _LLAMA_FIT_MIN_CTX
                        )
                        # Only a ceiling backed by a real KV estimate may refuse; the 4096 fallback is a guess.
                        _apple_measured_ceiling: Optional[int] = None
                        # The other measured verdict: nothing fits, so there is no ceiling
                        # to name and every explicit request over-commits.
                        _apple_nothing_fits = False
                        # No measurement: the floor is a guess and may not refuse or be published.
                        _apple_ctx_unmeasured = False
                        # Reserve the flat MTP fraction up front so an unsized draft cannot over-commit; exclusive with the byte-accurate _mtp_bytes reserve.
                        _apple_fit_budget_mib = int(
                            _apple_budget_mib * max(0.0, 1.0 - _flat_mtp_reserve)
                        )
                        # A CPU-pinned projector is already in model_size_fit here; do not charge it twice.
                        _apple_host_embd = self._metal_demand_paged_embedding_bytes(
                            model_path,
                            extra_args,
                            binary = binary,
                            requested_load_mode = load_mode,
                            supports_load_mode = load_mode_support(server_caps),
                            settings = _mem_settings,
                            layers_fixed = _caller_owns_budget or _paravirtual_cpu_forced,
                            mtp_may_engage = _mtp_will_engage,
                        )
                        _apple_probe_embd = _apple_host_embd
                        # Metal refuses past the wired limit; None is unknown, 0 used up.
                        _apple_wired = self._apple_metal_wired_headroom_bytes()
                        _apple_resident_budget_mib = (
                            _apple_fit_budget_mib
                            if _apple_wired is None
                            else min(
                                _apple_fit_budget_mib,
                                int(
                                    _apple_wired
                                    // (1024 * 1024)
                                    * max(0.0, 1.0 - _flat_mtp_reserve)
                                ),
                            )
                        )
                        _apple_extras = (
                            self._strip_device_extra_args(extra_args)
                            if _gpu_ids_own_device_flags
                            else extra_args
                        )
                        _apple_env = dict(os.environ)
                        if gpu_memory_mode == "manual":
                            self._clear_manual_placement_env(_apple_env)
                        if _gpu_ids_own_device_flags:
                            self._clear_device_placement_env(_apple_env)
                        self._reconcile_split_mode_env(_apple_env, tensor_parallel = tensor_parallel)
                        _apple_host_embd = self._apple_lookup_table_discount(
                            _apple_host_embd,
                            model_path,
                            caps = server_caps,
                            extra_args = _apple_extras,
                            env = _apple_env,
                            model_size_fit = model_size_fit,
                            need_at_ctx = (
                                (
                                    _kv_bytes(effective_ctx, _fit_ctx_checkpoints)
                                    + _cc_bytes(effective_ctx)
                                    + _mtp_bytes(effective_ctx)
                                    + _apple_cpu_draft
                                )
                                if effective_ctx > 0
                                and not _pass_through_reprices_cache(extra_args, n_parallel)
                                and not _flat_mtp_engages
                                and (
                                    _apple_cpu_draft := self._cpu_resident_draft_bytes(
                                        effective_ctx,
                                        drafter_path = _cpu_draft_path,
                                        draft_cache_type_k = _mtp_draft_ck,
                                        draft_cache_type_v = _mtp_draft_cv,
                                        n_parallel = n_parallel,
                                        swa_full = swa_full,
                                        kv_unified = planned_kv_unified,
                                        n_ubatch = _effective_ubatch,
                                        flash_attn = planned_flash_attn,
                                    )
                                )
                                is not None
                                else None
                            ),
                            budget_mib = _apple_resident_budget_mib,
                            cache_ram = cache_ram,
                            binary = binary,
                            cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                        )
                        _managed_lazy_flags = list(self._apple_lazy_flags)
                        _apple_model_size_fit = model_size_fit - _apple_host_embd
                        if _apple_host_embd:
                            logger.info(
                                "Metal fit: %.2f GB of input embeddings stay in the CPU "
                                "file mapping; charging %.2f GB of weights to unified memory.",
                                _apple_host_embd / (1024**3),
                                _apple_model_size_fit / (1024**3),
                            )

                        def _apple_ctx_fit(
                            target: int,
                            min_ctx: int,
                            budget_mib: Optional[int] = None,
                        ) -> int:
                            return self._fit_context_to_vram(
                                target,
                                _apple_fit_budget_mib if budget_mib is None else budget_mib,
                                _apple_model_size_fit,
                                cache_type_kv,
                                min_ctx = min_ctx,
                                swa_full = swa_full,
                                n_parallel = n_parallel,
                                kv_unified = planned_kv_unified,
                                n_ubatch = _effective_ubatch,
                                flash_attn = planned_flash_attn,
                                mtp_engaged = _mtp_reserves_gpu,
                                mtp_overhead_fn = mtp_overhead_fn,
                                compute_ctx_bytes_fn = _cc_bytes,
                                budget_frac = 1.0,
                                pooled = True,
                                total_mib = None,
                                ctx_checkpoints = _fit_ctx_checkpoints,
                            )

                        def _apple_footprint_mib(ctx: int, ctx_checkpoints: int = 0) -> float:
                            return (
                                _apple_model_size_fit
                                + _kv_bytes(ctx, ctx_checkpoints)
                                + _mtp_bytes(ctx)
                                + _cc_bytes(ctx)
                            ) / (1024 * 1024)

                        # Auto only: drop the drafter when the target fits Metal alone but not with
                        # the sidecar reserve.
                        if (
                            use_fit
                            and _mtp_will_engage
                            and _mtp_reserves_gpu
                            and _mtp_effective in ("dspark", "dflash")
                            and (_canonicalize_spec_mode(speculative_type) or "auto") == "auto"
                            and not _extra_args_set_spec_type(extra_args)
                            # A bare --model-draft in extras still loads (has_dft()).
                            and not _extra_args_mtp_draft_path(extra_args, env = _spec_env)
                            and not _draft_share_unknown
                            and _draft_on_target_device_now()
                            # Zero KV would read as a target that fits alone.
                            and self._can_estimate_kv()
                        ):
                            # _apple_fit_budget_mib already holds back a flat fraction for this
                            # drafter.
                            _sc_ctx = (
                                effective_ctx
                                if explicit_ctx
                                else min(_metal_floor_ctx, native_ctx_for_cap or _metal_floor_ctx)
                            )
                            _sc_target_mib = (
                                _apple_model_size_fit
                                + _kv_bytes(_sc_ctx, _fit_ctx_checkpoints)
                                + _cc_bytes(_sc_ctx)
                            ) / (1024 * 1024)
                            _sc_draft_ub = _capped_draft_n_ubatch(
                                extra_args,
                                os.environ,
                                _sc_ctx,
                                _emitted_n_batch(n_batch, n_parallel),
                                n_ubatch,
                            )
                            _sc_with_draft_mib = _sc_target_mib + self._sidecar_fit_reserve_mib(
                                _mtp_bytes(
                                    _sc_ctx,
                                    slots = _extra_args_n_parallel(extra_args, os.environ),
                                    ubatch = _sc_draft_ub,
                                ),
                                mtp_draft_path,
                                flat_mib = math.ceil(_flat_mtp_reserve * max(0, _apple_budget_mib)),
                            )
                            # An explicit context is refused past the wired limit when that is
                            # readable.
                            _sc_wired_mib = (
                                self._apple_metal_wired_ceiling_bytes() // (1024 * 1024)
                                if explicit_ctx
                                and not _caller_owns_budget
                                and not _paravirtual_cpu_forced
                                else 0
                            )
                            _sc_over_limit = _apple_budget_mib < _sc_with_draft_mib or (
                                0 < _sc_wired_mib < _sc_with_draft_mib
                            )
                            # Only when both do not fit: the draft-free embedding discount can cost
                            # a cold llama-fit-params run.
                            _sc_host_embd_without_draft = _apple_host_embd
                            _sc_target_only_mib = _sc_target_mib
                            if _sc_over_limit:
                                _sc_host_embd_without_draft = (
                                    self._metal_demand_paged_embedding_bytes(
                                        model_path,
                                        extra_args,
                                        binary = binary,
                                        requested_load_mode = load_mode,
                                        supports_load_mode = load_mode_support(server_caps),
                                        settings = _mem_settings,
                                        layers_fixed = _caller_owns_budget or _paravirtual_cpu_forced,
                                        mtp_may_engage = False,
                                    )
                                )
                                _sc_target_only_mib = _sc_target_mib - (
                                    self._MTP_DRAFT_COMPUTE_BYTES
                                    + _sc_host_embd_without_draft
                                    - _apple_host_embd
                                ) / (1024 * 1024)
                            if _sc_target_only_mib <= _apple_budget_mib < _sc_with_draft_mib or (
                                _sc_wired_mib > 0
                                and _sc_target_only_mib <= _sc_wired_mib < _sc_with_draft_mib
                            ):
                                logger.info(
                                    "Auto: the %s sidecar does not fit in unified memory "
                                    "alongside the model, so it is dropped.",
                                    "DSpark" if _mtp_effective == "dspark" else "DFlash",
                                )
                                _spec_dropped_no_vram = True
                                _mtp_will_engage = False
                                _mtp_reserves_gpu = False
                                mtp_overhead_fn = None
                                _mtp_kv_unsized = False
                                # Derived after the discrete drop: undo them, or Auto keeps a
                                # smaller context than Off.
                                _mtp_gpu_bytes_remain = False
                                _flat_mtp_engages = False
                                _flat_mtp_reserve = 0.0
                                _pin_fraction = _vram_frac
                                _apple_fit_budget_mib = _apple_budget_mib
                                _soft_overhead -= self._MTP_DRAFT_COMPUTE_BYTES
                                model_size_fit -= self._MTP_DRAFT_COMPUTE_BYTES
                                _apple_embd_logged = bool(_apple_host_embd)
                                _apple_host_embd = _sc_host_embd_without_draft
                                _apple_model_size_fit = model_size_fit - _apple_host_embd
                                if _apple_host_embd and not _apple_embd_logged:
                                    logger.info(
                                        "Metal fit: %.2f GB of input embeddings stay in the CPU "
                                        "file mapping; charging %.2f GB of weights to unified "
                                        "memory.",
                                        _apple_host_embd / (1024**3),
                                        _apple_model_size_fit / (1024**3),
                                    )

                        if self._can_estimate_kv():
                            cap = _apple_ctx_fit(native_ctx_for_cap, _FIT_MIN_CTX)
                            _cap_footprint_mib = _apple_footprint_mib(cap)
                            # Fit returns the request unchanged when it fits or weights exceed budget; only the latter over-commits, so floor to _FIT_MIN_CTX.
                            if _cap_footprint_mib <= _apple_fit_budget_mib:
                                max_available_ctx = cap
                                _apple_measured_ceiling = cap
                            else:
                                # Weights fit but _FIT_MIN_CTX may not: re-price under the floor
                                # before concluding nothing
                                # was measured (llama.cpp's own --fit stops at 4096 and cannot rescue it).
                                _floor_cap = _apple_ctx_fit(native_ctx_for_cap, _FIT_FLOOR_MIN_CTX)
                                # Ask the budget directly: both fits tie when native <= floor, and a tie reads as priced nothing and refuses nothing (native 256 hits it)
                                _weights_over_budget = (
                                    _apple_model_size_fit / (1024 * 1024)
                                ) > _apple_fit_budget_mib
                                if _weights_over_budget:
                                    # Weights alone miss the budget: floor for the UI but do not
                                    # refuse on an unvouched number.
                                    max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                                elif _apple_footprint_mib(_floor_cap) <= _apple_fit_budget_mib:
                                    max_available_ctx = _floor_cap
                                    _apple_measured_ceiling = _floor_cap
                                else:
                                    # Nothing fits even at the smallest context: every explicit
                                    # request over-commits.
                                    max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                                    _apple_nothing_fits = True
                        else:
                            # No KV estimate: floor to _FIT_MIN_CTX rather than launch at native, which would over-commit memory
                            max_available_ctx = min(_metal_floor_ctx, native_ctx_for_cap)
                            _apple_ctx_unmeasured = True
                        if not explicit_ctx:
                            effective_ctx = max_available_ctx
                        elif _apple_ctx_unmeasured:
                            # Never publish a ceiling below the launched context.
                            max_available_ctx = max(max_available_ctx, effective_ctx)
                            _unmeasured_ctx_notice = self._unmeasured_context_notice(
                                effective_ctx, cache_type_kv
                            )
                        elif (
                            self._can_estimate_kv()
                            and not _caller_owns_budget
                            and not _paravirtual_cpu_forced
                        ):
                            # Exempt manual caller-owned loads and the paravirtual CPU pin (no Metal memory, RAM priced elsewhere). Re-price past native; adopt only if budget vouches
                            if _apple_measured_ceiling is not None and (
                                effective_ctx > native_ctx_for_cap
                            ):
                                _extended_ceiling = _apple_ctx_fit(effective_ctx, _FIT_MIN_CTX)
                                if _apple_footprint_mib(_extended_ceiling) > _apple_fit_budget_mib:
                                    # _FIT_MIN_CTX is a floor, not a measurement: when native is below it, a refusal wrongly names the native-sized cap as the largest that fits
                                    _extended_ceiling = _apple_ctx_fit(
                                        effective_ctx, _FIT_FLOOR_MIN_CTX
                                    )
                                if (
                                    _extended_ceiling > _apple_measured_ceiling
                                    and _apple_footprint_mib(_extended_ceiling)
                                    <= _apple_fit_budget_mib
                                ):
                                    _apple_measured_ceiling = _extended_ceiling
                                    # Publish it: the UI reads max_context_length as the largest context that fits; left at native, an allowed load would show a does-not-fit warning
                                    max_available_ctx = max(
                                        max_available_ctx, _apple_measured_ceiling
                                    )
                            # Past free memory macOS swaps; past the wired limit the machine panics.
                            _apple_wired_mib = int(
                                _apple_wired_left_mib(self._apple_metal_wired_ceiling_bytes())
                                * max(0.0, 1.0 - _flat_mtp_reserve)
                            )
                            if (
                                _apple_wired_mib <= 0
                                or _apple_model_size_fit / (1024 * 1024) > _apple_wired_mib
                            ):
                                _metal_ctx_refusal = self._metal_context_overcommit_message(
                                    effective_ctx,
                                    _apple_measured_ceiling or 0,
                                    cache_type_kv,
                                    nothing_fits = _apple_nothing_fits,
                                )
                            else:
                                # Priced like the fit (SWA checkpoints included) so admission matches the refusal ceiling.
                                _requested_mib = _apple_footprint_mib(
                                    effective_ctx, _fit_ctx_checkpoints
                                )
                                if _requested_mib > _apple_wired_mib:
                                    _wired_ctx = _apple_ctx_fit(
                                        effective_ctx, _FIT_FLOOR_MIN_CTX, _apple_wired_mib
                                    )
                                    _wired_fits = (
                                        _apple_footprint_mib(_wired_ctx, _fit_ctx_checkpoints)
                                        <= _apple_wired_mib
                                    )
                                    _metal_ctx_refusal = self._metal_context_overcommit_message(
                                        effective_ctx,
                                        _wired_ctx if _wired_fits else 0,
                                        cache_type_kv,
                                        nothing_fits = not _wired_fits,
                                        wired_limit = True,
                                    )
                                elif _requested_mib > _apple_fit_budget_mib:
                                    _metal_ctx_warning = self._metal_context_pressure_message(
                                        effective_ctx, _requested_mib, _apple_fit_budget_mib
                                    )
                        # The paravirtual pin loads on CPU, so no Metal budget held anything.
                        _vram_fit_ctx = None if _paravirtual_cpu_forced else _apple_measured_ceiling
                        # The measured ceiling was priced without SWA checkpoints; re-fit with them.
                        if _vram_fit_ctx and (
                            _apple_footprint_mib(_vram_fit_ctx, _fit_ctx_checkpoints)
                            > _apple_fit_budget_mib
                        ):
                            _ckpt_cap = _apple_ctx_fit(_vram_fit_ctx, _FIT_FLOOR_MIN_CTX)
                            _vram_fit_ctx = (
                                _ckpt_cap
                                if _apple_footprint_mib(_ckpt_cap, _fit_ctx_checkpoints)
                                <= _apple_fit_budget_mib
                                else None
                            )
                        # Past the wired limit Metal refuses, so it is the harder ceiling when readable.
                        _fit_wired_mib = (
                            int(
                                _apple_wired_left_mib(self._apple_metal_wired_ceiling_bytes())
                                * max(0.0, 1.0 - _flat_mtp_reserve)
                            )
                            if _vram_fit_ctx
                            else 0
                        )
                        if (
                            _fit_wired_mib > 0
                            and _apple_footprint_mib(_vram_fit_ctx, _fit_ctx_checkpoints)
                            > _fit_wired_mib
                        ):
                            _wired_cap = _apple_ctx_fit(
                                _vram_fit_ctx, _FIT_FLOOR_MIN_CTX, _fit_wired_mib
                            )
                            _vram_fit_ctx = (
                                _wired_cap
                                if _apple_footprint_mib(_wired_cap, _fit_ctx_checkpoints)
                                <= _fit_wired_mib
                                else None
                            )
                            # Auto launches a fixed -c, so llama.cpp's fitter could only move
                            # layers to CPU; give up context first, down to the Auto floor,
                            # so every layer stays on Metal.
                            if (
                                not explicit_ctx
                                and _vram_fit_ctx
                                and min(_FIT_MIN_CTX, effective_ctx)
                                <= _vram_fit_ctx
                                < effective_ctx
                            ):
                                effective_ctx = max_available_ctx = _vram_fit_ctx
                        # Unmeasured floors still rely on llama.cpp's fitter.
                        _metal_full_offload_pinned = bool(
                            _apple_measured_ceiling is not None
                            and (
                                _apple_probe_embd
                                or (
                                    _apple_host_embd
                                    and not _paravirtual_cpu_forced
                                    and self._metal_placement_unset(
                                        extra_args, os.environ, layers_fixed = _caller_owns_budget
                                    )
                                )
                            )
                        )
                        # Weights over the budget launch here too and the fitter places
                        # them, so it must see the same wired limit the refusals do.
                        if not _caller_owns_budget and not _paravirtual_cpu_forced:
                            _metal_fit_target_floor_mib = self._metal_fit_target_floor_mib()
                            if _metal_fit_target_floor_mib > 0:
                                _metal_fit_target_floor_mib += _metal_media_wired_mib

                        if (
                            intent.refuse_partial_gpu_fit
                            and gpu_memory_mode != "manual"
                            and not _paravirtual_cpu_forced
                            # A CPU-only child takes no Metal memory; the host-RAM guard prices it.
                            and not _device_selection_is_cpu(extra_args, os.environ)
                        ):
                            # No discrete GPU row on Metal, so the partial-placement verdict
                            # cannot refuse this; CPU offload adds no unified memory.
                            budget_mib = _apple_fit_budget_mib
                            # Unknown headroom skips the wired cap, a known 0 is exhausted. The
                            # reserve matches the wired refusals: the footprint omits an unsized MTP draft.
                            wired_bytes = self._apple_metal_wired_headroom_bytes()
                            if wired_bytes is not None:
                                wired_mib = int(
                                    _apple_wired_left_mib(wired_bytes)
                                    * max(0.0, 1.0 - _flat_mtp_reserve)
                                )
                                budget_mib = min(budget_mib, wired_mib)
                            need_mib = math.ceil(
                                _apple_footprint_mib(effective_ctx, _fit_ctx_checkpoints)
                            )
                            if need_mib > budget_mib:
                                _metal_alongside_shortfall = (need_mib, budget_mib)

                    # Prefer fewer serving slots on GPU over --fit on offload: when the extra
                    # --parallel slots push the footprint past the pin budget, llama-server
                    # offloads layers to host and decode collapses ~3x (#6718). Retry the fit
                    # at fewer slots, keeping the largest count that stays fully on GPU and the
                    # chosen context. Skips tensor mode / Metal / KV-inestimable paths.
                    if (
                        use_fit
                        and n_parallel > 1
                        and gpus
                        and self._can_estimate_kv()
                        and effective_ctx > 0
                    ):
                        # Probe at _FIT_MIN_CTX, not _AUTO_OFFLOAD_CTX (a higher probe fails the slot reduction); must match _largest_ctx floor. Explicit contexts priced as given
                        _reduce_ctx = (
                            effective_ctx if explicit_ctx else min(effective_ctx, _FIT_MIN_CTX)
                        )
                        # Slot-independent footprint (folded compute buffer and the MTP
                        # reserve swapped out so the helper re-prices both per candidate).
                        _base_footprint = (
                            model_size_fit - _compute_buffer_pipeline + _cc_bytes(_reduce_ctx)
                        )
                        _gi_slots, _uf_slots, _slots = self._slots_that_fit_on_gpu(
                            n_parallel,
                            _reduce_ctx,
                            gpus,
                            total_by_idx,
                            _base_footprint,
                            cache_type_kv,
                            _pin_fraction,
                            _pipeline_overhead_bytes + _cc_bytes(_reduce_ctx),
                            _layer_min_gpus,
                            _effective_ubatch,
                            swa_full = swa_full,
                            kv_unified = planned_kv_unified,
                            flash_attn = planned_flash_attn,
                            split_extra_for_slots = lambda s: _cc_split_extra(_reduce_ctx, s),
                            ubatch_for_slots = _ubatch_for_slots,
                            mtp_bytes_for_slots = lambda s, ub: _mtp_bytes(_reduce_ctx, s, ub),
                            ctx_checkpoints = _placement_ctx_checkpoints,
                            # An explicit device pick skips the discrete tier; host-only accounting still applies.
                            integrated = _integrated_gpus,
                            prefer_discrete = bool(_tier_gpus),
                            discount_prefixes = _discount_prefixes,
                            discrete_host_only_bytes = _discrete_host_only(),
                            shared_gpu_ids = _shared_gpu_ids,
                        )
                        if not _uf_slots:
                            _slots_asked = n_parallel
                            gpu_indices, use_fit, n_parallel = _gi_slots, False, _slots
                            # Fewer slots lower the batch floor; re-derive the micro-batch, or the recorded _n_ubatch describes a graph never built
                            _effective_ubatch = _ubatch_for_slots(n_parallel)
                            # Re-fit at the final slot count; the KV and compute closures
                            # read the values just rebound above.

                            def _slots_hold(
                                ctx: int, devices: list[tuple[int, int]]
                            ) -> Optional[list[int]]:
                                """Return the GPU subset if the final slot count fits."""
                                _gi, _uf, _got = self._slots_that_fit_on_gpu(
                                    n_parallel,
                                    ctx,
                                    devices,
                                    total_by_idx,
                                    model_size_fit - _compute_buffer_pipeline + _cc_bytes(ctx),
                                    cache_type_kv,
                                    _pin_fraction,
                                    _pipeline_overhead_bytes + _cc_bytes(ctx),
                                    _layer_min_gpus,
                                    _effective_ubatch,
                                    swa_full = swa_full,
                                    kv_unified = planned_kv_unified,
                                    flash_attn = planned_flash_attn,
                                    split_extra_bytes = _cc_split_extra(ctx),
                                    ubatch_for_slots = _ubatch_for_slots,
                                    mtp_bytes_for_slots = (lambda s, ub, c = ctx: _mtp_bytes(c, s, ub)),
                                    include_requested = True,
                                    exact = True,  # only n_parallel is accepted below
                                    ctx_checkpoints = _placement_ctx_checkpoints,
                                    integrated = _integrated_gpus,
                                    prefer_discrete = bool(_tier_gpus),
                                    discount_prefixes = _discount_prefixes,
                                    discrete_host_only_bytes = _discrete_host_only(),
                                    shared_gpu_ids = _shared_gpu_ids,
                                )
                                return _gi if not _uf and _got == n_parallel else None

                            def _largest_ctx(
                                devices: list[tuple[int, int]],
                            ) -> Optional[tuple[int, list[int]]]:
                                """Largest 256-aligned context the cards hold; footprint grows monotonically with context, and a missing native length (0 sentinel) would search nothing"""
                                _native = self._context_length or _reduce_ctx
                                _lo = max(1, min(_FIT_MIN_CTX, _native) // 256)
                                _hi = _native // 256
                                _best = None
                                while _lo <= _hi:
                                    _mid = (_lo + _hi) // 2
                                    _held = _slots_hold(_mid * 256, devices)
                                    if _held is None:
                                        _hi = _mid - 1
                                    else:
                                        _best = (_mid * 256, _held)
                                        _lo = _mid + 1
                                return _best

                            # Only the chosen cards; searching all GPUs would reintroduce the layer split.
                            _kept = set(_gi_slots or ())
                            _plan_gpus = [g for g in gpus if g[0] in _kept]
                            _refit = _largest_ctx(_plan_gpus)
                            # Explicit contexts are never rewritten; otherwise the re-fit is the answer, up or down, since any other context was never priced for the final slots
                            if _refit is not None and not explicit_ctx:
                                if _refit[0] != effective_ctx:
                                    logger.info(
                                        "Context re-fitted %d -> %d for %d serving slot(s).",
                                        effective_ctx,
                                        _refit[0],
                                        n_parallel,
                                    )
                                effective_ctx, gpu_indices = _refit
                            # After the re-fit, so it names the context that launches
                            # rather than one sized for slots this load dropped.
                            logger.info(
                                "Serving slots reduced %d -> %d to keep the model on GPU "
                                "(avoid --fit offload) at context %d.",
                                _slots_asked,
                                n_parallel,
                                effective_ctx,
                            )
                            # Largest context across every card at the final slot count, matching best_cap; not a hardware max, since a larger request can reduce slots further
                            _ceiling = (
                                _refit if len(_plan_gpus) == len(gpus) else _largest_ctx(gpus)
                            )
                            if _ceiling is not None:
                                # Replace, not max(): the old anchor belongs to a superseded plan.
                                max_available_ctx = _ceiling[0]
                                _vram_fit_ctx = _ceiling[0]

                    # Single-GPU VRAM shortfall vs free less --fit-target (None = unpriceable).
                    _model_size_fit_cb = _compute_buffer_pipeline

                    def _fit_ctx_overridden(
                        child_extras: Optional[Iterable[str]], child_env: Mapping[str, str]
                    ) -> bool:
                        """A --fit-ctx / -fitc (argv, else LLAMA_ARG_FIT_CTX) the child
                        runs with that is not the value _ctx_integrity_flags emits."""
                        _studio_fitc: Optional[int] = None
                        if (
                            use_fit
                            and not (gpu_memory_mode == "manual" and gpu_layers >= 0)
                            and server_caps.get("supports_fit_ctx")
                        ):
                            if requested_ctx > 0 and effective_ctx > 0:
                                _studio_fitc = int(effective_ctx)
                            elif gpu_memory_mode == "manual" and gpu_layers < 0:
                                _studio_fitc = 8192
                        try:
                            _raw = _last_flag_value(child_extras, _FIT_CTX_FLAGS)
                        except ValueError:
                            return True
                        # The emitted flag beats the env; argv after it beats both.
                        if _raw is None and _studio_fitc is None:
                            _raw = child_env.get("LLAMA_ARG_FIT_CTX")
                        if _raw is None or not str(_raw).strip():
                            return False
                        try:
                            return int(str(_raw).strip()) != _studio_fitc
                        except ValueError:
                            return True

                    def _fitter_vram_shortfall() -> Optional[float]:
                        if not (gpus and effective_ctx > 0 and self._can_estimate_kv()):
                            return None
                        # Smart offload may still pin experts to CPU against Unsloth's budget.
                        from core.inference.offload_planner import smart_offload_enabled

                        if smart_offload_enabled(os.environ):
                            return None
                        # A drafter priced with a flat cushion has no draft-KV term here.
                        if _flat_mtp_engages:
                            return None
                        _on = [g for g in gpus if gpu_indices is None or g[0] in gpu_indices]
                        # Per-device placement (common/fit.cpp) can spill despite a pooled fit.
                        if len(_on) != 1:
                            return None
                        _child_extras = (
                            self._strip_device_extra_args(extra_args)
                            if _gpu_ids_own_device_flags
                            else extra_args
                        )
                        _child_env = dict(os.environ)
                        if _gpu_ids_own_device_flags:
                            self._clear_device_placement_env(_child_env)
                        self._reconcile_split_mode_env(_child_env, tensor_parallel = tensor_parallel)
                        if _pass_through_overrides_placement(
                            _child_extras,
                            _child_env,
                            len(_on),
                            is_vulkan_backend = is_vulkan_backend,
                            gpu_indices = gpu_indices,
                        ):
                            return None
                        # Priced at Unsloth's --parallel; any other pass-through one wins.
                        _np_override = _extra_args_n_parallel(_child_extras, {})
                        if _np_override is not None and _np_override != n_parallel:
                            return None
                        # A later pass-through -c 0 lets llama.cpp pick the context.
                        if parse_ctx_override(_child_extras) == 0:
                            return None
                        # A --fit-ctx Studio did not emit moves llama.cpp's fit.
                        if _fit_ctx_overridden(_child_extras, _child_env):
                            return None
                        # A GPU projector Studio never sized; Vision off keeps only audio-only.
                        _env_mmproj = _child_env.get("LLAMA_ARG_MMPROJ")
                        # The emitted --mmproj replaces an inherited path (argv after env).
                        if effective_is_vision:
                            _env_mmproj = None
                        # --mmproj-device / MTMD_BACKEND_DEVICE re-enable the GPU projector.
                        _mmproj_dev = _extra_args_device(
                            _child_extras, {"--mmproj-device", "-mmdev"}
                        )
                        if _mmproj_dev is None:
                            _mmproj_dev = _child_env.get("MTMD_BACKEND_DEVICE")
                        _mmproj_dev_gpu = bool(
                            _mmproj_dev is not None and str(_mmproj_dev).strip().lower() != "none"
                        )
                        if _resolved_mmproj_offload(_child_extras, _child_env) is False:
                            if _mmproj_dev_gpu:
                                return None
                        elif disable_vision:
                            if _mmproj_env_is_audio_only(_env_mmproj):
                                return None
                        elif (
                            _env_mmproj
                            or _child_env.get("LLAMA_ARG_MMPROJ_URL")
                            or (
                                not launch_mmproj_path
                                and extra_args_mmproj_auto(_child_extras, _child_env)
                            )
                        ):
                            return None
                        # --fit-target precedence: argv, Studio's emitted value, env, default.
                        _supports_fit_target = bool(server_caps.get("supports_fit_target"))
                        _auto_fit = gpu_memory_mode == "manual" and gpu_layers < 0
                        _managed_mib = self._fit_target_margin_mib(
                            auto_fit = _auto_fit,
                            fit_target_delta_mib = _fit_target_delta_mib,
                            supports_fit_target = _supports_fit_target,
                        )
                        # A per-device list reads as its largest entry (the larger shortfall).
                        _margin_mib = fit_target_margin_in(_child_extras or (), None)
                        # Studio's own per-card margins, when it spells the list itself.
                        _margins_by_idx: Optional[dict[int, float]] = None
                        if _margin_mib is None:
                            _emits = _supports_fit_target and (
                                _auto_fit or _managed_mib != _LLAMA_FIT_TARGET_DEFAULT_MIB
                            )
                            _env_mib = None if _emits else fit_target_margin_in((), _child_env)
                            # An inherited 0 is a valid margin, not "unset".
                            _margin_mib = _managed_mib if _env_mib is None else _env_mib
                            if _emits:
                                _margins_by_idx = self._fit_target_margins_mib(
                                    auto_fit = _auto_fit,
                                    fit_target_delta_by_idx = _fit_target_delta_by_idx,
                                    supports_fit_target = _supports_fit_target,
                                )
                        # A lazily read table stays mmap'd on the host, never on the GPU.
                        _child_order, _child_mask = self._planned_child_gpu_order(
                            gpu_ids = gpu_ids,
                            gpu_indices = gpu_indices,
                            tp_tensor_split = tp_tensor_split,
                            extra_args = _child_extras,
                            env = _child_env,
                            is_vulkan_backend = is_vulkan_backend,
                            cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                        )
                        _lazy_host = self._lazy_read_host_bytes(
                            model_path,
                            caps = server_caps,
                            extra_args = _child_extras,
                            env = _child_env,
                            auto_resolves_off = self._lazy_auto_resolves_off(
                                gpu_indices = _child_order,
                                detected_gpus = _detected_gpus,
                                shared_gpu_ids = _shared_gpu_ids,
                                is_vulkan_backend = is_vulkan_backend,
                                extra_args = _child_extras,
                                env = _child_env,
                                tensor_parallel = tensor_parallel,
                                integrated_gpu_ids = _vulkan_igpu_ids,
                                child_gpu_order = _child_mask,
                            ),
                        )
                        _need = (
                            model_size_fit
                            - max(0, _lazy_host - _host_input_embd)
                            - _model_size_fit_cb
                            + _compute_buffer_pipeline
                            + (
                                _kv_bytes(effective_ctx)
                                if _kv_offload_from_args(_child_extras, _child_env)
                                else 0
                            )
                            + (
                                _mtp_bytes(effective_ctx, n_parallel, _effective_ubatch)
                                if _mtp_will_engage
                                else 0
                            )
                            + _cc_bytes(effective_ctx, len(_on))
                        )
                        _free = sum(
                            max(0.0, free - _margin_mib_for(_margins_by_idx or _margin_mib, _idx))
                            for _idx, free in _on
                        )
                        return _need - _free * 1024 * 1024

                    def _moe_resident_share_now() -> Optional[float]:
                        if self.n_moe_layers <= 0:
                            return None
                        try:
                            _short = _fitter_vram_shortfall()
                            if _short is None:
                                return None
                            _scan = self._gguf_tensor_scan(model_path) or (None, {}, 0)
                            return _moe_resident_expert_share(_short, _scan[2])
                        except Exception as e:
                            logger.debug(f"MoE resident share unpriceable ({e})")
                            return None

                    # MoE experts in host RAM: a larger micro-batch amortises the expert
                    # copies of prompt processing (see _MOE_SPILL_N_UBATCH). The placement
                    # verdict above was priced at the default micro-batch, so a model that
                    # fits keeps today's launch. This runs before every term that reads the
                    # micro-batch (MTP reserve, KV, compute buffer, spill planner, load mode),
                    # so the larger buffer is priced: the spill planner keeps fewer experts on
                    # the GPU, and llama.cpp's fitter measures a --fit on launch at the emitted
                    # value. Manual pinned layers (--fit off) are the user's placement, where an
                    # unpriced larger buffer could OOM, so they are left alone. A GPU-only -ot
                    # does not count for the same reason. A user --device none / cpu runs on
                    # the CPU with nothing to stream, like the CPU fallback.
                    _moe_experts_on_host = bool(
                        not (gpu_memory_mode == "manual" and gpu_layers >= 0)
                        and not intent.cpu_fallback
                        and not _device_selection_is_cpu(extra_args, os.environ)
                        and (use_fit or _expert_spill_places_tensors_on_cpu(extra_args, os.environ))
                    )
                    _moe_spill_discrete_gpu = bool(
                        _moe_experts_on_host
                        and self._discrete_gpu_for_expert_spill(
                            gpu_indices, _detected_gpus, _shared_gpu_ids
                        )
                    )
                    _spill_n_batch, _spill_n_ubatch = _moe_spill_batch_ubatch(
                        n_batch,
                        n_ubatch,
                        n_moe_layers = self.n_moe_layers,
                        experts_on_host = _moe_experts_on_host,
                        discrete_gpu = _moe_spill_discrete_gpu,
                        user_named_batch = _user_named_batch,
                    )
                    _moe_ub_switch = _moe_switch(_MOE_SPILL_UBATCH_ENV)
                    if _spill_n_ubatch != n_ubatch and _moe_ub_switch != "off":
                        _share_before = (
                            _moe_resident_share_now() if _moe_ub_switch == "auto" else None
                        )
                        _pre_raise = (
                            n_batch,
                            n_ubatch,
                            _effective_ubatch,
                            _compute_buffer_pipeline,
                            _compute_buffer_tensor,
                        )
                        n_batch, n_ubatch = _spill_n_batch, _spill_n_ubatch
                        _effective_ubatch = _ubatch_for_slots(n_parallel)
                        # Same calls and fallbacks as above, at the new micro-batch.
                        _compute_buffer_pipeline = self._estimate_compute_buffer_bytes(
                            n_ubatch = _effective_ubatch,
                            n_parallel = n_parallel,
                            per_device_tensor = False,
                        ) or (self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024)
                        _compute_buffer_tensor = self._estimate_compute_buffer_bytes(
                            n_ubatch = _effective_ubatch,
                            n_parallel = n_parallel,
                            per_device_tensor = True,
                        ) or (self._TENSOR_PARALLEL_BUFFER_RESERVE_MIB * 1024 * 1024)
                        _share_after = (
                            _moe_resident_share_now()
                            if _moe_ub_switch == "auto" and _share_before is not None
                            else None
                        )
                        if _moe_spill_raise_keeps_experts(
                            _share_before, _share_after, switch = _moe_ub_switch
                        ):
                            logger.info(
                                "MoE experts are offloaded to system RAM; raising "
                                "--ubatch-size %s -> %s for faster prompt processing.",
                                (
                                    _pre_raise[1]
                                    if _pre_raise[1] is not None
                                    else _DEFAULT_LLAMA_N_UBATCH
                                ),
                                _spill_n_ubatch,
                            )
                            self._moe_spill_batch_restore = (_pre_raise[0], _pre_raise[1])
                        else:
                            (
                                n_batch,
                                n_ubatch,
                                _effective_ubatch,
                                _compute_buffer_pipeline,
                                _compute_buffer_tensor,
                            ) = _pre_raise
                            logger.info(
                                "MoE experts: keeping the default --ubatch-size; %s would "
                                "move the GPU's resident share of the routed experts "
                                "%.0f%% -> %.0f%%.",
                                _spill_n_ubatch,
                                100 * (_share_before or 0.0),
                                100 * (_share_after or 0.0),
                            )

                    _moe_cache_candidate = self._moe_cache_auto_eligible(
                        caps = server_caps,
                        gpu_memory_mode = gpu_memory_mode,
                        use_fit = use_fit,
                        experts_on_host = _moe_experts_on_host,
                        discrete_gpu = _moe_spill_discrete_gpu,
                        gpu_indices = gpu_indices,
                        detected_gpus = _detected_gpus,
                        is_vulkan_backend = is_vulkan_backend,
                        tensor_parallel = tensor_parallel,
                        extra_args = extra_args,
                        env = os.environ,
                    )

                    # Pass the final slot and micro-batch values instead of the defaults
                    # captured before slot reduction.
                    _mtp_reserve_bytes = (
                        _mtp_bytes(effective_ctx, n_parallel, _effective_ubatch)
                        if _mtp_will_engage
                        else 0
                    )
                    # DSpark/DFlash borrow the target's token_embd/output, so llama.cpp's fitter
                    # cannot measure the draft
                    # (common/fit.cpp "fitting without it"); carry the planner's reserve in the
                    # child's --fit-target.
                    _sidecar_kind_for_fit = (
                        _mtp_effective if _mtp_effective in ("dspark", "dflash") else None
                    )
                    if _extra_args_set_spec_type(extra_args):
                        _child_spec_types = _accumulated_spec_types(extra_args, env = _spec_env)
                        _sidecar_kind_for_fit = (
                            "dspark"
                            if "draft-dspark" in _child_spec_types
                            else ("dflash" if "draft-dflash" in _child_spec_types else None)
                        )
                    _fit_device_count = _sidecar_planned_device_count()
                    _draft_on_target_device = _draft_on_target_device_now()
                    if (
                        _mtp_will_engage
                        and _mtp_reserves_gpu
                        and _sidecar_kind_for_fit is not None
                        and _draft_on_target_device
                        # Builds whose fitter measures borrowed-tensor drafts need no reserve.
                        and not server_caps.get("fit_measures_borrowed_drafts")
                        and _sidecar_borrows_target_tensors(_mtp_draft_for_budget or mtp_draft_path)
                    ):
                        # Priced even under --fit off: a startup-OOM retry turns the fitter on with
                        # the drafter loaded.
                        _sidecar_auto_ctx = effective_ctx <= 0
                        _sidecar_reserve_ctx = (
                            _sidecar_child_ctx(
                                extra_args,
                                os.environ,
                                self._context_length,
                                n_parallel,
                                planned_kv_unified,
                            )
                            if _sidecar_auto_ctx
                            else effective_ctx
                        )
                        _sidecar_compute_mib = math.ceil(
                            self._MTP_DRAFT_COMPUTE_BYTES / (1024 * 1024)
                        )
                        _sidecar_reserve_path = _mtp_draft_for_budget or mtp_draft_path
                        try:
                            _sidecar_draft_layers = getattr(
                                self._draft_backend_for(_sidecar_reserve_path), "_n_layers", None
                            )
                        except Exception:  # noqa: BLE001 - an unread drafter shares by memory alone
                            _sidecar_draft_layers = None
                        _sidecar_owns_output = not _sidecar_borrows_output(_sidecar_reserve_path)
                        # The fitter measures the target's rollback copies itself.
                        _sidecar_only_bytes = _mtp_bytes(
                            _sidecar_reserve_ctx, n_parallel, _effective_ubatch
                        )
                        if _target_rollback and _mtp_eff_n_max:
                            _sidecar_only_bytes -= (
                                self._rollback_state_bytes(n_parallel) * _mtp_eff_n_max
                            )
                        # An unsized sidecar carries the planner's flat fraction, or the fitter
                        # spends it on target layers.
                        _sidecar_flat_mib = 0
                        if _flat_mtp_reserve > 0:
                            _flat_pool_mib = (
                                _apple_budget_mib
                                if _apple_budget_mib > 0
                                else max(
                                    (
                                        free
                                        for idx, free in (gpus or _detected_gpus)
                                        if gpu_indices is None or idx in gpu_indices
                                    ),
                                    default = 0,
                                )
                            )
                            _sidecar_flat_mib = math.ceil(
                                _flat_mtp_reserve * max(0, _flat_pool_mib)
                            )
                        _sidecar_fit_reserve_eligible_mib = (
                            self._sidecar_fit_reserve_mib(
                                max(0, _sidecar_only_bytes),
                                _sidecar_reserve_path,
                                flat_mib = _sidecar_flat_mib,
                            )
                            + _sidecar_compute_mib
                        )

                        def _sidecar_child_on_discrete_gpus(
                            run_args: List[str], child_env: Mapping[str, str]
                        ) -> bool:
                            """Whether every card the drafter runs on is discrete; positive evidence
                            only."""
                            if _apple_budget_mib:
                                return False
                            active = gpu_indices
                            if (
                                not is_vulkan_backend
                                and _child_gpu_physical_ids is not None
                                and _child_gpu_physical_ids is not _parent_view_gpu_ids
                            ):
                                active = list(_child_gpu_physical_ids)
                                if not active:
                                    return False
                            override = self._effective_device_ids(run_args, child_env)
                            if override is not None:
                                if not override or any(
                                    d.lower() in _CPU_DEVICE_VALUES for d in override
                                ):
                                    return False
                                # This backend's own names only: Vulkan0 is not CUDA0.
                                if not all(
                                    (
                                        re.fullmatch(r"(?i)vulkan\d+", d)
                                        if is_vulkan_backend
                                        else _CUDA_LIKE_DEVICE_RE.match(d)
                                    )
                                    for d in override
                                ):
                                    return False
                                studio_pin = (
                                    [f"vulkan{i}" for i in _vulkan_pin_ids]
                                    if is_vulkan_backend and _vulkan_pin_ids
                                    else None
                                )
                                if [d.lower() for d in override] != studio_pin:
                                    listed = {
                                        d.lower()
                                        for d in (
                                            self._enumerated_gpu_devices(binary, child_env) or []
                                        )
                                    }
                                    if not {d.lower() for d in override} <= listed:
                                        return False
                            seen = {idx for idx, _free in (_detected_gpus or ())}
                            shared = set(_shared_gpu_ids or ())
                            if (
                                is_vulkan_backend
                                and override
                                and not {int(d[6:]) for d in override} <= seen
                            ):
                                # Vulkan Auto drops its iGPUs from the probe.
                                return False
                            if (
                                seen
                                and not (seen & shared)
                                and self._discrete_gpu_for_expert_spill(
                                    None, _detected_gpus, _shared_gpu_ids
                                )
                            ):
                                return True
                            # A mixed host: narrow only through an order the child provably shares.
                            if not is_vulkan_backend and (
                                self._positional_child_order_unproven(child_env)
                                or any(
                                    not all(
                                        t.strip().isdigit()
                                        for t in str(child_env.get(name)).split(",")
                                        if t.strip()
                                    )
                                    for name in (
                                        "CUDA_VISIBLE_DEVICES",
                                        "HIP_VISIBLE_DEVICES",
                                        "ROCR_VISIBLE_DEVICES",
                                    )
                                    if child_env.get(name) is not None
                                )
                            ):
                                return False
                            active, compact = self._effective_gpu_selection(
                                binary, child_env, active, run_args, is_vulkan = is_vulkan_backend
                            )
                            pos = _draft_pin_device_index(
                                _extra_args_draft_device_pin(run_args),
                                ",".join(override) if override else None,
                                len(compact or active or _detected_gpus or ()),
                            )
                            if (
                                pos is None
                                and _extra_args_draft_device_pin(run_args) is None
                                and _split_mode_confines_to_one_device(run_args, child_env)
                            ):
                                main = self._effective_main_gpu(run_args, child_env)
                                pos = 0 if main is None else (main if override else None)
                            if pos is not None:
                                if override:
                                    if not (compact and 0 <= pos < len(compact)):
                                        return False
                                    active = self._physical_ordinals(
                                        [compact[pos]], child_env, is_vulkan_backend
                                    )
                                elif is_vulkan_backend or not self._positional_child_order_unproven(
                                    child_env
                                ):
                                    active = self._physical_ordinals(
                                        [pos], child_env, is_vulkan_backend
                                    )
                            on = set(active) if active else seen
                            if not on or not on <= seen - shared:
                                return False
                            return self._discrete_gpu_for_expert_spill(
                                sorted(on), _detected_gpus, _shared_gpu_ids
                            )

                        def _sidecar_reserve_reprice(
                            run_args: List[str],
                            child_env: Mapping[str, str],
                            _ctx: int = _sidecar_reserve_ctx,
                            _n: int = _mtp_eff_n_max,
                            _dp: Optional[str] = _sidecar_reserve_path,
                            _w: int = _mtp_draft_weights,
                            _np: int = n_parallel,
                            _mtp: bool = _engaged_is_mtp,
                            _swa_full: bool = swa_full,
                            _kv_unified: bool = planned_kv_unified,
                            _ub: Optional[int] = _effective_ubatch,
                            _floor: int = _sidecar_compute_mib,
                            _flat: int = _sidecar_flat_mib,
                            _native: Optional[int] = self._context_length,
                        ) -> int:
                            # Read off the argv: a --flash-attn off respawn pads the draft cache to
                            # f16, extras can change slots.
                            _ck, _cv = _extra_args_draft_cache_types(run_args, child_env)
                            _np = _extra_args_n_parallel(run_args, child_env) or _np
                            _kv_unified = _kv_unified_from_args(
                                run_args, default = _kv_unified, env = child_env
                            )
                            try:
                                _ctx = _sidecar_child_ctx(
                                    run_args, child_env, _native, _np, _kv_unified
                                )
                            except ValueError:
                                pass  # a malformed -c is the launch's error to report, not this
                            # llama_context caps the micro-batch at the batch, and a causal batch at
                            # the context.
                            _ub = _capped_draft_n_ubatch(run_args, child_env, _ctx) or _ub
                            if _ub and _ctx and _ctx > 0:
                                _ub = min(_ub, int(_ctx))
                            _kv_kw = dict(
                                drafter_path = _dp,
                                draft_cache_type_k = _ck,
                                draft_cache_type_v = _cv,
                                n_parallel = _np,
                                swa_full = _swa_full,
                                kv_unified = _kv_unified,
                                n_ubatch = _ub,
                                flash_attn = _flash_attn_enabled_from_args(
                                    run_args, default = planned_flash_attn, env = child_env
                                ),
                            )
                            _v = self._estimate_mtp_overhead_bytes(
                                _ctx,
                                spec_draft_n_max = _n,
                                draft_weights_bytes = _w,
                                mtp_keeps_target_ctx = _mtp,
                                target_rollback = False,
                                **_kv_kw,
                            )
                            # The draft context copies -nkvo, so its KV stays in host buffers.
                            if (
                                _v
                                and not _kv_offload_from_args(run_args, child_env)
                                and _sidecar_child_on_discrete_gpus(run_args, child_env)
                            ):
                                _host_kv = self._mtp_draft_kv_bytes(_ctx, **_kv_kw)
                                if _host_kv:
                                    _v = max(0, _v - _host_kv)
                            try:
                                _sidecar_reserve_graph_mib[0] = math.ceil(
                                    self._mtp_draft_compute_bytes(
                                        _ctx,
                                        drafter_path = _dp,
                                        n_ubatch = _ub,
                                        n_parallel = _np,
                                        spec_draft_n_max = _n,
                                    )
                                    / (1024 * 1024)
                                )
                            except Exception:  # noqa: BLE001 - unsized: the shares carry it
                                _sidecar_reserve_graph_mib[0] = 0
                            return (
                                self._sidecar_fit_reserve_mib(_v or 0, _dp, flat_mib = _flat) + _floor
                            )

                        if _draft_share_unknown:
                            # Drafter partly off the card: its weight share is unpriced, keep only
                            # the compute floor.
                            _sidecar_fit_reserve_eligible_mib = _sidecar_compute_mib
                            _sidecar_reserve_reprice = None
                        # A scalar --fit-target suits only a single-device launch; priced anyway,
                        # since a retry can narrow to one card.
                        if use_fit and (_apple_budget_mib > 0 or _fit_device_count == 1):
                            _sidecar_fit_reserve_mib = _sidecar_fit_reserve_eligible_mib
                    if _mtp_will_engage:
                        _mtp_note = self._mtp_reserve_note(
                            _mtp_reserve_bytes,
                            n_ctx = effective_ctx,
                            n_parallel = n_parallel or 1,
                            n_ubatch = _effective_ubatch,
                            n_max = _mtp_eff_n_max,
                            target_rollback = _target_rollback,
                            flat_fallback = mtp_overhead_fn is None,
                            reprice = lambda slots, ub: _mtp_bytes(effective_ctx, slots, ub),
                        )
                    else:
                        _mtp_note = ""

                    if effective_ctx < original_ctx:
                        kv_est = _kv_bytes(effective_ctx)
                        logger.info(
                            f"Context auto-reduced: {original_ctx} -> {effective_ctx} "
                            f"(model: {model_size / (1024**3):.1f} GB, "
                            f"est. KV cache: {kv_est / (1024**3):.1f} GB, "
                            f"{_mtp_note}".rstrip(", ")
                            + ")"
                        )

                    kv_cache_bytes = _kv_bytes(effective_ctx)
                    # Decide before the log line so it matches the argv.
                    if gpu_memory_mode == "manual" and gpu_layers >= 0:
                        use_fit = False
                    # Separate GPU drafter is a second model; None once CPU-offloaded (_mtp_draft_for_budget nulled).
                    _spill_inputs = {
                        "model_size": model_size,
                        "kv_cache_bytes": kv_cache_bytes,
                        "gpus": list(gpus or ()),
                        # Usable budget per device, not raw free_mib (would under-spill then pin
                        # with --fit off).
                        # _pin_fraction keeps the unsized-drafter cushion free.
                        "gpu_usable_mib": {
                            _idx: max(0.0, _gpu_usable((_idx, _free), _pin_fraction))
                            for _idx, _free in (gpus or ())
                        },
                        "gpu_indices": gpu_indices,
                        "soft_overhead": _soft_overhead,
                        # The planner rebuilds from the GGUF tensor table, so projector and MTP are absent.
                        "extra_gpu_bytes": (mmproj_size + _shared_pool_mmproj + _mtp_reserve_bytes),
                        # Not double-charged; omitting it would OOM in graph_reserve under --fit off.
                        "compute_buffer_flat": int(_compute_buffer_pipeline),
                        "ctx_compute_per_device": (
                            _cc_bytes(effective_ctx, max(1, len(gpus or ())))
                            // max(1, len(gpus or ()))
                        ),
                        # An engaged draft of any kind makes nextn/MTP blocks resident in the target load, so charge them back; over-charging only spills more
                        "mtp_will_engage": bool(_mtp_will_engage),
                        # A SEPARATE drafter that stays on the GPU: a second model,
                        # whose weights and KV llama.cpp distributes like any other.
                        # None once the drafter is CPU-offloaded (_mtp_draft_for_budget
                        # is nulled there), which is the case that really is off-GPU.
                        "separate_draft_on_gpu": bool(_mtp_will_engage and _mtp_draft_for_budget),
                        # Claims no placement (llama.cpp enumerates devices); _detected_gpus, since manual modes empty gpus.
                        "model_path": model_path,
                        "n_ctx": effective_ctx,
                        "n_threads": n_threads,
                        # Slot count the KV and recurrent state were priced at; a pass-through --parallel is appended last and wins, and both caches scale with it
                        "n_parallel": int(n_parallel or 1),
                        # Only ratios are used (scaled to kv_cache_bytes) to show where big caches land; must use the same launch settings kv_cache_bytes was priced at
                        "kv_layer_weights": self._kv_layer_weights(
                            effective_ctx,
                            swa_full = swa_full,
                            n_parallel = n_parallel,
                            kv_unified = planned_kv_unified,
                            n_ubatch = _effective_ubatch,
                            flash_attn = planned_flash_attn,
                            cache_type_kv = cache_type_kv,
                        ),
                        # An iGPU or APU reports host RAM as VRAM; do not count it twice.
                        "shared_gpu_ids": set(_shared_gpu_ids or ()),
                    }
                    mmproj_note = (
                        f"mmproj: {mmproj_size / (1024**3):.1f} GB, " if mmproj_size else ""
                    )
                    logger.info(
                        f"GGUF size: {gguf_size / (1024**3):.1f} GB, "
                        f"{mmproj_note}"
                        f"est. KV cache: {kv_cache_bytes / (1024**3):.1f} GB, "
                        f"{_mtp_note}"
                        f"context: {effective_ctx}, "
                        # Reports the --fit flag state, not whether the model fits: off means this subset provably fits; manual modes empty gpus on purpose, not a failed probe
                        f"GPUs free: {gpus}"
                        f"{' (manual mode)' if not gpus and gpu_memory_mode == 'manual' else ''}, "
                        f"selected: {gpu_indices}, --fit: {'on' if use_fit else 'off'}"
                    )
                    _on = list(gpu_indices or [idx for idx, _ in gpus])
                    if _on:
                        self._pending_plan_mib = _gpu_plan_mib(
                            max(1, gguf_size - _host_input_embd) + mmproj_size + kv_cache_bytes,
                            _on,
                            gpus,
                        )
                    if (
                        not gpus
                        and not _detected_gpus
                        and not gpu_ids
                        and not _arch_gate_forced_cpu
                        and not _metal_capable_host()
                    ):
                        # Claims no placement: llama.cpp enumerates devices itself.
                        # _detected_gpus, not gpus: Manual modes empty gpus on purpose.
                        # gpu_ids is pinned for the child below; the arch gate warns better.
                        logger.warning(
                            "Unsloth could not enumerate any GPU, so this load was planned "
                            "without device information: %s",
                            LlamaCppBackend._explain_empty_gpu_probe(binary),
                        )
                    # Set last, so any early return or raise leaves it False.
                    _placement_verdict_partial = bool(_detected_gpus) and bool(use_fit)

                    # Load mode: mmap demand-pages what RAM cannot hold, so a fitting load wants none. Use gpus not _detected_gpus: arch gate empties it on --device none
                    _fit_devices = max(1, len(gpu_indices or ()) or len(gpus))
                    # A CPU-pinned drafter is still in host RAM; None means abstain.
                    _cpu_draft_fit_bytes = self._cpu_resident_draft_bytes(
                        effective_ctx,
                        drafter_path = _cpu_draft_path,
                        draft_cache_type_k = _mtp_draft_ck,
                        draft_cache_type_v = _mtp_draft_cv,
                        n_parallel = n_parallel,
                        swa_full = swa_full,
                        kv_unified = planned_kv_unified,
                        n_ubatch = _effective_ubatch,
                        flash_attn = planned_flash_attn,
                    )
                    # Classify on what the child gets: a gpu_ids pin drops device flags and env twins; unpinned, the child inherits LLAMA_ARG_DEVICE verbatim
                    _fit_extras = (
                        self._strip_device_extra_args(extra_args)
                        if _gpu_ids_own_device_flags
                        else extra_args
                    )
                    _fit_env = dict(os.environ)
                    if gpu_memory_mode == "manual":
                        self._clear_manual_placement_env(_fit_env)
                    if _gpu_ids_own_device_flags:
                        self._clear_device_placement_env(_fit_env)
                    self._reconcile_split_mode_env(_fit_env, tensor_parallel = tensor_parallel)
                    # What the placement branch below will emit, so the effective
                    # (last-wins) fitter state is readable before the final argv exists.
                    # Every reachable branch is fixed by use_fit.
                    _fitter_runs = fit_is_effectively_on(
                        ["--fit", "on" if use_fit else "off", *(_fit_extras or [])],
                        _fit_env,
                    )
                    # Drafter split card/host by fixed -ngld is unsized, so abstain: llama.cpp keeps layers past the count in host RAM. Pass-through --fit-target wins
                    _draft_split_across_host = bool(
                        _mtp_draft_for_budget
                        and _draft_is_split_across_host(
                            _fit_extras,
                            _fit_env,
                            n_draft_layers = getattr(
                                self._draft_backend_for(_mtp_draft_for_budget),
                                "_n_layers",
                                None,
                            ),
                        )
                    )
                    _fit_margin_mib = (
                        max(
                            self._fit_target_margin_mib(
                                auto_fit = (gpu_memory_mode == "manual" and gpu_layers < 0),
                                fit_target_delta_mib = _fit_target_delta_mib if use_fit else 0.0,
                                supports_fit_target = use_fit
                                and bool(server_caps.get("supports_fit_target")),
                                floor_mib = _metal_fit_target_floor_mib,
                            ),
                            fit_target_margin_in(_fit_extras, _fit_env) or 0.0,
                        )
                        if _fitter_runs
                        else 0.0
                    )
                    # Studio's per-card list replaces the single value only when Studio
                    # owns the margin: a pass-through one wins outright (above).
                    _fit_margins_by_idx = (
                        self._fit_target_margins_mib(
                            auto_fit = (gpu_memory_mode == "manual" and gpu_layers < 0),
                            fit_target_delta_by_idx = _fit_target_delta_by_idx,
                            supports_fit_target = bool(server_caps.get("supports_fit_target")),
                        )
                        if _fitter_runs
                        and use_fit
                        and not _metal_fit_target_floor_mib
                        and fit_target_margin_in(_fit_extras, _fit_env) is None
                        else None
                    )
                    # A projector Unsloth never resolved but the child loads anyway:
                    # LLAMA_ARG_MMPROJ / _URL are read before argv and only the vision
                    # switch and the paravirtual pin clear them, while model_size carries
                    # none of those bytes. A URL names a download that has not happened
                    # (and outranks even the --mmproj this launch emits), and an
                    # unreadable path cannot be sized, so both abstain.
                    _fit_env_mmproj_scrubbed = bool(
                        _pv_mmproj_unpinnable or _paravirtual_cpu_forced
                    )
                    _fit_env_mmproj = (
                        ""
                        if (
                            launch_mmproj_path
                            or _fit_env_mmproj_scrubbed
                            or (
                                disable_vision
                                # The scrub's own audio-only reprieve: that projector
                                # survives the switch, so it is loaded.
                                and not _mmproj_env_is_audio_only(_fit_env.get("LLAMA_ARG_MMPROJ"))
                            )
                        )
                        else (_fit_env.get("LLAMA_ARG_MMPROJ") or "").strip()
                    )
                    _fit_env_mmproj_url = (
                        ""
                        if (_fit_env_mmproj_scrubbed or disable_vision)
                        else (_fit_env.get("LLAMA_ARG_MMPROJ_URL") or "").strip()
                    )
                    _fit_env_mmproj_bytes = self._mmproj_vram_bytes(_fit_env_mmproj or None)
                    _fit_env_mmproj_unsized = bool(_fit_env_mmproj_url) or (
                        bool(_fit_env_mmproj) and _fit_env_mmproj_bytes <= 0
                    )
                    # Ungated like _subset_model_size: CUDA context and scratch exist regardless of the pipeline.
                    _fit_env_mmproj_on_host = (
                        _resolved_mmproj_offload(_fit_extras, _fit_env) is False
                    )
                    _fit_model_size = model_size
                    if _fit_env_mmproj_unsized:
                        # Same abstain the other unreadable terms take.
                        _fit_model_size = None
                    elif _fit_model_size and not _fit_env_mmproj_on_host:
                        _fit_model_size += _fit_env_mmproj_bytes
                    _fit_soft_overhead = _soft_overhead + self._inherited_mmproj_soft_overhead(
                        _fit_env_mmproj_bytes,
                        on_host = _fit_env_mmproj_on_host,
                    )
                    # Pass the inherited projector to the spill planner, or its VRAM goes unpaid: the plan is pinned with --fit off, so llama.cpp cannot absorb it
                    _spill_inputs["env_mmproj_unsized"] = _fit_env_mmproj_unsized
                    _spill_inputs["host_mmproj_bytes"] = _mmproj_pinned_bytes + (
                        _fit_env_mmproj_bytes if _fit_env_mmproj_on_host else 0
                    )
                    _spill_inputs["env_mmproj_bytes"] = (
                        0
                        if _fit_env_mmproj_on_host
                        else _fit_env_mmproj_bytes
                        + self._inherited_mmproj_soft_overhead(_fit_env_mmproj_bytes, on_host = False)
                    )
                    # Derive the host-only share from the same estimator as the total.
                    _effective_ctx_checkpoints = _ctx_checkpoints_for_final_slots()
                    _ckpt_host_bytes = max(
                        0,
                        _kv_bytes(effective_ctx, _effective_ctx_checkpoints)
                        - _kv_bytes(effective_ctx, 0),
                    )
                    # A lazily read table stays mmap'd under every load mode: not pinned RAM.
                    # An empty inventory beside a GPU may hide an iGPU, where auto is off: priced
                    # resident.
                    _fit_child_order, _fit_child_mask = self._planned_child_gpu_order(
                        gpu_ids = gpu_ids,
                        gpu_indices = gpu_indices,
                        tp_tensor_split = tp_tensor_split,
                        extra_args = _fit_extras,
                        env = _fit_env,
                        is_vulkan_backend = is_vulkan_backend,
                        cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                    )
                    _fit_lazy_auto_off = (
                        not _detected_gpus
                        and (is_vulkan_backend or _gpu_device_node_present())
                        and not self._child_runs_on_cpu(
                            binary,
                            _fit_extras,
                            _fit_env,
                            cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                            tensor_parallel = tensor_parallel,
                        )
                    ) or self._lazy_auto_resolves_off(
                        gpu_indices = _fit_child_order,
                        detected_gpus = _detected_gpus,
                        shared_gpu_ids = _shared_gpu_ids,
                        is_vulkan_backend = is_vulkan_backend,
                        extra_args = _fit_extras,
                        env = _fit_env,
                        tensor_parallel = tensor_parallel,
                        integrated_gpu_ids = _vulkan_igpu_ids,
                        child_gpu_order = _fit_child_mask,
                    )
                    _fit_lazy_bytes = self._lazy_read_host_bytes(
                        model_path,
                        caps = server_caps,
                        extra_args = _fit_extras,
                        env = _fit_env,
                        auto_resolves_off = _fit_lazy_auto_off,
                    )
                    _fit_load_mode_kwargs = dict(
                        model_size = _fit_model_size,
                        mmproj_pinned_bytes = _mmproj_pinned_bytes
                        + (_fit_env_mmproj_bytes if _fit_env_mmproj_on_host else 0),
                        # Checkpoints are split into host_only_bytes below.
                        kv_cache_bytes = _kv_bytes(effective_ctx, 0),
                        kv_sized = self._can_estimate_kv(),
                        # mtp_overhead_fn bound the pre-raise micro-batch; charge the raised one.
                        mtp_bytes = _mtp_bytes(
                            effective_ctx,
                            ubatch = (
                                _effective_ubatch
                                if self._moe_spill_batch_restore is not None
                                else None
                            ),
                        ),
                        # MTP engages whole: its unsized arm prices weights but no draft KV, which a
                        # flat cushion covers.
                        mtp_unsized = bool(
                            _flat_mtp_engages
                            or _cpu_draft_fit_bytes is None
                            or _draft_split_across_host
                        ),
                        # Neither a CPU drafter nor checkpoints can be covered by free VRAM.
                        host_only_bytes = (_cpu_draft_fit_bytes or 0) + _ckpt_host_bytes,
                        # A tensor split replicates the graph buffer on every device.
                        compute_buffer_flat = (
                            _fit_devices * _compute_buffer_tensor
                            if _tp_planned
                            else _compute_buffer_pipeline
                        ),
                        compute_buffer_ctx = _cc_bytes(effective_ctx, _fit_devices),
                        # Ungated, like _subset_model_size: the per-device CUDA context
                        # and scratch are there whether or not llama.cpp keeps the
                        # pipeline (_cc_bytes is the term that gates on it).
                        pipeline_overhead_bytes = (
                            max(0, _fit_devices - 1) * _pipeline_overhead_bytes
                        ),
                        soft_overhead = _fit_soft_overhead,
                        gpus = gpus,
                        gpu_indices = gpu_indices,
                        shared_gpu_ids = _shared_gpu_ids,
                        # A running fitter keeps --fit-target free per device, so that
                        # margin is not VRAM this fit may spend. Zero only when the
                        # fitter is provably off; see _fitter_runs above.
                        fit_margin_mib = _fit_margins_by_idx or _fit_margin_mib,
                        is_vulkan_backend = is_vulkan_backend,
                        # Never stripped, and appended last, so they beat this
                        # launch's own -ngl.
                        extra_args = _fit_extras,
                        env = _fit_env,
                        lazy_read_bytes = _fit_lazy_bytes,
                    )
                    _resident_inputs = max(0, _host_input_embd - _fit_lazy_bytes)
                    if _resident_inputs and _fit_load_mode_kwargs["model_size"]:
                        _fit_load_mode_kwargs["model_size"] = max(
                            1, _fit_load_mode_kwargs["model_size"] - _resident_inputs
                        )
                        _fit_load_mode_kwargs["host_only_bytes"] += _resident_inputs
                    if _managed_lazy_flags is None:
                        _lazy_prompt_cache = _prompt_cache_host_bytes(
                            cache_ram,
                            _fit_extras,
                            _fit_env,
                            supports_cache_ram = bool(server_caps.get("supports_cache_ram")),
                        )

                        def _table_resident_fits(table: int) -> Optional[bool]:
                            if (
                                _lazy_prompt_cache is None
                                or not _fit_load_mode_kwargs["model_size"]
                                or effective_ctx <= 0
                                or _pass_through_reprices_cache(_fit_extras, n_parallel)
                                # A CPU child cannot use the cards this fit credits.
                                or self._child_runs_on_cpu(
                                    binary,
                                    _fit_extras,
                                    _fit_env,
                                    cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                                    tensor_parallel = tensor_parallel,
                                )
                            ):
                                return None
                            return (
                                self._fit_derived_load_mode(
                                    **{
                                        **_fit_load_mode_kwargs,
                                        "lazy_read_bytes": table,
                                        "host_only_bytes": _fit_load_mode_kwargs["host_only_bytes"]
                                        + table
                                        + _lazy_prompt_cache
                                        + int(table * _LAZY_RESIDENT_MARGIN_FRAC),
                                        "announce": False,
                                    }
                                )
                                == self._FIT_LOAD_MODE
                            )

                        _managed_lazy_flags = self._managed_lazy_mode_flags(
                            model_path,
                            caps = server_caps,
                            extra_args = _fit_extras,
                            env = _fit_env,
                            auto_resolves_off = _fit_lazy_auto_off,
                            resident_fits = _table_resident_fits,
                            binary = binary,
                        )
                    if _managed_lazy_flags and _fit_lazy_bytes:
                        if _fit_load_mode_kwargs["model_size"]:
                            _fit_load_mode_kwargs["model_size"] = max(
                                1, _fit_load_mode_kwargs["model_size"] - _fit_lazy_bytes
                            )
                        _fit_load_mode_kwargs["host_only_bytes"] += _fit_lazy_bytes
                        _fit_load_mode_kwargs["lazy_read_bytes"] = 0
                        _fit_lazy_bytes = 0
                    _spill_inputs["lazy_read_bytes"] = _fit_lazy_bytes
                    _fit_load_mode = self._fit_derived_load_mode(**_fit_load_mode_kwargs)
                    if _moe_cache_candidate:
                        _moe_cache_switch = _moe_switch(_MOE_CACHE_ENV)
                        _moe_share = (
                            _moe_resident_share_now() if _moe_cache_switch == "auto" else None
                        )
                        if not _moe_cache_share_admits(
                            _moe_share, drafter = _mtp_will_engage, switch = _moe_cache_switch
                        ):
                            _moe_cache_candidate = False
                            if _moe_cache_switch == "off":
                                _why = f"{_MOE_CACHE_ENV} is off"
                            elif _moe_share is None:
                                _why = "the share of routed experts left on the GPU is unknown"
                            elif _mtp_will_engage and not _MOE_CACHE_WITH_DRAFTER:
                                _why = "a drafter is engaged"
                            else:
                                _why = (
                                    f"an estimated {100 * _moe_share:.0f}% of the routed "
                                    "experts stay on the GPU"
                                )
                            logger.info(
                                "MoE cache: %s; keeping the --fit split without "
                                "--moe-cache-mib.",
                                _why,
                            )
                    if _moe_cache_candidate:
                        # The cache frees no host RAM: every routed expert plus the prompt
                        # cache must fit pinned (moved out of model_size, not counted twice).
                        _moe_expert_bytes = (self._gguf_tensor_scan(model_path) or (None, {}, 0))[2]
                        _moe_prompt_cache_bytes = _prompt_cache_host_bytes(
                            cache_ram,
                            _fit_extras,
                            _fit_env,
                            supports_cache_ram = bool(server_caps.get("supports_cache_ram")),
                        )
                        # An unknown size (unsized inherited projector) admits nothing.
                        _moe_cache_ram_ok = bool(
                            _fit_load_mode_kwargs["model_size"]
                            and _moe_expert_bytes > 0
                            and _moe_prompt_cache_bytes is not None
                            and self._fit_derived_load_mode(
                                **{
                                    **_fit_load_mode_kwargs,
                                    "model_size": max(
                                        1, _fit_load_mode_kwargs["model_size"] - _moe_expert_bytes
                                    ),
                                    "host_only_bytes": _fit_load_mode_kwargs["host_only_bytes"]
                                    + _moe_expert_bytes
                                    + _moe_prompt_cache_bytes,
                                    "announce": False,
                                }
                            )
                            == self._FIT_LOAD_MODE
                        )
                        if not _moe_cache_ram_ok:
                            logger.info(
                                "MoE cache: system RAM cannot hold the %.1f GB of routed "
                                "experts pinned; launching without --moe-cache-mib.",
                                _moe_expert_bytes / (1024**3),
                            )
                except Exception as e:
                    logger.warning(f"GPU selection failed ({e}), using --fit on")
                    gpu_indices, use_fit = None, True
                    _metal_full_offload_pinned = False
                    # Not a verdict: this arm never priced anything, so the flag is set explicitly and cannot survive from a previous load
                    _placement_verdict_partial = False
                    # Same reasoning: an unpriced load keeps llama.cpp's default.
                    _fit_load_mode = None
                    _managed_lazy_flags = None
                    _moe_cache_candidate = _moe_cache_ram_ok = False
                    # And a half-built snapshot is not a price either: the throw can
                    # land after the dict exists but before the later terms are added
                    # to it, which would plan against a footprint missing them.
                    _spill_inputs = None
                    # Nor is a ceiling the fallback's own fitter may spill past.
                    _vram_fit_ctx = None
                    tp_tensor_split = None
                    effective_ctx = requested_ctx  # fall back to original
                    # Nor is a slot cut for the drafter: requested count, no drafter, as before.
                    if _mtp_slots_asked is not None:
                        n_parallel = _mtp_slots_asked
                        _mtp_slots_asked = _mtp_slots_target_ctx = None
                        _effective_ubatch = _ubatch_for_slots(n_parallel)
                        _compute_buffer_pipeline = _layer_compute_buffer(n_parallel)
                        _spec_dropped_no_vram = True
                        _mtp_will_engage = False
                        mtp_overhead_fn = None
                        _mtp_kv_unsized = False

                # Outside the placement catch, which would fall back to --fit on; the route
                # evicts an idle resident and retries.
                if _metal_alongside_shortfall is not None:
                    need_mib, budget_mib = _metal_alongside_shortfall
                    raise GpuMemoryShortError(
                        f"This model and its context need about {need_mib / 1024:.1f} GiB, "
                        f"but only {budget_mib / 1024:.1f} GiB remains in this Mac's "
                        "unified-memory budget. Free memory or use a smaller model.",
                        short_mib = need_mib - budget_mib,
                    )
                # A hand-set context unified memory cannot hold. Raised here so the handler
                # above cannot turn it back into the launch it refuses, and ahead of the
                # Vulkan and APU checks, which describe hardware this branch has ruled out.
                if _metal_ctx_refusal:
                    raise RuntimeError(_metal_ctx_refusal)
                self._record_load_warning(_metal_ctx_warning)

                if (
                    intent.refuse_partial_gpu_fit
                    and (_placement_verdict_partial or _ctx_capped_for_vram)
                    and gpu_memory_mode != "manual"
                ):
                    capped_only = _ctx_capped_for_vram and not _placement_verdict_partial
                    asked_ctx = _ctx_before_fit if capped_only else effective_ctx
                    need_mib = (
                        max(1, gguf_size - _host_input_embd) + mmproj_size + _kv_bytes(asked_ctx)
                    ) // (1024 * 1024)
                    free_mib = sum(free for _, free in gpus)
                    need_gb, free_gb = need_mib / 1024, free_mib / 1024
                    # The probe's own classifiers: an integrated CUDA SoC can report a real total.
                    try:
                        _shared = (
                            _shared_pool_gpus
                            | self._rocm_unified_memory_gpu_ids()
                            | self._integrated_cuda_gpu_ids()
                        )
                    except Exception:
                        _shared = None
                    raise GpuMemoryShortError(
                        _gpu_short_message(need_gb, free_gb, asked_ctx, effective_ctx, capped_only),
                        capped = capped_only,
                        short_mib = max(0, need_mib - free_mib),
                        gpu_indices = tuple(idx for idx, _ in gpus),
                        discrete = _shared is not None and not _shared & {idx for idx, _ in gpus},
                    )

                # Unpinnable explicit Vulkan ordinal: fail loudly rather than fit onto an unselected device; clear raw selection so it never leaks into gpu_ids
                if _vulkan_explicit_unmatched:
                    self._gpu_ids = None
                    self._requested_gpu_ids = None
                    raise ValueError(
                        f"Requested Vulkan GPU ordinal(s) {_vulkan_requested_ids} not "
                        f"present. Available Vulkan devices: {_vulkan_available_ordinals}."
                    )

                # Pin the whole picked set so the model can't spill onto an unpicked GPU.
                if gpu_ids:
                    gpu_indices, tp_tensor_split = self._picker_ordered_gpu_indices(
                        gpu_ids, gpu_indices, tp_tensor_split
                    )
                # Auto Vulkan fit prefers discrete GPUs and keeps that pool pinned.
                elif (
                    is_vulkan_backend
                    and gpu_memory_mode != "manual"
                    and use_fit
                    and gpu_indices is None
                    and _detected_gpus
                ):
                    gpu_indices = sorted(idx for idx, _free in _detected_gpus)

                # Reload dedupe compares requested_gpu_ids; a forced-CPU launch pins no GPU.
                if gpu_ids and not _paravirtual_cpu_forced:
                    effective_pin = gpu_indices if gpu_indices is not None else gpu_ids
                    # Survivor order, not sorted: _runtime_matches_intent compares positionally.
                    self._gpu_ids = [int(idx) for idx in effective_pin]
                else:
                    self._gpu_ids = None

                # Carried to the launch site, the only place the pageable override can apply; without it an oversized APU load under none or mlock is an OOM kill
                _apu_ram_oversized = False
                # model_size less a lazily read table; the text-only reprice charges the same.
                _apu_resident_model_size = model_size
                # The two shortfall notices this load recorded, kept verbatim (and
                # un-amended) so the text-only fallback further down can re-price them
                # once it drops the CPU-pinned projector whose bytes they charged. Both
                # are re-stated by the arch-crash retry, which starts its own warning
                # scope, so what these hold is always the pair behind the notice the
                # route would hand back right now.
                _apu_ram_msg: Optional[str] = None
                _host_ram_msg: Optional[str] = None
                # The RAM figure those notices were priced against, kept with them.
                _apu_avail_mib: Optional[int] = None
                # ...and which part they describe, for the same reason.
                _apu_ram_part = "APU"

                # Unified-memory APUs load weights into system RAM (WSL: VM cap), so refuse oversize loads the OS would kill mid-flight; base model only. CUDA/ROCm ids only
                if (
                    model_size is not None
                    and not is_vulkan_backend
                    # An integrated CUDA SoC loads into system RAM; _shared_gpu_ids is Vulkan-only, so without this its pool is credited as VRAM and the spill prices at zero
                    and (
                        self._amd_apu_wants_unified_memory(gpu_indices)
                        or (
                            self._integrated_cuda_probe_is_free()
                            and self._integrated_cuda_selection_is_all_shared(gpu_indices)
                        )
                    )
                ):
                    # Read once: a later reading would already exclude the resident model.
                    _apu_avail_mib = self._available_system_memory_mib()
                    # Kept beside the notice: the text-only fallback rebuilds it later
                    # and would otherwise turn a Spark's into an APU's, .wslconfig hint
                    # and all.
                    _apu_ram_part = (
                        "APU" if self._amd_apu_wants_unified_memory(gpu_indices) else "SoC"
                    )
                    _apu_lazy_extras = (
                        self._strip_device_extra_args(extra_args)
                        if _gpu_ids_own_device_flags
                        else extra_args
                    )
                    _apu_lazy_env = dict(os.environ)
                    if gpu_memory_mode == "manual":
                        self._clear_manual_placement_env(_apu_lazy_env)
                    if _gpu_ids_own_device_flags:
                        self._clear_device_placement_env(_apu_lazy_env)
                    self._reconcile_split_mode_env(_apu_lazy_env, tensor_parallel = tensor_parallel)
                    _apu_child_order, _apu_child_mask = self._planned_child_gpu_order(
                        gpu_ids = gpu_ids,
                        gpu_indices = gpu_indices,
                        tp_tensor_split = tp_tensor_split,
                        extra_args = _apu_lazy_extras,
                        env = _apu_lazy_env,
                        is_vulkan_backend = False,
                        cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                    )
                    _apu_resident_model_size = max(
                        1,
                        model_size
                        - self._lazy_read_host_bytes(
                            model_path,
                            caps = server_caps,
                            extra_args = _apu_lazy_extras,
                            env = _apu_lazy_env,
                            # A failed GPU probe still launches on the APU, where auto is off.
                            auto_resolves_off = (
                                not _detected_gpus
                                and not self._child_runs_on_cpu(
                                    binary,
                                    _apu_lazy_extras,
                                    _apu_lazy_env,
                                    cpu_forced = _paravirtual_cpu_forced or _arch_gate_forced_cpu,
                                    tensor_parallel = tensor_parallel,
                                )
                            )
                            or self._lazy_auto_resolves_off(
                                gpu_indices = _apu_child_order,
                                detected_gpus = _detected_gpus,
                                shared_gpu_ids = _shared_gpu_ids,
                                is_vulkan_backend = False,
                                probe_integrated_cuda = False,
                                extra_args = _apu_lazy_extras,
                                env = _apu_lazy_env,
                                tensor_parallel = tensor_parallel,
                                child_gpu_order = _apu_child_mask,
                            ),
                        ),
                    )
                    _ram_msg = self._apu_ram_shortfall_message(
                        # A pinned projector left model_size but not system RAM, and
                        # this guard exists to stop an oversize load being OOM-killed
                        # mid-read, so it has to weigh the projector either way.
                        _apu_resident_model_size + _mmproj_pinned_bytes,
                        _apu_avail_mib,
                        part = _apu_ram_part,
                    )
                    # Re-ask for the set the child sees: the guard priced every visible card, incl. an APU the gate drops. Warned branch only; an empty answer keeps the warning
                    if _ram_msg and gpu_indices is None and not gpu_ids:
                        _gated_pin = self._arch_gate_survivors(binary)
                        if _gated_pin and not self._amd_apu_wants_unified_memory(_gated_pin):
                            logger.info(
                                "Skipping the APU RAM warning: the arch gate pins "
                                "this launch to discrete GPU(s) %s.",
                                _gated_pin,
                            )
                            _ram_msg = None
                    # Read after the arch-gate skip, so a launch the gate moves onto discrete cards is not remapped; independent of UNSLOTH_ALLOW_HOST_OFFLOAD
                    _apu_ram_oversized = bool(_ram_msg)
                    # The opt-out may only silence the message, never the rewrite: read it after the verdict, so the rewrite the verdict drives is untouched
                    if _ram_msg and self._host_offload_warning_opted_out():
                        logger.info(
                            "UNSLOTH_ALLOW_HOST_OFFLOAD set: not recording the APU RAM advisory."
                        )
                        _ram_msg = None
                    _apu_ram_msg = _ram_msg
                    self._record_load_warning(_ram_msg)

                # Probe LLAMA_ARG_MMPROJ too, since launch_mmproj_path misses it, but never a projector the unpinnable guard dropped
                self._mmproj_has_audio = False
                self._mmproj_accepts_image = True
                # Skip a projector the vision switch or the Metal scrub will remove, unless the switch keeps
                # an audio-only encoder; otherwise we'd advertise audio the child does not have.
                _dv_env_mmproj_kept = (
                    disable_vision
                    and not _paravirtual_cpu_forced
                    and _mmproj_env_is_audio_only(os.environ.get("LLAMA_ARG_MMPROJ"))
                )
                _mmproj_probe = launch_mmproj_path or (
                    ""
                    if (_pv_mmproj_unpinnable or (disable_vision and not _dv_env_mmproj_kept))
                    else (os.environ.get("LLAMA_ARG_MMPROJ") or "")
                )
                self._mmproj_projector_type = None
                if launch_mmproj_path or os.path.isfile(_mmproj_probe):
                    try:
                        from utils.models.gguf_metadata import (
                            mmproj_capabilities,
                            read_mmproj_projector_type,
                        )

                        has_audio, accepts_image = mmproj_capabilities(_mmproj_probe)
                        self._mmproj_has_audio = has_audio
                        self._mmproj_accepts_image = accepts_image
                        # KV admission needs the projector family to look up per-image token cost.
                        self._mmproj_projector_type = read_mmproj_projector_type(_mmproj_probe)
                    except Exception as e:
                        logger.debug(f"mmproj capability read failed: {e}")

                auto_fit = gpu_memory_mode == "manual" and gpu_layers < 0
                # Keep the unstripped request: it is the reuse comparator, stripping it forced reloads.
                _extra_args_as_requested = list(extra_args) if extra_args is not None else None
                if self._metal_drops_zero_ctx_override(ctx_override, _caller_owns_budget):
                    extra_args = strip_context_only(extra_args)
                    logger.warning(
                        "Dropping the pass-through zero context: on Metal it pins the "
                        "model's native length and disables --fit."
                    )
                _metal_floor = self._metal_zero_ctx_floor(
                    effective_ctx,
                    auto_fit,
                    _caller_owns_budget,
                    self._context_length,
                    max_available_ctx,
                    # Whether the child fitter runs decides the Auto-layers exemption and floor reach; only the user can turn it off, via later extras or LLAMA_ARG_FIT
                    fitter_runs = fit_is_effectively_on(extra_args, os.environ),
                )
                if _metal_floor:
                    effective_ctx = _metal_floor
                    # Replace, not max(): on failure this still holds the native length, which never fit.
                    max_available_ctx = _metal_floor
                    logger.warning(
                        "No GPU is enumerated on Metal and the context cap did not "
                        f"run, so starting at {effective_ctx} rather than the model's "
                        "native length."
                    )

                # Fail open: these flags are emitted every launch and an unknown arg exits a stale or user LLAMA_SERVER_PATH, so only a build positively lacking one drops it
                _caps = _launch_caps(binary)
                cmd = [
                    binary,
                    "-m",
                    model_path,
                    "--port",
                    str(self._port),
                    "--parallel",
                    str(n_parallel),
                ]
                # Gate on whether the build has -fa and whether it takes a value (old builds: bare bool).
                if _caps.get("supports_flash_attn", True):
                    if not _extra_args_set_any_flag(extra_args, {"-fa", "--flash-attn"}):
                        cmd.append("--flash-attn")
                        if _caps.get("flash_attn_takes_value", True):
                            cmd.append("on")
                else:
                    # Only ever reached on an authoritative --help that has no
                    # flash attention to lose, so there is no speed to give up.
                    _flash_attn_known_off = True
                # Error out at n_ctx instead of silently rotating the KV cache; frontend catches it and points the user at "Context Length".
                if _caps.get("supports_no_context_shift", True):
                    if not _extra_args_set_any_flag(
                        extra_args, {"--context-shift", "--no-context-shift"}
                    ):
                        cmd.append("--no-context-shift")
                # Omit -c for auto-fit with no context: -c 0 pins native ctx and disables --fit reduction.
                if effective_ctx > 0:
                    cmd.extend(["-c", str(effective_ctx)])
                elif not auto_fit:
                    cmd.extend(["-c", "0"])

                # llama-server 501s on /v1/embeddings without this; pooling stays model-default.
                if self.is_embedding_gguf:
                    cmd.append("--embedding")

                # emitted before user extras so a pass-through -b / -ub still last-wins-overrides
                if n_batch is not None:
                    # -b < --parallel and -b 1 both GGML_ASSERT, so the batch floor is max(slots, 2).
                    _emit_batch = _emitted_n_batch(n_batch, n_parallel)
                    if _emit_batch != n_batch:
                        logger.warning(
                            "Raising --batch-size from %s to %s: llama-server aborts below "
                            "2 and below the %s parallel slot(s) it serves.",
                            n_batch,
                            _emit_batch,
                            n_parallel,
                        )
                    cmd.extend(["--batch-size", str(_emit_batch)])
                if n_ubatch is not None:
                    cmd.extend(["--ubatch-size", str(n_ubatch)])
                # The expert-spill raise, as emitted and as it was before, so a CPU
                # replay (no GPU, nothing to stream) can hand back today's pair.
                self._moe_spill_batch_tokens = None
                if self._moe_spill_batch_restore is not None:
                    _orig_batch, _orig_ubatch = self._moe_spill_batch_restore
                    _raised = ["--ubatch-size", str(n_ubatch)]
                    _before = [] if _orig_ubatch is None else ["--ubatch-size", str(_orig_ubatch)]
                    if n_batch is not None and n_batch != _orig_batch:
                        _raised = ["--batch-size", str(_emit_batch), *_raised]
                        _before = [
                            *(
                                []
                                if _orig_batch is None
                                else [
                                    "--batch-size",
                                    str(_emitted_n_batch(_orig_batch, n_parallel)),
                                ]
                            ),
                            *_before,
                        ]
                    self._moe_spill_batch_tokens = (_raised, _before)

                server_caps = _launch_caps(binary)

                # Before extras so a hand-typed flag wins; gated since older builds exit on unknown flags.
                if ctx_checkpoints is not None:
                    _ctxcp_flag = server_caps.get("ctx_checkpoints_flag")
                    if _ctxcp_flag:
                        cmd.extend([str(_ctxcp_flag), str(int(ctx_checkpoints))])
                    else:
                        logger.info(
                            "llama-server has no --ctx-checkpoints; skipping the requested %s.",
                            ctx_checkpoints,
                        )
                if cache_ram is not None:
                    if server_caps.get("supports_cache_ram"):
                        cmd.extend(["--cache-ram", str(int(cache_ram))])
                    else:
                        logger.info(
                            "llama-server has no --cache-ram; skipping the requested %s MiB.",
                            cache_ram,
                        )
                # Read early so the effective budget can fold in an inherited
                # LLAMA_ARG_THINK_BUDGET*; the launch env is rebuilt below before spawn.
                env = self._llama_server_env_for_binary(binary)
                # On every launch, not only where Studio emits --mmproj: a projector
                # from the extras or LLAMA_ARG_MMPROJ takes video too.
                cmd.extend(_video_fps_flags(server_caps, extra_args = extra_args))

                # Report the public model id, not the raw -m path.
                from core.inference.model_ids import public_model_id

                _alias = public_model_id(self._model_identifier or model_path)
                if _alias:
                    cmd.extend(["--alias", _alias])

                fully_gpu_offloaded = False
                # Set when a positional --tensor-split is emitted, so the env block
                # can pin CUDA to PCI order even without a GPU subset (see below).
                manual_tensor_split_emitted = False
                # The MoE cache's "auto" sizing runs only under llama.cpp's fitter.
                _placed_by_fitter = False
                if gpu_memory_mode == "manual" and gpu_layers >= 0:
                    # --fit off: _ctx_integrity_flags must not add --fit-ctx.
                    use_fit = False
                    cmd.extend(["--gpu-layers", str(gpu_layers), "--fit", "off"])
                    # Keep the first n_cpu_moe MoE layers' experts on CPU.
                    moe_flag = self._resolve_cpu_moe_flag(
                        n_cpu_moe,
                        self.n_moe_layers,
                        self._leading_dense_block_count or 0,
                    )
                    if moe_flag is not None:
                        cmd.extend(["--n-cpu-moe", str(moe_flag)])
                    elif n_cpu_moe:
                        # Requested on a dense model: nothing was emitted, so
                        # don't report a count llama-server never received.
                        self._n_cpu_moe = 0
                    # Emit only with >1 GPU and a matching length: llama.cpp zero-pads short lists silently.
                    _split_gpus = self._effective_gpu_count(gpu_indices)
                    if tensor_split and _split_gpus > 1:
                        # An all-zero/non-positive sanitized split assigns nothing
                        # anywhere, so fall through to the free-VRAM default in
                        # that case.
                        _sanitized_split = self._sanitize_tensor_split(tensor_split)
                        _split_total = sum(_sanitized_split)
                        if len(_sanitized_split) == _split_gpus and _split_total > 0:
                            cmd.extend(
                                ["--tensor-split", ",".join(f"{x:g}" for x in _sanitized_split)]
                            )
                            self._tensor_split = _sanitized_split
                            manual_tensor_split_emitted = True
                        else:
                            logger.warning(
                                "Dropping manual --tensor-split (%d entries for "
                                "%d GPUs, sanitized total %s); llama.cpp's "
                                "free-VRAM split applies instead",
                                len(tensor_split),
                                _split_gpus,
                                _split_total,
                            )
                            self._tensor_split = None
                    elif tensor_split:
                        # Single effective GPU: the split is never emitted, so
                        # don't report it as active via /status and /load.
                        self._tensor_split = None
                elif use_fit and _metal_full_offload_pinned:
                    # Keep the launch on the full-offload mapping the discount measured.
                    cmd.extend(["-ngl", "-1", "--fit", "off"])
                    # -1 is the llama.cpp default, so the --fit on retry does not abort on a user-set -ngl; the retry is gated on fully_gpu_offloaded, so set it
                    fully_gpu_offloaded = True
                elif use_fit:
                    # Spill weight tensors, not whole layers: a spilled layer takes its KV cache with it.
                    _spill = self._planned_tensor_spill(
                        _spill_inputs,
                        extra_args = extra_args,
                        env = os.environ,
                    )
                    # Do not test the spill plan for truthiness: Plan is a dataclass and always truthy, even when it could not place anything
                    _spill_flags = self._spill_plan_flags_for(_spill)
                    if _spill_flags:
                        self._spill_plan_flags = _spill_flags
                        cmd.extend(self._spill_plan_flags)
                        logger.info(
                            "Tensor spill: %s (resident %.1f GB, host %.1f GB)",
                            " ".join(_spill.ot_patterns),
                            _spill.vram_bytes / (1024**3),
                            _spill.host_bytes / (1024**3),
                        )
                    else:
                        cmd.extend(["--fit", "on"])
                        _placed_by_fitter = True
                elif gpu_indices is not None:
                    # --fit off required: otherwise --fit on still offloads ~1 GB at --parallel 4.
                    cmd.extend(["-ngl", "-1", "--fit", "off"])
                    fully_gpu_offloaded = True
                    _mixed_split = self._mixed_pin_split(
                        list(gpu_indices),
                        _spill_inputs,
                        _shared_gpu_ids,
                        extra_args,
                        env,
                        layer_min_gpus = _layer_min_gpus,
                        tensor_parallel = tensor_parallel,
                        pin_owns_devices = _gpu_ids_own_device_flags,
                    )
                    if _mixed_split is not None:
                        self._mixed_split_flags = [
                            "--tensor-split",
                            self._format_tensor_split(_mixed_split),
                        ]
                        cmd.extend(self._mixed_split_flags)
                        if gpu_memory_mode != "manual":
                            self._auto_tensor_split_emitted = self._auto_split_fingerprint(
                                _mixed_split
                            )
                        logger.info(
                            "Filling discrete GPU(s) before the shared-memory iGPU: "
                            "--tensor-split %s over %s",
                            cmd[-1],
                            list(gpu_indices),
                        )

                # Expose Prometheus /metrics for the engine-stats logger, only
                # when the binary advertises it (older/custom binaries may not).
                if server_caps.get("supports_metrics"):
                    if not _extra_args_set_any_flag(extra_args, {"--metrics", "--no-metrics"}):
                        cmd.append("--metrics")
                self._slot_save_dir = None
                self._slot_save_binary = None
                self._prompt_cache_disabled = False
                if server_caps.get("supports_slot_save"):
                    try:
                        from utils.paths.storage_roots import (  # noqa: WPS433
                            llama_slot_cache_root,
                        )

                        slot_dir = llama_slot_cache_root()
                        slot_dir.mkdir(parents = True, exist_ok = True)
                        # Saved KV encodes chat content; keep it from other local users.
                        with contextlib.suppress(OSError):
                            os.chmod(slot_dir, 0o700)
                        slot_path = str(slot_dir)
                        # llama.cpp rejects non-ASCII paths on Windows; skip optional slot persistence until the managed runtime carries the upstream UTF-8 fix
                        if sys.platform == "win32" and not slot_path.isascii():
                            logger.warning(
                                "Disabling llama.cpp slot persistence because its "
                                "Windows path contains non-ASCII characters: %s",
                                slot_path,
                            )
                        else:
                            cmd.extend(["--slot-save-path", slot_path])
                            self._slot_save_dir = slot_path
                            self._slot_save_binary = (binary, Path(binary).stat().st_mtime_ns)
                    except OSError:
                        self._slot_save_dir = None
                        self._slot_save_binary = None
                _integrity_args = (
                    n_parallel,
                    use_fit,
                    auto_fit,
                    requested_ctx,
                    effective_ctx,
                    server_caps,
                )
                _integrity_flags = self._ctx_integrity_flags(
                    *_integrity_args,
                    fit_target_delta_mib = _fit_target_delta_mib,
                )
                # From the flags, not the inputs: --fit off, an older server without
                # the capability and a budget at the default all leave the child
                # unpriced, and each is decided inside that call.
                _fit_target_priced = "--fit-target" in _integrity_flags
                # Spelled per device at spawn, against the child's final mask.
                _fit_target_margins_by_idx = (
                    self._fit_target_margins_mib(
                        auto_fit = auto_fit,
                        fit_target_delta_by_idx = _fit_target_delta_by_idx,
                        supports_fit_target = bool(server_caps.get("supports_fit_target")),
                    )
                    if _fit_target_priced and use_fit and not _metal_fit_target_floor_mib
                    else None
                )
                if _metal_fit_target_floor_mib or _sidecar_fit_reserve_mib:
                    # Rebuilt after the price is read: the floor is the machine's
                    # margin and the sidecar reserve the drafter's, not the budget
                    # slider's.
                    _integrity_flags = self._ctx_integrity_flags(
                        *_integrity_args,
                        fit_target_delta_mib = _fit_target_delta_mib,
                        fit_target_floor_mib = _metal_fit_target_floor_mib,
                        # The reserve rides on the spawn's trailing pair, which retry cleanup must
                        # tell apart from a user's value.
                        fit_target_reserve_mib = 0,
                    )
                    if _sidecar_fit_reserve_mib and not server_caps.get("supports_fit_target"):
                        _sidecar_fit_reserve_mib = 0
                cmd.extend(_integrity_flags)
                offload_overridden = _extra_args_set_any_flag(
                    extra_args, _GPU_OFFLOAD_OVERRIDE_FLAGS
                )
                threads_overridden = _extra_args_set_any_flag(extra_args, _THREAD_OVERRIDE_FLAGS)
                full_offload_tuning_active = fully_gpu_offloaded and not offload_overridden
                # The CPU replay must undo what this launch pins for an absent GPU;
                # a user's own --threads still wins.
                _drop_full_offload_threads = (
                    sys.platform == "win32"
                    and full_offload_tuning_active
                    and not threads_overridden
                )

                # Omit --threads when unset: -1 means all hyperthreads, which slows decode.
                if (
                    sys.platform == "win32"
                    and full_offload_tuning_active
                    and not threads_overridden
                ):
                    cmd.extend(["--threads", "2"])
                elif n_threads is not None and n_threads > 0:
                    cmd.extend(["--threads", str(n_threads)])

                # Enable Jinja chat template rendering
                if _caps.get("supports_jinja", True):
                    if not _extra_args_set_any_flag(extra_args, {"--jinja", "--no-jinja"}):
                        cmd.extend(["--jinja"])
                cmd.extend(_trace_verbosity_args(_caps, extra_args, os.environ))

                # KV cache data type
                _valid_cache_types = _VALID_CACHE_TYPES
                # Normalize case like the budget does: a case-sensitive match drops Q8_0 with no flag, so llama.cpp runs f16 while the estimate priced q8_0
                cache_type_kv = cache_type_kv.strip().lower() if cache_type_kv else cache_type_kv
                if (
                    cache_type_kv
                    and cache_type_kv in _valid_cache_types
                    and not _cache_type_from_env
                ):
                    gpu_fallback_warning = (
                        None
                        if intent.cpu_fallback
                        or _arch_gate_forced_cpu
                        or not _detected_gpus
                        or _extras_cache is not None
                        else _kv_cache_gpu_fallback_warning(
                            cache_type_kv,
                            gpu_memory_mode,
                            gpu_layers,
                            lambda: self._installed_ggml_backends(binary),
                        )
                    )
                    if gpu_fallback_warning:
                        logger.warning(gpu_fallback_warning)
                        cache_type_kv = _GPU_UNACCELERATED_CACHE_TYPES[cache_type_kv]
                    if not _extra_args_set_any_flag(extra_args, _CACHE_TYPE_K_FLAGS):
                        cmd.extend(["--cache-type-k", cache_type_kv])
                    if not _extra_args_set_any_flag(extra_args, _CACHE_TYPE_V_FLAGS):
                        cmd.extend(["--cache-type-v", cache_type_kv])
                    self._cache_type_kv = cache_type_kv
                    logger.info(f"KV cache type: {cache_type_kv}")
                else:
                    # An env-only type is left inherited (untouched) so an
                    # asymmetric K/V env reaches the child as set.
                    self._cache_type_kv = None

                # Single-GPU tensor mode is redundant; unsupported archs abort and /load retries layer split.
                if tensor_parallel:
                    cmd.extend(["--split-mode", "tensor"])
                    _emitted_tensor_split: Optional[str] = None
                    if tp_tensor_split and len(tp_tensor_split) > 1:
                        _emitted_tensor_split = ",".join(str(int(x)) for x in tp_tensor_split)
                    elif (
                        gpu_memory_mode != "manual" and tensor_split and _tp_planned and gpu_indices
                    ):
                        # Fall back to the user ratio only if the planner emitted nothing and it fits budget; gate on _tp_planned, not tp_tensor_split, to avoid a KeyError
                        _split_gpus = self._effective_gpu_count(gpu_indices)
                        _sanitized_split = self._sanitize_tensor_split(tensor_split)
                        if (
                            len(_sanitized_split) == _split_gpus
                            and sum(_sanitized_split) > 0
                            and self._tensor_split_fits_budget(
                                _sanitized_split,
                                tp_gpus,
                                gpu_indices,
                                max(1, model_size - _host_input_embd),
                                effective_ctx,
                                cache_type_kv = cache_type_kv,
                                n_parallel = n_parallel,
                                n_ubatch = _effective_ubatch,
                                kv_unified = planned_kv_unified,
                                flash_attn = planned_flash_attn,
                                swa_full = swa_full,
                                mtp_engaged = _mtp_reserves_gpu,
                                mtp_overhead_fn = mtp_overhead_fn,
                                mtp_flat_reserve_bytes = (
                                    2 * 1024**3 if (_mtp_reserves_gpu and _mtp_kv_unsized) else 0
                                ),
                                total_by_idx = total_by_idx,
                                vram_fraction = _vram_frac,
                                # The planner's own operands, so "the same budget"
                                # in the docstring is true. Both are bound by the
                                # time _tp_planned is set.
                                soft_overhead_bytes = _soft_overhead,
                                scratch_cache_type_kv = _scratch_cache_type_kv,
                            )
                        ):
                            _emitted_tensor_split = self._format_tensor_split(_sanitized_split)
                    _emitted_values: Optional[list[float]] = None
                    if _emitted_tensor_split is not None:
                        cmd.extend(["--tensor-split", _emitted_tensor_split])
                        _emitted_values = [float(x) for x in _emitted_tensor_split.split(",")]
                    self._tensor_parallel = True
                    self._layer_preserves_tensor_intent = False
                    # Record the requested ratio, not the emitted one, so identical repeats are reused.
                    if gpu_memory_mode != "manual":
                        self._auto_tensor_split = self._auto_split_fingerprint(tensor_split)
                        self._auto_tensor_split_emitted = self._auto_split_fingerprint(
                            _emitted_values
                        )
                    logger.info(
                        "Tensor parallelism: --split-mode tensor, --tensor-split %s",
                        _emitted_tensor_split,
                    )
                else:
                    self._tensor_parallel = False
                    # > 1 only when a tensor request was downgraded but kept multi-GPU.
                    self._layer_preserves_tensor_intent = _layer_min_gpus > 1

                # Speculative decoding. See _build_speculative_flags for the
                # mode resolution, benchmarks, and llama.cpp references.
                _vulkan_pin_ids = gpu_indices if gpu_indices is not None else (gpu_ids or None)
                _draft_device = (
                    _extra_args_main_device(extra_args) if not _gpu_ids_own_device_flags else None
                )
                if _draft_device is None and is_vulkan_backend and _vulkan_pin_ids:
                    _draft_device = ",".join(f"Vulkan{i}" for i in _vulkan_pin_ids)
                launch_mtp_draft_path = self._resolve_launch_mtp_path(
                    mtp_draft_path = mtp_draft_path,
                    drafter_label = _DRAFTER_DISPLAY_LABELS.get(_spec_canon, "MTP"),
                )
                _suppressed_draft_path: Optional[str] = _unloadable_mtp_draft_path
                _suppressed_draft_reason: Optional[str] = (
                    "unloadable" if _unloadable_mtp_draft_path else None
                )
                _pv_suppressed_spec_extra_args: Optional[List[str]] = None
                # Drop an unpinnable drafter on virtualised Metal (throughput only, never correctness); a drafter-dependent --spec-type would abort the server, so drop it too
                _pv_draft_unpinnable = bool(
                    _paravirtual_cpu_forced
                    and not _paravirtual_draft_ngl_flag(server_caps)
                    and (
                        _extra_args_mtp_draft_path(extra_args, env = _child_spec_env(extra_args))
                        or (launch_mtp_draft_path and not _extra_args_set_spec_type(extra_args))
                    )
                    and not _extra_args_draft_offloaded_to_cpu(extra_args)
                )
                if _pv_draft_unpinnable:
                    logger.warning(
                        "Dropping the speculative drafter for this session: this "
                        "Mac's Metal device is virtualised and this llama-server "
                        "build advertises no draft-layer flag, so the drafter would "
                        "keep running on the device whose output is corrupt. Output "
                        "stays correct either way; this only costs speed. Run "
                        "'unsloth studio update' to install a build that supports it."
                    )
                    # Remember the suppressed drafter, else every repeat Apply reloads; record only what this drop removed, since None would clear an earlier drop record
                    if launch_mtp_draft_path:
                        _suppressed_draft_path = launch_mtp_draft_path
                        # A property of the build, not the file, so a repair must not reload.
                        _suppressed_draft_reason = "paravirtual"
                    launch_mtp_draft_path = None
                    if extra_args:
                        # Record extras as requested, or repeat Applies never match and reload.
                        _pv_suppressed_spec_extra_args = list(extra_args)
                        extra_args = strip_shadowing_flags(
                            extra_args,
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                # Classify using the same argv/env views as the launch so they cannot drift.
                _spec_placement_env = dict(os.environ)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(_spec_placement_env)
                _spec_placement_extras = extra_args
                if _gpu_ids_own_device_flags:
                    _spec_placement_extras = self._strip_device_extra_args(extra_args)
                    self._clear_device_placement_env(_spec_placement_env)
                _spec_placement_argv = [*cmd, *(_spec_placement_extras or [])]
                # A device the launch really carries, and not the CPU spelling of it.
                # Only consulted where the probe found nothing: it is the one remaining
                # way the child can still be pointed at a GPU.
                _spec_device_pick = _extra_args_main_device(
                    _spec_placement_argv
                ) or _spec_placement_env.get("LLAMA_ARG_DEVICE")
                _spec_extras_pick_a_gpu = bool(_spec_device_pick) and not _device_selection_is_cpu(
                    _spec_placement_argv, _spec_placement_env
                )
                # Log-only; a priced reserve is reported by the spawn (_log_sidecar_fit_reserve).
                _sidecar_fit_sized = (
                    not fit_is_effectively_on(_spec_placement_argv, _spec_placement_env)
                    or bool(_sidecar_fit_reserve_eligible_mib)
                    or bool(server_caps.get("fit_measures_borrowed_drafts"))
                    or (
                        bool(launch_mtp_draft_path)
                        and not _sidecar_borrows_target_tensors(launch_mtp_draft_path)
                    )
                )
                spec_flags = self._build_speculative_flags(
                    speculative_type = speculative_type,
                    spec_draft_n_max = spec_draft_n_max,
                    extra_args = extra_args,
                    model_identifier = model_identifier,
                    model_path = model_path,
                    gpus = bool(_detected_gpus),
                    binary = binary,
                    mtp_draft_path = (
                        None if _spec_canon in ("dspark", "dflash") else launch_mtp_draft_path
                    ),
                    dspark_draft_path = (launch_mtp_draft_path if _spec_canon == "dspark" else None),
                    dspark_fit_sized = _sidecar_fit_sized,
                    dflash_draft_path = (launch_mtp_draft_path if _spec_canon == "dflash" else None),
                    dflash_fit_sized = _sidecar_fit_sized,
                    # So the fallback says unopenable, not missing. DSpark/DFlash never
                    # reach the drop.
                    mtp_drafter_unloadable = bool(_unloadable_mtp_draft_path),
                    drafter_no_vram = _spec_dropped_no_vram,
                    embedded_mtp_partial_offload = bool(
                        _spec_canon == "auto"
                        and self._nextn_predict_layers
                        and self._ssm_inner_size is not None
                        and self._full_attention_interval is not None
                        and not launch_mtp_draft_path
                        and not _extra_args_set_spec_type(extra_args)
                        # Only when no GPU is offloaded to: an explicit pick or a device in extras counts even if the probe missed it; CPU-only and Metal also emit --fit on
                        and (_detected_gpus or gpu_indices or _spec_extras_pick_a_gpu)
                        and self._partially_offloads_layers(
                            [*cmd, *(_spec_placement_extras or [])],
                            _spec_placement_env,
                            # Manual --fit on is a default, not evidence of a failed fit; only Auto fitter that ran and failed counts, not an empty VRAM probe with a hand-pinned device
                            fit_implies_partial = (
                                gpu_memory_mode != "manual" and _placement_verdict_partial
                            ),
                        )
                    ),
                    draft_device = _draft_device,
                )
                # Restore the requested spec view, or the spec-mode compare never matches.
                if _extra_args_set_spec_type(_pv_suppressed_spec_extra_args):
                    self._requested_spec_mode = None
                # Draft KV dtype applies only with --model-draft, judged on flags actually built, not the requested mode; unknown values are dropped since llama-server exits
                _draft_cache_type = (
                    spec_draft_cache_type.strip().lower() if spec_draft_cache_type else None
                )
                if _draft_cache_type and _draft_cache_type not in _VALID_KV_CACHE_TYPES:
                    logger.warning(
                        "Ignoring unsupported draft KV cache type %r", spec_draft_cache_type
                    )
                    _draft_cache_type = None
                if _draft_cache_type and any(
                    _flag_name(tok) in _LOCAL_DRAFT_FLAGS for tok in spec_flags
                ):
                    _draft_k_flag = server_caps.get("spec_draft_cache_k_flag")
                    _draft_v_flag = server_caps.get("spec_draft_cache_v_flag")
                    if _draft_k_flag and _draft_v_flag:
                        # llama.cpp refuses K != V on an MLA draft context.
                        spec_flags.extend(
                            [
                                str(_draft_k_flag),
                                _draft_cache_type,
                                str(_draft_v_flag),
                                _draft_cache_type,
                            ]
                        )
                        logger.info("Draft KV cache dtype: %s", _draft_cache_type)
                    else:
                        logger.info(
                            "llama-server has no draft KV cache flags; skipping the requested %s.",
                            _draft_cache_type,
                        )
                _no_backend_draft = _draft_backend_sampling_off(
                    spec_flags, server_caps, self._vocab_size, self._is_vulkan_backend(binary)
                )
                if _no_backend_draft:
                    logger.info(
                        "Vulkan: sampling drafts on the CPU, the %s-token vocab misaligns "
                        "the logits rows the backend sampler reads.",
                        self._vocab_size or "unknown",
                    )
                    spec_flags.extend(_no_backend_draft)
                # Remember where the spec block sits so a drafter-load failure
                # can be retried with these flags swapped out (see below).
                _spec_start = len(cmd)
                cmd.extend(spec_flags)

                # Separate drafter ignores main --gpu-layers (draft default -1 is auto), so pin it; emit after the pass-through extras, since the parser is last-wins
                _pv_draft_cpu_pin: List[str] = []
                _pv_mmproj_cpu_pin: List[str] = []
                _pv_split_mode_pin: List[str] = []
                # --gpu-layers 0 is not enough: op_offload still sends ops to Metal; --device none drops it.
                _pv_device_pin: List[str] = ["--device", "none"] if _paravirtual_cpu_forced else []
                if (
                    _paravirtual_cpu_forced
                    # preserve_thinking is independent of the thinking gate; Qwen3.8 defaults on, other families off.
                    and _extra_args_mtp_draft_path(
                        [*spec_flags, *(extra_args or [])], env = _child_spec_env(extra_args)
                    )
                    is not None
                    and _paravirtual_draft_ngl_flag(server_caps)
                ):
                    # The draft context has its own device list, so main --device none does not reach it.
                    _pv_draft_cpu_pin = [
                        str(_paravirtual_draft_ngl_flag(server_caps)),
                        "0",
                        "--device-draft",
                        "none",
                    ]
                    logger.warning(
                        "Pinning the speculative drafter to CPU: this Mac's Metal "
                        "device is virtualised."
                    )

                # Emitted after the pass-through extras too, same last-wins reason.
                if _paravirtual_cpu_forced:
                    _pv_split_mode_pin = _paravirtual_split_mode_pin(extra_args)

                self._chat_template_override = chat_template_override
                self._empty_chat_render_refused = False
                _effective_template = self._effective_chat_template(chat_template_override)
                if _effective_template:
                    import tempfile

                    flags = detect_reasoning_flags(
                        _effective_template,
                        self._model_identifier,
                        log_source = (
                            "GGUF chat template override"
                            if chat_template_override
                            else "repaired GGUF chat template"
                        ),
                    )
                    self._supports_reasoning = flags["supports_reasoning"]
                    self._reasoning_style = flags["reasoning_style"]
                    self._reasoning_effort_levels = flags.get("reasoning_effort_levels", [])
                    self._reasoning_always_on = flags["reasoning_always_on"]
                    self._supports_preserve_thinking = flags["supports_preserve_thinking"]
                    self._preserve_thinking_default = flags["preserve_thinking_default"]
                    self._supports_tools = flags["supports_tools"]

                    self._chat_template_file = tempfile.NamedTemporaryFile(
                        mode = "w",
                        encoding = "utf-8",
                        suffix = ".jinja",
                        delete = False,
                        prefix = "unsloth_chat_template_",
                    )
                    self._chat_template_file.write(_effective_template)
                    self._chat_template_file.close()
                    cmd.extend(["--chat-template-file", self._chat_template_file.name])
                    logger.info(f"Using custom chat template file: {self._chat_template_file.name}")

                # Qwen3.5 Small tier (<=9B) defaults reasoning off, and the templates match so it is a launch flag; always-on templates ignore the kwarg, so skip them
                if self._supports_reasoning and not self._reasoning_always_on:
                    thinking_default = True
                    mid = (model_identifier or "").lower()
                    if "qwen3.5" in mid or "qwen3.6" in mid:
                        # Match total params (35B-A3B is 35B), not the active count; scan segments right to left so the leaf size beats a size-like parent dir
                        size_re = r"(?:^|[-_.])(\d+\.?\d*)\s*([bm])(?:$|[-_.])"
                        size_match = None
                        for seg in reversed(mid.replace("\\", "/").split("/")):
                            size_match = re.search(size_re, seg)
                            if size_match:
                                break
                        if size_match:
                            size_b = float(size_match.group(1))
                            if size_match.group(2) == "m":
                                size_b /= 1000.0
                            # <= 9, not < 9: 9B is the top of the Small tier, so it is off too.
                            if size_b <= 9:
                                thinking_default = False
                    # argv beats the env `unsloth start` pins these through, so repeat it.
                    _env_reasoning = _reasoning_from_env(env)
                    if _env_reasoning is not None:
                        thinking_default = _env_reasoning
                    reasoning_kw = self._reasoning_kwargs(
                        thinking_default, _reasoning_effort_from_env(env)
                    )
                    # An effort ladder thinks at every level but "none" (Inkling: 0), low included.
                    self._reasoning_default = reasoning_kw.get(
                        "enable_thinking", reasoning_kw.get("reasoning_effort") not in ("none", 0)
                    )
                    # preserve_thinking is independent of the thinking gate.
                    # Qwen3.8 defaults it on; Qwen3.6, Gemma 4, and every other
                    # supporting family keep the existing off default. The
                    # frontend receives the same resolved value via load/status.
                    # An override takes the default its own text renders, and an explicit
                    # --[no-]reasoning-preserve beats both: llama.cpp applies this kwarg
                    # after that flag, so it would otherwise undo it (#15115).
                    if self._supports_preserve_thinking:
                        if chat_template_override:
                            self._preserve_thinking_default = (
                                _template_preserves_thinking_by_default(
                                    chat_template_override, reasoning_kw
                                )
                            )
                        _preserve = _reasoning_preserve_from_args_or_env(extra_args, env)
                        if _preserve is not None:
                            self._preserve_thinking_default = _preserve
                        reasoning_kw["preserve_thinking"] = self._preserve_thinking_default
                    _reasoning_args = _build_launch_reasoning_args(server_caps, reasoning_kw)
                    cmd.extend(_reasoning_args)
                    logger.info(
                        f"Reasoning model: {reasoning_kw} by default "
                        f"(launched as {' '.join(_reasoning_args)})"
                    )

                reasoning_budget = resolve_reasoning_budget(extra_args, reasoning_budget)
                reasoning_budget_message = resolve_reasoning_budget_message(
                    extra_args, reasoning_budget_message
                )
                cmd.extend(
                    _build_reasoning_budget_flags(
                        server_caps, reasoning_budget, reasoning_budget_message
                    )
                )
                # Check extra_args and env, not the later policy list; only explicit gpu_ids clears LLAMA_ARG_DEVICE.
                self._requested_reasoning_budget = reasoning_budget
                self._requested_reasoning_budget_message = reasoning_budget_message
                # Only a conclusive missing flag means the child ignores LLAMA_ARG_THINK_BUDGET*.
                _budget_env_applies = server_caps.get(
                    "supports_reasoning_budget"
                ) or server_caps.get("reasoning_budget_probe_inconclusive")
                reasoning_budget = (
                    resolve_reasoning_budget_with_env(extra_args, reasoning_budget, env)
                    if _budget_env_applies
                    else reasoning_budget
                )
                reasoning_budget_message = (
                    resolve_reasoning_budget_message_with_env(
                        extra_args, reasoning_budget_message, env
                    )
                    if server_caps.get("supports_reasoning_budget_message")
                    or server_caps.get("reasoning_budget_probe_inconclusive")
                    else reasoning_budget_message
                )
                self._reasoning_budget = reasoning_budget
                self._reasoning_budget_message = reasoning_budget_message

                if launch_mmproj_path and effective_is_vision:
                    cmd.extend(["--mmproj", launch_mmproj_path])
                    logger.info(f"Using mmproj for vision: {launch_mmproj_path}")
                    # The projector ignores --gpu-layers, so pin it to CPU; last flag wins, so emit
                    # after extras.
                    if _mmproj_cpu_pinned:
                        _pv_mmproj_cpu_pin = ["--no-mmproj-offload"]
                        if _paravirtual_cpu_forced:
                            logger.warning(
                                "Disabling mmproj GPU offload: this Mac's Metal "
                                "device is virtualised."
                            )

                # llama-server sends permissive CORS, so without a key any open web page could drive it.
                import secrets as _secrets

                _key_on = _llama_server_api_key_enabled()
                if _key_on and not server_caps.get("supports_api_key_file", True):
                    # A custom build predating --api-key-file would exit on the flag; run it keyless as before.
                    logger.warning(
                        "This llama-server build has no --api-key-file; starting it without an API key."
                    )
                    _key_on = False
                _key_env: dict[str, str] = {}
                if _key_on:
                    self._api_key = _secrets.token_urlsafe(32)
                    # Through a file or the child env, not argv: a command line is readable by every process of this Unix user, and the auth directory is not.
                    _key_argv, _key_env, self._api_key_file = _llama_server_key_launch(
                        self._api_key, self._api_key_file
                    )
                    cmd.extend(_key_argv)
                else:
                    self._api_key = None

                # Windows discrete full offload: drop host-RAM KV checkpoints but keep prompt cache; not on iGPUs, where --cache-ram 0 also drops --cache-idle-slots
                _cache_flags_emitted: list[str] = []
                # llama.cpp reads env before argv, so an appended 0 would override the operator's value.
                _ctx_checkpoints_owned = (
                    ctx_checkpoints
                    if ctx_checkpoints is not None
                    else _env_ctx_checkpoints_override()
                )
                # extra_args, not the memory policy's list: that one is built later, and
                # a gpu_ids pin is the case _strip_device_extra_args removes the flag in.
                # The env twin counts too: only an explicit gpu_ids clears
                # LLAMA_ARG_DEVICE, and llama.cpp reads it before argv, so an automatic
                # load can place against a target the generated pin never names.
                _cache_target_unknown = self._cache_tuning_target_unknown(
                    extra_args, _gpu_ids_own_device_flags, os.environ
                )
                _shared_memory_offload = (
                    sys.platform == "win32"
                    and full_offload_tuning_active
                    and (
                        _cache_target_unknown
                        or self._offload_target_shares_system_memory(
                            is_vulkan_backend = is_vulkan_backend,
                            shared_gpu_ids = _shared_gpu_ids,
                            detected_gpus = _detected_gpus,
                            gpu_indices = gpu_indices,
                        )
                    )
                )
                if _cache_target_unknown and sys.platform == "win32" and full_offload_tuning_active:
                    logger.info(
                        "Keeping the llama-server prompt cache: a user --device in the extra "
                        "arguments overrides the automatic placement, so the offload target "
                        "this tuning would be chosen against is not the one the child gets."
                    )
                elif _shared_memory_offload:
                    logger.info(
                        "Keeping the llama-server prompt cache: this load offloads to a GPU "
                        "that shares system memory, so --cache-ram 0 and --ctx-checkpoints 0 "
                        "would remove prefix reuse without saving a transfer."
                    )
                elif sys.platform == "win32" and full_offload_tuning_active:
                    unsupported_cache_flags: list[str] = []
                    # An explicit control wins over platform tuning (llama.cpp is last-wins).
                    if cache_ram is not None:
                        pass
                    elif server_caps.get("supports_cache_ram"):
                        _cache_flags_emitted.extend(["--cache-ram", "0"])
                    else:
                        unsupported_cache_flags.append("--cache-ram")
                    if _ctx_checkpoints_owned is not None:
                        pass
                    elif server_caps.get("ctx_checkpoints_flag"):
                        _cache_flags_emitted.extend([str(server_caps["ctx_checkpoints_flag"]), "0"])
                    else:
                        unsupported_cache_flags.append("--ctx-checkpoints")
                    cmd.extend(_cache_flags_emitted)
                    if unsupported_cache_flags:
                        logger.info(
                            "Skipping unsupported Windows cache flags for llama-server: %s",
                            ", ".join(unsupported_cache_flags),
                        )

                def _decide_auto_ctx_checkpoints() -> Optional[int]:
                    """The cap for the slots n_parallel currently names, or None to stand down."""
                    return (
                        self._bounded_ctx_checkpoints(
                            n_parallel,
                            server_caps,
                            extra_args,
                            cache_type_kv = cache_type_kv,
                            swa_full = swa_full,
                            flash_attn = planned_flash_attn,
                        )
                        if ctx_checkpoints is None
                        else None
                    )

                _auto_ctx_checkpoints = _decide_auto_ctx_checkpoints()
                # Tracked apart from _cache_flags_emitted, which means "the Windows tuning
                # ran", so the arch-crash respawn can re-decide each one on its own.
                _auto_ckpt_emitted: list[str] = []

                def _emit_auto_ctx_checkpoints(command: list[str]) -> list[str]:
                    """Append the automatic cap unless the Windows tuning already zeroed it."""
                    if _auto_ctx_checkpoints is None:
                        return []
                    if any(
                        _flag_name(str(token)) in _CTX_CHECKPOINTS_FLAGS
                        for token in _cache_flags_emitted
                    ):
                        return []
                    pair = [
                        str(server_caps["ctx_checkpoints_flag"]),
                        str(_auto_ctx_checkpoints),
                    ]
                    command.extend(pair)
                    return pair

                _auto_ckpt_emitted = _emit_auto_ctx_checkpoints(cmd)

                # Record the effective pin so /status never echoes an ordinal the child never saw.
                if _paravirtual_cpu_forced:
                    # --device none pins nothing, so record no effective pin here either.
                    # Ahead of the backend branches: this is the authoritative record and
                    # would otherwise re-echo the device the child never saw.
                    self._gpu_ids = None
                elif is_vulkan_backend:
                    # Only record an explicit Vulkan pin, mirroring CUDA/ROCm; recording an auto pick would make dedupe miss the loaded server
                    self._gpu_ids = (
                        [int(x) for x in _vulkan_pin_ids] if (gpu_ids and _vulkan_pin_ids) else None
                    )
                elif gpu_ids:
                    # Classify on the same stripped view the launch uses; a gpu_ids pin drops the device flags.
                    _effective_pin_ids = (
                        [int(x) for x in gpu_indices]
                        if gpu_indices is not None
                        else [int(x) for x in gpu_ids]
                    )
                    # Keep survivor order, not sorted, so /status round-trips the pin.
                    self._gpu_ids = (
                        [int(x) for x in _effective_pin_ids] if _effective_pin_ids else None
                    )
                else:
                    self._gpu_ids = None

                # Raw requested pin for load dedupe; /status echoes the effective one.
                self._requested_gpu_ids = [int(x) for x in gpu_ids] if gpu_ids else None

                if is_vulkan_backend and _vulkan_pin_ids is not None:
                    cmd += LlamaCppBackend._vulkan_pin_args(_vulkan_pin_ids)

                # Managed flag goes before extras; vetoed flags drop from a launch-only copy. mlock applies only where weights sit in host RAM; asked on every launch
                _mem_env = dict(os.environ)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(_mem_env)
                # A gpu_ids pin drops the device flags from argv and env below,
                # so classifying on them would pin for a --device cpu the child
                # never sees. Same helpers the launch uses, so they cannot drift.
                _mem_extra_args = extra_args
                if _gpu_ids_own_device_flags:
                    _mem_extra_args = self._strip_device_extra_args(extra_args)
                    self._clear_device_placement_env(_mem_env)
                _mem_keep_resident, _mem_no_reserve = _mem_settings
                _mem_should_mlock = _mem_keep_resident and not _mem_no_reserve
                # Armed here, not at load start: rows from before the Hub download are stale.
                _arm_load_probe_memo()
                _mem_dio_possible = no_reserve_requires_dio(
                    supports_load_mode = load_mode_support(server_caps),
                    gpu_offload_confirmed = True,
                )
                # NOT gated on the toggle: the answer is this launch's recorded placement
                # and a LATER save is compared against it, so gating made the record mean
                # "we did not look". Costs one subprocess, on Windows Vulkan builds only.
                _mem_probe_for_dio = _mem_dio_possible
                # Ordinals the child uses: a pass-through --device wins.
                _mem_physical_indices, _mem_compact_indices = self._effective_gpu_selection(
                    binary,
                    _mem_env,
                    gpu_indices,
                    _mem_extra_args,
                    _mem_dio_possible,
                    is_vulkan_backend,
                )
                _mem_host_resident = self._weights_in_host_memory(
                    fully_gpu_offloaded = fully_gpu_offloaded,
                    gpu_memory_mode = gpu_memory_mode,
                    gpu_layers = gpu_layers,
                    extra_args = _mem_extra_args,
                    gpu_indices = _mem_physical_indices,
                    is_vulkan_backend = is_vulkan_backend,
                    binary = binary,
                    env = _mem_env,
                    # Gate masks every device, so host RAM is used; a skipped page-lock is recorded as deliberate.
                    probe_vulkan = _mem_should_mlock or _mem_probe_for_dio,
                    # Over cmd and extras so a later user --fit wins by last-arg.
                    fit_active = fit_is_effectively_on([*cmd, *(_mem_extra_args or [])], _mem_env),
                )
                # Env as it would be under no-reserve, since the scrub follows the settings, not the live view.
                if _arch_gate_forced_cpu:
                    _mem_host_resident = True
                # Moved up: the managed DirectIO defers to an inherited mode and runs first.
                _fit_load_mode_env_view = dict(_mem_env)
                scrub_memory_env(_fit_load_mode_env_view, _mem_settings)
                # Must be positive: the predicate errs True when unprobed; dio is not gated on projector placement.
                _mem_env_view_no_reserve = dict(_mem_env)
                scrub_memory_env(_mem_env_view_no_reserve, (_mem_keep_resident, True))
                # Whether a relaunch would stream: placement alone is not enough, and a per-model mmap or extra wins.
                _mem_gpu_offload_confirmed = self._gpu_offload_confirmed(
                    binary,
                    _mem_env,
                    _mem_compact_indices,
                    _mem_host_resident,
                    _mem_dio_possible,
                    _mem_extra_args,
                )
                _mem_managed, _mem_extras = apply_model_memory_policy(
                    extra_args,
                    supports_load_mode = load_mode_support(server_caps),
                    weights_in_host_memory = _mem_host_resident,
                    gpu_offload_confirmed = _mem_gpu_offload_confirmed,
                    env = _fit_load_mode_env_view,
                    settings = _mem_settings,
                )
                # What the user wrote, so the strip can tell their pair from ours.
                self._memory_dio_user_tokens = list(_mem_extras or [])
                self._memory_dio_flags = (
                    list(_mem_managed) if tuple(_mem_managed) == MANAGED_DIO_FLAGS else []
                )
                # Defers to Model Memory and extras; an inherited LLAMA_ARG_LOAD_MODE is an explicit choice that would beat the managed block, so only the fit mode yields
                if (
                    _fit_load_mode
                    and not load_mode
                    and memory_env_selects_load_mode(_fit_load_mode_env_view)
                ):
                    logger.info(
                        "Load mode: the environment already selects a loader mode; "
                        "leaving the fit's --load-mode %s off this launch.",
                        _fit_load_mode,
                    )
                    _fit_load_mode = None
                # Retry rungs strip the first matching pair, so a user's duplicate pair must be detected.
                if _fit_load_mode and not load_mode and extra_args_select_load_mode(_mem_extras):
                    logger.info(
                        "Load mode: the extra arguments already select a loader mode; "
                        "leaving the fit's --load-mode %s off this launch.",
                        _fit_load_mode,
                    )
                    _fit_load_mode = None
                _resolved_load_mode = load_mode or _fit_load_mode
                _load_mode_managed, _mem_extras = apply_load_mode_policy(
                    _mem_extras,
                    supports_load_mode = load_mode_support(server_caps),
                    weights_in_host_memory = _mem_host_resident,
                    requested_load_mode = _resolved_load_mode,
                    settings = _mem_settings,
                )

                # Whether a relaunch under no-reserve would really stream. Placement alone
                # is not enough: a per-model mmap, an extra or an inherited choice lands
                # after the managed pair and wins by last-arg, so it demanded a reload no
                # relaunch could satisfy. Toggle-independent, so a LATER save is compared
                # against this launch instead of reading as satisfied.
                def _ask(pair, env_view):
                    return resolve_launch_load_mode(
                        extra_args,
                        supports_load_mode = load_mode_support(server_caps),
                        weights_in_host_memory = _mem_host_resident,
                        gpu_offload_confirmed = _mem_gpu_offload_confirmed,
                        requested_load_mode = _resolved_load_mode,
                        env = env_view,
                        settings = pair,
                    )

                # Would a relaunch ADD the pair. The POLICY emitting it is the question,
                # not the effective mode: a user's own "dio" already streams, and a reload
                # to reach the mode the child is in is a notice that never clears.
                _hypo_emitted, _hypo_effective = _ask(
                    (_mem_keep_resident, True), _mem_env_view_no_reserve
                )
                self._memory_dio_applicable = _hypo_emitted and _hypo_effective

                # The child with the policy off entirely, which is what activity asks.
                _off_view = dict(_mem_env)
                scrub_memory_env(_off_view, (False, False))

                def _mem_env_for(child_env):
                    """`_mem_env`'s placement scrubbing with the CHILD's current
                    visibility. `_mem_env` predates the gate, so probing with it reused
                    the unnarrowed set's verdict."""
                    if child_env is None:
                        return _mem_env
                    view = dict(_mem_env)
                    for _name in _DEVICE_VISIBILITY_ENV:
                        if _name in child_env:
                            view[_name] = child_env[_name]
                        else:
                            view.pop(_name, None)
                    return view

                def _dio_decision_for(
                    devices,
                    *,
                    fully_offloaded,
                    child_env = None,
                ):
                    """Returns (pair, applicable, active) for a changed device set, re-asking every launch question instead of a subset each."""
                    _rung_env = _mem_env_for(child_env)
                    _rung_physical, _rung_compact = self._effective_gpu_selection(
                        binary,
                        _rung_env,
                        devices,
                        _mem_extra_args,
                        _mem_dio_possible,
                        is_vulkan_backend,
                    )
                    host_resident = self._weights_in_host_memory(
                        fully_gpu_offloaded = fully_offloaded,
                        gpu_memory_mode = gpu_memory_mode,
                        gpu_layers = gpu_layers,
                        extra_args = _mem_extra_args,
                        gpu_indices = _rung_physical,
                        is_vulkan_backend = is_vulkan_backend,
                        binary = binary,
                        env = _rung_env,
                        probe_vulkan = _mem_probe_for_dio or _mem_should_mlock,
                        fit_active = fit_is_effectively_on(
                            [*cmd, *(_mem_extra_args or [])], _rung_env
                        ),
                    )
                    confirmed = self._gpu_offload_confirmed(
                        binary,
                        _rung_env,
                        _rung_compact,
                        host_resident,
                        _mem_dio_possible,
                        _mem_extra_args,
                    )

                    def _for(pair, env_view):
                        return resolve_launch_load_mode(
                            extra_args,
                            supports_load_mode = load_mode_support(server_caps),
                            weights_in_host_memory = host_resident,
                            gpu_offload_confirmed = confirmed,
                            requested_load_mode = _resolved_load_mode,
                            env = env_view,
                            settings = pair,
                        )

                    live_emitted, live_effective = _for(_mem_settings, _fit_load_mode_env_view)
                    hypo_emitted, hypo_effective = _for(
                        (_mem_keep_resident, True), _mem_env_view_no_reserve
                    )
                    pair = list(MANAGED_DIO_FLAGS) if (live_emitted and live_effective) else []
                    # Redundant with the user's own loader: nothing a relaunch could undo.
                    active = bool(pair) and live_effective != _for((False, False), _off_view)[1]
                    return pair, (hypo_emitted and hypo_effective), active

                # Only when FIT chose the load mode: a user's own pick survives every fallback, but a placement conclusion must go when the placement does
                self._fit_load_mode_flags = (
                    list(_load_mode_managed) if (_fit_load_mode and not load_mode) else []
                )
                # Remembered so the reload hint and the duplicate-load comparator do
                # not demand an mlock this launch deliberately skipped.
                # A probe forced for the DirectIO decision must not make the page-lock
                # bookkeeping LESS conservative: an unreadable Vulkan probe answers "not an
                # iGPU", which recorded the lock inapplicable on maybe-host-backed weights.
                self._memory_mlock_applicable = _mem_host_resident or (
                    _mem_probe_for_dio
                    and not _mem_should_mlock
                    and is_vulkan_backend
                    and not self._vulkan_probe_answered(binary)
                )
                # An unknown build gets no lock, so none is owed either.
                self._memory_mlock_applicable = keep_resident_lock_applicable(
                    self._memory_mlock_applicable, load_mode_support(server_caps)
                )
                if (
                    _mem_should_mlock
                    and _mem_host_resident
                    and load_mode_support(server_caps) is None
                ):
                    logger.info(
                        "Model Memory: skipping page-lock, the llama-server --help "
                        "probe was inconclusive and newer builds reject --mlock."
                    )
                if _mem_should_mlock and not _mem_host_resident:
                    logger.info(
                        "Model Memory: skipping page-lock, the weights are fully "
                        "offloaded to a discrete GPU; residency is kept by not "
                        "unloading the model."
                    )
                if _mem_managed:
                    cmd.extend(_mem_managed)
                    logger.info(
                        "Model Memory: applying loading policy (%s)",
                        " ".join(_mem_managed),
                    )
                if _load_mode_managed:
                    cmd.extend(_load_mode_managed)
                    # Protected like the extras: the per-model selection is the user's too,
                    # so a rung that stripped a COPY left it behind for the next strip.
                    self._memory_dio_user_tokens = [
                        *self._memory_dio_user_tokens,
                        *_load_mode_managed,
                    ]
                    logger.info("Load mode: %s", " ".join(_load_mode_managed))

                # Before the extras, so a user's own lazy mode wins by last-arg.
                self._lazy_mode_flags = list(_managed_lazy_flags or [])
                if self._lazy_mode_flags:
                    cmd.extend(self._lazy_mode_flags)
                    logger.info("Lookup tables: %s", " ".join(self._lazy_mode_flags))

                # A flag validate_extra_args refuses has an env twin llama.cpp reads before argv, so both must go.
                if _mem_extras:
                    _emit_extra_args = self._strip_mmproj_args(list(_mem_extras))
                    if _gpu_ids_own_device_flags:
                        # gpu_ids owns placement, so remove competing device flags.
                        _before_device_strip = list(_emit_extra_args)
                        _emit_extra_args = self._strip_device_extra_args(_emit_extra_args)
                        if _emit_extra_args != _before_device_strip:
                            logger.info(
                                "Dropped user device placement flags from extra args: "
                                "explicit gpu_ids owns placement."
                            )
                    _emit_extra_args = translate_ngram_mod_args(
                        _emit_extra_args,
                        _caps.get("ngram_mod_flavor"),
                        chain_with_mtp = self._speculative_type == "draft-mtp"
                        or _extra_args_requests_mtp(
                            _emit_extra_args, env = _child_spec_env(_emit_extra_args)
                        ),
                    )
                    cmd.extend(str(a) for a in _emit_extra_args)
                    logger.info(
                        f"Appending user extra args to llama-server: {list(_emit_extra_args)}"
                    )
                # Reconcile the reserve with the child as launched: extras can turn the fitter on or
                # add a margin.
                _sidecar_user_tokens = list(_emit_extra_args) if _mem_extras else []
                if (
                    _sidecar_fit_reserve_eligible_mib
                    and server_caps.get("supports_fit_target")
                    # Re-read: a failed GPU selection falls back to every card.
                    and (_apple_budget_mib > 0 or _sidecar_planned_device_count() == 1)
                ):
                    _sidecar_child_env = dict(os.environ)
                    if gpu_memory_mode == "manual":
                        self._clear_manual_placement_env(_sidecar_child_env)
                    _sidecar_override_flags = _sidecar_reserve_margin_flags(
                        cmd,
                        _emit_extra_args if _mem_extras else (),
                        _sidecar_child_env,
                        max(
                            _VRAM_FLOOR_RESERVE_MIB,
                            self._fit_target_margin_mib(
                                auto_fit = auto_fit,
                                fit_target_delta_mib = _fit_target_delta_mib,
                                floor_mib = _metal_fit_target_floor_mib,
                            ),
                        ),
                        _sidecar_fit_reserve_eligible_mib,
                    )
                    if _sidecar_override_flags:
                        _sidecar_fit_reserve_mib = _sidecar_fit_reserve_eligible_mib
                        _sidecar_override_pairs.append(list(_sidecar_override_flags))
                        cmd.extend(_sidecar_override_flags)
                # Last so it wins: the Metal drafter CPU pin is a correctness fix.
                if _pv_draft_cpu_pin:
                    cmd.extend(_pv_draft_cpu_pin)
                if _pv_mmproj_cpu_pin:
                    cmd.extend(_pv_mmproj_cpu_pin)
                # Last too: a remembered --mmproj-auto would rediscover the projector and restore vision on a text-only load; --no-mmproj-auto does not unload it.
                if disable_vision and not launch_mmproj_path and not _dv_env_mmproj_kept:
                    cmd.append("--no-mmproj-auto")
                # Must be in cmd before the env block reads _zero_offload_keeps_gpu_visible.
                if _pv_split_mode_pin:
                    cmd.extend(_pv_split_mode_pin)
                if _pv_device_pin:
                    cmd.extend(_pv_device_pin)
                # Pinned loads only: under mmap the cache measured slower than none.
                self._moe_cache_flags = []
                if (
                    _moe_cache_candidate
                    and _moe_cache_ram_ok
                    and _placed_by_fitter
                    and _argv_loads_pinned(cmd, _fit_load_mode_env_view)
                ):
                    self._moe_cache_flags = list(_MOE_CACHE_AUTO_TOKENS)
                    cmd.extend(self._moe_cache_flags)
                    logger.info(
                        "MoE experts spill to pinned system RAM on one GPU; adding "
                        "--moe-cache-mib auto so llama.cpp caches hot experts in VRAM."
                    )

                # Without --flash-attn a build cannot run a quantized V cache; reset V before the logged launch, keeping length so _spec_start still indexes the tokens.
                if _flash_attn_known_off:
                    cmd = self._reset_quantized_v_cache(
                        cmd,
                        "this build has no --flash-attn",
                        mla = self._target_kv_symmetry(),
                        # Use os.environ: the child env is not built until below (reading it here is an UnboundLocalError), and Unsloth never rewrites LLAMA_ARG_SPEC_DRAFT_MODEL.
                        draft_mla = self._draft_kv_symmetry(cmd),
                    )

                kv_cache_unified = _kv_unified_from_args(cmd)

                # Library paths so llama-server finds its shared libs and CUDA DLLs.
                env = self._llama_server_env_for_binary(binary)
                # The GGUF header controls pooling; ignore inherited defaults.
                for _pooling_var in (
                    "LLAMA_ARG_POOLING",
                    "LLAMA_ARG_RERANKING",
                    "LLAMA_ARG_EMBEDDINGS",
                ):
                    env.pop(_pooling_var, None)
                if gpu_memory_mode == "manual":
                    self._clear_manual_placement_env(env)
                # Scrub inherited LLAMA_ARG_MLOCK/_MMAP/_LOAD_MODE (read before argv); use the _mem_settings snapshot, not live toggles, or env and argv diverge.
                _mem_scrubbed = scrub_memory_env(env, _mem_settings)
                if _mem_scrubbed:
                    logger.info(
                        "Model Memory owns placement; dropped inherited %s",
                        ", ".join(_mem_scrubbed),
                    )
                # Tracks whether the policy changed this launch; turning the toggles off relaunches only if it did.
                _denied_scrubbed = scrub_denied_env(env)
                if _denied_scrubbed:
                    logger.info(
                        "dropped inherited %s: managed by Unsloth Studio",
                        ", ".join(_denied_scrubbed),
                    )
                # After the scrub, which drops an inherited LLAMA_API_KEY.
                env.update(_key_env)
                # Records what the child will run (env plus last-wins argv, load-mode pair included: none holds an anonymous copy) so user --mlock and --no-mmap count.
                self._record_memory_state(
                    list(_mem_managed) + list(_load_mode_managed) + list(_mem_extras), env
                )
                # Activity is whether turning the toggles off changes this child; shadowed _mem_managed does not.
                _mem_policy_touched_extras = bool(_mem_scrubbed) or _mem_extras != list(
                    extra_args or []
                )
                # Snapshot of what cmd carries, taken before respawns edit it; the arch-crash retry restores it.
                _mem_managed_is_effective = bool(_mem_managed) and (
                    tuple(_mem_managed) != MANAGED_DIO_FLAGS
                    or self._memory_direct_io != _ask((False, False), _off_view)[1]
                )
                self._memory_policy_active = _mem_managed_is_effective or _mem_policy_touched_extras
                self._memory_policy_extras_touched = _mem_policy_touched_extras

                # No --flash-attn in this build: LLAMA_ARG_FLASH_ATTN is unread; keeping it under-sizes the V cache.
                def _snapshot_policy_for_cmd():
                    """Read at call time, not from a snapshot, since a stale snapshot restored an
                    outdated cmd."""
                    return (
                        _mem_host_resident,
                        self._memory_state,
                        self._memory_direct_io,
                        self._memory_dio_applicable,
                        list(self._memory_dio_flags),
                        self._memory_policy_active,
                        self._memory_mlock_applicable,
                    )

                _mem_policy_for_cmd = _snapshot_policy_for_cmd()
                # Drop inherited LLAMA_ARG_THREADS, which would force hardware_concurrency().
                if "--threads" not in cmd:
                    env.pop("LLAMA_ARG_THREADS", None)
                # Drop an inherited LLAMA_ARG_CTX_SIZE=0: it pins native ctx and disables --fit.
                if (
                    not any(token in cmd for token in ("-c", "--ctx-size"))
                    and _env_asks_for_the_native_context(env)
                    and self._metal_drops_zero_ctx_override(0, _caller_owns_budget)
                ):
                    env.pop("LLAMA_ARG_CTX_SIZE", None)
                    logger.warning(
                        "Dropping the inherited LLAMA_ARG_CTX_SIZE=0: on Metal it pins "
                        "the model's native length and disables --fit."
                    )
                # A build whose help has no --flash-attn never registers the option,
                # so it never reads LLAMA_ARG_FLASH_ATTN either (llama.cpp resolves
                # each env var through the arg that declares it). Leaving an
                # inherited one in place would only fool the accounting below, which
                # reads env plus argv and would then record flash attention as on for
                # a server running without it, under-sizing the padded V cache.
                if _flash_attn_known_off and self._drop_env_flash_attn(env):
                    logger.info(
                        "Dropped inherited LLAMA_ARG_FLASH_ATTN: this build has no --flash-attn."
                    )
                # Same for an env-only quantized V cache, which the argv reset
                # above cannot reach.
                if _flash_attn_known_off and self._drop_env_quantized_v_cache(
                    env,
                    mla = self._target_kv_symmetry(),
                    draft_mla = self._draft_kv_symmetry(cmd, env),
                ):
                    logger.info(
                        "Dropped inherited quantized V-cache env: this build has no --flash-attn."
                    )

                # Drop an unparsable inherited KV type: it aborts both the launch and the layer retry; apply in every split mode, since llama.cpp parses it the same way.
                for _ct_var in ("LLAMA_ARG_CACHE_TYPE_K", "LLAMA_ARG_CACHE_TYPE_V"):
                    # Compare against the ORIGINAL, not a stripped copy: kv_cache_type_from_str needs an exact match, and a stripped compare leaves the whitespace on the child.
                    _ct_orig = env.get(_ct_var) or ""
                    _ct_norm = _ct_orig.strip().lower()
                    if not _ct_norm:
                        continue
                    if _ct_norm not in _VALID_CACHE_TYPES:
                        env.pop(_ct_var, None)
                        logger.info(
                            "Dropped inherited %s=%s: llama.cpp does not accept that "
                            "KV cache type, and it would abort the load.",
                            _ct_var,
                            _ct_orig,
                        )
                    elif _ct_norm != _ct_orig:
                        # Clears an inherited non-layer LLAMA_ARG_SPLIT_MODE so the child cannot override the layer plan.
                        env[_ct_var] = _ct_norm

                # Reconcile the inherited LLAMA_ARG_* split env with Unsloth's final
                # decision (the previews above apply the same helper).
                self._reconcile_split_mode_env(env, tensor_parallel = tensor_parallel)

                # A gpu_ids pin also owns inherited device placement.
                if _gpu_ids_own_device_flags:
                    self._clear_device_placement_env(env)

                # Point at the Vision switch only for an existing mmproj file; a stale path drops nothing to restore.
                _cpu_fallback_eligible = self._auto_vulkan_cpu_fallback_eligible(
                    binary,
                    intent,
                    extra_args,
                    env,
                )
                _vulkan_suspect = False

                # Argv drop cannot reach an env drafter; spec types accumulate, so scrub both.
                if _pv_draft_unpinnable or not _extra_args_set_spec_type(extra_args):
                    for _pv_spec_var in _SPEC_ENV_VARS:
                        env.pop(_pv_spec_var, None)

                # Also clear LLAMA_ARG_MMPROJ(_URL): the guard only cleared our resolved path.
                if disable_vision:
                    # Keep an audio-only encoder: a projector is not always a vision tower, and clearing it loses audio input; unknown still counts as image-capable.
                    _dv_env_mmproj = (env.get("LLAMA_ARG_MMPROJ") or "").strip()
                    if not _mmproj_env_is_audio_only(_dv_env_mmproj):
                        # Same signal the resolved path records, for the same reason:
                        # this one IS restored by turning Vision back on, so the composer
                        # must point at the switch rather than at a missing mmproj. Only
                        # for a file that exists -- a stale path drops nothing, and
                        # blaming the switch there sends the user to a control that
                        # cannot help. Unknown-but-present reads image-capable, matching
                        # the rule the scrub itself just used.
                        if _dv_env_mmproj and Path(_dv_env_mmproj).is_file():
                            _dv_dropped_image_projector = True
                        env.pop("LLAMA_ARG_MMPROJ", None)
                    # No such reprieve for the URL: it names a download that has not
                    # happened, so there is no file to classify and nothing to do but
                    # honor the switch.
                    env.pop("LLAMA_ARG_MMPROJ_URL", None)
                if _paravirtual_cpu_forced:
                    for _pv_mmproj_var in ("LLAMA_ARG_MMPROJ", "LLAMA_ARG_MMPROJ_URL"):
                        env.pop(_pv_mmproj_var, None)
                    # LLAMA_ARG_OVERRIDE_TENSOR puts weights back on Metal regardless of --gpu-layers 0; strip only GPU-bound overrides, keeping inherited CPU-target ones.
                    _pv_env_ot = env.get("LLAMA_ARG_OVERRIDE_TENSOR")
                    if _pv_env_ot and not _paravirtual_strip_gpu_overrides(
                        ["-ot", str(_pv_env_ot)]
                    ):
                        env.pop("LLAMA_ARG_OVERRIDE_TENSOR", None)

                # Windows full offload: PASSIVE OMP + 2 threads stop spin-wait CPU burn.
                if sys.platform == "win32" and full_offload_tuning_active:
                    env.setdefault("OMP_WAIT_POLICY", "PASSIVE")
                    if not threads_overridden:
                        env.setdefault("OMP_NUM_THREADS", "2")

                # Managed allocations trade ROCm APU carve-out capacity for host RAM.
                # Vulkan indices are not ROCm ids. Track ownership so later retries
                # preserve inherited values.
                _unified_env_applied = False
                _unified_opt_out = self._unified_memory_opted_out(env)
                _unified_opt_in = self._unified_memory_opted_in(env)
                # The arch gate and arch-crash retry re-select without rebinding gpu_indices.
                _unified_gpu_indices = gpu_indices

                def _unified_need_now(argv = None, mtp_engages = None):
                    """Bytes a forced full offload puts on the device, or None."""
                    run_argv = cmd if argv is None else argv
                    # The trailing blocks load only when the EMBEDDED head drafts: a
                    # sidecar wins over it (llama.cpp has_dft()), wherever it lands.
                    if mtp_engages is None:
                        engages = _mtp_will_engage and not _separate_draft_launches
                    else:
                        engages = mtp_engages
                    if model_size is None or not self._launch_forces_full_offload(run_argv, env):
                        return None
                    need = int(model_size)
                    if mmproj_size and not _argv_keeps_projector_on_gpu(run_argv, env):
                        need -= int(mmproj_size)
                    # Re-priced rather than cleared, so a spill that still stands is still reported.
                    layout = self._tensor_spill_layout(model_path, all_shards = True)
                    if layout is None or not getattr(layout, "complete", True):
                        return None
                    if int(getattr(layout, "lm_head_bytes", 0) or 0) and not (
                        _override_places_tensor_on_device("token_embd.weight", run_argv, env)
                    ):
                        need -= int(getattr(layout, "token_embd_bytes", 0) or 0)
                    per_layer = int(getattr(layout, "per_layer_embd_bytes", 0) or 0)
                    scan = self._gguf_tensor_scan(model_path) if per_layer else None
                    if scan is not None and any(
                        _override_places_tensor_on_device(name, run_argv, env)
                        for name in scan[1]
                        if _is_per_layer_embedding(name)
                    ):
                        per_layer = 0
                    need -= per_layer
                    if not engages and self._nextn_predict_layers:
                        need -= int(getattr(layout, "excluded_block_bytes", 0) or 0)
                    return need

                def _unified_withdraw_if_unneeded(
                    run_cmd,
                    *,
                    mtp_engages = None,
                    why = "",
                ):
                    """Drop the variable THIS launch set once a respawn stops needing it."""
                    nonlocal _unified_env_applied
                    # Whether the user could stop the spill at all, independent of the managed-memory decision above.
                    try:
                        _carveout_need = _unified_need_now(argv = run_cmd, mtp_engages = mtp_engages)
                    except Exception:
                        _carveout_need = None
                    self._record_carveout_advice(
                        _unified_gpu_indices,
                        _carveout_need,
                        is_vulkan_backend = is_vulkan_backend,
                        shared_gpu_ids = _shared_gpu_ids,
                        detected_gpus = _detected_gpus,
                        target_unknown = _cache_target_unknown,
                        forced_cpu = _arch_gate_forced_cpu,
                    )
                    if not _unified_env_applied:
                        return
                    if self._unified_memory_for_launch(
                        _unified_gpu_indices,
                        _unified_need_now(argv = run_cmd, mtp_engages = mtp_engages),
                        opted_in = _unified_opt_in,
                    ):
                        return
                    env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None)
                    _unified_env_applied = False
                    logger.info(
                        "%s no longer needs managed memory; dropped "
                        "GGML_CUDA_ENABLE_UNIFIED_MEMORY.",
                        why or "The retry",
                    )

                _unified_need = _unified_need_now()
                if _unified_opt_out:
                    # ggml tests presence, so a user's "0" would enable it; only absence is off.
                    if env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None) is not None:
                        logger.info(
                            "Unified memory opted out: unset GGML_CUDA_ENABLE_UNIFIED_MEMORY"
                        )
                elif not is_vulkan_backend and self._unified_memory_for_launch(
                    gpu_indices, _unified_need, opted_in = _unified_opt_in
                ):
                    _unified_env_applied = "GGML_CUDA_ENABLE_UNIFIED_MEMORY" not in env
                    env.setdefault("GGML_CUDA_ENABLE_UNIFIED_MEMORY", "1")
                    logger.info(
                        "AMD unified-memory APU: set GGML_CUDA_ENABLE_UNIFIED_MEMORY=1 (%s)",
                        "UNSLOTH_ENABLE_UNIFIED_MEMORY=1"
                        if _unified_opt_in
                        else "the weights outgrow the carve-out and host RAM is the larger pool",
                    )

                # Computed here: zero-offload is masked to CUDA_VISIBLE_DEVICES=-1 and moves no tensors between GPUs.
                self._record_carveout_advice(
                    gpu_indices,
                    _unified_need,
                    is_vulkan_backend = is_vulkan_backend,
                    shared_gpu_ids = _shared_gpu_ids,
                    detected_gpus = _detected_gpus,
                    target_unknown = _cache_target_unknown,
                    forced_cpu = _arch_gate_forced_cpu,
                )

                # GGML_CUDA_P2P=0 still enables P2P (presence, not value); env builder strips it already, so this covers envs assembled another way.
                self._sanitize_p2p_env(env)

                # gpu_indices are PCI ids only when PCI_BUS_ID is pinned, else FASTEST_FIRST may name other cards.
                _cpu_only_zero_offload = (
                    gpu_memory_mode == "manual"
                    and gpu_layers == 0
                    and not is_vulkan_backend
                    and not self._zero_offload_keeps_gpu_visible(cmd, env)
                )

                # Whether the child will resolve gpu_indices as the nvidia-smi ids
                # the P2P gate verifies. The launch below pins PCI_BUS_ID for an
                # explicit pick, and for an auto-fit selection only when NO mask was
                # inherited (nothing to reinterpret); anything else leaves CUDA on
                # FASTEST_FIRST, where those ids may name other cards.
                # That auto-fit arm also requires the ids to BE PCI indices: when the
                # nvidia-smi query fails _get_gpu_memory falls back to torch CUDA
                # ordinals, and pinning PCI order re-emits those numbers as a
                # different set of cards. An explicit pick is unaffected, its ids
                # come from the UI's own PCI-ordered picker.
                _p2p_launch_order_pinned = bool(gpu_ids) or (
                    os.environ.get("CUDA_VISIBLE_DEVICES") is None
                    and LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is True
                )
                # Only for an unconfirmed fabric; datacenter boxes are left to _apply_datacenter_env, which warns.
                _p2p_ids_are_pci = (
                    LlamaCppBackend._GPU_IDS_ARE_PCI_INDICES is True
                    or os.environ.get("CUDA_DEVICE_ORDER") == "PCI_BUS_ID"
                )

                # When the arch gate empties the pool, mask every GPU: the child would enumerate and abort on them.
                if (
                    env.get("GGML_CUDA_P2P")
                    and not _cpu_only_zero_offload
                    and not is_vulkan_backend
                    and not self._is_datacenter_gpu(gpu_indices)
                    and self._effective_gpu_count(gpu_indices) > 1
                    and not LlamaCppBackend._warned_no_nvlink
                ):
                    _p2p_veto = self._p2p_veto_reason(
                        gpu_indices, _p2p_launch_order_pinned, _p2p_ids_are_pci
                    )
                    if _p2p_veto is not None:
                        LlamaCppBackend._warned_no_nvlink = True
                        logger.warning(
                            "GGML_CUDA_P2P=%s is set in the environment but this "
                            "selection has no confirmed NVLink fabric: %s. Peer copies "
                            "over PCIe can be discarded silently while CUDA still "
                            "reports success, which surfaces as garbled output rather "
                            "than an error. Verify with scripts/p2p_integrity_probe.py "
                            "and unset the variable entirely (not =0, which reads as ON "
                            "upstream) if it fails (#10613).",
                            env["GGML_CUDA_P2P"],
                            _p2p_veto,
                        )

                # DC NVIDIA: FP32 accum, launch queues, P2P once NVLink is confirmed. Opt out: UNSLOTH_DISABLE_DC_TUNING=1, or UNSLOTH_DISABLE_DC_P2P=1 for P2P only.
                if not (is_vulkan_backend or _cpu_only_zero_offload):
                    self._apply_datacenter_env(
                        env,
                        gpu_indices,
                        p2p_opted_out = self._p2p_user_opted_out(),
                        launch_order_pinned = _p2p_launch_order_pinned,
                        ids_are_pci_indices = _p2p_ids_are_pci,
                    )

                # ROCm needs HIP_VISIBLE_DEVICES too. Zero-offload hides GPUs (a visible CUDA device costs ~0.5 GB reported free); user device pins keep control.
                _child_gpu_physical_ids: Optional[tuple[int, ...]] = None
                # companion flags fitted to the child's mask, refitted by the arch-crash retry
                _companion_fit_mask: Optional[list[int]] = None
                _companion_added_device: Optional[list[str]] = None
                if not is_vulkan_backend and _gpu_mem:
                    _child_gpu_physical_ids = self._unmasked_child_gpu_physical_ids()
                _parent_view_gpu_ids = _child_gpu_physical_ids

                # The CUDA SM gate goes here, where the child's GPU visibility is
                # finally known: both arms below write CUDA_VISIBLE_DEVICES=-1, so no
                # kernel image loads and the abort this pre-empts cannot happen.
                # Deciding it from the request over-refused -- speculative "auto", a
                # --no-mmproj-offload projector and a --spec-draft-ngl 0 drafter all
                # read as GPU-bearing there, only the resolved argv knows. Still
                # before every spawn below and outside the fit's try/except, so the
                # refusal cannot be swallowed into the --fit on fallback.
                # Pinned ids are checked against nvidia-smi's caps only in its index space
                # (torch-fallback ordinals are not); otherwise "any visible", as before.
                _sm_gate_ids_are_pci = not is_vulkan_backend and _p2p_ids_are_pci
                if not (_cpu_only_zero_offload or _arch_gate_forced_cpu):
                    # Pinned launches check the pinned cards, not "any visible".
                    _sm_gate = self._cuda_sm_gate_error(
                        binary, gpu_indices if _sm_gate_ids_are_pci else None
                    )
                    if _sm_gate:
                        raise RuntimeError(_sm_gate)
                # The arch gate emptying the pool lands here for the same reason
                # (#7624): no device set this binary can launch on, so the child must
                # not see the cards it would enumerate and abort on. gpu_indices is
                # None there, so this branch writes the mask.
                if _cpu_only_zero_offload or _arch_gate_forced_cpu:
                    self._emit_child_gpu_visibility(env, "-1")
                    _child_gpu_physical_ids = ()
                    # Tensor mode with no visible device fails in llama_prepare_model_devices; strip it.
                    _cpu_cmd = (
                        self._without_flags(cmd, ("--split-mode", "-sm", "--tensor-split", "-ts"))
                        if _arch_gate_forced_cpu
                        else None
                    )
                    if _cpu_cmd is not None:
                        logger.info(
                            "Forced-CPU launch: dropped the split-mode/tensor-split "
                            "flags, which abort a server with no visible device."
                        )
                        cmd = _cpu_cmd
                        # Recorded, or the next Apply reads the normalized server as a
                        # different one and rebuilds a multi-GB model every time.
                        if self._tensor_parallel:
                            self._arch_gate_dropped_tensor_parallel = True
                        if self._tensor_split:
                            self._arch_gate_dropped_tensor_split = tuple(self._tensor_split)
                        self._tensor_parallel = False
                        self._tensor_split = None
                    if _arch_gate_forced_cpu:
                        # Not gated on the argv strip: llama.cpp reads the LLAMA_ARG_*
                        # twins whether or not we emitted the flags, so an inherited
                        # tensor mode aborts a child with no visible device on its own.
                        self._clear_split_placement_env(env)
                elif gpu_indices is not None and not is_vulkan_backend:
                    # Pin PCI_BUS_ID so UI GPU 1 is llama.cpp GPU 1; auto-fit only when no inherited mask exists, since a scheduler mask would be re-read in new order.
                    if _p2p_launch_order_pinned:
                        env["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
                    # Keep a mask that deliberately reorders the same cards.
                    _pin_ids = list(gpu_indices)
                    # Record the rewritten --tensor-split, or /status pairs shares with the wrong device.
                    _inherited_order = (
                        None if gpu_ids else self._inherited_child_gpu_order(_pin_ids)
                    )
                    if _inherited_order is not None:
                        # A user --tensor-split is positional; decline to reorder under it.
                        if _extra_args_have_tensor_split(extra_args, env):
                            logger.info(
                                "Keeping ascending GPU order: a pass-through "
                                "--tensor-split is positional over it."
                            )
                        elif self._repoint_emitted_tensor_split(cmd, _pin_ids, _inherited_order):
                            logger.info(
                                "Pinning the child's GPU order to the inherited "
                                "visibility mask: %s (ascending would be %s).",
                                _inherited_order,
                                _pin_ids,
                            )
                            _pin_ids = _inherited_order
                            # --fit on or a manual all-GPU ratio leaves the child unpinned, so an uncovered card can reach it.
                            if "--tensor-split" in cmd and gpu_memory_mode != "manual":
                                _rewritten = cmd[cmd.index("--tensor-split") + 1]
                                try:
                                    self._auto_tensor_split_emitted = self._auto_split_fingerprint(
                                        [float(x) for x in str(_rewritten).split(",")]
                                    )
                                except (TypeError, ValueError):
                                    self._auto_tensor_split_emitted = None
                    # Mask at ROCr/HSA: HIP-only masking still enumerates and segfaults on unsupported GPUs. Skipped for uuid/MIG masks and an inherited LLAMA_ARG_DEVICE.
                    _companion_widen = ""
                    if not self._visibility_mask_is_unmappable() and not (
                        _extra_args_main_device(cmd) is None
                        and str(env.get("LLAMA_ARG_DEVICE", "")).strip()
                    ):
                        _had_main_device = _extra_args_main_device(cmd) is not None
                        _pin_ids, _companion_widen = _widen_pin_ids_for_companion_devices(
                            cmd,
                            _pin_ids,
                            self._resolve_visible_physical_ids(),
                            allowed_ids = gpu_ids or None,
                        )
                        if _companion_widen:
                            _companion_fit_mask = list(_pin_ids)
                            if not _had_main_device and _extra_args_main_device(cmd) is not None:
                                _companion_added_device = list(cmd[-2:])
                            if gpu_ids:
                                self._adopt_widened_pin(_pin_ids)
                    if _companion_widen:
                        logger.info(
                            "Companion device flags name GPUs by their unpinned "
                            "numbering; fitted the pinned mask to them: %s",
                            _companion_widen,
                        )
                        # The widened mask can add a card the gate above never saw.
                        if _sm_gate_ids_are_pci:
                            _sm_gate = self._cuda_sm_gate_error(binary, _pin_ids)
                            if _sm_gate:
                                raise RuntimeError(_sm_gate)
                    _child_mask = LlamaCppBackend._pinned_child_visibility(_pin_ids)
                    if _child_mask is None:
                        logger.info(
                            "Keeping the inherited CUDA_VISIBLE_DEVICES=%s: GPU ids %s "
                            "cannot be mapped to it.",
                            os.environ.get("CUDA_VISIBLE_DEVICES"),
                            _pin_ids,
                        )
                    else:
                        self._emit_child_gpu_visibility(env, _child_mask, prefer_rocr = True)
                    _child_gpu_physical_ids = tuple(int(i) for i in _pin_ids)
                    _launch_pinned_ids = list(_pin_ids)
                elif not is_vulkan_backend and not gpu_ids:
                    # Record it, or the duplicate-load check sees a different server and rebuilds on every Apply.
                    _survivors = self._arch_gate_survivors(binary)
                    if _survivors:
                        # Masking re-indexes survivors, so drop the full-count ratio.
                        _gated_cmd = self._without_tensor_split(cmd)
                        if _gated_cmd is not None:
                            logger.warning(
                                "Dropping the manual --tensor-split: it was sized "
                                "for every visible GPU, and the installed build "
                                "has no kernels for some of them."
                            )
                            cmd = _gated_cmd
                            # With one survivor, --split-mode tensor is a no-op but still reported active, so drop the mode too.
                            self._arch_gate_dropped_tensor_split = (
                                tuple(self._tensor_split) if self._tensor_split else None
                            )
                            self._tensor_split = None
                        # Narrowing to one survivor leaves --split-mode tensor a no-op
                        # still REPORTED as active (tensor_parallel drives the UI and
                        # arms the MTP crash watchdog), manual mode having admitted it
                        # on the FULL device count. _without_tensor_split takes only the
                        # ratio, so drop the mode too, as the arch-crash retry does.
                        if len(_survivors) < 2 and self._tensor_parallel:
                            _no_tensor_mode = self._without_flags(cmd, ("--split-mode", "-sm"))
                            if _no_tensor_mode is not None:
                                cmd = _no_tensor_mode
                            self._arch_gate_dropped_tensor_parallel = True
                            self._tensor_parallel = False
                            logger.info(
                                "The arch gate leaves one GPU; dropped tensor "
                                "parallelism, which needs at least two."
                            )
                        logger.info(
                            "The installed llama.cpp build has no kernels for GPU(s) "
                            "left visible; pinning the child to %s.",
                            _survivors,
                        )
                        # Re-asked on the narrowed set: an unsupported APU answered host-resident for the unnarrowed launch.
                        self._clear_split_placement_env(env)
                        # Process-wide, so recompute after changing devices; an inherited value is never overwritten.
                        _unified_gpu_indices = _survivors
                        _survivors_gain_unified = self._unified_memory_for_launch(
                            _survivors, _unified_need_now(), opted_in = _unified_opt_in
                        )
                        if _unified_env_applied and not _survivors_gain_unified:
                            env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None)
                            _unified_env_applied = False
                            logger.info(
                                "Arch gate narrowed the launch onto GPU(s) the "
                                "unified-memory swap cannot help; dropped "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY."
                            )
                        elif (
                            _survivors_gain_unified
                            and not _unified_opt_out
                            and "GGML_CUDA_ENABLE_UNIFIED_MEMORY" not in env
                        ):
                            env["GGML_CUDA_ENABLE_UNIFIED_MEMORY"] = "1"
                            _unified_env_applied = True
                            logger.info(
                                "Arch gate narrowed the launch onto a unified-memory "
                                "APU the weights outgrow; set "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY=1."
                            )
                        self._emit_child_gpu_visibility(
                            env, ",".join(str(i) for i in _survivors), prefer_rocr = True
                        )
                        _child_gpu_physical_ids = tuple(int(i) for i in _survivors)
                        # Narrower than any pin above, so it replaces it.
                        _launch_pinned_ids = list(_survivors)
                        # Taken against the UNNARROWED set, where an unsupported APU
                        # answered host-resident for the whole launch; this gate removes
                        # it. fully_offloaded False: the fitter still owns placement.
                        _gate_dio, _gate_applicable, _gate_active = _dio_decision_for(
                            _survivors, fully_offloaded = False, child_env = env
                        )
                        self._memory_dio_applicable = _gate_applicable
                        # BOTH directions: narrowing can also take the offload away, and
                        # the pair then reads CPU-resident layers into allocated buffers.
                        if self._memory_dio_flags and not _gate_dio:
                            cmd = self._drop_managed_dio(
                                cmd,
                                "the arch gate's surviving GPU(s) no longer confirm a "
                                "full offload",
                            )
                            self._memory_dio_applicable = _gate_applicable
                            self._record_memory_state(cmd, env)
                            _mem_policy_for_cmd = _snapshot_policy_for_cmd()
                        elif _gate_dio and not self._memory_dio_flags:
                            cmd = [*cmd, *_gate_dio]
                            self._memory_dio_flags = list(_gate_dio)
                            self._memory_policy_active = _gate_active or self._memory_policy_active
                            self._record_memory_state(cmd, env)
                            _mem_policy_for_cmd = _snapshot_policy_for_cmd()
                            logger.info(
                                "Model Memory: applying %s; the arch gate pins this "
                                "launch to discrete GPU(s) %s.",
                                " ".join(_gate_dio),
                                _survivors,
                            )
                        # And the carve-out advice with it: upstream priced the
                        # UNNARROWED set, which _rocm_selected_pool_mib declines on a
                        # mixed host, so a model outgrowing the surviving APU's
                        # carve-out was never advised about.
                        try:
                            _gated_carveout_need = _unified_need_now(argv = cmd)
                        except Exception:
                            _gated_carveout_need = None
                        self._record_carveout_advice(
                            _survivors,
                            _gated_carveout_need,
                            is_vulkan_backend = is_vulkan_backend,
                            shared_gpu_ids = _shared_gpu_ids,
                            detected_gpus = _detected_gpus,
                            target_unknown = _cache_target_unknown,
                            forced_cpu = _arch_gate_forced_cpu,
                        )
                    elif manual_tensor_split_emitted:
                        # A manual per-GPU ratio across ALL GPUs (no explicit pick, so
                        # no mask above): the UI built --tensor-split in ascending
                        # physical/PCI order, so pin the child's enumeration to match.
                        # The whole visible set stays in use, only its order is fixed.
                        _child_gpu_physical_ids = self._pin_visible_gpu_order_for_split(env)

                _child_has_no_gpu = (
                    # each names a device present but unusable, so it owns the empty pool
                    _arch_gate_forced_cpu
                    or _paravirtual_cpu_forced
                    # neither says a device exists, so an empty pool stays unreadable
                    or (
                        bool(_detected_gpus)
                        and (
                            _cpu_only_zero_offload or self._binary_ships_no_gpu_backend(binary, env)
                        )
                    )
                )
                # Pool read before anything spawns (a later reading subtracts the model being priced); the replay and guard must share it, so only the VRAM credit differs.
                _preflight_avail_mib = (
                    self._available_system_memory_mib() if _cpu_fallback_eligible else None
                )
                # Only count VRAM on cards this child can reach.
                _reachable_gpus = self._rows_the_child_can_reach(_detected_gpus, _launch_pinned_ids)
                # reads the argv the child gets, not the mid-fit state that produced it
                _offload_msg = self._launch_host_shortfall_message(
                    cmd,
                    _reachable_gpus,
                    env,
                    child_has_no_gpu = _child_has_no_gpu,
                    avail_mib = _preflight_avail_mib,
                    shared_gpu_ids = _shared_gpu_ids,
                    integrated_gpu_ids = _vulkan_igpu_ids,
                )
                if (
                    _offload_msg
                    and intent.refuse_partial_gpu_fit
                    and gpu_memory_mode != "manual"
                    and self._other_servers_running()
                ):
                    raise GpuMemoryShortError(_offload_msg, host = True)
                # Snapshotted BEFORE the override note is appended below, so a re-price
                # that promotes this notice appends that note once rather than twice.
                _host_ram_msg = _offload_msg

                def _launch_is_oversized() -> bool:
                    """Oversized by APU preflight, the warning just raised, or pricing with the opt-out ignored; the opt-out hides a message and must not withdraw the rewrite."""
                    if _apu_ram_oversized or _offload_msg:
                        return True
                    if not self._host_offload_warning_opted_out():
                        return False
                    return bool(
                        self._launch_host_shortfall_message(
                            cmd,
                            _reachable_gpus,
                            env,
                            child_has_no_gpu = _child_has_no_gpu,
                            avail_mib = _preflight_avail_mib,
                            shared_gpu_ids = _shared_gpu_ids,
                            honor_opt_out = False,
                            integrated_gpu_ids = _vulkan_igpu_ids,
                        )
                    )

                cmd, _pageable_note = self._page_an_oversized_unmapped_load(
                    cmd, env, _launch_is_oversized
                )
                if _pageable_note:
                    # Record the argv that actually launches, and snapshot it too, since arch-crash retry restores it.
                    if _offload_msg:
                        _offload_msg += _pageable_note
                    # First notice wins, so amend whatever is already recorded.
                    self._amend_load_warning(_pageable_note)
                    # The recorded state has to describe the argv that launches, or the
                    # reload comparator judges this child against a mode it no longer
                    # runs. The snapshot too: the arch-crash retry restores it over
                    # `cmd`, which now carries the override.
                    self._record_memory_state(cmd, env)
                    _mem_policy_for_cmd = _snapshot_policy_for_cmd()
                self._record_load_warning(_offload_msg)

                # Captured before any text-only fallback strips it from cmd.
                launched_with_mmproj = "--mmproj" in cmd

                # One-shot --fit off retry (fit aborts on some ROCm), never when fit was requested or passed in extras. Argv launched; text-only retry strips --mmproj.
                _last_spawn_cmd = list(cmd)
                _spawn_cwd: Optional[str] = None
                # An inherited LLAMA_ARG_FIT=off belongs to the user, and the flip would override it on the CLI.
                _did_rocm_retry = False

                def _enable_managed_fit_for_no_flash(fa_cmd: list) -> list:
                    """Restores Unsloth's own --fit on for a --flash-attn off respawn, which is re-
                    placed and needs it."""
                    if "--fit" not in fa_cmd:
                        return fa_cmd
                    if any(
                        _flag_name(str(token)) in {"-fit", "--fit"} for token in (extra_args or ())
                    ):
                        return fa_cmd
                    # Record from the argv, not the managed parts: dropping --load-mode none returns the child to auto.
                    if _user_fit_disabled(extra_args, env = env):
                        return fa_cmd
                    if _placement_is_fitter_proof(fa_cmd, gpu_layers = _manual_gpu_layers, env = env):
                        return fa_cmd
                    index = fa_cmd.index("--fit")
                    if index + 1 >= len(fa_cmd) or str(fa_cmd[index + 1]).strip().lower() == "on":
                        return fa_cmd
                    flipped = list(fa_cmd)
                    flipped[index + 1] = "on"
                    logger.info(
                        "Re-enabling the fitter for the --flash-attn off retry: the padded "
                        "V cache the retry runs with is bigger than the placement the fit "
                        "priced with flash attention on."
                    )
                    return flipped

                def _drop_fit_load_mode_for_no_flash(fa_cmd: list) -> list:
                    """Drops Unsloth's --load-mode on a --flash-attn off respawn (OOM instead of paging); do NOT clear the record, since the CPU fallback replays these tokens."""
                    if not self._fit_load_mode_flags:
                        return fa_cmd
                    stripped = _without_subsequence(fa_cmd, self._fit_load_mode_flags)
                    if stripped != fa_cmd:
                        # Tee llama-server output to a log; label and attempt index stop same-second respawns clobbering it.
                        self._record_memory_state(stripped, env)
                        logger.info(
                            "Load mode: dropping the fit's --load-mode none for the "
                            "--flash-attn off retry; the no-flash launch has a "
                            "footprint the fit did not price."
                        )
                    return stripped

                # Memoed only when the load ends terminally, so a recovering fallback is not blocked.
                _sched_abort_seen = False

                def _vulkan_wait_args(label):
                    """(timeout, kwargs) for a health wait: a stuck Vulkan driver burns CPU
                    and touches pages forever (#142), so auto-Vulkan launches get a ceiling."""
                    timeout = self._HEALTH_STALL_TIMEOUT_S
                    if not _cpu_fallback_eligible or intent.cpu_fallback or label == "-cpu":
                        return timeout, {}
                    per_gib = self._AUTO_VULKAN_START_S_PER_GIB
                    floor = timeout
                    if _vulkan_suspect and not label:
                        timeout = min(timeout, self._SUSPECT_VULKAN_STALL_TIMEOUT_S)
                        floor = timeout
                    elif not _vulkan_suspect:
                        # Listed device: ends with advice only, so CPU work (shader compile) is progress.
                        per_gib *= self._LISTED_VULKAN_CEILING_FACTOR
                        floor = timeout * self._LISTED_VULKAN_CEILING_FACTOR
                    ceiling = (model_size or 0) / (1 << 30) * per_gib
                    return timeout, {
                        "cpu_counts_as_progress": not _vulkan_suspect,
                        "max_total_s": max(floor, ceiling),
                    }

                def _spawn_and_wait(run_cmd, *, label = ""):
                    """Start llama-server with run_cmd and wait for health.

                    Up to four launches: the first, one ROCm env correction, one
                    retry without the MoE expert cache, and one --fit recovery.
                    Separate flags, so a library mix does not spend the fit slot
                    and a VRAM crash after the correction can still fit-retry.
                    """
                    # _mem_host_resident too: the --fit on retry re-arms the
                    # page-lock and writes it back, which without this makes the
                    # read below an UnboundLocalError instead.
                    nonlocal _last_spawn_cmd, _mem_host_resident, _did_rocm_retry
                    nonlocal _sched_abort_seen, _sidecar_fit_reserve_mib
                    # Single revocation point for the tensor-spill plan; label is empty only on the first spawn.
                    if label:
                        run_cmd = self._drop_tensor_spill(run_cmd, label.lstrip("-") or "retry")
                        run_cmd = self._drop_managed_lazy_mode(
                            run_cmd, label.lstrip("-") or "retry"
                        )
                    # The cache only rides the first pinned launch: every retry re-places.
                    if label or not _argv_loads_pinned(run_cmd, env):
                        run_cmd = self._drop_moe_cache(
                            run_cmd, f"{label.lstrip('-') or 'unpinned'} launch"
                        )
                    _fit_retry_allowed = self._fit_off_retry_eligible(run_cmd, use_fit)
                    _did_fit_retry = False
                    _did_moe_cache_retry = False
                    for _spawn_attempt in (0, 1, 2, 3):
                        if _spawn_attempt:
                            run_cmd = self._drop_managed_lazy_mode(run_cmd, "startup")
                        # Defensive kill: drop an orphan Popen a concurrent load may
                        # have stored before we overwrite the reference (#5161).
                        # Also reaps the crashed first attempt on the retry pass.
                        self._kill_process()
                        self._child_gpu_physical_ids = _child_gpu_physical_ids

                        self._stdout_lines = []
                        # Tee llama-server output to a dedicated log file so a
                        # post-mortem has the full trail even when the parent only
                        # kept the last 50 lines. Path is under the studio home.
                        # ``label`` (MTP fallback) and the attempt index (--fit
                        # off retry) keep a respawn within the same epoch second
                        # from truncating the crash log a retry warning just
                        # pointed the user at.
                        self._llama_log_fh = None
                        try:
                            log_dir = _swa_cache_path().parent / "logs" / "llama-server"
                            log_dir.mkdir(parents = True, exist_ok = True)
                            self._llama_log_path = log_dir / (
                                f"llama-{int(time.time())}{label}-port-{self._port}"
                                f"-try{_spawn_attempt}.log"
                            )
                            self._llama_log_fh = open(
                                self._llama_log_path,
                                "w",
                                encoding = "utf-8",
                                buffering = 1,
                            )
                            # After the open, so the cap counts this file and never deletes
                            # it. On the retry path the earlier attempts' logs are what a
                            # reader wants, and keep-newest holds on to them.
                            prune_log_dir(log_dir, "llama-*.log", protect = self._llama_log_path)
                            logger.info(f"llama-server stdout/stderr -> {self._llama_log_path}")
                        except (OSError, UnicodeDecodeError) as e:
                            # Best-effort; never block the load on logging.
                            logger.warning(f"Could not open llama-server log file: {e}")
                            self._llama_log_path = None
                        # Every launch: a retry can turn the fitter on or re-mask onto several
                        # cards.
                        _spawn_devices = _extra_args_main_device(run_cmd) or env.get(
                            "LLAMA_ARG_DEVICE"
                        )
                        _spawn_device_count = (
                            _distinct_device_count(_spawn_devices)
                            if _spawn_devices
                            else max(len(_child_gpu_physical_ids or ()), len(_detected_gpus))
                            if _child_gpu_physical_ids is None
                            or _child_gpu_physical_ids is _parent_view_gpu_ids
                            else len(_child_gpu_physical_ids)
                        )
                        if _sidecar_fit_reserve_eligible_mib:
                            # Re-derived each spawn: drop Studio's earlier reserve-bearing margins,
                            # keep the user's.
                            run_cmd = _drop_sidecar_margins(
                                list(run_cmd),
                                _integrity_flags,
                                self._ctx_integrity_flags(
                                    *_integrity_args,
                                    fit_target_delta_mib = _fit_target_delta_mib,
                                    fit_target_floor_mib = _metal_fit_target_floor_mib,
                                ),
                                _sidecar_override_pairs,
                                user_args = _sidecar_user_tokens,
                            )
                            _sidecar_fit_reserve_mib = 0
                        run_cmd = self._per_device_fit_target_argv(
                            run_cmd, env, _fit_target_margins_by_idx
                        )
                        _spawn_base_by_dev: Optional[list[float]] = None
                        if _fit_target_margins_by_idx:
                            try:
                                _spelled = [
                                    float(v)
                                    for v in str(
                                        _last_flag_value(run_cmd, {"-fitt", "--fit-target"})
                                    ).split(",")
                                ]
                            except ValueError:
                                _spelled = []
                            if len(_spelled) == 1:
                                _spelled = _spelled * _spawn_device_count
                            if len(_spelled) == _spawn_device_count:
                                _spawn_base_by_dev = _spelled
                        # --rpc devices come first in the child's list, so local positional shares
                        # would land on the wrong cards.
                        _spawn_rpc = not _spawn_devices and bool(
                            (_extra_args_device(run_cmd, {"--rpc"}) or "").strip()
                            or str(env.get("LLAMA_ARG_RPC", "")).strip()
                        )
                        # Several cards: each keeps its share of the drafter (whole draft layers) in
                        # a per-device list.
                        _spawn_shares: Optional[list[float]] = [1.0]
                        _spawn_output_dev: Optional[int] = None
                        _spawn_pinned_at: Optional[int] = None
                        _spawn_cpu_only = _device_selection_is_cpu(run_cmd, env) or (
                            _child_gpu_physical_ids is not None
                            and _child_gpu_physical_ids is not _parent_view_gpu_ids
                            and not _child_gpu_physical_ids
                        )
                        if _spawn_cpu_only:
                            _spawn_shares = None
                        elif (
                            _spawn_device_count > 1
                            and _extra_args_split_mode(run_cmd, env) == "tensor"
                        ):
                            # --split-mode tensor folds the cards into one device: no per-device
                            # reserve.
                            _spawn_shares = None
                        elif _spawn_rpc:
                            _spawn_shares = None
                        elif _spawn_device_count > 1 and _split_mode_confines_to_one_device(
                            run_cmd, env
                        ):
                            if _spawn_base_by_dev and len(set(_spawn_base_by_dev)) > 1:
                                # llama.cpp keeps only devices[main_gpu] (src/llama.cpp): the
                                # reserve goes in entry 0 of a list that keeps the other margins.
                                _main = self._effective_main_gpu(run_cmd, env) or 0
                                if 0 <= _main < _spawn_device_count:
                                    _spawn_shares = [
                                        1.0 if i == 0 else 0.0 for i in range(_spawn_device_count)
                                    ]
                                    _spawn_output_dev = 0
                                else:
                                    _spawn_shares = None
                        elif _spawn_device_count > 1:
                            _spawn_shares = None
                            _spawn_pinned_at = _draft_pin_device_index(
                                _extra_args_draft_device_pin(run_cmd),
                                _spawn_devices,
                                _spawn_device_count,
                            )
                            if _spawn_pinned_at is not None:
                                _spawn_shares = [
                                    1.0 if i == _spawn_pinned_at else 0.0
                                    for i in range(_spawn_device_count)
                                ]
                                _spawn_output_dev = _spawn_pinned_at
                            # Positional shares need the child to enumerate in the ids' order.
                            _spawn_order_unproven = self._positional_child_order_unproven(env)
                            if (
                                not is_vulkan_backend
                                and not _spawn_devices
                                and _extra_args_draft_device_pin(run_cmd) is None
                                and not _spawn_order_unproven
                            ):
                                _free_by_idx = dict(gpus or _detected_gpus or ())
                                if (
                                    _child_gpu_physical_ids is None
                                    or _child_gpu_physical_ids is _parent_view_gpu_ids
                                ):
                                    _det_ids = [idx for idx, _free in _detected_gpus]
                                    _spawn_ids = (
                                        self._inherited_child_gpu_order(_det_ids) or _det_ids
                                    )
                                else:
                                    _spawn_ids = list(_child_gpu_physical_ids)
                                _spawn_free = [_free_by_idx.get(i) for i in _spawn_ids]
                                # The drafter inherits the target's --tensor-split
                                # (common_base_params_to_speculative).
                                _spawn_base = self._fit_target_margin_mib(
                                    auto_fit = auto_fit,
                                    fit_target_delta_mib = _fit_target_delta_mib,
                                    floor_mib = _metal_fit_target_floor_mib,
                                )
                                _weights = None
                                if _spawn_free and all(f and f > 0 for f in _spawn_free):
                                    _spawn_margins = _fit_margins_by_device(
                                        extra_args, env, 0.0, len(_spawn_free)
                                    )
                                    _bases = (
                                        _spawn_base_by_dev
                                        if _spawn_base_by_dev
                                        and len(_spawn_base_by_dev) == len(_spawn_free)
                                        else [_spawn_base] * len(_spawn_free)
                                    )
                                    _weights = [
                                        max(1.0, float(f) - max(b, m))
                                        for f, m, b in zip(_spawn_free, _spawn_margins, _bases)
                                    ]
                                _ts = _extra_args_tensor_split(run_cmd, env)
                                if _ts and _spawn_ids:
                                    _ts_w = [
                                        float(_ts[i]) if i < len(_ts) else 0.0
                                        for i in range(len(_spawn_ids))
                                    ]
                                    if sum(_ts_w) > 0 and all(w >= 0 for w in _ts_w):
                                        _weights = _ts_w
                                if _weights:
                                    _layers = _sidecar_draft_layers or 0
                                    _cum = list(
                                        itertools.accumulate(w / sum(_weights) for w in _weights)
                                    )
                                    # "row" assigns blocks like "layer" (CUDA / ROCm register no
                                    # split buffer type).
                                    if _layers > 0:
                                        # llama.cpp's layer split: block il goes to the first device
                                        # whose cumulative share exceeds il / (n_layer + 1).
                                        _counts = [0] * len(_weights)
                                        for _il in range(_layers):
                                            _dev = bisect.bisect_right(_cum, _il / (_layers + 1))
                                            _counts[min(_dev, len(_weights) - 1)] += 1
                                        _spawn_shares = [c / _layers for c in _counts]
                                    else:
                                        _spawn_shares = [w / sum(_weights) for w in _weights]
                                    # Logits over a borrowed output run on the card holding the
                                    # target's layer n_layer.
                                    _t_layers = (
                                        _layers
                                        if _sidecar_owns_output
                                        else int(getattr(self, "_n_layers", 0) or 0) or _layers
                                    )
                                    if _t_layers > 0:
                                        _spawn_output_dev = min(
                                            bisect.bisect_right(_cum, _t_layers / (_t_layers + 1)),
                                            len(_weights) - 1,
                                        )
                        if (
                            _sidecar_fit_reserve_eligible_mib
                            and _spawn_shares is not None
                            and (
                                _spawn_pinned_at is not None
                                or _spawn_draft_on_target(run_cmd, _spawn_devices, env)
                            )
                            and server_caps.get("supports_fit_target")
                        ):
                            _spawn_total = (
                                _sidecar_reserve_reprice(list(run_cmd), env)
                                if _sidecar_reserve_reprice is not None
                                else _sidecar_fit_reserve_eligible_mib
                            )
                            # The vocabulary-wide graph stays whole on the output card.
                            _spawn_graph = min(
                                _sidecar_reserve_graph_mib[0] if len(_spawn_shares) > 1 else 0,
                                max(0, _spawn_total - _sidecar_compute_mib),
                            )
                            _spawn_body = max(0, _spawn_total - _sidecar_compute_mib - _spawn_graph)
                            _last = (
                                _spawn_output_dev
                                if _spawn_output_dev is not None
                                else max(i for i, f in enumerate(_spawn_shares) if f > 0)
                                if any(f > 0 for f in _spawn_shares)
                                else len(_spawn_shares) - 1
                            )
                            _spawn_head = 0
                            if (
                                _sidecar_owns_output
                                and len(_spawn_shares) > 1
                                and not _draft_share_unknown
                            ):
                                _head_layout = self._tensor_spill_layout(
                                    _sidecar_reserve_path, all_shards = True
                                )
                                if _head_layout is not None and _head_layout.complete:
                                    _spawn_head = min(
                                        _spawn_body,
                                        math.ceil(_head_layout.lm_head_bytes / (1024 * 1024)),
                                    )
                                    _spawn_body -= _spawn_head
                                else:
                                    _spawn_head = _spawn_body
                            _spawn_per_device = [
                                math.ceil(_spawn_body * f)
                                + (_sidecar_compute_mib if f > 0 or i == _last else 0)
                                + (_spawn_graph + _spawn_head if i == _last else 0)
                                for i, f in enumerate(_spawn_shares)
                            ]
                            _spawn_reserve = max(_spawn_per_device)
                            _spawn_flags = _sidecar_reserve_margin_flags(
                                run_cmd,
                                extra_args,
                                env,
                                self._fit_target_margin_mib(
                                    auto_fit = auto_fit,
                                    fit_target_delta_mib = _fit_target_delta_mib,
                                    floor_mib = _metal_fit_target_floor_mib,
                                ),
                                _spawn_reserve,
                                per_device = _spawn_per_device
                                if len(_spawn_per_device) > 1
                                else None,
                                base_by_device = _spawn_base_by_dev,
                            )
                            if _spawn_flags:
                                run_cmd = [*run_cmd, *_spawn_flags]
                                if _spawn_total != _sidecar_fit_reserve_eligible_mib:
                                    logger.info(
                                        "Sidecar reserve repriced for this launch's argv: "
                                        "%.2f GB.",
                                        _spawn_total / 1024,
                                    )
                                _sidecar_fit_reserve_mib = _spawn_reserve
                                if list(_spawn_flags) not in _sidecar_override_pairs:
                                    _sidecar_override_pairs.append(list(_spawn_flags))
                        if (
                            _sidecar_fit_reserve_eligible_mib
                            and _sidecar_kind_for_fit
                            and not _spawn_cpu_only
                        ):
                            self._log_sidecar_fit_reserve(
                                run_cmd,
                                env,
                                _sidecar_kind_for_fit,
                                _sidecar_reserve_path,
                                _sidecar_fit_reserve_mib,
                                _sidecar_reserve_logged,
                            )
                        logger.info(
                            f"Starting llama-server: {' '.join(self._redacted_cmd_for_log(run_cmd))}"
                        )
                        _last_spawn_cmd = list(run_cmd)
                        # Read off the argv actually spawned rather than the intent, so
                        # every emitter is covered by construction.
                        self._idle_slot_clearing_active = _idle_slot_clearing_active(
                            run_cmd,
                            supports_cache_ram = bool(server_caps.get("supports_cache_ram")),
                        )
                        # Check and publish under one lock, across Popen only, never the wait.
                        with self._spawn_lock:
                            if self._spawn_is_stale():
                                logger.info("app is shutting down; not starting llama-server")
                                self._close_attempt_log()
                                self._health_wait_cancelled = True
                                return False
                            _spawned = _spawn_on_lifetime_thread(
                                lambda: subprocess.Popen(
                                    run_cmd,
                                    stdout = subprocess.PIPE,
                                    stderr = subprocess.STDOUT,
                                    text = True,
                                    encoding = "utf-8",
                                    errors = "replace",
                                    env = env,
                                    cwd = _spawn_cwd,
                                    **_windows_hidden_subprocess_kwargs(),
                                    **_child_popen_kwargs(),
                                )
                            )
                            self._process = _spawned
                            self._process_env = (_spawned, env)
                            _invalidate_gpu_memory("llama-server spawned")
                            # Inside the lock: written after a sweep reaped the child,
                            # _pid_start_identity yields no start time, and the bare pid
                            # left behind is one a later launch kills blind.
                            self._note_server_pid(_spawned.pid)
                        # mark_process_shutting_down skips _spawn_lock, so recheck after spawn.
                        if self._spawn_is_stale():
                            logger.info(
                                "shutdown began during the spawn; killing the new llama-server"
                            )
                            self._kill_process()
                            self._close_attempt_log()
                            self._health_wait_cancelled = True
                            return False
                        # is_active covers it from here, so drop the pre-spawn flag.
                        # Re-armed below if this attempt fails: the retry rungs respawn from the same settings.
                        self._memory_pending_launch = None

                        # Background thread to drain stdout (prevents pipe deadlock)
                        self._stdout_thread = threading.Thread(
                            target = self._drain_stdout, daemon = True, name = "llama-stdout"
                        )
                        self._stdout_thread.start()
                        _wait_timeout, _wait_kwargs = _vulkan_wait_args(label)
                        if self._wait_for_health(
                            timeout = _wait_timeout,
                            cancelled = _load_cancelled,
                            **_wait_kwargs,
                        ):
                            if _did_rocm_retry:
                                # Proved on this host: every later child skips the
                                # prepend instead of crashing into it first.
                                self._remember_bundle_only_rocm(binary)
                            return True
                        if getattr(self, "_health_wait_cancelled", False):
                            return False
                        # The window is open again: the rungs below respawn from the SAME
                        # captured settings while a crashed child leaves is_active false.
                        # Here rather than per rung, so a later rung cannot forget it.
                        self._memory_pending_launch = _mem_settings
                        # Read once, like the wait itself: a cleared reference is a
                        # teardown, not a startup crash, and re-reading the
                        # attribute per term would race the shutdown thread again.
                        _crashed_proc = self._process
                        _startup_crashed = (
                            _crashed_proc is not None
                            and _crashed_proc.poll() is not None
                            and _crashed_proc.returncode != 0
                        )
                        # Split-axis aborts and old builds refusing tensor-mode quantized KV are not
                        # fit problems.
                        _startup_output = "\n".join(self._stdout_lines[-50:])
                        # Wider tail: the GGML_ASSERT line scrolls past the [New LWP] dump.
                        if _startup_crashed and self._is_sched_reserve_abort(
                            "\n".join(self._stdout_lines[-200:])
                        ):
                            _sched_abort_seen = True
                        # Scan the full buffer: gdb output can bury the assert.
                        _tensor_capability_crash = self._is_tensor_split_assert(
                            "\n".join(self._stdout_lines)
                        ) or self._is_tensor_quant_kv_unsupported(_startup_output)
                        _hip_rocr_mismatch = self._is_bundled_hip_rocr_mismatch(_startup_output)
                        # A startup crash means the spill prediction was wrong, so placement returns to llama.cpp.
                        _capability_crash = _tensor_capability_crash or self._is_kv_unified_refused(
                            "\n".join(self._stdout_lines)
                        )
                        _capability_crash = _capability_crash or (
                            self._cuda_kernel_image_error("\n".join(self._stdout_lines)) is not None
                        )
                        if (
                            not _did_rocm_retry
                            and _startup_crashed
                            and not _tensor_capability_crash
                            and _hip_rocr_mismatch
                        ):
                            # Drop only the prepended lib dirs; the rest of env holds the scrubs.
                            _bundle_only = self._llama_server_env_for_binary(
                                binary, use_system_rocm = False
                            )
                            _retry_ld = _bundle_only.get("LD_LIBRARY_PATH", "")
                            # "" on a host that never had the var: nothing to undo.
                            if _retry_ld and _retry_ld != env.get("LD_LIBRARY_PATH"):
                                logger.warning(
                                    "llama-server crashed during startup (exit code %s) "
                                    "because a bundled ROCm library could not resolve a "
                                    "symbol against the system ROCm; retrying once "
                                    "with the bundled runtime only. Crash log: %s",
                                    _crashed_proc.returncode,
                                    self._llama_log_path,
                                )
                                env["LD_LIBRARY_PATH"] = _retry_ld
                                _did_rocm_retry = True
                                continue
                        if (
                            not _did_moe_cache_retry
                            and _startup_crashed
                            and not _capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            # OOM or a cache error with the cache on: same placement without it.
                            _uncached = self._drop_moe_cache(run_cmd)
                            _crash_text = "\n".join(self._stdout_lines[-200:])
                            if _uncached != run_cmd and (
                                _MOE_CACHE_ERROR_RE.search(_crash_text)
                                or self._is_gpu_memory_start_failure(_crash_text)
                            ):
                                logger.warning(
                                    "llama-server crashed during startup (exit code %s) "
                                    "with --moe-cache-mib auto; retrying once without "
                                    "the MoE expert cache. Crash log: %s",
                                    _crashed_proc.returncode,
                                    self._llama_log_path,
                                )
                                run_cmd = _uncached
                                _did_moe_cache_retry = True
                                continue
                        if (
                            not _did_fit_retry
                            and _startup_crashed
                            and not _capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            # A spill-planned launch that crashed on startup. The
                            # two recoveries below cannot reach it: the spill arm
                            # leaves fully_gpu_offloaded False and runs under
                            # use_fit=True with an explicit --fit, so
                            # _fit_off_retry_eligible is False on both counts and
                            # the load would skip to the terminal/CPU fallbacks
                            # even though the --fit on placement it replaced would
                            # have worked. A crash means the prediction was wrong,
                            # so hand placement back to llama.cpp. Self-gating:
                            # _drop_tensor_spill returns run_cmd unchanged when no
                            # plan is present.
                            _reverted = self._drop_tensor_spill(run_cmd, "startup failure")
                            if _reverted != run_cmd:
                                logger.warning(
                                    "llama-server crashed during startup (exit code %s) "
                                    "with a tensor-spill plan; the plan was optimistic, "
                                    "retrying once with --fit on so llama.cpp can place "
                                    "the model itself. Crash log: %s",
                                    _crashed_proc.returncode,
                                    self._llama_log_path,
                                )
                                run_cmd = _reverted
                                self._record_memory_state(run_cmd, env)
                                _did_fit_retry = True
                                self._vram_fit_context_length = None
                                continue
                        if (
                            not _did_fit_retry
                            and fully_gpu_offloaded
                            and _startup_crashed
                            and not _capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            # Our VRAM math was optimistic: fall back to --fit on and let llama.cpp offload; DSpark takes this path too (fit only skips its sidecar reserve).
                            logger.warning(
                                "llama-server crashed during startup (exit code %s) "
                                "with forced --fit off; the fit estimate was optimistic, "
                                "retrying once with --fit on so it can offload. "
                                "Crash log: %s",
                                _crashed_proc.returncode,
                                self._llama_log_path,
                            )
                            # The fit's --load-mode none rested on a proof that just failed; drop only Unsloth's own tokens.
                            _run = list(run_cmd)
                            if "--fit" in _run:
                                _run[_run.index("--fit") + 1] = "on"
                            if self._mixed_split_flags:
                                # common/fit.cpp aborts a multi-device fit on a set split.
                                _run = _without_subsequence(_run, self._mixed_split_flags)
                                self._auto_tensor_split_emitted = None
                            # The --fit off launch emitted no margin; the next spawn adds the
                            # reserve.
                            # Same reasoning as the page-lock below, one step
                            # earlier: the fit picked "none" because it had proved
                            # the load fits, and that proof is what just failed, so
                            # give the retry llama.cpp's auto back. Only Unsloth's
                            # own tokens; a user's --load-mode is untouched.
                            if self._fit_load_mode_flags:
                                _run = _without_subsequence(_run, self._fit_load_mode_flags)
                                # The record is NOT cleared: it describes `cmd`, which
                                # this retry never touched and the arch-crash and CPU
                                # fallbacks respawn from, so clearing here would leave
                                # them carrying a --load-mode none they can no longer
                                # name. Stripping an already-stripped argv is a no-op.
                                logger.info(
                                    "Load mode: dropping the fit's --load-mode none "
                                    "for the --fit on retry; the fit it was derived "
                                    "from did not hold."
                                )
                            # The full-offload guess that skipped the page-lock just failed; appending it wins as last arg.
                            _run = self._drop_managed_dio(
                                _run,
                                "the --fit on retry gives up the confirmed full offload",
                                clear_record = False,
                            )
                            # With --fit off, -ngl defaults to every layer, so the host-resident verdict may no longer hold.
                            if _mem_should_mlock and not _mem_host_resident:
                                _retry_lock = keep_resident_lock_flags(
                                    load_mode_support(server_caps)
                                )
                                _run.extend(_retry_lock)
                                _mem_host_resident = True
                                # An unknown build gets no lock, so none is owed either.
                                self._memory_mlock_applicable = bool(_retry_lock)
                                if _retry_lock:
                                    self._memory_policy_active = True
                                    logger.info(
                                        "Model Memory: re-applying the page-lock for "
                                        "the --fit on retry; the full-offload "
                                        "prediction did not hold."
                                    )
                            run_cmd = _run
                            self._record_memory_state(_run, env)
                            _did_fit_retry = True
                            # The fit that vouched for the ceiling is what just failed.
                            self._vram_fit_context_length = None
                            continue
                        if (
                            not _did_fit_retry
                            and _fit_retry_allowed
                            and _startup_crashed
                            and not _capability_crash
                            and not _hip_rocr_mismatch
                        ):
                            logger.warning(
                                "llama-server crashed during startup (exit code %s) "
                                "with the default memory-fit step enabled; Unsloth "
                                "already verified the model fits, retrying once "
                                "with --fit off. Crash log: %s",
                                _crashed_proc.returncode,
                                self._llama_log_path,
                            )
                            run_cmd = [*run_cmd, "--fit", "off"]
                            # The mirror of the --fit on retry above. Turning the
                            # fitter off leaves -ngl at its default, which llama.cpp
                            # resolves to every layer, so the fitted attempt's
                            # host-resident verdict can stop holding. Drop a
                            # page-lock the retry no longer needs rather than
                            # reserving a full host copy of a fully offloaded model.
                            if _mem_host_resident and not self._weights_in_host_memory(
                                fully_gpu_offloaded = True,
                                gpu_memory_mode = gpu_memory_mode,
                                gpu_layers = gpu_layers,
                                extra_args = _mem_extra_args,
                                gpu_indices = gpu_indices,
                                is_vulkan_backend = is_vulkan_backend,
                                binary = binary,
                                env = _mem_env,
                            ):
                                _mem_host_resident = False
                                # So a later save is not compared against a lock this
                                # launch dropped.
                                self._memory_mlock_applicable = False
                                if _mem_managed:
                                    run_cmd = _without_subsequence(run_cmd, _mem_managed)
                                    # The managed flag was the policy's only mark on
                                    # this child unless it also scrubbed or stripped,
                                    # and a child equal to an unmanaged one must not
                                    # be torn down when the toggles go off.
                                    self._memory_policy_active = _mem_policy_touched_extras
                                    logger.info(
                                        "Model Memory: dropping the page-lock for "
                                        "the --fit off retry; it offloads every layer."
                                    )

                                # The other direction, which the page-lock arm cannot
                                # reach: nothing was emitted BECAUSE the fitted attempt
                                # read host-resident, the verdict this retry overturns.
                                # Appended, so a hand-typed flag still wins last. The
                                # fitter is OFF here, so -ngl is every layer.
                                _retry_dio, _retry_applicable, _retry_active = _dio_decision_for(
                                    gpu_indices, fully_offloaded = True, child_env = env
                                )
                                self._memory_dio_applicable = _retry_applicable
                                if _retry_dio and not self._memory_dio_flags:
                                    run_cmd = [*run_cmd, *_retry_dio]
                                    self._memory_dio_flags = list(_retry_dio)
                                    self._memory_policy_active = (
                                        _retry_active or self._memory_policy_active
                                    )
                                    logger.info(
                                        "Model Memory: applying %s for the --fit off "
                                        "retry; it offloads every layer.",
                                        " ".join(_retry_dio),
                                    )
                                self._record_memory_state(run_cmd, env)
                            _did_fit_retry = True
                            continue
                        return False

                _launched_mmproj_has_audio = self._mmproj_has_audio

                def _raise_terminal_load_failure(detail: str) -> NoReturn:
                    if _sched_abort_seen and not _load_cancelled():
                        LlamaCppBackend._record_sched_reserve_abort(binary, _abort_memo_model)
                    if intent.cpu_fallback:
                        self._cleanup_failed_cpu_fallback()
                    # No child will carry this budget; left set, the route reads it
                    # ahead of is_active and asks for a reload with nothing loaded.
                    self._vram_fraction_pending = None
                    raise RuntimeError(detail)

                def _vulkan_stall_pending() -> bool:
                    return (
                        getattr(self, "_health_wait_stalled", False)
                        and _cpu_fallback_eligible
                        and not intent.cpu_fallback
                        and not _load_cancelled()
                    )

                def _cleanup_cancelled_load(message: str) -> None:
                    logger.info(message)
                    self._cleanup_failed_cpu_fallback()
                    self._unload_audio_codec()
                    self._healthy = False
                    self._vram_fraction_pending = None

                def _finish_cancelled_health_wait(message: str) -> bool:
                    if not getattr(self, "_health_wait_cancelled", False):
                        return False
                    _cleanup_cancelled_load(message)
                    return True

                def _try_auto_vulkan_cpu_fallback(
                    failed_cmd: list[str],
                    failed_rc: Optional[int],
                    *,
                    terminal: bool = True,
                    stalled: bool = False,
                ) -> bool:
                    """Replay an eligible signal crash without devices.

                    ``terminal`` off reports a failed CPU spawn as "not recovered"
                    instead of raising, for a caller that still holds another argv
                    worth replaying. ``stalled`` replays a child that never became
                    healthy and made no loading progress (already reaped by the
                    caller), the hang a crash gate cannot see.
                    """
                    nonlocal intent, gpu_memory_mode, gpu_layers, n_cpu_moe
                    nonlocal _replay_pageable_override
                    nonlocal tensor_parallel, tensor_split, gpu_indices, use_fit, _spawn_cwd
                    # GGML_ASSERT is a signal on POSIX and a CRT abort (exit 3) on
                    # MSVC, so Windows needs both. Cancel-checked like every retry
                    # here: an /unload racing the crash must not leave a server up.
                    _crashed = stalled or (
                        self._is_signal_crash(failed_rc)
                        or (sys.platform == "win32" and self._is_abort_exit(failed_rc))
                    )
                    if not _crashed or not _cpu_fallback_eligible or _load_cancelled():
                        return False
                    fallback_has_mmproj = self._launch_has_mmproj(failed_cmd, env)
                    prepared = self._prepare_cpu_fallback_launch(
                        binary,
                        failed_cmd,
                        env,
                        server_caps,
                        drop_full_offload_threads = _drop_full_offload_threads,
                        # The same host pool the preflight and the reprice below read,
                        # so the rewrite and the advisory answer one question once.
                        avail_mib = _preflight_avail_mib,
                    )
                    if prepared is None:
                        return False
                    if _load_cancelled():
                        # This argv's drafter may be the cause, which a GPU crash does not show; keep the staged runtime.
                        _cleanup_cancelled_load("Load cancelled while staging the CPU fallback")
                        return False
                    replay, _spawn_cwd, _cpu_pageable_note = prepared
                    # The rewrite mutates the shared env in place, so it runs once across replays; carry its note forward, or a later replay reports no override.
                    if _cpu_pageable_note:
                        _replay_pageable_override = _cpu_pageable_note
                    _cpu_pageable_note = _cpu_pageable_note or _replay_pageable_override

                    logger.warning(
                        "The auto-selected Vulkan backend %s during startup; "
                        "retrying once with llama.cpp devices disabled.",
                        "stopped making progress" if stalled else "hard-crashed",
                    )
                    if not _spawn_and_wait(replay, label = "-cpu"):
                        if _finish_cancelled_health_wait(
                            "Load cancelled during the staged CPU replay health wait"
                        ):
                            return False
                        if not terminal:
                            # Record _last_spawn_cmd, the argv that started, since the replay can drop load-mode and DirectIO.
                            self._kill_process()
                            return False
                        _proc_snap1 = self._process  # snapshot: re-reading races the teardown
                        cpu_rc = _proc_snap1.poll() if _proc_snap1 is not None else None
                        detail = self._classify_llama_start_failure(
                            "\n".join(self._stdout_lines[-50:]),
                            gguf_path,
                            self._model_identifier,
                            cpu_rc,
                            binary,
                            self._llama_log_path,
                            (self._api_key,),
                            self._extra_args,
                        )
                        if _sched_abort_seen:
                            LlamaCppBackend._record_sched_reserve_abort(binary, _abort_memo_model)
                        self._cleanup_failed_cpu_fallback()
                        self._vram_fraction_pending = None
                        raise RuntimeError(detail)

                    # The replay dropped the fit's --load-mode none, so a record taken
                    # off the launch argv describes a reservation this child does not
                    # make, and a later "Don't reserve system RAM" would demand a
                    # pointless reload. From _last_spawn_cmd, the argv that really
                    # started, so this cannot undo a record a --fit retry wrote.
                    #
                    # Or the pageable override rewrote a mode this replay no longer runs
                    # with: the record has to describe the argv that started, whichever
                    # of the two changed it, or the reload comparator judges this child
                    # against a mode it does not have.
                    #
                    # Unconditional now: the replay also withdraws the managed DirectIO, a
                    # third way to go stale, and all of them land in _last_spawn_cmd.
                    self._record_memory_state(_last_spawn_cmd, env)
                    intent = self._apply_cpu_fallback_state(
                        intent,
                        reason = "vulkan_startup_stall" if stalled else "vulkan_startup_crash",
                        is_vision = fallback_has_mmproj,
                        mmproj_has_audio = (
                            _launched_mmproj_has_audio if fallback_has_mmproj else False
                        ),
                        disable_vision = disable_vision,
                        # The same expression the load's own assignment uses, since the
                        # replay carries the same switch and the same dropped projector.
                        vision_disabled_by_user = bool(
                            is_vision and disable_vision and _dv_dropped_image_projector
                        ),
                    )
                    gpu_memory_mode = intent.gpu_memory_mode
                    gpu_layers = intent.gpu_layers
                    n_cpu_moe = intent.n_cpu_moe
                    tensor_parallel = intent.tensor_parallel
                    tensor_split = intent.tensor_split
                    gpu_indices = None
                    use_fit = False
                    # Appended after the host-RAM and offload notices so it never replaces a memory warning.
                    self._reprice_after_cpu_only_fallback(
                        host_msg = _host_ram_msg,
                        cpu_cmd = _last_spawn_cmd,
                        env = env,
                        avail_mib = _preflight_avail_mib,
                        pageable_note = _cpu_pageable_note,
                    )
                    # This return skips the commit block, so record drafter state here.
                    self._mtp_draft_path = launch_mtp_draft_path
                    self._mtp_draft_suppressed_path = _suppressed_draft_path
                    self._mtp_draft_suppressed_reason = _suppressed_draft_reason
                    logger.warning(
                        "llama-server loaded successfully on CPU after the "
                        "auto-selected Vulkan backend %s. GPU acceleration "
                        "is disabled for this model session.",
                        "stalled" if stalled else "crashed",
                    )
                    return True

                def _recover_vulkan_stall(stalled_cmd: list[str]) -> bool:
                    """A probe that could not enumerate plus no loading work replays on CPU (True
                    once up, False if it could not start); any other stall fails with advice."""
                    if (
                        _vulkan_suspect
                        and getattr(self, "_health_wait_stall_kind", None) == "no_progress"
                    ):
                        return _try_auto_vulkan_cpu_fallback(stalled_cmd, None, stalled = True)
                    _why = (
                        "startup time limit reached"
                        if getattr(self, "_health_wait_stall_kind", None) == "ceiling"
                        else "no loading progress"
                    )
                    _raise_terminal_load_failure(
                        "llama-server did not finish starting on the auto-selected Vulkan "
                        f"backend ({_why}). If this keeps happening, choose CPU "
                        "in Settings > GGUF inference engine to run models without the "
                        "Vulkan driver."
                    )

                # Store the resolved on-disk path, not the caller's kwarg: in
                # HF mode gguf_path is None and ``model_path`` is what
                # llama-server mmap's, which downstream consumers need. Must be
                # set BEFORE the spawn: load_progress() reads _gguf_path for
                # the mmap progress total while the health wait runs.
                self._gguf_path = model_path
                self._gguf_load_identity = self._gguf_load_source_identity(model_path, mmproj_path)
                self._hf_repo = hf_repo
                self._mtp_draft_path = launch_mtp_draft_path
                self._mtp_draft_suppressed_path = _suppressed_draft_path
                self._mtp_draft_suppressed_reason = _suppressed_draft_reason
                # For local GGUF files, extract variant from filename if absent
                if hf_variant:
                    self._hf_variant = hf_variant
                elif gguf_path:
                    try:
                        from utils.models.model_config import _extract_quant_label
                        self._hf_variant = _extract_quant_label(gguf_path)
                    except Exception:
                        self._hf_variant = None
                else:
                    self._hf_variant = None
                self._is_vision = effective_is_vision
                self._disable_vision = bool(disable_vision)
                # is_vision, not effective_is_vision (this load detached the projector on purpose); text-only, audio-only and arg-dropped cases must not blame the switch.
                self._vision_disabled_by_user = bool(
                    is_vision and disable_vision and _dv_dropped_image_projector
                )
                self._model_identifier = model_identifier

                # Keep _context_length native for display.
                self._effective_context_length = (
                    effective_ctx if effective_ctx > 0 else self._context_length
                )
                self._max_context_length = (
                    max_available_ctx if max_available_ctx > 0 else self._effective_context_length
                )
                # The fit priced Unsloth's own placement and the base weights alone: a
                # pass-through placement override, adapter or inherited projector is not.
                if _vram_fit_ctx is not None:
                    _child_extras = (
                        self._strip_device_extra_args(extra_args)
                        if _gpu_ids_own_device_flags
                        else extra_args
                    )
                    _child_env = dict(os.environ)
                    if gpu_memory_mode == "manual":
                        self._clear_manual_placement_env(_child_env)
                    if _gpu_ids_own_device_flags:
                        self._clear_device_placement_env(_child_env)
                    if (
                        _pass_through_overrides_placement(
                            _child_extras,
                            _child_env,
                            len(gpu_indices) if gpu_indices is not None else len(gpus),
                            is_vulkan_backend = is_vulkan_backend,
                            gpu_indices = gpu_indices,
                        )
                        or _sidecar_adapter_bytes(extra_args) != 0
                        # A drafter the planner could only cover with a flat cushion.
                        or _flat_mtp_engages
                        or _child_env.get("LLAMA_ARG_MMPROJ")
                        or _child_env.get("LLAMA_ARG_MMPROJ_URL")
                        or (
                            not launch_mmproj_path
                            and extra_args_mmproj_auto(_child_extras, _child_env)
                        )
                        # A hand-set fitter or split ratio re-places what the fit priced.
                        or _extra_args_set_any_flag(_child_extras, _VRAM_FIT_VOIDING_FLAGS)
                        or any(_child_env.get(name) for name in _VRAM_FIT_VOIDING_ENV_VARS)
                        # Any surviving --device: the cap sweep may have pooled cards it leaves out.
                        or _extra_args_main_device(_child_extras) is not None
                        # And any companion (projector, drafter) pinned to a card of its own.
                        or any(
                            _extra_args_device(_child_extras, flags) is not None
                            for flags in _COMPANION_DEVICE_FLAG_GROUPS
                        )
                        or _child_env.get("LLAMA_ARG_DEVICE")
                        # --no-kv-offload keeps the whole cache in host RAM at any context.
                        or not _kv_offload_from_args(_child_extras, _child_env)
                    ):
                        _vram_fit_ctx = None
                self._vram_fit_context_length = _vram_fit_ctx

                # Past the host-RAM and offload advisories, so it can say the ceiling is
                # the request without costing the user a memory warning it does not
                # replace: appended when one of those spoke, recorded when none did.
                if _unmeasured_ctx_notice:
                    if self._last_load_warning:
                        self._amend_load_warning(" " + _unmeasured_ctx_notice)
                    else:
                        self._record_load_warning(_unmeasured_ctx_notice)

                if _cuda_ctx_notice and use_fit:  # slot reduction may have re-pinned it
                    if self._last_load_warning:
                        self._amend_load_warning(" " + _cuda_ctx_notice)
                    else:
                        self._record_load_warning(_cuda_ctx_notice)

                # Zero Vulkan devices: the bundle would still init a driver that can hang (#7213).
                _cpu_route_reason = None
                if not intent.cpu_fallback and _cpu_fallback_eligible:
                    _vk_outcome = self._vulkan_probe_outcome(binary)
                    _vulkan_suspect = _vk_outcome in ("timeout", "crashed")
                    # Only when a replay can be built, so the block below never fails the load.
                    if (
                        _vk_outcome == "none"
                        and self._cpu_isolated_replay(cmd, dict(env), server_caps) is not None
                        and self._cpu_isolated_binary(binary) is not None
                    ):
                        logger.warning(
                            "The auto-selected Vulkan backend has no usable device "
                            "(probe: %s); starting llama.cpp on CPU without loading the "
                            "Vulkan runtime.",
                            _vk_outcome,
                        )
                        intent = replace(intent, cpu_fallback = True)
                        _cpu_route_reason = "vulkan_no_device"

                # LoadRequest carries this flag, so a stale rollback, an API caller or
                # a swapped-out runtime can ask for a replay that never happened. Hold
                # it to the crash path's bar (managed auto Vulkan, no explicit
                # placement) and otherwise run the request as sent.
                if intent.cpu_fallback:
                    if self._auto_vulkan_cpu_fallback_eligible(
                        binary, intent, extra_args, env, allow_manual_cpu = True
                    ):
                        prepared = self._prepare_cpu_fallback_launch(
                            binary,
                            cmd,
                            env,
                            server_caps,
                            drop_full_offload_threads = _drop_full_offload_threads,
                            avail_mib = _preflight_avail_mib,
                        )
                        if prepared is None:
                            if _load_cancelled():
                                _cleanup_cancelled_load(
                                    "Load cancelled while reconstructing the CPU fallback"
                                )
                                return False
                            _raise_terminal_load_failure(
                                "The prior Vulkan CPU fallback could not be reconstructed; run "
                                "`unsloth studio update` to repair the managed llama.cpp runtime."
                            )
                        cmd, _spawn_cwd, _replay_pageable_note = prepared
                        # The override is new since the replay's argv was built, so it is appended to the recorded notice.
                        self._record_memory_state(cmd, env)
                        _mem_policy_for_cmd = _snapshot_policy_for_cmd()
                        # The --device none replay is CPU-only, so it needs a host-RAM advisory; an empty probe leaves none.
                        self._amend_load_warning(_replay_pageable_note)
                        # This replay is CPU-only by construction (--device none), so
                        # the advisory has to describe the whole model in host RAM. The
                        # amend above can only add to a notice that already exists, and
                        # on a restored fallback there often is none: an empty Vulkan
                        # probe leaves _child_has_no_gpu False, so the preflight
                        # abstained and memory_warning was null for a session paging
                        # everything from disk. Deferred rather than priced here,
                        # because only a child that came up is evidence of what runs.
                        _restored_cpu_reprice = _replay_pageable_note or True
                        # Same normalization the crash path applies, so a client that
                        # sent only the flag cannot leave a CPU-only server reporting
                        # an Auto/GPU placement (which then fails holds_no_vram).
                        intent = self._apply_cpu_fallback_state(
                            intent,
                            is_vision = self._is_vision,
                            mmproj_has_audio = self._mmproj_has_audio,
                            disable_vision = disable_vision,
                            vision_disabled_by_user = bool(
                                is_vision and disable_vision and _dv_dropped_image_projector
                            ),
                            reason = (
                                _cpu_route_reason
                                or self._cpu_fallback_reason
                                or "vulkan_startup_crash"
                            ),
                        )
                        gpu_memory_mode = intent.gpu_memory_mode
                        gpu_layers = intent.gpu_layers
                        n_cpu_moe = intent.n_cpu_moe
                        tensor_parallel = intent.tensor_parallel
                        tensor_split = intent.tensor_split
                        gpu_indices = None
                        use_fit = False
                    else:
                        # Clear only once a child is up, where is_active takes over; an unconditional clear undid the re-arm.
                        intent = replace(intent, cpu_fallback = False)
                        self._cpu_fallback_reason = None
                        self._cleanup_cpu_fallback_runtime()
                # _process is unset until Popen, so mark the load committed for saves; Popen and every exit below clear it, so a failed spawn cannot leave it stuck.
                self._memory_pending_launch = _mem_settings
                self._vram_fraction_pending = _budget_priced_placement()
                healthy = False
                try:
                    healthy = _spawn_and_wait(cmd)
                    if not healthy:
                        # Every recovery below relaunches a plan the fit never priced.
                        self._vram_fit_context_length = None
                finally:
                    # Old llama.cpp refuses quantized KV in tensor mode; retries cannot fix it, so latch on first spawn.
                    if healthy:
                        self._memory_pending_launch = None
                if not healthy and _finish_cancelled_health_wait(
                    "Load cancelled during the llama-server health wait"
                ):
                    return False
                # Stalled auto-Vulkan launch (#142): every rung below relaunches the same driver.
                if not healthy and _vulkan_stall_pending():
                    _stalled_cmd = list(_last_spawn_cmd)
                    self._kill_process()
                    if _recover_vulkan_stall(_stalled_cmd):
                        healthy = True
                    elif _finish_cancelled_health_wait(
                        "Load cancelled during the CPU replay health wait"
                    ):
                        return False
                # #6415 split-mode tensor warmup abort. Latch it on THIS first spawn:
                # the flash-attn-off retry below can't run tensor (needs flash_attn),
                # so its output drops the marker and recording later would miss it,
                # looping every load. Record and raise to the route's layer fallback,
                # skipping the futile flash-attn/MTP retries.
                if not healthy and self._tensor_parallel and not _load_cancelled():
                    _ts_out = "\n".join(self._stdout_lines[-50:])
                    _proc_snap2 = self._process  # snapshot: re-reading races the teardown
                    _ts_rc = _proc_snap2.poll() if _proc_snap2 is not None else None
                    if self._should_record_tensor_split_abort(
                        _ts_rc, "\n".join(self._stdout_lines)
                    ):
                        # A drafter crash must not disable tensor split for drafterless loads.
                        if not _extra_args_mtp_draft_path(
                            _last_spawn_cmd, env = _child_spec_env(extra_args)
                        ):
                            LlamaCppBackend._record_tensor_split_abort(
                                binary, model_identifier, _planned_cache_pair
                            )
                        self._kill_process()
                        raise RuntimeError(
                            "llama-server aborted on --split-mode tensor "
                            "(split-axis geometry); retrying with layer split."
                        )
                    # Pre-b9455 llama.cpp refusing a quantized KV cache in tensor mode.
                    # Latched on this first spawn for the same reason as the abort
                    # above: the retries below cannot fix a capability the binary
                    # lacks, and only the first spawn carries the marker.
                    if self._is_tensor_quant_kv_unsupported(_ts_out):
                        # Use _detected_gpus, not gpus: it survives manual mode, which empties the pool to skip the planner.
                        LlamaCppBackend._record_tensor_quant_kv_unsupported(binary)
                        self._kill_process()
                        raise RuntimeError(
                            "This llama.cpp build does not support a quantized KV "
                            "cache with --split-mode tensor (added in b9455, "
                            "ggml-org/llama.cpp#23792). Retrying with layer split; "
                            "update llama.cpp to use tensor parallelism with a "
                            "quantized cache."
                        )
                # Auto-pinned device has no kernels in this binary: retry once on a narrowed set, since the gate cannot see custom builds; explicit picks keep their error.
                if (
                    not healthy
                    and not _load_cancelled()
                    and not gpu_ids
                    and not is_vulkan_backend
                    and gpu_indices
                    and self._kernel_image_invalid("\n".join(self._stdout_lines[-80:]))
                ):
                    _crashed = sorted(set(gpu_indices))
                    # _detected_gpus, not gpus: the post-picker enumeration this launch
                    # planned against, and unlike `gpus` it survives the manual mode that
                    # empties the pool to bypass the planner.
                    _remaining = self._arch_crash_retry_gpu_ids(
                        gpu_indices, [i for i, _free in _detected_gpus]
                    )
                    if _remaining:
                        # Earlier notices priced the crashed selection; re-price on the respawn set, since first notice wins.
                        _retry_wants_unified = self._amd_apu_wants_unified_memory(_remaining)
                        _retry_unified_helps = self._unified_memory_for_launch(
                            _remaining, _unified_need_now(), opted_in = _unified_opt_in
                        )
                        # Everything recorded so far priced the CRASHED selection, and
                        # that placement is gone: the canonical #7624 shape pins the APU
                        # whose shared-pool "free memory" outranked the dGPU, warns that
                        # system RAM cannot hold the weights, then crashes and respawns
                        # on the discrete sibling that holds them in VRAM. First notice
                        # wins, so without this the served child reports a shortfall on
                        # a device it never touches. The two checks below price exactly
                        # the set the respawn reaches, and both are wider than their
                        # upstream twins (the same weights against a NARROWED pool), so
                        # a shortfall that still stands is re-recorded here.
                        #
                        # Both are also kept in a variable: the pageable-load override
                        # at the END of this block, after every rewrite `cmd` still has
                        # coming, reads them as its shortfall condition and amends
                        # whichever one first-notice-wins recorded.
                        self._begin_load_warnings()
                        # ...and the re-price snapshots go with the scope they describe:
                        # the preflight's pair priced the crashed placement, so leaving
                        # them standing would let the text-only fallback re-price the
                        # notice this block is about to record against the wrong pool.
                        _apu_ram_msg = None
                        _host_ram_msg = None
                        _apu_avail_mib = None
                        # Read before the kill frees the crashed child's memory, which would inflate the reading.
                        _retry_apu_avail_mib = (
                            self._available_system_memory_mib()
                            if model_size is not None and _retry_wants_unified
                            else None
                        )
                        _retry_host_avail_mib = self._available_system_memory_mib()
                        # host guard credited the whole pool; the respawn reaches only _remaining
                        _retry_rows = [row for row in _detected_gpus if row[0] in set(_remaining)]
                        logger.warning(
                            f"llama-server crashed with a HIP kernel-image error on "
                            f"GPU(s) {_crashed} -- the llama.cpp build has no kernels "
                            f"for that arch. Retrying on GPU(s) {_remaining}."
                        )
                        self._kill_process()
                        gpu_indices = _remaining
                        _unified_gpu_indices = _remaining
                        # The tuning was decided against the devices that just crashed,
                        # and this respawn reuses `cmd`, so a discrete-to-APU retry would
                        # carry --cache-ram 0 onto a shared pool and the reverse would
                        # reach a discrete card without it. Re-decide against the retry.
                        if sys.platform == "win32" and full_offload_tuning_active:
                            _retry_shared = _cache_target_unknown or (
                                self._offload_target_shares_system_memory(
                                    is_vulkan_backend = is_vulkan_backend,
                                    shared_gpu_ids = _shared_gpu_ids,
                                    detected_gpus = _retry_rows or _detected_gpus,
                                    gpu_indices = _remaining,
                                )
                            )
                            # Off first, or _retry_cache_tuning_flags reads the cap as a
                            # count the user typed and declines to zero it.
                            if _auto_ckpt_emitted:
                                cmd = self._without_flag_pairs(cmd, _auto_ckpt_emitted)
                                _auto_ckpt_emitted = []
                            if _retry_shared and _cache_flags_emitted:
                                # Exactly the tokens this policy appended, each a flag
                                # with its value, so the strip cannot eat a user extra.
                                cmd = self._without_flag_pairs(cmd, _cache_flags_emitted)
                                _cache_flags_emitted = []
                                logger.info(
                                    "Retry lands on a GPU that shares system memory: dropped "
                                    "--cache-ram 0 and --ctx-checkpoints 0 so the prompt cache "
                                    "survives."
                                )
                            elif not _retry_shared and not _cache_flags_emitted:
                                _retry_flags = self._retry_cache_tuning_flags(
                                    cmd,
                                    cache_ram = cache_ram,
                                    ctx_checkpoints = _ctx_checkpoints_owned,
                                    server_caps = server_caps,
                                )
                                if _retry_flags:
                                    cmd.extend(_retry_flags)
                                    _cache_flags_emitted = list(_retry_flags)
                                    logger.info(
                                        "Retry lands on a GPU with its own memory: applied the "
                                        "Windows full-offload cache tuning."
                                    )
                            _auto_ckpt_emitted = _emit_auto_ctx_checkpoints(cmd)
                        # Withdraw GGML_CUDA_ENABLE_UNIFIED_MEMORY decided for the crashed set (only our value).
                        if _unified_env_applied and not _retry_unified_helps:
                            env.pop("GGML_CUDA_ENABLE_UNIFIED_MEMORY", None)
                            _unified_env_applied = False
                            logger.info(
                                "Arch-crash retry targets GPU(s) the unified-memory "
                                "swap cannot help; dropped "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY for the respawn."
                            )
                        elif (
                            _retry_unified_helps
                            and not _unified_opt_out  # the opt-out outlives the respawn
                            and "GGML_CUDA_ENABLE_UNIFIED_MEMORY" not in env
                        ):
                            env["GGML_CUDA_ENABLE_UNIFIED_MEMORY"] = "1"
                            _unified_env_applied = True
                            logger.info(
                                "Arch-crash retry targets a unified-memory APU the "
                                "weights outgrow; set "
                                "GGML_CUDA_ENABLE_UNIFIED_MEMORY=1 for the respawn."
                            )
                        _retry_mask = list(_remaining)
                        if _companion_fit_mask is not None:
                            # tokens are positions in the crashed launch's mask
                            if _companion_added_device is not None:
                                for _k in range(len(cmd) - 1, 0, -1):
                                    if cmd[_k - 1 : _k + 1] == _companion_added_device:
                                        del cmd[_k - 1 : _k + 1]
                                        break
                            _had_main_device = _extra_args_main_device(cmd) is not None
                            _retry_mask, _refit = _widen_pin_ids_for_companion_devices(
                                cmd,
                                list(_remaining),
                                list(_companion_fit_mask),
                                allowed_ids = gpu_ids or None,
                            )
                            _companion_added_device = (
                                list(cmd[-2:])
                                if not _had_main_device and _extra_args_main_device(cmd) is not None
                                else None
                            )
                            _companion_fit_mask = list(_retry_mask)
                            if _refit:
                                logger.info(
                                    "Refitted companion device flags to the retry's mask: %s",
                                    _refit,
                                )
                        self._emit_child_gpu_visibility(
                            env, ",".join(str(i) for i in _retry_mask), prefer_rocr = True
                        )
                        _child_gpu_physical_ids = tuple(int(i) for i in _retry_mask)
                        # No ratio record here: _tensor_split is set only in manual mode, where gpu_indices stays None.
                        self._clear_split_placement_env(env)
                        # The mask re-indexes survivors, so drop a --tensor-split sized for the crashed set.
                        _arch_retry_cmd = self._without_tensor_split(cmd)
                        if _arch_retry_cmd is not None:
                            logger.info(
                                "Dropped --tensor-split for the arch-crash retry: "
                                "its shares are positional over the visible "
                                "devices and the narrowed set re-indexes them."
                            )
                            cmd = _arch_retry_cmd
                            # No ratio record, unlike the proactive gate: _tensor_split
                            # is non-None only in manual mode, which leaves gpu_indices
                            # None, and this arm needs it truthy.
                            self._tensor_split = None
                            # The auto twin, which this arm CAN reach: an auto
                            # tensor-parallel fallback emits its ratio with
                            # gpu_indices pinned. Left set it feeds the
                            # `tensor_split` property a ratio the respawned child
                            # does not have.
                            self._auto_tensor_split_emitted = None
                        # The fit's none assumed the pinned devices, and KV can exceed RAM with mmap off; drop the none.
                        if len(_remaining) < 2 and self._tensor_parallel:
                            _no_tensor_mode = self._without_flags(cmd, ("--split-mode", "-sm"))
                            if _no_tensor_mode is not None:
                                cmd = _no_tensor_mode
                            self._arch_gate_dropped_tensor_parallel = True
                            self._tensor_parallel = False
                            logger.info(
                                "Arch-crash retry leaves one GPU; dropped tensor "
                                "parallelism, which needs at least two."
                            )
                        cmd = self._drop_managed_lazy_mode(cmd, "device fallback")
                        _retry_apu_msg = None
                        if model_size is not None and _retry_wants_unified:
                            _apu_avail_mib = _retry_apu_avail_mib
                            _apu_resident_model_size = max(
                                1,
                                model_size
                                - self._lazy_read_host_bytes(
                                    model_path,
                                    caps = server_caps,
                                    extra_args = cmd,
                                    env = env,
                                    auto_resolves_off = self._lazy_auto_resolves_off(
                                        gpu_indices = _remaining,
                                        detected_gpus = _detected_gpus,
                                        shared_gpu_ids = _shared_gpu_ids,
                                        is_vulkan_backend = is_vulkan_backend,
                                        probe_integrated_cuda = False,
                                        extra_args = cmd,
                                        env = env,
                                    ),
                                ),
                            )
                            _retry_apu_msg = self._apu_ram_shortfall_message(
                                _apu_resident_model_size + _mmproj_pinned_bytes,
                                _apu_avail_mib,
                            )
                            if not self._host_offload_warning_opted_out():
                                _apu_ram_msg = _retry_apu_msg
                                self._record_load_warning(_retry_apu_msg)
                        _retry_host_msg = self._launch_host_shortfall_message(
                            cmd, _retry_rows, env, avail_mib = _retry_host_avail_mib
                        )
                        _host_ram_msg = _retry_host_msg
                        self._record_load_warning(_retry_host_msg)
                        # Restore what cmd means: a --fit retry may have recorded a page-lock that cmd never carried.
                        _fit_mode_left_cmd = bool(self._fit_load_mode_flags)
                        if self._fit_load_mode_flags:
                            cmd = _without_subsequence(cmd, self._fit_load_mode_flags)
                            self._fit_load_mode_flags = []
                            logger.info(
                                "Load mode: dropping the fit's --load-mode none for "
                                "the arch-crash retry; it runs on a different device "
                                "set than the fit was proved against."
                            )
                        # Re-asked on the narrowed set both ways, since narrowing can gain an offload the full set lacked.
                        (
                            _mem_host_resident,
                            self._memory_state,
                            self._memory_direct_io,
                            self._memory_dio_applicable,
                            self._memory_dio_flags,
                            self._memory_policy_active,
                            self._memory_mlock_applicable,
                        ) = _mem_policy_for_cmd
                        # Excluding the load-mode pair removed; record the stripped argv, not _mem_managed + _mem_extras.
                        _arch_dio, _arch_applicable, _arch_active = _dio_decision_for(
                            _remaining, fully_offloaded = fully_gpu_offloaded, child_env = env
                        )
                        self._memory_dio_applicable = _arch_applicable
                        _dio_left_cmd = False
                        if self._memory_dio_flags and not _arch_dio:
                            _dio_left_cmd = True
                            cmd = self._drop_managed_dio(
                                cmd,
                                "the arch-crash retry's remaining devices no longer "
                                "confirm a full offload",
                            )
                            self._memory_dio_applicable = _arch_applicable
                        elif _arch_dio and not self._memory_dio_flags:
                            _dio_left_cmd = True
                            cmd = [*cmd, *_arch_dio]
                            self._memory_dio_flags = list(_arch_dio)
                            self._memory_policy_active = _arch_active or self._memory_policy_active
                            logger.info(
                                "Model Memory: applying %s; the arch-crash retry's "
                                "remaining GPU(s) %s confirm a full offload.",
                                " ".join(_arch_dio),
                                _remaining,
                            )
                        # Residency follows the devices the retry changed, so re-decide the page-lock with the same helpers.
                        if _fit_mode_left_cmd or _dio_left_cmd:
                            self._record_memory_state(cmd, env)
                        # Residency is a property of the DEVICES, which the retry just
                        # changed: crash on the discrete card, land on the
                        # unified-memory APU, and the weights are host-backed after
                        # all, so the lock the first launch skipped is the one the user
                        # asked for. Left alone the respawn runs unlocked AND records
                        # _memory_mlock_applicable False, reading the missing lock as
                        # deliberate and deduping away the reload that would apply it.
                        # Through the same helpers, so the two cannot drift.
                        _retry_host_resident = self._weights_in_host_memory(
                            fully_gpu_offloaded = fully_gpu_offloaded,
                            gpu_memory_mode = gpu_memory_mode,
                            gpu_layers = gpu_layers,
                            extra_args = _mem_extra_args,
                            gpu_indices = _remaining,
                            is_vulkan_backend = is_vulkan_backend,
                            binary = binary,
                            env = env,
                            # Only adds a lock: scanning to remove valueless --mlock/--no-mmap would eat the user's extra args.
                            probe_vulkan = _mem_should_mlock or _mem_probe_for_dio,
                            fit_active = fit_is_effectively_on([*cmd, *(_mem_extra_args or [])], env),
                        )
                        # Lock-ADDING direction only: `cmd` carries a policy-emitted
                        # lock only when the first launch found the weights
                        # host-resident, so this is the one direction that adds without
                        # taking anything back off argv. Removing flags would mean
                        # scanning for --mlock/--no-mmap, VALUELESS in llama.cpp's
                        # parser, so the scan would eat the user extra after them. The
                        # reverse direction leaves the crashed launch's lock in place,
                        # which stays truthful: the child does hold it.
                        if _retry_host_resident and not _mem_host_resident:
                            _retry_managed, _ = apply_model_memory_policy(
                                extra_args,
                                supports_load_mode = load_mode_support(server_caps),
                                # Not the requested load mode: the first launch
                                # emitted it and this call only ADDS, so a second
                                # copy would land after the extras and mark
                                # _memory_policy_active for a launch it never touched.
                                weights_in_host_memory = _retry_host_resident,
                                # The launch's own pair: a save landing before this retry
                                # would otherwise pick flags this launch never saw.
                                settings = _mem_settings,
                            )
                            if _retry_managed:
                                # After the user extras, so llama.cpp's last-wins parse
                                # gives it the final say over any hand-written memory
                                # flag. Nothing is stripped, so kept extras survive.
                                cmd.extend(_retry_managed)
                            _mem_host_resident = _retry_host_resident
                            self._memory_mlock_applicable = keep_resident_lock_applicable(
                                _retry_host_resident, load_mode_support(server_caps)
                            )
                            # Stays active if it already was: the flag also
                            # covers extras this policy touched and env it
                            # scrubbed, neither of which the respawn undoes.
                            self._memory_policy_active = (
                                bool(_retry_managed) or self._memory_policy_active
                            )
                            # Runs last, after all `cmd` rewrites: an unmapped respawn on the narrowed pool OOMs in host RAM.
                            self._record_memory_state(cmd, env)
                            logger.info(
                                "Arch-crash retry changed where the weights live; "
                                "recomputed Model Memory (%s).",
                                " ".join(_retry_managed) if _retry_managed else "no page-lock",
                            )

                        # Last, because everything above still rewrites `cmd`: the
                        # tensor-split drop, the split-mode drop, the fit's load-mode
                        # strip and the re-armed page-lock. The narrowed pool is where a
                        # load that FIT its first placement can meet its first shortfall,
                        # and nothing upstream remapped it, so an unmapped respawn would
                        # allocate the whole model in host RAM and be OOM-killed. Same
                        # condition, same helper, before the respawn rather than after.
                        def _retry_is_oversized() -> bool:
                            if _retry_apu_msg or _retry_host_msg:
                                return True
                            # The opt-out silences the message, never the rewrite.
                            if not self._host_offload_warning_opted_out():
                                return False
                            return bool(
                                self._launch_host_shortfall_message(
                                    cmd,
                                    _retry_rows,
                                    env,
                                    honor_opt_out = False,
                                    avail_mib = _retry_host_avail_mib,
                                )
                            )

                        cmd, _retry_pageable_note = self._page_an_oversized_unmapped_load(
                            cmd, env, _retry_is_oversized
                        )
                        if _retry_pageable_note:
                            # Onto whichever notice first-notice-wins kept above; a
                            # suppressed one leaves the log line as the only record,
                            # which is the intended contract for the opt-out.
                            self._amend_load_warning(_retry_pageable_note)
                            # Re-price carve-out advice (dropped by _begin_load_warnings()); respawn may land on a tighter APU.
                            self._record_memory_state(cmd, env)
                        # And the carve-out advice with them. _begin_load_warnings()
                        # dropped the one priced for the crashed placement, but the
                        # respawn can land on a unified-memory APU whose allocation the
                        # same weights outgrow. Priced against `cmd` and _remaining, so
                        # the spill reported is this placement's.
                        try:
                            _retry_carveout_need = _unified_need_now(argv = cmd)
                        except Exception:
                            _retry_carveout_need = None
                        self._record_carveout_advice(
                            _remaining,
                            _retry_carveout_need,
                            is_vulkan_backend = is_vulkan_backend,
                            shared_gpu_ids = _shared_gpu_ids,
                            detected_gpus = _retry_rows or _detected_gpus,
                            target_unknown = _cache_target_unknown,
                        )
                        healthy = _spawn_and_wait(cmd, label = "-archfallback")

                # #12842: after the #7624 respawn every rung below keeps the same kernels.
                if not healthy and not _load_cancelled():
                    # Whole buffer: a Linux abort appends a debugger backtrace.
                    _cuda_image_out = "\n".join(self._stdout_lines)
                    if self._cuda_kernel_image_error(_cuda_image_out) is not None:
                        _proc_snap_ki = self._process  # snapshot: re-reading races the teardown
                        _ki_rc = _proc_snap_ki.poll() if _proc_snap_ki is not None else None
                        self._kill_process()
                        _raise_terminal_load_failure(
                            self._classify_llama_start_failure(
                                _cuda_image_out,
                                gguf_path,
                                self._model_identifier,
                                _ki_rc,
                                binary,
                                self._llama_log_path,
                                (self._api_key,),
                                self._extra_args,
                            )
                        )

                # Retry at one slot on a --kv-unified refusal, which must run ahead of the flash-
                # attn rung.
                if not healthy and not _load_cancelled():
                    _kvu_cmd = (
                        self._with_single_sequence(_last_spawn_cmd)
                        if self._is_kv_unified_refused("\n".join(self._stdout_lines))
                        else None
                    )
                    if _kvu_cmd is not None:
                        logger.warning(
                            "llama-server refused a unified KV cache with more than "
                            "one sequence; retrying with one slot and --kv-unified "
                            "dropped. Concurrent requests will queue."
                        )
                        self._kill_process()
                        if self._drop_env_single_sequence(env):
                            logger.info(
                                "Dropped inherited LLAMA_ARG_KV_UNIFIED / "
                                "LLAMA_ARG_N_PARALLEL for the single-sequence retry."
                            )
                        cmd = _kvu_cmd
                        # Read by admission control; left as-is Studio over-admits.
                        n_parallel = 1  # allow-slot-clamp: llama-server refused more
                        kv_cache_unified = False
                        # The reserve was priced for the dropped slots: reprice for one sequence.
                        if (
                            _sidecar_fit_reserve_eligible_mib
                            and _sidecar_reserve_reprice is not None
                        ):
                            cmd = _drop_sidecar_margins(
                                cmd,
                                _integrity_flags,
                                self._ctx_integrity_flags(
                                    *_integrity_args,
                                    fit_target_delta_mib = _fit_target_delta_mib,
                                    fit_target_floor_mib = _metal_fit_target_floor_mib,
                                ),
                                _sidecar_override_pairs,
                                user_args = _sidecar_user_tokens,
                            )
                            _sidecar_override_pairs.clear()
                            _sidecar_reserve_reprice = functools.partial(
                                _sidecar_reserve_reprice, _np = 1, _kv_unified = False
                            )
                            _sidecar_fit_reserve_eligible_mib = _sidecar_reserve_reprice(cmd, env)
                            _sidecar_fit_reserve_mib = 0
                        # LLAMA_ARG_SPEC_TYPE reaches the child only if extras set --spec-type; else the launch scrubs it.
                        if _auto_ckpt_emitted:
                            cmd = self._without_flag_pairs(cmd, _auto_ckpt_emitted)
                            _auto_ckpt_emitted = []
                        _auto_ctx_checkpoints = _decide_auto_ctx_checkpoints()
                        _auto_ckpt_emitted = _emit_auto_ctx_checkpoints(cmd)
                        healthy = _spawn_and_wait(cmd, label = "-single-seq")

                # FA kernels hard-crash on some ROCm builds; retry FA-off before dropping vision or MTP.
                if not healthy and not _load_cancelled():
                    _proc_snap3 = self._process  # snapshot: re-reading races the teardown
                    _fa_rc = _proc_snap3.poll() if _proc_snap3 is not None else None
                    _fa_cmd = (
                        self._with_flash_attn_off(
                            _last_spawn_cmd,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        )
                        if self._is_signal_crash(_fa_rc)
                        else None
                    )
                    if _fa_cmd is not None:
                        logger.warning(
                            "llama-server hard-crashed at startup (exit %s) with "
                            "flash attention on; retrying once with --flash-attn "
                            "off (keeps vision and MTP).",
                            _fa_rc,
                        )
                        self._kill_process()
                        # Drop an env-only quantized V cache, or the FA-off child aborts.
                        if self._drop_env_quantized_v_cache(
                            env,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        ):
                            logger.info(
                                "Dropped inherited quantized V-cache env for the "
                                "--flash-attn off retry (requires flash attention)."
                            )
                        # Also drop the env flash-attn flag; the argv rewrite cannot reach it.
                        if self._drop_env_flash_attn(env):
                            logger.info(
                                "Dropped inherited LLAMA_ARG_FLASH_ATTN for the "
                                "--flash-attn off retry."
                            )
                        _fa_cmd = _drop_fit_load_mode_for_no_flash(_fa_cmd)
                        _fa_cmd = _enable_managed_fit_for_no_flash(_fa_cmd)
                        _flash_attn_known_off = True
                        cmd = _fa_cmd
                        healthy = _spawn_and_wait(_fa_cmd, label = "-noflash")

                # MTP from Unsloth's spec flags or the user's (extra_args
                # --spec-type / LLAMA_ARG_SPEC_TYPE). The env survives to the child only
                # when the extras own --spec-type (the launch scrubs it otherwise), so
                # anything else would judge a server it is not starting.
                _launch_spec_env: Mapping[str, str] = _child_spec_env(extra_args)
                _spec_requested_mtp = any(
                    "mtp" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_mtp(extra_args, env = _launch_spec_env)
                _spec_requested_dspark = any(
                    "draft-dspark" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_dspark(extra_args, env = _launch_spec_env)
                _spec_requested_dflash = any(
                    "draft-dflash" in str(t).lower() for t in spec_flags
                ) or _extra_args_requests_dflash(extra_args, env = _launch_spec_env)
                # A paired EAGLE-3 drafter (Studio export) can abort the server the same way.
                _spec_requested_eagle3 = any("draft-eagle3" in str(t).lower() for t in spec_flags)
                # Any MTP launch, not only tensor: a respawn would replay a drafter that
                # aborts every decode (#13253). Cleared if the MTP-drop fallback wins.
                _mtp_active_for_launched_server = bool(_spec_requested_mtp)
                # MTP can pass /health then crash the flash-attn kernel on the
                # first decode under tensor; probe one generation so the fallback
                # catches that too. Tensor-only, so ordinary MTP stays probe-free.
                if (
                    healthy
                    and self._tensor_parallel
                    and _spec_requested_mtp
                    and not _load_cancelled()
                    and not self._probe_mtp_decode()
                ):
                    # A first-decode hard fault is usually the FA kernel: retry
                    # FA-off (keeps MTP) before dropping speculative decoding below.
                    _proc_snap4 = self._process  # snapshot: re-reading races the teardown
                    _probe_rc = _proc_snap4.poll() if _proc_snap4 is not None else None
                    _fa_cmd = (
                        self._with_flash_attn_off(
                            _last_spawn_cmd,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        )
                        if self._is_signal_crash(_probe_rc)
                        else None
                    )
                    healthy = False
                    if _fa_cmd is not None:
                        logger.warning(
                            "MTP first-decode hard-crashed (exit %s) with flash "
                            "attention on; retrying with --flash-attn off.",
                            _probe_rc,
                        )
                        self._kill_process()
                        # Same reach gap: argv drops a bare --flash-attn, but an env LLAMA_ARG_FLASH_ATTN still enables it.
                        if self._drop_env_quantized_v_cache(
                            env,
                            mla = self._target_kv_symmetry(),
                            draft_mla = self._draft_kv_symmetry(_last_spawn_cmd, env),
                        ):
                            logger.info(
                                "Dropped inherited quantized V-cache env for the "
                                "--flash-attn off retry (requires flash attention)."
                            )
                        # Same reach problem for the flag itself: where the rewrite
                        # could only drop a bare --flash-attn, the env var alone
                        # still enables it.
                        if self._drop_env_flash_attn(env):
                            logger.info(
                                "Dropped inherited LLAMA_ARG_FLASH_ATTN for the "
                                "--flash-attn off retry."
                            )
                        _fa_cmd = _drop_fit_load_mode_for_no_flash(_fa_cmd)
                        _fa_cmd = _enable_managed_fit_for_no_flash(_fa_cmd)
                        _flash_attn_known_off = True
                        cmd = _fa_cmd
                        healthy = (
                            _spawn_and_wait(_fa_cmd, label = "-noflash-mtp")
                            and self._probe_mtp_decode()
                        )
                    if not healthy:
                        logger.warning(
                            "MTP speculative decoding crashed on the first decode "
                            "under tensor parallelism; retrying without it."
                        )
                # Retry once with --spec-default on MTP abort; keep requested argv (GPU init crash is not drafter's fault) and _requested_spec_mode to stop /load thrash.
                _spec_cpu_replay_cmd: Optional[List[str]] = None
                if (
                    not healthy
                    and (
                        _spec_requested_mtp
                        or _spec_requested_dspark
                        or _spec_requested_dflash
                        or _spec_requested_eagle3
                    )
                    and not _load_cancelled()
                ):
                    _spec_cpu_replay_cmd = list(_last_spawn_cmd)
                    # Launched without spec group; keep MTP only in requested state or the next Apply repeats the crash.
                    _lo = "\n".join(self._stdout_lines).lower()
                    # Only an unknown arch proves the binary is outdated; other failures are runtime.
                    _arch_unsupported = "unknown model architecture" in _lo
                    if (
                        _arch_unsupported
                        or "failed to measure draft model memory" in _lo
                        or "failed to measure mtp context memory" in _lo
                        or "failed to create mtp context" in _lo
                        or "failed to create llama_context" in _lo
                    ):
                        _retry_reason = (
                            "the prebuilt may predate it; retrying without "
                            "speculative decoding -- run `unsloth studio "
                            "update` for this drafter"
                        )
                        self._spec_fallback_reason = (
                            "binary_outdated" if _arch_unsupported else "runtime_error"
                        )
                    else:
                        _retry_reason = (
                            "retrying without speculative decoding in case the drafter is the cause"
                        )
                        self._spec_fallback_reason = "runtime_error"
                    _drafter = (
                        Path(launch_mtp_draft_path).name
                        if launch_mtp_draft_path
                        else "embedded head"
                    )
                    logger.warning(
                        "llama-server failed to start with speculative drafter (%s); %s.",
                        _drafter,
                        _retry_reason,
                    )
                    self._kill_process()
                    # Re-locate the spec block: the arch gate may have shifted it.
                    _spec_at = _subsequence_index(cmd, spec_flags, _spec_start)
                    _fb_tail = cmd[_spec_at + len(spec_flags) :]
                    _fb_stripped_extras: Optional[List[str]] = None
                    # Spec types accumulate, so the extras/env MTP must be removed, not overridden.
                    if (
                        _extra_args_requests_mtp(extra_args, env = _launch_spec_env)
                        or _extra_args_requests_dspark(extra_args, env = _launch_spec_env)
                        or _extra_args_requests_dflash(extra_args, env = _launch_spec_env)
                    ):
                        _fb_tail = strip_shadowing_flags(
                            _fb_tail,
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                        for _fb_spec_var in _SPEC_ENV_VARS:
                            env.pop(_fb_spec_var, None)
                        _fb_stripped_extras = strip_shadowing_flags(
                            extra_args or [],
                            strip_context = False,
                            strip_cache = False,
                            strip_spec = True,
                            strip_template = False,
                            strip_split_mode = False,
                        )
                    fallback_cmd = cmd[:_spec_at] + ["--spec-default"] + _fb_tail
                    # A user-owned drafter in the extras or env still loads and keeps its reserve.
                    if _sidecar_fit_reserve_mib and not _extra_args_mtp_draft_path(
                        fallback_cmd, env = env
                    ):
                        _fb_integrity = self._ctx_integrity_flags(
                            *_integrity_args,
                            fit_target_delta_mib = _fit_target_delta_mib,
                            fit_target_floor_mib = _metal_fit_target_floor_mib,
                        )
                        fallback_cmd = _drop_sidecar_margins(
                            fallback_cmd,
                            _integrity_flags,
                            _fb_integrity,
                            _sidecar_override_pairs,
                            user_args = _sidecar_user_tokens,
                        )
                    # Restore the cut slots; if they fail (unified KV refused), retry as cut.
                    _fb_cut = (
                        (
                            fallback_cmd,
                            n_parallel,
                            effective_ctx,
                            (self._effective_context_length, self._max_context_length),
                            _auto_ctx_checkpoints,
                            _auto_ckpt_emitted,
                        )
                        if _mtp_slots_asked is not None
                        else None
                    )
                    if _fb_cut is not None:
                        n_parallel = _mtp_slots_asked
                        fallback_cmd = _with_parallel_slots(
                            fallback_cmd,
                            n_parallel,
                            n_batch = n_batch,
                            supports_kv_unified = bool(server_caps.get("supports_kv_unified")),
                        )
                        # The cut may have bought context; the restored count was priced at this.
                        if _mtp_slots_target_ctx and "-c" in fallback_cmd:
                            effective_ctx = _mtp_slots_target_ctx
                            fallback_cmd[fallback_cmd.index("-c") + 1] = str(effective_ctx)
                            # The ceiling was priced at the cut count; this is the one proven here.
                            self._effective_context_length = self._max_context_length = (
                                effective_ctx
                            )
                        # The checkpoint cap is per slot; same re-decide as the single-seq rung.
                        if _auto_ckpt_emitted:
                            fallback_cmd = self._without_flag_pairs(
                                fallback_cmd, _auto_ckpt_emitted
                            )
                        _auto_ctx_checkpoints = _decide_auto_ctx_checkpoints()
                        _auto_ckpt_emitted = _emit_auto_ctx_checkpoints(fallback_cmd)
                        kv_cache_unified = _kv_unified_from_args(fallback_cmd)
                        # The plan other loads place against was priced at the cut count.
                        _fb_cut_plan = dict(self._pending_plan_mib)
                        if self._pending_plan_mib and self._can_estimate_kv():
                            kv_cache_bytes = self._estimate_kv_cache_bytes(
                                effective_ctx,
                                cache_type_kv,
                                n_parallel = n_parallel,
                                swa_full = swa_full,
                                kv_unified = bool(kv_cache_unified),
                                n_ubatch = _ubatch_for_slots(n_parallel),
                                flash_attn = planned_flash_attn,
                            )
                            self._pending_plan_mib = _gpu_plan_mib(
                                max(1, gguf_size - _host_input_embd) + mmproj_size + kv_cache_bytes,
                                list(self._pending_plan_mib),
                                gpus,
                            )
                    _unified_withdraw_if_unneeded(
                        fallback_cmd,
                        mtp_engages = False,
                        why = "The retry without speculative decoding",
                    )
                    healthy = _spawn_and_wait(fallback_cmd, label = "-retry")
                    if not healthy and _fb_cut is not None and not _load_cancelled():
                        logger.warning(
                            "The retry without speculative decoding failed at %d slots; "
                            "retrying at the %d the drafter launch ran.",
                            n_parallel,
                            _fb_cut[1],
                        )
                        self._kill_process()
                        (
                            fallback_cmd,
                            _fb_slots,
                            effective_ctx,
                            (self._effective_context_length, self._max_context_length),
                            _auto_ctx_checkpoints,
                            _auto_ckpt_emitted,
                        ) = _fb_cut
                        self._pending_plan_mib = _fb_cut_plan
                        n_parallel = (
                            _fb_slots  # allow-slot-clamp: the restored count failed to start
                        )
                        kv_cache_unified = _kv_unified_from_args(fallback_cmd)
                        healthy = _spawn_and_wait(fallback_cmd, label = "-retry-cut")
                    if healthy:
                        self._speculative_type = "default"
                        _mtp_active_for_launched_server = False
                        # The record below stores extra_args as what LAUNCHED, but this
                        # server launched without the spec group. Leaving the MTP list
                        # there would have the next inheriting Apply pick it back up and
                        # repeat the crash. Keep it as the requested state only, the way
                        # the runtime-crash replay does.
                        if _fb_stripped_extras is not None:
                            _pv_suppressed_spec_extra_args = (
                                _pv_suppressed_spec_extra_args
                                if _pv_suppressed_spec_extra_args is not None
                                else list(extra_args or [])
                            )
                            extra_args = _fb_stripped_extras

                # A stalled later retry: a live child has no exit code for the crash gate.
                if not healthy and _vulkan_stall_pending():
                    _stalled_cmd = list(_last_spawn_cmd)
                    self._kill_process()
                    if _recover_vulkan_stall(_stalled_cmd):
                        healthy = True
                    elif _finish_cancelled_health_wait(
                        "Load cancelled during the CPU replay health wait"
                    ):
                        return False

                # Keep a multimodal model multimodal when only its GPU projector
                # placement fails. llama.cpp owns mmproj offload separately from
                # --gpu-layers, so retry it on CPU before removing --mmproj.
                if not healthy:
                    out = "\n".join(self._stdout_lines[-50:])
                    # Read the crash code before _kill_process() clears _process.
                    _proc_snap5 = self._process  # snapshot: re-reading races the teardown
                    _crash_rc = _proc_snap5.poll() if _proc_snap5 is not None else None
                    self._kill_process()
                    # Only when the wait itself was cancelled; a later cancel must still run the CPU fallback.
                    if _finish_cancelled_health_wait(
                        "Load cancelled during the llama-server health wait"
                    ):
                        return False
                    # Projector moves to host RAM, outside the fit proofs; strip Unsloth's --load-mode only, keep record.
                    _projector_msg = self._is_projector_incompatibility(out)
                    _projector_memory = self._is_gpu_memory_start_failure(out)
                    _signal_mmproj_guess = self._is_signal_crash(
                        _crash_rc
                    ) and not self._output_has_nonprojector_diagnostic(out)
                    if (
                        launched_with_mmproj
                        and not _load_cancelled()
                        and (_projector_msg or _projector_memory or _signal_mmproj_guess)
                    ):
                        _vision_gpu_cmd = list(_last_spawn_cmd)
                        _cpu_projector_cmd = None
                        if not _projector_msg and _paravirtual_mmproj_pinnable(server_caps):
                            _cpu_projector_cmd = self._with_mmproj_offload_disabled(
                                _vision_gpu_cmd, env
                            )

                        if _cpu_projector_cmd is not None:
                            # The fit priced the projector as GPU-eligible, and this
                            # retry moves those bytes into host RAM, so neither the
                            # VRAM-only proof (which never asked what RAM holds) nor the
                            # VRAM-plus-RAM one (answered with the projector on the card)
                            # covers the launch this respawns. Only Unsloth's own tokens;
                            # a user's --load-mode is theirs. The record is NOT cleared:
                            # the fallbacks below respawn from an argv that carries these
                            # tokens and has to be able to name them.
                            if self._fit_load_mode_flags:
                                _stripped_cpu_projector_cmd = _without_subsequence(
                                    _cpu_projector_cmd, self._fit_load_mode_flags
                                )
                                if _stripped_cpu_projector_cmd != _cpu_projector_cmd:
                                    # Same as the no-flash rung: the record follows the
                                    # argv, or a stale "reserving" spends a full reload
                                    # the running server already satisfies.
                                    self._record_memory_state(_stripped_cpu_projector_cmd, env)
                                    logger.info(
                                        "Load mode: dropping the fit's --load-mode none "
                                        "for the CPU-projector retry; it moves the "
                                        "projector into host RAM the fit credited to VRAM."
                                    )
                                _cpu_projector_cmd = _stripped_cpu_projector_cmd
                            # The managed pair stays: this retry moves the PROJECTOR, which
                            # clip.cpp loads through its own ifstream, and the main model is
                            # still fully offloaded. The block above is the fit's VRAM
                            # accounting, which the move really does void.
                            logger.warning(
                                "llama-server failed while loading this model's GPU "
                                "vision projector (--mmproj); retrying with the "
                                "projector on CPU to preserve image input."
                            )
                            cmd = _cpu_projector_cmd
                            _unified_withdraw_if_unneeded(
                                cmd, why = "The retry with the projector on CPU"
                            )
                            healthy = _spawn_and_wait(cmd, label = "-mmproj-cpu")
                            if healthy:
                                self._mmproj_fallback_reason = "cpu_offload"
                                logger.warning(
                                    "Vision projector loaded on CPU after GPU startup "
                                    "failed; image input remains available for this session."
                                )
                            else:
                                _cpu_projector_out = "\n".join(self._stdout_lines[-50:])
                                # Snapshot: re-reading races the teardown.
                                _proc_snap6 = self._process
                                _cpu_projector_rc = (
                                    _proc_snap6.poll() if _proc_snap6 is not None else None
                                )
                                self._kill_process()
                                if _finish_cancelled_health_wait(
                                    "Load cancelled during the CPU-projector health wait"
                                ):
                                    return False
                                if _load_cancelled():
                                    _cleanup_cancelled_load(
                                        "Load cancelled after the CPU-projector health wait"
                                    )
                                    return False
                                if self._is_projector_incompatibility(_cpu_projector_out):
                                    _projector_msg = True
                                elif self._is_gpu_memory_start_failure(_cpu_projector_out):
                                    # The projector was already off the GPU, so removing it
                                    # cannot repair this allocation failure; keep the real error.
                                    _raise_terminal_load_failure(
                                        self._classify_llama_start_failure(
                                            _cpu_projector_out,
                                            gguf_path,
                                            self._model_identifier,
                                            _cpu_projector_rc,
                                            binary,
                                            self._llama_log_path,
                                            (self._api_key,),
                                            self._extra_args,
                                        )
                                    )
                        elif _projector_memory and _paravirtual_mmproj_pinnable(server_caps):
                            # An env/argv pin already put mmproj on CPU. Text-only
                            # cannot free additional GPU memory, so surface the OOM.
                            _raise_terminal_load_failure(
                                self._classify_llama_start_failure(
                                    out,
                                    gguf_path,
                                    self._model_identifier,
                                    _crash_rc,
                                    binary,
                                    self._llama_log_path,
                                    (self._api_key,),
                                    self._extra_args,
                                )
                            )

                        if not healthy:
                            if _projector_msg:
                                logger.warning(
                                    "llama-server could not load this model's vision "
                                    "projector (--mmproj). The installed llama.cpp build is "
                                    "likely too old for it. Loading text-only for this "
                                    "session; run 'unsloth studio update' to enable vision."
                                )
                                self._mmproj_fallback_reason = "projector_incompatible"
                            else:
                                logger.warning(
                                    "llama-server could not start with this model's vision "
                                    "projector (--mmproj), including the CPU-projector "
                                    "recovery when available. Retrying text-only for this "
                                    "session; check memory, GPU/driver logs, or update Unsloth."
                                )
                                self._mmproj_fallback_reason = "projector_startup_failure"
                            cmd = self._strip_mmproj_args(_vision_gpu_cmd)
                            cmd = self._drop_managed_lazy_mode(cmd, "text-only retry")
                            # Keep a trailing sidecar pair: rewriting it would drop the drafter's
                            # reserve.
                            if [
                                "--fit-target",
                                str(_last_flag_value(cmd, {"-fitt", "--fit-target"})),
                            ] not in _sidecar_override_pairs:
                                cmd = self._per_device_fit_target_argv(
                                    cmd, env, _fit_target_margins_by_idx
                                )
                            _unified_withdraw_if_unneeded(cmd, why = "The text-only retry")
                            # This retry bypasses _spawn_and_wait, so refresh the launched-argv snapshot here.
                            _last_spawn_cmd = list(cmd)
                            self._is_vision = False
                            self._mmproj_has_audio = False
                            if not self._start_llama_process(
                                cmd,
                                env,
                                child_gpu_physical_ids = _child_gpu_physical_ids,
                            ):
                                # Repriced here: a failed text-only retry can replay the vision argv on CPU, loading the projector.
                                _cleanup_cancelled_load("App shut down during the text-only retry")
                                return False
                            _textonly_timeout, _textonly_kwargs = _vulkan_wait_args("-textonly")
                            if self._wait_for_health(
                                timeout = _textonly_timeout,
                                cancelled = _load_cancelled,
                                **_textonly_kwargs,
                            ):
                                healthy = True
                                # The child that serves this session never read the
                                # CPU-pinned projector, so the host-memory advisory the
                                # APU preflight charged it against is now describing a
                                # load nothing is running. Priced again here, and not at
                                # the strip above, because a failed text-only retry can
                                # still replay the ORIGINAL vision argv on CPU further
                                # down -- projector and all -- and that child does load
                                # the bytes. Only a healthy text-only server is evidence.
                                self._reprice_after_dropping_pinned_projector(
                                    apu_msg = _apu_ram_msg,
                                    host_msg = _host_ram_msg,
                                    model_size = _apu_resident_model_size,
                                    pinned_bytes = _mmproj_pinned_bytes,
                                    avail_mib = _apu_avail_mib,
                                    part = _apu_ram_part,
                                )
                            else:
                                # Read the exit code before _kill_process() clears it, so
                                # an OS-killed text-only retry still gets the OOM message.
                                # Snapshot: re-reading races the teardown.
                                _retry_proc = self._process
                                _retry_rc = _retry_proc.poll() if _retry_proc is not None else None
                                # This retry bypasses _spawn_and_wait's abort detection.
                                if _retry_rc not in (None, 0) and self._is_sched_reserve_abort(
                                    "\n".join(self._stdout_lines[-200:])
                                ):
                                    _sched_abort_seen = True
                                self._kill_process()
                                if _finish_cancelled_health_wait(
                                    "Load cancelled during the text-only retry health wait"
                                ):
                                    return False
                                if _vulkan_stall_pending():
                                    if _recover_vulkan_stall(
                                        _last_spawn_cmd if _projector_msg else _vision_gpu_cmd
                                    ):
                                        healthy = True
                                        # The replay carries the original vision argv, as below.
                                        if not _projector_msg:
                                            self._mmproj_fallback_reason = None
                                    elif _finish_cancelled_health_wait(
                                        "Load cancelled during the CPU replay health wait"
                                    ):
                                        return False
                                # A text-only signal crash is independent evidence of a GPU
                                # startup fault. Keep a confirmed bad projector out of the
                                # replay; a guessed one still gets a CPU try with vision.
                                if not healthy and self._is_signal_crash(_retry_rc):
                                    _cpu_replay_cmd = (
                                        _last_spawn_cmd if _projector_msg else _vision_gpu_cmd
                                    )
                                    if _try_auto_vulkan_cpu_fallback(
                                        _cpu_replay_cmd,
                                        _retry_rc,
                                    ):
                                        healthy = True
                                        # A whole-runtime CPU replay with the original
                                        # vision argv supersedes the text-only diagnosis.
                                        if not _projector_msg:
                                            self._mmproj_fallback_reason = None
                                    else:
                                        if _finish_cancelled_health_wait(
                                            "Load cancelled during the CPU replay health wait"
                                        ):
                                            return False
                                        _raise_terminal_load_failure(
                                            self._gpu_init_crash_message(binary)
                                        )
                                if not healthy:
                                    _retry_detail = self._classify_llama_start_failure(
                                        "\n".join(self._stdout_lines[-50:]),
                                        gguf_path,
                                        self._model_identifier,
                                        _retry_rc,
                                        binary,
                                        self._llama_log_path,
                                        (self._api_key,),
                                        self._extra_args,
                                    )
                                    if _finish_cancelled_health_wait(
                                        "Load cancelled during the text-only recovery"
                                    ):
                                        return False
                                    _raise_terminal_load_failure(
                                        self._mmproj_retry_failure_message(
                                            projector_confirmed = _projector_msg,
                                            detail = _retry_detail,
                                        )
                                    )
                    else:
                        # Try the drafter launch non-terminally so the drafterless argv can still recover; snapshot that argv, since a spawned replay rebinds _last_spawn_cmd.
                        _drafterless_cpu_replay_cmd = list(_last_spawn_cmd)
                        _replayed = _spec_cpu_replay_cmd is not None and (
                            _try_auto_vulkan_cpu_fallback(
                                _spec_cpu_replay_cmd, _crash_rc, terminal = False
                            )
                        )
                        if _replayed:
                            # The drafter came back with the replay, so the
                            # speculative-disable diagnosis no longer holds.
                            self._spec_fallback_reason = None
                        elif _try_auto_vulkan_cpu_fallback(_drafterless_cpu_replay_cmd, _crash_rc):
                            _replayed = True
                        if _replayed:
                            healthy = True
                        else:
                            if _finish_cancelled_health_wait(
                                "Load cancelled during the CPU replay health wait"
                            ):
                                return False
                            _raise_terminal_load_failure(
                                self._classify_llama_start_failure(
                                    out,
                                    gguf_path,
                                    self._model_identifier,
                                    _crash_rc,
                                    binary,
                                    self._llama_log_path,
                                    (self._api_key,),
                                    self._extra_args,
                                )
                            )

                if _restored_cpu_reprice is not None:
                    # Micro-batch uses the LAUNCHED slot count: the drafter drop and non-MTP retry hand slots back later.
                    self._reprice_after_cpu_only_fallback(
                        host_msg = _host_ram_msg,
                        cpu_cmd = _last_spawn_cmd or cmd,
                        env = env,
                        avail_mib = _preflight_avail_mib,
                        pageable_note = (
                            _restored_cpu_reprice
                            if isinstance(_restored_cpu_reprice, str)
                            else None
                        ),
                    )
                if not self._publish_healthy():
                    # Teardown began after the 200; publishing would report a model that is gone.
                    _cleanup_cancelled_load("App shut down as the load was completing")
                    return False
                self._commit_effective_parallel_slots(n_parallel)
                self._swa_full = swa_full
                self._kv_cache_unified = kv_cache_unified
                # Request's pair beside the launched one: the matcher must use it, else repeat loads are rejected.
                _launched_ubatch = _ubatch_for_slots(n_parallel)
                self._n_ubatch = max(
                    0,
                    int(self._DEFAULT_N_UBATCH if _launched_ubatch is None else _launched_ubatch),
                )
                # What the child is RUNNING: the same architecture rule the plan above used.
                self._flash_attn_enabled = _flash_attn_enabled_from_args(
                    _last_spawn_cmd, default = not _flash_attn_known_off, env = env
                ) and not _architecture_forces_flash_attn_off(self._architecture)
                self._effective_cache_types = _effective_main_cache_types(
                    _last_spawn_cmd,
                    env,
                )
                # The pair the REQUEST resolved to, kept beside the pair that launched.
                # A launch-time rewrite makes them differ (no --flash-attn resets a
                # quantized V cache to f16, as does the flash-attn crash recovery), and
                # the matcher wants the request: comparing the running pair against an
                # unrewritten request rejects every identical repeat load.
                self._requested_cache_types = _planned_cache_pair
                self._kv_cache_context_total = effective_ctx if effective_ctx > 0 else None

                # -- the length --fit chose, or a --parallel slot split -- so the
                # Adopt the context the server allocated (--fit or slot split); clear video state first, or a swap to a model without video inherits the old answer.
                self._has_video_input = False
                # Use _extra_args_as_requested: the drafter-drop snapshot would restore the Metal zero-context strip.
                self._reconcile_effective_ctx_with_server(ctx_override or 0)
                if self._kv_cache_context_total is not None:
                    self._n_ubatch = min(
                        self._n_ubatch,
                        self._kv_cache_context_total,
                    )

                # Commit caller intent only after _healthy, so a failed start cannot poison the next inheritance check. None keeps prior, [] clears, list sets.
                if extra_args is not None:
                    # Persist device-stripped extras so a later reload cannot resurrect the dropped --device.
                    self._extra_args = (
                        self._strip_device_extra_args(extra_args)
                        if _gpu_ids_own_device_flags
                        else list(extra_args)
                    )
                    # Budget this child was sized for; None if placement never used it. Committed with known-good state.
                    _pv_requested = (
                        _extra_args_as_requested
                        if _extra_args_as_requested is not None
                        else (
                            _pv_suppressed_spec_extra_args
                            if _pv_suppressed_spec_extra_args is not None
                            else extra_args
                        )
                    )
                    self._requested_extra_args = (
                        self._strip_device_extra_args(_pv_requested)
                        if _gpu_ids_own_device_flags
                        else list(_pv_requested)
                    )
                    self._extra_args_source = (model_identifier, hf_variant)
                # A re-fit replay records what launched, which is what the client replays next.
                self._requested_n_ctx = int(effective_ctx if _replayed_ctx_refit else n_ctx)
                # Local n_parallel may have been reduced above; the snapshot has the ask.
                self._requested_n_parallel = max(1, int(intent.n_parallel))
                self._slots_cut_for_drafter = (
                    _mtp_slots_asked is not None and n_parallel < _mtp_slots_asked
                )
                # Commit with the rest of the known-good state: only a launch that got
                # this far replaced the runtime, so a rejected preflight leaves the old
                # marker intact, and the diffusion runner returns well before it without
                # consuming, or paying for, any llama-server capability.
                self._capability_probe_inconclusive = _launch_probe_inconclusive
                # The budget this child was sized against, committed with the rest of
                # the known-good state so a duplicate-load fast path or failed launch
                # leaves the previous marker intact and the route keeps asking for the
                # reload. None when placement never used it (_budget_priced_placement).
                self._vram_fraction_launched = _budget_priced_placement()
                self._vram_fraction_pending = None
                self._requested_n_batch = intent.n_batch
                self._requested_n_ubatch = intent.n_ubatch
                self._requested_load_mode = intent.load_mode
                self._requested_spec_draft_cache_type = intent.spec_draft_cache_type
                self._requested_ctx_checkpoints = intent.ctx_checkpoints
                self._requested_cache_ram = intent.cache_ram
                # Commit the known-good snapshot + whether MTP is live, then
                # watch this load for a mid-generation crash. The verified-cache hint is
                # dropped: a respawn replays this snapshot arbitrarily later, so recovery
                # re-resolves the file instead of trusting a path this request verified.
                self._last_load_intent = replace(intent, verified_gguf = None)
                if not getattr(_AUTO_RECOVERY_LOAD, "active", False):
                    # A caller's load starts a fresh OOM episode; only automatic recovery carries
                    # the strike count.
                    self._metal_oom_strikes = None
                    self._metal_oom_terminal_key = None
                self._mtp_runtime_fallback_active = _mtp_active_for_launched_server
                self._start_mtp_crash_watchdog()

                # Catch silent CPU fallback when GPU was intended; a deliberate zero-offload load must read False, not None, or training needlessly unloads it.
                _deliberate_cpu_only = (
                    gpu_memory_mode == "manual" and gpu_layers == 0
                ) or _arch_gate_forced_cpu
                # Publish on every load so a stale value is never read for the new child.
                self._arch_gate_forced_cpu = bool(_arch_gate_forced_cpu)
                if _arch_gate_forced_cpu:
                    # False, never None: training spares only an exactly-False server.
                    self._gpu_offload_active = False
                elif _deliberate_cpu_only:
                    self._gpu_offload_active = self._zero_offload_gpu_flag(
                        _last_spawn_cmd, _detected_gpus, env
                    )
                else:
                    self._gpu_offload_active = self._classify_gpu_offload(
                        gpu_indices is not None or use_fit or gpu_memory_mode == "manual",
                        _detected_gpus,
                    )
                # CPU-only hosts log 0/N too, so a zero needs an expected GPU; a positive count stands.
                _offload_counts = (
                    None
                    if _arch_gate_forced_cpu or _deliberate_cpu_only
                    else parse_gpu_offload_counts(self._stdout_lines)
                )
                if (
                    _offload_counts is not None
                    and _offload_counts[0] <= 0
                    and not (
                        (_detected_gpus or _metal_capable_host())
                        and (gpu_indices is not None or use_fit or gpu_memory_mode == "manual")
                    )
                ):
                    _offload_counts = None
                self._gpu_offload_layers = _offload_counts
                self._weight_placement = parse_weight_placement(
                    self._stdout_lines,
                    _gguf_set_bytes(Path(self._gguf_path)) if self._gguf_path else None,
                )
                self._gpu_backend_unavailable = bool(_detected_gpus or _metal_capable_host()) and (
                    llama_saw_gpu_device(self._stdout_lines) is False
                )
                # Not _GPU_OFFLOAD_OVERRIDE_FLAGS: --fit on is exactly the split to report.
                self._offload_overridden = (
                    _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
                    or _device_selection_is_cpu(
                        self._strip_device_extra_args(extra_args)
                        if _gpu_ids_own_device_flags
                        else extra_args,
                        env,
                    )
                    or _env_fixes_gpu_layers(env)
                )
                if (
                    self._gpu_offload_layers is not None
                    and 0 < self._gpu_offload_layers[0] < self._gpu_offload_layers[1]
                ):
                    logger.warning(
                        "llama-server offloaded %d of %d layers to GPU; the rest run on "
                        "CPU, which is much slower for a dense model.",
                        self._gpu_offload_layers[0],
                        self._gpu_offload_layers[1],
                    )
                if self._gpu_offload_active is False and not _deliberate_cpu_only:
                    logger.warning(
                        "llama-server appears to have loaded the model entirely "
                        "on CPU even though Unsloth detected at least one GPU. "
                        "This usually means the prebuilt binary's GPU backend "
                        "failed to load -- on Windows, cudart64_X.dll / "
                        "cublas64_X.dll could not be resolved. Reinstall the "
                        "Unsloth llama.cpp prebuilt or install a matching CUDA "
                        "toolkit (issue unslothai/unsloth#5106).",
                    )

                logger.info(
                    f"llama-server ready on port {self._port} for model '{model_identifier}'"
                )
                # Poll llama-server /metrics -> vLLM-style engine_stats logs
                # (only when the binary exposes /metrics).
                if server_caps.get("supports_metrics"):
                    try:
                        from core.inference.llama_stats import maybe_start_stats_logger
                        if self._stats_logger is not None:
                            self._stats_logger.stop()
                        self._stats_logger = maybe_start_stats_logger(
                            self.base_url, logger, headers = self._auth_headers
                        )
                    except Exception as e:
                        logger.debug(f"engine-stats logger not started: {e}")
                else:
                    self._stats_logger = None

            # Probe outside _lock (interruptible by /unload); init inside.
            self._is_audio = False
            self._audio_type = None
            self._audio_probed = False
            self._has_audio_input = False
            try:
                detected = self._detect_audio_type_strict()
                self._audio_probed = True
            except Exception as exc:
                logger.debug("Audio probe failed: %s", exc)
                detected = None
            applied_audio = (
                self._apply_detected_audio(detected)
                if intent.audio_codec_path is None
                else self._apply_detected_audio(detected, intent.audio_codec_path)
            )
            if not applied_audio:
                return False

            if not self._healthy:
                return False
            if _load_cancelled():
                # Cancelled during the post-health setup or the audio probe. Publishing
                # now leaves the child resident while the cancel route sees is_loaded.
                _cleanup_cancelled_load(
                    "Load cancelled after llama-server became healthy; unwinding"
                )
                return False
            # Snapshot loaded files so save_slots_for_resume() can refuse after on-disk swaps.
            if self._slot_save_dir:
                self._slot_loaded_identity = (
                    self._gguf_file_identity(self._gguf_path),
                    self._slot_launch_fingerprint(),
                )
            return True

    def _build_speculative_flags(
        self,
        *,
        speculative_type: Optional[str],
        spec_draft_n_max: Optional[int],
        extra_args: Optional[List[str]],
        model_identifier: str,
        model_path: Optional[str],
        gpus: bool,
        binary: Optional[str],
        mtp_draft_path: Optional[str] = None,
        dspark_draft_path: Optional[str] = None,
        dspark_fit_sized: bool = True,
        dflash_draft_path: Optional[str] = None,
        dflash_fit_sized: bool = True,
        drafter_no_vram: bool = False,
        embedded_mtp_partial_offload: bool = False,
        draft_device: Optional[str] = None,
        mtp_drafter_unloadable: bool = False,
        eagle3_draft_path: Optional[str] = None,
        mtp_trained: Optional[bool] = None,
    ) -> List[str]:
        """Returns spec flags; sets speculative type, requested mode, draft n-max. Auto uses ngram-mod for sub-3B embedded MTP (regresses); separate drafters exempt."""
        flags: List[str] = []
        # Reset; emit branches re-set on the resolved emission.
        self._spec_draft_n_max = None
        self._speculative_type = None
        self._spec_fallback_reason = None
        # A drafter trained with the fine-tune and exported beside this GGUF (drafter.json).
        trained_steps = None
        if eagle3_draft_path is None or mtp_trained is None:
            sidecar_eagle3, sidecar_trained, trained_steps = _trained_drafter_sidecar(model_path)
            eagle3_draft_path = eagle3_draft_path or sidecar_eagle3
            mtp_trained = sidecar_trained if mtp_trained is None else mtp_trained

        # Canonical UI-facing requested mode (legacy values mapped via
        # _canonicalize_spec_mode).
        canonical_mode = _canonicalize_spec_mode(speculative_type)
        user_owns_spec_type = _extra_args_set_spec_type(extra_args)
        if (
            not user_owns_spec_type
            and canonical_mode in ("auto", "mtp", "mtp+ngram")
            and self._nextn_predict_layers
            and mtp_draft_path
        ):
            # Backstop for callers that bypass load_model's discovery normalization.
            mtp_draft_path = None
        # A dropped sidecar is this quant's only MTP signal; keep it so it reaches the fallback.
        is_mtp_model = (
            bool(self._nextn_predict_layers)
            or _is_mtp_model_name(model_identifier, model_path)
            or bool(mtp_draft_path)
            # Drafter kind is set before fallbacks erase it; under Auto, no later field keeps it.
            or mtp_drafter_unloadable
        )
        _mtp_size_b = _extract_model_size_b(model_identifier)
        # The sub-3B regression is an embedded-head cost; a separate drafter
        # (Gemma) is a cheap standalone model that wins below 3B, so exempt it.
        # A head the user trained with this fine-tune is what they asked to draft with, so the
        # size floor (a stock-head cost measurement) and the MLA default-off below do not apply.
        _mtp_too_small = (
            _mtp_size_b is not None
            and _mtp_size_b < _MTP_MIN_SIZE_B
            and not bool(mtp_draft_path)
            and not mtp_trained
        )
        # Drafterless MTP (a sidecar dropped as unopenable included) would abort llama-server, so fall back; without that case MTP is silently disabled.
        _mtp_drafter_missing = (
            not mtp_draft_path
            and not self._nextn_predict_layers
            and (_is_gemma_mtp_name(model_identifier, model_path) or mtp_drafter_unloadable)
        )
        # MLA embedded MTP is ~2x slower than no spec, so Auto drops it; override with forced mtp or UNSLOTH_MLA_MTP_ENABLED=1. Separate drafters are unaffected.
        _auto_mla_embedded_mtp = (
            bool(self._nextn_predict_layers)
            and self._kv_lora_rank is not None
            and not bool(mtp_draft_path)
            and not _mla_mtp_auto_enabled()
            and not _arch_has_fast_mla_mtp(getattr(self, "_architecture", None))
            and not mtp_trained
        )

        if user_owns_spec_type:
            # User --spec-type wins; skip auto-emit to avoid a duplicate spec block.
            self._requested_spec_mode = None
            return flags

        effective_mode = canonical_mode or "auto"
        self._requested_spec_mode = effective_mode
        if effective_mode == "off":
            return flags
        if effective_mode == "ngram-simple":
            flags.extend(["--spec-type", "ngram-simple"])
            self._speculative_type = "ngram-simple"
            return flags
        caps = self.probe_server_capabilities(binary)

        # Which drafter every branch below is about. Set once here, before any
        # fallback can erase the evidence: the UI names the recovery from this,
        # and under Auto neither the requested mode nor the resolved
        # _speculative_type ("default" after a fallback) still carries the kind.
        _auto_mode = (canonical_mode or "auto") == "auto"
        if canonical_mode == "eagle3" or (
            _auto_mode and eagle3_draft_path and caps.get("supports_eagle3")
        ):
            self._spec_drafter_kind = "eagle3"
            if not caps.get("supports_eagle3"):
                logger.warning(
                    "EAGLE-3 requested but llama-server lacks --spec-type draft-eagle3; "
                    "loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "binary_no_mtp"
                return flags
            if not eagle3_draft_path:
                logger.warning(
                    "EAGLE-3 requested but no trained eagle3-*.gguf drafter sits next to this "
                    "model; loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "drafter_not_found"
                return flags
            draft_n_max = (
                int(spec_draft_n_max) if spec_draft_n_max is not None else (trained_steps or 3)
            )
            if spec_draft_n_max is not None:
                self._spec_draft_n_max = draft_n_max
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            flags.extend(
                [
                    "--model-draft",
                    eagle3_draft_path,
                    "--spec-type",
                    "draft-eagle3",
                    str(n_max_flag),
                    str(draft_n_max),
                ]
            )
            if draft_device:
                flags.extend(["--spec-draft-device", draft_device])
            self._speculative_type = "draft-eagle3"
            logger.info("Spec decoding: draft-eagle3 using %s", eagle3_draft_path)
            return flags
        if canonical_mode == "dspark" or (
            _auto_mode and dspark_draft_path and caps.get("supports_dspark")
        ):
            self._spec_drafter_kind = "dspark"
        elif canonical_mode == "dflash" or (
            _auto_mode and dflash_draft_path and caps.get("supports_dflash")
        ):
            self._spec_drafter_kind = "dflash"
        else:
            self._spec_drafter_kind = "mtp"

        def _resolved_draft_n_max() -> int:
            # Like DSpark, the sidecar borrows target token_embd/output, so llama.cpp cannot size its ~1.5 GB.
            if spec_draft_n_max is not None:
                n = int(spec_draft_n_max)
                self._spec_draft_n_max = n
                return n
            if mtp_trained and trained_steps and self._spec_drafter_kind == "mtp":
                return trained_steps  # the depth the exported head was trained for
            return 2 if gpus else 3

        def _emit_dspark() -> None:
            """Appends --model-draft <sidecar> with draft-dspark; callers check the sidecar and
            capability first."""
            if not dspark_fit_sized:
                # Not a blocker: the sidecar borrows the target's embeddings, so fit cannot reserve for it; the load still works, with ~11 GB missing from the fit budget.
                logger.info(
                    "DSpark under --fit on: llama.cpp cannot size the sidecar during "
                    "fitting, so its ~%.1f GB is not reserved. Pin GPU Layers in "
                    "Manual mode if the load runs out of VRAM.",
                    (self._get_gguf_size_bytes(dspark_draft_path) or 0) / 1e9,
                )
            draft_n_max = int(spec_draft_n_max) if spec_draft_n_max is not None else 3
            if spec_draft_n_max is not None:
                self._spec_draft_n_max = draft_n_max
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            flags.extend(
                [
                    "--model-draft",
                    dspark_draft_path,
                    "--spec-type",
                    "draft-dspark",
                    str(n_max_flag),
                    str(draft_n_max),
                ]
            )
            self._speculative_type = "draft-dspark"
            logger.info("Spec decoding: draft-dspark using %s", dspark_draft_path)

        if effective_mode == "dspark":
            # Check capability first: a missing sidecar is usually the binary's fault.
            if not caps.get("supports_dspark"):
                logger.warning(
                    "DSpark requested but llama-server lacks --spec-type "
                    "draft-dspark; loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "binary_no_mtp"
                return flags
            if not dspark_draft_path:
                logger.warning(
                    "DSpark requested but no matching dspark-*.gguf sidecar was found; "
                    "loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "drafter_not_found"
                return flags
            _emit_dspark()
            return flags

        def _emit_dflash() -> None:
            """Appends --model-draft <sidecar> with draft-dflash; Auto picks it whenever the model
            ships one."""
            if not dflash_fit_sized:
                # Same shape as DSpark: the sidecar ships no token_embd/output and
                # borrows the target's, so llama.cpp cannot build a standalone
                # draft context to measure it (llama-context.cpp:153-160) and
                # skips the reserve (server-context.cpp:1190-1193). The load still
                # works; only the ~1.5 GB is missing from the fit budget, which is
                # an order of magnitude less than the DSpark case.
                logger.info(
                    "DFlash under --fit on: llama.cpp cannot size the sidecar during "
                    "fitting, so its ~%.1f GB is not reserved. Pin GPU Layers in "
                    "Manual mode if the load runs out of VRAM.",
                    (self._get_gguf_size_bytes(dflash_draft_path) or 0) / 1e9,
                )
            draft_n_max = _resolved_draft_n_max()
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            flags.extend(
                [
                    "--model-draft",
                    dflash_draft_path,
                    "--spec-type",
                    "draft-dflash",
                    str(n_max_flag),
                    str(draft_n_max),
                ]
            )
            if draft_device:
                # Check capability first, as DSpark does: a missing sidecar is usually the binary's fault.
                flags.extend(["--spec-draft-device", draft_device])
            self._speculative_type = "draft-dflash"
            logger.info("Spec decoding: draft-dflash using %s", dflash_draft_path)

        if effective_mode == "dflash":
            # Separate-file drafter (Gemma) gets --model-draft path; baked-in heads (Qwen) pass none.
            if not caps.get("supports_dflash"):
                logger.warning(
                    "DFlash requested but llama-server lacks --spec-type "
                    "draft-dflash; loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "binary_no_mtp"
                return flags
            if not dflash_draft_path:
                logger.warning(
                    "DFlash requested but no matching dflash-*.gguf sidecar was found; "
                    "loading without speculative decoding."
                )
                flags.append("--spec-default")
                self._speculative_type = "default"
                self._spec_fallback_reason = "drafter_not_found"
                return flags
            _emit_dflash()
            return flags

        def _emit_mtp(*, chain_ngram: bool) -> bool:
            """Append --spec-type mtp[/draft-mtp][,ngram-mod] + n-max."""
            mtp_token = caps.get("mtp_token") if caps else None
            if not mtp_token:
                inconclusive = bool(caps.get("mtp_probe_inconclusive")) if caps else True
                if inconclusive:
                    logger.info(
                        "Requested MTP speculative decoding but llama-server MTP "
                        "capability probe was inconclusive; loading without "
                        "speculative decoding."
                    )
                else:
                    logger.warning(
                        "Requested MTP speculative decoding but "
                        "llama-server lacks --spec-type mtp/draft-mtp; "
                        "run `unsloth studio update`. Loading without "
                        "speculative decoding."
                    )
                # Override inherited LLAMA_ARG_SPEC_TYPE=draft-mtp (CLI wins over env) so the child matches the capability gate and the no-MTP budget.
                flags.append("--spec-default")
                self._speculative_type = "default"
                if inconclusive:
                    self._spec_fallback_reason = None
                else:
                    self._spec_fallback_reason = "binary_no_mtp"
                return False
            draft_n_max = _resolved_draft_n_max()
            n_max_flag = caps.get("spec_draft_n_max_flag") or "--spec-draft-n-max"
            # Record the stand-down so it takes; reason binary_outdated, since ngram-mod has no drafter kind.
            if mtp_draft_path:
                flags.extend(["--model-draft", mtp_draft_path])
                if draft_device:
                    flags.extend(["--spec-draft-device", draft_device])
                logger.info(f"Using separate MTP drafter: {mtp_draft_path}")
            spec_value = mtp_token
            ngram_knobs: list[str] = []
            if chain_ngram:
                ngram_knobs = _build_ngram_mod_flags(caps, chain_with_mtp = True)
                if ngram_knobs:
                    spec_value = f"ngram-mod,{mtp_token}"
                else:
                    logger.warning(
                        "llama-server lacks ngram-mod tuning "
                        "flags; loading MTP only (no ngram chain)"
                    )
            flags.extend(["--spec-type", spec_value, n_max_flag, str(draft_n_max)])
            flags.extend(ngram_knobs)
            self._speculative_type = "draft-mtp"
            chain_label = "chained ngram-mod" if chain_ngram else "MTP-only"
            logger.info(f"Spec decoding: {mtp_token} ({chain_label})")
            return True

        def _emit_ngram_mod() -> bool:
            """Append --spec-type ngram-mod + flag-set knobs."""
            if not caps.get("supports_ngram_mod"):
                logger.warning(
                    "Requested ngram-mod speculative decoding but llama-server "
                    "does not advertise ngram-mod support; run `unsloth studio "
                    "update`. Loading without speculative decoding."
                )
                # The stand-down the warning tells the user to fix, recorded so the
                # update actually takes: an unrecorded one leaves the picker adopting
                # this process forever. "binary_outdated" rather than "binary_no_mtp"
                # because the retry rule for that one asks _SPEC_KIND_CAPABILITY about
                # _spec_drafter_kind, which ngram-mod never sets, having no drafter.
                self._spec_fallback_reason = "binary_outdated"
                return False
            ngram_knobs = _build_ngram_mod_flags(caps)
            flags.extend(["--spec-type", "ngram-mod"])
            if not ngram_knobs:
                logger.warning(
                    "llama-server lacks ngram-mod tuning "
                    "flags; loading without --spec-ngram-mod-* knobs"
                )
            flags.extend(ngram_knobs)
            self._speculative_type = "ngram-mod"
            logger.info("Spec decoding: ngram-mod")
            return True

        def _fallback_drafter_not_found() -> None:
            """Drafterless Gemma: use ngram-mod (or spec-default) and record why."""
            if mtp_drafter_unloadable:
                logger.warning(
                    "Model %s had an MTP drafter that llama-server cannot open as "
                    "--model-draft; falling back without it.",
                    model_identifier,
                )
            else:
                logger.warning(
                    "Model %s is MTP-capable but no drafter or head was found; "
                    "falling back. Check network or run `unsloth studio update`.",
                    model_identifier,
                )
            if caps.get("supports_ngram_mod"):
                _emit_ngram_mod()
            else:
                flags.append("--spec-default")
                self._speculative_type = "default"
            # Auto stands down embedded Hybrid Mamba MTP on partial offload: rollback pushes layers to CPU.
            self._spec_fallback_reason = (
                "drafter_unloadable" if mtp_drafter_unloadable else "drafter_not_found"
            )

        if effective_mode == "ngram":
            _emit_ngram_mod()
            return flags
        if effective_mode in ("mtp", "mtp+ngram"):
            chain_ngram = effective_mode == "mtp+ngram"
            if not is_mtp_model:
                if chain_ngram:
                    logger.warning(
                        "MTP+Ngram requested but this GGUF has no MTP head or "
                        "drafter; loading ngram-mod only."
                    )
                    _emit_ngram_mod()
                else:
                    logger.warning(
                        "MTP requested but this GGUF has no MTP head or drafter; "
                        "loading without speculative decoding."
                    )
                    flags.append("--spec-default")
                    self._speculative_type = "default"
                return flags
            if _mtp_drafter_missing:
                _fallback_drafter_not_found()
                return flags
            if _mtp_too_small:
                logger.warning(
                    f"Forcing {effective_mode.upper()} on a {_mtp_size_b:.1f}B model; "
                    "the bench shows MTP regresses below 3B. "
                    "Engaging anyway (user override)."
                )
            _emit_mtp(chain_ngram = chain_ngram)
            return flags

        # No vision gate (DFlash measured with mmproj); MLA with no sidecar gets its own reason, not VRAM.
        if embedded_mtp_partial_offload and caps.get("mtp_token"):
            logger.info(
                "Auto: embedded MTP is disabled because the Hybrid Mamba target "
                "requires partial CPU offload; ordinary decoding is faster at this "
                "placement. Choose MTP explicitly to force it."
            )
            flags.extend(["--spec-type", "none"])
            self._speculative_type = "none"
            self._spec_fallback_reason = "mtp_partial_offload"
            # Depth changes the rollback copies priced into the fit, so it must trigger a reload.
            if spec_draft_n_max is not None:
                self._spec_draft_n_max = int(spec_draft_n_max)
            return flags

        # DSpark first: it beats other Auto outcomes for this architecture; without it, --spec-default.
        _no_vram_drops_a_real_drafter = (
            bool(dspark_draft_path and caps.get("supports_dspark"))
            or bool(dflash_draft_path and caps.get("supports_dflash"))
            or not _auto_mla_embedded_mtp
        )
        if drafter_no_vram and _no_vram_drops_a_real_drafter:
            # The fit reserved nothing for the drafter, so emitting one would OOM.
            self._spec_fallback_reason = "drafter_no_vram"
            if caps.get("supports_ngram_mod"):
                logger.info(
                    "Auto: the drafter does not fit in VRAM alongside the model at this "
                    "context, so it is dropped and ngram-mod (zero-VRAM) takes its "
                    "place. Choose the drafter in the Speculative Decoding dropdown to "
                    "force it at a smaller context."
                )
                _emit_ngram_mod()
            else:
                # ngram-mod is not in this build's enum and llama-server aborts on unknown values.
                logger.info(
                    "Auto: the drafter does not fit in VRAM alongside the model at this "
                    "context, so speculative decoding is disabled (this llama-server "
                    "does not advertise ngram-mod). Choose the drafter in the "
                    "Speculative Decoding dropdown to force it at a smaller context."
                )
        elif dspark_draft_path and caps.get("supports_dspark"):
            # DFlash needs no opt-in unlike DSpark: its sidecar ships in the model repo; DSpark is tried first.
            _emit_dspark()
        elif dflash_draft_path and caps.get("supports_dflash"):
            # MLA embedded MTP regresses, so Auto uses ngram-mod; UNSLOTH_MLA_MTP_ENABLED=1 re-enables it.
            _emit_dflash()
        elif _auto_mla_embedded_mtp:
            # MLA embedded-MTP (GLM-5.2 et al.): the MTP path regresses vs spec-off
            # on llama.cpp today, so Auto drops it and falls back to ngram-mod (or
            # spec-off if unsupported), mirroring the sub-3B branch. Forced mtp /
            # mtp+ngram (handled above) still engage; UNSLOTH_MLA_MTP_ENABLED=1
            # re-enables this promotion once upstream optimizes the path.
            self._spec_fallback_reason = "mla_mtp_disabled"
            if caps.get("supports_ngram_mod"):
                logger.info(
                    "Auto: MLA embedded-MTP model detected; llama.cpp's MLA/DSA "
                    "MTP path is slower than no speculation, so using ngram-mod "
                    "instead. Override via the Unsloth Speculative Decoding "
                    "dropdown or UNSLOTH_MLA_MTP_ENABLED=1."
                )
                _emit_ngram_mod()
            else:
                logger.info(
                    "Auto: MLA embedded-MTP model detected; disabling speculative "
                    "decoding (this llama-server does not advertise ngram-mod). "
                    "Override via the dropdown or UNSLOTH_MLA_MTP_ENABLED=1."
                )
                # spec-off: emit nothing, mirroring the sub-3B no-ngram path.
        elif is_mtp_model and not _mtp_too_small:
            if _mtp_drafter_missing:
                # Name-only MTP, drafter did not resolve (download failed/absent).
                _fallback_drafter_not_found()
            else:
                # GPU: MTP-only. CPU/Mac: chain ngram-mod + MTP.
                _emit_mtp(chain_ngram = not gpus)
        elif is_mtp_model and _mtp_too_small:
            # Sub-3B fallback: drop the MTP draft head, keep ngram-mod when
            # the binary supports it.
            if _mtp_drafter_missing:
                _fallback_drafter_not_found()
            elif caps.get("supports_ngram_mod"):
                logger.info(
                    f"MTP GGUF detected but model size {_mtp_size_b:.1f}B "
                    "is below the 3B speedup threshold; using ngram-mod "
                    "only (zero-VRAM, no draft head). Override via "
                    "--spec-type or the Unsloth Speculative Decoding "
                    "dropdown."
                )
                _emit_ngram_mod()
            else:
                logger.info(
                    f"MTP GGUF detected but model size {_mtp_size_b:.1f}B "
                    "is below the 3B speedup threshold and the bundled "
                    "llama-server does not advertise ngram-mod; "
                    "auto-disabling speculative decoding."
                )
        else:
            # Non-MTP model: let llama-server choose its default strategy.
            flags.append("--spec-default")
            self._speculative_type = "default"
        return flags

    def adopt_load_intent_if_matched(self, intent: GgufLoadIntent) -> bool:
        """Match live state and adopt the caller's compatible GPU placement."""
        if not self.matches_load_source(intent):
            return False
        # A custom-path save leaves the model intent unchanged, but the
        # resident process still belongs to the previously selected runtime.
        if self._binary_changed_since_launch():
            logger.info("llama-server selection changed since launch; forcing a reload")
            return False
        intent = self._preserve_cpu_fallback_intent(intent, source_matches = True)
        # Budget is server-wide, so a save with same intent must reload; None if placement never used it.
        if _metal_device_is_paravirtual():
            (
                _pv_mode,
                _pv_layers,
                _pv_tp,
                _pv_split,
                _pv_cpu_moe,
                _pv_extras,
            ) = paravirtual_normalized_request(
                gpu_memory_mode = intent.gpu_memory_mode,
                gpu_layers = intent.gpu_layers,
                tensor_parallel = intent.tensor_parallel,
                tensor_split = list(intent.tensor_split) if intent.tensor_split else None,
                n_cpu_moe = intent.n_cpu_moe,
                extra_args = list(intent.extra_args) if intent.extra_args is not None else None,
                log_dropped = False,
            )
            intent = replace(
                intent,
                gpu_memory_mode = _pv_mode,
                gpu_layers = _pv_layers,
                tensor_parallel = _pv_tp,
                tensor_split = tuple(_pv_split) if _pv_split else None,
                n_cpu_moe = _pv_cpu_moe,
                extra_args = tuple(_pv_extras) if _pv_extras is not None else None,
            )
        effective_extra_args = (
            list(intent.extra_args) if intent.extra_args is not None else self._extra_args
        )
        candidate_extra_args = list(effective_extra_args) if effective_extra_args else []
        if intent.extra_args is not None and self._gpu_ids_own_placement(intent.gpu_ids):
            candidate_extra_args = self._strip_device_extra_args(candidate_extra_args)
        # Model Memory toggles change only launch flags, so compare them explicitly.
        if not memory_state_satisfies_settings(
            self._memory_state,
            self._memory_policy_active,
            self._memory_mlock_applicable,
            self._memory_direct_io,
            self._memory_dio_applicable,
            bool(self._memory_dio_flags),
        ):
            logger.info("Model Memory policy changed since launch; forcing a reload")
            return False
        # Use the pending marker: an in-flight load's budget was captured under the lock, not re-read.
        _launched_frac = self._vram_fraction_launched
        # The pending marker, not a fresh read: a load in flight captured its budget
        # under the lock, and re-reading could decide against a different number than
        # the plan that follows. The route's fast path finds it unset and resolves
        # live as before. Reading the marker rather than taking a parameter keeps the
        # signature every caller and test double already has.
        _pending_frac = self._vram_fraction_pending
        _active_frac = _pending_frac if _pending_frac is not None else _active_vram_fraction()
        if _launched_frac is not None and float(_launched_frac) != _active_frac:
            logger.info("VRAM budget changed since launch; forcing a reload")
            return False
        if self._hand_added_projector_since_launch(candidate_extra_args):
            logger.info("A projector was added beside the cached weight; forcing a reload")
            return False
        if not self._runtime_matches_intent(intent, candidate_extra_args):
            return False
        self._record_matching_gpu_request(
            list(intent.gpu_ids) if intent.gpu_ids is not None else None
        )
        return True

    def _hand_added_projector_since_launch(self, extra_args: list) -> bool:
        """A text-only -hf launch whose repo publishes no projector, with one now
        dropped beside the cached weight (#9286). Without this the next Apply dedupes
        onto the projector-less server until Studio restarts."""
        last = getattr(self, "_last_load_intent", None)
        if (
            self._is_vision
            or self._disable_vision
            or not self._hf_repo
            or not self._gguf_path
            or last is None
            or last.is_vision
            or extra_args_disable_mmproj(extra_args)
        ):
            return False
        try:
            from utils.models.model_config import _hf_cached_local_mmproj
            return _hf_cached_local_mmproj(self._gguf_path) is not None
        except Exception as exc:
            logger.debug("Hand-added mmproj probe failed: %s", exc)
            return False

    def matches_load_source(self, intent: GgufLoadIntent) -> bool:
        """Whether the resident model has the intent's identity and weights."""
        # A retired child stays recorded until respawned: an identical load must replace it.
        _retired = getattr(self, "_retired_process", None)
        if _retired is not None and getattr(self, "_process", None) is _retired:
            return False
        if not self.is_loaded or (self._model_identifier or "").lower() != (
            intent.model_identifier.lower()
        ):
            return False
        custom_mmproj = _extra_args_device(intent.extra_args, {"--mmproj", "-mm"})
        source_path = intent.gguf_path
        if source_path is None and custom_mmproj is not None:
            if (self._hf_variant or "").lower() != (intent.hf_variant or "").lower():
                return False
            source_path = self._gguf_path
        if source_path is not None and self._gguf_path:
            resident_identity = getattr(self, "_gguf_load_identity", None)
            if resident_identity is not None:
                candidate_identity = LlamaCppBackend._gguf_load_source_identity(
                    source_path,
                    custom_mmproj or intent.mmproj_path,
                )
                return candidate_identity == resident_identity
            try:
                return Path(self._gguf_path).resolve() == Path(source_path).resolve()
            except OSError:
                return False
        return (self._hf_variant or "").lower() == (intent.hf_variant or "").lower()

    def components_match_intent(self, intent: GgufLoadIntent) -> bool:
        """``_runtime_matches_intent`` minus capacity and placement: same weights and components."""
        if intent.force_reload or not self.matches_load_source(intent):
            return False
        requested = self.requested_extra_args
        # Inherited extras would carry the resident's adapters and drafters unnamed by the caller.
        if intent.extra_args_inherited and requested:
            return False
        extras = requested if intent.extra_args_inherited else intent.extra_args
        if tuple(extras or ()) != tuple(requested or ()):
            return False
        if (self._chat_template_override or None) != (intent.chat_template_override or None):
            return False
        if not self._is_diffusion and (
            bool(self._disable_vision) != bool(intent.disable_vision)
            or self._requested_reasoning_budget
            != resolve_reasoning_budget(extras, intent.reasoning_budget)
            or self._requested_reasoning_budget_message
            != resolve_reasoning_budget_message(extras, intent.reasoning_budget_message)
        ):
            return False
        if _extra_args_set_spec_type(extras):
            return self._requested_spec_mode is None
        return (_canonicalize_spec_mode(intent.speculative_type) or "auto") == (
            self._requested_spec_mode or "auto"
        )

    def _classify_gpu_offload(
        self, expected_gpu: bool, detected_gpus: list[tuple[int, int]]
    ) -> Optional[bool]:
        """True if on GPU, False if only CPU buffers despite GPU intent, None with no signal; delegates to the shared classifier that tracks current llama.cpp logs."""
        if not detected_gpus or not expected_gpu:
            return None
        return classify_gpu_offload_lines(self._stdout_lines)

    @staticmethod
    def _cmd_has_gpu_companion(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """A --mmproj or GPU drafter offloads regardless of --gpu-layers; CPU-forced drafters do not
        count."""
        _args = [str(a) for a in cmd]
        if any(a.startswith("--mmproj") or _flag_name(a) == "-mm" for a in _args):
            # --no-mmproj-offload disables clip.cpp's GPU backend, so the projector holds no VRAM.
            _off = [a for a in _args if a in ("--mmproj-offload", "--no-mmproj-offload")]
            if not _off or _off[-1] != "--no-mmproj-offload":
                return True
        if _extra_args_mtp_draft_path(cmd, env) is None:
            return False
        return not _extra_args_draft_offloaded_to_cpu(cmd, env)

    @staticmethod
    def _zero_offload_keeps_gpu_visible(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """Shared with child masking: a device pin, tensor mode, mmproj or GPU drafter keeps GPUs
        visible."""
        return (
            LlamaCppBackend._cmd_has_gpu_device_pin(cmd, env)
            or _effective_tensor_parallel(cmd, False, env)
            or LlamaCppBackend._cmd_has_gpu_companion(cmd, env)
        )

    @staticmethod
    def _cmd_has_gpu_device_pin(cmd: list, env: Optional[Mapping[str, str]] = None) -> bool:
        """True when the effective main or draft ``--device`` pin names a GPU."""
        main_flags = {"--device", "-dev"}
        draft_flags = {"--spec-draft-device", "-devd", "--device-draft"}
        last_main: Optional[str] = None
        last_draft: Optional[str] = None
        args = [str(arg) for arg in cmd]
        for index, raw in enumerate(args):
            flag = _flag_name(raw)
            _, equals, inline = raw.partition("=")
            if flag not in main_flags and flag not in draft_flags:
                continue
            value = inline if equals else (args[index + 1] if index + 1 < len(args) else "")
            if flag in main_flags:
                last_main = value
            else:
                last_draft = value
        if last_main is None:
            last_main = (env or {}).get("LLAMA_ARG_DEVICE")

        def _names_gpu(value: Optional[str]) -> bool:
            if value is None:
                return False
            devices = [item.strip().lower() for item in value.split(",") if item.strip()]
            return not devices or any(item not in ("cpu", "none") for item in devices)

        return _names_gpu(last_main) or _names_gpu(last_draft)

    @staticmethod
    def _zero_offload_gpu_flag(
        spawn_cmd: list,
        detected_gpus: list,
        env: Optional[Mapping[str, str]] = None,
    ) -> Optional[bool]:
        """Residency flag for a manual zero-offload load: counted classifiers miss pins, mmproj and drafter VRAM, so reuse the launch predicate; None means no signal."""
        if LlamaCppBackend._is_vulkan_backend():
            # Unlike -ngl 0, the recovery's last-wins --device none removes Vulkan.
            main_device = (_extra_args_main_device(spawn_cmd) or "").strip().lower()
            if main_device in ("cpu", "none"):
                return LlamaCppBackend._zero_offload_keeps_gpu_visible(spawn_cmd, env)
            if detected_gpus:
                return True
        if not detected_gpus:
            return None
        return LlamaCppBackend._zero_offload_keeps_gpu_visible(spawn_cmd, env)

    def load_cancelled(self) -> bool:
        """True if a load was cancelled (e.g. via unload/_cancel_event) and not
        yet consumed by the next load_model. Lets the tensor->layer fallback
        avoid restarting a load the user just cancelled."""
        return self._cancel_event.is_set()

    @_invalidates_gpu_memory("llama.cpp unload")
    def unload_model(self) -> bool:
        """Terminate the subprocess and cancel any in-flight download."""
        self._cancel_event.set()
        with self._lock:
            self._unload_epoch += 1
            # Read before the kill clears it: callers unload from a finally either way.
            _was_resident = self._process is not None
            self._kill_process()
            self._cleanup_cpu_fallback_runtime()
            if self._api_key_file is not None:
                with contextlib.suppress(OSError):
                    os.unlink(self._api_key_file)
                self._api_key_file = None
            # The one unload line: routes/inference.py logged a second, differently named.
            if _was_resident:
                logger.info(f"Unloaded GGUF model: {self._model_identifier}")
            self._model_identifier = None
            self._gguf_path = None
            self._gguf_load_identity = None
            self._hf_repo = None
            self._mtp_draft_path = None
            self._mtp_draft_suppressed_path = None
